CREATE OR REPLACE FUNCTION public._be_count_table(table_name text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  result_count integer := 0;
begin
  if to_regclass('public.' || table_name) is null then
    return 0;
  end if;

  execute format('select count(*) from public.%I', table_name)
  into result_count;

  return coalesce(result_count, 0);
end;
$function$
;

create type "public"."_time_trial_type" as ("a_time" numeric);

CREATE OR REPLACE FUNCTION public.admin_auth_email_duplicates()
 RETURNS TABLE(email text, cnt integer, user_ids uuid[])
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.is_admin_role() then
    raise exception 'Admin only';
  end if;

  return query
  select lower(u.email) as email, count(*)::int as cnt, array_agg(u.id)::uuid[] as user_ids
  from auth.users u
  where u.email is not null and trim(u.email) <> ''
  group by lower(u.email)
  having count(*) > 1;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.api_report_audit_logs(p_page integer DEFAULT 1, p_page_size integer DEFAULT 20, p_sort_by text DEFAULT 'event_time'::text, p_sort_order text DEFAULT 'desc'::text, p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date, p_user text DEFAULT NULL::text, p_module text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
  v_offset integer := greatest((p_page - 1) * p_page_size, 0);
  v_total integer;
  v_items jsonb;
begin
  select count(*)
    into v_total
  from rpt_audit_logs r
  where (p_date_from is null or r.event_time::date >= p_date_from)
    and (p_date_to is null or r.event_time::date <= p_date_to)
    and (p_user is null or r.user_email ilike '%' || p_user || '%')
    and (p_module is null or r.module ilike '%' || p_module || '%');

  select jsonb_agg(to_jsonb(x))
    into v_items
  from (
    select *
    from rpt_audit_logs r
    where (p_date_from is null or r.event_time::date >= p_date_from)
      and (p_date_to is null or r.event_time::date <= p_date_to)
      and (p_user is null or r.user_email ilike '%' || p_user || '%')
      and (p_module is null or r.module ilike '%' || p_module || '%')
    order by
      case when p_sort_by = 'event_time' and p_sort_order = 'asc' then r.event_time end asc,
      case when p_sort_by = 'event_time' and p_sort_order = 'desc' then r.event_time end desc
    offset v_offset
    limit p_page_size
  ) x;

  return jsonb_build_object(
    'items', coalesce(v_items, '[]'::jsonb),
    'total', coalesce(v_total, 0),
    'page', p_page,
    'pageSize', p_page_size,
    'summary', '{}'::jsonb
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.api_report_branches(p_page integer DEFAULT 1, p_page_size integer DEFAULT 20, p_sort_by text DEFAULT 'branch_name'::text, p_sort_order text DEFAULT 'asc'::text, p_search text DEFAULT NULL::text, p_is_active boolean DEFAULT NULL::boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
  v_offset integer := greatest((p_page - 1) * p_page_size, 0);
  v_total integer;
  v_items jsonb;
  v_summary jsonb;
begin
  select count(*)
    into v_total
  from rpt_branches r
  where (
      p_search is null
      or r.branch_name ilike '%' || p_search || '%'
      or r.branch_code ilike '%' || p_search || '%'
      or r.environment ilike '%' || p_search || '%'
    )
    and (p_is_active is null or r.is_active = p_is_active);

  select jsonb_agg(to_jsonb(x))
    into v_items
  from (
    select *
    from rpt_branches r
    where (
        p_search is null
        or r.branch_name ilike '%' || p_search || '%'
        or r.branch_code ilike '%' || p_search || '%'
        or r.environment ilike '%' || p_search || '%'
      )
      and (p_is_active is null or r.is_active = p_is_active)
    order by
      case when p_sort_by = 'branch_name' and p_sort_order = 'asc' then r.branch_name end asc,
      case when p_sort_by = 'branch_name' and p_sort_order = 'desc' then r.branch_name end desc,
      case when p_sort_by = 'branch_code' and p_sort_order = 'asc' then r.branch_code end asc,
      case when p_sort_by = 'branch_code' and p_sort_order = 'desc' then r.branch_code end desc,
      case when p_sort_by = 'created_at' and p_sort_order = 'asc' then r.created_at end asc,
      case when p_sort_by = 'created_at' and p_sort_order = 'desc' then r.created_at end desc
    offset v_offset
    limit p_page_size
  ) x;

  select jsonb_build_object(
    'branchCount', count(*),
    'activeBranches', count(*) filter (where is_active = true),
    'inactiveBranches', count(*) filter (where is_active = false)
  )
    into v_summary
  from rpt_branches r
  where (
      p_search is null
      or r.branch_name ilike '%' || p_search || '%'
      or r.branch_code ilike '%' || p_search || '%'
      or r.environment ilike '%' || p_search || '%'
    )
    and (p_is_active is null or r.is_active = p_is_active);

  return jsonb_build_object(
    'items', coalesce(v_items, '[]'::jsonb),
    'total', coalesce(v_total, 0),
    'page', p_page,
    'pageSize', p_page_size,
    'summary', coalesce(v_summary, '{}'::jsonb)
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.api_report_merchants(p_page integer DEFAULT 1, p_page_size integer DEFAULT 20, p_sort_by text DEFAULT 'merchant_name'::text, p_sort_order text DEFAULT 'asc'::text, p_search text DEFAULT NULL::text, p_status text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
  v_offset integer := greatest((p_page - 1) * p_page_size, 0);
  v_total integer;
  v_items jsonb;
  v_summary jsonb;
begin
  select count(*)
    into v_total
  from rpt_merchants r
  where (
      p_search is null
      or r.merchant_name ilike '%' || p_search || '%'
      or r.merchant_code ilike '%' || p_search || '%'
      or r.contact_person ilike '%' || p_search || '%'
      or r.email ilike '%' || p_search || '%'
    )
    and (p_status is null or upper(coalesce(r.status, '')) = upper(p_status));

  select jsonb_agg(to_jsonb(x))
    into v_items
  from (
    select *
    from rpt_merchants r
    where (
        p_search is null
        or r.merchant_name ilike '%' || p_search || '%'
        or r.merchant_code ilike '%' || p_search || '%'
        or r.contact_person ilike '%' || p_search || '%'
        or r.email ilike '%' || p_search || '%'
      )
      and (p_status is null or upper(coalesce(r.status, '')) = upper(p_status))
    order by
      case when p_sort_by = 'merchant_name' and p_sort_order = 'asc' then r.merchant_name end asc,
      case when p_sort_by = 'merchant_name' and p_sort_order = 'desc' then r.merchant_name end desc,
      case when p_sort_by = 'merchant_code' and p_sort_order = 'asc' then r.merchant_code end asc,
      case when p_sort_by = 'merchant_code' and p_sort_order = 'desc' then r.merchant_code end desc,
      case when p_sort_by = 'created_at' and p_sort_order = 'asc' then r.created_at end asc,
      case when p_sort_by = 'created_at' and p_sort_order = 'desc' then r.created_at end desc
    offset v_offset
    limit p_page_size
  ) x;

  select jsonb_build_object(
    'merchantCount', count(*),
    'activeMerchants', count(*) filter (where upper(coalesce(status, '')) = 'ACTIVE'),
    'inactiveMerchants', count(*) filter (where upper(coalesce(status, '')) <> 'ACTIVE')
  )
    into v_summary
  from rpt_merchants r
  where (
      p_search is null
      or r.merchant_name ilike '%' || p_search || '%'
      or r.merchant_code ilike '%' || p_search || '%'
      or r.contact_person ilike '%' || p_search || '%'
      or r.email ilike '%' || p_search || '%'
    )
    and (p_status is null or upper(coalesce(r.status, '')) = upper(p_status));

  return jsonb_build_object(
    'items', coalesce(v_items, '[]'::jsonb),
    'total', coalesce(v_total, 0),
    'page', p_page,
    'pageSize', p_page_size,
    'summary', coalesce(v_summary, '{}'::jsonb)
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.api_report_overdue_ways_count(p_page integer DEFAULT 1, p_page_size integer DEFAULT 20, p_sort_by text DEFAULT 'overdue_count'::text, p_sort_order text DEFAULT 'desc'::text, p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date, p_branch_id uuid DEFAULT NULL::uuid, p_township text DEFAULT NULL::text, p_merchant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
  v_offset integer := greatest((p_page - 1) * p_page_size, 0);
  v_total integer;
