CREATE OR REPLACE FUNCTION public.audit_dml_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row_id text;
begin
  v_row_id := coalesce(
    (case when tg_op in ('INSERT','UPDATE') then (to_jsonb(NEW)->>'id') end),
    (case when tg_op = 'DELETE' then (to_jsonb(OLD)->>'id') end),
    (case when tg_op in ('INSERT','UPDATE') then (to_jsonb(NEW)->>'way_id') end),
    (case when tg_op = 'DELETE' then (to_jsonb(OLD)->>'way_id') end)
  );

  insert into public.audit_dml_logs(actor_uid, actor_role, action, table_name, row_id, old_record, new_record)
  values (
    auth.uid(),
    public.app_role(),
    tg_op,
    tg_table_name,
    v_row_id,
    case when tg_op in ('UPDATE','DELETE') then to_jsonb(OLD) else null end,
    case when tg_op in ('INSERT','UPDATE') then to_jsonb(NEW) else null end
  );

  if tg_op = 'DELETE' then return OLD; end if;
  return NEW;
end
$function$
;

CREATE OR REPLACE FUNCTION public.audit_log_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor_uid uuid;
  v_actor_role text;
  v_row jsonb;
  v_old jsonb;
  v_new jsonb;
  v_row_id text;
begin
  v_actor_uid := auth.uid();

  begin
    v_actor_role := public.be_current_role();
  exception when others then
    v_actor_role := null;
  end;

  if TG_OP = 'DELETE' then
    v_row := to_jsonb(OLD);
    v_old := to_jsonb(OLD);
    v_new := null;
  elsif TG_OP = 'UPDATE' then
    v_row := to_jsonb(NEW);
    v_old := to_jsonb(OLD);
    v_new := to_jsonb(NEW);
  else
    v_row := to_jsonb(NEW);
    v_old := null;
    v_new := to_jsonb(NEW);
  end if;

  v_row_id := coalesce(
    v_row ->> 'id',
    v_row ->> 'tracking_no',
    v_row ->> 'pickup_code',
    v_row ->> 'merchant_code',
    v_row ->> 'code',
    v_row ->> 'name',
    md5(coalesce(v_row::text, random()::text))
  );

  insert into public.audit_logs (
    actor_uid,
    actor_role,
    action,
    table_name,
    row_id,
    old_record,
    new_record,
    entity_type,
    entity_id,
    status,
    metadata,
    old_values,
    new_values,
    "timestamp"
  )
  values (
    v_actor_uid,
    v_actor_role,
    TG_OP,
    TG_TABLE_NAME,
    v_row_id,
    v_old,
    v_new,
    TG_TABLE_NAME,
    v_row_id,
    'success',
    jsonb_build_object('source', 'audit_log_trigger', 'operation', TG_OP),
    v_old,
    v_new,
    now()
  );

  if TG_OP = 'DELETE' then
    return OLD;
  end if;
  return NEW;

exception when others then
  -- Audit logging must never block operational inserts/updates during production import.
  if TG_OP = 'DELETE' then
    return OLD;
  end if;
  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.authenticate_demo_user_2026_02_19_14_00(p_email text, p_password text)
 RETURNS TABLE(success boolean, user_id uuid, email text, role text, full_name text, message text)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_user_id UUID;
  v_email TEXT;
  v_role TEXT;
  v_full_name TEXT;
BEGIN
  -- Check if user exists and password matches
  SELECT
    dlc.id,
    dlc.email,
    dlc.role,
    dlc.full_name
  INTO v_user_id, v_email, v_role, v_full_name
  FROM demo_login_credentials_2026_02_19_14_00 dlc
  WHERE dlc.email = p_email
    AND dlc.password_hash = p_password
    AND dlc.is_active = true;

  -- If no match found
  IF NOT FOUND THEN
    RETURN QUERY SELECT false, NULL::UUID, NULL::TEXT, NULL::TEXT, NULL::TEXT, 'Invalid email or password'::TEXT;
  ELSE
    -- Update last login
    UPDATE demo_login_credentials_2026_02_19_14_00
    SET last_login = NOW(), login_attempts = 0
    WHERE demo_login_credentials_2026_02_19_14_00.email = p_email;

    -- Return success
    RETURN QUERY SELECT true, v_user_id, v_email, v_role, v_full_name, 'Login successful'::TEXT;
  END IF;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.authenticate_user_2026_02_17_18_40(user_email text, user_password text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    user_record public.auth_users_2026_02_17_18_40%ROWTYPE;
    branch_info public.branches_2026_02_17_18_40%ROWTYPE;
    result json;
BEGIN
    -- Get user record
    SELECT * INTO user_record
    FROM public.auth_users_2026_02_17_18_40
    WHERE email = user_email AND is_active = true;

    IF NOT FOUND THEN
        RETURN json_build_object('success', false, 'error', 'Invalid credentials');
    END IF;

    -- Check if account is locked
    IF user_record.locked_until IS NOT NULL AND user_record.locked_until > now() THEN
        RETURN json_build_object('success', false, 'error', 'Account is temporarily locked');
    END IF;

    -- Simple password check (in production, use proper hashing)
    IF user_record.password_hash != user_password THEN
        -- Increment failed attempts
        UPDATE public.auth_users_2026_02_17_18_40
        SET failed_attempts = failed_attempts + 1,
            locked_until = CASE
                WHEN failed_attempts >= 4 THEN now() + interval '15 minutes'
                ELSE NULL
            END
        WHERE id = user_record.id;

        RETURN json_build_object('success', false, 'error', 'Invalid credentials');
    END IF;

    -- Get branch info
    SELECT * INTO branch_info
    FROM public.branches_2026_02_17_18_40
    WHERE id = user_record.branch_id;

    -- Update successful login
    UPDATE public.auth_users_2026_02_17_18_40
    SET last_login_at = now(),
        updated_at = now(),
        failed_attempts = 0,
        locked_until = NULL
    WHERE id = user_record.id;

    -- Build success result
    result := json_build_object(
        'success', true,
        'user', json_build_object(
            'id', user_record.id,
            'email', user_record.email,
            'full_name', user_record.full_name,
            'role', user_record.role,
            'branch_name', COALESCE(branch_info.name, 'Unknown Branch'),
            'branch_code', COALESCE(branch_info.code, 'UNK'),
            'must_change_password', user_record.must_change_password,
            'is_active', user_record.is_active,
            'last_login_at', user_record.last_login_at
        )
    );

    RETURN result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.auto_approve_on_insert()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  -- Policy: If COD is 0, auto-approve immediately
  IF NEW.cod_amount = 0 THEN
    INSERT INTO public.supply_chain_events (way_id, segment, event_type, note, meta)
    VALUES (NEW.way_id, 'SUPERVISOR', 'SUPV_APPROVED', 'System Auto-Approve: COD=0', '{"auto": true, "force": true}');
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.auto_assign_resources_2026_02_18_17_00(p_parcel_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_result JSONB := '{"assigned": [], "failed": []}';
    v_parcel_id UUID;
    v_zone VARCHAR(10);
    v_route_id UUID;
    v_rider_id TEXT;
    v_driver_id TEXT;
    v_vehicle_id TEXT;
BEGIN
    FOREACH v_parcel_id IN ARRAY p_parcel_ids
    LOOP
        -- Get parcel zone
        SELECT pickup_zone INTO v_zone
        FROM public.parcels_2026_02_18_17_00
        WHERE id = v_parcel_id;

        -- Find or create route for the zone and date
        SELECT id INTO v_route_id
        FROM public.route_plans_2026_02_18_17_00
        WHERE zone = v_zone
        AND route_date = CURRENT_DATE
        AND status = 'PLANNED'
        AND total_parcels < 20 -- Max parcels per route
        ORDER BY total_parcels ASC
        LIMIT 1;

        -- Create new route if none available
        IF v_route_id IS NULL THEN
            INSERT INTO public.route_plans_2026_02_18_17_00 (
                route_code, route_date, zone
            ) VALUES (
                v_zone || '-' || TO_CHAR(CURRENT_DATE, 'YYYYMMDD') || '-' ||
                LPAD((SELECT COUNT(*) + 1 FROM public.route_plans_2026_02_18_17_00
                      WHERE zone = v_zone AND route_date = CURRENT_DATE)::TEXT, 3, '0'),
                CURRENT_DATE,
                v_zone
            ) RETURNING id INTO v_route_id;
        END IF;

        -- Assign available rider
        SELECT personnel_code INTO v_rider_id
        FROM public.delivery_personnel_2026_02_18_17_00
        WHERE role = 'RIDER'
        AND current_status = 'AVAILABLE'
        AND v_zone = ANY(zone_assignments)
        ORDER BY total_deliveries ASC
        LIMIT 1;

        -- Assign available vehicle
        SELECT vehicle_code INTO v_vehicle_id
        FROM public.vehicles_2026_02_18_17_00
        WHERE status = 'AVAILABLE'
        AND vehicle_type IN ('MOTORCYCLE', 'VAN')
        ORDER BY capacity_parcels DESC
        LIMIT 1;

        -- Update parcel with assignments
        UPDATE public.parcels_2026_02_18_17_00
        SET
            assigned_route_id = v_route_id,
            assigned_rider_id = v_rider_id,
            assigned_vehicle_id = v_vehicle_id,
            status = 'ASSIGNED',
            updated_at = NOW()
        WHERE id = v_parcel_id;

        -- Update route parcel count
        UPDATE public.route_plans_2026_02_18_17_00
        SET total_parcels = total_parcels + 1
        WHERE id = v_route_id;

        -- Update personnel status
        IF v_rider_id IS NOT NULL THEN
            UPDATE public.delivery_personnel_2026_02_18_17_00
            SET
                current_status = 'ASSIGNED',
                current_route_id = v_route_id
            WHERE personnel_code = v_rider_id;
        END IF;

        -- Update vehicle status
        IF v_vehicle_id IS NOT NULL THEN
            UPDATE public.vehicles_2026_02_18_17_00
            SET
                status = 'ASSIGNED',
                current_route_id = v_route_id
            WHERE vehicle_code = v_vehicle_id;
        END IF;

        -- Add to result
        v_result := jsonb_set(
            v_result,
            '{assigned}',
            (v_result->'assigned') || jsonb_build_object(
                'parcel_id', v_parcel_id,
                'route_id', v_route_id,
                'rider_id', v_rider_id,
                'vehicle_id', v_vehicle_id
            )
        );
    END LOOP;

    RETURN v_result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.auto_assign_shipment_2026_02_19_17_00(p_shipment_id uuid, p_shipment_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_assignment_result JSONB := '{"success": false}';
    v_rule RECORD;
    v_branch_id UUID;
    v_user_id UUID;
    v_priority INTEGER := 5;
BEGIN
    -- Get applicable assignment rules
    FOR v_rule IN
        SELECT * FROM shipment_assignment_rules_2026_02_19_17_00
        WHERE is_active = true
        ORDER BY priority ASC
    LOOP
        -- Check if rule conditions match (simplified logic)
        IF v_rule.rule_type = 'PICKUP' THEN
            -- Find nearest branch for pickup
            SELECT id INTO v_branch_id
            FROM branches_2026_02_19_13_00
            WHERE status = 'ACTIVE'
            ORDER BY RANDOM()
            LIMIT 1;

            -- Find available user at branch
            SELECT id INTO v_user_id
            FROM users_2026_02_19_13_00
            WHERE branch_id = v_branch_id
            AND role IN ('WAREHOUSE_MANAGER', 'SUPERVISOR')
            AND status = 'ACTIVE'
            ORDER BY RANDOM()
            LIMIT 1;

            -- Create workflow state
            INSERT INTO shipment_workflow_states_2026_02_19_17_00 (
                shipment_id, current_state, assigned_to_user_id,
                assigned_to_branch_id, auto_assigned, assignment_reason
            ) VALUES (
                p_shipment_id, 'PENDING_PICKUP', v_user_id,
                v_branch_id, true, v_rule.rule_name
            );

            -- Add to assignment queue
            INSERT INTO assignment_queue_2026_02_19_17_00 (
                shipment_id, queue_type, branch_id, assigned_user_id, priority
            ) VALUES (
                p_shipment_id, 'PICKUP', v_branch_id, v_user_id, v_priority
            );

            -- Create notification
            INSERT INTO realtime_notifications_2026_02_19_17_00 (
                user_id, notification_type, title, message, data, action_required, action_url
            ) VALUES (
                v_user_id, 'PICKUP_ASSIGNMENT', 'New Pickup Assignment',
                'A new shipment has been assigned for pickup',
                jsonb_build_object('shipment_id', p_shipment_id, 'branch_id', v_branch_id),
                true, '/warehouse/receiving'
            );

            v_assignment_result := jsonb_build_object(
                'success', true,
                'assigned_to_branch', v_branch_id,
                'assigned_to_user', v_user_id,
                'workflow_state', 'PENDING_PICKUP',
                'rule_applied', v_rule.rule_name
            );

            EXIT; -- Exit after first successful assignment
        END IF;
    END LOOP;

    RETURN v_assignment_result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be30_after_pickup(pid text, evt text DEFAULT 'pickup_submitted'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r record; meta jsonb;
begin
  select * into r from public.be_portal_pickup_requests where pickup_id=pid limit 1;
  if not found then return; end if;
  meta := jsonb_build_object('pickup_id',r.pickup_id,'deliver_id',r.deliver_id,'invoice_no',r.invoice_no,'waybill_no',r.waybill_no,'merchant_code',r.merchant_code,'parcel_count',r.parcel_count,'status',r.status);
  perform public.be30_event(r.pickup_id,evt,r.status,coalesce(r.source,'system'),null,meta);
  perform public.be30_notify('customer_service',r.assigned_branch,r.pickup_id,'Pickup request created',coalesce(r.merchant_name,r.pickup_id)||' pickup created.',meta);
  perform public.be30_notify('supervisor',r.assigned_branch,r.pickup_id,'Pickup requires assignment',r.pickup_id||' waiting for assignment.',meta);
  perform public.be30_notify('operation_manager',r.assigned_branch,r.pickup_id,'New pickup in operations queue',r.pickup_id||' entered workflow.',meta);
  perform public.be30_notify('dispatch',r.assigned_branch,r.pickup_id,'Pickup ready for dispatch planning',r.pickup_id||' can be planned after assignment.',meta);
  if r.status='data_entry_in_progress' then perform public.be30_notify('data_entry',r.assigned_branch,r.pickup_id,'Pickup needs Data Entry completion',r.pickup_id||' missing address/township.',meta); end if;
  if coalesce(r.cod_amount,0)>0 or lower(coalesce(r.payment_terms,''))='cod' then perform public.be30_notify('finance',r.assigned_branch,r.pickup_id,'COD pickup created',r.pickup_id||' requires COD tracking.',meta); end if;

  insert into public.be_waybill_ledger(waybill_no,pickup_id,deliver_id,invoice_no,merchant_code,merchant_name,parcel_count,cod_amount,status,payload,updated_at)
  values(r.waybill_no,r.pickup_id,r.deliver_id,r.invoice_no,r.merchant_code,r.merchant_name,coalesce(r.parcel_count,1),coalesce(r.cod_amount,0),'printed',meta,now())
  on conflict(waybill_no) do update set pickup_id=excluded.pickup_id, deliver_id=excluded.deliver_id, invoice_no=excluded.invoice_no, parcel_count=excluded.parcel_count, cod_amount=excluded.cod_amount, updated_at=now();

  insert into public.be_invoice_ledger(invoice_no,pickup_id,deliver_id,waybill_no,merchant_code,merchant_name,shipment_count,status,payload,updated_at)
  values(r.invoice_no,r.pickup_id,r.deliver_id,r.waybill_no,r.merchant_code,r.merchant_name,coalesce(r.parcel_count,1),'draft',meta,now())
  on conflict(invoice_no) do update set pickup_id=excluded.pickup_id, deliver_id=excluded.deliver_id, waybill_no=excluded.waybill_no, shipment_count=excluded.shipment_count, updated_at=now();

  if coalesce(r.cod_amount,0)>0 or lower(coalesce(r.payment_terms,''))='cod' then
    insert into public.be_cod_ledger(pickup_id,deliver_id,invoice_no,waybill_no,merchant_code,cod_expected,status,payload,updated_at)
    values(r.pickup_id,r.deliver_id,r.invoice_no,r.waybill_no,r.merchant_code,coalesce(r.cod_amount,0),'pending_collection',meta,now())
    on conflict(pickup_id) do update set cod_expected=excluded.cod_expected, deliver_id=excluded.deliver_id, invoice_no=excluded.invoice_no, waybill_no=excluded.waybill_no, updated_at=now();
  end if;
end; $function$
;

CREATE OR REPLACE FUNCTION public.be30_clean(p text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare v text;
begin
  v := nullif(btrim(coalesce(p,'')), '');
  if v is null or lower(v) in ('null','undefined','none','n/a','na','unknown','missing','no pickup address','no address','not set','-') then return null; end if;
  return v;
end; $function$
;

CREATE OR REPLACE FUNCTION public.be30_count(payload jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare raw text; n int;
begin
  raw := regexp_replace(coalesce(payload->>'parcel_count', payload->>'pickup_parcel_count', payload->>'package_count', '1'), '[^0-9]', '', 'g');
  n := coalesce(nullif(raw,'')::int,1);
  return greatest(1, least(n,999));
exception when others then return 1;
end; $function$
;

CREATE OR REPLACE FUNCTION public.be30_event(pid text, typ text, st text, role text DEFAULT NULL::text, code text DEFAULT NULL::text, meta jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  insert into public.be_portal_cargo_events(pickup_id,event_type,status,actor_role,actor_code,metadata,created_at)
  values(pid,typ,st,role,code,coalesce(meta,'{}'::jsonb),now());
exception when others then null;
end; $function$
;

CREATE OR REPLACE FUNCTION public.be30_ids(payload jsonb, merchant jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare pfx text; d date; cnt int; suffix text; dsuffix text;
begin
  pfx := public.be30_prefix(payload,merchant);
  d := public.be30_pickup_date(payload);
  cnt := public.be30_count(payload);
  suffix := lpad(cnt::text,3,'0');
  dsuffix := lpad(least(cnt+1,999)::text,3,'0');
  return jsonb_build_object(
    'pickup_prefix',pfx,'pickup_date',d,'parcel_count',cnt,
    'pickup_id','P'||to_char(d,'MMDD')||'-'||pfx||'-'||suffix,
    'deliver_id','D'||to_char(d,'MMDD')||'-'||pfx||'-'||dsuffix,
    'invoice_no','I'||to_char(d,'MMDD')||'-'||pfx||'-'||suffix,
    'waybill_no','W'||to_char(d,'MMDD')||'-'||pfx||'-'||suffix
  );
end; $function$
;

CREATE OR REPLACE FUNCTION public.be30_jtext(j jsonb, keys text[])
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare k text; v text;
begin
  foreach k in array keys loop
    v := public.be30_clean(j->>k);
    if v is not null then return v; end if;
  end loop;
  return null;
end; $function$
;

CREATE OR REPLACE FUNCTION public.be30_notify(role text, branch text, pid text, title text, msg text, meta jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  insert into public.be_app_notifications(target_role,target_branch,pickup_id,title,message,source_key,metadata,created_at)
  values(role,branch,pid,title,msg,pid,coalesce(meta,'{}'::jsonb),now());
exception when others then null;
end; $function$
;

CREATE OR REPLACE FUNCTION public.be30_pickup_date(payload jsonb)
 RETURNS date
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare d text;
begin
  d := public.be30_clean(coalesce(payload->>'pickup_date', payload->>'request_date', payload->>'scheduled_pickup_date'));
  if d ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then return d::date; end if;
  if d ~ '^[0-9]{2}/[0-9]{2}/[0-9]{4}$' then return to_date(d,'MM/DD/YYYY'); end if;
  return current_date;
exception when others then return current_date;
end; $function$
;

CREATE OR REPLACE FUNCTION public.be30_prefix(p_payload jsonb, p_merchant jsonb)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$

declare
    v_prefix text;

begin

    select split_part(pr.pickup_id,'-',2)
    into v_prefix

    from public.be_portal_pickup_requests pr

    where pr.pickup_id ~ '^P[0-9]{4}-[A-Z]{3}-[0-9]{3}$'

    and (
        lower(coalesce(pr.merchant_name,'')) =
        lower(coalesce(p_payload->>'merchant_name',
                       p_merchant->>'merchant_name',
                       ''))

        or

        lower(coalesce(pr.sender_phone,'')) =
        lower(coalesce(p_payload->>'sender_phone',
                       p_merchant->>'sender_phone',
                       ''))
    )

    order by pr.created_at desc nulls last

    limit 1;


    if v_prefix is null then
        v_prefix :=
        upper(
            left(
                regexp_replace(
                    coalesce(
                        p_payload->>'merchant_code',
                        p_merchant->>'merchant_code',
                        'GEN'
                    ),
                    '[^A-Za-z0-9]',
                    '',
                    'g'
                ),
                3
            )
        );
    end if;


    return v_prefix;

end;
$function$
;

CREATE OR REPLACE FUNCTION public.be30_resolve_merchant(payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare q text; res jsonb; item jsonb;
begin
  q := coalesce(public.be30_clean(payload->>'merchant_code'), public.be30_clean(payload->>'merchant_name'), public.be30_clean(payload->>'sender_phone'), '');
  res := public.be_customer_service_merchant_lookup(q,20);
  select value into item from jsonb_array_elements(coalesce(res->'merchants','[]'::jsonb)) value
  order by case when lower(value->>'merchant_code')=lower(coalesce(payload->>'merchant_code','')) then 0 when lower(value->>'merchant_name')=lower(coalesce(payload->>'merchant_name','')) then 1 else 2 end
  limit 1;
  return coalesce(item,'{}'::jsonb);
end; $function$
;

CREATE OR REPLACE FUNCTION public.be__column_exists(p_table text, p_column text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  select exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = p_table
      and column_name = p_column
  );
$function$
;

CREATE OR REPLACE FUNCTION public.be__table_exists(p_table text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  select to_regclass('public.' || p_table) is not null;
$function$
;

CREATE OR REPLACE FUNCTION public.be__warehouse_touch_table(p_table text, p_match_col text, p_match_value text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_count integer := 0;
begin
  if p_match_value is null or btrim(p_match_value) = '' then
    return 0;
  end if;

  if not public.be__table_exists(p_table) then
    return 0;
  end if;

  if not public.be__column_exists(p_table, p_match_col) then
    return 0;
  end if;

  if not public.be__column_exists(p_table, 'updated_at') then
    return 0;
  end if;

  execute format(
    'update public.%I set updated_at = now() where %I::text = $1',
    p_table,
    p_match_col
  ) using p_match_value;

  get diagnostics v_count = row_count;
  return coalesce(v_count, 0);
exception when others then
  return 0;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be__warehouse_update_one(p_table text, p_match_col text, p_match_value text, p_target_col text, p_value text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_count integer := 0;
begin
  if p_match_value is null or btrim(p_match_value) = '' then
    return 0;
  end if;

  if not public.be__table_exists(p_table) then
    return 0;
  end if;

  if not public.be__column_exists(p_table, p_match_col) then
    return 0;
  end if;

  if not public.be__column_exists(p_table, p_target_col) then
    return 0;
  end if;

  execute format(
    'update public.%I set %I = $1 where %I::text = $2',
    p_table,
    p_target_col,
    p_match_col
  ) using p_value, p_match_value;

  get diagnostics v_count = row_count;
  return coalesce(v_count, 0);
exception when others then
  -- Some deployments use enum/json/timestamp columns. Ignore incompatible column writes
  -- and continue updating other compatible tables/columns.
  return 0;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_app_notifications_dedupe_before_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_new jsonb := to_jsonb(new);
  v_role text;
  v_email text;
  v_type text;
  v_pickup text;
  v_existing_id uuid;
begin
  v_role := coalesce(
    v_new->>'target_role',
    v_new->>'recipient_role',
    v_new->>'role',
    v_new->>'role_key'
  );

  v_email := coalesce(
    v_new->>'target_email',
    v_new->>'recipient_email',
    v_new->>'email',
    v_new->>'user_email'
  );

  v_type := coalesce(
    v_new->>'notification_type',
    v_new->>'type',
    v_new->>'event_type',
    v_new->>'message_type'
  );

  v_pickup := coalesce(
    v_new->>'pickup_id',
    v_new->>'pickup_way_id',
    v_new->>'reference_id',
    v_new->>'ref_id'
  );

  if v_role is null and v_email is null and v_type is null and v_pickup is null then
    return new;
  end if;

  select id
  into v_existing_id
  from public.be_app_notifications n
  where coalesce(
      to_jsonb(n)->>'target_role',
      to_jsonb(n)->>'recipient_role',
      to_jsonb(n)->>'role',
      to_jsonb(n)->>'role_key'
    ) is not distinct from v_role
    and coalesce(
      to_jsonb(n)->>'target_email',
      to_jsonb(n)->>'recipient_email',
      to_jsonb(n)->>'email',
      to_jsonb(n)->>'user_email'
    ) is not distinct from v_email
    and coalesce(
      to_jsonb(n)->>'notification_type',
      to_jsonb(n)->>'type',
      to_jsonb(n)->>'event_type',
      to_jsonb(n)->>'message_type'
    ) is not distinct from v_type
    and coalesce(
      to_jsonb(n)->>'pickup_id',
      to_jsonb(n)->>'pickup_way_id',
      to_jsonb(n)->>'reference_id',
      to_jsonb(n)->>'ref_id'
    ) is not distinct from v_pickup
  order by n.created_at desc nulls last
  limit 1;

  if v_existing_id is not null then
    -- Duplicate notification already exists. Skip insert to avoid unique crash.
    return null;
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_app_notifications_event_key_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_base_key text;
  v_suffix text;
  v_try_key text;
  v_counter integer := 0;
begin
  if new.event_key is null or trim(new.event_key) = '' then
    return new;
  end if;

  v_base_key := new.event_key;

  if not exists (
    select 1
    from public.be_app_notifications n
    where n.event_key = v_base_key
      and n.id is distinct from new.id
  ) then
    return new;
  end if;

  v_suffix := lower(
    coalesce(nullif(new.target_role, ''), 'role') || ':' ||
    coalesce(
      nullif(new.target_user_code, ''),
      nullif(new.target_workforce_code, ''),
      nullif(new.target_email, ''),
      nullif(new.recipient_email, ''),
      nullif(new.pickup_id, ''),
      nullif(new.pickup_way_id, ''),
      'general'
    )
  );

  v_suffix := regexp_replace(v_suffix, '[^a-z0-9:_@.-]+', '-', 'g');
  v_try_key := v_base_key || ':' || v_suffix;

  while exists (
    select 1
    from public.be_app_notifications n
    where n.event_key = v_try_key
      and n.id is distinct from new.id
  ) loop
    v_counter := v_counter + 1;
    v_try_key := v_base_key || ':' || v_suffix || ':' || v_counter::text;

    exit when v_counter > 50;
  end loop;

  new.event_key := v_try_key;
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_assign_live_dispatch_wayplan(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_pickup_id text := coalesce(p_payload->>'pickup_id', '');
  v_way_id text := coalesce(p_payload->>'way_id', '');
  v_rider_code text := coalesce(p_payload->>'rider_code', '');
  v_driver_code text := coalesce(p_payload->>'driver_code', '');
  v_helper_code text := coalesce(p_payload->>'helper_code', '');
  v_fleet_code text := coalesce(p_payload->>'fleet_code', '');
  v_vehicle_plate text := coalesce(p_payload->>'vehicle_plate', '');
  v_branch_code text := upper(coalesce(p_payload->>'branch_code', 'HQ'));
  v_actor_email text := coalesce(p_payload->>'actor_email', '');
  v_note text := coalesce(p_payload->>'supervisor_note', '');
  v_event jsonb := '{}'::jsonb;
begin
  if v_pickup_id = '' then
    return jsonb_build_object(
      'ok', false,
      'error', 'pickup_id is required before dispatch assignment'
    );
  end if;

  if v_rider_code = '' and v_driver_code = '' then
    return jsonb_build_object(
      'ok', false,
      'error', 'rider_code or driver_code is required'
    );
  end if;

  insert into public.be_dispatch_wayplan_assignments (
    pickup_id,
    way_id,
    rider_code,
    driver_code,
    helper_code,
    fleet_code,
    vehicle_plate,
    branch_code,
    assignment_status,
    workflow_status,
    supervisor_note,
    assigned_by,
    raw_payload
  )
  values (
    v_pickup_id,
    nullif(v_way_id, ''),
    nullif(v_rider_code, ''),
    nullif(v_driver_code, ''),
    nullif(v_helper_code, ''),
    nullif(v_fleet_code, ''),
    nullif(v_vehicle_plate, ''),
    v_branch_code,
    'ASSIGNED',
    'PICKUP_ASSIGNED',
    nullif(v_note, ''),
    nullif(v_actor_email, ''),
    p_payload
  )
  on conflict do nothing;

  update public.be_dispatch_wayplan_assignments
  set
    way_id = nullif(v_way_id, ''),
    rider_code = nullif(v_rider_code, ''),
    driver_code = nullif(v_driver_code, ''),
    helper_code = nullif(v_helper_code, ''),
    fleet_code = nullif(v_fleet_code, ''),
    vehicle_plate = nullif(v_vehicle_plate, ''),
    branch_code = v_branch_code,
    assignment_status = 'ASSIGNED',
    workflow_status = 'PICKUP_ASSIGNED',
    supervisor_note = nullif(v_note, ''),
    assigned_by = nullif(v_actor_email, ''),
    assigned_at = now(),
    updated_at = now(),
    raw_payload = p_payload
  where pickup_id = v_pickup_id;

  if to_regclass('public.be_portal_pickup_requests') is not null then
    begin
      execute $q$
        update public.be_portal_pickup_requests p
        set
          status = 'PICKUP_ASSIGNED',
          updated_at = now()
        where coalesce(to_jsonb(p)->>'pickup_id', to_jsonb(p)->>'canonical_pickup_id', '') = $1
      $q$
      using v_pickup_id;
    exception when others then
      null;
    end;
  end if;

  if to_regprocedure('public.be_logistics_apply_workflow_event_strict(jsonb)') is not null then
    begin
      execute 'select public.be_logistics_apply_workflow_event_strict($1)'
      into v_event
      using jsonb_build_object(
        'pickup_id', v_pickup_id,
        'way_id', v_way_id,
        'process_type', 'PICKUP',
        'status_code', 'PICKUP_ASSIGNED',
        'actor_email', v_actor_email,
        'actor_role', 'dispatch',
        'remarks', coalesce(v_note, 'Pickup assigned from live dispatch wayplan board'),
        'metadata', p_payload
      );
    exception when others then
      v_event := jsonb_build_object('ok', false, 'warning', 'workflow strict event failed');
    end;
  end if;

  return jsonb_build_object(
    'ok', true,
    'pickup_id', v_pickup_id,
    'way_id', v_way_id,
    'rider_code', v_rider_code,
    'driver_code', v_driver_code,
    'helper_code', v_helper_code,
    'fleet_code', v_fleet_code,
    'vehicle_plate', v_vehicle_plate,
    'branch_code', v_branch_code,
    'workflow_status', 'PICKUP_ASSIGNED',
    'workflow_event', coalesce(v_event, '{}'::jsonb)
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_assign_live_dispatch_wayplan(p_pickup_ids text[], p_worker_id text, p_route_label text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE v_count INT;
BEGIN
  UPDATE public.be_portal_pickup_requests
  SET assigned_rider_id = p_worker_id, status = 'PICKUP_ASSIGNED', route_label = p_route_label, updated_at = NOW()
  WHERE pickup_id = ANY(p_pickup_ids);
  GET DIAGNOSTICS v_count = ROW_COUNT;

  INSERT INTO public.be_portal_cargo_events (pickup_id, event_type, description, actor_role)
  SELECT pid, 'ASSIGNED', 'Dispatched to Route: ' || COALESCE(p_route_label, 'N/A'), public.be_current_user_role()
  FROM UNNEST(p_pickup_ids) AS pid;

  RETURN json_build_object('success', true, 'assigned_count', v_count);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_assign_pickup_field_team(p_pickup_id text, p_rider_code text DEFAULT NULL::text, p_driver_code text DEFAULT NULL::text, p_helper_code text DEFAULT NULL::text, p_vehicle_plate text DEFAULT NULL::text, p_supervisor_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_pickup_id text := trim(p_pickup_id);
  v_rider public.be_mobile_workforce_accounts;
  v_driver public.be_mobile_workforce_accounts;
  v_helper public.be_mobile_workforce_accounts;
begin
  if nullif(trim(coalesce(p_rider_code, '')), '') is not null then
    select * into v_rider
    from public.be_mobile_workforce_accounts
    where lower(coalesce(status, 'active')) = 'active'
      and lower(workforce_type) = 'rider'
      and (lower(workforce_code) = lower(trim(p_rider_code)) or lower(display_name) = lower(trim(p_rider_code)))
    limit 1;
    if v_rider.workforce_code is null then raise exception 'Rider % not found or inactive', p_rider_code; end if;
  end if;

  if nullif(trim(coalesce(p_driver_code, '')), '') is not null then
    select * into v_driver
    from public.be_mobile_workforce_accounts
    where lower(coalesce(status, 'active')) = 'active'
      and lower(workforce_type) = 'driver'
      and (lower(workforce_code) = lower(trim(p_driver_code)) or lower(display_name) = lower(trim(p_driver_code)))
    limit 1;
    if v_driver.workforce_code is null then raise exception 'Driver % not found or inactive', p_driver_code; end if;
  end if;

  if nullif(trim(coalesce(p_helper_code, '')), '') is not null then
    select * into v_helper
    from public.be_mobile_workforce_accounts
    where lower(coalesce(status, 'active')) = 'active'
      and lower(workforce_type) = 'helper'
      and (lower(workforce_code) = lower(trim(p_helper_code)) or lower(display_name) = lower(trim(p_helper_code)))
    limit 1;
    if v_helper.workforce_code is null then raise exception 'Helper % not found or inactive', p_helper_code; end if;
  end if;

  update public.be_portal_pickup_requests
  set
    status = 'assigned',
    assignment_status = 'assigned',
    assigned_rider_code = v_rider.workforce_code,
    assigned_rider_name = v_rider.display_name,
    assigned_driver_code = v_driver.workforce_code,
    assigned_driver_name = v_driver.display_name,
    assigned_helper_code = v_helper.workforce_code,
    assigned_helper_name = v_helper.display_name,
    assigned_workforce_type = coalesce(v_rider.workforce_type, v_driver.workforce_type, v_helper.workforce_type),
    assigned_workforce_code = coalesce(v_rider.workforce_code, v_driver.workforce_code, v_helper.workforce_code),
    assigned_workforce_name = coalesce(v_rider.display_name, v_driver.display_name, v_helper.display_name),
    assigned_vehicle_plate = nullif(trim(coalesce(p_vehicle_plate, '')), ''),
    supervisor_note = nullif(trim(coalesce(p_supervisor_note, '')), ''),
    assigned_at = now(),
    updated_at = now()
  where pickup_id = v_pickup_id;

  if not found then raise exception 'Pickup % not found', p_pickup_id; end if;

  update public.be_portal_cargo_events
  set
    status = case when event_type = 'data_entry_waybill' and coalesce(status, '') in ('draft','ready_for_operations','pickup_verified') then 'assigned' else status end,
    assigned_rider_code = v_rider.workforce_code,
    assigned_rider_name = v_rider.display_name,
    assigned_driver_code = v_driver.workforce_code,
    assigned_driver_name = v_driver.display_name,
    assigned_helper_code = v_helper.workforce_code,
    assigned_helper_name = v_helper.display_name,
    assigned_vehicle_plate = nullif(trim(coalesce(p_vehicle_plate, '')), ''),
    payload = coalesce(payload, '{}'::jsonb) || jsonb_build_object(
      'assigned_rider_code', v_rider.workforce_code,
      'assigned_rider_name', v_rider.display_name,
      'assigned_driver_code', v_driver.workforce_code,
      'assigned_driver_name', v_driver.display_name,
      'assigned_helper_code', v_helper.workforce_code,
      'assigned_helper_name', v_helper.display_name,
      'assigned_vehicle_plate', nullif(trim(coalesce(p_vehicle_plate, '')), '')
    ),
    updated_at = now()
  where pickup_id = v_pickup_id
    and event_type = 'data_entry_waybill';

  perform public.be_upsert_field_assignment_notification(v_pickup_id, 'rider', v_rider.auth_user_id, v_rider.workforce_code, v_rider.display_name);
  perform public.be_upsert_field_assignment_notification(v_pickup_id, 'driver', v_driver.auth_user_id, v_driver.workforce_code, v_driver.display_name);
  perform public.be_upsert_field_assignment_notification(v_pickup_id, 'helper', v_helper.auth_user_id, v_helper.workforce_code, v_helper.display_name);

  return jsonb_build_object(
    'ok', true, 'pickup_id', v_pickup_id, 'pickup_request_id', v_pickup_id,
    'assigned_rider_code', v_rider.workforce_code, 'assigned_rider_name', v_rider.display_name,
    'assigned_driver_code', v_driver.workforce_code, 'assigned_driver_name', v_driver.display_name,
    'assigned_helper_code', v_helper.workforce_code, 'assigned_helper_name', v_helper.display_name,
    'vehicle_plate', p_vehicle_plate
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_assign_pickup_request(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ select public.be_supervisor_assign_job(p_payload); $function$
;

CREATE OR REPLACE FUNCTION public.be_assign_pickup_request_by_rider_code(p_request_code text, p_rider_code text, p_assigned_vehicle_id uuid DEFAULT NULL::uuid, p_assignment_note text DEFAULT NULL::text, p_actor_registry_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id text := public.be_validate_pickupway_id(p_request_code);
  v_rows integer := 0;
begin
  if v_id is null then
    raise exception 'Invalid PickupWayID %. Expected format like P0611-BRV-001.', p_request_code;
  end if;

  v_rows := v_rows + public.be_try_update_pickupway_table(
    'be_portal_pickup_requests',
    v_id,
    jsonb_build_object(
      'pickup_way_id', v_id,
      'pickup_id', v_id,
      'request_code', v_id,
      'assigned_rider', upper(trim(p_rider_code)),
      'assigned_rider_code', upper(trim(p_rider_code)),
      'pickup_status', 'ASSIGNED_TO_DRIVER',
      'rider_status', 'ASSIGNED_TO_DRIVER',
      'workflow_stage', 'ASSIGNED_TO_DRIVER',
      'status', 'ASSIGNED_TO_DRIVER',
      'assignment_note', p_assignment_note,
      'assigned_at', now()
    )
  );

  v_rows := v_rows + public.be_try_update_pickupway_table(
    'be_pickup_requests',
    v_id,
    jsonb_build_object(
      'pickup_way_id', v_id,
      'pickup_id', v_id,
      'request_code', v_id,
      'assigned_rider', upper(trim(p_rider_code)),
      'assigned_rider_code', upper(trim(p_rider_code)),
      'pickup_status', 'ASSIGNED_TO_DRIVER',
      'rider_status', 'ASSIGNED_TO_DRIVER',
      'workflow_stage', 'ASSIGNED_TO_DRIVER',
      'status', 'ASSIGNED_TO_DRIVER',
      'assignment_note', p_assignment_note,
      'assigned_at', now()
    )
  );

  return jsonb_build_object(
    'ok', true,
    'pickup_way_id', v_id,
    'request_code', v_id,
    'assigned_rider_code', upper(trim(p_rider_code)),
    'updated_rows', v_rows
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_audit_document_print_log_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row jsonb := to_jsonb(new);
  v_document_type text;
  v_document_no text;
  v_actor_email text;
  v_print_count text;
  v_approval_status text;
begin
  v_document_type := coalesce(
    v_row->>'document_type',
    v_row->>'doc_type',
    'DOCUMENT'
  );

  v_document_no := coalesce(
    v_row->>'document_no',
    v_row->>'waybill_no',
    v_row->>'invoice_no',
    v_row->>'tracking_no',
    v_row->>'document_ref',
    v_row->>'id',
    'UNKNOWN'
  );

  v_actor_email := coalesce(
    v_row->>'printed_by',
    v_row->>'actor_email',
    v_row->>'created_by',
    v_row->>'user_email',
    'system'
  );

  v_print_count := coalesce(
    v_row->>'print_count',
    v_row->>'print_count_before',
    '1'
  );

  v_approval_status := coalesce(
    v_row->>'approval_status',
    case
      when coalesce(v_row->>'approval_request_id', '') <> '' then 'APPROVED_REPRINT'
      else 'FIRST_PRINT_OR_ALLOWED_PRINT'
    end
  );

  perform public.be_write_governance_audit(
    'DOCUMENT_PRINT',
    'DOCUMENT_PRINTED',
    'be_document_print_log',
    v_document_no,
    v_actor_email,
    '{}'::jsonb,
    v_row,
    jsonb_build_object(
      'document_type', v_document_type,
      'document_no', v_document_no,
      'print_count', v_print_count,
      'approval_status', v_approval_status,
      'source', 'be_audit_document_print_log_insert'
    )
  );

  return new;
end;
$function$
;

