CREATE OR REPLACE FUNCTION public.be_bootstrap_first_admin(p_full_name text DEFAULT 'Britium Admin'::text, p_branch_code text DEFAULT 'YGN'::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_email text := auth.email();
  v_count int;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT count(*) INTO v_count FROM public.be_user_account_registry WHERE status = 'active';

  IF v_count > 0 THEN
    RAISE EXCEPTION 'Admin bootstrap is locked because registry already has users';
  END IF;

  INSERT INTO public.be_user_account_registry(auth_user_id, full_name, role, email, branch_code, status)
  VALUES (v_uid, p_full_name, 'admin', v_email, p_branch_code, 'active')
  ON CONFLICT (auth_user_id) DO UPDATE SET role = 'admin', status = 'active', updated_at = now();

  RETURN json_build_object('ok', true, 'role', 'admin', 'email', v_email);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_branch_amendment_decide(p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id uuid := nullif(p_payload->>'amendment_id', '')::uuid;
  v_decision text := upper(coalesce(p_payload->>'decision', 'APPROVED'));
  v_actor text := nullif(p_payload->>'actor_email', '');
  v_role text := lower(coalesce(p_payload->>'actor_role', 'admin'));
  v_note text := nullif(p_payload->>'decision_note', '');
  v_ctx jsonb;
  v_req record;
  v_updated integer := 0;
begin
  v_ctx := public.be_require_admin(v_actor, v_role);

  if v_decision not in ('APPROVED', 'REJECTED') then
    raise exception 'decision must be APPROVED or REJECTED';
  end if;

  select *
  into v_req
  from public.be_branch_amendment_requests
  where id = v_id
  for update;

  if not found then
    raise exception 'Amendment request not found: %', v_id;
  end if;

  if coalesce(v_req.approval_status, 'PENDING') <> 'PENDING' then
    return jsonb_build_object(
      'ok', true,
      'amendment_id', v_id,
      'approval_status', v_req.approval_status,
      'message', 'Already decided',
      'actor', v_ctx
    );
  end if;

  update public.be_branch_amendment_requests
  set
    approval_status = v_decision,
    approved_by = coalesce(v_actor, v_ctx->>'email'),
    approved_at = now(),
    remarks = coalesce(v_note, remarks),
    updated_at = now()
  where id = v_id;

  if v_decision = 'APPROVED' then
    if v_req.target_table = 'be_branch_shipments' then
      update public.be_branch_shipments
      set
        recipient_name = coalesce(v_req.requested_data->>'recipient_name', recipient_name),
        recipient_phone = coalesce(v_req.requested_data->>'recipient_phone', recipient_phone),
        township = coalesce(v_req.requested_data->>'township', township),
        address = coalesce(v_req.requested_data->>'address', address),
        shipment_status = coalesce(v_req.requested_data->>'shipment_status', shipment_status),
        metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
          'last_amendment_id', v_id,
          'amended_by', coalesce(v_actor, v_ctx->>'email'),
          'amended_at', now()
        ),
        updated_at = now()
      where id::text = v_req.target_id
         or delivery_way_id = v_req.target_id
         or waybill_no = v_req.target_id
         or tracking_no = v_req.target_id;

      get diagnostics v_updated = row_count;
    end if;

    if v_req.target_table = 'be_master_entity_records' then
      update public.be_master_entity_records
      set
        data = coalesce(data, '{}'::jsonb) || v_req.requested_data,
        updated_by = coalesce(v_actor, v_ctx->>'email'),
        updated_at = now()
      where id::text = v_req.target_id
         or entity_code = v_req.target_id;

      get diagnostics v_updated = row_count;
    end if;
  end if;

  insert into public.be_governance_audit_log (
    module,
    action,
    ref_table,
    ref_id,
    actor_email,
    before_data,
    after_data,
    metadata
  )
  values (
    'BRANCH_OFFICE',
    'AMENDMENT_' || v_decision,
    v_req.target_table,
    v_req.target_id,
    coalesce(v_actor, v_ctx->>'email'),
    v_req.old_data,
    v_req.requested_data,
    jsonb_build_object(
      'amendment_id', v_id,
      'updated_rows', v_updated,
      'decision_note', v_note
    )
  );

  return jsonb_build_object(
    'ok', true,
    'amendment_id', v_id,
    'approval_status', v_decision,
    'updated_rows', v_updated,
    'actor', v_ctx
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_branch_amendment_request(p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_branch_code text := coalesce(p_payload->>'branch_code', 'YGN');
  v_request_type text := coalesce(p_payload->>'request_type', 'SHIPMENT_AMENDMENT');
  v_target_table text := nullif(p_payload->>'target_table', '');
  v_target_id text := nullif(p_payload->>'target_id', '');
  v_requested_data jsonb := coalesce(p_payload->'requested_data', '{}'::jsonb);
  v_old_data jsonb := coalesce(p_payload->'old_data', '{}'::jsonb);
  v_actor text := nullif(p_payload->>'actor_email', '');
  v_reason text := nullif(p_payload->>'remarks', '');
  v_id uuid;
begin
  insert into public.be_branch_amendment_requests (
    branch_code,
    request_type,
    target_table,
    target_id,
    old_data,
    requested_data,
    approval_status,
    requested_by,
    remarks
  )
  values (
    v_branch_code,
    v_request_type,
    v_target_table,
    v_target_id,
    v_old_data,
    v_requested_data,
    'PENDING',
    v_actor,
    v_reason
  )
  returning id into v_id;

  insert into public.be_governance_audit_log (
    module,
    action,
    ref_table,
    ref_id,
    actor_email,
    after_data,
    metadata
  )
  values (
    'BRANCH_OFFICE',
    'AMENDMENT_REQUESTED',
    v_target_table,
    v_target_id,
    v_actor,
    v_requested_data,
    jsonb_build_object('amendment_id', v_id, 'branch_code', v_branch_code)
  );

  return jsonb_build_object(
    'ok', true,
    'amendment_id', v_id,
    'approval_status', 'PENDING'
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_branch_dashboard(p_branch text)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
AS $function$

select jsonb_build_object(

'staff',
(
 select coalesce(jsonb_agg(w), '[]')
 from be_mobile_workforce_accounts w
 where branch_code=p_branch
),

'pickup',
(
 select coalesce(jsonb_agg(p), '[]')
 from be_portal_pickup_requests p
 where branch_code=p_branch
),

'cod',
(
 select coalesce(sum(actual_collect),0)
 from be_data_entry_parcel_details
)

);

$function$
;

CREATE OR REPLACE FUNCTION public.be_branch_go_live_verification()
 RETURNS json
 LANGUAGE sql
 STABLE SECURITY DEFINER
AS $function$
  SELECT json_build_object('ok',true,'rpc_count',(SELECT COUNT(*) FROM pg_proc WHERE proname IN ('be_branch_snapshot','be_branch_list')),'ts',NOW());
$function$
;

CREATE OR REPLACE FUNCTION public.be_branch_list()
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
DECLARE v_role TEXT := public.be_current_user_role();
BEGIN
  IF v_role NOT IN ('admin','operation_manager') THEN RAISE EXCEPTION 'Access denied'; END IF;
  RETURN (SELECT COALESCE(json_agg(row_to_json(b)),'[]'::json) FROM (
    SELECT branch_code,
           COUNT(*) AS total_shipments,
           COUNT(*) FILTER (WHERE status='DELIVERED') AS delivered,
           COUNT(*) FILTER (WHERE status='IN_TRANSIT') AS in_transit,
           COUNT(*) FILTER (WHERE created_at::DATE=CURRENT_DATE) AS today
    FROM public.be_portal_pickup_requests
    GROUP BY branch_code ORDER BY branch_code
  ) b);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_branch_office_snapshot(p_branch_code text DEFAULT NULL::text, p_limit integer DEFAULT 300)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_branches jsonb := '[]'::jsonb;
  v_staff jsonb := '[]'::jsonb;
  v_shipments jsonb := '[]'::jsonb;
  v_amendments jsonb := '[]'::jsonb;
  v_summary jsonb := '{}'::jsonb;
begin
  select coalesce(jsonb_agg(to_jsonb(b) order by b.branch_code), '[]'::jsonb)
  into v_branches
  from public.be_branch_offices b
  where p_branch_code is null or b.branch_code = p_branch_code;

  select coalesce(jsonb_agg(to_jsonb(s) order by s.branch_code, s.employee_name), '[]'::jsonb)
  into v_staff
  from (
    select
      coalesce(branch_code, 'YGN') as branch_code,
      employee_id,
      coalesce(employee_name, employee_id, email) as employee_name,
      role_id,
      department,
      phone,
      email,
      status,
      created_at,
      updated_at
    from public.be_branch_staff
    where p_branch_code is null or branch_code = p_branch_code

    union all

    select
      coalesce(branch_code, 'YGN') as branch_code,
      employee_id,
      coalesce(full_name, display_name, name, email, employee_id) as employee_name,
      coalesce(role_id, app_role) as role_id,
      department,
      phone_e164 as phone,
      email,
      status,
      created_at,
      updated_at
    from public.be_employee_master
    where coalesce(is_active, true) = true
      and (p_branch_code is null or branch_code = p_branch_code)

    limit greatest(coalesce(p_limit, 300), 1)
  ) s;

  select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc), '[]'::jsonb)
  into v_shipments
  from (
    select bs.*
    from public.be_branch_shipments bs
    where p_branch_code is null or bs.branch_code = p_branch_code
    order by bs.created_at desc nulls last
    limit greatest(coalesce(p_limit, 300), 1)
  ) x;

  select coalesce(jsonb_agg(to_jsonb(a) order by a.created_at desc), '[]'::jsonb)
  into v_amendments
  from (
    select *
    from public.be_branch_amendment_requests
    where p_branch_code is null
       or coalesce(branch_code, branch_id::text, 'YGN') = p_branch_code
    order by created_at desc nulls last
    limit 100
  ) a;

  select jsonb_build_object(
    'branches', coalesce(jsonb_array_length(v_branches), 0),
    'active_branches', (
      select count(*)
      from public.be_branch_offices
      where (p_branch_code is null or branch_code = p_branch_code)
        and coalesce(status, 'Active') = 'Active'
    ),
    'staff', coalesce(jsonb_array_length(v_staff), 0),
    'shipments', coalesce(jsonb_array_length(v_shipments), 0),
    'pending_shipments', (
      select count(*)
      from jsonb_array_elements(v_shipments) x
      where coalesce(x->>'shipment_status', '') not in ('DELIVERED','CANCELLED','RETURNED')
    ),
    'cod_total', (
      select coalesce(sum(coalesce(nullif(x->>'cod_amount', '')::numeric, 0)), 0)
      from jsonb_array_elements(v_shipments) x
    ),
    'pending_amendments', (
      select count(*)
      from public.be_branch_amendment_requests
      where (p_branch_code is null or coalesce(branch_code, branch_id::text, 'YGN') = p_branch_code)
        and coalesce(approval_status, 'PENDING') = 'PENDING'
    )
  )
  into v_summary;

  return jsonb_build_object(
    'ok', true,
    'source', 'be_branch_office_snapshot',
    'summary', coalesce(v_summary, '{}'::jsonb),
    'branches', coalesce(v_branches, '[]'::jsonb),
    'staff', coalesce(v_staff, '[]'::jsonb),
    'shipments', coalesce(v_shipments, '[]'::jsonb),
    'amendments', coalesce(v_amendments, '[]'::jsonb)
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_branch_snapshot(p_branch text)
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
DECLARE v_role TEXT := public.be_current_user_role(); v_allowed_branch TEXT;
BEGIN
  IF v_role NOT IN ('admin','operation_manager','branch_office','supervisor') THEN RAISE EXCEPTION 'Access denied'; END IF;
  -- Branch office role can only see own branch
  IF v_role = 'branch_office' THEN
    SELECT branch_code INTO v_allowed_branch FROM public.be_user_account_registry WHERE auth_user_id=auth.uid() LIMIT 1;
    IF v_allowed_branch != p_branch THEN RAISE EXCEPTION 'Access denied to branch %', p_branch; END IF;
  END IF;
  RETURN (SELECT json_build_object(
    'branch', p_branch,
    'today', json_build_object(
      'new_shipments', (SELECT COUNT(*) FROM public.be_portal_pickup_requests WHERE branch_code=p_branch AND created_at::DATE=CURRENT_DATE),
      'delivered', (SELECT COUNT(*) FROM public.be_portal_pickup_requests WHERE branch_code=p_branch AND status='DELIVERED' AND updated_at::DATE=CURRENT_DATE),
      'failed', (SELECT COUNT(*) FROM public.be_portal_pickup_requests WHERE branch_code=p_branch AND status='FAILED_DELIVERY' AND updated_at::DATE=CURRENT_DATE),
      'in_transit', (SELECT COUNT(*) FROM public.be_portal_pickup_requests WHERE branch_code=p_branch AND status='IN_TRANSIT'),
      'revenue', (SELECT COALESCE(SUM(delivery_fee),0) FROM public.be_portal_pickup_requests WHERE branch_code=p_branch AND status='DELIVERED' AND updated_at::DATE=CURRENT_DATE)
    ),
    'this_month', json_build_object(
      'new_shipments', (SELECT COUNT(*) FROM public.be_portal_pickup_requests WHERE branch_code=p_branch AND DATE_TRUNC('month',created_at)=DATE_TRUNC('month',NOW())),
      'delivered', (SELECT COUNT(*) FROM public.be_portal_pickup_requests WHERE branch_code=p_branch AND status='DELIVERED' AND DATE_TRUNC('month',updated_at)=DATE_TRUNC('month',NOW())),
      'revenue', (SELECT COALESCE(SUM(delivery_fee),0) FROM public.be_portal_pickup_requests WHERE branch_code=p_branch AND status='DELIVERED' AND DATE_TRUNC('month',updated_at)=DATE_TRUNC('month',NOW()))
    ),
    'staff', (SELECT COALESCE(json_agg(row_to_json(u)),'[]'::json) FROM (
      SELECT user_id, full_name, role, phone_number, status FROM public.be_user_account_registry WHERE branch_code=p_branch AND status='active' ORDER BY role, full_name
    ) u),
    'recent_shipments', (SELECT COALESCE(json_agg(row_to_json(s)),'[]'::json) FROM (
      SELECT pickup_id, merchant_name, recipient_name, delivery_township, status, created_at
      FROM public.be_portal_pickup_requests WHERE branch_code=p_branch ORDER BY created_at DESC LIMIT 10
    ) s)
  ));
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_bulk_submit_batch(p_rows json, p_filename text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_role TEXT := public.be_current_user_role();
  v_uid UUID := auth.uid();
  v_batch_id TEXT := 'BATCH'||TO_CHAR(NOW(),'MMDD')||'-'||SUBSTR(MD5(RANDOM()::TEXT),1,6);
  v_total INT; v_valid INT := 0; v_invalid INT := 0;
  v_row JSON; v_validation JSON; v_date TEXT; v_code TEXT; v_seq INT;
BEGIN
  IF v_role NOT IN ('admin','operation_manager','data_entry','cs') THEN RAISE EXCEPTION 'Access denied'; END IF;
  v_total := json_array_length(p_rows);
  v_date  := TO_CHAR(NOW(),'MMDD');
  -- Insert batch record
  INSERT INTO public.be_bulk_upload_batches(batch_id,original_filename,total_rows,valid_rows,invalid_rows,status,uploaded_by,uploaded_at)
  VALUES(v_batch_id,p_filename,v_total,0,0,'PROCESSING',v_uid,NOW());
  -- Process each row
  FOR i IN 0..v_total-1 LOOP
    v_row := p_rows->i;
    v_validation := public.be_validate_bulk_row(v_row);
    IF (v_validation->>'valid')::BOOLEAN THEN
      v_code := UPPER(SUBSTRING(v_row->>'merchant_code',1,3));
      SELECT COALESCE(MAX((split_part(pickup_id,'-',3))::INT),0)+1 INTO v_seq
      FROM public.be_portal_pickup_requests WHERE pickup_id LIKE 'P'||v_date||'-'||v_code||'-%';
      INSERT INTO public.be_portal_pickup_requests(
        pickup_id,deliver_id,invoice_no,waybill_no,
        merchant_code,merchant_name,
        recipient_name,recipient_phone,delivery_township,delivery_address,
        service_tier,priority,payment_method,cod_amount,weight_kg,
        status,batch_id,created_by,created_at,updated_at
      )
      SELECT 'P'||v_date||'-'||v_code||'-'||LPAD(v_seq::TEXT,3,'0'),
             'D'||v_date||'-'||v_code||'-'||LPAD((v_seq+1)::TEXT,3,'0'),
             'I'||v_date||'-'||v_code||'-'||LPAD(v_seq::TEXT,3,'0'),
             'W'||v_date||'-'||v_code||'-'||LPAD(v_seq::TEXT,3,'0'),
             v_row->>'merchant_code', m.merchant_name,
             v_row->>'recipient_name', v_row->>'recipient_phone',
             COALESCE(v_row->>'delivery_township',''), COALESCE(v_row->>'delivery_address',''),
             COALESCE(v_row->>'service_tier','Standard'),
             COALESCE(v_row->>'priority','NORMAL'),
             COALESCE(v_row->>'payment_method','COD'),
             COALESCE((v_row->>'cod_amount')::NUMERIC,0),
             COALESCE((v_row->>'weight_kg')::NUMERIC,0),
             'SUBMITTED',v_batch_id,v_uid,NOW(),NOW()
      FROM public.be_masterdata_merchants m WHERE m.merchant_code=v_row->>'merchant_code' LIMIT 1;
      v_valid := v_valid + 1;
    ELSE
      v_invalid := v_invalid + 1;
    END IF;
  END LOOP;
  UPDATE public.be_bulk_upload_batches SET valid_rows=v_valid,invalid_rows=v_invalid,status=CASE WHEN v_invalid=0 THEN 'COMPLETED' ELSE 'COMPLETED_WITH_ERRORS' END, uploaded_at=NOW() WHERE batch_id=v_batch_id;
  RETURN json_build_object('success',true,'batch_id',v_batch_id,'total',v_total,'valid',v_valid,'invalid',v_invalid);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_bulk_upload_history(p_limit integer DEFAULT 20)
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
DECLARE v_role TEXT := public.be_current_user_role(); v_uid UUID := auth.uid();
BEGIN
  IF v_role NOT IN ('admin','operation_manager','data_entry','cs') THEN RAISE EXCEPTION 'Access denied'; END IF;
  RETURN (SELECT COALESCE(json_agg(row_to_json(t) ORDER BY t.uploaded_at DESC),'[]'::json) FROM (
    SELECT batch_id, original_filename, total_rows, valid_rows, invalid_rows,
           status, error_summary, uploaded_by, uploaded_at
    FROM public.be_bulk_upload_batches
    WHERE uploaded_by = v_uid
    ORDER BY uploaded_at DESC LIMIT p_limit
  ) t);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_calculate_delivery_charge(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_weight numeric := greatest(public.be_jsonb_num(p_payload, array['weight_kg','actual_weight_kg','actual_weight','declared_weight','chargeable_weight','weight'], 0), 0);
  v_parcels numeric := greatest(public.be_jsonb_num(p_payload, array['parcel_count','qty','quantity','pieces','no_of_parcels'], 1), 1);
  v_distance numeric := greatest(public.be_jsonb_num(p_payload, array['distance_km','km','route_km'], 0), 0);
  v_cod numeric := greatest(public.be_jsonb_num(p_payload, array['cod_amount','cod','actual_collect','collect_amount'], 0), 0);
  v_service text := upper(public.be_jsonb_text(p_payload, array['service_type','service','delivery_type','shipment_type'], 'STANDARD'));
  v_branch text := upper(public.be_jsonb_text(p_payload, array['branch_code','origin_branch','warehouse_code'], 'HQ'));
  v_merchant text := public.be_jsonb_text(p_payload, array['merchant_code','merchant_id','merchant'], '');
  v_pickup text := public.be_jsonb_text(p_payload, array['pickup_id','canonical_pickup_id'], '');
  v_way text := public.be_jsonb_text(p_payload, array['way_id','tracking_no','waybill_no'], '');
  v_base numeric := 1000;
  v_per_kg numeric := 500;
  v_per_km numeric := 0;
  v_per_parcel numeric := 0;
  v_cod_rate numeric := 0.01;
  v_min numeric := 0;
  v_max numeric := null;
  v_surcharge numeric := 0;
  v_currency text := 'MMK';
  v_source text := 'default_formula';
  v_row jsonb;
  v_row_service text;
  v_row_branch text;
  v_base_charge numeric;
  v_weight_charge numeric;
  v_distance_charge numeric;
  v_parcel_charge numeric;
  v_cod_charge numeric;
  v_total numeric;
  v_result jsonb;
begin
  if to_regclass('public.be_tariff_master') is not null then
    for v_row in execute 'select to_jsonb(t) from (select * from public.be_tariff_master limit 500) t' loop
      if lower(coalesce(v_row->>'status', v_row->>'record_status', 'active')) in ('inactive','disabled','deleted','rejected') then
        continue;
      end if;

      v_row_service := upper(public.be_jsonb_text(v_row, array['service_type','service','delivery_type','shipment_type'], ''));
      if v_row_service <> '' and v_row_service <> v_service then
        continue;
      end if;

      v_row_branch := upper(public.be_jsonb_text(v_row, array['branch_code','origin_branch','warehouse_code'], ''));
      if v_row_branch <> '' and v_row_branch <> v_branch then
        continue;
      end if;

      v_base := public.be_jsonb_num(v_row, array['base_fee','base_rate','minimum_charge','base_charge','fixed_charge','flat_rate'], v_base);
      v_per_kg := public.be_jsonb_num(v_row, array['per_kg','kg_rate','rate_per_kg','weight_rate'], v_per_kg);
      v_per_km := public.be_jsonb_num(v_row, array['per_km','km_rate','rate_per_km','distance_rate'], v_per_km);
      v_per_parcel := public.be_jsonb_num(v_row, array['per_parcel','parcel_rate','piece_rate','rate_per_piece'], v_per_parcel);
      v_cod_rate := public.be_jsonb_num(v_row, array['cod_percent','cod_rate','cod_fee_percent'], v_cod_rate);
      v_min := public.be_jsonb_num(v_row, array['min_charge','minimum_charge','floor_charge'], v_min);
      v_max := nullif(public.be_jsonb_num(v_row, array['max_charge','maximum_charge','ceiling_charge'], -1), -1);
      v_surcharge := public.be_jsonb_num(v_row, array['surcharge','handling_fee','special_handling_fee'], v_surcharge);
      v_currency := public.be_jsonb_text(v_row, array['currency'], v_currency);
      v_source := 'be_tariff_master';
      exit;
    end loop;
  end if;

  if v_cod_rate > 1 then
    v_cod_rate := v_cod_rate / 100;
  end if;

  v_base_charge := v_base;
  v_weight_charge := v_weight * v_per_kg;
  v_distance_charge := v_distance * v_per_km;
  v_parcel_charge := v_parcels * v_per_parcel;
  v_cod_charge := v_cod * v_cod_rate;
  v_total := v_base_charge + v_weight_charge + v_distance_charge + v_parcel_charge + v_cod_charge + v_surcharge;

  if v_min > 0 and v_total < v_min then
    v_total := v_min;
  end if;

  if v_max is not null and v_max > 0 and v_total > v_max then
    v_total := v_max;
  end if;

  v_total := round(v_total, 0);

  v_result := jsonb_build_object(
    'ok', true,
    'source', v_source,
    'currency', v_currency,
    'service_type', v_service,
    'branch_code', v_branch,
    'merchant_code', v_merchant,
    'pickup_id', v_pickup,
    'way_id', v_way,
    'weight_kg', v_weight,
    'parcel_count', v_parcels,
    'distance_km', v_distance,
    'cod_amount', v_cod,
    'base_charge', v_base_charge,
    'weight_charge', round(v_weight_charge, 0),
    'distance_charge', round(v_distance_charge, 0),
    'parcel_charge', round(v_parcel_charge, 0),
    'cod_charge', round(v_cod_charge, 0),
    'surcharge', round(v_surcharge, 0),
    'total_charge', v_total
  );

  insert into public.be_delivery_charge_calculation_events (
    pickup_id, way_id, merchant_code, branch_code, service_type,
    weight_kg, parcel_count, distance_km, cod_amount,
    base_charge, weight_charge, distance_charge, parcel_charge, cod_charge,
    total_charge, currency, source, payload, result, created_at
  ) values (
    v_pickup, v_way, v_merchant, v_branch, v_service,
    v_weight, v_parcels, v_distance, v_cod,
    v_base_charge, round(v_weight_charge, 0), round(v_distance_charge, 0), round(v_parcel_charge, 0), round(v_cod_charge, 0),
    v_total, v_currency, v_source, p_payload, v_result, now()
  );

  return v_result;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_calculate_delivery_charge(p_tier text, p_weight_kg numeric, p_highway_dropoff boolean DEFAULT false)
 RETURNS json
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  v_tier TEXT := COALESCE(p_tier, 'Standard');
  v_allowance INT := CASE WHEN v_tier = 'Royal' THEN 5 ELSE 3 END;
  v_chargeable INT := CEIL(GREATEST(0, COALESCE(p_weight_kg, 0)));
  v_extra INT := GREATEST(0, v_chargeable - v_allowance);
  v_surcharge NUMERIC := v_extra * 500;
  v_highway_fee NUMERIC := CASE WHEN COALESCE(p_highway_dropoff, FALSE) THEN 3000 ELSE 0 END;
  v_base_fee NUMERIC;
BEGIN
  SELECT base_fee_mmk INTO v_base_fee FROM public.be_tariff_master WHERE tier_name = v_tier;
  IF v_base_fee IS NULL THEN v_base_fee := 4000; END IF;

  RETURN json_build_object(
    'tier', v_tier, 'allowance_kg', v_allowance, 'actual_weight_kg', COALESCE(p_weight_kg, 0),
    'chargeable_weight_kg', v_chargeable, 'extra_weight_kg', v_extra, 'base_fee', v_base_fee,
    'weight_surcharge', v_surcharge, 'highway_fee', v_highway_fee, 'total_tariff', v_base_fee + v_surcharge + v_highway_fee
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_clean_merchant_code3(p_merchant_code text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v text;
begin
  v := upper(regexp_replace(coalesce(p_merchant_code, 'GEN'), '[^A-Za-z0-9]', '', 'g'));
  v := left(v || 'GEN', 3);
  return v;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_clean_text(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$ select public.be30_clean(p); $function$
;

CREATE OR REPLACE FUNCTION public.be_cod_handover_submit(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare rider text := public.be30_clean(coalesce(p_payload->>'rider_code',p_payload->>'worker_code')); merchant text := public.be30_clean(p_payload->>'merchant_code'); total numeric := coalesce(nullif(regexp_replace(coalesce(p_payload->>'total_cash_received','0'),'[^0-9.]','','g'),'')::numeric,0); ref text;
begin
  if rider is null then raise exception 'rider_code required'; end if;
  ref := 'RH'||to_char(current_date,'MMDD')||'-'||rider||'-'||coalesce(merchant,'GEN')||'-'||lpad((1+coalesce((select max(right(settlement_ref,3)::int) from public.be_rider_handover_ledger where settlement_ref like 'RH'||to_char(current_date,'MMDD')||'-'||rider||'-'||coalesce(merchant,'GEN')||'-___'),0))::text,3,'0');
  insert into public.be_rider_handover_ledger(settlement_ref,rider_code,route_zone,merchant_code,total_delivered_parcels,total_cod_expected,total_cash_received,status,notes,payload,created_at,updated_at)
  values(ref,rider,p_payload->>'route_zone',merchant,coalesce(nullif(p_payload->>'total_delivered_parcels','')::int,0),coalesce(nullif(regexp_replace(coalesce(p_payload->>'total_cod_expected','0'),'[^0-9.]','','g'),'')::numeric,total),total,'submitted',p_payload->>'notes',p_payload,now(),now());
  update public.be_cod_ledger set status='submitted',settlement_ref=ref,cod_handed_over=case when total>0 then total else cod_handed_over end,updated_at=now() where rider_code=rider and status in ('awaiting_handover','collected');
  return jsonb_build_object('ok',true,'settlement_ref',ref,'status','submitted');
end; $function$
;

CREATE OR REPLACE FUNCTION public.be_cod_mark_collected(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_way text := nullif(coalesce(p_payload ->> 'delivery_way_id', p_payload ->> 'way_id'), '');
  v_amt numeric := coalesce(public.be_gl_num(coalesce(p_payload ->> 'amount', p_payload ->> 'collected_amount'), 0), 0);
  v_id uuid;
begin
  update public.be_cod_ledger
  set collected_amount = case when v_amt > 0 then v_amt else cod_amount end,
      variance_amount = (case when v_amt > 0 then v_amt else cod_amount end) - cod_amount,
      cod_status = 'collected',
      collected_at = now(),
      rider_id = coalesce(nullif(p_payload ->> 'rider_id', ''), rider_id),
      rider_name = coalesce(nullif(p_payload ->> 'rider_name', ''), rider_name),
      payload = coalesce(payload, '{}'::jsonb) || p_payload,
      updated_at = now()
  where delivery_way_id = v_way
  returning cod_id into v_id;

  if v_id is null then
    raise exception 'COD ledger row not found for %', v_way;
  end if;

  return jsonb_build_object('ok', true, 'cod_id', v_id, 'status', 'collected');
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_cod_mark_handover(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_way text := nullif(coalesce(p_payload ->> 'delivery_way_id', p_payload ->> 'way_id'), '');
  v_amt numeric := coalesce(public.be_gl_num(coalesce(p_payload ->> 'amount', p_payload ->> 'handover_amount'), 0), 0);
  v_id uuid;
  v_set text;
begin
  update public.be_cod_ledger
  set handover_amount = case when v_amt > 0 then v_amt else coalesce(nullif(collected_amount, 0), cod_amount) end,
      variance_amount = (case when v_amt > 0 then v_amt else coalesce(nullif(collected_amount, 0), cod_amount) end) - cod_amount,
      cod_status = 'handed_over_to_finance',
      handed_over_at = now(),
      received_by = coalesce(nullif(p_payload ->> 'received_by', ''), received_by),
      received_by_name = coalesce(nullif(p_payload ->> 'received_by_name', ''), received_by_name),
      payload = coalesce(payload, '{}'::jsonb) || p_payload,
      updated_at = now()
  where delivery_way_id = v_way
  returning cod_id, settlement_id into v_id, v_set;

  if v_id is null then
    raise exception 'COD ledger row not found for %', v_way;
  end if;

  update public.be_financial_settlements
  set handover_amount = (
        select handover_amount
        from public.be_cod_ledger
        where cod_id = v_id
      ),
      variance_amount = (
        select variance_amount
        from public.be_cod_ledger
        where cod_id = v_id
      ),
      settlement_status = 'handed_over_to_finance',
      payload = coalesce(payload, '{}'::jsonb) || p_payload,
      updated_at = now()
  where settlement_id = v_set
     or delivery_way_id = v_way;

  return jsonb_build_object('ok', true, 'cod_id', v_id, 'settlement_id', v_set, 'status', 'handed_over_to_finance');
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_cod_settlement_snapshot(p_status text DEFAULT NULL::text, p_limit integer DEFAULT 200)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
AS $function$
  select jsonb_build_object('rows', coalesce(jsonb_agg(row_to_json(x)::jsonb order by x.updated_at desc), '[]'::jsonb), 'synced_at', now()) from (select * from public.be_cod_ledger where p_status is null or cod_status=p_status order by updated_at desc limit least(greatest(coalesce(p_limit,200),1),500)) x;
$function$
;

CREATE OR REPLACE FUNCTION public.be_column_exists(p_table text, p_column text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = p_table
      and column_name = p_column
  );
$function$
;

CREATE OR REPLACE FUNCTION public.be_commission_center(p_limit integer DEFAULT 300)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_sync jsonb;
  v_rules jsonb;
  v_wallets jsonb;
  v_summary jsonb;
begin
  v_sync := public.be_sync_workforce_wallets();

  select coalesce(jsonb_agg(to_jsonb(r) order by r.role, r.rule_id), '[]'::jsonb)
  into v_rules
  from public.be_commission_rules r
  where r.is_active = true;

  select coalesce(jsonb_agg(to_jsonb(w) order by w.created_at desc), '[]'::jsonb)
  into v_wallets
  from (
    select *
    from public.be_workforce_wallets
    where delivery_way_id is not null
      and worker_code is not null
      and worker_code <> 'UNKNOWN'
      and amount > 0
    order by created_at desc
    limit greatest(coalesce(p_limit, 300), 1)
  ) w;

  select jsonb_build_object(
    'active_rules', count(*) filter (where is_active = true),
    'total_commission_pending', coalesce((
      select sum(amount)
      from public.be_workforce_wallets
      where wallet_status = 'PENDING'
        and delivery_way_id is not null
        and worker_code is not null
        and worker_code <> 'UNKNOWN'
        and amount > 0
    ), 0),
    'total_commission_paid', coalesce((
      select sum(amount)
      from public.be_workforce_wallets
      where wallet_status = 'PAID'
        and delivery_way_id is not null
        and worker_code is not null
        and worker_code <> 'UNKNOWN'
        and amount > 0
    ), 0),
    'wallet_records', coalesce((
      select count(*)
      from public.be_workforce_wallets
      where delivery_way_id is not null
        and worker_code is not null
        and worker_code <> 'UNKNOWN'
        and amount > 0
    ), 0)
  )
  into v_summary
  from public.be_commission_rules;

  return jsonb_build_object(
    'ok', true,
    'source', 'be_commission_center',
    'count', jsonb_array_length(v_rules),
    'summary', v_summary,
    'sync', v_sync,
    'rules', v_rules,
    'wallets', v_wallets
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_commission_get_rate(p_operation_type text, p_role_code text, p_unit_type text, p_work_date date DEFAULT CURRENT_DATE)
 RETURNS numeric
 LANGUAGE sql
 STABLE
AS $function$
  select coalesce((
    select r.rate_mmk
    from public.be_commission_rate_master r
    where r.active
      and r.operation_type = upper(trim(p_operation_type))
      and r.role_code = upper(trim(p_role_code))
      and r.unit_type = upper(trim(p_unit_type))
      and r.effective_from <= coalesce(p_work_date, current_date)
      and (r.effective_to is null or r.effective_to >= coalesce(p_work_date, current_date))
    order by r.effective_from desc, r.updated_at desc
    limit 1
  ), 0);
$function$
;

CREATE OR REPLACE FUNCTION public.be_commission_settlement_snapshot(p_work_date date DEFAULT CURRENT_DATE, p_actor_email text DEFAULT NULL::text, p_rebuild boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_work_date date := coalesce(p_work_date, current_date);
  v_rebuild jsonb := null;
  v_rates jsonb;
  v_rows jsonb;
  v_stats jsonb;
begin
  if coalesce(p_rebuild, true) then
    v_rebuild := public.be_rebuild_auto_commission_events(v_work_date, p_actor_email);
  end if;

  select coalesce(jsonb_agg(to_jsonb(r) order by r.operation_type, r.role_code), '[]'::jsonb)
  into v_rates
  from (
    select operation_type, role_code, unit_type, rate_mmk
    from public.be_commission_rate_master
    where active
      and effective_from <= v_work_date
      and (effective_to is null or effective_to >= v_work_date)
    order by operation_type, role_code, unit_type
  ) r;

  select coalesce(jsonb_agg(to_jsonb(s) order by s.role_code, s.assignee_email, s.operation_type), '[]'::jsonb)
  into v_rows
  from public.be_v_commission_settlement s
  where s.work_date = v_work_date;

  select jsonb_build_object(
    'work_date', v_work_date,
    'pickup_commission', coalesce(sum(commission_mmk) filter (where operation_type = 'PICKUP'),0),
    'delivery_commission', coalesce(sum(commission_mmk) filter (where operation_type = 'DELIVERY'),0),
    'highway_dropoff_commission', coalesce(sum(commission_mmk) filter (where operation_type = 'HIGHWAY_DROPOFF'),0),
    'rider_commission', coalesce(sum(commission_mmk) filter (where role_code = 'RIDER'),0),
    'driver_commission', coalesce(sum(commission_mmk) filter (where role_code = 'DRIVER'),0),
    'helper_commission', coalesce(sum(commission_mmk) filter (where role_code = 'HELPER'),0),
    'total_commission', coalesce(sum(commission_mmk),0),
    'event_rows', coalesce(sum(event_rows),0)
  )
  into v_stats
  from public.be_v_commission_settlement
  where work_date = v_work_date;

  return jsonb_build_object(
    'ok', true,
    'rebuild', v_rebuild,
    'rates', v_rates,
    'stats', v_stats,
    'rows', v_rows
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_confirm_pickup_dispatch(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ select public.be_supervisor_assign_job(p_payload); $function$
;

CREATE OR REPLACE FUNCTION public.be_create_delivery(p_payload json)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_role TEXT := public.be_current_user_role();
  v_user_id UUID := auth.uid();
  v_pickup_id TEXT; v_deliver_id TEXT; v_invoice_no TEXT; v_waybill_no TEXT;
  v_date TEXT := TO_CHAR(NOW(),'MMDD');
  v_code TEXT; v_count INT; v_new_id UUID;
  v_tariff JSON;
  v_branch TEXT;
BEGIN
  IF v_role NOT IN ('admin','operation_manager','cs','data_entry') THEN RAISE EXCEPTION 'Access denied'; END IF;
  -- Validate required fields
  IF p_payload->>'merchant_code' IS NULL OR p_payload->>'recipient_phone' IS NULL THEN
    RAISE EXCEPTION 'merchant_code and recipient_phone are required';
  END IF;
  -- Phone format check
  IF NOT ((p_payload->>'recipient_phone') ~ '^(09|\+959)[0-9]{7,9}$') THEN
    RAISE EXCEPTION 'Invalid phone format: %', p_payload->>'recipient_phone';
  END IF;
  -- Generate IDs
  v_code := UPPER(SUBSTRING(p_payload->>'merchant_code',1,3));
  SELECT COALESCE(MAX((split_part(pickup_id,'-',3))::INT),0)+1 INTO v_count
  FROM public.be_portal_pickup_requests
  WHERE pickup_id LIKE 'P'||v_date||'-'||v_code||'-%';
  v_pickup_id  := 'P'||v_date||'-'||v_code||'-'||LPAD(v_count::TEXT,3,'0');
  v_deliver_id := 'D'||v_date||'-'||v_code||'-'||LPAD((v_count+1)::TEXT,3,'0');
  v_invoice_no := 'I'||v_date||'-'||v_code||'-'||LPAD(v_count::TEXT,3,'0');
  v_waybill_no := 'W'||v_date||'-'||v_code||'-'||LPAD(v_count::TEXT,3,'0');
  -- Branch resolution
  v_branch := CASE
    WHEN lower(p_payload->>'pickup_city') LIKE '%mandalay%' OR lower(p_payload->>'pickup_city') LIKE '%mdy%' THEN 'MDY'
    WHEN lower(p_payload->>'pickup_city') LIKE '%naypyi%' OR lower(p_payload->>'pickup_city') LIKE '%npt%' THEN 'NPT'
    ELSE 'YGN'
  END;
  -- Tariff calculation
  v_tariff := public.be_calculate_tariff(
    COALESCE(p_payload->>'service_tier','Standard'),
    COALESCE((p_payload->>'weight_kg')::NUMERIC, 0),
    COALESCE((p_payload->>'highway_dropoff')::BOOLEAN, FALSE)
  );
  -- Insert record
  INSERT INTO public.be_portal_pickup_requests (
    pickup_id, deliver_id, invoice_no, waybill_no,
    merchant_id, merchant_code, merchant_name,
    sender_phone, pickup_address, pickup_township, pickup_city,
    recipient_name, recipient_phone, delivery_township, delivery_address,
    service_tier, priority, payment_method, cod_amount,
    weight_kg, delivery_fee, status, branch_code,
    requester_type, created_by, created_at, updated_at
  ) VALUES (
    v_pickup_id, v_deliver_id, v_invoice_no, v_waybill_no,
    p_payload->>'merchant_id', p_payload->>'merchant_code', p_payload->>'merchant_name',
    p_payload->>'sender_phone', p_payload->>'pickup_address', p_payload->>'pickup_township', p_payload->>'pickup_city',
    p_payload->>'recipient_name', p_payload->>'recipient_phone', p_payload->>'delivery_township', p_payload->>'delivery_address',
    COALESCE(p_payload->>'service_tier','Standard'),
    COALESCE(p_payload->>'priority','NORMAL'),
    COALESCE(p_payload->>'payment_method','COD'),
    COALESCE((p_payload->>'cod_amount')::NUMERIC, 0),
    COALESCE((p_payload->>'weight_kg')::NUMERIC, 0),
    (v_tariff->>'total')::NUMERIC,
    'SUBMITTED', v_branch, 'PORTAL', v_user_id, NOW(), NOW()
  ) RETURNING id INTO v_new_id;
  -- Create initial cargo event
  INSERT INTO public.be_portal_cargo_events (pickup_id, event_type, description, actor_role, created_at)
  VALUES (v_pickup_id, 'SUBMITTED', 'Shipment created via Portal', v_role, NOW());
  RETURN json_build_object(
    'success', true, 'pickup_id', v_pickup_id, 'deliver_id', v_deliver_id,
    'invoice_no', v_invoice_no, 'waybill_no', v_waybill_no,
    'branch', v_branch, 'tariff', v_tariff, 'id', v_new_id
  );
END;
$function$
;

