CREATE OR REPLACE FUNCTION public.be_create_pickup_request_from_master(p_merchant_code text, p_expected_parcels integer, p_pickup_date text, p_vehicle_required text, p_payment_type text, p_actor_email text, p_pickup_address_override text, p_township_override text, p_city_override text, p_region_state_override text, p_pickup_remark text, p_duplicate_confirmed boolean)
 RETURNS json
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_pickup_id text;
BEGIN
    -- Generate Canonical ID based on BRITIUM_OPERATIONAL_ID_RULES
    v_pickup_id := public.generate_britium_pickup_id(p_merchant_code, p_expected_parcels);

    -- Insert record
    INSERT INTO public.be_portal_pickup_requests (
        pickup_id,
        merchant_code,
        status,
        pickup_status,
        pickup_address,
        pickup_township,
        pickup_city,
        expected_parcels,    -- Mapped successfully now that the column exists
        created_at
    ) VALUES (
        v_pickup_id,
        p_merchant_code,
        'PICKUP_REQUESTED',
        'Draft',
        COALESCE(p_pickup_address_override, 'Address not provided'),
        p_township_override,
        p_city_override,
        p_expected_parcels,
        now()
    );

    RETURN json_build_object('pickup_id', v_pickup_id, 'requires_confirmation', false);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_create_pickup_request_from_portal(p_merchant_code text, p_merchant_name text, p_pickup_address text, p_pickup_township text, p_expected_parcels integer, p_expected_weight_kg numeric, p_payment_method text, p_transport_mode text, p_note text, p_branch_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_date text := to_char(now() at time zone 'Asia/Yangon', 'MMDD');
  v_code text := regexp_replace(upper(coalesce(nullif(trim(p_merchant_code), ''), 'GEN')), '[^A-Z0-9]', '', 'g');
  v_count integer := greatest(coalesce(p_expected_parcels, 1), 1);
  v_count_suffix text := lpad(v_count::text, 3, '0');

  v_pickup_way_id text;
  v_delivery_id text;
  v_parent_id uuid := gen_random_uuid();

  v_m public.be_master_merchants%rowtype;

  v_payload jsonb;
  v_cols text;
  v_vals text;

  i integer;
begin
  select *
  into v_m
  from public.be_master_merchants
  where merchant_code = upper(trim(p_merchant_code))
  limit 1;

  if v_m.merchant_code is null then
    raise exception 'Merchant code % not found in master data', p_merchant_code;
  end if;

  v_pickup_way_id := 'P' || v_date || '-' || v_code || '-' || v_count_suffix;

  if exists (
    select 1
    from public.be_portal_pickup_requests
    where pickup_id = v_pickup_way_id
       or pickup_way_id = v_pickup_way_id
  ) then
    raise exception 'PickupWayID % already exists. Delete duplicate test row or use a different parcel count.', v_pickup_way_id;
  end if;

  alter table public.be_portal_pickup_requests
    add column if not exists pickup_way_id text;

  alter table public.be_portal_pickup_requests
    add column if not exists tracking_no text;

  alter table public.be_portal_pickup_requests
    add column if not exists expected_parcels integer default 1;

  alter table public.be_portal_pickup_requests
    add column if not exists delivery_count integer;

  alter table public.be_portal_pickup_requests
    add column if not exists updated_at timestamptz default now();

  alter table public.be_portal_pickup_request_items
    add column if not exists pickup_way_id text;

  alter table public.be_portal_pickup_request_items
    add column if not exists delivery_way_id text;

  alter table public.be_portal_pickup_request_items
    add column if not exists tracking_no text;

  alter table public.be_portal_pickup_request_items
    add column if not exists merchant_code text;

  alter table public.be_portal_pickup_request_items
    add column if not exists merchant_name text;

  alter table public.be_portal_pickup_request_items
    add column if not exists delivery_sequence integer;

  alter table public.be_portal_pickup_request_items
    add column if not exists delivery_count integer;

  alter table public.be_portal_pickup_request_items
    add column if not exists delivery_status text default 'WAITING_ASSIGNMENT';

  alter table public.be_portal_pickup_request_items
    add column if not exists updated_at timestamptz default now();

  v_payload := jsonb_build_object(
    'id', v_parent_id,
    'pickup_request_id', v_parent_id::text,

    'pickup_id', v_pickup_way_id,
    'pickup_way_id', v_pickup_way_id,
    'tracking_no', v_pickup_way_id,

    'merchant_code', v_m.merchant_code,
    'merchant_name', coalesce(nullif(p_merchant_name, ''), v_m.merchant_name),
    'business_type', v_m.business_type,
    'contact_person', v_m.contact_person,
    'phone_primary', v_m.phone_primary,

    'pickup_address', coalesce(nullif(p_pickup_address, ''), v_m.address_line_1, v_m.address_mm),
    'pickup_township', coalesce(nullif(p_pickup_township, ''), v_m.township),
    'branch_code', coalesce(nullif(p_branch_code, ''), 'YGN'),

    'expected_parcels', v_count,
    'delivery_count', v_count,
    'total_weight_kg', coalesce(p_expected_weight_kg, 0),

    'payment_method', coalesce(nullif(p_payment_method, ''), 'COD'),
    'transport_mode', coalesce(nullif(p_transport_mode, ''), 'Bike'),

    'pickup_status', 'WAITING_ASSIGNMENT',
    'rider_status', 'WAITING_ASSIGNMENT',
    'workflow_stage', 'PICKUP_REQUESTED',

    'request_note', p_note,
    'note', p_note,

    'created_at', now(),
    'updated_at', now()
  );

  select
    string_agg(quote_ident(e.key), ', '),
    string_agg(quote_literal(e.value), ', ')
  into v_cols, v_vals
  from jsonb_each_text(v_payload) e
  where exists (
    select 1
    from information_schema.columns c
    where c.table_schema = 'public'
      and c.table_name = 'be_portal_pickup_requests'
      and c.column_name = e.key
  );

  execute format(
    'insert into public.be_portal_pickup_requests (%s) values (%s)',
    v_cols,
    v_vals
  );

  for i in 1..v_count loop
    v_delivery_id := 'D' || v_date || '-' || v_code || '-' || lpad(i::text, 3, '0');

    insert into public.be_portal_pickup_request_items (
      pickup_request_id,
      pickup_id,
      item_no,
      pickup_way_id,
      delivery_way_id,
      tracking_no,
      merchant_code,
      merchant_name,
      delivery_sequence,
      delivery_count,
      delivery_status,
      created_at,
      updated_at
    )
    values (
      v_parent_id,
      v_pickup_way_id,
      i,
      v_pickup_way_id,
      v_delivery_id,
      v_delivery_id,
      v_m.merchant_code,
      v_m.merchant_name,
      i,
      v_count,
      'WAITING_ASSIGNMENT',
      now(),
      now()
    );
  end loop;

  return jsonb_build_object(
    'ok', true,
    'pickup_id', v_pickup_way_id,
    'pickup_way_id', v_pickup_way_id,
    'tracking_no', v_pickup_way_id,
    'pickup_request_id', v_parent_id,
    'merchant_code', v_m.merchant_code,
    'merchant_name', v_m.merchant_name,
    'expected_parcels', v_count,
    'delivery_count', v_count,
    'delivery_way_ids',
      (
        select jsonb_agg('D' || v_date || '-' || v_code || '-' || lpad(x::text, 3, '0'))
        from generate_series(1, v_count) x
      ),
    'pickup_status', 'WAITING_ASSIGNMENT',
    'workflow_stage', 'PICKUP_REQUESTED'
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_create_pickup_submission_notifications(p_pickup_id text, p_source text DEFAULT 'portal'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_pickup record;
  v_pickup_id text := trim(coalesce(p_pickup_id, ''));
  v_branch text;
  v_cod numeric;
  v_role text;
  v_roles text[];
BEGIN
  IF v_pickup_id = '' THEN
    RAISE EXCEPTION 'pickup_id is required';
  END IF;

  SELECT *
  INTO v_pickup
  FROM public.be_portal_pickup_requests p
  WHERE upper(coalesce(p.pickup_id, p.canonical_pickup_id, p.pickup_way_id, p.waybill_no, p.be_sync_uuid::text)) = upper(v_pickup_id)
  LIMIT 1;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Pickup % not found in be_portal_pickup_requests', v_pickup_id;
  END IF;

  v_branch := coalesce(v_pickup.branch_code, 'YGN');
  v_cod := coalesce(v_pickup.cod_amount, v_pickup.rider_cod_amount, v_pickup.item_price, 0);

  INSERT INTO public.be_portal_cargo_events (
    pickup_id,
    source_table,
    source_key,
    event_type,
    event_status,
    event_note,
    actor_type,
    actor_code,
    branch_code,
    metadata
  )
  VALUES (
    v_pickup_id,
    'be_portal_pickup_requests',
    v_pickup_id,
    'PICKUP_REQUESTED',
    'PICKUP_REQUESTED',
    'Pickup request submitted into canonical backend workflow',
    p_source,
    p_source,
    v_branch,
    jsonb_build_object('source', p_source)
  );

  v_roles := ARRAY['customer_service', 'operations_supervisor', 'operation_manager', 'dispatch'];

  IF v_branch IN ('MDY', 'NPT') THEN
    v_roles := array_append(v_roles, 'branch_office');
  END IF;

  IF v_cod > 0 THEN
    v_roles := array_append(v_roles, 'finance');
  END IF;

  FOREACH v_role IN ARRAY v_roles LOOP
    INSERT INTO public.be_app_notifications (
      notification_type,
      title,
      body,
      source_table,
      source_key,
      pickup_id,
      target_role,
      target_branch,
      is_read,
      metadata
    )
    VALUES (
      'PICKUP_REQUESTED',
      'New pickup request',
      'Pickup ' || v_pickup_id || ' requires workflow action.',
      'be_portal_pickup_requests',
      v_pickup_id,
      v_pickup_id,
      v_role,
      CASE WHEN v_role = 'branch_office' THEN v_branch ELSE NULL END,
      false,
      jsonb_build_object('pickup_id', v_pickup_id, 'branch_code', v_branch, 'source', p_source)
    );
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'pickup_id', v_pickup_id,
    'branch_code', v_branch,
    'notified_roles', v_roles
  );
END;
$function$
;

