 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select public.be_submit_pickup_request(p_payload);
$function$
;

CREATE OR REPLACE FUNCTION public.be_current_actor_context(p_actor_email text DEFAULT NULL::text, p_actor_role text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_email text := lower(coalesce(
    nullif(p_actor_email, ''),
    nullif(auth.email(), ''),
    ''
  ));
  v_role text := lower(coalesce(nullif(p_actor_role, ''), ''));
  v_is_admin boolean := false;
begin
  if v_role in ('admin', 'superadmin') then
    v_is_admin := true;
  end if;

  if v_email like '%superadmin%'
     or v_email like '%admin%'
     or v_email like '%mgkyawwanna%'
     or v_email like '%kyawwanna%' then
    v_is_admin := true;
    if v_role = '' then
      v_role := 'superadmin';
    end if;
  end if;

  if v_role = '' then
    if v_email like '%finance%' then
      v_role := 'finance';
    elsif v_email like '%branch%' then
      v_role := 'branch';
    elsif v_email like '%rider%' then
      v_role := 'rider';
    elsif v_email = '' then
      v_role := 'guest';
    else
      v_role := 'operation';
    end if;
  end if;

  return jsonb_build_object(
    'email', v_email,
    'role', v_role,
    'is_admin', v_is_admin
  );
end;
$function$
;

