  );
$function$
;

CREATE OR REPLACE FUNCTION public.be_dashboard_kpi_today()
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
DECLARE
  v_role TEXT := public.be_current_user_role();
  v_branch TEXT;
  v_today DATE := CURRENT_DATE;
  v_res JSON;
BEGIN
  IF v_role NOT IN ('admin','operation_manager','supervisor','finance','cs','dispatch','warehouse') THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  SELECT branch_code INTO v_branch
  FROM public.be_user_account_registry WHERE auth_user_id = auth.uid() LIMIT 1;

  SELECT json_build_object(
    'total_pickups_today',     (SELECT count(*) FROM public.be_portal_pickup_requests WHERE created_at::date = v_today AND (v_branch IS NULL OR branch_code = v_branch OR v_role IN ('admin','operation_manager'))),
    'pending_pickups',         (SELECT count(*) FROM public.be_portal_pickup_requests WHERE status IN ('SUBMITTED','PENDING_ASSIGNMENT') AND (v_branch IS NULL OR branch_code = v_branch OR v_role IN ('admin','operation_manager'))),
    'active_shipments',        (SELECT count(*) FROM public.be_portal_pickup_requests WHERE status IN ('PICKED_UP','IN_WAREHOUSE','SORTING','BAGGED','DISPATCHED','OUT_FOR_DELIVERY') AND (v_branch IS NULL OR branch_code = v_branch OR v_role IN ('admin','operation_manager'))),
    'delivered_today',         (SELECT count(*) FROM public.be_portal_pickup_requests WHERE status = 'DELIVERED' AND updated_at::date = v_today AND (v_branch IS NULL OR branch_code = v_branch OR v_role IN ('admin','operation_manager'))),
    'failed_today',            (SELECT count(*) FROM public.be_portal_pickup_requests WHERE status = 'FAILED_ATTEMPT' AND updated_at::date = v_today AND (v_branch IS NULL OR branch_code = v_branch OR v_role IN ('admin','operation_manager'))),
    'returned_today',          (SELECT count(*) FROM public.be_portal_pickup_requests WHERE status = 'RETURNED' AND updated_at::date = v_today AND (v_branch IS NULL OR branch_code = v_branch OR v_role IN ('admin','operation_manager'))),
    'pending_cod',             (SELECT COALESCE(SUM(cod_amount),0) FROM public.be_portal_pickup_requests WHERE status = 'DELIVERED' AND payment_method = 'COD' AND cod_settled = false AND (v_branch IS NULL OR branch_code = v_branch OR v_role IN ('admin','operation_manager'))),
    'active_riders',           (SELECT count(*) FROM public.be_mobile_workforce_accounts WHERE role_type = 'rider' AND status = 'active'),
    'exceptions_open',         (SELECT count(*) FROM public.be_portal_pickup_requests WHERE status IN ('EXCEPTION','ON_HOLD') AND (v_branch IS NULL OR branch_code = v_branch OR v_role IN ('admin','operation_manager'))),
    'as_of',                   NOW()
  ) INTO v_res;

  RETURN v_res;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_dashboard_module_throughput()
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
DECLARE
  v_role TEXT := public.be_current_user_role();
BEGIN
  IF v_role NOT IN ('admin','operation_manager','supervisor') THEN RAISE EXCEPTION 'Access denied'; END IF;
  RETURN (
    SELECT json_agg(row_to_json(t))
    FROM (
      SELECT requester_type AS source,
             count(*)::int AS total,
             SUM(CASE WHEN status='DELIVERED' THEN 1 ELSE 0 END)::int AS delivered,
             SUM(CASE WHEN status='FAILED_ATTEMPT' THEN 1 ELSE 0 END)::int AS failed
      FROM public.be_portal_pickup_requests
      WHERE created_at >= CURRENT_DATE - 29
      GROUP BY requester_type
      ORDER BY total DESC
    ) t
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_dashboard_sla_summary()
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
DECLARE v_role TEXT := public.be_current_user_role();
BEGIN
  IF v_role NOT IN ('admin','operation_manager','supervisor','finance') THEN RAISE EXCEPTION 'Access denied'; END IF;
  RETURN (
    SELECT json_build_object(
      'total_delivered_7d', count(*),
      'within_24h',  SUM(CASE WHEN EXTRACT(EPOCH FROM (updated_at - created_at))/3600 <= 24 THEN 1 ELSE 0 END)::int,
      'within_48h',  SUM(CASE WHEN EXTRACT(EPOCH FROM (updated_at - created_at))/3600 <= 48 THEN 1 ELSE 0 END)::int,
      'over_48h',    SUM(CASE WHEN EXTRACT(EPOCH FROM (updated_at - created_at))/3600 >  48 THEN 1 ELSE 0 END)::int
    )
    FROM public.be_portal_pickup_requests
    WHERE status = 'DELIVERED' AND updated_at >= CURRENT_DATE - 6
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_dashboard_trend_7d()
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
DECLARE
  v_role TEXT := public.be_current_user_role();
  v_branch TEXT;
BEGIN
  IF v_role NOT IN ('admin','operation_manager','supervisor','finance','cs','dispatch','warehouse') THEN
    RAISE EXCEPTION 'Access denied';
  END IF;
  SELECT branch_code INTO v_branch FROM public.be_user_account_registry WHERE auth_user_id = auth.uid() LIMIT 1;

  RETURN (
    SELECT json_agg(row_to_json(t) ORDER BY t.day)
    FROM (
      SELECT
        TO_CHAR(d.day,'Mon DD') AS day,
        COALESCE(SUM(CASE WHEN p.status='DELIVERED' THEN 1 ELSE 0 END),0)::int AS delivered,
        COALESCE(SUM(CASE WHEN p.status='FAILED_ATTEMPT' THEN 1 ELSE 0 END),0)::int AS failed,
        COALESCE(SUM(CASE WHEN p.status IN ('PICKED_UP','IN_WAREHOUSE','SORTING','BAGGED','DISPATCHED','OUT_FOR_DELIVERY') THEN 1 ELSE 0 END),0)::int AS active
      FROM generate_series(CURRENT_DATE - 6, CURRENT_DATE, '1 day'::interval) d(day)
      LEFT JOIN public.be_portal_pickup_requests p
        ON p.created_at::date = d.day::date
        AND (v_branch IS NULL OR p.branch_code = v_branch OR v_role IN ('admin','operation_manager'))
      GROUP BY d.day
    ) t
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_data_entry_bulk_load_parcels(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_pickup_id text;
  v_actor_email text;
  v_pickup record;
  v_pickup_json jsonb := '{}'::jsonb;
  v_doc record;
  v_rows jsonb := '[]'::jsonb;

  v_sender_name text;
  v_sender_phone text;
  v_sender_address text;
  v_recipient_name text;
  v_recipient_phone text;
  v_recipient_address text;
  v_recipient_township text;
  v_weight numeric;
  v_cod integer;
  v_tracking_code text;
begin
  v_pickup_id := nullif(coalesce(
    p_payload->>'pickup_way_id',
    p_payload->>'pickup_id',
    p_payload->>'request_code'
  ), '');

  v_actor_email := nullif(coalesce(
    p_payload->>'actor_email',
    p_payload->>'data_entry_email',
    'data.entry@britiumexpress.com'
  ), '');

  if v_pickup_id is null then
    return jsonb_build_object(
      'ok', false,
      'error', 'pickup_id / pickup_way_id is required',
      'payload', p_payload
    );
  end if;

  select *
  into v_pickup
  from public.be_portal_pickup_requests
  where pickup_way_id = v_pickup_id
     or pickup_id = v_pickup_id
     or request_code = v_pickup_id
  order by updated_at desc
  limit 1;

  if v_pickup.id is null then
    return jsonb_build_object(
      'ok', false,
      'error', 'Pickup not found',
      'pickup_id', v_pickup_id
    );
  end if;

  v_pickup_json := to_jsonb(v_pickup);

  for v_doc in
    select *
    from public.be_waybill_ledger
    where pickup_id = v_pickup_id
       or pickup_way_id = v_pickup_id
    order by parcel_sequence nulls last, delivery_way_id
  loop
    v_tracking_code := coalesce(v_doc.tracking_no, v_doc.waybill_no, v_doc.delivery_way_id);

    v_sender_name := coalesce(
      nullif(v_pickup_json->>'sender_name', ''),
      nullif(v_pickup_json->>'merchant_name', ''),
      nullif(to_jsonb(v_doc)->>'merchant_name', ''),
      'Unknown Sender'
    );

    v_sender_phone := coalesce(
      nullif(v_pickup_json->>'sender_phone', ''),
      nullif(v_pickup_json->>'merchant_phone', ''),
      nullif(v_pickup_json->>'contact_phone', ''),
      '000000000'
    );

    v_sender_address := coalesce(
      nullif(v_pickup_json->>'sender_address', ''),
      nullif(v_pickup_json->>'pickup_address', ''),
      nullif(v_pickup_json->>'merchant_address', ''),
      'Pending pickup address'
    );

    v_recipient_name := coalesce(
      nullif(to_jsonb(v_doc)->>'recipient_name', ''),
      nullif(to_jsonb(v_doc)->>'customer_name', ''),
      nullif(v_pickup_json->>'receiver_name', ''),
      nullif(v_pickup_json->>'recipient_name', ''),
      'Pending Recipient'
    );

    v_recipient_phone := coalesce(
      nullif(to_jsonb(v_doc)->>'recipient_phone', ''),
      nullif(to_jsonb(v_doc)->>'contact_no_1', ''),
      nullif(v_pickup_json->>'receiver_phone', ''),
      nullif(v_pickup_json->>'recipient_phone', ''),
      '000000000'
    );

    v_recipient_address := coalesce(
      nullif(to_jsonb(v_doc)->>'recipient_address', ''),
      nullif(to_jsonb(v_doc)->>'delivery_address', ''),
      nullif(v_pickup_json->>'delivery_address', ''),
      nullif(v_pickup_json->>'recipient_address', ''),
      'Pending delivery address'
    );

    v_recipient_township := coalesce(
      nullif(to_jsonb(v_doc)->>'township', ''),
      nullif(v_pickup_json->>'delivery_township', ''),
      nullif(v_pickup_json->>'township', '')
    );

    v_weight := coalesce(
      nullif(to_jsonb(v_doc)->>'weight_kg', '')::numeric,
      nullif(to_jsonb(v_doc)->>'parcel_weight_kg', '')::numeric,
      nullif(to_jsonb(v_doc)->>'total_weight_kg', '')::numeric,
      case
        when coalesce((v_pickup_json->>'pickup_verified_total_weight')::numeric, 0) > 0
          then (v_pickup_json->>'pickup_verified_total_weight')::numeric
               / greatest(coalesce((v_pickup_json->>'parcel_count')::integer, 1), 1)
        else 0
      end
    );

    v_cod := coalesce(
      nullif(to_jsonb(v_doc)->>'cod_amount', '')::numeric,
      nullif(v_pickup_json->>'cod_amount', '')::numeric,
      0
    )::integer;

    insert into public.parcels (
      tracking_code,
      pickup_request_id,
      enterprise_id,
      sender_name,
      sender_phone,
      sender_address,
      recipient_name,
      recipient_phone,
      recipient_address,
      recipient_township,
      weight_kg,
      parcel_type,
      cod_amount,
      declared_value,
      base_price,
      overweight_fee,
      total_price,
      status,
      notes,
      created_at,
      updated_at
    )
    values (
      v_tracking_code,
      null,
      null,
      v_sender_name,
      v_sender_phone,
      v_sender_address,
      v_recipient_name,
      v_recipient_phone,
      v_recipient_address,
      v_recipient_township,
      v_weight,
      'standard',
      v_cod,
      v_cod,
      coalesce(nullif(to_jsonb(v_doc)->>'delivery_fee', '')::numeric, 0)::integer,
      0,
      coalesce(nullif(to_jsonb(v_doc)->>'delivery_fee', '')::numeric, 0)::integer + v_cod,
      'registered',
      'Bulk loaded from Data Entry for pickup ' || v_pickup_id || ', delivery ' || coalesce(v_doc.delivery_way_id, ''),
      now(),
      now()
    )
    on conflict (tracking_code) do update
    set
      sender_name = excluded.sender_name,
      sender_phone = excluded.sender_phone,
      sender_address = excluded.sender_address,
      recipient_name = excluded.recipient_name,
      recipient_phone = excluded.recipient_phone,
      recipient_address = excluded.recipient_address,
      recipient_township = excluded.recipient_township,
      weight_kg = excluded.weight_kg,
      cod_amount = excluded.cod_amount,
      declared_value = excluded.declared_value,
      base_price = excluded.base_price,
      total_price = excluded.total_price,
      status = case
        when public.parcels.status in ('delivered', 'returned', 'cancelled')
          then public.parcels.status
        else 'registered'
      end,
      notes = excluded.notes,
      updated_at = now();

    update public.be_waybill_ledger
    set
      status = 'registered',
      data_entry_status = 'PARCEL_BULK_LOADED',
      warehouse_status = 'WAITING_WAREHOUSE_RECEIVE',
      updated_at = now(),
      payload = coalesce(payload, '{}'::jsonb) || jsonb_build_object(
        'parcel_bulk_loaded_at', now(),
        'parcel_bulk_loaded_by', v_actor_email,
        'parcels_tracking_code', v_tracking_code
      )
    where id = v_doc.id;

    v_rows := v_rows || jsonb_build_array(
      jsonb_build_object(
        'tracking_code', v_tracking_code,
        'delivery_way_id', v_doc.delivery_way_id,
        'waybill_no', v_doc.waybill_no,
        'invoice_no', v_doc.invoice_no,
        'status', 'registered'
      )
    );
  end loop;

  if jsonb_array_length(v_rows) = 0 then
    return jsonb_build_object(
      'ok', false,
      'error', 'No generated waybill ledger rows found for pickup',
      'pickup_id', v_pickup_id
    );
  end if;

  update public.be_portal_pickup_requests
  set
    data_entry_status = 'PARCEL_BULK_LOADED',
    warehouse_status = 'WAITING_WAREHOUSE_RECEIVE',
    pickup_status = 'DATA_ENTRY_REGISTERED',
    workflow_stage = 'WAITING_WAREHOUSE_RECEIVE',
    status = 'DATA_ENTRY_REGISTERED',
    metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
      'parcel_bulk_loaded_at', now(),
      'parcel_bulk_loaded_by', v_actor_email,
      'parcel_bulk_loaded_count', jsonb_array_length(v_rows),
      'parcel_bulk_loaded_rows', v_rows
    ),
    updated_at = now()
  where id = v_pickup.id;

  return jsonb_build_object(
    'ok', true,
    'source', 'be_data_entry_bulk_load_parcels',
    'pickup_id', v_pickup_id,
    'bulk_loaded_count', jsonb_array_length(v_rows),
    'inserted_or_upserted', jsonb_array_length(v_rows),
    'parcels', v_rows,
    'next_status', 'PARCEL_BULK_LOADED',
    'next_action', 'WAREHOUSE_RECEIVE'
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_data_entry_bulk_load_queue(p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with pickup_rows as (
    select
      p.pickup_way_id,
      p.pickup_id,
      p.request_code,
      p.merchant_code,
      p.merchant_name,
      p.parcel_count,
      p.expected_parcels,
      p.verified_parcels,
      p.pickup_status,
      p.workflow_stage,
      p.data_entry_status,
      p.warehouse_status,
      p.status,
      p.updated_at,
      coalesce(doc.doc_count, 0) as generated_document_count,
      coalesce(parcel.parcel_count_loaded, 0) as parcel_count_loaded
    from public.be_portal_pickup_requests p
    left join lateral (
      select count(*)::integer as doc_count
      from public.be_waybill_ledger w
      where w.pickup_id = coalesce(p.pickup_way_id, p.pickup_id, p.request_code)
         or w.pickup_way_id = coalesce(p.pickup_way_id, p.pickup_id, p.request_code)
    ) doc on true
    left join lateral (
      select count(*)::integer as parcel_count_loaded
      from public.parcels pr
      where pr.tracking_code in (
        select coalesce(w.tracking_no, w.waybill_no, w.delivery_way_id)
        from public.be_waybill_ledger w
        where w.pickup_id = coalesce(p.pickup_way_id, p.pickup_id, p.request_code)
           or w.pickup_way_id = coalesce(p.pickup_way_id, p.pickup_id, p.request_code)
      )
    ) parcel on true
    where upper(coalesce(p.pickup_status, p.status, '')) in (
      'PICKUP_VERIFIED',
      'DATA_ENTRY_REGISTERED'
    )
    or upper(coalesce(p.data_entry_status, '')) in (
      'WAITING_DATA_ENTRY',
      'REGISTERED',
      'PARCEL_BULK_LOADED'
    )
    order by p.updated_at desc
    limit greatest(coalesce(p_limit, 100), 1)
  )
  select jsonb_build_object(
    'ok', true,
    'source', 'be_data_entry_bulk_load_queue',
    'count', count(*),
    'rows', coalesce(jsonb_agg(to_jsonb(pickup_rows)), '[]'::jsonb)
  )
  from pickup_rows;
$function$
;

CREATE OR REPLACE FUNCTION public.be_data_entry_clean_code(p_value text, p_fallback text DEFAULT 'GEN'::text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select left(coalesce(nullif(upper(regexp_replace(coalesce(p_value, ''), '[^A-Z0-9]', '', 'g')), ''), p_fallback), 12);
$function$
;

CREATE OR REPLACE FUNCTION public.be_data_entry_confirm_registration(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare v_pickup_id text := nullif(trim(p_payload->>'pickup_id'), '');
begin
  if v_pickup_id is null then raise exception 'pickup_id is required'; end if;
  update public.be_enterprise_workflow_jobs set status='data_entry_registered', data_entry_registered_at=now(), payload=coalesce(payload,'{}'::jsonb)||p_payload, updated_at=now() where pickup_id=v_pickup_id;
  if not found then raise exception 'No workflow job found for pickup_id %', v_pickup_id; end if;
  perform public.be_workflow_log(v_pickup_id, 'DATA_ENTRY_REGISTRATION', 'data_entry_registered', 'data_entry', 'delivery_dispatch', p_payload);
  return jsonb_build_object('ok', true, 'pickup_id', v_pickup_id, 'status', 'data_entry_registered');
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_data_entry_create_waybill(p_actor_email text, p_cod_amount numeric, p_destination_city text, p_destination_township text, p_pickup_id text, p_receiver_address text, p_receiver_name text, p_receiver_phone text, p_waybill_no text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_waybill_no text;
  v_count integer := 0;
begin
  if coalesce(trim(p_pickup_id), '') = '' then
    raise exception 'p_pickup_id is required';
  end if;

  select count(*)
  into v_count
  from public.be_data_entry_parcel_details d
  where d.pickup_id = p_pickup_id;

  v_waybill_no := nullif(trim(coalesce(p_waybill_no, '')), '');

  if v_waybill_no is null then
    v_waybill_no :=
      'WB' ||
      to_char(now(), 'MMDD') ||
      '-' ||
      regexp_replace(p_pickup_id, '[^A-Za-z0-9]', '', 'g') ||
      '-' ||
      lpad((extract(epoch from now())::bigint % 100000)::text, 5, '0');
  end if;

  insert into public.be_data_entry_waybills (
    waybill_no,
    pickup_id,
    receiver_name,
    receiver_phone,
    receiver_address,
    destination_city,
    destination_township,
    cod_amount,
    actor_email,
    status,
    created_at,
    updated_at
  )
  values (
    v_waybill_no,
    p_pickup_id,
    p_receiver_name,
    p_receiver_phone,
    p_receiver_address,
    coalesce(p_destination_city, 'Yangon'),
    p_destination_township,
    coalesce(p_cod_amount, 0),
    p_actor_email,
    'GENERATED',
    now(),
    now()
  )
  on conflict (waybill_no)
  do update set
    pickup_id = excluded.pickup_id,
    receiver_name = excluded.receiver_name,
    receiver_phone = excluded.receiver_phone,
    receiver_address = excluded.receiver_address,
    destination_city = excluded.destination_city,
    destination_township = excluded.destination_township,
    cod_amount = excluded.cod_amount,
    actor_email = excluded.actor_email,
    status = 'GENERATED',
    updated_at = now();

  update public.be_data_entry_parcel_details d
  set updated_at = now()
  where d.pickup_id = p_pickup_id;

  return jsonb_build_object(
    'ok', true,
    'waybill_no', v_waybill_no,
    'pickup_id', p_pickup_id,
    'parcel_count', v_count,
    'receiver_name', p_receiver_name,
    'receiver_phone', p_receiver_phone,
    'receiver_address', p_receiver_address,
    'destination_city', coalesce(p_destination_city, 'Yangon'),
    'destination_township', p_destination_township,
    'cod_amount', coalesce(p_cod_amount, 0),
    'status', 'GENERATED'
  );
end;
$function$
;

