;

CREATE OR REPLACE FUNCTION public.be_data_entry_mark_partial_registration(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_pickup text := coalesce(p_payload->>'pickup_id', p_payload->>'pickup_way_id');
  v_expected integer := greatest(1, coalesce(nullif(p_payload->>'expected_count', '')::integer, 1));
  v_registered integer := greatest(0, coalesce(nullif(p_payload->>'registered_count', '')::integer, 0));
  v_rejected integer := greatest(0, coalesce(nullif(p_payload->>'rejected_count', '')::integer, 0));
  v_pending integer := greatest(0, coalesce(nullif(p_payload->>'pending_count', '')::integer, v_expected - v_registered - v_rejected));
begin
  update public.be_portal_pickup_requests
  set expected_parcel_count = v_expected,
      registered_parcel_count = v_registered,
      rejected_photo_count = v_rejected,
      pending_photo_count = v_pending,
      data_entry_status = case
        when v_registered >= v_expected then 'PARCEL_BULK_LOADED'
        else 'PARTIAL_PARCEL_REGISTERED'
      end,
      workflow_stage = case
        when v_registered >= v_expected then 'WAITING_WAREHOUSE_RECEIVE'
        else 'PARTIAL_DATA_ENTRY'
      end,
      warehouse_status = case
        when v_registered > 0 then 'PARTIAL_WAREHOUSE_RECEIVE_ALLOWED'
        else warehouse_status
      end,
      updated_at = now()
  where pickup_way_id = v_pickup;

  return jsonb_build_object(
    'ok', true,
    'source', 'be_data_entry_mark_partial_registration',
    'pickup_id', v_pickup,
    'expected_count', v_expected,
    'registered_count', v_registered,
    'rejected_count', v_rejected,
    'pending_count', v_pending,
    'partial', v_registered < v_expected
  );
end $function$
;

CREATE OR REPLACE FUNCTION public.be_data_entry_pickup_queue(p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object('ok', true, 'items', coalesce(jsonb_agg(to_jsonb(p) order by p.updated_at desc), '[]'::jsonb), 'data', coalesce(jsonb_agg(to_jsonb(p) order by p.updated_at desc), '[]'::jsonb))
  from public.be_portal_pickup_requests p
  where upper(coalesce(p.pickup_status, '')) in ('PICKUP_VERIFIED', 'PICKUP_COLLECTED')
     or upper(coalesce(p.data_entry_status, '')) in ('WAITING_DATA_ENTRY', 'WAITING_PICKUP');
$function$
;

create or replace view "public"."be_data_entry_pickup_verification_summary" as  SELECT h.pickup_id,
    h.status,
    h.sender_acknowledged,
    h.sender_signature_url,
    h.sender_acknowledgment_text,
    h.expected_parcel_count,
    h.actual_parcel_count,
    h.total_weight_kg,
    (count(p.id))::integer AS parcel_count,
    COALESCE(jsonb_agg(jsonb_build_object('parcel_no', p.parcel_no, 'waybill_id', p.waybill_id, 'weight_kg', p.weight_kg, 'receiver_address', p.receiver_address, 'receiver_township', p.receiver_township, 'parcel_photo_url', p.parcel_photo_url, 'address_photo_url', p.address_photo_url, 'remarks', p.remarks, 'status', p.status) ORDER BY p.parcel_no) FILTER (WHERE (p.id IS NOT NULL)), '[]'::jsonb) AS parcels,
    array_remove(array_agg(p.parcel_photo_url ORDER BY p.parcel_no), NULL::text) AS parcel_photo_urls,
    array_remove(array_agg(p.address_photo_url ORDER BY p.parcel_no), NULL::text) AS address_photo_urls,
    h.updated_at
   FROM (public.be_pickup_verifications h
     LEFT JOIN public.be_pickup_verification_parcels p ON ((p.pickup_id = h.pickup_id)))
  GROUP BY h.id;


CREATE OR REPLACE FUNCTION public.be_data_entry_prepare_pickup_template(p_pickup_request_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_pickup_id text := trim(p_pickup_request_id);
  v_req public.be_portal_pickup_requests;
  v_count integer;
  v_i integer;
  v_suffix integer;
  v_deliver_way_id text;
  v_rows jsonb;
begin
  select * into v_req
  from public.be_portal_pickup_requests
  where pickup_id = v_pickup_id or canonical_pickup_id = v_pickup_id or pickup_way_id = v_pickup_id;

  if v_req.pickup_id is null then
    raise exception 'Pickup request % not found', p_pickup_request_id;
  end if;

  v_count := greatest(coalesce(v_req.parcel_count, 1), 1);

  if v_req.delivery_start_no is null or v_req.delivery_end_no is null then
    raise exception 'Pickup % has no delivery sequence. Create it again from Customer Service.', v_req.pickup_id;
  end if;

  for v_i in 1..v_count loop
    v_suffix := v_req.delivery_start_no + v_i - 1;
    v_deliver_way_id := coalesce(v_req.delivery_prefix, 'D' || to_char(coalesce(v_req.pickup_date, now()::date), 'MMDD') || '-' || v_req.merchant_code) || '-' || lpad(v_suffix::text, 3, '0');

    insert into public.be_portal_cargo_events (
      pickup_id, tracking_no, deliver_way_id, line_no, event_type, event_title, event_description, status, source_table, source_key,
      pickup_date, merchant, sender_name, sender_phone, pickup_address, pickup_township, pickup_city,
      item_price, deli_fee_os, cod_os, std_deli, max_deli, weight_kg, surcharge, final_cod, cod_amount,
      package_type, service_type, pickup_verification_status, payload, metadata, created_at, updated_at
    )
    values (
      v_req.pickup_id, v_deliver_way_id, v_deliver_way_id, v_i, 'data_entry_waybill',
      'Data Entry Waybill', 'Delivery waybill generated from pickup ' || v_req.pickup_id, 'draft',
      'be_portal_cargo_events', v_deliver_way_id,
      coalesce(v_req.pickup_date, v_req.created_at::date, now()::date), coalesce(v_req.merchant_name, v_req.merchant_code),
      v_req.sender_name, v_req.sender_phone, v_req.pickup_address, v_req.township, v_req.city,
      0, 0, 0, 0, 0, 1, 0, 0, 0,
      'parcel', 'standard', 'pending',
      jsonb_build_object('source', 'data_entry_template', 'pickup_id', v_req.pickup_id, 'pickup_way_id', v_req.pickup_id, 'deliver_way_id', v_deliver_way_id, 'delivery_suffix', v_suffix),
      '{}'::jsonb, now(), now()
    )
    on conflict (tracking_no)
    do update set
      deliver_way_id = excluded.deliver_way_id,
      pickup_id = excluded.pickup_id,
      line_no = excluded.line_no,
      event_type = 'data_entry_waybill',
      pickup_date = excluded.pickup_date,
      merchant = excluded.merchant,
      sender_name = excluded.sender_name,
      sender_phone = excluded.sender_phone,
      pickup_address = excluded.pickup_address,
      pickup_township = excluded.pickup_township,
      pickup_city = excluded.pickup_city,
      updated_at = now();
  end loop;

  update public.be_portal_pickup_requests
  set status = 'data_entry_in_progress', updated_at = now()
  where pickup_id = v_req.pickup_id;

  select coalesce(jsonb_agg(to_jsonb(x) order by x.line_no), '[]'::jsonb)
  into v_rows
  from public.be_portal_cargo_events x
  where x.pickup_id = v_req.pickup_id
    and x.event_type = 'data_entry_waybill';

  return jsonb_build_object('ok', true, 'pickup_id', v_req.pickup_id, 'pickup_request_id', v_req.pickup_id, 'pickup_way_id', v_req.pickup_id, 'parcel_count', v_count, 'rows', v_rows);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_data_entry_register_bulk(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_batch uuid := gen_random_uuid();
  v_rows jsonb := coalesce(p_payload -> 'rows', '[]'::jsonb);
  v_total int := jsonb_array_length(coalesce(p_payload -> 'rows', '[]'::jsonb));
  v_upserted int := 0;
  v_row jsonb;
  v_idx int := 0;
  v_pickup_date date;
  v_delivery_way_id text;
  v_pickup_way_id text;
  v_merchant_code text;
  v_item_price numeric;
  v_deli_fee numeric;
  v_surcharge numeric;
  v_final_cod numeric;
begin
  insert into public.be_data_entry_register_batches (
    batch_id,
    source_file_name,
    uploaded_by,
    uploaded_by_name,
    total_rows,
    status,
    payload
  )
  values (
    v_batch,
    p_payload ->> 'source_file_name',
    p_payload ->> 'uploaded_by',
    p_payload ->> 'uploaded_by_name',
    v_total,
    'registered',
    p_payload
  );

  for v_row in
    select * from jsonb_array_elements(v_rows)
  loop
    v_idx := v_idx + 1;

    begin
      v_pickup_date := coalesce(nullif(v_row ->> 'pickup_date', '')::date, current_date);
    exception when others then
      v_pickup_date := current_date;
    end;

    v_merchant_code := public.be_gl_code(coalesce(v_row ->> 'merchant_code', v_row ->> 'merchant'), 'GEN');
    v_pickup_way_id := nullif(coalesce(v_row ->> 'pickup_way_id', v_row ->> 'pickup_id'), '');
    if v_pickup_way_id is null then
      v_pickup_way_id := public.be_gl_pickup_id(v_pickup_date, v_merchant_code, 1);
    end if;

    v_delivery_way_id := nullif(coalesce(v_row ->> 'delivery_way_id', v_row ->> 'way_id', v_row ->> 'tracking_no'), '');
    if v_delivery_way_id is null then
      v_delivery_way_id := public.be_gl_delivery_id(v_pickup_date, v_merchant_code, v_idx);
    end if;

    v_item_price := public.be_gl_num(coalesce(v_row ->> 'item_price', v_row ->> 'cod_amount'), 0);
    v_deli_fee := public.be_gl_num(coalesce(v_row ->> 'delivery_fee', v_row ->> 'deli_fee_os', v_row ->> 'deli_fee'), 0);
    v_surcharge := public.be_gl_num(v_row ->> 'surcharge', 0);
    v_final_cod := coalesce(nullif(public.be_gl_num(coalesce(v_row ->> 'actual_collect', v_row ->> 'final_cod'), 0), 0), v_item_price + v_deli_fee + v_surcharge);

    insert into public.delivery_waybills (
      pickup_date,
      pickup_way_id,
      pickup_id,
      delivery_way_id,
      merchant_code,
      merchant_name,
      merchant,
      recipient_name,
      recipient_phone,
      recipient_phone_2,
      recipient_township,
      recipient_address,
      item_price,
      deli_fee_os,
      delivery_fee_os,
      cod_os,
      std_deli,
      max_deli,
      weight_kg,
      surcharge,
      final_cod,
      destination,
      pickup_by_1,
      general_remarks,
      finance_deli,
      finance_cod,
      finance_received_by,
      finance_status,
      operation_status,
      overall_status,
      financial_status,
      validation_status,
      validation_errors,
      raw_row,
      created_by,
      created_by_name,
      updated_at
    )
    values (
      v_pickup_date,
      v_pickup_way_id,
      v_pickup_way_id,
      v_delivery_way_id,
      v_merchant_code,
      nullif(coalesce(v_row ->> 'merchant_name', v_row ->> 'merchant'), ''),
      nullif(coalesce(v_row ->> 'merchant', v_row ->> 'merchant_name'), ''),
      nullif(v_row ->> 'recipient_name', ''),
      nullif(coalesce(v_row ->> 'recipient_phone', v_row ->> 'contact_no_1', v_row ->> 'phone'), ''),
      nullif(coalesce(v_row ->> 'recipient_phone_2', v_row ->> 'contact_no_2'), ''),
      nullif(coalesce(v_row ->> 'recipient_township', v_row ->> 'township', v_row ->> 'town'), ''),
      nullif(coalesce(v_row ->> 'recipient_address', v_row ->> 'address'), ''),
      v_item_price,
      v_deli_fee,
      v_deli_fee,
      v_item_price + v_deli_fee,
      v_deli_fee,
      v_deli_fee,
      public.be_gl_num(coalesce(v_row ->> 'weight_kg', v_row ->> 'weight'), 0),
      v_surcharge,
      v_final_cod,
      nullif(coalesce(v_row ->> 'destination', v_row ->> 'city'), ''),
      nullif(coalesce(v_row ->> 'pickup_by', v_row ->> 'pickup_by_1'), ''),
      nullif(coalesce(v_row ->> 'remark', v_row ->> 'remarks', v_row ->> 'general_remarks'), ''),
      v_deli_fee,
      v_final_cod,
      nullif(v_row ->> 'finance_received_by', ''),
      coalesce(nullif(v_row ->> 'finance_status', ''), 'pending_finance'),
      'data_entry_registered',
      'registered',
      'pending_finance',
      'valid',
      '[]'::jsonb,
      v_row,
      p_payload ->> 'uploaded_by',
      p_payload ->> 'uploaded_by_name',
      now()
    )
    on conflict (delivery_way_id) do update set
      pickup_date = excluded.pickup_date,
      pickup_way_id = excluded.pickup_way_id,
      pickup_id = excluded.pickup_id,
      merchant_code = excluded.merchant_code,
      merchant_name = excluded.merchant_name,
      merchant = excluded.merchant,
      recipient_name = excluded.recipient_name,
      recipient_phone = excluded.recipient_phone,
      recipient_phone_2 = excluded.recipient_phone_2,
      recipient_township = excluded.recipient_township,
      recipient_address = excluded.recipient_address,
      item_price = excluded.item_price,
      deli_fee_os = excluded.deli_fee_os,
      delivery_fee_os = excluded.delivery_fee_os,
      cod_os = excluded.cod_os,
      std_deli = excluded.std_deli,
      max_deli = excluded.max_deli,
      weight_kg = excluded.weight_kg,
      surcharge = excluded.surcharge,
      final_cod = excluded.final_cod,
      destination = excluded.destination,
      pickup_by_1 = excluded.pickup_by_1,
      general_remarks = excluded.general_remarks,
      finance_deli = excluded.finance_deli,
      finance_cod = excluded.finance_cod,
      finance_status = excluded.finance_status,
      operation_status = excluded.operation_status,
      overall_status = excluded.overall_status,
      financial_status = excluded.financial_status,
      validation_status = excluded.validation_status,
      validation_errors = excluded.validation_errors,
      raw_row = excluded.raw_row,
      updated_at = now();

    insert into public.be_data_entry_register_rows (
      batch_id,
      row_no,
      source_file_name,
      pickup_date,
      pickup_way_id,
      delivery_way_id,
      merchant_code,
      merchant_name,
      recipient_name,
      recipient_phone,
      recipient_township,
      recipient_address,
      item_price,
      deli_fee_os,
      delivery_fee_os,
      cod_os,
      std_deli,
      max_deli,
      weight_kg,
      surcharge,
      final_cod,
      destination,
      pickup_by_1,
      general_remarks,
      finance_deli,
      finance_cod,
      finance_received_by,
      finance_status,
      operation_status,
      overall_status,
      financial_status,
      validation_status,
      validation_errors,
      raw_row,
      created_by,
      created_by_name,
      updated_at
    )
    values (
      v_batch,
      v_idx,
      p_payload ->> 'source_file_name',
      v_pickup_date,
      v_pickup_way_id,
      v_delivery_way_id,
      v_merchant_code,
      nullif(coalesce(v_row ->> 'merchant_name', v_row ->> 'merchant'), ''),
      nullif(v_row ->> 'recipient_name', ''),
      nullif(coalesce(v_row ->> 'recipient_phone', v_row ->> 'contact_no_1', v_row ->> 'phone'), ''),
      nullif(coalesce(v_row ->> 'recipient_township', v_row ->> 'township', v_row ->> 'town'), ''),
      nullif(coalesce(v_row ->> 'recipient_address', v_row ->> 'address'), ''),
      v_item_price,
      v_deli_fee,
      v_deli_fee,
      v_item_price + v_deli_fee,
      v_deli_fee,
      v_deli_fee,
      public.be_gl_num(coalesce(v_row ->> 'weight_kg', v_row ->> 'weight'), 0),
      v_surcharge,
      v_final_cod,
      nullif(coalesce(v_row ->> 'destination', v_row ->> 'city'), ''),
      nullif(coalesce(v_row ->> 'pickup_by', v_row ->> 'pickup_by_1'), ''),
      nullif(coalesce(v_row ->> 'remark', v_row ->> 'remarks', v_row ->> 'general_remarks'), ''),
      v_deli_fee,
      v_final_cod,
      nullif(v_row ->> 'finance_received_by', ''),
      coalesce(nullif(v_row ->> 'finance_status', ''), 'pending_finance'),
      'data_entry_registered',
      'registered',
      'pending_finance',
      'valid',
      '[]'::jsonb,
      v_row,
      p_payload ->> 'uploaded_by',
      p_payload ->> 'uploaded_by_name',
      now()
    )
    on conflict (delivery_way_id) do update set
      batch_id = excluded.batch_id,
      row_no = excluded.row_no,
      item_price = excluded.item_price,
      deli_fee_os = excluded.deli_fee_os,
      finance_cod = excluded.finance_cod,
      raw_row = excluded.raw_row,
      updated_at = now();

    v_upserted := v_upserted + 1;
  end loop;

  update public.be_data_entry_register_batches
  set valid_rows = (
        select count(*)
        from public.be_data_entry_register_rows
        where batch_id = v_batch
          and validation_status = 'valid'
      ),
      rejected_rows = (
        select count(*)
        from public.be_data_entry_register_rows
        where batch_id = v_batch
          and validation_status <> 'valid'
      ),
      updated_at = now()
  where batch_id = v_batch;

  return jsonb_build_object(
    'ok', true,
    'batch_id', v_batch,
    'total_rows', v_total,
    'upserted_rows', v_upserted,
    'synced_to_delivery_waybills', true,
    'synced_to_finance', true
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_data_entry_register_snapshot(p_status text DEFAULT NULL::text, p_limit integer DEFAULT 300)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
AS $function$
  select jsonb_build_object(
    'rows', coalesce(jsonb_agg(row_to_json(x)::jsonb order by x.created_at desc), '[]'::jsonb),
    'kpis', jsonb_build_object(
      'total', (select count(*) from public.be_data_entry_register_rows),
      'valid', (select count(*) from public.be_data_entry_register_rows where validation_status = 'valid'),
      'warning', (select count(*) from public.be_data_entry_register_rows where validation_status = 'warning'),
      'finance_pending', (select count(*) from public.be_data_entry_register_rows where finance_status = 'pending_finance')
    ),
    'synced_at', now()
  )
  from (
    select *
    from public.be_data_entry_register_rows
    where p_status is null or validation_status = p_status or operation_status = p_status or finance_status = p_status
    order by created_at desc
    limit least(greatest(coalesce(p_limit,300),1),1000)
  ) x;
$function$
;

CREATE OR REPLACE FUNCTION public.be_data_entry_register_verified_pickup(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_pickup_id text;
  v_actor_email text;
  v_pickup record;
  v_count integer;
  v_seq integer;
  v_delivery_id text;
  v_waybill_no text;
  v_invoice_no text;
  v_tracking_no text;
  v_rows jsonb := '[]'::jsonb;
begin
  v_pickup_id := nullif(coalesce(
    p_payload->>'pickup_way_id',
    p_payload->>'pickup_id',
    p_payload->>'request_code'
  ), '');

  v_actor_email := nullif(coalesce(
    p_payload->>'actor_email',
    p_payload->>'data_entry_email',
    'data.entry@britiumexpress.com'
  ), '');

  if v_pickup_id is null then
    return jsonb_build_object(
      'ok', false,
      'error', 'pickup_id / pickup_way_id is required',
      'payload', p_payload
    );
  end if;

  select *
  into v_pickup
  from public.be_portal_pickup_requests
  where pickup_way_id = v_pickup_id
     or pickup_id = v_pickup_id
     or request_code = v_pickup_id
  order by updated_at desc
  limit 1;

  if v_pickup.id is null then
    return jsonb_build_object(
      'ok', false,
      'error', 'Pickup not found',
      'pickup_id', v_pickup_id
    );
  end if;

  if upper(coalesce(v_pickup.pickup_status, v_pickup.status, '')) not in (
    'PICKUP_VERIFIED',
    'PICKUP_COLLECTED',
    'ACCEPTED_BY_RIDER'
  ) then
    return jsonb_build_object(
      'ok', false,
      'error', 'Pickup is not ready for Data Entry',
      'pickup_id', v_pickup_id,
      'pickup_status', v_pickup.pickup_status,
      'status', v_pickup.status
    );
  end if;

  v_count := greatest(
    coalesce(v_pickup.expected_parcel_count, 0),
    coalesce(v_pickup.expected_parcels, 0),
    coalesce(v_pickup.parcel_count, 0),
    coalesce(v_pickup.verified_parcels, 0),
    1
  );

  for v_seq in 1..v_count loop
    v_delivery_id := 'D' || substring(v_pickup_id from 2 for 8) || '-' || lpad(v_seq::text, 3, '0');
    v_waybill_no := 'WB' || substring(v_pickup_id from 2 for 8) || '-' || lpad(v_seq::text, 3, '0');
    v_invoice_no := 'INV' || substring(v_pickup_id from 2 for 8) || '-' || lpad(v_seq::text, 3, '0');
    v_tracking_no := 'TRK' || substring(v_pickup_id from 2 for 8) || '-' || lpad(v_seq::text, 3, '0');

    insert into public.be_waybill_ledger (
      pickup_id,
      pickup_way_id,
      delivery_way_id,
      waybill_no,
      invoice_no,
      tracking_no,
      merchant_code,
      merchant_name,
      parcel_sequence,
      parcel_count,
      pickup_status,
      warehouse_status,
      data_entry_status,
      created_at,
      updated_at,
      metadata
    )
    values (
      v_pickup_id,
      v_pickup_id,
      v_delivery_id,
      v_waybill_no,
      v_invoice_no,
      v_tracking_no,
      v_pickup.merchant_code,
      v_pickup.merchant_name,
      v_seq,
      v_count,
      'DATA_ENTRY_REGISTERED',
      'WAITING_WAREHOUSE_RECEIVE',
      'REGISTERED',
      now(),
      now(),
      jsonb_build_object(
        'source', 'be_data_entry_register_verified_pickup',
        'pickup_id', v_pickup_id,
        'delivery_way_id', v_delivery_id,
        'waybill_no', v_waybill_no,
        'invoice_no', v_invoice_no,
        'tracking_no', v_tracking_no,
        'registered_by', v_actor_email
      )
    )
    on conflict do nothing;

    v_rows := v_rows || jsonb_build_array(
      jsonb_build_object(
        'parcel_sequence', v_seq,
        'delivery_way_id', v_delivery_id,
        'waybill_no', v_waybill_no,
        'invoice_no', v_invoice_no,
        'tracking_no', v_tracking_no
      )
    );
  end loop;

  update public.be_portal_pickup_requests
  set
    pickup_status = 'DATA_ENTRY_REGISTERED',
    workflow_stage = 'DATA_ENTRY_REGISTERED',
    data_entry_status = 'REGISTERED',
    warehouse_status = 'WAITING_WAREHOUSE_RECEIVE',
    status = 'DATA_ENTRY_REGISTERED',
    delivery_start_no = 1,
    delivery_end_no = v_count,
    delivery_prefix = 'D' || substring(v_pickup_id from 2 for 8),
    delivery_count = v_count,
    metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
      'data_entry_registered_at', now(),
      'data_entry_registered_by', v_actor_email,
      'generated_documents', v_rows
    ),
    updated_at = now()
  where id = v_pickup.id;

  insert into public.be_app_notifications (
    title,
    body,
    message,
    status,
    is_read,
    category,
    notification_type,
    event_type,
    event_key,
    source_key,
    source_table,
    pickup_id,
    pickup_way_id,
    target_role,
    metadata,
    payload,
    created_at
  )
  values (
    'Pickup ready for warehouse receive',
    'Pickup ' || v_pickup_id || ' has completed Data Entry and is ready for warehouse receiving.',
    'Pickup ' || v_pickup_id || ' has completed Data Entry and is ready for warehouse receiving.',
    'unread',
    false,
    'warehouse',
    'DATA_ENTRY_REGISTERED_WAREHOUSE_RECEIVE',
    'data_entry_registered',
    'workflow:warehouse:be_portal_pickup_requests:' || v_pickup_id,
    v_pickup_id,
    'be_portal_pickup_requests',
    v_pickup_id,
    v_pickup_id,
    'warehouse',
    jsonb_build_object(
      'source', 'be_data_entry_register_verified_pickup',
      'pickup_id', v_pickup_id,
      'next_action', 'WAREHOUSE_RECEIVE',
      'workflow_stage', 'WAITING_WAREHOUSE_RECEIVE',
      'parcel_count', v_count
    ),
    jsonb_build_object(
      'pickup_id', v_pickup_id,
      'pickup_way_id', v_pickup_id,
      'next_action', 'WAREHOUSE_RECEIVE',
      'parcel_count', v_count,
      'documents', v_rows
    ),
    now()
  )
  on conflict (event_key) do update
  set
    status = 'unread',
    is_read = false,
    notification_type = 'DATA_ENTRY_REGISTERED_WAREHOUSE_RECEIVE',
    metadata = coalesce(public.be_app_notifications.metadata, '{}'::jsonb) || excluded.metadata,
    payload = coalesce(public.be_app_notifications.payload, '{}'::jsonb) || excluded.payload;

  return jsonb_build_object(
    'ok', true,
    'source', 'be_data_entry_register_verified_pickup',
    'pickup_id', v_pickup_id,
    'parcel_count', v_count,
    'documents', v_rows,
    'next_status', 'DATA_ENTRY_REGISTERED',
    'warehouse_status', 'WAITING_WAREHOUSE_RECEIVE',
    'next_action', 'WAREHOUSE_RECEIVE'
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_data_entry_save_parcel(p_parcel_id uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_row public.be_portal_cargo_events;
  v_item numeric := coalesce(nullif(regexp_replace(coalesce(p_payload->>'item_price','0'), '[,\s]', '', 'g'), '')::numeric, 0);
  v_deli numeric := coalesce(nullif(regexp_replace(coalesce(p_payload->>'deli_fee_os','0'), '[,\s]', '', 'g'), '')::numeric, 0);
  v_surcharge numeric := coalesce(nullif(regexp_replace(coalesce(p_payload->>'surcharge','0'), '[,\s]', '', 'g'), '')::numeric, 0);
  v_weight numeric := coalesce(nullif(regexp_replace(coalesce(p_payload->>'weight_kg','1'), '[,\s]', '', 'g'), '')::numeric, 1);
  v_cod_os numeric;
  v_final numeric;
begin
  v_cod_os := coalesce(nullif(regexp_replace(coalesce(p_payload->>'cod_os',''), '[,\s]', '', 'g'), '')::numeric, v_item + v_deli);
  v_final := coalesce(nullif(regexp_replace(coalesce(p_payload->>'final_cod',''), '[,\s]', '', 'g'), '')::numeric, v_cod_os + v_surcharge);

  update public.be_portal_cargo_events
  set
    pickup_date = coalesce(nullif(p_payload->>'pickup_date', '')::date, pickup_date),
    deliver_way_id = coalesce(nullif(p_payload->>'deliver_way_id', ''), deliver_way_id),
    merchant = coalesce(nullif(p_payload->>'merchant', ''), merchant),
    receiver_name = nullif(p_payload->>'receiver_name', ''),
    receiver_phone = nullif(p_payload->>'receiver_phone', ''),
    recipient_town = nullif(coalesce(p_payload->>'recipient_town', p_payload->>'delivery_township'), ''),
    delivery_township = nullif(coalesce(p_payload->>'delivery_township', p_payload->>'recipient_town'), ''),
    delivery_address = nullif(p_payload->>'delivery_address', ''),
    item_price = v_item,
    deli_fee_os = v_deli,
    cod_os = v_cod_os,
    std_deli = coalesce(nullif(regexp_replace(coalesce(p_payload->>'std_deli','0'), '[,\s]', '', 'g'), '')::numeric, 0),
    max_deli = coalesce(nullif(regexp_replace(coalesce(p_payload->>'max_deli','0'), '[,\s]', '', 'g'), '')::numeric, 0),
    weight_kg = v_weight,
    surcharge = v_surcharge,
    final_cod = v_final,
    cod_amount = v_final,
    destination = nullif(p_payload->>'destination', ''),
    pickup_by_1 = nullif(p_payload->>'pickup_by_1', ''),
    pickup_by_2 = nullif(p_payload->>'pickup_by_2', ''),
    general_remarks = nullif(p_payload->>'general_remarks', ''),
    driver_rider = nullif(p_payload->>'driver_rider', ''),
    helper = nullif(p_payload->>'helper', ''),
    plate_no = nullif(p_payload->>'plate_no', ''),
    delivery_remarks = nullif(p_payload->>'delivery_remarks', ''),
    column_37 = nullif(p_payload->>'column_37', ''),
    finance_deli = coalesce(nullif(regexp_replace(coalesce(p_payload->>'finance_deli','0'), '[,\s]', '', 'g'), '')::numeric, 0),
    finance_cod = coalesce(nullif(regexp_replace(coalesce(p_payload->>'finance_cod','0'), '[,\s]', '', 'g'), '')::numeric, 0),
    finance_received_by = nullif(p_payload->>'finance_received_by', ''),
    finance_status = nullif(p_payload->>'finance_status', ''),
    item_description = nullif(p_payload->>'item_description', ''),
    remarks = nullif(p_payload->>'remarks', ''),
    status = case when coalesce(status, '') in ('draft','data_entry_in_progress') then 'draft' else status end,
    payload = coalesce(payload, '{}'::jsonb) || coalesce(p_payload, '{}'::jsonb),
    updated_at = now()
  where id = p_parcel_id
  returning * into v_row;

  if v_row.id is null then
    raise exception 'Parcel row not found';
  end if;

  return to_jsonb(v_row);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_data_entry_submit_pickup_parcels(p_pickup_request_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_pickup_id text := trim(p_pickup_request_id);
  v_count integer;
begin
  select count(*) into v_count
  from public.be_portal_cargo_events
  where pickup_id = v_pickup_id
    and event_type = 'data_entry_waybill';

  if v_count = 0 then
    raise exception 'No parcel rows found. Prepare parcel template first.';
  end if;

  update public.be_portal_cargo_events
  set status = case when coalesce(status, '') = 'draft' then 'ready_for_operations' else status end,
      updated_at = now()
  where pickup_id = v_pickup_id
    and event_type = 'data_entry_waybill';

  update public.be_portal_pickup_requests
  set status = 'data_entry_completed',
      updated_at = now()
  where pickup_id = v_pickup_id;

  insert into public.be_app_notifications (
    event_key, notification_type, category, target_role, pickup_id, source_table, source_key,
    title, body, message, status, is_read, payload, metadata, created_at
  )
  values (
    v_pickup_id || ':data_entry_completed:operation_supervisor',
    'data_entry_completed', 'data_entry_completed', 'operation_supervisor',
    v_pickup_id, 'be_portal_pickup_requests', v_pickup_id || ':data_entry_completed',
    'Data Entry Completed',
    'Pickup ' || v_pickup_id || ' has completed parcel data entry.',
    'Pickup ' || v_pickup_id || ' has completed parcel data entry.',
    'unread', false,
    jsonb_build_object('pickup_id', v_pickup_id, 'event', 'data_entry_completed'),
    '{}'::jsonb, now()
  )
  on conflict (event_key)
  do update set body = excluded.body, message = excluded.message, status = 'unread', is_read = false, payload = excluded.payload, created_at = now();

  return jsonb_build_object('ok', true, 'pickup_id', v_pickup_id, 'pickup_request_id', v_pickup_id, 'parcel_count', v_count, 'status', 'data_entry_completed');
end;
$function$
;

