CREATE OR REPLACE FUNCTION public.be_data_entry_toggle_registration_check(p_event_id uuid, p_checked boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_row public.be_portal_cargo_events;
begin
  update public.be_portal_cargo_events
  set
    data_entry_registration_checked = coalesce(p_checked, false),
    data_entry_registration_checked_at = case when coalesce(p_checked, false) then now() else null end,
    data_entry_registration_checked_by = case when coalesce(p_checked, false) then auth.uid() else null end,
    updated_at = now()
  where id = p_event_id
  returning * into v_row;

  if v_row.id is null then
    raise exception 'Parcel row not found';
  end if;

  return jsonb_build_object('ok', true, 'id', v_row.id, 'deliver_way_id', coalesce(v_row.deliver_way_id, v_row.tracking_no), 'data_entry_registration_checked', v_row.data_entry_registration_checked);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_data_entry_work_queue_snapshot(p_status text DEFAULT NULL::text, p_limit integer DEFAULT 200)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
AS $function$
  select jsonb_build_object('rows', coalesce(jsonb_agg(row_to_json(x)::jsonb order by x.updated_at desc), '[]'::jsonb), 'synced_at', now())
  from (select * from public.be_enterprise_workflow_jobs where status in ('picked_up_verified','data_entry_pending','data_entry_registered') and (p_status is null or status=p_status) order by updated_at desc limit least(greatest(coalesce(p_limit,200),1),500)) x;
$function$
;

CREATE OR REPLACE FUNCTION public.be_date_from_json(p_data jsonb, VARIADIC p_keys text[])
 RETURNS date
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  k text;
  v text;
begin
  foreach k in array p_keys loop
    v := nullif(trim(coalesce(p_data ->> k, '')), '');
    if v is not null and lower(v) not in ('null','undefined','nan') then
      begin
        return v::timestamptz::date;
      exception when others then
        begin
          return v::date;
        exception when others then
          null;
        end;
      end;
    end if;
  end loop;
  return current_date;
end;
$function$
;

