CREATE OR REPLACE FUNCTION public.be_delivery_item_rows()
 RETURNS TABLE(pickup_way_id text, existing_delivery_way_id text, delivery_sequence integer, recipient_name text, recipient_phone text, recipient_address text, delivery_township text, item_status text, cod_amount numeric, item_price numeric, delivery_fee numeric, lat numeric, lng numeric, created_at text, updated_at text, source_table text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_table text;
  v_reg regclass;
  v_sql text;
begin
  foreach v_table in array array[
    'public.be_portal_pickup_request_items',
    'public.be_pickup_request_items',
    'public.be_pickup_items',
    'public.be_parcel_items',
    'public.be_parcels',
    'public.be_waybills',
    'public.be_dispatch_job_items',
    'public.be_delivery_job_items'
  ] loop
    v_reg := to_regclass(v_table);

    if v_reg is not null then
      v_sql := format($q$
        with src as (
          select to_jsonb(t) as j
          from %s t
        ), norm as (
          select
            public.be_extract_pickupway_id_from_json(j) as pickup_way_id,
            public.be_extract_deliveryway_id_from_json(j) as existing_delivery_way_id,
            public.be_delivery_safe_int(public.be_delivery_json_first_text(j, array[
              'delivery_sequence','delivery_seq','line_no','line_number','parcel_no',
              'parcel_sequence','item_no','sequence_no','seq','stop_sequence','route_sequence'
            ])) as explicit_sequence,
            public.be_delivery_json_first_text(j, array['recipient_name','receiver_name','customer_name','consignee_name','name']) as recipient_name,
            public.be_delivery_json_first_text(j, array['recipient_phone','receiver_phone','phone_number','delivery_phone','customer_phone','phone']) as recipient_phone,
            public.be_delivery_json_first_text(j, array['recipient_address','receiver_address','delivery_address','customer_address','dropoff_address','address']) as recipient_address,
            public.be_delivery_json_first_text(j, array['delivery_township','destination_township','recipient_township','township']) as delivery_township,
            upper(public.be_delivery_json_first_text(j, array['delivery_status','dispatch_status','item_status','parcel_status','status'])) as item_status,
            public.be_delivery_safe_numeric(public.be_delivery_json_first_text(j, array['cod_amount','rider_cod_amount','amount','item_price','declared_value'])) as cod_amount,
            public.be_delivery_safe_numeric(public.be_delivery_json_first_text(j, array['item_price','declared_value','cod_amount','amount'])) as item_price,
            public.be_delivery_safe_numeric(public.be_delivery_json_first_text(j, array['delivery_fee','shipping_fee','fee'])) as delivery_fee,
            public.be_delivery_safe_numeric(public.be_delivery_json_first_text(j, array['lat','latitude','recipient_lat','delivery_lat','destination_lat'])) as lat,
            public.be_delivery_safe_numeric(public.be_delivery_json_first_text(j, array['lng','lon','longitude','recipient_lng','recipient_lon','delivery_lng','destination_lng'])) as lng,
            public.be_delivery_json_first_text(j, array['created_at','createdAt','submitted_at']) as created_at,
            public.be_delivery_json_first_text(j, array['updated_at','updatedAt','modified_at']) as updated_at
          from src
        ), numbered as (
          select
            n.*,
            row_number() over (
              partition by n.pickup_way_id
              order by n.explicit_sequence nulls last, n.existing_delivery_way_id nulls last, n.created_at nulls last, n.updated_at nulls last
            )::integer as rn
          from norm n
          where n.pickup_way_id is not null
        )
        select
          pickup_way_id,
          existing_delivery_way_id,
          coalesce(nullif(explicit_sequence, 0), rn)::integer as delivery_sequence,
          recipient_name,
          recipient_phone,
          recipient_address,
          delivery_township,
          item_status,
          cod_amount,
          item_price,
          delivery_fee,
          lat,
          lng,
          created_at,
          updated_at,
          %L::text as source_table
        from numbered
      $q$, v_reg, v_table);

      return query execute v_sql;
    end if;
  end loop;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_delivery_json_first_text(p_json jsonb, p_keys text[])
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  k text;
  v text;
begin
  if p_json is null then
    return null;
  end if;

  foreach k in array p_keys loop
    if p_json ? k then
      v := nullif(trim(p_json ->> k), '');
      if v is not null then
        return v;
      end if;
    end if;
  end loop;

  return null;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_delivery_safe_int(p_value text)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v text := nullif(trim(coalesce(p_value, '')), '');
begin
  if v is null then
    return null;
  end if;
  return floor(v::numeric)::integer;
exception when others then
  return null;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_delivery_safe_numeric(p_value text)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v text := nullif(trim(coalesce(p_value, '')), '');
begin
  if v is null then
    return null;
  end if;
  return v::numeric;
exception when others then
  return null;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_delivery_waybill_normalize_biu()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_item numeric;
  v_fee numeric;
  v_sur numeric;
begin
  new.delivery_way_id := nullif(trim(coalesce(new.delivery_way_id, '')), '');
  new.pickup_way_id := nullif(trim(coalesce(new.pickup_way_id, new.pickup_id, '')), '');
  new.pickup_id := nullif(trim(coalesce(new.pickup_id, new.pickup_way_id, '')), '');
  new.merchant_code := nullif(trim(coalesce(new.merchant_code, split_part(coalesce(new.merchant, ''), ' - ', 1), '')), '');
  new.merchant_name := nullif(trim(coalesce(new.merchant_name, new.merchant, '')), '');

  v_item := coalesce(nullif(new.item_price, 0), public.be_gl_num(new.raw_row ->> 'item_price', 0), 0);
  v_fee := coalesce(nullif(new.delivery_fee_os, 0), nullif(new.deli_fee_os, 0), public.be_gl_num(new.raw_row ->> 'delivery_fee', 0), 0);
  v_sur := coalesce(nullif(new.surcharge, 0), public.be_gl_num(new.raw_row ->> 'surcharge', 0), 0);

  new.item_price := v_item;
  new.deli_fee_os := v_fee;
  new.delivery_fee_os := v_fee;
  new.std_deli := coalesce(nullif(new.std_deli, 0), v_fee, 0);
  new.max_deli := coalesce(nullif(new.max_deli, 0), v_fee, 0);
  new.cod_os := coalesce(nullif(new.cod_os, 0), v_item + v_fee, 0);
  new.final_cod := coalesce(nullif(new.final_cod, 0), v_item + v_fee + v_sur, 0);
  new.finance_deli := coalesce(nullif(new.finance_deli, 0), v_fee, 0);
  new.finance_cod := coalesce(nullif(new.finance_cod, 0), new.final_cod, 0);
  new.overall_status := coalesce(nullif(new.overall_status, ''), 'registered');
  new.operation_status := coalesce(nullif(new.operation_status, ''), 'data_entry_registered');
  new.financial_status := coalesce(nullif(new.financial_status, ''), 'pending_finance');
  new.finance_status := coalesce(nullif(new.finance_status, ''), 'pending_finance');
  new.validation_status := coalesce(nullif(new.validation_status, ''), 'valid');
  new.updated_at := now();

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_deliveryway_id_from_invoice_no(p_invoice_no text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v_invoice text := public.be_normalize_invoice_no(p_invoice_no);
begin
  if v_invoice is null then
    return null;
  end if;
  return 'D' || substring(v_invoice from 4);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_deliveryway_id_from_waybill_no(p_waybill_no text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v_waybill text := public.be_normalize_waybill_no(p_waybill_no);
begin
  if v_waybill is null then
    return null;
  end if;
  return 'D' || substring(v_waybill from 3);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_dispatch_assign(p_pickup_ids text[], p_assignee_id uuid, p_assignee_name text, p_route_label text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE v_role TEXT := public.be_current_user_role(); v_count INT;
BEGIN
  IF v_role NOT IN ('admin','operation_manager','dispatch','supervisor') THEN RAISE EXCEPTION 'Access denied'; END IF;
  UPDATE public.be_portal_pickup_requests
  SET assigned_rider_id=p_assignee_id, status='IN_TRANSIT', route_label=p_route_label, updated_at=NOW()
  WHERE pickup_id=ANY(p_pickup_ids);
  GET DIAGNOSTICS v_count = ROW_COUNT;
  INSERT INTO public.be_portal_cargo_events(pickup_id,event_type,description,actor_role,created_at)
  SELECT pid,'ASSIGNED','Assigned to '||p_assignee_name||(CASE WHEN p_route_label IS NOT NULL THEN ' — route: '||p_route_label ELSE '' END), v_role, NOW()
  FROM UNNEST(p_pickup_ids) AS pid;
  RETURN json_build_object('success',true,'assigned',v_count,'assignee',p_assignee_name,'route',p_route_label);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_dispatch_delivery_lifecycle_action(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_action text;
  v_pickup_id text;
  v_wayplan_id text;
  v_actor_email text;
  v_cod_collected numeric;
  v_next_dispatch_status text;
  v_parcel_status text;
  v_updated_parcels integer := 0;
  v_updated_ledger integer := 0;
  v_updated_pickup integer := 0;
begin
  v_action := upper(coalesce(p_payload->>'action', ''));

  v_pickup_id := nullif(coalesce(
    p_payload->>'pickup_way_id',
    p_payload->>'pickup_id',
    p_payload->>'request_code'
  ), '');

  v_wayplan_id := nullif(p_payload->>'wayplan_id', '');

  v_actor_email := nullif(coalesce(
    p_payload->>'actor_email',
    'dispatch@britiumexpress.com'
  ), '');

  v_cod_collected := coalesce(nullif(p_payload->>'cod_collected', '')::numeric, 0);

  if v_pickup_id is null and v_wayplan_id is null then
    return jsonb_build_object('ok', false, 'error', 'pickup_id or wayplan_id is required');
  end if;

  if v_pickup_id is null then
    select pickup_id into v_pickup_id
    from public.be_dispatch_wayplan_bridge
    where wayplan_id = v_wayplan_id
    limit 1;
  end if;

  if v_wayplan_id is null then
    select wayplan_id into v_wayplan_id
    from public.be_dispatch_wayplan_bridge
    where pickup_id = v_pickup_id
    limit 1;
  end if;

  if v_action in ('HANDOVER_TO_RIDER', 'HANDOVER', 'DISPATCH_HANDOVER') then
    v_next_dispatch_status := 'HANDED_OVER_TO_RIDER';
    v_parcel_status := 'in_transit';

  elsif v_action in ('OUT_FOR_DELIVERY', 'START_DELIVERY') then
    v_next_dispatch_status := 'OUT_FOR_DELIVERY';
    v_parcel_status := 'out_for_delivery';

  elsif v_action in ('DELIVERED', 'COMPLETE_DELIVERY') then
    v_next_dispatch_status := 'DELIVERED';
    v_parcel_status := 'delivered';

  else
    return jsonb_build_object(
      'ok', false,
      'error', 'Unsupported dispatch action',
      'action', v_action,
      'supported_actions', jsonb_build_array('HANDOVER_TO_RIDER', 'OUT_FOR_DELIVERY', 'DELIVERED')
    );
  end if;

  update public.parcels p
  set
    status = v_parcel_status,
    delivered_at = case when v_parcel_status = 'delivered' then now() else delivered_at end,
    updated_at = now(),
    notes = coalesce(p.notes, '') || ' | Dispatch action ' || v_next_dispatch_status || ' for pickup ' || v_pickup_id
  where p.tracking_code in (
    select coalesce(w.tracking_no, w.waybill_no, w.delivery_way_id)
    from public.be_waybill_ledger w
    where w.pickup_id = v_pickup_id
       or w.pickup_way_id = v_pickup_id
  )
  and p.status not in ('returned', 'cancelled');

  get diagnostics v_updated_parcels = row_count;

  update public.be_waybill_ledger
  set
    dispatch_status = v_next_dispatch_status,
    wayplan_status = v_next_dispatch_status,
    warehouse_status = case
      when v_next_dispatch_status = 'HANDED_OVER_TO_RIDER' then 'OUTBOUND_HANDED_OVER'
      else warehouse_status
    end,
    rider_status = v_next_dispatch_status,
    delivered_at = case when v_next_dispatch_status = 'DELIVERED' then now() else delivered_at end,
    cod_collected = case when v_next_dispatch_status = 'DELIVERED' then v_cod_collected else cod_collected end,
    updated_at = now(),
    payload = coalesce(payload, '{}'::jsonb) || jsonb_build_object(
      'last_dispatch_action', v_action,
      'dispatch_status', v_next_dispatch_status,
      'dispatch_actor', v_actor_email,
      'wayplan_id', v_wayplan_id,
      'cod_collected', v_cod_collected,
      'dispatch_action_at', now()
    )
  where pickup_id = v_pickup_id
     or pickup_way_id = v_pickup_id;

  get diagnostics v_updated_ledger = row_count;

  update public.be_warehouse_inventory
  set
    warehouse_status = case
      when v_next_dispatch_status = 'HANDED_OVER_TO_RIDER' then 'OUTBOUND_HANDED_OVER'
      when v_next_dispatch_status = 'OUT_FOR_DELIVERY' then 'OUT_FOR_DELIVERY'
      when v_next_dispatch_status = 'DELIVERED' then 'DELIVERED'
      else warehouse_status
    end,
    status = v_parcel_status,
    wayplan_id = v_wayplan_id,
    wayplan_code = v_wayplan_id,
    dispatched_by = case when v_next_dispatch_status = 'HANDED_OVER_TO_RIDER' then v_actor_email else dispatched_by end,
    dispatched_at = case when v_next_dispatch_status = 'HANDED_OVER_TO_RIDER' then now() else dispatched_at end,
    actual_collect = case when v_next_dispatch_status = 'DELIVERED' then v_cod_collected else actual_collect end,
    updated_at = now()
  where tracking_no in (
    select coalesce(w.tracking_no, w.waybill_no, w.delivery_way_id)
    from public.be_waybill_ledger w
    where w.pickup_id = v_pickup_id
       or w.pickup_way_id = v_pickup_id
  );

  update public.be_portal_pickup_requests
  set
    dispatch_status = v_next_dispatch_status,
    wayplan_status = v_next_dispatch_status,
    rider_status = v_next_dispatch_status,
    warehouse_status = case
      when v_next_dispatch_status = 'HANDED_OVER_TO_RIDER' then 'OUTBOUND_HANDED_OVER'
      else warehouse_status
    end,
    pickup_status = v_next_dispatch_status,
    workflow_stage = v_next_dispatch_status,
    status = v_next_dispatch_status,
    metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
      'wayplan_id', v_wayplan_id,
      'last_dispatch_action', v_action,
      'dispatch_status', v_next_dispatch_status,
      'dispatch_actor', v_actor_email,
      'cod_collected', v_cod_collected,
      'dispatch_action_at', now()
    ),
    updated_at = now()
  where pickup_way_id = v_pickup_id
     or pickup_id = v_pickup_id
     or request_code = v_pickup_id;

  get diagnostics v_updated_pickup = row_count;

  update public.be_dispatch_wayplan_bridge
  set
    dispatch_status = v_next_dispatch_status,
    handed_over_at = case when v_next_dispatch_status = 'HANDED_OVER_TO_RIDER' then now() else handed_over_at end,
    delivered_at = case when v_next_dispatch_status = 'DELIVERED' then now() else delivered_at end,
    cod_collected = case when v_next_dispatch_status = 'DELIVERED' then v_cod_collected else cod_collected end,
    finance_status = case when v_next_dispatch_status = 'DELIVERED' then 'PENDING_COD_SETTLEMENT' else finance_status end,
    updated_at = now()
  where pickup_id = v_pickup_id
     or wayplan_id = v_wayplan_id;

  if v_next_dispatch_status = 'DELIVERED' then
    insert into public.be_app_notifications (
      title,
      body,
      message,
      status,
      is_read,
      category,
      notification_type,
      event_type,
      event_key,
      source_key,
      source_table,
      pickup_id,
      pickup_way_id,
      target_role,
      metadata,
      payload,
      created_at
    )
    values (
      'COD settlement required',
      'Pickup ' || v_pickup_id || ' has been delivered and COD settlement is required.',
      'Pickup ' || v_pickup_id || ' has been delivered and COD settlement is required.',
      'unread',
      false,
      'finance',
      'COD_SETTLEMENT_REQUIRED',
      'delivery_completed',
      'workflow:finance:cod_settlement:' || v_pickup_id,
      v_pickup_id,
      'be_dispatch_wayplan_bridge',
      v_pickup_id,
      v_pickup_id,
      'finance',
      jsonb_build_object(
        'source', 'be_dispatch_delivery_lifecycle_action',
        'pickup_id', v_pickup_id,
        'wayplan_id', v_wayplan_id,
        'cod_collected', v_cod_collected,
        'next_action', 'COD_SETTLEMENT',
        'workflow_stage', 'PENDING_COD_SETTLEMENT'
      ),
      jsonb_build_object(
        'pickup_id', v_pickup_id,
        'wayplan_id', v_wayplan_id,
        'cod_collected', v_cod_collected,
        'next_action', 'COD_SETTLEMENT'
      ),
      now()
    )
    on conflict (event_key) do update
    set
      status = 'unread',
      is_read = false,
      metadata = coalesce(public.be_app_notifications.metadata, '{}'::jsonb) || excluded.metadata,
      payload = excluded.payload;
  end if;

  return jsonb_build_object(
    'ok', true,
    'source', 'be_dispatch_delivery_lifecycle_action',
    'pickup_id', v_pickup_id,
    'wayplan_id', v_wayplan_id,
    'action', v_action,
    'dispatch_status', v_next_dispatch_status,
    'parcel_status', v_parcel_status,
    'updated_pickup_rows', v_updated_pickup,
    'updated_ledger_rows', v_updated_ledger,
    'updated_parcel_rows', v_updated_parcels,
    'next_action', case
      when v_next_dispatch_status = 'HANDED_OVER_TO_RIDER' then 'OUT_FOR_DELIVERY'
      when v_next_dispatch_status = 'OUT_FOR_DELIVERY' then 'DELIVERED'
      when v_next_dispatch_status = 'DELIVERED' then 'COD_SETTLEMENT'
      else null
    end
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_dispatch_go_live_verification()
 RETURNS json
 LANGUAGE sql
 STABLE SECURITY DEFINER
AS $function$
  SELECT json_build_object('ok',true,'rpc_count',(SELECT COUNT(*) FROM pg_proc WHERE proname LIKE 'be_dispatch_%'),'ts',NOW());
$function$
;

CREATE OR REPLACE FUNCTION public.be_dispatch_plan_ready_pickup(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_pickup_id text;
  v_rider_code text;
  v_rider_name text;
  v_rider_email text;
  v_vehicle_code text;
  v_actor_email text;
  v_wayplan_id text;
  v_stops jsonb := '[]'::jsonb;
  v_stop_count integer := 0;
  v_cod_amount numeric := 0;
begin
  v_pickup_id := nullif(coalesce(
    p_payload->>'pickup_way_id',
    p_payload->>'pickup_id',
    p_payload->>'request_code'
  ), '');

  v_rider_code := nullif(coalesce(
    p_payload->>'rider_code',
    p_payload->>'assigned_rider_code',
    'RID001'
  ), '');

  v_rider_name := nullif(coalesce(
    p_payload->>'rider_name',
    'Ko Kyaw Zin Khant'
  ), '');

  v_rider_email := nullif(coalesce(
    p_payload->>'rider_email',
    'rider_ygn_0001@britiumventures.com'
  ), '');

  v_vehicle_code := nullif(coalesce(
    p_payload->>'vehicle_code',
    p_payload->>'vehicle_name',
    'UAT-VEHICLE-001'
  ), '');

  v_actor_email := nullif(coalesce(
    p_payload->>'actor_email',
    'dispatch@britiumexpress.com'
  ), '');

  if v_pickup_id is null then
    return jsonb_build_object('ok', false, 'error', 'pickup_id / pickup_way_id is required');
  end if;

  if not exists (
    select 1
    from public.be_portal_pickup_requests
    where (pickup_way_id = v_pickup_id or pickup_id = v_pickup_id or request_code = v_pickup_id)
      and upper(coalesce(warehouse_status, status, '')) in ('READY_FOR_DISPATCH', 'SORTING', 'RECEIVED_AT_ORIGIN')
  ) then
    return jsonb_build_object(
      'ok', false,
      'error', 'Pickup is not ready for dispatch',
      'pickup_id', v_pickup_id
    );
  end if;

  v_wayplan_id := 'WP-' || to_char(now() at time zone 'Asia/Yangon', 'YYYYMMDD-HH24MISS') || '-' || upper(substr(md5(v_pickup_id || now()::text), 1, 6));

  select
    coalesce(jsonb_agg(jsonb_build_object(
      'tracking_code', p.tracking_code,
      'delivery_way_id', w.delivery_way_id,
      'waybill_no', w.waybill_no,
      'invoice_no', w.invoice_no,
      'recipient_name', p.recipient_name,
      'recipient_phone', p.recipient_phone,
      'recipient_address', p.recipient_address,
      'township', p.recipient_township,
      'cod_amount', p.cod_amount,
      'status', p.status
    ) order by w.parcel_sequence), '[]'::jsonb),
    count(*)::integer,
    coalesce(sum(coalesce(p.cod_amount, 0)), 0)
  into v_stops, v_stop_count, v_cod_amount
  from public.parcels p
  join public.be_waybill_ledger w
    on coalesce(w.tracking_no, w.waybill_no, w.delivery_way_id) = p.tracking_code
  where w.pickup_id = v_pickup_id
     or w.pickup_way_id = v_pickup_id;

  insert into public.be_dispatch_wayplan_bridge (
    wayplan_id,
    pickup_id,
    rider_code,
    rider_name,
    rider_email,
    vehicle_code,
    dispatch_status,
    stop_count,
    stops,
    planned_by,
    planned_at,
    cod_amount,
    finance_status,
    notes,
    updated_at
  )
  values (
    v_wayplan_id,
    v_pickup_id,
    v_rider_code,
    v_rider_name,
    v_rider_email,
    v_vehicle_code,
    'PLANNED',
    v_stop_count,
    v_stops,
    v_actor_email,
    now(),
    v_cod_amount,
    'PENDING_COD',
    'Dispatch plan created from ready warehouse pickup',
    now()
  )
  on conflict (pickup_id) do update
  set
    wayplan_id = excluded.wayplan_id,
    rider_code = excluded.rider_code,
    rider_name = excluded.rider_name,
    rider_email = excluded.rider_email,
    vehicle_code = excluded.vehicle_code,
    dispatch_status = 'PLANNED',
    stop_count = excluded.stop_count,
    stops = excluded.stops,
    planned_by = excluded.planned_by,
    planned_at = now(),
    cod_amount = excluded.cod_amount,
    finance_status = 'PENDING_COD',
    updated_at = now()
  returning wayplan_id into v_wayplan_id;

  update public.be_waybill_ledger
  set
    wayplan_id = v_wayplan_id,
    dispatch_status = 'PLANNED',
    wayplan_status = 'PLANNED',
    warehouse_status = 'READY_FOR_DISPATCH',
    updated_at = now(),
    payload = coalesce(payload, '{}'::jsonb) || jsonb_build_object(
      'wayplan_id', v_wayplan_id,
      'rider_code', v_rider_code,
      'rider_name', v_rider_name,
      'dispatch_planned_at', now()
    )
  where pickup_id = v_pickup_id
     or pickup_way_id = v_pickup_id;

  update public.be_portal_pickup_requests
  set
    wayplan_id = v_wayplan_id,
    assigned_rider_code = v_rider_code,
    assigned_rider_name = v_rider_name,
    assigned_rider_email = v_rider_email,
    assigned_vehicle_code = v_vehicle_code,
    warehouse_status = 'READY_FOR_DISPATCH',
    dispatch_status = 'PLANNED',
    wayplan_status = 'PLANNED',
    workflow_stage = 'DISPATCH_PLANNED',
    pickup_status = 'READY_FOR_DISPATCH',
    status = 'READY_FOR_DISPATCH',
    metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
      'wayplan_id', v_wayplan_id,
      'dispatch_planned_at', now(),
      'dispatch_planned_by', v_actor_email,
      'dispatch_rider_code', v_rider_code,
      'dispatch_vehicle_code', v_vehicle_code
    ),
    updated_at = now()
  where pickup_way_id = v_pickup_id
     or pickup_id = v_pickup_id
     or request_code = v_pickup_id;

  insert into public.be_app_notifications (
    title,
    body,
    message,
    status,
    is_read,
    category,
    notification_type,
    event_type,
    event_key,
    source_key,
    source_table,
    pickup_id,
    pickup_way_id,
    target_role,
    target_user_code,
    target_workforce_code,
    target_email,
    metadata,
    payload,
    created_at
  )
  values (
    'Dispatch wayplan assigned',
    'Wayplan ' || v_wayplan_id || ' is assigned to you.',
    'Wayplan ' || v_wayplan_id || ' is assigned to you.',
    'unread',
    false,
    'dispatch',
    'DISPATCH_WAYPLAN_ASSIGNED',
    'dispatch_wayplan_assigned',
    'workflow:rider:dispatch_wayplan:' || v_wayplan_id,
    v_wayplan_id,
    'be_dispatch_wayplan_bridge',
    v_pickup_id,
    v_pickup_id,
    'rider',
    v_rider_code,
    v_rider_code,
    v_rider_email,
    jsonb_build_object(
      'source', 'be_dispatch_plan_ready_pickup',
      'pickup_id', v_pickup_id,
      'wayplan_id', v_wayplan_id,
      'rider_code', v_rider_code,
      'next_action', 'ACCEPT_DISPATCH_WAYPLAN',
      'workflow_stage', 'DISPATCH_PLANNED'
    ),
    jsonb_build_object(
      'pickup_id', v_pickup_id,
      'wayplan_id', v_wayplan_id,
      'stops', v_stops,
      'next_action', 'ACCEPT_DISPATCH_WAYPLAN'
    ),
    now()
  )
  on conflict (event_key) do update
  set
    status = 'unread',
    is_read = false,
    metadata = coalesce(public.be_app_notifications.metadata, '{}'::jsonb) || excluded.metadata,
    payload = excluded.payload;

  return jsonb_build_object(
    'ok', true,
    'source', 'be_dispatch_plan_ready_pickup',
    'pickup_id', v_pickup_id,
    'wayplan_id', v_wayplan_id,
    'rider_code', v_rider_code,
    'vehicle_code', v_vehicle_code,
    'stop_count', v_stop_count,
    'cod_amount', v_cod_amount,
    'dispatch_status', 'PLANNED',
    'next_action', 'HANDOVER_TO_RIDER'
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_dispatch_ready_queue(p_limit integer DEFAULT 200)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_rows jsonb;
begin
  select coalesce(jsonb_agg(to_jsonb(q) order by q.created_at desc), '[]'::jsonb)
  into v_rows
  from (
    select *
    from public.be_v_dispatch_ready_queue
    order by created_at desc
    limit greatest(coalesce(p_limit, 200), 1)
  ) q;

  return jsonb_build_object(
    'ok', true,
    'queue', v_rows,
    'count', jsonb_array_length(v_rows),
    'source', 'be_dispatch_ready_queue'
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_dispatch_rider_finance_e2e_health()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_capacity jsonb := '{}'::jsonb;
  v_rider_jobs jsonb := '{}'::jsonb;
  v_finance_queue jsonb := '{}'::jsonb;
  v_summary jsonb := '{}'::jsonb;
begin
  select public.be_enterprise_dispatch_capacity_recommend(100)
  into v_capacity;

  select public.be_rider_route_jobs(null, 100)
  into v_rider_jobs;

  select public.be_finance_rider_cod_settlement_queue(100)
  into v_finance_queue;

  select jsonb_build_object(
    'capacity_available_workforce', coalesce((v_capacity->'summary'->>'available_workforce')::integer, 0),
    'capacity_recommendations', coalesce((v_capacity->'summary'->>'recommendations')::integer, 0),
    'capacity_within_capacity', coalesce((v_capacity->'summary'->>'within_capacity')::integer, 0),

    'rider_total_jobs', coalesce((v_rider_jobs->'summary'->>'total_jobs')::integer, 0),
    'rider_assigned_jobs', coalesce((v_rider_jobs->'summary'->>'assigned_jobs')::integer, 0),
    'rider_optimized_jobs', coalesce((v_rider_jobs->'summary'->>'optimized_jobs')::integer, 0),

    'finance_pending_count', coalesce((v_finance_queue->'summary'->>'pending_count')::integer, 0),
    'finance_pending_amount', coalesce((v_finance_queue->'summary'->>'pending_amount')::numeric, 0),

    'delivered_count', (
      select count(*)
      from public.be_wayplan_dispatch_stops
      where upper(coalesce(dispatch_status, stop_status, rider_status, '')) = 'DELIVERED'
    ),

    'cod_settled_count', (
      select count(*)
      from public.be_wayplan_dispatch_stops
      where upper(coalesce(finance_status, '')) = 'COD_SETTLED'
    ),

    'cod_settled_amount', (
      select coalesce(sum(coalesce(cod_collected, 0)), 0)
      from public.be_wayplan_dispatch_stops
      where upper(coalesce(finance_status, '')) = 'COD_SETTLED'
    ),

    'audit_dispatch_events', (
      select count(*)
      from public.be_governance_audit_log
      where module = 'DISPATCH'
    ),

    'audit_rider_events', (
      select count(*)
      from public.be_governance_audit_log
      where module = 'RIDER_APP'
    ),

    'audit_finance_cod_events', (
      select count(*)
      from public.be_governance_audit_log
      where module = 'FINANCE_COD'
    )
  )
  into v_summary;

  return jsonb_build_object(
    'ok', true,
    'source', 'be_dispatch_rider_finance_e2e_health',
    'generated_at', now(),
    'summary', v_summary,
    'status',
      case
        when coalesce((v_summary->>'capacity_available_workforce')::integer, 0) > 0
         and coalesce((v_summary->>'capacity_recommendations')::integer, 0) > 0
         and coalesce((v_summary->>'rider_assigned_jobs')::integer, 0) > 0
         and coalesce((v_summary->>'delivered_count')::integer, 0) > 0
         and coalesce((v_summary->>'cod_settled_count')::integer, 0) > 0
         and coalesce((v_summary->>'audit_rider_events')::integer, 0) > 0
         and coalesce((v_summary->>'audit_finance_cod_events')::integer, 0) > 0
        then 'READY'
        else 'CHECK_REQUIRED'
      end,
    'capacity', v_capacity->'summary',
    'rider_jobs', v_rider_jobs->'summary',
    'finance_queue', v_finance_queue->'summary'
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_dispatch_start_wayplan(p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_wayplan_id text := nullif(p_payload->>'wayplan_id', '');
begin
  if v_wayplan_id is null then
    return jsonb_build_object('ok', false, 'error', 'wayplan_id is required');
  end if;

  update public.be_wayplan_dispatches
  set
    wayplan_status = 'DISPATCHED',
    dispatched_at = now(),
    updated_at = now()
  where wayplan_id = v_wayplan_id;

  update public.be_wayplan_dispatch_stops
  set
    stop_status = 'DISPATCHED',
    updated_at = now()
  where wayplan_id = v_wayplan_id;

  update public.be_waybill_ledger
  set
    dispatch_status = 'DISPATCHED',
    wayplan_status = 'DISPATCHED',
    updated_at = now()
  where wayplan_id = v_wayplan_id;

  update public.be_portal_pickup_requests
  set
    dispatch_status = 'DISPATCHED',
    wayplan_status = 'DISPATCHED',
    updated_at = now()
  where wayplan_id = v_wayplan_id;

  return jsonb_build_object(
    'ok', true,
    'wayplan_id', v_wayplan_id,
    'status', 'DISPATCHED'
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_dispatch_summary(p_branch text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
DECLARE v_role TEXT := public.be_current_user_role();
BEGIN
  IF v_role NOT IN ('admin','operation_manager','dispatch','supervisor') THEN RAISE EXCEPTION 'Access denied'; END IF;
  RETURN (SELECT json_build_object(
    'unassigned', (SELECT COUNT(*) FROM public.be_portal_pickup_requests WHERE assigned_rider_id IS NULL AND status IN ('IN_WAREHOUSE','SUBMITTED','PICKED_UP') AND (p_branch IS NULL OR branch_code=p_branch)),
    'in_transit', (SELECT COUNT(*) FROM public.be_portal_pickup_requests WHERE status='IN_TRANSIT' AND (p_branch IS NULL OR branch_code=p_branch)),
    'delivered_today', (SELECT COUNT(*) FROM public.be_portal_pickup_requests WHERE status='DELIVERED' AND created_at::DATE=CURRENT_DATE AND (p_branch IS NULL OR branch_code=p_branch)),
    'failed_today', (SELECT COUNT(*) FROM public.be_portal_pickup_requests WHERE status='FAILED_DELIVERY' AND updated_at::DATE=CURRENT_DATE AND (p_branch IS NULL OR branch_code=p_branch)),
    'active_riders', (SELECT COUNT(*) FROM public.be_user_account_registry WHERE role IN ('rider','driver') AND status='active' AND (p_branch IS NULL OR branch_code=p_branch))
  ));
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_dispatch_unassigned(p_branch text DEFAULT NULL::text, p_limit integer DEFAULT 100)
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
DECLARE v_role TEXT := public.be_current_user_role();
BEGIN
  IF v_role NOT IN ('admin','operation_manager','dispatch','supervisor') THEN RAISE EXCEPTION 'Access denied'; END IF;
  RETURN (SELECT COALESCE(json_agg(row_to_json(t)),'[]'::json) FROM (
    SELECT pickup_id, waybill_no, merchant_name,
           recipient_name, recipient_phone, delivery_address, delivery_township,
           service_tier, priority, payment_method, cod_amount, delivery_fee, branch_code, created_at
    FROM public.be_portal_pickup_requests
    WHERE assigned_rider_id IS NULL
      AND status IN ('IN_WAREHOUSE','SUBMITTED','PICKED_UP')
      AND (p_branch IS NULL OR branch_code=p_branch)
    ORDER BY CASE priority WHEN 'SAME_DAY' THEN 1 WHEN 'EXPRESS' THEN 2 ELSE 3 END, created_at ASC
    LIMIT p_limit
  ) t);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_dispatch_workforce(p_branch text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
DECLARE v_role TEXT := public.be_current_user_role();
BEGIN
  IF v_role NOT IN ('admin','operation_manager','dispatch','supervisor') THEN RAISE EXCEPTION 'Access denied'; END IF;
  RETURN (SELECT COALESCE(json_agg(row_to_json(t)),'[]'::json) FROM (
    SELECT u.user_id, u.full_name, u.role, u.phone_number, u.branch_code,
           u.vehicle_type, u.license_plate,
           COUNT(p.pickup_id) FILTER (WHERE p.status='IN_TRANSIT') AS active_assignments,
           COUNT(p.pickup_id) FILTER (WHERE p.status='DELIVERED' AND p.created_at::DATE=CURRENT_DATE) AS delivered_today,
           u.status AS availability_status
    FROM public.be_user_account_registry u
    LEFT JOIN public.be_portal_pickup_requests p ON p.assigned_rider_id::TEXT = u.user_id::TEXT
    WHERE u.role IN ('rider','driver') AND u.status='active'
      AND (p_branch IS NULL OR u.branch_code=p_branch)
    GROUP BY u.user_id, u.full_name, u.role, u.phone_number, u.branch_code, u.vehicle_type, u.license_plate, u.status
    ORDER BY active_assignments ASC, u.full_name
  ) t);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_document_print_approval_center(p_limit integer DEFAULT 200)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_requests jsonb;
  v_logs jsonb;
  v_summary jsonb;
begin
  select coalesce(jsonb_agg(to_jsonb(r) order by r.created_at desc), '[]'::jsonb)
  into v_requests
  from (
    select *
    from public.be_document_print_approval_requests
    order by created_at desc
    limit greatest(coalesce(p_limit, 200), 1)
  ) r;

  select coalesce(jsonb_agg(to_jsonb(l) order by l.created_at desc), '[]'::jsonb)
  into v_logs
  from (
    select *
    from public.be_document_print_log
    order by created_at desc
    limit greatest(coalesce(p_limit, 200), 1)
  ) l;

  select jsonb_build_object(
    'pending', count(*) filter (where approval_status = 'PENDING'),
    'approved', count(*) filter (where approval_status = 'APPROVED'),
    'consumed', count(*) filter (where consumed_at is not null),
    'waybill_pending', count(*) filter (where document_type = 'WAYBILL' and approval_status = 'PENDING'),
    'invoice_pending', count(*) filter (where document_type = 'INVOICE' and approval_status = 'PENDING')
  )
  into v_summary
  from public.be_document_print_approval_requests;

  return jsonb_build_object(
    'ok', true,
    'source', 'be_document_print_approval_center',
    'summary', coalesce(v_summary, '{}'::jsonb),
    'requests', v_requests,
    'logs', v_logs
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_document_print_approve(p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor_email text := nullif(p_payload->>'actor_email', '');
  v_actor_role text := nullif(p_payload->>'actor_role', '');
  v_ctx jsonb;
  v_document_type text := upper(nullif(p_payload->>'document_type', ''));
  v_document_no text := nullif(p_payload->>'document_no', '');
  v_note text := nullif(p_payload->>'decision_note', '');
  v_count integer := 0;
begin
  v_ctx := public.be_require_admin(v_actor_email, v_actor_role);

  update public.be_document_print_approval_requests
  set
    approval_status = 'APPROVED',
    approved_by = coalesce(v_actor_email, v_ctx->>'email'),
    approved_at = now(),
    decision_note = coalesce(v_note, decision_note),
    updated_at = now()
  where document_type = v_document_type
    and document_no = v_document_no
    and approval_status = 'PENDING'
    and consumed_at is null;

  get diagnostics v_count = row_count;

  perform public.be_write_governance_audit(
    'PRINT_APPROVAL',
    'REPRINT_APPROVED',
    'be_document_print_approval_requests',
    v_document_no,
    coalesce(v_actor_email, v_ctx->>'email'),
    '{}'::jsonb,
    jsonb_build_object(
      'document_type', v_document_type,
      'document_no', v_document_no,
      'approved_requests', v_count
    ),
    jsonb_build_object(
      'actor', v_ctx,
      'decision_note', v_note
    )
  );

  return jsonb_build_object(
    'ok', true,
    'approved_requests', v_count,
    'document_type', v_document_type,
    'document_no', v_document_no,
    'actor', v_ctx
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_document_print_governance_dashboard(p_limit integer DEFAULT 200)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_logs jsonb := '[]'::jsonb;
  v_requests jsonb := '[]'::jsonb;
  v_audit jsonb := '[]'::jsonb;
  v_summary jsonb := '{}'::jsonb;
begin
  select coalesce(jsonb_agg(to_jsonb(t)), '[]'::jsonb)
  into v_logs
  from (
    select *
    from public.be_document_print_log
    order by created_at desc nulls last
    limit greatest(coalesce(p_limit, 200), 1)
  ) t;

  select coalesce(jsonb_agg(to_jsonb(t)), '[]'::jsonb)
  into v_requests
  from (
    select *
    from public.be_document_print_approval_requests
    order by created_at desc nulls last
    limit greatest(coalesce(p_limit, 200), 1)
  ) t;

  select coalesce(jsonb_agg(to_jsonb(t)), '[]'::jsonb)
  into v_audit
  from (
    select
      module,
      action,
      ref_id,
      actor_email,
      after_data,
      created_at
    from public.be_governance_audit_log
    where module in ('DOCUMENT_PRINT','PRINT_APPROVAL')
    order by created_at desc
    limit greatest(coalesce(p_limit, 200), 1)
  ) t;

  select jsonb_build_object(
    'total_print_logs', (
      select count(*)
      from public.be_document_print_log
    ),
    'waybill_print_logs', (
      select count(*)
      from public.be_document_print_log
      where upper(coalesce(document_type, '')) = 'WAYBILL'
    ),
    'invoice_print_logs', (
      select count(*)
      from public.be_document_print_log
      where upper(coalesce(document_type, '')) = 'INVOICE'
    ),
    'manifest_print_logs', (
      select count(*)
      from public.be_document_print_log
      where upper(coalesce(document_type, '')) = 'MANIFEST'
    ),
    'pending_approvals', (
      select count(*)
      from public.be_document_print_approval_requests
      where upper(coalesce(approval_status, '')) = 'PENDING'
    ),
    'approved_approvals', (
      select count(*)
      from public.be_document_print_approval_requests
      where upper(coalesce(approval_status, '')) = 'APPROVED'
    ),
    'rejected_approvals', (
      select count(*)
      from public.be_document_print_approval_requests
      where upper(coalesce(approval_status, '')) = 'REJECTED'
    ),
    'consumed_approvals', (
      select count(*)
      from public.be_document_print_approval_requests
      where consumed_at is not null
    ),
    'open_approved_reprints', (
      select count(*)
      from public.be_document_print_approval_requests
      where upper(coalesce(approval_status, '')) = 'APPROVED'
        and consumed_at is null
    ),
    'document_print_audit_events', (
      select count(*)
      from public.be_governance_audit_log
      where module = 'DOCUMENT_PRINT'
    ),
    'print_approval_audit_events', (
      select count(*)
      from public.be_governance_audit_log
      where module = 'PRINT_APPROVAL'
    )
  )
  into v_summary;

  return jsonb_build_object(
    'ok', true,
    'source', 'be_document_print_governance_dashboard',
    'generated_at', now(),
    'summary', v_summary,
    'logs', v_logs,
    'approval_requests', v_requests,
    'audit', v_audit,
    'status',
      case
        when coalesce((v_summary->>'document_print_audit_events')::integer, 0) > 0
          or coalesce((v_summary->>'pending_approvals')::integer, 0) > 0
          or coalesce((v_summary->>'approved_approvals')::integer, 0) > 0
        then 'READY'
        else 'CHECK_REQUIRED'
      end
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_document_print_guard(p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_type text := upper(coalesce(p_payload->>'document_type', 'WAYBILL'));
  v_no text := nullif(coalesce(p_payload->>'document_no', p_payload->>'waybill_no', p_payload->>'invoice_no'), '');
  v_actor text := nullif(p_payload->>'actor_email', '');
  v_role text := lower(coalesce(p_payload->>'actor_role', 'operator'));
  v_department text := lower(coalesce(p_payload->>'department', 'operation'));
  v_reason text := nullif(p_payload->>'reason', '');
  v_existing integer := 0;
  v_has_approval boolean := false;
begin
  if v_no is null then
    raise exception 'document_no is required';
  end if;

  select count(*)
  into v_existing
  from public.be_document_print_log
  where document_type = v_type
    and document_no = v_no;

  if v_existing = 0 then
    if v_type = 'WAYBILL' and v_department not in ('operation','warehouse','data entry','data_entry','superadmin') and v_role <> 'superadmin' then
      raise exception 'Waybill first print is allowed only for operator/warehouse/data-entry or superadmin';
    end if;

    if v_type = 'INVOICE' and v_department not in ('finance','superadmin') and v_role <> 'superadmin' then
      raise exception 'Invoice first print is allowed only for finance or superadmin';
    end if;

    insert into public.be_document_print_log (
      document_type,
      document_no,
      document_ref,
      printed_by,
      printed_by_role,
      department,
      print_count,
      approval_required,
      approval_status,
      reason,
      metadata
    )
    values (
      v_type,
      v_no,
      p_payload->>'document_ref',
      v_actor,
      v_role,
      v_department,
      1,
      false,
      'NOT_REQUIRED',
      v_reason,
      p_payload
    );

    return jsonb_build_object(
      'ok', true,
      'allowed', true,
      'document_type', v_type,
      'document_no', v_no,
      'print_count_before', 0,
      'message', 'First print allowed and recorded.'
    );
  end if;

  select exists (
    select 1
    from public.be_document_print_approval_requests
    where document_type = v_type
      and document_no = v_no
      and approval_status = 'APPROVED'
  )
  into v_has_approval;

  if v_role = 'superadmin' or v_has_approval then
    insert into public.be_document_print_log (
      document_type,
      document_no,
      document_ref,
      printed_by,
      printed_by_role,
      department,
      print_count,
      approval_required,
      approval_status,
      approved_by,
      approved_at,
      reason,
      metadata
    )
    values (
      v_type,
      v_no,
      p_payload->>'document_ref',
      v_actor,
      v_role,
      v_department,
      v_existing + 1,
      true,
      'APPROVED',
      case when v_role = 'superadmin' then v_actor else null end,
      case when v_role = 'superadmin' then now() else null end,
      v_reason,
      p_payload
    );

    return jsonb_build_object(
      'ok', true,
      'allowed', true,
      'document_type', v_type,
      'document_no', v_no,
      'print_count_before', v_existing,
      'message', 'Reprint allowed by approval/superadmin.'
    );
  end if;

  insert into public.be_document_print_approval_requests (
    document_type,
    document_no,
    requested_by,
    requested_by_role,
    department,
    request_reason
  )
  values (
    v_type,
    v_no,
    v_actor,
    v_role,
    v_department,
    coalesce(v_reason, 'Reprint request')
  );

  return jsonb_build_object(
    'ok', true,
    'allowed', false,
    'approval_required', true,
    'document_type', v_type,
    'document_no', v_no,
    'print_count_before', v_existing,
    'message', 'Reprint blocked. Superadmin approval request created.'
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_driver_assignment_response(p_payload jsonb)
