CREATE OR REPLACE FUNCTION public.be_driver_helper_settlement_snapshot(p_work_date date DEFAULT CURRENT_DATE, p_actor_email text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_work_date date := coalesce(p_work_date, current_date);
  v_base jsonb;
  v_rows jsonb;
  v_stats jsonb;
begin
  v_base := public.be_commission_settlement_snapshot(v_work_date, p_actor_email, true);

  select coalesce(jsonb_agg(to_jsonb(s) order by s.role_code, s.assignee_email, s.operation_type), '[]'::jsonb)
  into v_rows
  from public.be_v_commission_settlement s
  where s.work_date = v_work_date
    and s.role_code in ('DRIVER','HELPER');

  select jsonb_build_object(
    'work_date', v_work_date,
    'driver_commission', coalesce(sum(commission_mmk) filter (where role_code = 'DRIVER'),0),
    'helper_commission', coalesce(sum(commission_mmk) filter (where role_code = 'HELPER'),0),
    'total_commission', coalesce(sum(commission_mmk),0),
    'driver_units', coalesce(sum(total_units) filter (where role_code = 'DRIVER'),0),
    'helper_units', coalesce(sum(total_units) filter (where role_code = 'HELPER'),0),
    'rows', count(*)
  )
  into v_stats
  from public.be_v_commission_settlement s
  where s.work_date = v_work_date
    and s.role_code in ('DRIVER','HELPER');

  return jsonb_build_object('ok', true, 'stats', v_stats, 'rows', v_rows, 'rates', v_base -> 'rates');
end;
$function$
;

create or replace view "public"."be_drivers" as  SELECT record_key AS id,
    record_key AS driver_id,
    record_key AS driver_code,
    record_key AS code,
    COALESCE((payload ->> 'driver_name'::text), (payload ->> 'name'::text), record_key) AS driver_name,
    COALESCE((payload ->> 'driver_name'::text), (payload ->> 'name'::text), record_key) AS name,
    COALESCE((payload ->> 'driver_name'::text), (payload ->> 'name'::text), record_key) AS label,
    COALESCE((payload ->> 'driver_name'::text), (payload ->> 'name'::text), record_key) AS display_name,
    COALESCE((payload ->> 'phone_primary'::text), (payload ->> 'phone'::text)) AS phone,
    'ACTIVE'::text AS status,
    true AS active,
    true AS is_active,
    true AS available,
    true AS is_available,
    payload,
    updated_at
   FROM public.be_master_data_rows
  WHERE ((dataset_key = 'driver_master'::text) AND (deleted_at IS NULL) AND (lower(COALESCE((payload ->> 'status'::text), status, 'active'::text)) <> 'inactive'::text));


CREATE OR REPLACE FUNCTION public.be_employee_master_upsert(p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_rows jsonb := coalesce(p_payload->'rows', '[]'::jsonb);
  v_row jsonb;
  v_count integer := 0;
  v_employee_id text;
  v_email text;
  v_force_password_change boolean;
  v_is_active boolean;
begin
  if jsonb_typeof(v_rows) <> 'array' then
    raise exception 'rows must be an array';
  end if;

  for v_row in select * from jsonb_array_elements(v_rows)
  loop
    v_employee_id := nullif(coalesce(
      v_row->>'employee_id',
      v_row->>'employee_code',
      v_row->>'id'
    ), '');

    v_email := nullif(coalesce(
      v_row->>'email',
      v_row->>'account'
    ), '');

    v_force_password_change :=
      lower(coalesce(v_row->>'force_password_change', 'false')) in ('true','t','yes','1');

    v_is_active :=
      lower(coalesce(v_row->>'is_active', 'true')) not in ('false','f','no','0','inactive');

    insert into public.be_employee_master (
      employee_id,
      employee_code,
      account,
      email,
      display_name,
      full_name,
      name,
      designation,
      role_label,
      app_role,
      role_id,
      department,
      branch_code,
      workforce_type,
      phone_e164,
      status,
      is_active,
      force_password_change,
      auth_user_id,
      metadata,
      updated_at
    )
    values (
      coalesce(v_employee_id, 'EMP-' || to_char(now(), 'YYYYMMDDHH24MISS') || '-' || v_count::text),
      nullif(v_row->>'employee_code', ''),
      nullif(v_row->>'account', ''),
      v_email,
      coalesce(nullif(v_row->>'display_name', ''), nullif(v_row->>'full_name', ''), nullif(v_row->>'name', '')),
      coalesce(nullif(v_row->>'full_name', ''), nullif(v_row->>'display_name', ''), nullif(v_row->>'name', '')),
      coalesce(nullif(v_row->>'name', ''), nullif(v_row->>'full_name', ''), nullif(v_row->>'display_name', '')),
      nullif(v_row->>'designation', ''),
      nullif(v_row->>'role_label', ''),
      nullif(v_row->>'app_role', ''),
      nullif(v_row->>'role_id', ''),
      nullif(v_row->>'department', ''),
      coalesce(nullif(v_row->>'branch_code', ''), 'YGN'),
      nullif(v_row->>'workforce_type', ''),
      nullif(v_row->>'phone_e164', ''),
      coalesce(nullif(v_row->>'status', ''), 'active'),
      v_is_active,
      v_force_password_change,
      nullif(v_row->>'auth_user_id', '')::uuid,
      case
        when coalesce(v_row->>'metadata', '') like '{%' then (v_row->>'metadata')::jsonb
        else v_row
      end,
      now()
    )
    on conflict (email) do update set
      employee_id = coalesce(excluded.employee_id, public.be_employee_master.employee_id),
      employee_code = excluded.employee_code,
      account = excluded.account,
      display_name = excluded.display_name,
      full_name = excluded.full_name,
      name = excluded.name,
      designation = excluded.designation,
      role_label = excluded.role_label,
      app_role = excluded.app_role,
      role_id = excluded.role_id,
      department = excluded.department,
      branch_code = excluded.branch_code,
      workforce_type = excluded.workforce_type,
      phone_e164 = excluded.phone_e164,
      status = excluded.status,
      is_active = excluded.is_active,
      force_password_change = excluded.force_password_change,
      auth_user_id = excluded.auth_user_id,
      metadata = excluded.metadata,
      updated_at = now();

    v_count := v_count + 1;
  end loop;

  return jsonb_build_object(
    'ok', true,
    'source', 'be_employee_master_upsert',
    'upserted_rows', v_count
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_enterprise_complete_wireup_health()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_modules jsonb := '[]'::jsonb;
  v_summary jsonb := '{}'::jsonb;
  v_ready_count integer := 0;
  v_warning_count integer := 0;
  v_error_count integer := 0;
  v_total_count integer := 0;

  v_pickup jsonb := '{}'::jsonb;
  v_readiness jsonb := '{}'::jsonb;
  v_e2e jsonb := '{}'::jsonb;
  v_print jsonb := '{}'::jsonb;
begin
  ---------------------------------------------------------------------------
  -- 1. CS Pickup Request / Canonical ID / Tariff / Branch Routing
  ---------------------------------------------------------------------------
  begin
    select public.be_process_router(
      'pickup.create',
      jsonb_build_object(
        'dry_run', true,
        'merchant_code', 'ZZE',
        'merchant_name', 'Zan Zan Export Clothings',
        'parcel_count', 6,
        'pickup_weight_kg', 2.5,
        'service_tier', 'STANDARD',
        'pickup_city', 'Yangon',
        'pickup_township', 'Shwe Pyi Thar',
        'created_at', now()
      )
    )
    into v_pickup;

    v_modules := v_modules || jsonb_build_array(
      jsonb_build_object(
        'module', 'CS Pickup Request / Canonical ID',
        'status',
          case
            when coalesce(v_pickup->>'ok','false') = 'true'
             and coalesce(v_pickup#>>'{canonical_ids,pickup_id}','') ~ '-006$'
            then 'READY'
            else 'WARNING'
          end,
        'ready',
          coalesce(v_pickup->>'ok','false') = 'true'
          and coalesce(v_pickup#>>'{canonical_ids,pickup_id}','') ~ '-006$',
        'summary', jsonb_build_object(
          'pickup_id', v_pickup#>>'{canonical_ids,pickup_id}',
          'parcel_count', v_pickup#>>'{canonical_ids,pickup_parcel_count}',
          'assigned_branch', v_pickup->>'assigned_branch',
          'tariff', v_pickup->'tariff'
        ),
        'detail', v_pickup
      )
    );
  exception when others then
    v_modules := v_modules || jsonb_build_array(
      jsonb_build_object(
        'module', 'CS Pickup Request / Canonical ID',
        'status', 'ERROR',
        'ready', false,
        'error', sqlerrm
      )
    );
  end;

  ---------------------------------------------------------------------------
  -- 2. Production Readiness Plus
  ---------------------------------------------------------------------------
  begin
    select public.be_production_readiness_dashboard_plus(
      'mgkyawwanna@gmail.com',
      'superadmin'
    )
    into v_readiness;

    v_modules := v_modules || jsonb_build_array(
      jsonb_build_object(
        'module', 'Production Readiness Plus',
        'status', coalesce(v_readiness->>'status', 'CHECK_REQUIRED'),
        'ready', coalesce(v_readiness->>'status','') = 'READY',
        'summary', v_readiness->'summary',
        'detail', v_readiness
      )
    );
  exception when others then
    v_modules := v_modules || jsonb_build_array(
      jsonb_build_object(
        'module', 'Production Readiness Plus',
        'status', 'ERROR',
        'ready', false,
        'error', sqlerrm
      )
    );
  end;

  ---------------------------------------------------------------------------
  -- 3. Dispatch / Rider / Finance E2E
  ---------------------------------------------------------------------------
  begin
    select public.be_dispatch_rider_finance_e2e_health()
    into v_e2e;

    v_modules := v_modules || jsonb_build_array(
      jsonb_build_object(
        'module', 'Dispatch Rider Finance E2E',
        'status', coalesce(v_e2e->>'status', 'CHECK_REQUIRED'),
        'ready', coalesce(v_e2e->>'status','') = 'READY',
        'summary', v_e2e->'summary',
        'detail', v_e2e
      )
    );
  exception when others then
    v_modules := v_modules || jsonb_build_array(
      jsonb_build_object(
        'module', 'Dispatch Rider Finance E2E',
        'status', 'ERROR',
        'ready', false,
        'error', sqlerrm
      )
    );
  end;

  ---------------------------------------------------------------------------
  -- 4. Document Print Governance
  ---------------------------------------------------------------------------
  begin
    select public.be_document_print_governance_dashboard(100)
    into v_print;

    v_modules := v_modules || jsonb_build_array(
      jsonb_build_object(
        'module', 'Waybill / Invoice / Manifest Print Governance',
        'status', coalesce(v_print->>'status', 'CHECK_REQUIRED'),
        'ready', coalesce(v_print->>'status','') = 'READY',
        'summary', v_print->'summary',
        'detail', v_print
      )
    );
  exception when others then
    v_modules := v_modules || jsonb_build_array(
      jsonb_build_object(
        'module', 'Waybill / Invoice / Manifest Print Governance',
        'status', 'ERROR',
        'ready', false,
        'error', sqlerrm
      )
    );
  end;

  ---------------------------------------------------------------------------
  -- 5. Function / Process Existence Checks
  ---------------------------------------------------------------------------
  with required_functions as (
    select *
    from (
      values
        ('CS Pickup Request', 'be_submit_pickup_request'),
        ('CS Pickup Request Portal', 'be_create_pickup_request_from_portal'),
        ('Supervisor Assignment', 'be_assign_pickup_request'),
        ('Supervisor Pickup Queue', 'be_supervisor_pickup_assignment_queue'),
        ('Rider Pickup Queue', 'be_rider_pickup_queue'),
        ('Rider Pickup Action', 'be_rider_pickup_action'),
        ('Rider Verification', 'be_rider_verify_pickup'),
        ('Data Entry Queue', 'be_data_entry_pickup_queue'),
        ('Data Entry Submit Parcels', 'be_data_entry_submit_pickup_parcels'),
        ('Operational ID Generator', 'be_make_operational_ids_v2'),
        ('Waybill Print Guard', 'be_document_print_guard'),
        ('Print Approval', 'be_document_print_approve'),
        ('Wayplan Command Center', 'be_enterprise_dispatch_center'),
        ('Dispatch Action', 'be_enterprise_dispatch_action'),
        ('Dispatch Capacity Recommend', 'be_enterprise_dispatch_capacity_recommend'),
        ('Route Optimize', 'be_enterprise_dispatch_route_optimize'),
        ('Warehouse Center', 'be_enterprise_warehouse_center'),
        ('Warehouse Action', 'be_enterprise_warehouse_action'),
        ('Rider Delivery Jobs', 'be_rider_route_jobs'),
        ('Rider Delivery Update', 'be_rider_route_job_update'),
        ('Finance COD Queue', 'be_finance_rider_cod_settlement_queue'),
        ('Finance COD Settle', 'be_finance_rider_cod_settle'),
        ('Commission Center', 'be_production_readiness_dashboard_plus'),
        ('Master Data', 'be_master_data_page_snapshot'),
        ('Branch Office', 'be_branch_office_snapshot'),
        ('Governance Approval', 'be_governance_approval_center'),
        ('Admin HR Save', 'be_hr_employee_save_audited'),
        ('Master Data Save', 'be_master_entity_save_audited'),
        ('KPI / Audit Snapshot', 'be_portal_wiring_health')
    ) as x(module, function_name)
  ),
  checked as (
    select
      rf.module,
      rf.function_name,
      exists (
        select 1
        from pg_proc p
        join pg_namespace n on n.oid = p.pronamespace
        where n.nspname = 'public'
          and p.proname = rf.function_name
      ) as exists_ok
    from required_functions rf
  )
  select v_modules || jsonb_agg(
    jsonb_build_object(
      'module', module,
      'function_name', function_name,
      'status', case when exists_ok then 'READY' else 'ERROR' end,
      'ready', exists_ok
    )
    order by module
  )
  into v_modules
  from checked;

  ---------------------------------------------------------------------------
  -- 6. Table / Ledger Existence Checks
  ---------------------------------------------------------------------------
  with required_tables as (
    select *
    from (
      values
        ('Pickup Requests', 'be_portal_pickup_requests'),
        ('Pickup Core Requests', 'be_pickup_requests'),
        ('Notifications', 'be_app_notifications'),
        ('Cargo Events / Timeline', 'be_portal_cargo_events'),
        ('Waybill Ledger', 'be_waybill_ledger'),
        ('Wayplan Dispatches', 'be_wayplan_dispatches'),
        ('Wayplan Dispatch Stops', 'be_wayplan_dispatch_stops'),
        ('Warehouse Exception Rules', 'be_logistics_exception_rules'),
        ('Document Print Log', 'be_document_print_log'),
        ('Document Print Approvals', 'be_document_print_approval_requests'),
        ('Governance Audit Log', 'be_governance_audit_log'),
        ('Workforce Accounts', 'be_workforce_accounts'),
        ('Dispatch Capacity Rules', 'be_dispatch_capacity_rules'),
        ('Master Data Records', 'be_master_entity_records'),
        ('Branch Offices', 'be_branch_offices'),
        ('Branch Staff', 'be_branch_staff'),
        ('Branch Amendments', 'be_branch_amendment_requests'),
        ('Employee Master', 'be_employee_master'),
        ('UAT Evidence', 'be_uat_test_evidence')
    ) as x(module, table_name)
  ),
  checked as (
    select
      rt.module,
      rt.table_name,
      exists (
        select 1
        from information_schema.tables t
        where t.table_schema = 'public'
          and t.table_name = rt.table_name
          and t.table_type = 'BASE TABLE'
      ) as exists_ok
    from required_tables rt
  )
  select v_modules || jsonb_agg(
    jsonb_build_object(
      'module', module,
      'table_name', table_name,
      'status', case when exists_ok then 'READY' else 'ERROR' end,
      'ready', exists_ok
    )
    order by module
  )
  into v_modules
  from checked;

  ---------------------------------------------------------------------------
  -- 7. Pickup ID Rule Audit
  ---------------------------------------------------------------------------
  v_modules := v_modules || jsonb_build_array(
    jsonb_build_object(
      'module', 'Pickup Way ID Parcel Count Rule',
      'status',
        case
          when exists (
            select 1
            from public.be_pickupway_normalized_rows()
            where greatest(
                coalesce(parcel_count, 1),
                coalesce(expected_parcels, 1)
              ) > 1
              and coalesce(pickup_way_id, pickup_id, request_code, '') ~ '-001$'
          )
          then 'WARNING'
          else 'READY'
        end,
      'ready',
        not exists (
          select 1
          from public.be_pickupway_normalized_rows()
          where greatest(
              coalesce(parcel_count, 1),
              coalesce(expected_parcels, 1)
            ) > 1
            and coalesce(pickup_way_id, pickup_id, request_code, '') ~ '-001$'
        ),
      'summary', jsonb_build_object(
        'rule', 'Pickup suffix must equal total pickup parcel count',
        'bad_rows', (
          select count(*)
          from public.be_pickupway_normalized_rows()
          where greatest(
              coalesce(parcel_count, 1),
              coalesce(expected_parcels, 1)
            ) > 1
            and coalesce(pickup_way_id, pickup_id, request_code, '') ~ '-001$'
        )
      )
    )
  );

  ---------------------------------------------------------------------------
  -- Summary
  ---------------------------------------------------------------------------
  select
    count(*) filter (where upper(coalesce(m->>'status','')) = 'READY'),
    count(*) filter (where upper(coalesce(m->>'status','')) in ('WARNING','CHECK_REQUIRED')),
    count(*) filter (where upper(coalesce(m->>'status','')) in ('ERROR','FAILED','NOT_READY')),
    count(*)
  into
    v_ready_count,
    v_warning_count,
    v_error_count,
    v_total_count
  from jsonb_array_elements(v_modules) m;

  v_summary := jsonb_build_object(
    'total_modules', v_total_count,
    'ready_modules', v_ready_count,
    'warning_modules', v_warning_count,
    'error_modules', v_error_count,
    'pickup_rule_bad_rows', (
      select count(*)
      from public.be_pickupway_normalized_rows()
      where greatest(
          coalesce(parcel_count, 1),
          coalesce(expected_parcels, 1)
        ) > 1
        and coalesce(pickup_way_id, pickup_id, request_code, '') ~ '-001$'
    )
  );

  return jsonb_build_object(
    'ok', v_error_count = 0,
    'source', 'be_enterprise_complete_wireup_health',
    'status',
      case
        when v_error_count > 0 then 'ERROR'
        when v_warning_count > 0 then 'WARNING'
        else 'READY'
      end,
    'generated_at', now(),
    'summary', v_summary,
    'modules', v_modules
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_enterprise_control_tower(p_limit integer DEFAULT 300)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
with base as (
  select
    w.delivery_way_id,
    w.waybill_no,
    w.pickup_id,
    null::text as merchant_name,
    w.recipient_name,
    w.recipient_phone,
    w.township,
    w.address,

    null::text as warehouse_status,
    null::text as dispatch_status,
    w.wayplan_status,
    w.rider_status,

    w.wayplan_id,
    w.wayplan_status as route_status,
    w.stop_status,
    w.stop_sequence,
    w.loaded_to_vehicle_at,
    w.handed_over_to_rider_at,
    w.delivered_at,
    coalesce(w.cod_amount, 0) as cod_amount,
    coalesce(w.cod_collected, 0) as cod_collected,

    w.vehicle_code,
    w.vehicle_name,
    w.driver_code,
    w.driver_name,
    w.rider_code,
    w.rider_name,
    w.helper_code,
    w.helper_name,

    f.settlement_status,
    f.settlement_reference,
    f.settled_at,

    coalesce(w.handed_over_to_rider_at, w.loaded_to_vehicle_at, w.delivered_at, w.wayplan_created_at) as last_activity_at,

    case
      when f.settlement_status = 'SETTLED' then 'FINANCE_SETTLED'
      when w.stop_status = 'DELIVERED' then 'DELIVERED_PENDING_FINANCE'
      when w.stop_status in ('FAILED_DELIVERY', 'RETURN_TO_WAREHOUSE') then w.stop_status
      when w.stop_status = 'HANDOVER_TO_RIDER' then 'HANDED_TO_RIDER'
      when w.stop_status = 'LOADED_TO_VEHICLE' then 'LOADED_TO_VEHICLE'
      when w.stop_status = 'DISPATCHED' then 'DISPATCHED'
      when w.wayplan_status is not null then w.wayplan_status
      else 'UNKNOWN'
    end as enterprise_status
  from public.be_v_warehouse_wayplan_center w
  left join public.be_wayplan_cod_settlements f
    on f.delivery_way_id = w.delivery_way_id
),
limited as (
  select *
  from base
  order by last_activity_at desc nulls last
  limit greatest(coalesce(p_limit, 300), 1)
),
summary as (
  select jsonb_build_object(
    'total_records', count(*),
    'loaded_to_vehicle', count(*) filter (where enterprise_status = 'LOADED_TO_VEHICLE'),
    'handed_to_rider', count(*) filter (where enterprise_status = 'HANDED_TO_RIDER'),
    'dispatched', count(*) filter (where enterprise_status = 'DISPATCHED'),
    'delivered_pending_finance', count(*) filter (where enterprise_status = 'DELIVERED_PENDING_FINANCE'),
    'finance_settled', count(*) filter (where enterprise_status = 'FINANCE_SETTLED'),
    'failed_or_returned', count(*) filter (where enterprise_status in ('FAILED_DELIVERY', 'RETURN_TO_WAREHOUSE')),
    'total_cod_collected', coalesce(sum(cod_collected), 0)
  ) as data
  from base
),
rows_json as (
  select coalesce(jsonb_agg(to_jsonb(l) order by l.last_activity_at desc nulls last), '[]'::jsonb) as data
  from limited l
)
select jsonb_build_object(
  'ok', true,
  'source', 'be_enterprise_control_tower',
  'count', jsonb_array_length(rows_json.data),
  'summary', summary.data,
  'rows', rows_json.data
)
from rows_json, summary;
$function$
;

CREATE OR REPLACE FUNCTION public.be_enterprise_dispatch_action(p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_action text := upper(coalesce(p_payload->>'action', ''));
  v_target_id text := nullif(coalesce(
    p_payload->>'delivery_way_id',
    p_payload->>'waybill_no',
    p_payload->>'tracking_no',
    p_payload->>'stop_id'
  ), '');
  v_actor text := nullif(p_payload->>'actor_email', '');
  v_status text;
  v_updated integer := 0;
begin
  if v_action = '' then
    raise exception 'action is required';
  end if;

  if v_target_id is null then
    raise exception 'delivery_way_id, waybill_no, tracking_no, or stop_id is required';
  end if;

  v_status := case v_action
    when 'MARK_READY' then 'READY_FOR_DISPATCH'
    when 'LOAD_TO_VEHICLE' then 'LOADED_TO_VEHICLE'
    when 'HANDOVER_TO_RIDER' then 'OUT_FOR_DELIVERY'
    when 'OUT_FOR_DELIVERY' then 'OUT_FOR_DELIVERY'
    when 'CANCEL_STOP' then 'CANCELLED'
    else v_action
  end;

  if public.be_table_exists('be_wayplan_dispatch_stops') then
    update public.be_wayplan_dispatch_stops
    set
      stop_status = case
        when public.be_column_exists('be_wayplan_dispatch_stops', 'stop_status') then v_status
        else stop_status
      end,
      warehouse_status = case
        when public.be_column_exists('be_wayplan_dispatch_stops', 'warehouse_status') then v_status
        else warehouse_status
      end,
      updated_at = case
        when public.be_column_exists('be_wayplan_dispatch_stops', 'updated_at') then now()
        else updated_at
      end
    where id::text = v_target_id
       or delivery_way_id = v_target_id
       or waybill_no = v_target_id
       or tracking_no = v_target_id;

    get diagnostics v_updated = row_count;
  end if;

  perform public.be_write_governance_audit(
    'DISPATCH',
    v_action,
    'be_wayplan_dispatch_stops',
    v_target_id,
    v_actor,
    '{}'::jsonb,
    jsonb_build_object(
      'action', v_action,
      'status', v_status,
      'updated_rows', v_updated,
      'payload', p_payload
    ),
    jsonb_build_object('source', 'be_enterprise_dispatch_action')
  );

  return jsonb_build_object(
    'ok', true,
    'source', 'be_enterprise_dispatch_action',
    'action', v_action,
    'target_id', v_target_id,
    'status', v_status,
    'updated_rows', v_updated
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_enterprise_dispatch_allocation_apply(p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_target_id text := nullif(coalesce(
    p_payload->>'target_id',
    p_payload->>'delivery_way_id',
    p_payload->>'waybill_no',
    p_payload->>'tracking_no'
  ), '');
  v_assignee_email text := nullif(coalesce(
    p_payload->>'assignee_email',
    p_payload->>'recommended_assignee_email'
  ), '');
  v_assignee_name text := nullif(coalesce(
    p_payload->>'assignee_name',
    p_payload->>'recommended_assignee_name'
  ), '');
  v_assignee_type text := lower(coalesce(
    p_payload->>'assignee_type',
    p_payload->>'recommended_assignee_type',
    'rider'
  ));
  v_actor text := nullif(p_payload->>'actor_email', '');
  v_updated integer := 0;
  v_sql text;
begin
  if v_target_id is null then
    raise exception 'target_id, delivery_way_id, waybill_no, or tracking_no is required';
  end if;

  if v_assignee_email is null then
    raise exception 'assignee_email is required';
  end if;

  if public.be_table_exists('be_wayplan_dispatch_stops') then
    v_sql := 'update public.be_wayplan_dispatch_stops set ';

    if public.be_column_exists('be_wayplan_dispatch_stops', 'assigned_to') then
      v_sql := v_sql || 'assigned_to = ' || quote_literal(v_assignee_email) || ', ';
    end if;

    if public.be_column_exists('be_wayplan_dispatch_stops', 'rider_email') then
      v_sql := v_sql || 'rider_email = ' || quote_literal(v_assignee_email) || ', ';
    end if;

    if public.be_column_exists('be_wayplan_dispatch_stops', 'rider_name') then
      v_sql := v_sql || 'rider_name = ' || quote_literal(coalesce(v_assignee_name, v_assignee_email)) || ', ';
    end if;

    if public.be_column_exists('be_wayplan_dispatch_stops', 'rider_code') then
      v_sql := v_sql || 'rider_code = ' || quote_literal(v_assignee_email) || ', ';
    end if;

    if public.be_column_exists('be_wayplan_dispatch_stops', 'dispatch_status') then
      v_sql := v_sql || 'dispatch_status = ''ASSIGNED'', ';
    end if;

    if public.be_column_exists('be_wayplan_dispatch_stops', 'stop_status') then
      v_sql := v_sql || 'stop_status = ''ASSIGNED'', ';
    end if;

    if public.be_column_exists('be_wayplan_dispatch_stops', 'updated_at') then
      v_sql := v_sql || 'updated_at = now(), ';
    end if;

    v_sql := regexp_replace(v_sql, ',\s*$', '');

    v_sql := v_sql || '
      where id::text = $1
         or delivery_way_id = $1
         or waybill_no = $1
         or tracking_no = $1';

    execute v_sql using v_target_id;
    get diagnostics v_updated = row_count;
  end if;

  perform public.be_write_governance_audit(
    'DISPATCH',
    'ALLOCATION_APPLIED',
    'be_wayplan_dispatch_stops',
    v_target_id,
    v_actor,
    '{}'::jsonb,
    jsonb_build_object(
      'target_id', v_target_id,
      'assignee_email', v_assignee_email,
      'assignee_name', v_assignee_name,
      'assignee_type', v_assignee_type,
      'updated_rows', v_updated,
      'payload', p_payload
    ),
    jsonb_build_object('source', 'be_enterprise_dispatch_allocation_apply')
  );

  return jsonb_build_object(
    'ok', true,
    'source', 'be_enterprise_dispatch_allocation_apply',
    'target_id', v_target_id,
    'assignee_email', v_assignee_email,
    'assignee_type', v_assignee_type,
    'updated_rows', v_updated
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_enterprise_dispatch_allocation_recommend(p_limit integer DEFAULT 300)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_stops jsonb := '[]'::jsonb;
  v_workforce jsonb := '[]'::jsonb;
  v_fleet jsonb := '[]'::jsonb;
  v_recommendations jsonb := '[]'::jsonb;
  v_summary jsonb := '{}'::jsonb;
begin
  v_stops := public.be_table_rows_json('be_wayplan_dispatch_stops', p_limit);
  v_workforce := public.be_table_rows_json('be_workforce_accounts', p_limit);
  v_fleet := public.be_table_rows_json('be_master_entity_records', p_limit);

  with stop_rows as (
    select
      row_number() over () as rn,
      s as stop_data,
      coalesce(
        s->>'delivery_way_id',
        s->>'waybill_no',
        s->>'tracking_no',
        s->>'id'
      ) as target_id,
      coalesce(
        s->>'branch_code',
        s->'warehouse_metadata'->>'branch_code',
        'YGN'
      ) as branch_code,
      coalesce(
        s->>'township',
        s->>'delivery_township',
        s->>'recipient_township',
        s->'metadata'->>'township',
        'UNKNOWN'
      ) as township,
      upper(coalesce(
        s->>'warehouse_status',
        s->>'stop_status',
        s->>'dispatch_status',
        'PENDING'
      )) as status
    from jsonb_array_elements(v_stops) s
  ),
  available_workforce as (
    select
      row_number() over (
        order by
          coalesce(w->>'branch_code', 'YGN'),
          coalesce(w->>'workforce_type', w->>'role', ''),
          coalesce(w->>'email', w->>'account', w->>'id', '')
      ) as rn,
      w as workforce_data,
      coalesce(w->>'email', w->>'account', w->>'id') as workforce_email,
      coalesce(w->>'display_name', w->>'full_name', w->>'name', w->>'email', 'Workforce') as workforce_name,
      lower(coalesce(w->>'workforce_type', w->>'role', w->>'app_role', 'rider')) as workforce_type,
      coalesce(w->>'branch_code', 'YGN') as branch_code
    from jsonb_array_elements(v_workforce) w
    where lower(coalesce(w->>'status', w->>'account_status', 'active')) in ('active','available','ready')
  ),
  allocatable_stops as (
    select *
    from stop_rows
    where status in (
      'READY_FOR_DISPATCH',
      'LOADED_TO_VEHICLE',
      'PENDING',
      'WAITING_ASSIGNMENT',
      'RECEIVED_AT_ORIGIN',
      'SORTING'
    )
  ),
  recommendations as (
    select
      st.target_id,
      st.branch_code,
      st.township,
      st.status,
      wf.workforce_email,
      wf.workforce_name,
      wf.workforce_type,
      jsonb_build_object(
        'target_id', st.target_id,
        'delivery_way_id', st.stop_data->>'delivery_way_id',
        'waybill_no', st.stop_data->>'waybill_no',
        'tracking_no', st.stop_data->>'tracking_no',
        'pickup_id', coalesce(st.stop_data->>'pickup_id', st.stop_data->>'pickup_way_id'),
        'branch_code', st.branch_code,
        'township', st.township,
        'current_status', st.status,
        'recommended_assignee_email', wf.workforce_email,
        'recommended_assignee_name', wf.workforce_name,
        'recommended_assignee_type', wf.workforce_type,
        'recommendation_reason',
          'Matched by branch and available workload rotation',
        'confidence_score',
          case
            when wf.branch_code = st.branch_code then 90
            else 65
          end,
        'stop_data', st.stop_data,
        'workforce_data', wf.workforce_data
      ) as recommendation
    from allocatable_stops st
    left join lateral (
      select *
      from available_workforce wf
      where wf.branch_code = st.branch_code
         or st.branch_code is null
      order by
        case when wf.branch_code = st.branch_code then 0 else 1 end,
        ((st.rn + wf.rn) % 11),
        wf.rn
      limit 1
    ) wf on true
  )
  select coalesce(jsonb_agg(recommendation), '[]'::jsonb)
  into v_recommendations
  from recommendations;

  select jsonb_build_object(
    'total_stops', coalesce(jsonb_array_length(v_stops), 0),
    'available_workforce', coalesce(jsonb_array_length(v_workforce), 0),
    'recommendations', coalesce(jsonb_array_length(v_recommendations), 0),
    'unassigned_recommendations', (
      select count(*)
      from jsonb_array_elements(v_recommendations) r
      where coalesce(r->>'recommended_assignee_email', '') = ''
    )
  )
  into v_summary;

  return jsonb_build_object(
    'ok', true,
    'source', 'be_enterprise_dispatch_allocation_recommend',
    'generated_at', now(),
    'summary', v_summary,
    'recommendations', v_recommendations
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_enterprise_dispatch_capacity_recommend(p_limit integer DEFAULT 300)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_stops jsonb := '[]'::jsonb;
  v_workforce jsonb := '[]'::jsonb;
  v_rules jsonb := '[]'::jsonb;
  v_recommendations jsonb := '[]'::jsonb;
  v_summary jsonb := '{}'::jsonb;
begin
  v_stops := public.be_table_rows_json('be_wayplan_dispatch_stops', p_limit);
  v_workforce := public.be_table_rows_json('be_workforce_accounts', p_limit);
  v_rules := public.be_table_rows_json('be_dispatch_capacity_rules', p_limit);

  with stop_rows as (
    select
      row_number() over () as rn,
      s as stop_data,
      coalesce(
        s->>'delivery_way_id',
        s->>'waybill_no',
        s->>'tracking_no',
        s->>'id'
      ) as target_id,
      coalesce(
        s->>'branch_code',
        s->'warehouse_metadata'->>'branch_code',
        s->'metadata'->>'branch_code',
        'YGN'
      ) as branch_code,
      coalesce(
        s->>'township',
        s->>'delivery_township',
        s->>'recipient_township',
        s->'metadata'->>'township',
        'UNKNOWN'
      ) as township,
      upper(coalesce(
        s->>'warehouse_status',
        s->>'stop_status',
        s->>'dispatch_status',
        'PENDING'
      )) as current_status,
      case
        when coalesce(s->>'weight_kg', s->>'weight', '') ~ '^[0-9]+(\.[0-9]+)?$'
          then coalesce(s->>'weight_kg', s->>'weight')::numeric
        else 1
      end as weight_kg,
      case
        when coalesce(s->>'cod_amount', s->>'amount_to_collect', '') ~ '^[0-9]+(\.[0-9]+)?$'
          then coalesce(s->>'cod_amount', s->>'amount_to_collect')::numeric
        else 0
      end as cod_amount,
      coalesce(s->>'assigned_to', s->>'rider_email', '') as current_assignee
    from jsonb_array_elements(v_stops) s
  ),
  allocatable_stops as (
    select *
    from stop_rows
    where current_status in (
      'READY_FOR_DISPATCH',
      'LOADED_TO_VEHICLE',
      'PENDING',
      'WAITING_ASSIGNMENT',
      'RECEIVED_AT_ORIGIN',
      'SORTING',
      'ASSIGNED',
      'ROUTE_OPTIMIZED'
    )
  ),
  workforce_rows as (
    select
      row_number() over (
        order by
          coalesce(w->>'branch_code', 'YGN'),
          lower(coalesce(w->>'workforce_type', w->>'role', w->>'app_role', 'rider')),
          coalesce(w->>'email', w->>'account', w->>'id', '')
      ) as rn,
      w as workforce_data,
      coalesce(w->>'email', w->>'account', w->>'id') as workforce_email,
      coalesce(w->>'display_name', w->>'full_name', w->>'name', w->>'email', 'Workforce') as workforce_name,
      lower(coalesce(w->>'workforce_type', w->>'role', w->>'app_role', 'rider')) as workforce_type,
      coalesce(w->>'branch_code', 'YGN') as branch_code
    from jsonb_array_elements(v_workforce) w
    where lower(coalesce(w->>'status', w->>'account_status', 'active')) in ('active','available','ready')
  ),
  workload as (
    select
      current_assignee as assignee_email,
      count(*) as assigned_stops,
      coalesce(sum(weight_kg), 0) as assigned_weight_kg,
      coalesce(sum(cod_amount), 0) as assigned_cod_amount,
      count(distinct township) as assigned_townships
    from stop_rows
    where coalesce(current_assignee, '') <> ''
      and current_status not in ('DELIVERED','CANCELLED','RETURNED','FAILED')
    group by current_assignee
  ),
  matched as (
    select
      st.*,
      wf.workforce_email,
      wf.workforce_name,
      wf.workforce_type,
      wf.workforce_data,
      coalesce(wl.assigned_stops, 0) as assigned_stops,
      coalesce(wl.assigned_weight_kg, 0) as assigned_weight_kg,
      coalesce(wl.assigned_cod_amount, 0) as assigned_cod_amount,
      coalesce(wl.assigned_townships, 0) as assigned_townships,
      coalesce(rule.max_stops, 25) as max_stops,
      coalesce(rule.max_weight_kg, 80) as max_weight_kg,
      coalesce(rule.max_cod_amount, 3000000) as max_cod_amount,
      coalesce(rule.max_townships, 4) as max_townships,
      coalesce(rule.priority, 100) as rule_priority
    from allocatable_stops st
    left join lateral (
      select *
      from workforce_rows wf
      where wf.branch_code = st.branch_code
         or st.branch_code is null
      order by
        case
          when wf.workforce_type = 'rider' then 0
          when wf.workforce_type = 'driver' then 1
          when wf.workforce_type = 'helper' then 2
          else 9
        end,
        ((st.rn + wf.rn) % 17),
        wf.rn
      limit 10
    ) wf on true
    left join workload wl
      on wl.assignee_email = wf.workforce_email
    left join lateral (
      select *
      from public.be_dispatch_capacity_rules r
      where lower(r.workforce_type) = wf.workforce_type
        and coalesce(r.branch_code, st.branch_code) = st.branch_code
        and coalesce(r.is_active, true) = true
      order by r.priority asc
      limit 1
    ) rule on true
  ),
  scored as (
    select
      *,
      (
        assigned_stops < max_stops
        and assigned_weight_kg + weight_kg <= max_weight_kg
        and assigned_cod_amount + cod_amount <= max_cod_amount
        and assigned_townships <= max_townships
      ) as within_capacity,
      (
        case when branch_code = coalesce(workforce_data->>'branch_code', branch_code) then 35 else 10 end
        + case when assigned_stops < max_stops then 20 else 0 end
        + case when assigned_weight_kg + weight_kg <= max_weight_kg then 20 else 0 end
        + case when assigned_cod_amount + cod_amount <= max_cod_amount then 10 else 0 end
        + case when assigned_townships <= max_townships then 10 else 0 end
        + case when workforce_type = 'rider' then 5 else 0 end
      ) as confidence_score
    from matched
  ),
  best_match as (
    select distinct on (target_id)
      *
    from scored
    where workforce_email is not null
    order by
      target_id,
      within_capacity desc,
      confidence_score desc,
      assigned_stops asc,
      rule_priority asc
  ),
  recommendations as (
    select jsonb_build_object(
      'target_id', target_id,
      'delivery_way_id', stop_data->>'delivery_way_id',
      'waybill_no', stop_data->>'waybill_no',
      'tracking_no', stop_data->>'tracking_no',
      'pickup_id', coalesce(stop_data->>'pickup_id', stop_data->>'pickup_way_id'),
      'branch_code', branch_code,
      'township', township,
      'current_status', current_status,
      'weight_kg', weight_kg,
      'cod_amount', cod_amount,
      'recommended_assignee_email', workforce_email,
      'recommended_assignee_name', workforce_name,
      'recommended_assignee_type', workforce_type,
      'assigned_stops_before', assigned_stops,
      'assigned_weight_before', assigned_weight_kg,
      'assigned_cod_before', assigned_cod_amount,
      'max_stops', max_stops,
      'max_weight_kg', max_weight_kg,
      'max_cod_amount', max_cod_amount,
      'max_townships', max_townships,
      'within_capacity', within_capacity,
      'confidence_score', confidence_score,
      'recommendation_reason',
        case
          when within_capacity then 'Capacity-safe match by branch, workload, COD, and weight'
          else 'Best available match but capacity threshold needs supervisor review'
        end,
      'stop_data', stop_data,
      'workforce_data', workforce_data
    ) as recommendation
    from best_match
  )
  select coalesce(jsonb_agg(recommendation), '[]'::jsonb)
  into v_recommendations
  from recommendations;

  select jsonb_build_object(
    'total_stops', coalesce(jsonb_array_length(v_stops), 0),
    'available_workforce', coalesce(jsonb_array_length(v_workforce), 0),
    'capacity_rules', coalesce(jsonb_array_length(v_rules), 0),
    'recommendations', coalesce(jsonb_array_length(v_recommendations), 0),
    'within_capacity', (
      select count(*)
      from jsonb_array_elements(v_recommendations) r
      where coalesce((r->>'within_capacity')::boolean, false) = true
    ),
    'needs_review', (
      select count(*)
      from jsonb_array_elements(v_recommendations) r
      where coalesce((r->>'within_capacity')::boolean, false) = false
    )
  )
  into v_summary;

  return jsonb_build_object(
    'ok', true,
    'source', 'be_enterprise_dispatch_capacity_recommend',
    'generated_at', now(),
    'summary', v_summary,
    'recommendations', v_recommendations
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_enterprise_dispatch_center(p_limit integer DEFAULT 300)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_pickups jsonb := '[]'::jsonb;
  v_wayplans jsonb := '[]'::jsonb;
  v_stops jsonb := '[]'::jsonb;
  v_workforce jsonb := '[]'::jsonb;
  v_notifications jsonb := '[]'::jsonb;
  v_summary jsonb := '{}'::jsonb;
begin
  v_pickups := public.be_table_rows_json('be_unified_pickup_requests', p_limit);
  v_wayplans := public.be_table_rows_json('be_wayplan_dispatches', p_limit);
  v_stops := public.be_table_rows_json('be_wayplan_dispatch_stops', p_limit);
  v_workforce := public.be_table_rows_json('be_workforce_accounts', p_limit);
  v_notifications := public.be_table_rows_json('be_app_notifications', 50);

  select jsonb_build_object(
    'pickups', coalesce(jsonb_array_length(v_pickups), 0),
    'wayplans', coalesce(jsonb_array_length(v_wayplans), 0),
    'dispatch_stops', coalesce(jsonb_array_length(v_stops), 0),
    'workforce_accounts', coalesce(jsonb_array_length(v_workforce), 0),
    'notifications', coalesce(jsonb_array_length(v_notifications), 0),

    'waiting_assignment', (
      select count(*)
      from jsonb_array_elements(v_pickups) p
      where upper(coalesce(
        p->>'pickup_status',
        p->>'status',
        p->>'assignment_status',
        ''
      )) in ('WAITING_ASSIGNMENT','PENDING','NEW')
    ),

    'loaded_to_vehicle', (
      select count(*)
      from jsonb_array_elements(v_stops) s
      where upper(coalesce(
        s->>'stop_status',
        s->>'warehouse_status',
        s->>'dispatch_status',
        ''
      )) in ('LOADED_TO_VEHICLE','LOADED','DISPATCHED')
    ),

    'out_for_delivery', (
      select count(*)
      from jsonb_array_elements(v_stops) s
      where upper(coalesce(
        s->>'stop_status',
        s->>'warehouse_status',
        s->>'dispatch_status',
        ''
      )) in ('OUT_FOR_DELIVERY','HANDED_OVER_TO_RIDER','HANDOVER_TO_RIDER')
    ),

    'delivered', (
      select count(*)
      from jsonb_array_elements(v_stops) s
      where upper(coalesce(
        s->>'stop_status',
        s->>'warehouse_status',
        s->>'dispatch_status',
        ''
      )) = 'DELIVERED'
    )
  )
  into v_summary;

  return jsonb_build_object(
    'ok', true,
    'source', 'be_enterprise_dispatch_center',
    'generated_at', now(),
    'summary', v_summary,
    'pickups', v_pickups,
    'wayplans', v_wayplans,
    'stops', v_stops,
    'workforce', v_workforce,
    'notifications', v_notifications
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_enterprise_dispatch_route_optimize(p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_assignee_email text := nullif(coalesce(
    p_payload->>'assignee_email',
    p_payload->>'rider_email',
    p_payload->>'assigned_to'
  ), '');

  v_branch_code text := nullif(coalesce(p_payload->>'branch_code', 'YGN'), '');
  v_actor text := nullif(p_payload->>'actor_email', '');
  v_route_code text;
  v_updated integer := 0;
  v_rows jsonb := '[]'::jsonb;
  v_sql text;
begin
  if v_assignee_email is null then
    raise exception 'assignee_email is required';
  end if;

  v_route_code := 'ROUTE-' || to_char(now(), 'YYYYMMDD-HH24MISS') || '-' ||
                  upper(substr(md5(v_assignee_email || now()::text), 1, 6));

  if not public.be_table_exists('be_wayplan_dispatch_stops') then
    return jsonb_build_object(
      'ok', false,
      'error', 'be_wayplan_dispatch_stops table not found'
    );
  end if;

  /*
    Optimization logic:
    1. Same assignee only
    2. Active non-final stops only
    3. Sort by township, COD priority, delivery sequence, delivery ID
    4. Write route_code and optimized sequence when columns exist
  */

  if public.be_column_exists('be_wayplan_dispatch_stops', 'route_code')
     and public.be_column_exists('be_wayplan_dispatch_stops', 'optimized_sequence') then

    with ranked as (
      select
        id,
        row_number() over (
          order by
            coalesce(township, delivery_township, recipient_township, ''),
            coalesce(cod_amount, amount_to_collect, 0) desc nulls last,
            coalesce(delivery_sequence, 999999),
            coalesce(delivery_way_id, waybill_no, tracking_no, id::text)
        ) as seq
      from public.be_wayplan_dispatch_stops
      where coalesce(assigned_to, rider_email, rider_code, '') = v_assignee_email
        and upper(coalesce(stop_status, warehouse_status, dispatch_status, '')) not in (
          'DELIVERED','CANCELLED','RETURNED','FAILED'
        )
    )
    update public.be_wayplan_dispatch_stops s
    set
      route_code = v_route_code,
      optimized_sequence = ranked.seq,
      dispatch_status = case
        when public.be_column_exists('be_wayplan_dispatch_stops', 'dispatch_status') then 'ROUTE_OPTIMIZED'
        else dispatch_status
      end,
      updated_at = case
        when public.be_column_exists('be_wayplan_dispatch_stops', 'updated_at') then now()
        else updated_at
      end
    from ranked
    where s.id = ranked.id;

    get diagnostics v_updated = row_count;

  else
    return jsonb_build_object(
      'ok', false,
      'error', 'Missing route_code or optimized_sequence columns. Run the schema patch first.'
    );
  end if;

  select coalesce(jsonb_agg(to_jsonb(t)), '[]'::jsonb)
  into v_rows
  from (
    select *
    from public.be_wayplan_dispatch_stops
    where route_code = v_route_code
    order by optimized_sequence asc nulls last
  ) t;

  perform public.be_write_governance_audit(
    'DISPATCH',
    'ROUTE_OPTIMIZED',
    'be_wayplan_dispatch_stops',
    v_route_code,
    v_actor,
    '{}'::jsonb,
    jsonb_build_object(
      'route_code', v_route_code,
      'assignee_email', v_assignee_email,
      'branch_code', v_branch_code,
      'updated_rows', v_updated,
      'stops', v_rows
    ),
    jsonb_build_object(
      'source', 'be_enterprise_dispatch_route_optimize',
      'payload', p_payload
    )
  );

  return jsonb_build_object(
    'ok', true,
    'source', 'be_enterprise_dispatch_route_optimize',
    'route_code', v_route_code,
    'assignee_email', v_assignee_email,
    'branch_code', v_branch_code,
    'updated_rows', v_updated,
    'stops', v_rows
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_enterprise_go_live_health()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_control jsonb := '{}'::jsonb;
  v_warehouse jsonb := '{}'::jsonb;
  v_wayplan jsonb := '{}'::jsonb;
  v_finance jsonb := '{}'::jsonb;
  v_rider jsonb := '{}'::jsonb;
  v_readiness jsonb := '{}'::jsonb;
  v_checks jsonb := '[]'::jsonb;
  v_ok boolean := true;
begin
  begin
    v_control := public.be_enterprise_control_tower(50);
  exception when others then
    v_control := jsonb_build_object('ok', false, 'error', sqlerrm);
    v_ok := false;
  end;

  begin
    v_warehouse := public.be_warehouse_wayplan_center(50);
  exception when others then
    v_warehouse := jsonb_build_object('ok', false, 'error', sqlerrm);
    v_ok := false;
  end;

  begin
    v_wayplan := public.be_wayplan_command_center(20);
  exception when others then
    v_wayplan := jsonb_build_object('ok', false, 'error', sqlerrm);
    v_ok := false;
  end;

  begin
    v_finance := public.be_finance_wayplan_cod_center(50);
  exception when others then
    v_finance := jsonb_build_object('ok', false, 'error', sqlerrm);
    v_ok := false;
  end;

  begin
    v_rider := public.be_rider_delivery_wayplan_jobs('RID001', 50);
  exception when others then
    v_rider := jsonb_build_object('ok', false, 'error', sqlerrm);
    v_ok := false;
  end;

  begin
    v_readiness := public.be_go_live_system_readiness();
  exception when others then
    v_readiness := jsonb_build_object('ok', false, 'error', sqlerrm);
    v_ok := false;
  end;

  v_checks := jsonb_build_array(
    jsonb_build_object(
      'module', 'Enterprise Control Tower',
      'ok', coalesce((v_control->>'ok')::boolean, false),
      'count', coalesce((v_control->>'count')::integer, 0),
      'summary', v_control->'summary'
    ),
    jsonb_build_object(
      'module', 'Warehouse Wayplan Center',
      'ok', coalesce((v_warehouse->>'ok')::boolean, false),
      'count', coalesce((v_warehouse->>'count')::integer, 0),
      'summary', v_warehouse->'summary'
    ),
    jsonb_build_object(
      'module', 'Wayplan Command Center',
      'ok', coalesce((v_wayplan->>'ok')::boolean, false),
      'count', coalesce((v_wayplan->>'count')::integer, 0),
      'summary', v_wayplan->'summary'
    ),
    jsonb_build_object(
      'module', 'Finance COD Center',
      'ok', coalesce((v_finance->>'ok')::boolean, false),
      'count', coalesce((v_finance->>'count')::integer, 0),
      'summary', v_finance->'summary'
    ),
    jsonb_build_object(
      'module', 'Rider Delivery Jobs',
      'ok', coalesce((v_rider->>'ok')::boolean, false),
      'count', coalesce((v_rider->>'count')::integer, 0),
      'summary', jsonb_build_object(
        'rider_code', 'RID001',
        'jobs', coalesce((v_rider->>'count')::integer, 0)
      )
    ),
    jsonb_build_object(
      'module', 'System Readiness',
      'ok', coalesce((v_readiness->>'ok')::boolean, false),
      'status', coalesce(v_readiness->>'status', 'unknown'),
      'workflow', v_readiness->>'workflow'
    )
  );

  return jsonb_build_object(
    'ok', v_ok,
    'status', case when v_ok then 'GO_LIVE_READY' else 'CHECK_REQUIRED' end,
    'source', 'be_enterprise_go_live_health',
    'checked_at', now(),
    'control_summary', v_control->'summary',
    'warehouse_summary', v_warehouse->'summary',
    'finance_summary', v_finance->'summary',
    'rider_jobs_count', coalesce((v_rider->>'count')::integer, 0),
    'checks', v_checks
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_enterprise_warehouse_action(p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_action text := upper(coalesce(p_payload->>'action', ''));
  v_target_id text := nullif(coalesce(
    p_payload->>'delivery_way_id',
    p_payload->>'waybill_no',
    p_payload->>'tracking_no',
    p_payload->>'stop_id'
  ), '');
  v_actor text := nullif(p_payload->>'actor_email', '');
  v_exception_code text := nullif(p_payload->>'exception_code', '');
  v_exception_note text := nullif(p_payload->>'exception_note', '');
  v_status text;
  v_updated integer := 0;
  v_sql text;
begin
  if v_action = '' then
    raise exception 'action is required';
  end if;

  if v_target_id is null then
    raise exception 'delivery_way_id, waybill_no, tracking_no, or stop_id is required';
  end if;

  v_status := case v_action
    when 'RECEIVE' then 'RECEIVED_AT_ORIGIN'
    when 'SORT' then 'SORTING'
    when 'READY' then 'READY_FOR_DISPATCH'
    when 'LOAD' then 'LOADED_TO_VEHICLE'
    when 'HOLD' then 'WAREHOUSE_HOLD'
    when 'OUT_FOR_DELIVERY' then 'OUT_FOR_DELIVERY'
    when 'EXCEPTION' then 'WAREHOUSE_HOLD'
    else v_action
  end;

  if public.be_table_exists('be_wayplan_dispatch_stops') then
    v_sql := 'update public.be_wayplan_dispatch_stops set ';

    if public.be_column_exists('be_wayplan_dispatch_stops', 'warehouse_status') then
      v_sql := v_sql || 'warehouse_status = ' || quote_literal(v_status) || ', ';
    end if;

    if public.be_column_exists('be_wayplan_dispatch_stops', 'stop_status') then
      v_sql := v_sql || 'stop_status = ' || quote_literal(v_status) || ', ';
    end if;

    if public.be_column_exists('be_wayplan_dispatch_stops', 'updated_at') then
      v_sql := v_sql || 'updated_at = now(), ';
    end if;

    v_sql := regexp_replace(v_sql, ',\s*$', '');

    v_sql := v_sql || '
      where id::text = $1
         or delivery_way_id = $1
         or waybill_no = $1
         or tracking_no = $1';

    execute v_sql using v_target_id;
    get diagnostics v_updated = row_count;
  end if;

  if v_action = 'EXCEPTION' then
    if public.be_table_exists('be_logistics_exceptions') then
      insert into public.be_logistics_exceptions (
        exception_code,
        exception_type,
        reference_id,
        delivery_way_id,
        waybill_no,
        tracking_no,
        exception_status,
        notes,
        created_by,
        created_at,
        updated_at
      )
      values (
        coalesce(v_exception_code, 'WAREHOUSE_EXCEPTION'),
        'WAREHOUSE',
        v_target_id,
        p_payload->>'delivery_way_id',
        p_payload->>'waybill_no',
        p_payload->>'tracking_no',
        'OPEN',
        coalesce(v_exception_note, 'Warehouse exception raised'),
        v_actor,
        now(),
        now()
      )
      on conflict do nothing;
    end if;
  end if;

  perform public.be_write_governance_audit(
    'WAREHOUSE',
    v_action,
    'be_wayplan_dispatch_stops',
    v_target_id,
    v_actor,
    '{}'::jsonb,
    jsonb_build_object(
      'action', v_action,
      'status', v_status,
      'exception_code', v_exception_code,
      'exception_note', v_exception_note,
      'updated_rows', v_updated,
      'payload', p_payload
    ),
    jsonb_build_object('source', 'be_enterprise_warehouse_action')
  );

  return jsonb_build_object(
    'ok', true,
    'source', 'be_enterprise_warehouse_action',
    'action', v_action,
    'target_id', v_target_id,
    'status', v_status,
    'updated_rows', v_updated
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_enterprise_warehouse_center(p_limit integer DEFAULT 300)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_stops jsonb := '[]'::jsonb;
  v_exceptions jsonb := '[]'::jsonb;
  v_rules jsonb := '[]'::jsonb;
  v_summary jsonb := '{}'::jsonb;
begin
  v_stops := public.be_table_rows_json('be_wayplan_dispatch_stops', p_limit);
  v_exceptions := public.be_table_rows_json('be_logistics_exceptions', p_limit);
  v_rules := public.be_table_rows_json('be_logistics_exception_rules', p_limit);

  select jsonb_build_object(
    'total_stops', coalesce(jsonb_array_length(v_stops), 0),
    'exception_rules', coalesce(jsonb_array_length(v_rules), 0),
    'exceptions', coalesce(jsonb_array_length(v_exceptions), 0),
    'warehouse_received', (
      select count(*) from jsonb_array_elements(v_stops) s
      where upper(coalesce(s->>'warehouse_status', s->>'stop_status', '')) in ('RECEIVED_AT_ORIGIN','RECEIVED_AT_DESTINATION')
    ),
    'sorting', (
      select count(*) from jsonb_array_elements(v_stops) s
      where upper(coalesce(s->>'warehouse_status', s->>'stop_status', '')) = 'SORTING'
    ),
    'ready_for_dispatch', (
      select count(*) from jsonb_array_elements(v_stops) s
      where upper(coalesce(s->>'warehouse_status', s->>'stop_status', '')) = 'READY_FOR_DISPATCH'
    ),
    'loaded_to_vehicle', (
      select count(*) from jsonb_array_elements(v_stops) s
      where upper(coalesce(s->>'warehouse_status', s->>'stop_status', '')) = 'LOADED_TO_VEHICLE'
    ),
    'out_for_delivery', (
      select count(*) from jsonb_array_elements(v_stops) s
      where upper(coalesce(s->>'warehouse_status', s->>'stop_status', '')) = 'OUT_FOR_DELIVERY'
    ),
    'on_hold', (
      select count(*) from jsonb_array_elements(v_stops) s
      where upper(coalesce(s->>'warehouse_status', s->>'stop_status', '')) in ('WAREHOUSE_HOLD','HOLD')
    )
  )
  into v_summary;

  return jsonb_build_object(
    'ok', true,
    'source', 'be_enterprise_warehouse_center',
    'generated_at', now(),
    'summary', v_summary,
    'stops', v_stops,
    'exceptions', v_exceptions,
    'rules', v_rules
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_enterprise_workflow_snapshot()
 RETURNS jsonb
