    'rider_active', (select count(*) from public.be_enterprise_workflow_jobs where status in ('order_picking_assigned','order_picking_started','picked_up_verified')),
    'data_entry_pending', (select count(*) from public.be_enterprise_workflow_jobs where status in ('picked_up_verified','data_entry_pending')),
    'cod_pending', (select count(*) from public.be_cod_ledger where cod_status in ('pending_collection','collected','handed_over_to_finance')),
    'finance_pending', (select count(*) from public.be_financial_settlements where settlement_status='pending_finance'),
    'events', (select coalesce(jsonb_agg(row_to_json(e)::jsonb order by e.created_at desc), '[]'::jsonb) from (select * from public.be_enterprise_workflow_events order by created_at desc limit 50) e),
    'synced_at', now()
  );
$function$
;

CREATE OR REPLACE FUNCTION public.be_exception_screen_snapshot(p_actor_email text DEFAULT NULL::text, p_merchant_code text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_rows jsonb;
  v_summary jsonb;
begin
  with exception_rows as (
    select
      s.delivery_way_id,
      s.waybill_no,
      s.pickup_id,
      s.wayplan_id,
      s.stop_sequence,
      s.recipient_name,
      s.recipient_phone,
      s.township,
      s.address,
      s.stop_status,
      s.rider_status,
      s.failed_reason,
      s.cod_amount,
      s.cod_collected,
      s.delivered_at,
      s.updated_at,
      d.rider_code,
      d.rider_name,
      d.vehicle_code,
      d.vehicle_name,
      d.wayplan_status,
      case
        when s.stop_status = 'FAILED_DELIVERY' then 'FAILED_DELIVERY'
        when s.stop_status = 'RETURN_TO_WAREHOUSE' then 'RETURN_TO_WAREHOUSE'
        when coalesce(s.failed_reason, '') <> '' then 'EXCEPTION'
        else 'OPEN'
      end as exception_status,
      coalesce(s.failed_reason, 'No exception reason recorded') as reason,
      coalesce(s.updated_at, s.delivered_at, d.updated_at, d.created_at) as created_at
    from public.be_wayplan_dispatch_stops s
    left join public.be_wayplan_dispatches d
      on d.wayplan_id = s.wayplan_id
    where coalesce(s.stop_status, '') in ('FAILED_DELIVERY', 'RETURN_TO_WAREHOUSE')
       or coalesce(s.failed_reason, '') <> ''
  )
  select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc nulls last), '[]'::jsonb)
  into v_rows
  from exception_rows x;

  select jsonb_build_object(
    'open_exceptions', count(*),
    'priority_next_wayplan', count(*) filter (where exception_status = 'FAILED_DELIVERY'),
    'rto', count(*) filter (where exception_status = 'RETURN_TO_WAREHOUSE'),
    'displayed_rows', count(*)
  )
  into v_summary
  from (
    select *
    from jsonb_to_recordset(coalesce(v_rows, '[]'::jsonb)) as x(
      exception_status text
    )
  ) q;

  return jsonb_build_object(
    'ok', true,
    'source', 'be_exception_screen_snapshot',
    'summary', coalesce(v_summary, jsonb_build_object(
      'open_exceptions', 0,
      'priority_next_wayplan', 0,
      'rto', 0,
      'displayed_rows', 0
    )),
    'rows', coalesce(v_rows, '[]'::jsonb)
  );
end;
$function$
;

