CREATE OR REPLACE FUNCTION public.be_extract_deliveryway_id_from_json(p_json jsonb)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select coalesce(
    public.be_normalize_deliveryway_id(public.be_delivery_json_first_text(p_json, array[
      'delivery_way_id', 'delivery_id', 'tracking_no', 'parcel_way_id',
      'parcel_id', 'awb_no', 'barcode'
    ])),
    public.be_deliveryway_id_from_waybill_no(public.be_delivery_json_first_text(p_json, array[
      'waybill_no', 'waybill', 'wb_no'
    ])),
    public.be_deliveryway_id_from_invoice_no(public.be_delivery_json_first_text(p_json, array[
      'invoice_no', 'invoice', 'inv_no'
    ]))
  );
$function$
;

CREATE OR REPLACE FUNCTION public.be_extract_pickupway_id_from_json(p_json jsonb)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select coalesce(
    public.be_normalize_pickupway_id(public.be_delivery_json_first_text(p_json, array[
      'pickup_way_id', 'pickup_id', 'pickup_request_id', 'request_code',
      'pickup_request_code', 'pickup_waybill_id', 'parent_pickup_id',
      'parent_pickup_way_id', 'waybill_no', 'tracking_no', 'id'
    ])),
    case
      when public.be_delivery_json_first_text(p_json, array['delivery_way_id','delivery_id','tracking_no','waybill_no']) ~ '^D[0-9]{4}-[A-Z0-9]+-[0-9]{3}$'
      then null
      else null
    end
  );
$function$
;

create or replace view "public"."be_field_jobs_live_v" as  SELECT a.id AS assignment_id,
    a.role,
    a.assigned_to,
    a.assigned_to_name,
    COALESCE(a.waybill_no, r.waybill_no, r.way_id) AS waybill_no,
    COALESCE(r.way_id, a.waybill_no) AS way_id,
    COALESCE(a.pickup_id, r.pickup_id) AS pickup_id,
    r.merchant_code,
    COALESCE(r.merchant_name, (a.payload ->> 'merchant_name'::text)) AS merchant_name,
    COALESCE(r.recipient_name, (a.payload ->> 'recipient_name'::text)) AS receiver_name,
    COALESCE(r.recipient_phone, (a.payload ->> 'recipient_phone'::text)) AS receiver_phone,
    COALESCE(r.city, a.city) AS city,
    COALESCE(r.township, a.township) AS township,
    COALESCE(r.recipient_address, (a.payload ->> 'address'::text)) AS address,
    COALESCE(r.cod_amount, a.cod_amount, (0)::numeric) AS cod_amount,
    COALESCE(a.status, r.status, 'assigned'::text) AS status,
    a.priority,
    a.eta_date,
    a.eta_at,
    a.route_group,
    (a.payload || jsonb_build_object('item_price', COALESCE(r.item_price, (0)::numeric), 'delivery_fee_os', COALESCE(r.delivery_fee_os, (0)::numeric))) AS payload,
    a.created_at,
    GREATEST(COALESCE(a.updated_at, a.created_at), COALESCE(r.updated_at, a.updated_at, a.created_at)) AS updated_at
   FROM (public.be_field_assignments a
     LEFT JOIN public.be_masterdata_delivery_records r ON ((COALESCE(r.waybill_no, r.way_id) = a.waybill_no)));


CREATE OR REPLACE FUNCTION public.be_field_team_assignment_action(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_pickup text;
  v_role text;
  v_action text;
  v_status text;
  v_updated integer := 0;
begin
  v_pickup := coalesce(
    nullif(trim(p_payload->>'pickup_id'), ''),
    nullif(trim(p_payload->>'pickup_way_id'), ''),
    nullif(trim(p_payload->>'waybill_no'), '')
  );

  v_role := upper(coalesce(
    nullif(trim(p_payload->>'role'), ''),
    nullif(trim(p_payload->>'worker_role'), ''),
    'RIDER'
  ));

  v_action := upper(coalesce(
    nullif(trim(p_payload->>'action'), ''),
    nullif(trim(p_payload->>'response'), '')
  ));

  if v_pickup is null then
    return jsonb_build_object(
      'ok', false,
      'error', 'pickup_id is required'
    );
  end if;

  if v_role not in ('RIDER', 'DRIVER', 'HELPER') then
    return jsonb_build_object(
      'ok', false,
      'error', 'role must be RIDER, DRIVER or HELPER'
    );
  end if;

  if v_action not in ('ACCEPT', 'REJECT') then
    return jsonb_build_object(
      'ok', false,
      'error', 'action must be ACCEPT or REJECT'
    );
  end if;

  v_status := case
    when v_action = 'ACCEPT' then 'ACCEPTED'
    else 'REJECTED'
  end;

  if v_role = 'RIDER' then
    update public.be_portal_pickup_requests
    set
      rider_status = v_status,
      rider_accepted_at = case
        when v_action = 'ACCEPT' then now()
        else rider_accepted_at
      end,
      rider_rejected_at = case
        when v_action = 'REJECT' then now()
        else rider_rejected_at
      end,
      updated_at = now()
    where
      pickup_id = v_pickup
      or pickup_way_id = v_pickup
      or id::text = v_pickup;

  elsif v_role = 'DRIVER' then
    update public.be_portal_pickup_requests
    set
      driver_status = v_status,
      driver_accepted_at = case
        when v_action = 'ACCEPT' then now()
        else driver_accepted_at
      end,
      driver_rejected_at = case
        when v_action = 'REJECT' then now()
        else driver_rejected_at
      end,
      updated_at = now()
    where
      pickup_id = v_pickup
      or pickup_way_id = v_pickup
      or id::text = v_pickup;

  else
    update public.be_portal_pickup_requests
    set
      helper_status = v_status,
      helper_accepted_at = case
        when v_action = 'ACCEPT' then now()
        else helper_accepted_at
      end,
      helper_rejected_at = case
        when v_action = 'REJECT' then now()
        else helper_rejected_at
      end,
      updated_at = now()
    where
      pickup_id = v_pickup
      or pickup_way_id = v_pickup
      or id::text = v_pickup;
  end if;

  get diagnostics v_updated = row_count;

  if v_updated = 0 then
    return jsonb_build_object(
      'ok', false,
      'error', 'pickup_not_found',
      'pickup_id', v_pickup
    );
  end if;

  update public.be_portal_pickup_requests
  set team_acceptance_status =
    case
      when rider_status = 'REJECTED'
        or driver_status = 'REJECTED'
        or helper_status = 'REJECTED'
      then 'REJECTED'

      when
        (
          coalesce(assigned_rider_code, assigned_rider_email) is null
          or rider_status = 'ACCEPTED'
        )
        and
        (
          coalesce(assigned_driver_code, assigned_driver_email) is null
          or driver_status = 'ACCEPTED'
        )
        and
        (
          coalesce(assigned_helper_code, assigned_helper_email) is null
          or helper_status = 'ACCEPTED'
        )
        and (
          coalesce(assigned_rider_code, assigned_rider_email) is not null
          or coalesce(assigned_driver_code, assigned_driver_email) is not null
          or coalesce(assigned_helper_code, assigned_helper_email) is not null
        )
      then 'TEAM_READY'

      else 'WAITING_TEAM_ACCEPTANCE'
    end
  where
    pickup_id = v_pickup
    or pickup_way_id = v_pickup
    or id::text = v_pickup;

  return jsonb_build_object(
    'ok', true,
    'pickup_id', v_pickup,
    'role', v_role,
    'action', v_action,
    'status', v_status,
    'updated_rows', v_updated
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_field_team_mobile_snapshot(p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_payload jsonb := coalesce(p_payload, '{}'::jsonb);
  v_worker text := upper(coalesce(
    nullif(trim(v_payload ->> 'worker_code'), ''),
    nullif(trim(v_payload ->> 'login'), ''),
    nullif(trim(v_payload ->> 'email'), ''),
    ''
  ));
  v_role text := upper(coalesce(
    nullif(trim(v_payload ->> 'role'), ''),
    nullif(trim(v_payload ->> 'worker_role'), ''),
    ''
  ));
  v_jobs jsonb := '[]'::jsonb;
begin
  if v_role not in ('RIDER','DRIVER','HELPER') then
    if v_worker like 'RID%' or lower(v_worker) like 'rider_%' then v_role := 'RIDER';
    elsif v_worker like 'DRV%' or lower(v_worker) like 'driver_%' then v_role := 'DRIVER';
    elsif v_worker like 'HLP%' or lower(v_worker) like 'helper_%' then v_role := 'HELPER';
    else v_role := 'RIDER';
    end if;
  end if;

  if v_role = 'RIDER' then
    select coalesce(jsonb_agg(to_jsonb(x) order by x.updated_at desc), '[]'::jsonb)
    into v_jobs
    from (
      select p.*, 'rider'::text as mobile_role
      from public.be_portal_pickup_requests p
      where upper(coalesce(p.assigned_rider_code, '')) = v_worker
         or upper(coalesce(p.assigned_rider_email, '')) = v_worker
      limit 200
    ) x;
  elsif v_role = 'DRIVER' then
    select coalesce(jsonb_agg(to_jsonb(x) order by x.updated_at desc), '[]'::jsonb)
    into v_jobs
    from (
      select p.*, 'driver'::text as mobile_role
      from public.be_portal_pickup_requests p
      where upper(coalesce(p.assigned_driver_code, '')) = v_worker
         or upper(coalesce(p.assigned_driver_email, '')) = v_worker
      limit 200
    ) x;
  else
    select coalesce(jsonb_agg(to_jsonb(x) order by x.updated_at desc), '[]'::jsonb)
    into v_jobs
    from (
      select p.*, 'helper'::text as mobile_role
      from public.be_portal_pickup_requests p
      where upper(coalesce(p.assigned_helper_code, '')) = v_worker
         or upper(coalesce(p.assigned_helper_email, '')) = v_worker
      limit 200
    ) x;
  end if;

  return jsonb_build_object(
    'ok', true,
    'source', 'be_field_team_mobile_snapshot_v3',
    'identity', jsonb_build_object(
      'worker_code', v_worker,
      'display_name', v_worker,
      'role', lower(v_role)
    ),
    'jobs', v_jobs,
    'notifications', '[]'::jsonb
  );
end;
$function$
;

