CREATE OR REPLACE FUNCTION public.be_finance_close_settlement(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_way text := nullif(coalesce(p_payload ->> 'delivery_way_id', p_payload ->> 'way_id'), '');
  v_set text := nullif(p_payload ->> 'settlement_id', '');
  v_closed text := nullif(p_payload ->> 'closed_by', '');
  v_closed_name text := nullif(p_payload ->> 'closed_by_name', '');
  v_final_set text;
begin
  update public.be_financial_settlements
  set settlement_status = 'finance_settled',
      finance_note = coalesce(nullif(p_payload ->> 'finance_note', ''), finance_note),
      closed_by = coalesce(v_closed, closed_by),
      closed_by_name = coalesce(v_closed_name, closed_by_name),
      closed_at = now(),
      payload = coalesce(payload, '{}'::jsonb) || p_payload,
      updated_at = now()
  where (v_set is not null and settlement_id = v_set)
     or (v_way is not null and delivery_way_id = v_way)
  returning settlement_id into v_final_set;

  if v_final_set is null then
    raise exception 'Settlement not found';
  end if;

  update public.be_cod_ledger
  set cod_status = 'finance_settled',
      updated_at = now()
  where settlement_id = v_final_set
     or delivery_way_id = v_way;

  update public.delivery_waybills
  set finance_status = 'finance_settled',
      financial_status = 'finance_settled',
      overall_status = 'finance_settled',
      updated_at = now()
  where delivery_way_id = v_way
     or delivery_way_id in (
       select delivery_way_id
       from public.be_financial_settlements
       where settlement_id = v_final_set
     );

  insert into public.be_finance_journal_entries (
    settlement_id,
    delivery_way_id,
    account_code,
    account_name,
    debit,
    credit,
    description,
    payload
  )
  select
    s.settlement_id,
    s.delivery_way_id,
    '4001',
    'Delivery Fee Income',
    0,
    coalesce(s.finance_deli, s.delivery_fee, 0),
    'Finance settlement closed',
    to_jsonb(s)
  from public.be_financial_settlements s
  where s.settlement_id = v_final_set;

  return jsonb_build_object(
    'ok', true,
    'settlement_id', v_final_set,
    'status', 'finance_settled'
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_finance_cod_settle_pickup(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_pickup_id text;
  v_wayplan_id text;
  v_actor_email text;
  v_cod_amount numeric := 0;
  v_settlement_ref text;
  v_updated_bridge integer := 0;
  v_updated_ledger integer := 0;
  v_updated_pickup integer := 0;
  v_updated_inventory integer := 0;
begin
  v_pickup_id := nullif(coalesce(
    p_payload->>'pickup_way_id',
    p_payload->>'pickup_id',
    p_payload->>'request_code'
  ), '');

  v_wayplan_id := nullif(p_payload->>'wayplan_id', '');

  v_actor_email := nullif(coalesce(
    p_payload->>'actor_email',
    p_payload->>'finance_email',
    'finance@britiumexpress.com'
  ), '');

  if v_pickup_id is null and v_wayplan_id is null then
    return jsonb_build_object(
      'ok', false,
      'error', 'pickup_id or wayplan_id is required',
      'payload', p_payload
    );
  end if;

  if v_pickup_id is null then
    select pickup_id
    into v_pickup_id
    from public.be_dispatch_wayplan_bridge
    where wayplan_id = v_wayplan_id
    limit 1;
  end if;

  if v_wayplan_id is null then
    select wayplan_id
    into v_wayplan_id
    from public.be_dispatch_wayplan_bridge
    where pickup_id = v_pickup_id
    limit 1;
  end if;

  v_cod_amount := coalesce(
    nullif(p_payload->>'cod_collected', '')::numeric,
    nullif(p_payload->>'settled_amount', '')::numeric,
    (
      select coalesce(sum(coalesce(cod_amount, 0)), 0)
      from public.parcels p
      where p.tracking_code in (
        select coalesce(w.tracking_no, w.waybill_no, w.delivery_way_id)
        from public.be_waybill_ledger w
        where w.pickup_id = v_pickup_id
           or w.pickup_way_id = v_pickup_id
      )
    ),
    0
  );

  v_settlement_ref := coalesce(
    nullif(p_payload->>'settlement_ref', ''),
    'COD-SETTLE-' || to_char(now() at time zone 'Asia/Yangon', 'YYYYMMDD-HH24MISS') || '-' || upper(substr(md5(v_pickup_id || now()::text), 1, 6))
  );

  update public.be_dispatch_wayplan_bridge
  set
    cod_collected = v_cod_amount,
    finance_status = 'COD_SETTLED',
    dispatch_status = coalesce(dispatch_status, 'DELIVERED'),
    notes = coalesce(notes, '') || ' | COD settled: ' || v_settlement_ref,
    updated_at = now()
  where pickup_id = v_pickup_id
     or wayplan_id = v_wayplan_id;

  get diagnostics v_updated_bridge = row_count;

  update public.be_waybill_ledger
  set
    cod_collected = v_cod_amount,
    finance_status = 'COD_SETTLED',
    dispatch_status = coalesce(dispatch_status, 'DELIVERED'),
    wayplan_status = coalesce(wayplan_status, 'DELIVERED'),
    updated_at = now(),
    payload = coalesce(payload, '{}'::jsonb) || jsonb_build_object(
      'finance_status', 'COD_SETTLED',
      'cod_settled_at', now(),
      'cod_settled_by', v_actor_email,
      'settlement_ref', v_settlement_ref,
      'settled_amount', v_cod_amount
    )
  where pickup_id = v_pickup_id
     or pickup_way_id = v_pickup_id;

  get diagnostics v_updated_ledger = row_count;

  update public.be_warehouse_inventory
  set
    actual_collect = v_cod_amount,
    notes = coalesce(notes, '') || ' | COD settled: ' || v_settlement_ref,
    updated_at = now()
  where pickup_id = v_pickup_id
     or way_id = v_pickup_id;

  get diagnostics v_updated_inventory = row_count;

  update public.be_portal_pickup_requests
  set
    finance_status = 'COD_SETTLED',
    cod_settlement_status = 'COD_SETTLED',
    cod_settled_amount = v_cod_amount,
    cod_settled_at = now(),
    cod_settled_by = v_actor_email,
    metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
      'finance_status', 'COD_SETTLED',
      'cod_settled_at', now(),
      'cod_settled_by', v_actor_email,
      'settlement_ref', v_settlement_ref,
      'settled_amount', v_cod_amount,
      'wayplan_id', v_wayplan_id
    ),
    updated_at = now()
  where pickup_way_id = v_pickup_id
     or pickup_id = v_pickup_id
     or request_code = v_pickup_id;

  get diagnostics v_updated_pickup = row_count;

  update public.be_app_notifications
  set
    status = 'read',
    is_read = true,
    read_at = coalesce(read_at, now()),
    metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
      'finance_status', 'COD_SETTLED',
      'settlement_ref', v_settlement_ref,
      'settled_amount', v_cod_amount,
      'settled_at', now()
    )
  where pickup_id = v_pickup_id
    and target_role = 'finance'
    and notification_type = 'COD_SETTLEMENT_REQUIRED';

  return jsonb_build_object(
    'ok', true,
    'source', 'be_finance_cod_settle_pickup',
    'pickup_id', v_pickup_id,
    'wayplan_id', v_wayplan_id,
    'settlement_ref', v_settlement_ref,
    'settled_amount', v_cod_amount,
    'finance_status', 'COD_SETTLED',
    'updated_bridge_rows', v_updated_bridge,
    'updated_ledger_rows', v_updated_ledger,
    'updated_pickup_rows', v_updated_pickup,
    'updated_inventory_rows', v_updated_inventory,
    'next_action', 'FINANCE_CLOSED'
  );
end;
$function$
;

