CREATE OR REPLACE FUNCTION public.be_finance_rider_cod_settle(p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_target_id text := nullif(coalesce(
    p_payload->>'delivery_way_id',
    p_payload->>'waybill_no',
    p_payload->>'tracking_no',
    p_payload->>'id'
  ), '');

  v_actor text := nullif(p_payload->>'actor_email', '');
  v_method text := coalesce(nullif(p_payload->>'settlement_method', ''), 'CASH_HANDOVER');
  v_reference text := nullif(p_payload->>'settlement_reference', '');
  v_updated integer := 0;
  v_amount numeric := 0;
begin
  if v_target_id is null then
    raise exception 'delivery_way_id, waybill_no, tracking_no, or id is required';
  end if;

  select coalesce(cod_collected, 0)
  into v_amount
  from public.be_wayplan_dispatch_stops
  where id::text = v_target_id
     or delivery_way_id = v_target_id
     or waybill_no = v_target_id
     or tracking_no = v_target_id
  limit 1;

  if coalesce(v_amount, 0) <= 0 then
    raise exception 'No collected COD amount found for %', v_target_id;
  end if;

  update public.be_wayplan_dispatch_stops
  set
    finance_status = 'COD_SETTLED',
    updated_at = now(),
    metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
      'cod_settlement',
      jsonb_build_object(
        'settled_at', now(),
        'settled_by', v_actor,
        'settlement_method', v_method,
        'settlement_reference', v_reference,
        'settled_amount', v_amount
      )
    )
  where id::text = v_target_id
     or delivery_way_id = v_target_id
     or waybill_no = v_target_id
     or tracking_no = v_target_id;

  get diagnostics v_updated = row_count;

  perform public.be_write_governance_audit(
    'FINANCE_COD',
    'RIDER_COD_SETTLED',
    'be_wayplan_dispatch_stops',
    v_target_id,
    v_actor,
    '{}'::jsonb,
    jsonb_build_object(
      'target_id', v_target_id,
      'settled_amount', v_amount,
      'settlement_method', v_method,
      'settlement_reference', v_reference,
      'updated_rows', v_updated,
      'payload', p_payload
    ),
    jsonb_build_object('source', 'be_finance_rider_cod_settle')
  );

  return jsonb_build_object(
    'ok', true,
    'source', 'be_finance_rider_cod_settle',
    'target_id', v_target_id,
    'settled_amount', v_amount,
    'settlement_method', v_method,
    'settlement_reference', v_reference,
    'updated_rows', v_updated
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_finance_rider_cod_settlement_queue(p_limit integer DEFAULT 200)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_rows jsonb := '[]'::jsonb;
  v_summary jsonb := '{}'::jsonb;
begin
  select coalesce(jsonb_agg(to_jsonb(t)), '[]'::jsonb)
  into v_rows
  from (
    select
      id,
      pickup_id,
      pickup_way_id,
      delivery_way_id,
      waybill_no,
      invoice_no,
      tracking_no,
      rider_email,
      rider_name,
      dispatch_status,
      stop_status,
      rider_status,
      cod_amount,
      amount_to_collect,
      cod_collected,
      cod_collected_at,
      cod_collected_by,
      finance_status,
      delivered_at,
      updated_at
    from public.be_wayplan_dispatch_stops
    where coalesce(cod_collected, 0) > 0
      and upper(coalesce(finance_status, '')) = 'COD_PENDING_SETTLEMENT'
    order by cod_collected_at desc nulls last, updated_at desc nulls last
    limit greatest(coalesce(p_limit, 200), 1)
  ) t;

  select jsonb_build_object(
    'pending_count', coalesce(jsonb_array_length(v_rows), 0),
    'pending_amount', (
      select coalesce(sum((r->>'cod_collected')::numeric), 0)
      from jsonb_array_elements(v_rows) r
      where coalesce(r->>'cod_collected', '') ~ '^[0-9]+(\.[0-9]+)?$'
    )
  )
  into v_summary;

  return jsonb_build_object(
    'ok', true,
    'source', 'be_finance_rider_cod_settlement_queue',
    'generated_at', now(),
    'summary', v_summary,
    'rows', v_rows
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_finance_settle_wayplan_cod(p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_wayplan_id text := nullif(p_payload->>'wayplan_id', '');
  v_delivery_way_id text := nullif(p_payload->>'delivery_way_id', '');
  v_reference text := coalesce(
    nullif(p_payload->>'settlement_reference', ''),
    'SET-' || to_char(now(), 'YYYYMMDD-HH24MISS')
  );
  v_actor text := coalesce(nullif(p_payload->>'actor', ''), 'finance');
  v_count integer;
begin
  if v_wayplan_id is null and v_delivery_way_id is null then
    return jsonb_build_object(
      'ok', false,
      'error', 'wayplan_id or delivery_way_id is required'
    );
  end if;

  update public.be_wayplan_cod_settlements
  set
    settlement_status = 'SETTLED',
    settlement_reference = v_reference,
    settled_at = now(),
    metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
      'settled_by', v_actor,
      'settled_at', now(),
      'settlement_reference', v_reference
    ),
    updated_at = now()
  where (v_wayplan_id is null or wayplan_id = v_wayplan_id)
    and (v_delivery_way_id is null or delivery_way_id = v_delivery_way_id)
    and settlement_status <> 'SETTLED';

  get diagnostics v_count = row_count;

  return jsonb_build_object(
    'ok', true,
    'settled_count', v_count,
    'settlement_reference', v_reference,
    'status', 'SETTLED'
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_finance_snapshot(p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
AS $function$
  select jsonb_build_object('ok',true,'cod_ledger',coalesce((select jsonb_agg(row_to_json(x)::jsonb order by updated_at desc) from public.be_cod_ledger x),'[]'::jsonb),'settlements',coalesce((select jsonb_agg(row_to_json(x)::jsonb order by updated_at desc) from public.be_financial_settlements x),'[]'::jsonb));
$function$
;

CREATE OR REPLACE FUNCTION public.be_finance_snapshot(p_status text DEFAULT NULL::text, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_status text := nullif(p_status, '');
  v_limit integer := greatest(coalesce(p_limit, 100), 1);
  v_cod jsonb;
  v_settlements jsonb;
  v_invoices jsonb;
  v_journal jsonb;
begin
  select coalesce(jsonb_agg(row_to_json(x)::jsonb order by x.updated_at desc), '[]'::jsonb)
  into v_cod
  from (
    select *
    from public.be_cod_ledger
    where v_status is null
       or cod_status = v_status
    order by updated_at desc
    limit v_limit
  ) x;

  select coalesce(jsonb_agg(row_to_json(x)::jsonb order by x.updated_at desc), '[]'::jsonb)
  into v_settlements
  from (
    select *
    from public.be_financial_settlements
    where v_status is null
       or settlement_status = v_status
    order by updated_at desc
    limit v_limit
  ) x;

  select coalesce(jsonb_agg(row_to_json(x)::jsonb order by x.updated_at desc), '[]'::jsonb)
  into v_invoices
  from (
    select *
    from public.be_customer_invoices
    order by updated_at desc
    limit v_limit
  ) x;

  select coalesce(jsonb_agg(row_to_json(x)::jsonb order by x.created_at desc), '[]'::jsonb)
  into v_journal
  from (
    select *
    from public.be_finance_journal_entries
    order by created_at desc
    limit v_limit
  ) x;

  return jsonb_build_object(
    'ok', true,
    'kpis', jsonb_build_object(
      'cod_pending', (select count(*) from public.be_cod_ledger where cod_status = 'pending_collection'),
      'cod_collected', (select count(*) from public.be_cod_ledger where cod_status = 'collected'),
      'cod_handed_over', (select count(*) from public.be_cod_ledger where cod_status = 'handed_over_to_finance'),
      'finance_pending', (select count(*) from public.be_financial_settlements where settlement_status = 'pending_finance'),
      'finance_settled', (select count(*) from public.be_financial_settlements where settlement_status = 'finance_settled'),
      'total_receivable', (select coalesce(sum(gross_cod), 0) from public.be_financial_settlements),
      'total_handover', (select coalesce(sum(handover_amount), 0) from public.be_financial_settlements),
      'variance', (select coalesce(sum(variance_amount), 0) from public.be_financial_settlements),
      'delivery_fee_income', (select coalesce(sum(finance_deli), 0) from public.be_financial_settlements)
    ),
    'cod_rows', v_cod,
    'settlements', v_settlements,
    'invoices', v_invoices,
    'journal', v_journal,
    'reports', jsonb_build_object(
      'cashBookSummary', jsonb_build_array(jsonb_build_object(
        'branch', 'YGN',
        'zone', 'Yangon',
        'report_date', current_date,
        'account_description', 'Cash / COD Handover',
        'received', (select coalesce(sum(handover_amount), 0) from public.be_financial_settlements)
      )),
      'incomeStatement', jsonb_build_array(jsonb_build_object(
        'code_no', '4001',
        'description', 'Delivery Fee Income',
        'category', 'income',
        'amount', (select coalesce(sum(finance_deli), 0) from public.be_financial_settlements)
      )),
      'profitAndLoss', jsonb_build_array(jsonb_build_object(
        'code_no', '4000',
        'description', 'Operating Revenue',
        'category', 'income',
        'amount', (select coalesce(sum(finance_deli), 0) from public.be_financial_settlements)
      ))
    ),
    'synced_at', now()
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_finance_verify_handover(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare ref text := public.be30_clean(p_payload->>'settlement_ref'); st text := lower(coalesce(p_payload->>'status','verified'));
begin
  update public.be_rider_handover_ledger set status=st,verified_by=p_payload->>'verified_by',verification_time=now(),updated_at=now(),payload=coalesce(payload,'{}'::jsonb)||p_payload where settlement_ref=ref;
  update public.be_cod_ledger set status=case when st in ('verified','handed_over') then 'handed_over' else st end,updated_at=now() where settlement_ref=ref;
  return jsonb_build_object('ok',true,'settlement_ref',ref,'status',st);
end; $function$
;

CREATE OR REPLACE FUNCTION public.be_finance_wayplan_cod_center(p_limit integer DEFAULT 200)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_rows jsonb;
  v_summary jsonb;
begin
  select coalesce(jsonb_agg(to_jsonb(x) order by x.delivered_at desc nulls last, x.created_at desc), '[]'::jsonb)
  into v_rows
  from (
    select *
    from public.be_wayplan_cod_settlements
    order by delivered_at desc nulls last, created_at desc
    limit greatest(coalesce(p_limit, 200), 1)
  ) x;

  select jsonb_build_object(
    'total_expected', coalesce(sum(cod_expected), 0),
    'total_collected', coalesce(sum(cod_collected), 0),
    'pending_settlement', coalesce(sum(cod_collected) filter (where settlement_status = 'PENDING_SETTLEMENT'), 0),
    'settled', coalesce(sum(cod_collected) filter (where settlement_status = 'SETTLED'), 0),
    'delivered_cod_count', count(*)
  )
  into v_summary
  from public.be_wayplan_cod_settlements;

  return jsonb_build_object(
    'ok', true,
    'source', 'be_finance_wayplan_cod_center',
    'count', jsonb_array_length(v_rows),
    'summary', v_summary,
    'rows', v_rows
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_finance_workflow_queue(p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object('ok', true, 'items', coalesce(jsonb_agg(to_jsonb(p) order by p.updated_at desc), '[]'::jsonb), 'data', coalesce(jsonb_agg(to_jsonb(p) order by p.updated_at desc), '[]'::jsonb))
  from public.be_portal_pickup_requests p
  where lower(coalesce(p.finance_status, 'pending_finance')) in ('pending_finance', 'pending', 'cod_pending', 'settlement_pending')
     or upper(coalesce(p.delivery_status, '')) in ('DELIVERED', 'OUT_FOR_DELIVERY');
$function$
;

CREATE OR REPLACE FUNCTION public.be_finance_workflow_snapshot()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare cod_today numeric; pending numeric; verify numeric; invoices int; waybills int;
begin
  select coalesce(sum(cod_collected),0) into cod_today from public.be_cod_ledger where date(created_at)=current_date;
  select coalesce(sum(cod_collected-cod_handed_over),0) into pending from public.be_cod_ledger where status in ('awaiting_handover','collected','submitted');
  select coalesce(sum(total_cash_received),0) into verify from public.be_rider_handover_ledger where status in ('submitted','under_verification');
  select count(*) into invoices from public.be_invoice_ledger where status in ('draft','under_review','issued');
  select count(*) into waybills from public.be_waybill_ledger where status in ('delivered','finance_pending','issued');
  return jsonb_build_object('ok',true,'cod_collected_today',cod_today,'pending_rider_handover',pending,'awaiting_operation_verification',verify,'pending_invoices',invoices,'waybills_finance_pending',waybills);
end; $function$
;

