create or replace view "public"."be_fleet_vehicles" as  SELECT record_key AS id,
    record_key AS vehicle_id,
    record_key AS fleet_id,
    record_key AS vehicle_code,
    record_key AS code,
    COALESCE((payload ->> 'vehicle_no'::text), (payload ->> 'vehicle_name'::text), (payload ->> 'fleet_id'::text), record_key) AS vehicle_name,
    COALESCE((payload ->> 'vehicle_no'::text), (payload ->> 'vehicle_name'::text), (payload ->> 'fleet_id'::text), record_key) AS name,
    concat_ws(' · '::text, NULLIF((payload ->> 'vehicle_no'::text), ''::text), NULLIF((payload ->> 'vehicle_type'::text), ''::text), (NULLIF((payload ->> 'capacity_kg'::text), ''::text) || ' kg'::text)) AS label,
    concat_ws(' · '::text, NULLIF((payload ->> 'vehicle_no'::text), ''::text), NULLIF((payload ->> 'vehicle_type'::text), ''::text), (NULLIF((payload ->> 'capacity_kg'::text), ''::text) || ' kg'::text)) AS display_name,
    COALESCE((payload ->> 'vehicle_no'::text), (payload ->> 'plate_no'::text), (payload ->> 'registration_no'::text)) AS plate_no,
    COALESCE((payload ->> 'vehicle_no'::text), (payload ->> 'plate_no'::text), (payload ->> 'registration_no'::text)) AS plate_number,
    COALESCE((payload ->> 'vehicle_no'::text), (payload ->> 'plate_no'::text), (payload ->> 'registration_no'::text)) AS registration_no,
    COALESCE((payload ->> 'vehicle_no'::text), (payload ->> 'plate_no'::text), (payload ->> 'registration_no'::text)) AS vehicle_no,
    (payload ->> 'vehicle_type'::text) AS vehicle_type,
    (NULLIF((payload ->> 'capacity_kg'::text), ''::text))::numeric AS capacity_kg,
    'ACTIVE'::text AS status,
    true AS active,
    true AS is_active,
    true AS available,
    true AS is_available,
    payload,
    updated_at
   FROM public.be_master_data_rows
  WHERE ((dataset_key = 'fleet_master'::text) AND (deleted_at IS NULL) AND (record_key ~~ 'FLT%'::text) AND (COALESCE((payload ->> 'vehicle_no'::text), ''::text) <> ''::text));


CREATE OR REPLACE FUNCTION public.be_generate_hierarchical_ids(p_merchant_code text, p_parcel_count integer, p_request_date date DEFAULT CURRENT_DATE)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_date_str text;
  v_base_str text;
  v_pickup_id text;
  v_parcels jsonb := '[]'::jsonb;
  v_idx_str text;
BEGIN
  -- 1. Format the date as MMDD (e.g., '0705' for July 5th)
  v_date_str := to_char(p_request_date, 'MMDD');

  -- 2. Create the base string (e.g., '0705-BBG')
  v_base_str := v_date_str || '-' || p_merchant_code;

  -- 3. Generate the master Pickup ID (e.g., 'P0705-BBG-015')
  v_pickup_id := 'P' || v_base_str || '-' || LPAD(p_parcel_count::text, 3, '0');

  -- 4. Loop to generate individual IDs for each parcel
  FOR i IN 1..p_parcel_count LOOP
    v_idx_str := LPAD(i::text, 3, '0'); -- Pads to '001', '002', etc.

    v_parcels := v_parcels || jsonb_build_object(
      'parcel_sequence', i,
      'delivery_way_id', 'D' || v_base_str || '-' || v_idx_str,
      'waybill_no', 'WB' || v_base_str || '-' || v_idx_str,
      'invoice_id', 'INV' || v_base_str || '-' || v_idx_str
    );
  END LOOP;

  -- 5. Return the full structured payload
  RETURN jsonb_build_object(
    'pickup_id', v_pickup_id,
    'total_parcels', p_parcel_count,
    'parcel_ids', v_parcels
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_generate_operational_ids_for_pickup(p_pickup_way_id text, p_parcel_count integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v jsonb;
  v_count integer;
  i integer;
  v_rows jsonb := '[]'::jsonb;
begin
  v := public.be_parse_pickup_way_id(p_pickup_way_id);
  v_count := coalesce(p_parcel_count, (v->>'parcel_count')::integer);

  if v_count <= 0 then
    raise exception 'Parcel count must be greater than zero';
  end if;

  for i in 1..v_count loop
    v_rows := v_rows || jsonb_build_array(public.be_make_operational_ids(p_pickup_way_id, i));
  end loop;

  return jsonb_build_object(
    'ok', true,
    'pickup_way_id', p_pickup_way_id,
    'parcel_count', v_count,
    'rows', v_rows
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_generate_wayplan(p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_wayplan_id text;
  v_vehicle_code text;
  v_vehicle_name text;
  v_driver_code text;
  v_driver_name text;
  v_rider_code text;
  v_rider_name text;
  v_helper_code text;
  v_helper_name text;
  v_actor text;
  v_selected jsonb;
  v_count integer := 0;
  v_cod numeric := 0;
begin
  v_wayplan_id := coalesce(
    nullif(p_payload->>'wayplan_id', ''),
    'WP-' || to_char(now(), 'YYYYMMDD-HH24MISS')
  );

  v_vehicle_code := nullif(p_payload->>'vehicle_code', '');
  v_vehicle_name := nullif(p_payload->>'vehicle_name', '');
  v_driver_code := nullif(p_payload->>'driver_code', '');
  v_driver_name := nullif(p_payload->>'driver_name', '');
  v_rider_code := nullif(p_payload->>'rider_code', '');
  v_rider_name := nullif(p_payload->>'rider_name', '');
  v_helper_code := nullif(p_payload->>'helper_code', '');
  v_helper_name := nullif(p_payload->>'helper_name', '');
  v_actor := coalesce(nullif(p_payload->>'actor', ''), 'dispatch');

  v_selected := coalesce(p_payload->'delivery_way_ids', p_payload->'waybill_nos', '[]'::jsonb);

  insert into public.be_wayplan_dispatches (
    wayplan_id,
    dispatch_batch_no,
    branch_code,
    vehicle_code,
    vehicle_name,
    driver_code,
    driver_name,
    rider_code,
    rider_name,
    helper_code,
    helper_name,
    wayplan_status,
    created_by,
    metadata
  )
  values (
    v_wayplan_id,
    v_wayplan_id,
    coalesce(nullif(p_payload->>'branch_code', ''), 'YGN'),
    v_vehicle_code,
    v_vehicle_name,
    v_driver_code,
    v_driver_name,
    v_rider_code,
    v_rider_name,
    v_helper_code,
    v_helper_name,
    'CREATED',
    v_actor,
    p_payload
  )
  on conflict (wayplan_id) do update
  set
    vehicle_code = excluded.vehicle_code,
    vehicle_name = excluded.vehicle_name,
    driver_code = excluded.driver_code,
    driver_name = excluded.driver_name,
    rider_code = excluded.rider_code,
    rider_name = excluded.rider_name,
    helper_code = excluded.helper_code,
    helper_name = excluded.helper_name,
    updated_at = now();

  delete from public.be_wayplan_dispatch_stops
  where wayplan_id = v_wayplan_id;

  insert into public.be_wayplan_dispatch_stops (
    wayplan_id,
    stop_sequence,
    pickup_id,
    pickup_way_id,
    delivery_way_id,
    waybill_no,
    recipient_name,
    recipient_phone,
    township,
    address,
    cod_amount,
    delivery_fee,
    parcel_weight_kg,
    stop_status,
    metadata
  )
  select
    v_wayplan_id,
    row_number() over (order by q.township, q.address, q.delivery_way_id),
    q.pickup_id,
    q.pickup_way_id,
    q.delivery_way_id,
    q.waybill_no,
    q.recipient_name,
    q.recipient_phone,
    q.township,
    q.address,
    q.cod_amount,
    q.delivery_fee,
    q.parcel_weight_kg,
    'READY_FOR_DISPATCH',
    q.metadata
  from public.be_v_dispatch_ready_queue q
  where (
    jsonb_array_length(v_selected) = 0
    or q.delivery_way_id in (select jsonb_array_elements_text(v_selected))
    or q.waybill_no in (select jsonb_array_elements_text(v_selected))
  );

  select count(*), coalesce(sum(cod_amount), 0)
  into v_count, v_cod
  from public.be_wayplan_dispatch_stops
  where wayplan_id = v_wayplan_id;

  if v_count = 0 then
    return jsonb_build_object(
      'ok', false,
      'error', 'No dispatch-ready stops found. Check be_dispatch_ready_queue first.',
      'wayplan_id', v_wayplan_id,
      'total_stops', 0
    );
  end if;

  update public.be_wayplan_dispatches
  set
    total_stops = v_count,
    total_parcels = v_count,
    total_cod = v_cod,
    updated_at = now()
  where wayplan_id = v_wayplan_id;

  update public.be_waybill_ledger w
  set
    wayplan_id = v_wayplan_id,
    wayplan_status = 'WAYPLAN_CREATED',
    dispatch_status = 'WAYPLAN_CREATED',
    updated_at = now()
  where exists (
    select 1
    from public.be_wayplan_dispatch_stops s
    where s.wayplan_id = v_wayplan_id
      and (
        s.delivery_way_id = w.delivery_way_id
        or s.waybill_no = w.waybill_no
      )
  );

  update public.be_portal_pickup_requests p
  set
    wayplan_id = v_wayplan_id,
    wayplan_status = 'WAYPLAN_CREATED',
    dispatch_status = 'WAYPLAN_CREATED',
    updated_at = now()
  where exists (
    select 1
    from public.be_wayplan_dispatch_stops s
    where s.wayplan_id = v_wayplan_id
      and s.pickup_id = p.pickup_id
  );

  return jsonb_build_object(
    'ok', true,
    'wayplan_id', v_wayplan_id,
    'total_stops', v_count,
    'total_cod', v_cod,
    'status', 'WAYPLAN_CREATED'
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_generate_wayplan_for_pickup(p_pickup_id text, p_mode text DEFAULT 'auto'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_pickup public.be_portal_pickup_requests;
  v_route_no text;
  v_route_id uuid;
  v_route_zone text;
  v_inserted integer := 0;
  v_total_stops integer := 0;
  v_total_cod numeric := 0;
begin
  select *
  into v_pickup
  from public.be_portal_pickup_requests
  where pickup_id = upper(trim(p_pickup_id))
    and coalesce(status, '') <> 'archived_test_data'
  limit 1;

  if v_pickup.id is null then
    raise exception 'Pickup % not found or archived', p_pickup_id;
  end if;

  v_route_no := public.be_wayplan_no_from_pickup_id(v_pickup.pickup_id);

  select public.be_wayplan_zone_for_township(
    coalesce(
      (select coalesce(e.recipient_town, e.delivery_township)
       from public.be_portal_cargo_events e
       where e.pickup_id = v_pickup.pickup_id
         and e.event_type = 'data_entry_waybill'
         and coalesce(e.status, '') <> 'archived_test_data'
       order by e.line_no
       limit 1),
      v_pickup.township
    )
  )
  into v_route_zone;

  insert into public.be_wayplan_routes (
    route_no,
    pickup_id,
    route_date,
    route_zone,
    route_status,
    assigned_rider_code,
    assigned_rider_name,
    assigned_driver_code,
    assigned_driver_name,
    assigned_helper_code,
    assigned_helper_name,
    assigned_vehicle_plate,
    payload,
    updated_at
  )
  values (
    v_route_no,
    v_pickup.pickup_id,
    coalesce(v_pickup.pickup_date, current_date),
    v_route_zone,
    case when coalesce(v_pickup.assignment_status, '') = 'assigned' then 'assigned' else 'planned' end,
    v_pickup.assigned_rider_code,
    v_pickup.assigned_rider_name,
    v_pickup.assigned_driver_code,
    v_pickup.assigned_driver_name,
    v_pickup.assigned_helper_code,
    v_pickup.assigned_helper_name,
    v_pickup.assigned_vehicle_plate,
    jsonb_build_object(
      'source', 'be_generate_wayplan_for_pickup',
      'mode', coalesce(p_mode, 'auto'),
      'pickup_id', v_pickup.pickup_id,
      'generated_at', now()
    ),
    now()
  )
  on conflict (route_no)
  do update set
    pickup_id = excluded.pickup_id,
    route_date = excluded.route_date,
    route_zone = excluded.route_zone,
    route_status = case
      when public.be_wayplan_routes.route_status in ('delivered', 'closed') then public.be_wayplan_routes.route_status
      else excluded.route_status
    end,
    assigned_rider_code = excluded.assigned_rider_code,
    assigned_rider_name = excluded.assigned_rider_name,
    assigned_driver_code = excluded.assigned_driver_code,
    assigned_driver_name = excluded.assigned_driver_name,
    assigned_helper_code = excluded.assigned_helper_code,
    assigned_helper_name = excluded.assigned_helper_name,
    assigned_vehicle_plate = excluded.assigned_vehicle_plate,
    payload = coalesce(public.be_wayplan_routes.payload, '{}'::jsonb) || excluded.payload,
    updated_at = now()
  returning id into v_route_id;

  with ordered as (
    select
      e.id as cargo_event_id,
      e.pickup_id,
      coalesce(e.deliver_way_id, e.tracking_no) as deliver_way_id,
      row_number() over (
        order by
          public.be_wayplan_zone_for_township(coalesce(e.recipient_town, e.delivery_township)),
          coalesce(e.recipient_town, e.delivery_township, ''),
          coalesce(e.line_no, 999999),
          coalesce(e.deliver_way_id, e.tracking_no)
      )::int as stop_sequence,
      coalesce(e.recipient_town, e.delivery_township) as township,
      e.receiver_name as recipient_name,
      e.receiver_phone as recipient_phone,
      e.delivery_address,
      coalesce(e.final_cod, e.cod_amount, 0) as cod_amount,
      coalesce(e.field_pickup_weight_kg, e.weight_kg, 0) as weight_kg,
      coalesce(e.status, 'planned') as source_status,
      e.line_no
    from public.be_portal_cargo_events e
    where e.pickup_id = v_pickup.pickup_id
      and e.event_type = 'data_entry_waybill'
      and coalesce(e.status, '') <> 'archived_test_data'
      and coalesce(e.deliver_way_id, e.tracking_no) is not null
  ),
  upserted as (
    insert into public.be_wayplan_stops (
      route_id,
      route_no,
      pickup_id,
      cargo_event_id,
      deliver_way_id,
      stop_sequence,
      township,
      recipient_name,
      recipient_phone,
      delivery_address,
      cod_amount,
      weight_kg,
      stop_status,
      payload,
      updated_at
    )
    select
      v_route_id,
      v_route_no,
      pickup_id,
      cargo_event_id,
      deliver_way_id,
      stop_sequence,
      township,
      recipient_name,
      recipient_phone,
      delivery_address,
      cod_amount,
      weight_kg,
      case
        when source_status in ('delivered', 'failed', 'return') then source_status
        when coalesce(v_pickup.assignment_status, '') = 'assigned' then 'assigned'
        else 'planned'
      end,
      jsonb_build_object(
        'source', 'be_portal_cargo_events',
        'line_no', line_no,
        'zone', public.be_wayplan_zone_for_township(township)
      ),
      now()
    from ordered
    on conflict (route_no, deliver_way_id)
    do update set
      route_id = excluded.route_id,
      pickup_id = excluded.pickup_id,
      cargo_event_id = excluded.cargo_event_id,
      stop_sequence = excluded.stop_sequence,
      township = excluded.township,
      recipient_name = excluded.recipient_name,
      recipient_phone = excluded.recipient_phone,
      delivery_address = excluded.delivery_address,
      cod_amount = excluded.cod_amount,
      weight_kg = excluded.weight_kg,
      stop_status = case
        when public.be_wayplan_stops.stop_status in ('delivered', 'failed', 'return') then public.be_wayplan_stops.stop_status
        else excluded.stop_status
      end,
      payload = coalesce(public.be_wayplan_stops.payload, '{}'::jsonb) || excluded.payload,
      updated_at = now()
    returning 1
  )
  select count(*) into v_inserted from upserted;

  update public.be_portal_cargo_events e
  set
    wayplan_route_no = v_route_no,
    wayplan_stop_sequence = s.stop_sequence,
    wayplan_status = s.stop_status,
    wayplan_generated_at = now(),
    updated_at = now(),
    payload = coalesce(e.payload, '{}'::jsonb) || jsonb_build_object(
      'wayplan_route_no', v_route_no,
      'wayplan_stop_sequence', s.stop_sequence,
      'wayplan_status', s.stop_status
    )
  from public.be_wayplan_stops s
  where s.cargo_event_id = e.id
    and s.route_no = v_route_no;

  select
    count(*),
    coalesce(sum(cod_amount), 0)
  into v_total_stops, v_total_cod
  from public.be_wayplan_stops
  where route_no = v_route_no;

  update public.be_wayplan_routes r
  set
    total_stops = v_total_stops,
    total_cod = v_total_cod,
    completed_stops = (
      select count(*) from public.be_wayplan_stops s
      where s.route_no = v_route_no and s.stop_status = 'delivered'
    ),
    failed_stops = (
      select count(*) from public.be_wayplan_stops s
      where s.route_no = v_route_no and s.stop_status in ('failed', 'return')
    ),
    updated_at = now()
  where r.route_no = v_route_no;

  return jsonb_build_object(
    'ok', true,
    'pickup_id', v_pickup.pickup_id,
    'wayplan_route_no', v_route_no,
    'route_zone', v_route_zone,
    'inserted_or_updated_stops', v_inserted,
    'total_stops', v_total_stops,
    'total_cod', v_total_cod
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_get_branch_office_dashboard(p_branch text DEFAULT 'YGN'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
begin

return jsonb_build_object(

'ok',true,

'branch',
jsonb_build_object(
 'code',p_branch
),

'staff',
(
 select coalesce(jsonb_agg(x),'[]'::jsonb)
 from (
   select
    worker_code,
    display_name,
    role,
    status
   from public.be_mobile_workforce_accounts
   where branch_code=p_branch
 ) x
),

'pickup_queue',
(
 select coalesce(jsonb_agg(x),'[]'::jsonb)
 from (
   select
    pickup_id,
    merchant_name,
    pickup_status,
    assigned_rider_code
   from public.be_portal_pickup_requests
   where branch_code=p_branch
 ) x
)

);

end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_get_business_development_dashboard(p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
begin
  return jsonb_build_object(
    'ok', true,

    'overview',
    jsonb_build_object(
      'total_customers',
      (select count(*) from public.be_master_merchants),

      'active_pipeline',
      (select count(*)
       from public.be_portal_pickup_requests
       where pickup_status not in ('DELIVERED','CANCELLED')),

      'monthly_revenue',
      (
        select coalesce(sum(actual_collect),0)
        from public.be_data_entry_parcel_details
      )
    ),

    'customers',
    (
      select coalesce(jsonb_agg(x),'[]'::jsonb)
      from (
        select
          merchant_code,
          merchant_name,
          status
        from public.be_master_merchants
        order by merchant_name
      ) x
    ),

    'pipeline',
    (
      select coalesce(jsonb_agg(x),'[]'::jsonb)
      from (
        select
          pickup_id,
          merchant_name,
          pickup_status,
          expected_parcels
        from public.be_portal_pickup_requests
        order by created_at desc
      ) x
    )
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_get_dashboard_summary()
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_pickup_count INTEGER;
  v_cod_total NUMERIC;
  v_exception_count INTEGER;
BEGIN
  -- Count active pickups
  SELECT COUNT(*) INTO v_pickup_count
  FROM be_pickup_requests
  WHERE status NOT IN ('DONE', 'CANCELLED');

  -- Sum pending COD collections
  SELECT COALESCE(SUM(cod_amount), 0) INTO v_cod_total
  FROM be_pickup_requests
  WHERE cod_settlement_status = 'PENDING';

  -- Count open exceptions
  SELECT COUNT(*) INTO v_exception_count
  FROM be_pickup_requests
  WHERE status = 'EXCEPTION';

  RETURN json_build_object(
    'active_pickups', v_pickup_count,
    'total_cod_mmk', v_cod_total,
    'open_exceptions', v_exception_count
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_get_data_entry_rider_verified_pickups(p_branch_code text)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
AS $function$
  select coalesce(
    jsonb_agg(to_jsonb(q) order by q.updated_at desc nulls last),
    '[]'::jsonb
  )
  from (
    select
      p.id,
      p.pickup_id,
      coalesce(p.pickup_way_id, p.pickup_id) as pickup_way_id,
      coalesce(p.tracking_no, p.pickup_way_id, p.pickup_id) as tracking_no,

      coalesce(p.branch_code, 'YGN') as branch_code,
      p.merchant_code,
      p.merchant_name,
      p.pickup_status,
      p.rider_status,
      p.workflow_stage,

      coalesce(p.expected_parcels, p.delivery_count, 1) as expected_parcels,
      coalesce(p.delivery_count, p.expected_parcels, 1) as delivery_count,

      coalesce(sum(v.photo_count), 0) as uploaded_photo_count,
      coalesce(sum(v.photo_count), 0) as verified_parcels,
      coalesce(sum(v.photo_count), 0) as photo_count,
      coalesce(sum(v.photo_count), 0) as photos_count,
      coalesce(sum(v.photo_count), 0) as proof_count,

      coalesce(count(v.id), 0) as parcel_rows,

      max(v.proof_photo_path) as proof_photo_path,
      max(v.proof_url) as proof_url,
      max(v.photo_url) as photo_url,
      max(v.updated_at) as latest_photo_at,

      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'id', v.id,
            'pickup_id', v.pickup_id,
            'item_no', v.item_no,
            'parcel_sequence', v.parcel_sequence,
            'delivery_way_id', v.delivery_way_id,
            'tracking_no', v.tracking_no,
            'weight_kg', v.weight_kg,
            'actual_weight_kg', v.actual_weight_kg,
            'proof_photo_path', v.proof_photo_path,
            'proof_url', v.proof_url,
            'photo_url', v.photo_url,
            'proof_urls', v.proof_urls,
            'photo_count', v.photo_count,
            'proof_status', v.proof_status
          )
          order by v.item_no
        ) filter (where v.id is not null),
        '[]'::jsonb
      ) as items,

      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'id', v.id,
            'pickup_id', v.pickup_id,
            'item_no', v.item_no,
            'parcel_sequence', v.parcel_sequence,
            'delivery_way_id', v.delivery_way_id,
            'tracking_no', v.tracking_no,
            'weight_kg', v.weight_kg,
            'actual_weight_kg', v.actual_weight_kg,
            'proof_photo_path', v.proof_photo_path,
            'proof_url', v.proof_url,
            'photo_url', v.photo_url,
            'proof_urls', v.proof_urls,
            'photo_count', v.photo_count,
            'proof_status', v.proof_status
          )
          order by v.item_no
        ) filter (where v.id is not null),
        '[]'::jsonb
      ) as proofs,

      p.updated_at

    from public.be_portal_pickup_requests p
    left join public.be_v_data_entry_parcel_proofs v
      on v.pickup_id = p.pickup_id
    where (
      coalesce(p_branch_code, '') = ''
      or coalesce(p.branch_code, 'YGN') = p_branch_code
    )
    and (
      coalesce(p.pickup_status, '') in (
        'PICKUP_VERIFIED',
        'ARRIVED_AT_PICKUP',
        'PICKUP_ASSIGNED',
        'PICKUP_ACCEPTED'
      )
      or coalesce(p.rider_status, '') in (
        'PICKUP_VERIFIED',
        'ARRIVED_AT_PICKUP',
        'PICKUP_ACCEPTED',
        'WAITING_ACCEPTANCE'
      )
    )
    group by
      p.id,
      p.pickup_id,
      p.pickup_way_id,
      p.tracking_no,
      p.branch_code,
      p.merchant_code,
      p.merchant_name,
      p.pickup_status,
      p.rider_status,
      p.workflow_stage,
      p.expected_parcels,
      p.delivery_count,
      p.updated_at
  ) q;
$function$
;

CREATE OR REPLACE FUNCTION public.be_get_data_entry_rider_verified_pickups(p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
AS $function$
  select coalesce(
    jsonb_agg(to_jsonb(q) order by q.updated_at desc nulls last),
    '[]'::jsonb
  )
  from (
    select
      p.id,
      p.pickup_id,
      coalesce(p.pickup_way_id, p.pickup_id) as pickup_way_id,
      coalesce(p.tracking_no, p.pickup_way_id, p.pickup_id) as tracking_no,
      coalesce(p.branch_code, 'YGN') as branch_code,

      p.merchant_code,
      p.merchant_name,
      p.pickup_status,
      p.rider_status,
      p.workflow_stage,

      coalesce(p.expected_parcels, p.delivery_count, 1) as expected_parcels,
      coalesce(p.delivery_count, p.expected_parcels, 1) as delivery_count,

      coalesce(sum(v.photo_count), 0) as uploaded_photo_count,
      coalesce(sum(v.photo_count), 0) as verified_parcels,
      coalesce(sum(v.photo_count), 0) as photo_count,
      coalesce(sum(v.photo_count), 0) as photos_count,
      coalesce(sum(v.photo_count), 0) as proof_count,

      coalesce(count(v.id), 0) as parcel_rows,

      max(v.proof_photo_path) as proof_photo_path,
      max(v.proof_url) as proof_url,
      max(v.photo_url) as photo_url,
      max(v.updated_at) as latest_photo_at,

      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'id', v.id,
            'pickup_id', v.pickup_id,
            'item_no', v.item_no,
            'parcel_sequence', v.parcel_sequence,
            'delivery_way_id', v.delivery_way_id,
            'tracking_no', v.tracking_no,
            'weight_kg', v.weight_kg,
            'actual_weight_kg', v.actual_weight_kg,
            'proof_photo_path', v.proof_photo_path,
            'proof_url', v.proof_url,
            'photo_url', v.photo_url,
            'proof_urls', v.proof_urls,
            'photo_count', v.photo_count,
            'proof_status', v.proof_status
          )
          order by v.item_no
        ) filter (where v.id is not null),
        '[]'::jsonb
      ) as items,

      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'id', v.id,
            'pickup_id', v.pickup_id,
            'item_no', v.item_no,
            'parcel_sequence', v.parcel_sequence,
            'delivery_way_id', v.delivery_way_id,
            'tracking_no', v.tracking_no,
            'weight_kg', v.weight_kg,
            'actual_weight_kg', v.actual_weight_kg,
            'proof_photo_path', v.proof_photo_path,
            'proof_url', v.proof_url,
            'photo_url', v.photo_url,
            'proof_urls', v.proof_urls,
            'photo_count', v.photo_count,
            'proof_status', v.proof_status
          )
          order by v.item_no
        ) filter (where v.id is not null),
        '[]'::jsonb
      ) as proofs,

      p.updated_at

    from public.be_portal_pickup_requests p
    left join public.be_v_data_entry_parcel_proofs v
      on v.pickup_id = p.pickup_id
    where (
      coalesce(p_payload->>'branch_code', '') = ''
      or coalesce(p.branch_code, 'YGN') = p_payload->>'branch_code'
    )
    and (
      coalesce(p.pickup_status, '') in (
        'PICKUP_VERIFIED',
        'ARRIVED_AT_PICKUP',
        'PICKUP_ASSIGNED',
        'PICKUP_ACCEPTED'
      )
      or coalesce(p.rider_status, '') in (
        'PICKUP_VERIFIED',
        'ARRIVED_AT_PICKUP',
        'PICKUP_ACCEPTED',
        'WAITING_ACCEPTANCE'
      )
    )
    group by
      p.id,
      p.pickup_id,
      p.pickup_way_id,
      p.tracking_no,
      p.branch_code,
      p.merchant_code,
      p.merchant_name,
      p.pickup_status,
      p.rider_status,
      p.workflow_stage,
      p.expected_parcels,
      p.delivery_count,
      p.updated_at
  ) q;
$function$
;

CREATE OR REPLACE FUNCTION public.be_get_document_print_room(p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_jobs jsonb;
begin
  select coalesce(jsonb_agg(x order by x.document_type, x.document_title), '[]'::jsonb)
  into v_jobs
  from (
    select *
    from public.be_document_print_jobs
  ) x;

  return jsonb_build_object(
    'ok', true,
    'jobs', v_jobs,
    'stats', jsonb_build_object(
      'documents', (select count(*) from public.be_document_print_jobs),
      'ready', (select count(*) from public.be_document_print_jobs where print_status = 'READY'),
      'superadmin_only', (select count(*) from public.be_document_print_jobs where access_role = 'superadmin')
    )
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_get_invoice_print_studio(p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_date date := nullif(p_payload->>'date','')::date;
  v_invoices jsonb;
  v_requests jsonb;
begin
  select coalesce(jsonb_agg(x order by x.invoice_date desc, x.invoice_id desc), '[]'::jsonb)
  into v_invoices
  from (
    select *
    from public.be_invoice_print_records
    where v_date is null or invoice_date = v_date
    order by invoice_date desc, invoice_id desc
    limit 300
  ) x;

  select coalesce(jsonb_agg(x order by x.created_at desc), '[]'::jsonb)
  into v_requests
  from (
    select *
    from public.be_invoice_reprint_requests
    order by created_at desc
    limit 100
  ) x;

  return jsonb_build_object(
    'ok', true,
    'invoices', v_invoices,
    'reprint_requests', v_requests
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_get_live_dispatch_wayplan_board(p_branch_code text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
BEGIN
  RETURN json_build_object(
    'unassigned', (
        SELECT COALESCE(json_agg(row_to_json(p)), '[]'::json)
        FROM public.be_portal_pickup_requests p
        WHERE assigned_rider_id IS NULL AND status IN ('PICKUP_REQUESTED', 'READY_FOR_DISPATCH')
        AND (p_branch_code IS NULL OR branch_code = p_branch_code)
    ),
    'workforce', (
        SELECT COALESCE(json_agg(row_to_json(w)), '[]'::json)
        FROM public.be_user_account_registry w
        WHERE role IN ('rider', 'driver') AND status = 'active'
        AND (p_branch_code IS NULL OR branch_code = p_branch_code)
    )
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_get_live_dispatch_wayplan_board(p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_branch text := upper(coalesce(p_payload->>'branch_code', 'HQ'));
  v_limit integer := least(greatest(coalesce(nullif(p_payload->>'limit', '')::integer, 300), 1), 1000);

  v_pickups jsonb := '[]'::jsonb;
  v_workforce jsonb := '[]'::jsonb;
  v_assignments jsonb := '[]'::jsonb;
begin
  if to_regclass('public.be_portal_pickup_requests') is not null then
    execute $q$
      select coalesce(jsonb_agg(to_jsonb(x)), '[]'::jsonb)
      from (
        select *
        from public.be_portal_pickup_requests p
        where (
          $1 = ''
          or upper(coalesce(to_jsonb(p)->>'branch_code', to_jsonb(p)->'metadata'->>'branch_code', 'HQ')) = $1
        )
        and upper(coalesce(to_jsonb(p)->>'status', 'PICKUP_REQUESTED')) in (
          'PICKUP_REQUESTED',
          'PICKUP_ASSIGNED',
          'PICKUP_COMPLETED',
          'READY_FOR_DISPATCH',
          'READY_FOR_DELIVERY',
          'DELIVERY_ASSIGNED'
        )
        order by coalesce(to_jsonb(p)->>'created_at', '') desc
        limit $2
      ) x
    $q$
    into v_pickups
    using v_branch, v_limit;
  end if;

  if to_regclass('public.be_mobile_workforce_accounts') is not null then
    execute $q$
      select coalesce(jsonb_agg(to_jsonb(x)), '[]'::jsonb)
      from (
        select *
        from public.be_mobile_workforce_accounts w
        where coalesce((to_jsonb(w)->>'active')::boolean, true) = true
          and lower(coalesce(to_jsonb(w)->>'role_type', to_jsonb(w)->>'workforce_type', to_jsonb(w)->>'role', '')) in (
            'rider',
            'driver',
            'helper',
            'mobile'
          )
        order by coalesce(to_jsonb(w)->>'rider_code', to_jsonb(w)->>'worker_id', to_jsonb(w)->>'full_name', '')
        limit 1000
      ) x
    $q$
    into v_workforce;
  end if;

  select coalesce(jsonb_agg(to_jsonb(a) order by a.assigned_at desc), '[]'::jsonb)
  into v_assignments
  from public.be_dispatch_wayplan_assignments a
  where ($1 = '' or upper(coalesce(a.branch_code, 'HQ')) = $1)
  limit v_limit;

  return jsonb_build_object(
    'ok', true,
    'branch_code', v_branch,
    'pickups', coalesce(v_pickups, '[]'::jsonb),
    'workforce', coalesce(v_workforce, '[]'::jsonb),
    'assignments', coalesce(v_assignments, '[]'::jsonb)
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_get_manifest_print_ready(p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_rows jsonb;
begin
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'way_id', coalesce(d.delivery_way_id, d.way_id),
      'pickup_id', d.pickup_id,
      'recipient_name', d.recipient_name,
      'township', d.township,
      'address', d.recipient_address,
      'weight_kg', coalesce(d.weight_kg, 0),
      'item_price', coalesce(d.item_price, 0),
      'delivery_fee', coalesce(d.delivery_fee, 0),
      'weight_fee', greatest(coalesce(d.delivery_fee, 0) - coalesce(d.surcharge, 0), 0),
      'total', coalesce(d.actual_collect, d.cod_amount, 0),
      'phone', d.contact_no_1,
      'remark', coalesce(d.remark, ''),
      'rider_name', coalesce(d.assigned_rider_name, 'Unassigned Rider'),
      'branch_name', coalesce(d.township, 'Britium Route')
    )
    order by coalesce(d.assigned_rider_name, 'Unassigned Rider'), d.township, d.parcel_sequence
  ), '[]'::jsonb)
  into v_rows
  from public.be_data_entry_parcel_details d
  where coalesce(d.recipient_name, '') <> '';

  return jsonb_build_object(
    'ok', true,
    'rows', v_rows
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_get_merchant_options(p_include_inactive boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
AS $function$
  select jsonb_build_object(
    'ok', true,
    'merchants',
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'merchant_code', merchant_code,
          'merchant_name', merchant_name,
          'business_type', business_type,
          'contact_person', contact_person,
          'phone_primary', phone_primary,
          'phone_secondary', phone_secondary,
          'email', email,
          'address_mm', address_mm,
          'address_line_1', address_line_1,
          'township', township,
          'city', city,
          'region_state', region_state,
          'customer_tier', customer_tier,
          'allowed_cargo_weight_kg', allowed_cargo_weight_kg,
          'monthly_commitment_parcels', monthly_commitment_parcels,
          'commitment_discount_mmk', commitment_discount_mmk,
          'status', coalesce(nullif(status, ''), 'Active'),
          'refund_amount', refund_amount
        )
        order by merchant_code
      ),
      '[]'::jsonb
    )
  )
  from public.be_master_merchants
  where
    p_include_inactive
    or coalesce(nullif(status, ''), 'Active') ilike 'Active';
$function$
;

