CREATE OR REPLACE FUNCTION public.be_get_operational_masterdata()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_result jsonb;
BEGIN
    SELECT jsonb_object_agg(dropdown_name, values_array)
    INTO v_result
    FROM (
        SELECT dropdown_name, jsonb_agg(jsonb_build_object('value', value, 'myanmar_label', myanmar_label, 'is_active', is_active)) as values_array
        FROM public.be_master_data_options
        WHERE is_active = true
        GROUP BY dropdown_name
    ) sub;
    RETURN coalesce(v_result, '{}'::jsonb);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_get_operational_masterdata(p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_rules jsonb := '{}'::jsonb;
  v_branches jsonb := '[]'::jsonb;
  v_pickups jsonb := '[]'::jsonb;
  v_tariffs jsonb := '[]'::jsonb;
  v_merchants jsonb := '[]'::jsonb;
begin
  if to_regprocedure('public.be_logistics_get_field_rules()') is not null then
    select public.be_logistics_get_field_rules() into v_rules;
  end if;

  if to_regclass('public.be_branch_nodes') is not null then
    execute 'select coalesce(jsonb_agg(to_jsonb(t)), ''[]''::jsonb) from (select * from public.be_branch_nodes limit 300) t' into v_branches;
  end if;

  if to_regclass('public.be_portal_pickup_requests') is not null then
    execute 'select coalesce(jsonb_agg(to_jsonb(t)), ''[]''::jsonb) from (select * from public.be_portal_pickup_requests order by created_at desc nulls last limit 300) t' into v_pickups;
  end if;

  if to_regclass('public.be_tariff_master') is not null then
    execute 'select coalesce(jsonb_agg(to_jsonb(t)), ''[]''::jsonb) from (select * from public.be_tariff_master limit 300) t' into v_tariffs;
  end if;

  if to_regclass('public.be_master_merchants') is not null then
    execute 'select coalesce(jsonb_agg(to_jsonb(t)), ''[]''::jsonb) from (select * from public.be_master_merchants limit 300) t' into v_merchants;
  elsif to_regclass('public.merchants') is not null then
    execute 'select coalesce(jsonb_agg(to_jsonb(t)), ''[]''::jsonb) from (select * from public.merchants limit 300) t' into v_merchants;
  elsif to_regclass('public.merchant_master') is not null then
    execute 'select coalesce(jsonb_agg(to_jsonb(t)), ''[]''::jsonb) from (select * from public.merchant_master limit 300) t' into v_merchants;
  end if;

  return jsonb_build_object(
    'ok', true,
    'field_rules', coalesce(v_rules, '{}'::jsonb),
    'branches', coalesce(v_branches, '[]'::jsonb),
    'pickup_options', coalesce(v_pickups, '[]'::jsonb),
    'tariffs', coalesce(v_tariffs, '[]'::jsonb),
    'merchants', coalesce(v_merchants, '[]'::jsonb)
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_get_operations_screen(p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_screen text := coalesce(p_payload->>'screen','executive');
  v_result jsonb;
begin
  if v_screen = 'wayplan' then
    select jsonb_build_object(
      'ok', true,
      'screen', v_screen,
      'stats', jsonb_build_object(
        'wayplans', count(distinct wayplan_id),
        'active', count(*) filter (where stop_status = 'active'),
        'planned', count(*) filter (where stop_status = 'planned'),
        'completed', count(*) filter (where stop_status = 'completed'),
        'stops', count(*),
        'done_stops', count(*) filter (where stop_status = 'completed'),
        'exception_stops', count(*) filter (where stop_status = 'exception')
      ),
      'rows', coalesce(jsonb_agg(jsonb_build_object(
        'id', id,
        'wayplan_id', wayplan_id,
        'pickup_id', pickup_id,
        'delivery_way_id', delivery_way_id,
        'sequence_no', sequence_no,
        'merchant_name', merchant_name,
        'customer_name', customer_name,
        'address', address,
        'township', township,
        'rider_name', rider_name,
        'vehicle_no', vehicle_no,
        'stop_status', stop_status,
        'exception_note', exception_note
      ) order by sequence_no), '[]'::jsonb)
    )
    into v_result
    from public.be_wayplan_command_rows;

  elsif v_screen = 'executive' then
    select jsonb_build_object(
      'ok', true,
      'screen', v_screen,
      'stats', jsonb_build_object(
        'total_pickups', (select count(*) from public.be_portal_pickup_requests),
        'submitted_pickups', (select count(*) from public.be_portal_pickup_requests where coalesce(status,'') ilike '%SUBMIT%'),
        'total_deliveries', (select count(*) from public.be_data_entry_parcel_details),
        'delivered', (select count(*) from public.be_data_entry_parcel_details where warehouse_status = 'DELIVERED'),
        'cod_expected', (select coalesce(sum(coalesce(actual_collect, cod_amount, 0)),0) from public.be_data_entry_parcel_details),
        'cod_collected', (select coalesce(sum(cod_amount),0) from public.be_cod_handover_records where cod_status in ('COLLECTED','HANDED_OVER','LOCKED')),
        'posted_settlements', (select count(*) from public.be_cod_handover_records where cod_status = 'LOCKED'),
        'settlement_variance', 0
      ),
      'trend', '[]'::jsonb
    )
    into v_result;

  elsif v_screen = 'finance' then
    select jsonb_build_object(
      'ok', true,
      'screen', v_screen,
      'stats', jsonb_build_object(
        'pending_settlement', count(*) filter (where cod_status in ('PENDING_COLLECTION','COLLECTED')),
        'approval', count(*) filter (where cod_status = 'SUBMITTED'),
        'approved', count(*) filter (where cod_status = 'HANDED_OVER'),
        'unsettled_cod', coalesce(sum(cod_amount) filter (where cod_status not in ('LOCKED')),0),
        'finance_hold', 0
      ),
      'settlements', coalesce(jsonb_agg(jsonb_build_object(
        'delivery_way_id', delivery_way_id,
        'rider_name', rider_name,
        'merchant_name', merchant_name,
        'cod_amount', cod_amount,
        'cod_status', cod_status,
        'handover_ref', handover_ref,
        'created_at', created_at
      ) order by created_at desc), '[]'::jsonb)
    )
    into v_result
    from public.be_cod_handover_records;

  elsif v_screen = 'cod' then
    select jsonb_build_object(
      'ok', true,
      'screen', v_screen,
      'stats', jsonb_build_object(
        'total_cod_pool', coalesce(sum(cod_amount),0),
        'open_batches', count(*) filter (where cod_status not in ('LOCKED')),
        'disputed_cases', count(*) filter (where cod_status = 'DISPUTED'),
        'shortage_cases', count(*) filter (where cod_status = 'SHORTAGE')
      ),
      'rows', coalesce(jsonb_agg(jsonb_build_object(
        'delivery_way_id', delivery_way_id,
        'rider_name', rider_name,
        'merchant_name', merchant_name,
        'cod_amount', cod_amount,
        'cod_status', cod_status,
        'collected_at', collected_at,
        'handover_ref', handover_ref
      ) order by created_at desc), '[]'::jsonb)
    )
    into v_result
    from public.be_cod_handover_records;

  elsif v_screen = 'exceptions' then
    select jsonb_build_object(
      'ok', true,
      'screen', v_screen,
      'stats', jsonb_build_object(
        'total_exception_records', count(*),
        'pickup_exceptions', count(*) filter (where category = 'PICKUP'),
        'warehouse_exceptions', count(*) filter (where category = 'WAREHOUSE'),
        'delivery_exceptions', count(*) filter (where category = 'DELIVERY')
      ),
      'rows', coalesce(jsonb_agg(to_jsonb(e) order by code), '[]'::jsonb)
    )
    into v_result
    from public.be_exception_master_records e;

  elsif v_screen = 'reports' then
    select jsonb_build_object(
      'ok', true,
      'screen', v_screen,
      'stats', jsonb_build_object(
        'revenue', coalesce(sum(coalesce(actual_collect, cod_amount, 0)),0),
        'delivery_fee', coalesce(sum(coalesce(delivery_fee,0)),0),
        'cod_collected', (select coalesce(sum(cod_amount),0) from public.be_cod_handover_records),
        'commission', (select coalesce(sum(amount),0) from public.be_commission_records),
        'settlement_pending', 0,
        'net_position', coalesce(sum(coalesce(actual_collect, cod_amount, 0)),0)
      )
    )
    into v_result
    from public.be_data_entry_parcel_details;

  elsif v_screen = 'wallets' then
    select jsonb_build_object(
      'ok', true,
      'screen', v_screen,
      'stats', jsonb_build_object(
        'total', count(*),
        'riders', count(*) filter (where role = 'rider'),
        'drivers', count(*) filter (where role = 'driver'),
        'helpers', count(*) filter (where role = 'helper')
      ),
      'rows', coalesce(jsonb_agg(to_jsonb(w) order by code), '[]'::jsonb)
    )
    into v_result
    from public.be_workforce_wallets w;

  elsif v_screen = 'commission' then
    select jsonb_build_object(
      'ok', true,
      'screen', v_screen,
      'stats', jsonb_build_object(
        'total', coalesce(sum(amount),0),
        'records', count(*)
      ),
      'rows', coalesce(jsonb_agg(to_jsonb(c) order by created_at desc), '[]'::jsonb)
    )
    into v_result
    from public.be_commission_records c;

  elsif v_screen = 'merchant' then
    select jsonb_build_object(
      'ok', true,
      'screen', v_screen,
      'stats', jsonb_build_object(
        'pickup_requests', (select count(*) from public.be_portal_pickup_requests),
        'live_tracking', (select count(*) from public.be_data_entry_parcel_details where coalesce(warehouse_status,'') not in ('DELIVERED','RETURNED_TO_SENDER')),
        'settlement', (select coalesce(sum(coalesce(actual_collect, cod_amount, 0)),0) from public.be_data_entry_parcel_details),
        'notifications', (select count(*) from public.be_waybill_status_events)
      ),
      'rows', coalesce(jsonb_agg(jsonb_build_object(
        'pickup_id', pickup_id,
        'merchant_name', merchant_name,
        'merchant_code', merchant_code,
        'status', status,
        'created_at', created_at
      ) order by created_at desc), '[]'::jsonb)
    )
    into v_result
    from public.be_portal_pickup_requests;

  else
    v_result := jsonb_build_object('ok', false, 'error', 'Unknown screen');
  end if;

  return v_result;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_get_pickup_order_options()
 RETURNS json
 LANGUAGE sql
 STABLE SECURITY DEFINER
AS $function$
    SELECT public.be_get_operational_masterdata();
$function$
;

CREATE OR REPLACE FUNCTION public.be_get_report_catalog()
 RETURNS json
 LANGUAGE sql
 STABLE
AS $function$
    SELECT json_build_array(
        json_build_object('id', 'ops_summary', 'name', 'Operational Summary', 'category', 'Operations'),
        json_build_object('id', 'fin_cod', 'name', 'COD Settlement Report', 'category', 'Finance')
    );
$function$
;

