CREATE OR REPLACE FUNCTION public.be_get_rider_sync_payload(p_login text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_code text := upper(trim(coalesce(p_login, 'RID001')));
  v_email text := lower(
    case
      when upper(trim(coalesce(p_login, 'RID001'))) = 'RID001'
        then 'rider_ygn_0001@britiumventures.com'
      else ''
    end
  );

  v_jobs jsonb := '[]'::jsonb;
begin
  select coalesce(
    jsonb_agg(
      to_jsonb(j)
      order by j.assigned_at desc nulls last, j.updated_at desc nulls last
    ),
    '[]'::jsonb
  )
  into v_jobs
  from public.be_v_rider_workflow_jobs j
  where upper(coalesce(j.assigned_rider_code, '')) = v_code
     or upper(coalesce(j.assigned_workforce_code, '')) = v_code
     or upper(coalesce(j.rider_id, '')) = v_code
     or lower(coalesce(j.assigned_rider_email, '')) = v_email;

  return jsonb_build_object(
    'ok', true,
    'source', 'backend',
    'rider_code', v_code,
    'jobs', v_jobs,
    'pickup_jobs', v_jobs,
    'notifications', '[]'::jsonb,
    'generated_at', now()
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_get_supervisor_live_gps(p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_rows jsonb;
  v_stats jsonb;
begin
  select jsonb_build_object(
    'monitor_jobs', (select count(*) from public.be_data_entry_parcel_details where coalesce(assigned_rider_id,'') <> ''),
    'gps_available', (select count(distinct rider_id) from public.be_rider_gps_events),
    'live_now', (select count(distinct rider_id) from public.be_rider_gps_events where captured_at > now() - interval '30 minutes'),
    'waiting_gps', greatest(
      (select count(*) from public.be_data_entry_parcel_details where coalesce(assigned_rider_id,'') <> '') -
      (select count(distinct rider_id) from public.be_rider_gps_events where captured_at > now() - interval '30 minutes'),
      0
    )
  )
  into v_stats;

  select coalesce(jsonb_agg(x order by (x->>'captured_at') desc), '[]'::jsonb)
  into v_rows
  from (
    select distinct on (rider_id)
      jsonb_build_object(
        'rider_id', rider_id,
        'rider_name', rider_name,
        'pickup_id', pickup_id,
        'delivery_way_id', delivery_way_id,
        'latitude', latitude,
        'longitude', longitude,
        'accuracy_m', accuracy_m,
        'gps_status', gps_status,
        'captured_at', captured_at
      ) x
    from public.be_rider_gps_events
    order by rider_id, captured_at desc
  ) q;

  return jsonb_build_object('ok', true, 'stats', v_stats, 'gps_rows', v_rows);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_get_supervisor_portal(p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_pickups jsonb;
  v_dropoffs jsonb;
  v_gps jsonb;
  v_notifications jsonb;
  v_settlements jsonb;
  v_wayplans jsonb;
  v_stats jsonb;
begin
  select jsonb_build_object(
    'assigned_pickups', count(*) filter (where coalesce(assigned_rider_id,'') <> ''),
    'pending_pickups', count(*) filter (where coalesce(assigned_rider_id,'') = ''),
    'confirmed_wayplans', count(*) filter (where coalesce(wayplan_status,'') ilike '%CONFIRM%'),
    'alerts', count(*) filter (
      where coalesce(supervisor_status,'') ilike '%FAILED%'
         or coalesce(supervisor_status,'') ilike '%ISSUE%'
    )
  )
  into v_stats
  from public.be_portal_pickup_requests;

  select coalesce(jsonb_agg(x order by x.created_at desc), '[]'::jsonb)
  into v_pickups
  from (
    select
      coalesce(pickup_id, pickup_way_id) as pickup_id,
      merchant_name,
      merchant_code,
      assigned_rider_id,
      assigned_rider_name,
      supervisor_status,
      wayplan_status,
      supervisor_note,
      created_at
    from public.be_portal_pickup_requests
    order by created_at desc
    limit 100
  ) x;

  select coalesce(jsonb_agg(x order by x.created_at desc), '[]'::jsonb)
  into v_dropoffs
  from (
    select
      coalesce(way_id, delivery_way_id) as waybill_no,
      pickup_id,
      recipient_name,
      contact_no_1 as phone,
      township,
      assigned_rider_id,
      assigned_rider_name,
      supervisor_status,
      warehouse_status,
      coalesce(actual_collect, cod_amount, 0) as cod_amount,
      coalesce(saved_at, updated_at, now()) as created_at
    from public.be_data_entry_parcel_details
    where coalesce(recipient_name,'') <> ''
    order by coalesce(saved_at, updated_at, now()) desc
    limit 150
  ) x;

  select coalesce(jsonb_agg(x order by x.captured_at desc), '[]'::jsonb)
  into v_gps
  from (
    select distinct on (rider_id)
      rider_id,
      rider_name,
      pickup_id,
      delivery_way_id,
      latitude,
      longitude,
      accuracy_m,
      gps_status,
      captured_at
    from public.be_rider_gps_events
    order by rider_id, captured_at desc
  ) x;

  select coalesce(jsonb_agg(x order by x.created_at desc), '[]'::jsonb)
  into v_notifications
  from (
    select
      event_code,
      event_name,
      waybill_no,
      pickup_id,
      source_module,
      note,
      created_at
    from public.be_waybill_status_events
    order by created_at desc
    limit 50
  ) x;

  select coalesce(jsonb_agg(x order by x.cod_total desc), '[]'::jsonb)
  into v_settlements
  from (
    select
      coalesce(merchant_id, 'UNKNOWN') as merchant,
      count(*) as count,
      sum(coalesce(actual_collect, cod_amount, 0)) as cod_total,
      coalesce(finance_status, 'PENDING_INVOICE') as finance_status
    from public.be_data_entry_parcel_details
    group by coalesce(merchant_id, 'UNKNOWN'), coalesce(finance_status, 'PENDING_INVOICE')
    limit 50
  ) x;

  select coalesce(jsonb_agg(x order by x.pickup_id desc), '[]'::jsonb)
  into v_wayplans
  from (
    select
      pickup_id,
      count(*) as waybill_count,
      sum(coalesce(actual_collect, cod_amount, 0)) as cod_total,
      max(coalesce(way_management_status, 'PENDING_WAYPLAN')) as status
    from public.be_data_entry_parcel_details
    where coalesce(pickup_id,'') <> ''
    group by pickup_id
    limit 50
  ) x;

  return jsonb_build_object(
    'ok', true,
    'stats', v_stats,
    'pickup_assignments', v_pickups,
    'dropoff_assignments', v_dropoffs,
    'gps', v_gps,
    'notifications', v_notifications,
    'settlements', v_settlements,
    'wayplans', v_wayplans
  );
end;
$function$
;

