CREATE OR REPLACE FUNCTION public.be_get_warehouse_lifecycle(p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_rows jsonb;
  v_stats jsonb;
  v_master jsonb;
begin
  select jsonb_build_object(
    'rows', count(*),
    'received', count(*) filter (where warehouse_status = 'RECEIVED_AT_ORIGIN'),
    'dispatch_scan', count(*) filter (where warehouse_status = 'READY_FOR_DISPATCH' or warehouse_status = 'DISPATCHED'),
    'returns', count(*) filter (where warehouse_status ilike '%RETURN%'),
    'priority', count(*) filter (where supervisor_status ilike '%PRIORITY%'),
    'rto', count(*) filter (where warehouse_status ilike '%RTO%')
  )
  into v_stats
  from public.be_data_entry_parcel_details;

  select coalesce(jsonb_agg(jsonb_build_object(
    'waybill_no', coalesce(way_id, delivery_way_id),
    'pickup_id', pickup_id,
    'delivery_way_id', delivery_way_id,
    'merchant', merchant_id,
    'recipient', recipient_name,
    'phone', contact_no_1,
    'township', township,
    'cod', coalesce(actual_collect, cod_amount, 0),
    'warehouse_status', warehouse_status,
    'inbound_scanned_at', inbound_scanned_at,
    'dispatch_scanned_at', dispatch_scanned_at,
    'return_scanned_at', return_scanned_at,
    'finance_status', finance_status,
    'way_management_status', way_management_status
  ) order by coalesce(updated_at, saved_at, now()) desc), '[]'::jsonb)
  into v_rows
  from public.be_data_entry_parcel_details
  where coalesce(recipient_name,'') <> ''
  limit 300;

  select coalesce(jsonb_agg(jsonb_build_object(
    'status_code', status_code,
    'name_en', name_en,
    'name_mm', name_mm,
    'process_type', process_type,
    'status_group', status_group,
    'final', is_final,
    'exception', is_exception,
    'live_count', 0
  ) order by sort_order), '[]'::jsonb)
  into v_master
  from public.be_waybill_status_master;

  return jsonb_build_object('ok', true, 'stats', v_stats, 'rows', v_rows, 'master', v_master);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_get_waybill_print_queue(p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_date text := nullif(trim(coalesce(p_payload->>'date', '')), '');
  v_rows jsonb;
begin
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'id', coalesce(d.way_id, d.delivery_way_id),
      'waybill_id', coalesce(d.way_id, d.delivery_way_id),
      'waybill_no', coalesce(d.way_id, d.delivery_way_id),
      'delivery_way_id', d.delivery_way_id,
      'pickup_id', d.pickup_id,
      'parcel_sequence', d.parcel_sequence,

      'merchant_code', coalesce(d.merchant_id, p.merchant_code, ''),
      'merchant_name', coalesce(p.merchant_name, d.merchant_id, 'Britium Merchant'),
      'merchant_phone', '',

      'receiver_name', d.recipient_name,
      'recipient_name', d.recipient_name,
      'receiver_phone', d.contact_no_1,
      'recipient_phone', d.contact_no_1,
      'receiver_address', d.recipient_address,
      'recipient_address', d.recipient_address,
      'delivery_address', d.recipient_address,

      'destination_city', coalesce(d.destination, 'Yangon'),
      'destination_township', d.township,

      'item_price', coalesce(d.item_price, 0),
      'delivery_fee', coalesce(d.delivery_fee, 0),
      'surcharge', coalesce(d.surcharge, 0),
      'cod_amount', coalesce(d.actual_collect, d.cod_amount, 0),
      'actual_collect', coalesce(d.actual_collect, d.cod_amount, 0),
      'weight_kg', coalesce(d.weight_kg, 0),

      'remarks', d.remark,
      'status', 'GENERATED',
      'print_status', coalesce(d.print_status, 'Ready'),
      'warehouse_status', coalesce(d.warehouse_status, 'PENDING_PRINT'),
      'way_management_status', coalesce(d.way_management_status, 'PENDING_PRINT'),
      'finance_status', coalesce(d.finance_status, 'PENDING_INVOICE'),
      'printed_at', d.printed_at,
      'printed_by', d.printed_by,

      'date', to_char(coalesce(d.saved_at, d.updated_at, now()), 'YYYY-MM-DD'),
      'created_at', coalesce(d.saved_at, d.updated_at, now())
    )
    order by coalesce(d.saved_at, d.updated_at, now()) desc, d.pickup_id desc, d.parcel_sequence asc
  ), '[]'::jsonb)
  into v_rows
  from public.be_data_entry_parcel_details d
  left join public.be_portal_pickup_requests p
    on p.pickup_id = d.pickup_id
    or p.pickup_way_id = d.pickup_id
  where coalesce(d.pickup_id, '') <> ''
    and coalesce(d.recipient_name, '') <> ''
    and (
      v_date is null
      or to_char(coalesce(d.saved_at, d.updated_at, now()), 'YYYY-MM-DD') = v_date
    );

  return jsonb_build_object(
    'ok', true,
    'source', 'be_data_entry_parcel_details',
    'waybills', v_rows
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_gl_bulk_register_delivery_rows(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare v_batch public.be_template_upload_batches; v_count int := coalesce(jsonb_array_length(coalesce(p_payload->'rows','[]'::jsonb)),0);
begin
  insert into public.be_template_upload_batches(template_type,file_name,row_count,valid_count,error_count,status,uploaded_by,payload)
  values(coalesce(p_payload->>'template_type','data_entry_register'),p_payload->>'file_name',v_count,v_count,0,'validated',p_payload->>'uploaded_by',p_payload)
  returning * into v_batch;
  insert into public.be_parcel_status_timeline(status_code,status_label,source_module,notes,metadata)
  values('bulk_registered','Bulk registered','data_entry','Bulk Excel/webform registration',row_to_json(v_batch)::jsonb);
  return jsonb_build_object('ok',true,'batch',row_to_json(v_batch)::jsonb);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_gl_code(p_value text, p_default text DEFAULT 'GEN'::text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select left(
    coalesce(nullif(upper(regexp_replace(coalesce(p_value, ''), '[^A-Z0-9]', '', 'g')), ''), p_default),
    12
  );
$function$
;

CREATE OR REPLACE FUNCTION public.be_gl_delivery_id(p_pickup_date date, p_merchant_code text, p_sequence integer)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  select 'D'
    || to_char(coalesce(p_pickup_date, current_date), 'MMDD')
    || '-'
    || public.be_gl_code(p_merchant_code, 'GEN')
    || '-'
    || lpad(greatest(coalesce(p_sequence, 1), 1)::text, 3, '0');
$function$
;

CREATE OR REPLACE FUNCTION public.be_gl_num(p_value text, p_default numeric DEFAULT 0)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v_result numeric;
begin
  begin
    v_result := nullif(regexp_replace(coalesce(p_value, ''), '[^0-9.-]', '', 'g'), '')::numeric;
  exception when others then
    v_result := p_default;
  end;
  return coalesce(v_result, p_default);
end;
$function$
;

