CREATE OR REPLACE FUNCTION public.be_go_live_archive_mock_operational_data()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_table text;
  v_schema text;
  v_name text;
  v_exists boolean;
  v_has_status boolean;
  v_has_assignment_status boolean;
  v_has_payload boolean;
  v_has_metadata boolean;
  v_has_updated_at boolean;
  v_set text[];
  v_sql text;
  v_updated integer := 0;
  v_total integer := 0;
  v_results jsonb := '[]'::jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication is required to archive non-live operational rows.';
  END IF;

  FOREACH v_table IN ARRAY ARRAY[
    'public.be_portal_pickup_requests',
    'public.be_portal_cargo_events',
    'public.shipments',
    'public.deliveries',
    'public.delivery_waybills',
    'public.be_delivery_jobs',
    'public.be_data_entry_parcels',
    'public.cod_collections',
    'public.cod_settlement_batches',
    'public.be_supervisor_wayplans',
    'public.be_supervisor_job_assignments',
    'public.be_wayplans',
    'public.be_wayplan_items',
    'public.be_finance_events',
    'public.be_employee_wallet_transactions'
  ] LOOP
    v_schema := split_part(v_table, '.', 1);
    v_name := split_part(v_table, '.', 2);

    SELECT EXISTS (
      SELECT 1
      FROM information_schema.tables
      WHERE table_schema = v_schema
        AND table_name = v_name
    ) INTO v_exists;

    IF NOT v_exists THEN
      CONTINUE;
    END IF;

    SELECT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = v_schema AND table_name = v_name AND column_name = 'status') INTO v_has_status;
    SELECT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = v_schema AND table_name = v_name AND column_name = 'assignment_status') INTO v_has_assignment_status;
    SELECT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = v_schema AND table_name = v_name AND column_name = 'payload' AND udt_name = 'jsonb') INTO v_has_payload;
    SELECT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = v_schema AND table_name = v_name AND column_name = 'metadata' AND udt_name = 'jsonb') INTO v_has_metadata;
    SELECT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = v_schema AND table_name = v_name AND column_name = 'updated_at') INTO v_has_updated_at;

    v_set := ARRAY[]::text[];

    -- Fix: Use array_append instead of || concatenation
    IF v_has_status THEN
      v_set := array_append(v_set, 'status = ''archived_test_data''');
    END IF;
    IF v_has_assignment_status THEN
      v_set := array_append(v_set, 'assignment_status = ''archived_test_data''');
    END IF;
    IF v_has_payload THEN
      v_set := array_append(v_set, 'payload = coalesce(payload, ''{}''::jsonb) || jsonb_build_object(''archived_reason'', ''go_live_mock_sample_test_isolation'', ''archived_at'', now())');
    END IF;
    IF v_has_metadata THEN
      v_set := array_append(v_set, 'metadata = coalesce(metadata, ''{}''::jsonb) || jsonb_build_object(''archived_reason'', ''go_live_mock_sample_test_isolation'', ''archived_at'', now())');
    END IF;
    IF v_has_updated_at THEN
      v_set := array_append(v_set, 'updated_at = now()');
    END IF;

    IF array_length(v_set, 1) IS NULL THEN
      CONTINUE;
    END IF;

    v_sql := format(
      'update %I.%I t set %s where coalesce(to_jsonb(t)->>''status'', '''') <> ''archived_test_data'' and public.be_go_live_is_non_live_payload(to_jsonb(t))',
      v_schema,
      v_name,
      array_to_string(v_set, ', ')
    );

    BEGIN
      EXECUTE v_sql;
      GET DIAGNOSTICS v_updated = row_count;
      v_total := v_total + v_updated;
      v_results := v_results || jsonb_build_array(jsonb_build_object('table', v_table, 'archived_rows', v_updated));
    EXCEPTION WHEN OTHERS THEN
      v_results := v_results || jsonb_build_array(jsonb_build_object('table', v_table, 'error', sqlerrm));
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'master_data_untouched', true,
    'archived_total', v_total,
    'tables', v_results
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_go_live_backfill_pickup_aliases_same_row()
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
  r record;
  before_count integer := 0;
  after_count integer := 0;
  q text;
begin
  select count(*) into before_count from public.be_pickup_id_aliases;

  for r in
    select c1.table_schema, c1.table_name
    from information_schema.columns c1
    join information_schema.columns c2 on c1.table_schema = c2.table_schema and c1.table_name = c2.table_name
    where c1.table_schema = 'public'
      and lower(c1.column_name) = 'pickup_id'
      and lower(c2.column_name) in ('data_entry_pickup_id','canonical_pickup_id','operational_pickup_id')
    group by c1.table_schema, c1.table_name
  loop
    q := format($f$
      insert into public.be_pickup_id_aliases(legacy_pickup_id, canonical_pickup_id, source, reason)
      select distinct
        (pickup_id)::text,
        coalesce(
          nullif((to_jsonb(t)->>'canonical_pickup_id'), ''),
          nullif((to_jsonb(t)->>'data_entry_pickup_id'), ''),
          nullif((to_jsonb(t)->>'operational_pickup_id'), '')
        )::text,
        'same_row_backfill',
        'Mapped because legacy and canonical IDs existed in the same row'
      from %I.%I t
      where (pickup_id)::text ~ '^D[0-9]{4}-[A-Za-z0-9]+-[0-9]+$'
        and coalesce(
          nullif((to_jsonb(t)->>'canonical_pickup_id'), ''),
          nullif((to_jsonb(t)->>'data_entry_pickup_id'), ''),
          nullif((to_jsonb(t)->>'operational_pickup_id'), '')
        ) ~ '^P[0-9]{4}-[A-Za-z0-9]+'
      on conflict (legacy_pickup_id) do update set
        canonical_pickup_id = excluded.canonical_pickup_id,
        source = excluded.source,
        reason = excluded.reason
    $f$, r.table_schema, r.table_name);
    execute q;
  end loop;

  select count(*) into after_count from public.be_pickup_id_aliases;
  return jsonb_build_object('ok', true, 'inserted_or_updated', after_count - before_count, 'total_aliases', after_count);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_go_live_finance_backfill()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_count integer;
begin
  update public.delivery_waybills
  set updated_at = now()
  where delivery_way_id is not null;

  get diagnostics v_count = row_count;

  return jsonb_build_object(
    'ok', true,
    'delivery_waybills_touched', v_count,
    'cod_ledger_rows', (select count(*) from public.be_cod_ledger),
    'settlement_rows', (select count(*) from public.be_financial_settlements),
    'invoice_rows', (select count(*) from public.be_customer_invoices)
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_go_live_is_non_live_payload(p_row jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$
  with fields as (
    select
      lower(coalesce(p_row::text, '')) as full_text,
      lower(concat_ws(' ',
        p_row->>'source',
        p_row->>'source_portal',
        p_row->>'sync_source',
        p_row->>'data_source',
        p_row->>'record_source',
        p_row->>'origin',
        p_row->>'environment',
        p_row->>'dataset',
        p_row->>'seed_source',
        p_row->>'status',
        p_row->>'record_status',
        p_row->>'validation_status',
        p_row->>'assignment_status'
      )) as source_text,
      lower(concat_ws(' ',
        p_row->>'id',
        p_row->>'pickup_id',
        p_row->>'pickup_way_id',
        p_row->>'request_id',
        p_row->>'delivery_id',
        p_row->>'deliver_way_id',
        p_row->>'delivery_way_id',
        p_row->>'waybill_id',
        p_row->>'waybill_no',
        p_row->>'tracking_no',
        p_row->>'invoice_no',
        p_row->>'settlement_id',
        p_row->>'batch_id'
      )) as id_text
  )
  select
    full_text ~ '(archived_test_data|archived_uploaded_sample_removed_for_production|sample_operational|mock_operational|demo_operational|test_operational|placeholder\.co)'
    or source_text ~ '\m(sample|mock|demo|dummy|fake|faker|test|training|sandbox)\M'
    or id_text ~ '(^|\s)(sample|mock|demo|dummy|test|sandbox)[-_:/]'
  from fields;
$function$
;

CREATE OR REPLACE FUNCTION public.be_go_live_isolation_report()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_table text;
  v_schema text;
  v_name text;
  v_exists boolean;
  v_count integer;
  v_examples jsonb;
  v_tables jsonb := '[]'::jsonb;
  v_invalid_pickups jsonb := '[]'::jsonb;
  v_invalid_waybills jsonb := '[]'::jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication is required to inspect go-live isolation.';
  END IF;

  FOREACH v_table IN ARRAY ARRAY[
    'public.be_portal_pickup_requests',
    'public.be_portal_cargo_events',
    'public.shipments',
    'public.deliveries',
    'public.delivery_waybills',
    'public.be_delivery_jobs',
    'public.be_data_entry_parcels',
    'public.cod_collections',
    'public.cod_settlement_batches',
    'public.be_supervisor_wayplans',
    'public.be_supervisor_job_assignments',
    'public.be_wayplans',
    'public.be_wayplan_items',
    'public.be_finance_events',
    'public.be_employee_wallet_transactions'
  ] LOOP
    v_schema := split_part(v_table, '.', 1);
    v_name := split_part(v_table, '.', 2);

    SELECT EXISTS (
      SELECT 1
      FROM information_schema.tables
      WHERE table_schema = v_schema
        AND table_name = v_name
    ) INTO v_exists;

    IF NOT v_exists THEN
      CONTINUE;
    END IF;

    EXECUTE format(
      'select count(*) from %I.%I t where coalesce(to_jsonb(t)->>''status'', to_jsonb(t)->>''event_status'', '''') <> ''archived_test_data'' and public.be_go_live_is_non_live_payload(to_jsonb(t))',
      v_schema,
      v_name
    ) INTO v_count;

    EXECUTE format(
      'select coalesce(jsonb_agg(row_payload), ''[]''::jsonb)
       from (
         select to_jsonb(t) - ''payload'' - ''metadata'' - ''source_payload'' as row_payload
         from %I.%I t
         where coalesce(to_jsonb(t)->>''status'', to_jsonb(t)->>''event_status'', '''') <> ''archived_test_data''
           and public.be_go_live_is_non_live_payload(to_jsonb(t))
         limit 5
       ) examples',
      v_schema,
      v_name
    ) INTO v_examples;

    v_tables := v_tables || jsonb_build_array(jsonb_build_object(
      'table', v_table,
      'non_live_rows', coalesce(v_count, 0),
      'examples', coalesce(v_examples, '[]'::jsonb)
    ));
  END LOOP;

  IF to_regclass('public.be_portal_pickup_requests') IS NOT NULL THEN
    SELECT coalesce(jsonb_agg(jsonb_build_object(
      'pickup_id', pickup_id,
      'status', status,
      'operation_status', operation_status,
      'merchant_code', merchant_code,
      'created_at', created_at
    )), '[]'::jsonb)
    INTO v_invalid_pickups
    FROM public.be_portal_pickup_requests
    WHERE coalesce(status, '') <> 'archived_test_data'
      AND (
        pickup_id IS NULL
        OR pickup_id !~ '^P[0-9]{4}-[A-Z][A-Z0-9]{1,4}-[0-9]{3}$'
        OR public.be_go_live_is_non_live_payload(to_jsonb(be_portal_pickup_requests))
      );
  END IF;

  IF to_regclass('public.be_portal_cargo_events') IS NOT NULL THEN
    SELECT coalesce(jsonb_agg(jsonb_build_object(
      'pickup_id', pickup_id,
      'delivery_way_id', delivery_way_id,
      'status', event_status,
      'created_at', created_at
    )), '[]'::jsonb)
    INTO v_invalid_waybills
    FROM public.be_portal_cargo_events
    WHERE coalesce(event_status, '') <> 'archived_test_data'
      AND event_type = 'data_entry_waybill'
      AND (
        coalesce(delivery_way_id, '') !~ '^D[0-9]{4}-[A-Z][A-Z0-9]{1,4}-[0-9]{3}$'
        OR public.be_go_live_is_non_live_payload(to_jsonb(be_portal_cargo_events))
      );
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'master_data_untouched', true,
    'operational_tables', v_tables,
    'active_invalid_pickup_ids', v_invalid_pickups,
    'active_invalid_waybills', v_invalid_waybills
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_go_live_monitoring_snapshot()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
select jsonb_build_object(
  'ok', true,
  'source', 'be_go_live_monitoring_snapshot',
  'checked_at', now(),

  'go_live_status', (
    select jsonb_build_object(
      'latest_status', test_status,
      'test_name', test_name,
      'tested_at', tested_at,
      'fail_count', fail_count,
      'warn_count', warn_count
    )
    from public.be_uat_test_evidence
    where test_name in (
      'SPEC-12 Final Go-Live Sign-Off',
      'Full Pickup to Finance Closure E2E Wireup',
      'Rider App Parcel-Level Verification UI'
    )
    order by tested_at desc
    limit 1
  ),

  'uat_summary', (
    select jsonb_build_object(
      'total_tests', count(*),
      'passed_tests', count(*) filter (
        where test_status in ('PASSED', 'GO_LIVE_READY')
      ),
      'failed_tests', count(*) filter (
        where coalesce(fail_count, 0) > 0
      ),
      'total_pass_count', coalesce(sum(pass_count), 0),
      'total_warn_count', coalesce(sum(warn_count), 0),
      'total_fail_count', coalesce(sum(fail_count), 0)
    )
    from public.be_uat_test_evidence
    where tested_at >= now() - interval '7 days'
  ),

  'pickup_health', (
    select jsonb_build_object(
      'total_pickups', count(*),
      'waiting_assignment', count(*) filter (
        where upper(coalesce(status, pickup_status, '')) like '%WAITING%'
      ),
      'rider_assigned', count(*) filter (
        where upper(coalesce(pickup_status, '')) = 'RIDER_ASSIGNED'
      ),
      'pickup_verified', count(*) filter (
        where upper(coalesce(pickup_status, '')) = 'PICKUP_VERIFIED'
      ),
      'delivered', count(*) filter (
        where upper(coalesce(pickup_status, status, '')) = 'DELIVERED'
      ),
      'cod_settled', count(*) filter (
        where upper(coalesce(finance_status, '')) = 'COD_SETTLED'
      )
    )
    from public.be_portal_pickup_requests
  ),

  'parcel_health', (
    select jsonb_build_object(
      'total_parcels', count(*),
      'registered', count(*) filter (where status = 'registered'),
      'at_branch', count(*) filter (where status = 'at_branch'),
      'in_transit', count(*) filter (where status = 'in_transit'),
      'out_for_delivery', count(*) filter (where status = 'out_for_delivery'),
      'delivered', count(*) filter (where status = 'delivered'),
      'failed', count(*) filter (where status = 'failed')
    )
    from public.parcels
  ),

  'rider_app_health', (
    select jsonb_build_object(
      'notifications_unread', count(*) filter (
        where target_role = 'rider'
          and coalesce(is_read, false) = false
      ),
      'pickup_assignments', count(*) filter (
        where notification_type = 'PICKUP_ASSIGNMENT'
      ),
      'dispatch_wayplans', count(*) filter (
        where notification_type = 'DISPATCH_WAYPLAN_ASSIGNED'
      )
    )
    from public.be_app_notifications
  ),

  'finance_health', (
    select jsonb_build_object(
      'pending_cod_notifications', count(*) filter (
        where target_role = 'finance'
          and notification_type = 'COD_SETTLEMENT_REQUIRED'
          and coalesce(is_read, false) = false
      ),
      'closed_cod_notifications', count(*) filter (
        where target_role = 'finance'
          and notification_type = 'COD_SETTLEMENT_REQUIRED'
          and coalesce(is_read, false) = true
      )
    )
    from public.be_app_notifications
  )
);
$function$
;

CREATE OR REPLACE FUNCTION public.be_go_live_pickup_id_audit()
 RETURNS TABLE(table_name text, column_name text, legacy_d_count bigint, p_count bigint, sample_legacy_ids jsonb, sample_p_ids jsonb)
 LANGUAGE plpgsql
AS $function$
declare
  r record;
  q text;
begin
  for r in
    select table_schema, table_name, column_name
    from information_schema.columns
    where table_schema = 'public'
      and lower(column_name) in (
        'pickup_id','pickupid','pickup_no','pickupno','pickup_request_id',
        'pickup_request_code','cs_pickup_id','data_entry_pickup_id',
        'canonical_pickup_id','operational_pickup_id'
      )
    order by table_name, column_name
  loop
    q := format($f$
      select %L::text, %L::text,
        count(*) filter (where (%I)::text ~ '^D[0-9]{4}-[A-Za-z0-9]+-[0-9]+$')::bigint,
        count(*) filter (where (%I)::text ~ '^P[0-9]{4}-[A-Za-z0-9]+')::bigint,
        coalesce(jsonb_agg(distinct (%I)::text) filter (where (%I)::text ~ '^D[0-9]{4}-[A-Za-z0-9]+-[0-9]+$'), '[]'::jsonb),
        coalesce(jsonb_agg(distinct (%I)::text) filter (where (%I)::text ~ '^P[0-9]{4}-[A-Za-z0-9]+'), '[]'::jsonb)
      from %I.%I
      where (%I)::text is not null
    $f$, r.table_name, r.column_name, r.column_name, r.column_name, r.column_name, r.column_name, r.column_name, r.column_name, r.table_schema, r.table_name, r.column_name);
    return query execute q;
  end loop;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_go_live_purge_mock_data()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_deleted jsonb := '[]'::jsonb;
  v_count integer;
begin
  delete from public.delivery_waybills
  where lower(coalesce(raw_row ->> 'source', '')) in ('mock', 'sample', 'demo')
     or upper(coalesce(delivery_way_id, '')) like 'MOCK%'
     or upper(coalesce(delivery_way_id, '')) like 'SAMPLE%';

  get diagnostics v_count = row_count;
  v_deleted := v_deleted || jsonb_build_array(jsonb_build_object('table', 'delivery_waybills', 'rows', v_count));

  delete from public.be_cod_ledger
  where lower(coalesce(payload ->> 'source', '')) in ('mock', 'sample', 'demo')
     or upper(coalesce(delivery_way_id, '')) like 'MOCK%'
     or upper(coalesce(delivery_way_id, '')) like 'SAMPLE%';

  get diagnostics v_count = row_count;
  v_deleted := v_deleted || jsonb_build_array(jsonb_build_object('table', 'be_cod_ledger', 'rows', v_count));

  delete from public.be_financial_settlements
  where lower(coalesce(payload ->> 'source', '')) in ('mock', 'sample', 'demo')
     or upper(coalesce(delivery_way_id, '')) like 'MOCK%'
     or upper(coalesce(delivery_way_id, '')) like 'SAMPLE%';

  get diagnostics v_count = row_count;
  v_deleted := v_deleted || jsonb_build_array(jsonb_build_object('table', 'be_financial_settlements', 'rows', v_count));

  return jsonb_build_object('ok', true, 'deleted', v_deleted);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_go_live_readiness_snapshot()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with checks as (
    select
      'delivery_waybills_schema'::text as check_code,
      exists(
        select 1
        from information_schema.columns
        where table_schema = 'public'
          and table_name = 'delivery_waybills'
          and column_name = 'deli_fee_os'
      )
      and exists(
        select 1
        from information_schema.columns
        where table_schema = 'public'
          and table_name = 'delivery_waybills'
          and column_name = 'finance_status'
      ) as passed,
      'delivery_waybills has Excel and Finance columns'::text as message
    union all
    select
      'finance_tables',
      to_regclass('public.be_cod_ledger') is not null
        and to_regclass('public.be_financial_settlements') is not null
        and to_regclass('public.be_finance_journal_entries') is not null,
      'COD, settlement and journal tables exist'
    union all
    select
      'finance_rpc',
      to_regprocedure('public.be_finance_snapshot(text,integer)') is not null
        and to_regprocedure('public.be_finance_close_settlement(jsonb)') is not null,
      'Finance RPCs exist'
    union all
    select
      'data_entry_to_finance_sync',
      (select count(*) from public.delivery_waybills where delivery_way_id is not null) = 0
        or (select count(*) from public.be_financial_settlements) >=
           (select count(*) from public.delivery_waybills where delivery_way_id is not null),
      'Every delivery waybill should have a settlement row'
  )
  select jsonb_build_object(
    'checks', coalesce(jsonb_agg(row_to_json(checks)::jsonb), '[]'::jsonb),
    'passed', bool_and(passed),
    'kpis', public.be_finance_snapshot(null, 50) -> 'kpis',
    'synced_at', now()
  )
  from checks;
$function$
;

CREATE OR REPLACE FUNCTION public.be_go_live_system_readiness()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
AS $function$
  with checks as (
    select 'pickup_single_backend' check_code, to_regclass('public.be_portal_pickup_requests') is not null passed, 'Unified pickup request table exists' message
    union all select 'canonical_pickup_id', to_regprocedure('public.be_submit_pickup_request(jsonb)') is not null, 'Submit pickup RPC creates canonical Pickup ID'
    union all select 'notifications', to_regclass('public.be_app_notifications') is not null, 'Role notifications table exists'
    union all select 'cargo_events', to_regclass('public.be_portal_cargo_events') is not null, 'Cargo event tracking table exists'
    union all select 'workforce_accounts', to_regclass('public.be_mobile_workforce_accounts') is not null, 'Rider/Driver/Helper workforce accounts table exists'
    union all select 'assignment_rpc', to_regprocedure('public.be_supervisor_assign_job(jsonb)') is not null, 'Supervisor assignment RPC exists'
    union all select 'mobile_snapshot', to_regprocedure('public.be_mobile_go_live_snapshot(text,text,integer)') is not null, 'Mobile app snapshot RPC exists'
    union all select 'mobile_status_update', to_regprocedure('public.be_mobile_update_job_status(jsonb)') is not null, 'Mobile status update RPC exists'
    union all select 'role_snapshot', to_regprocedure('public.be_role_portal_snapshot(text,text,text,integer)') is not null, 'Role portal snapshot RPC exists'
  )
  select jsonb_build_object(
    'passed', bool_and(passed),
    'checks', coalesce(jsonb_agg(row_to_json(checks)::jsonb), '[]'::jsonb),
    'kpis', jsonb_build_object(
      'pickups', (select count(*) from public.be_portal_pickup_requests),
      'assignments', (select count(*) from public.be_supervisor_job_assignments),
      'cargo_events', (select count(*) from public.be_portal_cargo_events),
      'notifications', (select count(*) from public.be_app_notifications),
      'workforce_accounts', (select count(*) from public.be_mobile_workforce_accounts)
    ),
    'synced_at', now()
  )
  from checks;
$function$
;

CREATE OR REPLACE FUNCTION public.be_go_live_wireup_healthcheck()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  out jsonb;
begin
  select jsonb_build_object(
    'master_options', (select count(*) from public.be_master_data_options),
    'merchant_options', (select count(*) from public.be_master_data_options where option_type='merchants' and is_active),
    'route_groups', (select public.be_master_data_combobox('route_group', null, 20)),
    'pickup_aliases', (select count(*) from public.be_pickup_id_aliases),
    'legacy_pickup_audit', (select coalesce(jsonb_agg(to_jsonb(x)), '[]'::jsonb) from public.be_go_live_pickup_id_audit() x)
  ) into out;
  return out;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_governance_approval_center(p_limit integer DEFAULT 200)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_amendments jsonb := '[]'::jsonb;
  v_print_requests jsonb := '[]'::jsonb;
  v_audit jsonb := '[]'::jsonb;
  v_summary jsonb := '{}'::jsonb;
begin
  select coalesce(jsonb_agg(to_jsonb(a) order by a.created_at desc), '[]'::jsonb)
  into v_amendments
  from (
    select *
    from public.be_branch_amendment_requests
    order by created_at desc nulls last
    limit greatest(coalesce(p_limit, 200), 1)
  ) a;

  select coalesce(jsonb_agg(to_jsonb(p) order by p.created_at desc), '[]'::jsonb)
  into v_print_requests
  from (
    select *
    from public.be_document_print_approval_requests
    order by created_at desc nulls last
    limit greatest(coalesce(p_limit, 200), 1)
  ) p;

  select coalesce(jsonb_agg(to_jsonb(g) order by g.created_at desc), '[]'::jsonb)
  into v_audit
  from (
    select *
    from public.be_governance_audit_log
    order by created_at desc nulls last
    limit greatest(coalesce(p_limit, 200), 1)
  ) g;

  select jsonb_build_object(
    'pending_amendments', (
      select count(*)
      from public.be_branch_amendment_requests
      where coalesce(approval_status, 'PENDING') = 'PENDING'
    ),
    'approved_amendments', (
      select count(*)
      from public.be_branch_amendment_requests
      where approval_status = 'APPROVED'
    ),
    'rejected_amendments', (
      select count(*)
      from public.be_branch_amendment_requests
      where approval_status = 'REJECTED'
    ),
    'pending_print_requests', (
      select count(*)
      from public.be_document_print_approval_requests
      where approval_status = 'PENDING'
    ),
    'audit_events', (
      select count(*)
      from public.be_governance_audit_log
    )
  )
  into v_summary;

  return jsonb_build_object(
    'ok', true,
    'source', 'be_governance_approval_center',
    'summary', v_summary,
    'amendments', v_amendments,
    'print_requests', v_print_requests,
    'audit', v_audit
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_governance_approval_center(p_limit integer DEFAULT 200, p_actor_email text DEFAULT NULL::text, p_actor_role text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_ctx jsonb;
  v_amendments jsonb := '[]'::jsonb;
  v_print_requests jsonb := '[]'::jsonb;
  v_audit jsonb := '[]'::jsonb;
  v_summary jsonb := '{}'::jsonb;
begin
  v_ctx := public.be_require_admin(p_actor_email, p_actor_role);

  select coalesce(jsonb_agg(to_jsonb(a) order by a.created_at desc), '[]'::jsonb)
  into v_amendments
  from (
    select *
    from public.be_branch_amendment_requests
    order by created_at desc nulls last
    limit greatest(coalesce(p_limit, 200), 1)
  ) a;

  select coalesce(jsonb_agg(to_jsonb(p) order by p.created_at desc), '[]'::jsonb)
  into v_print_requests
  from (
    select *
    from public.be_document_print_approval_requests
    order by created_at desc nulls last
    limit greatest(coalesce(p_limit, 200), 1)
  ) p;

  select coalesce(jsonb_agg(to_jsonb(g) order by g.created_at desc), '[]'::jsonb)
  into v_audit
  from (
    select *
    from public.be_governance_audit_log
    order by created_at desc nulls last
    limit greatest(coalesce(p_limit, 200), 1)
  ) g;

  select jsonb_build_object(
    'pending_amendments', (
      select count(*) from public.be_branch_amendment_requests
      where coalesce(approval_status, 'PENDING') = 'PENDING'
    ),
    'approved_amendments', (
      select count(*) from public.be_branch_amendment_requests
      where approval_status = 'APPROVED'
    ),
    'rejected_amendments', (
      select count(*) from public.be_branch_amendment_requests
      where approval_status = 'REJECTED'
    ),
    'pending_print_requests', (
      select count(*) from public.be_document_print_approval_requests
      where approval_status = 'PENDING'
    ),
    'audit_events', (
      select count(*) from public.be_governance_audit_log
    )
  )
  into v_summary;

  return jsonb_build_object(
    'ok', true,
    'source', 'be_governance_approval_center',
    'actor', v_ctx,
    'summary', v_summary,
    'amendments', v_amendments,
    'print_requests', v_print_requests,
    'audit', v_audit
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_gps_tracking_health(p_rider_code text DEFAULT 'RID001'::text)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
select jsonb_build_object(
  'ok', true,
  'rider_code', p_rider_code,

