  (
    select jsonb_build_object(
      'rider_id', g.rider_id,
      'rider_name', g.rider_name,
      'pickup_id', g.pickup_id,
      'delivery_way_id', g.delivery_way_id,

      'latitude', g.latitude,
      'longitude', g.longitude,

      'accuracy_meters', g.accuracy_m,

      'gps_status', g.gps_status,

