create or replace view "public"."be_helpers" as  SELECT record_key AS id,
    record_key AS helper_id,
    record_key AS helper_code,
    record_key AS code,
    COALESCE((payload ->> 'helper_name'::text), (payload ->> 'employee_name'::text), (payload ->> 'name'::text), record_key) AS helper_name,
    COALESCE((payload ->> 'helper_name'::text), (payload ->> 'employee_name'::text), (payload ->> 'name'::text), record_key) AS name,
    COALESCE((payload ->> 'helper_name'::text), (payload ->> 'employee_name'::text), (payload ->> 'name'::text), record_key) AS label,
    COALESCE((payload ->> 'helper_name'::text), (payload ->> 'employee_name'::text), (payload ->> 'name'::text), record_key) AS display_name,
    COALESCE((payload ->> 'phone_primary'::text), (payload ->> 'phone'::text)) AS phone,
    'ACTIVE'::text AS status,
    true AS active,
    true AS is_active,
    true AS available,
    true AS is_available,
    payload,
    updated_at
   FROM public.be_master_data_rows
  WHERE ((dataset_key = ANY (ARRAY['helper_master'::text, 'employee_master'::text])) AND (deleted_at IS NULL) AND (lower(COALESCE((payload ->> 'status'::text), status, 'active'::text)) <> 'inactive'::text) AND ((dataset_key = 'helper_master'::text) OR (lower(COALESCE((payload ->> 'role_id'::text), ''::text)) ~~ '%warehouse helper%'::text)));


CREATE OR REPLACE FUNCTION public.be_hr_dashboard()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_rows jsonb;
  v_summary jsonb;
begin
  select coalesce(jsonb_agg(to_jsonb(e) order by e.department nulls last, e.full_name nulls last, e.display_name nulls last), '[]'::jsonb)
  into v_rows
  from public.be_employee_master e
  where coalesce(e.is_active, true) = true;

  select jsonb_build_object(
    'total_employees', count(*),
    'active_employees', count(*) filter (
      where coalesce(is_active, true) = true
        and lower(coalesce(status, 'active')) in ('active', 'approved')
    ),
    'inactive_employees', count(*) filter (
      where coalesce(is_active, true) = false
        or lower(coalesce(status, 'active')) not in ('active', 'approved')
    ),
    'branches', count(distinct branch_code),
    'departments', count(distinct department),
    'riders', count(*) filter (where lower(coalesce(app_role, role_id, workforce_type, '')) like '%rider%'),
    'drivers', count(*) filter (where lower(coalesce(app_role, role_id, workforce_type, '')) like '%driver%'),
    'helpers', count(*) filter (where lower(coalesce(app_role, role_id, workforce_type, '')) like '%helper%'),
    'warehouse', count(*) filter (
      where lower(coalesce(app_role, role_id, department, '')) like '%warehouse%'
    )
  )
  into v_summary
  from public.be_employee_master;

  return jsonb_build_object(
    'ok', true,
    'source', 'be_hr_dashboard',
    'summary', coalesce(v_summary, '{}'::jsonb),
    'rows', coalesce(v_rows, '[]'::jsonb)
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_hr_employee_delete(p_employee_id text, p_actor_email text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_count integer := 0;
begin
  update public.be_employee_master
  set
    is_active = false,
    status = 'inactive',
    metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
      'deleted_by', p_actor_email,
      'deleted_at', now()
    ),
    updated_at = now()
  where employee_id = p_employee_id
     or id::text = p_employee_id
     or email = p_employee_id;

  get diagnostics v_count = row_count;

  return jsonb_build_object(
    'ok', true,
    'deleted_rows', v_count
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_hr_employee_delete_audited(p_employee_id text, p_actor_email text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_before jsonb := '{}'::jsonb;
  v_result jsonb;
begin
  select to_jsonb(e)
  into v_before
  from public.be_employee_master e
  where e.employee_id = p_employee_id
     or e.email = p_employee_id
     or e.id::text = p_employee_id
  limit 1;

  v_result := public.be_hr_employee_delete(p_employee_id, p_actor_email);

  perform public.be_write_governance_audit(
    'ADMIN_HR',
    'EMPLOYEE_DELETED',
    'be_employee_master',
    p_employee_id,
    p_actor_email,
    coalesce(v_before, '{}'::jsonb),
    v_result,
    jsonb_build_object(
      'source', 'be_hr_employee_delete_audited'
    )
  );

  return v_result;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_hr_employee_save(p_record jsonb, p_actor_email text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id uuid;
  v_email text := nullif(coalesce(p_record->>'email', p_record->>'account'), '');
  v_employee_id text := nullif(coalesce(p_record->>'employee_id', p_record->>'employee_code'), '');
begin
  if v_email is null and v_employee_id is null then
    raise exception 'employee_id or email is required';
  end if;

  select id
  into v_id
  from public.be_employee_master
  where (
      v_email is not null
      and email is not null
      and lower(email) = lower(v_email)
    )
    or (
      v_employee_id is not null
      and employee_id = v_employee_id
    )
  order by updated_at desc nulls last
  limit 1;

  if v_id is null then
    insert into public.be_employee_master (
      id,
      employee_id,
      employee_code,
      account,
      email,
      display_name,
      full_name,
      name,
      designation,
      role_label,
      app_role,
      role_id,
      department,
      branch_code,
      workforce_type,
      phone_e164,
      status,
      is_active,
      force_password_change,
      metadata,
      created_at,
      updated_at
    )
    values (
      gen_random_uuid(),
      coalesce(v_employee_id, 'EMP-' || to_char(now(), 'YYYYMMDDHH24MISSMS')),
      nullif(p_record->>'employee_code', ''),
      nullif(p_record->>'account', ''),
      v_email,
      coalesce(nullif(p_record->>'display_name', ''), nullif(p_record->>'full_name', ''), nullif(p_record->>'name', '')),
      coalesce(nullif(p_record->>'full_name', ''), nullif(p_record->>'display_name', ''), nullif(p_record->>'name', '')),
      coalesce(nullif(p_record->>'name', ''), nullif(p_record->>'full_name', ''), nullif(p_record->>'display_name', '')),
      nullif(p_record->>'designation', ''),
      nullif(p_record->>'role_label', ''),
      nullif(p_record->>'app_role', ''),
      nullif(p_record->>'role_id', ''),
      nullif(p_record->>'department', ''),
      coalesce(nullif(p_record->>'branch_code', ''), 'YGN'),
      nullif(p_record->>'workforce_type', ''),
      nullif(coalesce(p_record->>'phone_e164', p_record->>'phone'), ''),
      coalesce(nullif(p_record->>'status', ''), 'active'),
      coalesce((p_record->>'is_active')::boolean, true),
      coalesce((p_record->>'force_password_change')::boolean, false),
      p_record || jsonb_build_object('updated_by', p_actor_email),
      now(),
      now()
    )
    returning id into v_id;
  else
    update public.be_employee_master
    set
      employee_id = coalesce(v_employee_id, employee_id),
      employee_code = coalesce(nullif(p_record->>'employee_code', ''), employee_code),
      account = coalesce(nullif(p_record->>'account', ''), account),
      email = coalesce(v_email, email),
      display_name = coalesce(nullif(p_record->>'display_name', ''), nullif(p_record->>'full_name', ''), display_name),
      full_name = coalesce(nullif(p_record->>'full_name', ''), nullif(p_record->>'display_name', ''), full_name),
      name = coalesce(nullif(p_record->>'name', ''), nullif(p_record->>'full_name', ''), name),
      designation = coalesce(nullif(p_record->>'designation', ''), designation),
      role_label = coalesce(nullif(p_record->>'role_label', ''), role_label),
      app_role = coalesce(nullif(p_record->>'app_role', ''), app_role),
      role_id = coalesce(nullif(p_record->>'role_id', ''), role_id),
      department = coalesce(nullif(p_record->>'department', ''), department),
      branch_code = coalesce(nullif(p_record->>'branch_code', ''), branch_code, 'YGN'),
      workforce_type = coalesce(nullif(p_record->>'workforce_type', ''), workforce_type),
      phone_e164 = coalesce(nullif(coalesce(p_record->>'phone_e164', p_record->>'phone'), ''), phone_e164),
      status = coalesce(nullif(p_record->>'status', ''), status, 'active'),
      is_active = coalesce((p_record->>'is_active')::boolean, is_active, true),
      force_password_change = coalesce((p_record->>'force_password_change')::boolean, force_password_change, false),
      metadata = coalesce(metadata, '{}'::jsonb) || p_record || jsonb_build_object('updated_by', p_actor_email),
      updated_at = now()
    where id = v_id;
  end if;

  return jsonb_build_object(
    'ok', true,
    'id', v_id,
    'employee_id', coalesce(v_employee_id, p_record->>'employee_id'),
    'email', v_email
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_hr_employee_save_audited(p_record jsonb, p_actor_email text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_result jsonb;
  v_employee_id text;
  v_email text;
  v_before jsonb := '{}'::jsonb;
begin
  v_employee_id := nullif(coalesce(p_record->>'employee_id', p_record->>'employee_code'), '');
  v_email := nullif(coalesce(p_record->>'email', p_record->>'account'), '');

  select to_jsonb(e)
  into v_before
  from public.be_employee_master e
  where (v_employee_id is not null and e.employee_id = v_employee_id)
     or (v_email is not null and lower(e.email) = lower(v_email))
  order by e.updated_at desc nulls last
  limit 1;

  v_result := public.be_hr_employee_save(p_record, p_actor_email);

  perform public.be_write_governance_audit(
    'ADMIN_HR',
    case when v_before is null then 'EMPLOYEE_CREATED' else 'EMPLOYEE_UPDATED' end,
    'be_employee_master',
    coalesce(v_result->>'employee_id', v_employee_id, v_email),
    p_actor_email,
    coalesce(v_before, '{}'::jsonb),
    p_record || v_result,
    jsonb_build_object(
      'email', v_email,
      'source', 'be_hr_employee_save_audited'
    )
  );

  return v_result;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_invoice_approve(p_pickup_id text, p_approved boolean, p_notes text DEFAULT ''::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE v_role TEXT := public.be_current_user_role();
BEGIN
  IF v_role NOT IN ('admin','finance','accountant','operation_manager') THEN RAISE EXCEPTION 'Access denied'; END IF;
  UPDATE public.be_portal_pickup_requests SET invoice_approved=p_approved, invoice_approved_at=CASE WHEN p_approved THEN NOW() ELSE NULL END, invoice_notes=p_notes, updated_at=NOW() WHERE pickup_id=p_pickup_id;
  INSERT INTO public.be_portal_cargo_events(pickup_id,event_type,description,actor_role,created_at) VALUES(p_pickup_id,CASE WHEN p_approved THEN 'INVOICE_APPROVED' ELSE 'INVOICE_REJECTED' END, COALESCE(p_notes,''), v_role, NOW());
  RETURN json_build_object('success',true,'pickup_id',p_pickup_id,'approved',p_approved);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_invoice_list(p_status text DEFAULT NULL::text, p_merchant_code text DEFAULT NULL::text, p_limit integer DEFAULT 50)
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
DECLARE v_role TEXT := public.be_current_user_role();
BEGIN
  IF v_role NOT IN ('admin','finance','accountant','auditor','operation_manager') THEN RAISE EXCEPTION 'Access denied'; END IF;
  RETURN (SELECT COALESCE(json_agg(row_to_json(t)),'[]'::json) FROM (
    SELECT p.pickup_id, p.invoice_no, p.merchant_name, p.merchant_code, p.recipient_name, p.delivery_fee, p.cod_amount, p.payment_method, p.status, p.invoice_approved, p.invoice_approved_at, p.created_at, p.service_tier, p.weight_kg
    FROM public.be_portal_pickup_requests p
    WHERE (p_status IS NULL OR p.status=p_status) AND (p_merchant_code IS NULL OR p.merchant_code=p_merchant_code)
    ORDER BY p.created_at DESC LIMIT p_limit
  ) t);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_invoice_print_action(p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_action text := upper(coalesce(p_payload->>'action',''));
  v_invoice_ids text[] := array(select jsonb_array_elements_text(coalesce(p_payload->'invoice_ids','[]'::jsonb)));
  v_invoice_id text := coalesce(p_payload->>'invoice_id','');
  v_request_no text := coalesce(p_payload->>'request_no','');
  v_actor text := coalesce(p_payload->>'actor','system');
  v_reason text := coalesce(p_payload->>'reason','');
begin
  if v_action = 'MARK_PRINTED' then
    update public.be_invoice_print_records
    set is_printed = true,
        printed_at = now(),
        printed_by = v_actor,
        print_count = coalesce(print_count, 0) + 1,
        updated_at = now()
    where invoice_id = any(v_invoice_ids);

    return jsonb_build_object('ok', true, 'action', v_action, 'updated', array_length(v_invoice_ids, 1));
  end if;

  if v_action = 'REQUEST_REPRINT' then
    insert into public.be_invoice_reprint_requests(invoice_id, reason, requester, status)
    values (v_invoice_id, v_reason, v_actor, 'PENDING');

    return jsonb_build_object('ok', true, 'action', v_action);
  end if;

  if v_action = 'APPROVE_REPRINT' then
    update public.be_invoice_reprint_requests
    set status = 'APPROVED',
        approved_by = v_actor,
        approved_at = now()
    where request_no = v_request_no;

    update public.be_invoice_print_records r
    set is_printed = false,
        updated_at = now()
    from public.be_invoice_reprint_requests q
    where q.request_no = v_request_no
      and q.invoice_id = r.invoice_id;

    return jsonb_build_object('ok', true, 'action', v_action);
  end if;

  if v_action = 'REJECT_REPRINT' then
    update public.be_invoice_reprint_requests
    set status = 'REJECTED',
        rejected_by = v_actor,
        rejected_at = now()
    where request_no = v_request_no;

    return jsonb_build_object('ok', true, 'action', v_action);
  end if;

  return jsonb_build_object('ok', false, 'error', 'Unknown action');
end;
$function$
;

