CREATE OR REPLACE FUNCTION public.be_json_text(p_data jsonb, p_keys text[], p_fallback text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  k text;
  v text;
begin
  foreach k in array p_keys loop
    v := nullif(p_data->>k, '');
    if v is not null then
      return v;
    end if;
  end loop;

  return p_fallback;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_json_try_int(p_value text)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
begin
  if nullif(trim(coalesce(p_value, '')), '') is null then
    return null;
  end if;

  return round((trim(p_value))::numeric)::integer;
exception when others then
  return null;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_json_try_numeric(p_value text)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
begin
  if nullif(trim(coalesce(p_value, '')), '') is null then
    return null;
  end if;

  return (trim(p_value))::numeric;
exception when others then
  return null;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_jsonb_num(p_json jsonb, p_keys text[], p_default numeric DEFAULT 0)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  k text;
  v text;
begin
  foreach k in array p_keys loop
    v := nullif(trim(coalesce(p_json ->> k, '')), '');
    if v is not null and v ~ '^-?[0-9]+(\.[0-9]+)?$' then
      return v::numeric;
    end if;
  end loop;
  return p_default;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_jsonb_text(p_json jsonb, p_keys text[], p_default text DEFAULT ''::text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  k text;
  v text;
begin
  foreach k in array p_keys loop
    v := nullif(trim(coalesce(p_json ->> k, '')), '');
    if v is not null then
      return v;
    end if;
  end loop;
  return p_default;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_known_merchant_code(p_code text, p_name text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_candidate text;
  v_code text;
begin
  v_candidate := upper(regexp_replace(coalesce(p_code, ''), '[^A-Za-z0-9]', '', 'g'));
  if v_candidate ~ '^[A-Z][A-Z0-9]{1,4}$' and v_candidate !~ '^[0-9]+$' then
    return left(v_candidate, 3);
  end if;

  if to_regclass('public.merchant_master') is not null then
    execute $q$
      with rows as (select to_jsonb(m) j from public.merchant_master m)
      select upper(coalesce(j->>'merchant_code', j->>'merchant_id', j->>'record_key'))
      from rows
      where lower(coalesce(j->>'merchant_name', j->>'display_name', j->>'name', '')) = lower(coalesce($1, ''))
         or lower(coalesce(j->>'merchant_code', j->>'merchant_id', j->>'record_key', '')) = lower(coalesce($2, ''))
      limit 1
    $q$ into v_code using p_name, p_code;

    if v_code ~ '^[A-Z][A-Z0-9]{1,4}$' and v_code !~ '^[0-9]+$' then
      return left(v_code, 3);
    end if;
  end if;

  select a.code into v_code
  from (
    values
      ('ALN','Alnoor'), ('APA','APAC'), ('APS','Aung Pyae Sone'), ('BBG','Baby Genius'),
      ('BBK','Baby Kyaw'), ('BBR','Best Buy in Rangoon'), ('BBT','BabyTop'), ('CUY','Curvy'),
      ('DDC','DDC BC'), ('DSD','Daw Sanda'), ('ETE','Ei Tone'), ('HAM','HAIM'), ('HMS','လှမေတ္တာရှင်'),
      ('JLS','July Sis'), ('KKK','ကိုကျော် အထည်'), ('LOS','Lady OS'), ('MBO','MaBel OS'),
      ('MDY','မန္တလေး ရုံးခွဲ'), ('MEL','Mee Lay'), ('NDN','NDN'), ('NFS','နွယ် Fashion'),
      ('NFT','Nfinity'), ('NHT','နန်းထိုက်တန်'), ('NPT','နေပြည်တော် ရုံးခွဲ'), ('PLE','Pleasure'),
      ('POC','PO Clothing'), ('PPL','Poe Poe Lay'), ('PRE','PREMIER'), ('PSO','Phyu Sin OS'),
      ('PTB','ပီတိစာပေ'), ('PTP','ပန်းသရဖီ'), ('PYT','ပုရစ်'), ('SEN','ရွှေအိမ့်'),
      ('SHS','Shwe Sin'), ('SMH','ရွှေမဟာ'), ('SSF','Su Su Fashion World'), ('STZ','ဆောင်းသဇင်'),
      ('SYE','Shwe Yee'), ('TGK','သင်္ဃန်းကျွန်း ရုံးခွဲ'), ('UQD','Unique/Diva')
  ) as a(code, name)
  where lower(a.code) = lower(coalesce(p_code, ''))
     or lower(a.name) = lower(coalesce(p_name, ''))
  limit 1;

  if v_code is null then
    raise exception 'Valid merchant code not found for merchant "%". Update merchant_master merchant_code.', coalesce(p_name, p_code);
  end if;

  return v_code;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_label_queue(p_status text DEFAULT NULL::text, p_merchant_code text DEFAULT NULL::text, p_limit integer DEFAULT 50)
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
DECLARE v_role TEXT := public.be_current_user_role();
BEGIN
  IF v_role NOT IN ('admin','operation_manager','cs','data_entry','finance','supervisor') THEN RAISE EXCEPTION 'Access denied'; END IF;
  RETURN (SELECT COALESCE(json_agg(row_to_json(t)),'[]'::json) FROM (
    SELECT pickup_id, deliver_id, waybill_no, invoice_no, merchant_name, merchant_code, recipient_name, recipient_phone, delivery_address, delivery_township, service_tier, weight_kg, delivery_fee, payment_method, cod_amount, status, waybill_printed_at, created_at
    FROM public.be_portal_pickup_requests
    WHERE (p_status IS NULL OR status=p_status) AND (p_merchant_code IS NULL OR merchant_code=p_merchant_code)
    ORDER BY created_at DESC LIMIT p_limit
  ) t);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_logistics_apply_workflow_event_strict(p_pickup_id text, p_new_status text, p_exception_code text DEFAULT NULL::text, p_remarks text DEFAULT NULL::text, p_user_role text DEFAULT 'System'::text, p_photo_url text DEFAULT NULL::text, p_lat numeric DEFAULT NULL::numeric, p_lng numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_current_status TEXT;
    v_event_id UUID;
BEGIN
    -- 1. Lock and verify the record exists
    SELECT status INTO v_current_status
    FROM be_portal_pickup_requests
    WHERE pickup_id = p_pickup_id FOR UPDATE;

    IF v_current_status IS NULL THEN
        RAISE EXCEPTION 'Pickup ID % not found', p_pickup_id;
    END IF;

    -- 2. Update the master request table to the new workflow state
    UPDATE be_portal_pickup_requests
    SET
        status = p_new_status,
        updated_at = NOW()
    WHERE pickup_id = p_pickup_id;

    -- 3. Insert the immutable cargo event / audit log
    INSERT INTO be_portal_cargo_events (
        pickup_id,
        event_status,
        exception_reason,
        remarks,
        updated_by_role,
        photo_url,
        gps_lat,
        gps_lng,
        event_timestamp
    ) VALUES (
        p_pickup_id,
        p_new_status,
        p_exception_code,
        p_remarks,
        p_user_role,
        p_photo_url,
        p_lat,
        p_lng,
        NOW()
    ) RETURNING id INTO v_event_id;

    -- 4. Return success payload for frontend toast notifications
    RETURN jsonb_build_object(
        'success', true,
        'pickup_id', p_pickup_id,
        'previous_status', v_current_status,
        'new_status', p_new_status,
        'event_id', v_event_id
    );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_logistics_apply_workflow_event_strict(p_pickup_id text, p_process_type text, p_new_status text, p_actor_role text, p_actor_id text, p_notes text DEFAULT NULL::text, p_exception_code text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_current_status text;
BEGIN
    -- Get current status for audit trail
    SELECT status INTO v_current_status
    FROM public.be_portal_pickup_requests
    WHERE pickup_id = p_pickup_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Pickup ID % not found', p_pickup_id;
    END IF;

    -- Update the main operational record
    UPDATE public.be_portal_pickup_requests
    SET
        status = p_new_status,
        pickup_status = p_new_status,
        exception_reason = p_exception_code,
        updated_at = now()
    WHERE pickup_id = p_pickup_id;

    -- Insert the Canonical Cargo Event
    INSERT INTO public.be_portal_cargo_events (
        pickup_id,
        event_type,
        status_code,
        previous_status,
        actor_role,
        actor_id,
        description,
        exception_code,
        created_at
    ) VALUES (
        p_pickup_id,
        p_process_type,
        p_new_status,
        v_current_status,
        p_actor_role,
        p_actor_id,
        COALESCE(p_notes, 'Status updated to ' || p_new_status),
        p_exception_code,
        now()
    );

    RETURN json_build_object('success', true, 'pickup_id', p_pickup_id, 'new_status', p_new_status);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_logistics_assign_rider(p_pickup_id text, p_rider_id text, p_rider_name text, p_driver_id text, p_helper_id text, p_vehicle_type text, p_supervisor_note text, p_actor_role text)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
BEGIN
    -- 1. Update the main pickup request record
    UPDATE be_portal_pickup_requests
    SET
        assigned_rider_id = p_rider_id,
        assigned_rider_name = p_rider_name,
        assigned_driver_id = p_driver_id,
        assigned_helper_id = p_helper_id,
        vehicle_type = p_vehicle_type,
        supervisor_note = p_supervisor_note,
        status = 'PICKUP_ASSIGNED',
        pickup_status = 'Assigned',
        updated_at = NOW()
    WHERE pickup_id = p_pickup_id;

    -- 2. Insert the tracking event log
    INSERT INTO be_portal_cargo_events (
        pickup_id,
        event_type,
        status_code,
        description,
        actor_role,
        created_at
    ) VALUES (
        p_pickup_id,
        'PICKUP_ASSIGNED',
        'PICKUP_ASSIGNED',
        'Supervisor assigned pickup rider ' || p_rider_name || '. Vehicle: ' || COALESCE(p_vehicle_type, 'N/A') || '.',
        p_actor_role,
        NOW()
    );
END;
$function$
;

