CREATE OR REPLACE FUNCTION public.be_make_delivery_way_id(p_pickup_way_id text, p_delivery_sequence integer)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v_mmdd text;
  v_merchant text;
  v_seq integer;
begin
  v_mmdd := substring(p_pickup_way_id from '^P([0-9]{4})-');
  v_merchant := substring(p_pickup_way_id from '^P[0-9]{4}-([A-Z0-9]{3})-');

  if v_mmdd is null or v_merchant is null then
    raise exception 'Invalid pickup_way_id format: %', p_pickup_way_id;
  end if;

  v_seq := greatest(least(coalesce(p_delivery_sequence, 1), 999), 1);

  return 'D' || v_mmdd || '-' || v_merchant || '-' || lpad(v_seq::text, 3, '0');
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_make_deliveryway_id(p_pickup_way_id text, p_delivery_sequence integer)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v_pickup text := public.be_normalize_pickupway_id(p_pickup_way_id);
  v_seq integer := greatest(1, least(999, coalesce(p_delivery_sequence, 1)));
  v_mid text;
begin
  if v_pickup is null then
    return null;
  end if;

  -- Drop leading P and trailing -NNN, then prefix with D and the line sequence.
  v_mid := regexp_replace(v_pickup, '^P(.+)-[0-9]{3}$', '\1');
  return 'D' || v_mid || '-' || lpad(v_seq::text, 3, '0');
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_make_invoice_no(p_delivery_way_id text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v_delivery text := public.be_normalize_deliveryway_id(p_delivery_way_id);
begin
  if v_delivery is null then
    return null;
  end if;
  return 'INV' || substring(v_delivery from 2);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_make_operational_ids(p_pickup_way_id text, p_sequence integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v jsonb;
  v_mmdd text;
  v_merchant text;
  v_seq text;
begin
  if coalesce(p_sequence, 0) <= 0 then
    raise exception 'p_sequence must be greater than 0';
  end if;

  v := public.be_parse_pickup_way_id(p_pickup_way_id);
  v_mmdd := v->>'mmdd';
  v_merchant := v->>'merchant_code';
  v_seq := lpad(p_sequence::text, 3, '0');

  return jsonb_build_object(
    'pickup_way_id', p_pickup_way_id,
    'sequence', p_sequence,
    'delivery_way_id', 'D' || v_mmdd || '-' || v_merchant || '-' || v_seq,
    'waybill_no', 'WB' || v_mmdd || '-' || v_merchant || '-' || v_seq,
    'invoice_no', 'INV' || v_mmdd || '-' || v_merchant || '-' || v_seq,
    'tracking_no', 'TRK' || v_mmdd || '-' || v_merchant || '-' || v_seq
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_make_operational_ids_v2(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  v_merchant text;
  v_count integer;
  v_pickup_way_id text;
  v_rows jsonb := '[]'::jsonb;
  i integer;
  v_delivery_way_id text;
begin
  v_merchant := public.be_clean_merchant_code3(
    coalesce(
      p_payload->>'merchant_code',
      p_payload->>'merchantCode',
      p_payload->>'merchant',
      p_payload->>'merchant_id',
      'GEN'
    )
  );

  v_count := public.be_pickup_total_parcels_from_payload(p_payload);

  v_pickup_way_id := public.be_make_pickup_way_id(
    v_merchant,
    v_count,
    coalesce(nullif(p_payload->>'created_at','')::timestamptz, now())
  );

  for i in 1..v_count loop
    v_delivery_way_id := public.be_make_delivery_way_id(v_pickup_way_id, i);

    v_rows := v_rows || jsonb_build_array(
      jsonb_build_object(
        'pickup_way_id', v_pickup_way_id,
        'delivery_way_id', v_delivery_way_id,
        'waybill_no', replace(v_delivery_way_id, 'D', 'WB'),
        'invoice_no', replace(v_delivery_way_id, 'D', 'INV'),
        'tracking_no', replace(v_delivery_way_id, 'D', 'TRK'),
        'delivery_sequence', i,
        'pickup_parcel_count', v_count
      )
    );
  end loop;

  return jsonb_build_object(
    'ok', true,
    'source', 'be_make_operational_ids_v2',
    'merchant_code', v_merchant,
    'pickup_parcel_count', v_count,
    'pickup_way_id', v_pickup_way_id,
    'deliveries', v_rows
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_make_pickup_way_id(p_merchant_code text, p_pickup_parcel_count integer, p_created_at timestamp with time zone DEFAULT now())
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  v_count integer;
  v_mmdd text;
begin
  v_count := greatest(least(coalesce(p_pickup_parcel_count, 1), 999), 1);

  v_mmdd := to_char(
    coalesce(p_created_at, now()) at time zone 'Asia/Yangon',
    'MMDD'
  );

  return
    'P'
    || v_mmdd
    || '-'
    || public.be_clean_merchant_code3(p_merchant_code)
    || '-'
    || lpad(v_count::text, 3, '0');
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_make_waybill_no(p_delivery_way_id text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v_delivery text := public.be_normalize_deliveryway_id(p_delivery_way_id);
begin
  if v_delivery is null then
    return null;
  end if;
  return 'WB' || substring(v_delivery from 2);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_mark_app_notification_read(p_notification_id uuid, p_login text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_count int;
BEGIN
  UPDATE public.be_app_notifications SET is_read = true, read_at = now() WHERE id = p_notification_id;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN jsonb_build_object('ok', v_count > 0, 'updated', v_count);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_mark_waybill_printed(p_pickup_ids text[])
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE v_role TEXT := public.be_current_user_role(); v_count INT;
BEGIN
  IF v_role NOT IN ('admin','operation_manager','cs','data_entry') THEN RAISE EXCEPTION 'Access denied'; END IF;
  UPDATE public.be_portal_pickup_requests SET waybill_printed_at=NOW(), updated_at=NOW() WHERE pickup_id=ANY(p_pickup_ids);
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN json_build_object('success',true,'updated',v_count,'ts',NOW());
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_mark_waybills_printed(p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_actor text := coalesce(p_payload->>'actor_email', 'waybill-studio@britiumexpress.com');
  v_ids text[] := array(
    select jsonb_array_elements_text(coalesce(p_payload->'waybill_nos', '[]'::jsonb))
  );
  v_count integer := 0;
begin
  if array_length(v_ids, 1) is null then
    raise exception 'waybill_nos is required';
  end if;

  update public.be_data_entry_parcel_details d
  set
    print_status = 'Printed',
    printed_at = now(),
    printed_by = v_actor,
    warehouse_status = 'PRINTED_READY_FOR_SORTING',
    way_management_status = 'PRINTED_READY_FOR_ROUTE_PLANNING',
    finance_status = 'READY_FOR_INVOICE',
    updated_at = now()
  where coalesce(d.way_id, d.delivery_way_id) = any(v_ids);

  get diagnostics v_count = row_count;

  insert into public.be_waybill_print_events (
    waybill_no,
    pickup_id,
    parcel_sequence,
    event_type,
    actor_email,
    payload
  )
  select
    coalesce(d.way_id, d.delivery_way_id),
    d.pickup_id,
    d.parcel_sequence,
    'WAYBILL_PRINTED',
    v_actor,
    jsonb_build_object(
      'warehouse_status', 'PRINTED_READY_FOR_SORTING',
      'way_management_status', 'PRINTED_READY_FOR_ROUTE_PLANNING',
      'finance_status', 'READY_FOR_INVOICE',
      'cod_amount', d.actual_collect,
      'delivery_fee', d.delivery_fee,
      'item_price', d.item_price
    )
  from public.be_data_entry_parcel_details d
  where coalesce(d.way_id, d.delivery_way_id) = any(v_ids);

  return jsonb_build_object(
    'ok', true,
    'printed_count', v_count,
    'waybill_nos', to_jsonb(v_ids)
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_master_data_autofill(p_merchant_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  v_merchant public.be_master_merchants;
BEGIN
  SELECT * INTO v_merchant
  FROM public.be_master_merchants
  WHERE merchant_code = p_merchant_code
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Merchant not found');
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'merchant_code', v_merchant.merchant_code,
    'merchant_name', coalesce(v_merchant.merchant_name, ''),
    'contact_person', coalesce(v_merchant.contact_person, ''),
    'phone_primary', coalesce(v_merchant.phone_primary, ''),
    'pickup_address', coalesce(v_merchant.address_line_1, ''),
    'township', coalesce(v_merchant.township, ''),
    'business_type', coalesce(v_merchant.business_type, 'E-commerce'),
    'payment_terms', coalesce(v_merchant.payment_terms, 'COD')
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_master_data_bulk_upsert_records(p_dataset_key text, p_rows jsonb, p_actor_email text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row jsonb;
  v_count integer := 0;
  v_pk text;
  v_key text;
begin
  select primary_key into v_pk
  from public.be_master_data_tabs
  where dataset_key = p_dataset_key;

  if v_pk is null then
    raise exception 'Unknown master dataset: %', p_dataset_key;
  end if;

  for v_row in select * from jsonb_array_elements(coalesce(p_rows, '[]'::jsonb))
  loop
    v_key := nullif(v_row ->> v_pk, '');
    perform public.be_master_data_upsert_record(p_dataset_key, v_key, v_row, p_actor_email);
    v_count := v_count + 1;
  end loop;

  return jsonb_build_object('ok', true, 'dataset_key', p_dataset_key, 'upserted', v_count);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_master_data_combobox(p_kind text, p_search text DEFAULT ''::text, p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$

DECLARE
    normalized_kind text;
    search_text text;

BEGIN

    normalized_kind :=
        lower(trim(coalesce(p_kind,'')));

    search_text :=
        lower(trim(coalesce(p_search,'')));


    RETURN jsonb_build_object(

        'options',

        (
            SELECT coalesce(
                jsonb_agg(
                    jsonb_build_object(
                        'value', x.value,
                        'label', x.label,
                        'label_mm', x.label_mm,
                        'meta', jsonb_build_object(
                            'dropdown_name', x.dropdown_name,
                            'master_type', x.master_type,
                            'option_type', x.option_type
                        )
                    )
                    ORDER BY x.sort_order, x.value
                ),
                '[]'::jsonb
            )

            FROM (

                SELECT
                    value,
                    coalesce(
                        myanmar_label,
                        label_mm,
                        value
                    ) AS label,
                    label_mm,
                    dropdown_name,
                    master_type,
                    option_type,
                    sort_order

                FROM public.be_master_data_options

                WHERE lower(option_type)=normalized_kind

                AND is_active=true

                AND (
                    search_text=''
                    OR lower(value) LIKE '%'||search_text||'%'
                    OR lower(coalesce(myanmar_label,'')) LIKE '%'||search_text||'%'
                    OR lower(coalesce(label_mm,'')) LIKE '%'||search_text||'%'
                )

                LIMIT p_limit

            ) x
        )

    );

END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_master_data_delete_record(p_dataset_key text, p_record_key text, p_actor_email text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_count integer;
begin
  update public.be_master_data_rows
  set deleted_at = now(),
      status = 'DELETED',
      updated_by_email = p_actor_email,
      updated_at = now()
  where dataset_key = p_dataset_key
    and record_key = p_record_key
    and deleted_at is null;

  get diagnostics v_count = row_count;

  return jsonb_build_object(
    'ok', v_count > 0,
    'dataset_key', p_dataset_key,
    'record_key', p_record_key,
    'deleted', v_count
  );
end;
$function$
;

