CREATE OR REPLACE FUNCTION public.be_master_data_page_snapshot()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_rows jsonb;
  v_summary jsonb;
  v_options jsonb;
begin
  select coalesce(jsonb_agg(to_jsonb(r) order by r.entity_type, r.entity_name nulls last, r.entity_code), '[]'::jsonb)
  into v_rows
  from public.be_master_entity_records r
  where coalesce(r.record_status, 'Active') <> 'Deleted';

  select jsonb_build_object(
    'total_records', count(*),
    'merchants', count(*) filter (where entity_type = 'MERCHANT'),
    'riders', count(*) filter (where entity_type = 'RIDER'),
    'drivers', count(*) filter (where entity_type = 'DRIVER'),
    'helpers', count(*) filter (where entity_type = 'HELPER'),
    'fleet', count(*) filter (where entity_type = 'FLEET'),
    'employees', count(*) filter (where entity_type = 'EMPLOYEE'),
    'branches', count(*) filter (where entity_type = 'BRANCH'),
    'options', count(*) filter (where entity_type = 'OPTION'),
    'townships', count(*) filter (where entity_type = 'TOWNSHIP'),
    'tariffs', count(*) filter (where entity_type = 'TARIFF')
  )
  into v_summary
  from public.be_master_entity_records
  where coalesce(record_status, 'Active') <> 'Deleted';

  select coalesce(jsonb_object_agg(dropdown_name, values), '{}'::jsonb)
  into v_options
  from (
    select
      dropdown_name,
      jsonb_agg(value order by sort_order nulls last, value) as values
    from public.be_master_data_options
    where is_active = true
    group by dropdown_name
  ) x;

  return jsonb_build_object(
    'ok', true,
    'source', 'be_master_data_page_snapshot',
    'summary', coalesce(v_summary, '{}'::jsonb),
    'rows', coalesce(v_rows, '[]'::jsonb),
    'entities', coalesce(v_rows, '[]'::jsonb),
    'options', coalesce(v_options, '{}'::jsonb)
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_master_data_snapshot(p_dataset_key text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0, p_search text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
BEGIN
  IF p_dataset_key = 'merchants' THEN
    RETURN json_build_object('data', (SELECT COALESCE(json_agg(row_to_json(m)), '[]'::json) FROM public.be_masterdata_merchants m LIMIT p_limit OFFSET p_offset));
  ELSE
    RETURN json_build_object('data', (SELECT COALESCE(json_agg(row_to_json(m)), '[]'::json) FROM public.be_master_data_options m WHERE dropdown_name = p_dataset_key LIMIT p_limit OFFSET p_offset));
  END IF;
END; $function$
;

