CREATE OR REPLACE FUNCTION public.be_master_entity_delete(p_entity_type text, p_entity_code text, p_actor_email text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_entity text := upper(trim(coalesce(p_entity_type, '')));
  v_before jsonb := '{}'::jsonb;
  v_count integer := 0;
begin
  select to_jsonb(r)
  into v_before
  from public.be_master_entity_records r
  where r.entity_type = v_entity
    and r.entity_code = p_entity_code
  limit 1;

  update public.be_master_entity_records
  set
    record_status = 'Deleted',
    updated_by = p_actor_email,
    updated_at = now(),
    data = coalesce(data, '{}'::jsonb) || jsonb_build_object(
      'deleted_at', now(),
      'deleted_by', p_actor_email
    )
  where entity_type = v_entity
    and entity_code = p_entity_code;

  get diagnostics v_count = row_count;

  perform public.be_write_governance_audit(
    'MASTER_DATA',
    'MASTER_ENTITY_DELETED',
    'be_master_entity_records',
    p_entity_code,
    p_actor_email,
    coalesce(v_before, '{}'::jsonb),
    jsonb_build_object(
      'entity_type', v_entity,
      'entity_code', p_entity_code,
      'deleted_rows', v_count
    ),
    '{}'::jsonb
  );

  if v_entity = 'EMPLOYEE' then
    perform public.be_hr_employee_delete(p_entity_code, p_actor_email);
  end if;

  if v_entity = 'BRANCH' then
    update public.be_branch_offices
    set status = 'Inactive', updated_at = now()
    where branch_code = p_entity_code;
  end if;

  return jsonb_build_object(
    'ok', true,
    'entity_type', v_entity,
    'entity_code', p_entity_code,
    'deleted_rows', v_count
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_master_entity_save(p_entity_type text, p_record jsonb, p_actor_email text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_entity text := upper(trim(coalesce(p_entity_type, '')));
  v_code text;
  v_name text;
  v_status text;
  v_id uuid;
begin
  if v_entity = '' then
    raise exception 'entity_type is required';
  end if;

  v_code := coalesce(
    nullif(p_record->>'entity_code',''),
    nullif(p_record->>'merchant_code',''),
    nullif(p_record->>'rider_id',''),
    nullif(p_record->>'rider_code',''),
    nullif(p_record->>'driver_id',''),
    nullif(p_record->>'driver_code',''),
    nullif(p_record->>'helper_id',''),
    nullif(p_record->>'helper_code',''),
    nullif(p_record->>'fleet_id',''),
    nullif(p_record->>'vehicle_no',''),
    nullif(p_record->>'employee_id',''),
    nullif(p_record->>'employee_code',''),
    nullif(p_record->>'branch_code',''),
    nullif(p_record->>'township_code',''),
    nullif(p_record->>'zone_code',''),
    nullif(p_record->>'code','')
  );

  v_name := coalesce(
    nullif(p_record->>'entity_name',''),
    nullif(p_record->>'merchant_name',''),
    nullif(p_record->>'rider_name',''),
    nullif(p_record->>'driver_name',''),
    nullif(p_record->>'helper_name',''),
    nullif(p_record->>'vehicle_no',''),
    nullif(p_record->>'employee_name',''),
    nullif(p_record->>'full_name',''),
    nullif(p_record->>'display_name',''),
    nullif(p_record->>'branch_name',''),
    nullif(p_record->>'township',''),
    nullif(p_record->>'zone_name',''),
    nullif(p_record->>'name','')
  );

  v_status := coalesce(
    nullif(p_record->>'record_status',''),
    nullif(p_record->>'status',''),
    'Active'
  );

  if v_code is null then
    v_code := v_entity || '-' || to_char(now(), 'YYYYMMDDHH24MISSMS');
  end if;

  insert into public.be_master_entity_records (
    entity_type,
    entity_code,
    entity_name,
    record_status,
    data,
    created_by,
    updated_by
  )
  values (
    v_entity,
    v_code,
    v_name,
    v_status,
    p_record || jsonb_build_object(
      'entity_type', v_entity,
      'entity_code', v_code,
      'entity_name', v_name,
      'record_status', v_status
    ),
    p_actor_email,
    p_actor_email
  )
  on conflict (entity_type, entity_code)
  do update set
    entity_name = excluded.entity_name,
    record_status = excluded.record_status,
    data = excluded.data,
    updated_by = excluded.updated_by,
    updated_at = now()
  returning id into v_id;

  -- Keep employee master synchronized.
  if v_entity = 'EMPLOYEE' then
    perform public.be_hr_employee_save(
      p_record || jsonb_build_object(
        'employee_id', v_code,
        'full_name', coalesce(v_name, p_record->>'full_name'),
        'status', lower(v_status)
      ),
      p_actor_email
    );
  end if;

  -- Keep branch office synchronized.
  if v_entity = 'BRANCH' then
    insert into public.be_branch_offices (
      branch_code,
      branch_name,
      branch_type,
      city,
      region_state,
      township,
      address,
      phone,
      manager_name,
      manager_email,
      status,
      metadata,
      updated_at
    )
    values (
      v_code,
      coalesce(v_name, v_code),
      coalesce(nullif(p_record->>'branch_type',''), 'Branch Office'),
      coalesce(nullif(p_record->>'city',''), 'Yangon'),
      coalesce(nullif(p_record->>'region_state',''), 'Yangon Region'),
      nullif(p_record->>'township',''),
      nullif(p_record->>'address',''),
      nullif(p_record->>'phone',''),
      nullif(p_record->>'manager_name',''),
      nullif(p_record->>'manager_email',''),
      v_status,
      p_record,
      now()
    )
    on conflict (branch_code)
    do update set
      branch_name = excluded.branch_name,
      branch_type = excluded.branch_type,
      city = excluded.city,
      region_state = excluded.region_state,
      township = excluded.township,
      address = excluded.address,
      phone = excluded.phone,
      manager_name = excluded.manager_name,
      manager_email = excluded.manager_email,
      status = excluded.status,
      metadata = excluded.metadata,
      updated_at = now();
  end if;

  return jsonb_build_object(
    'ok', true,
    'id', v_id,
    'entity_type', v_entity,
    'entity_code', v_code,
    'entity_name', v_name,
    'record_status', v_status
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_master_record_lookup(p_record_type text, p_search text DEFAULT NULL::text, p_limit integer DEFAULT 20, p_lang text DEFAULT 'en'::text)
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
BEGIN
  IF p_record_type = 'merchant' THEN
    RETURN (SELECT coalesce(json_agg(row_to_json(t)), '[]'::json) FROM (
      SELECT merchant_code AS value, merchant_code || ' — ' || merchant_name AS label
      FROM public.be_masterdata_merchants
      WHERE status = 'active'
        AND (p_search IS NULL OR merchant_code ILIKE '%'||p_search||'%' OR merchant_name ILIKE '%'||p_search||'%')
      ORDER BY merchant_name LIMIT p_limit
    ) t);
  ELSIF p_record_type = 'rider' THEN
    RETURN (SELECT coalesce(json_agg(row_to_json(t)), '[]'::json) FROM (
      SELECT rider_id AS value, rider_id || ' — ' || rider_name AS label
      FROM public.be_masterdata_riders
      WHERE lower(status) = 'active'
        AND (p_search IS NULL OR rider_id ILIKE '%'||p_search||'%' OR rider_name ILIKE '%'||p_search||'%')
      ORDER BY rider_id LIMIT p_limit
    ) t);
  ELSIF p_record_type = 'driver' THEN
    RETURN (SELECT coalesce(json_agg(row_to_json(t)), '[]'::json) FROM (
      SELECT driver_id AS value, driver_id || ' — ' || driver_name AS label
      FROM public.be_masterdata_drivers
      WHERE lower(status) = 'active'
        AND (p_search IS NULL OR driver_id ILIKE '%'||p_search||'%' OR driver_name ILIKE '%'||p_search||'%')
      ORDER BY driver_id LIMIT p_limit
    ) t);
  ELSIF p_record_type IN ('vehicle','fleet') THEN
    RETURN (SELECT coalesce(json_agg(row_to_json(t)), '[]'::json) FROM (
      SELECT fleet_id AS value, fleet_id || ' — ' || vehicle_no || ' — ' || vehicle_type AS label
      FROM public.be_masterdata_fleet
      WHERE lower(coalesce(status,'')) IN ('active','assigned')
        AND (p_search IS NULL OR fleet_id ILIKE '%'||p_search||'%' OR vehicle_no ILIKE '%'||p_search||'%' OR vehicle_type ILIKE '%'||p_search||'%')
      ORDER BY fleet_id LIMIT p_limit
    ) t);
  END IF;

  RETURN '[]'::json;
END;
$function$
;

