CREATE OR REPLACE FUNCTION public.be_next_go_live_pickup_batch(p_pickup_date date, p_merchant_code text, p_parcel_count integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_date date := coalesce(p_pickup_date, now()::date);
  v_count integer := greatest(coalesce(p_parcel_count, 1), 1);
  v_code text;
  v_mmdd text;
  v_d_prefix text;
  v_p_prefix text;
  v_max_no integer := 0;
  v_start_no integer;
  v_end_no integer;
  v_pickup_id text;
begin
  v_code := upper(regexp_replace(coalesce(p_merchant_code, ''), '[^A-Za-z0-9]', '', 'g'));
  if v_code !~ '^[A-Z][A-Z0-9]{1,4}$' or v_code ~ '^[0-9]+$' then
    raise exception 'Invalid merchant abbreviation "%". Must be like MEL, NFS, HAM, SSF.', p_merchant_code;
  end if;

  v_code := left(v_code, 3);
  v_mmdd := to_char(v_date, 'MMDD');
  v_d_prefix := 'D' || v_mmdd;
  v_p_prefix := 'P' || v_mmdd;

  perform pg_advisory_xact_lock(hashtext(v_d_prefix));

  select greatest(
    coalesce((select max(delivery_end_no) from public.be_portal_pickup_requests where pickup_date = v_date and pickup_id ~ ('^P' || v_mmdd || '-[A-Z][A-Z0-9]{1,4}-[0-9]{3}$')), 0),
    coalesce((select max(substring(deliver_way_id from '[0-9]{3}$')::int) from public.be_portal_cargo_events where deliver_way_id ~ ('^' || v_d_prefix || '-[A-Z][A-Z0-9]{1,4}-[0-9]{3}$')), 0),
    coalesce((select max(substring(pickup_id from '[0-9]{3}$')::int) from public.be_portal_pickup_requests where pickup_id ~ ('^' || v_p_prefix || '-[A-Z][A-Z0-9]{1,4}-[0-9]{3}$')), 0)
  ) into v_max_no;

  v_start_no := v_max_no + 1;
  v_end_no := v_max_no + v_count;
  v_pickup_id := v_p_prefix || '-' || v_code || '-' || lpad(v_end_no::text, 3, '0');

  return jsonb_build_object(
    'pickup_id', v_pickup_id,
    'pickup_way_id', v_pickup_id,
    'merchant_abbr', v_code,
    'pickup_date', v_date,
    'date_code', v_mmdd,
    'delivery_prefix', v_d_prefix || '-' || v_code,
    'delivery_start_no', v_start_no,
    'delivery_end_no', v_end_no,
    'parcel_count', v_count
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_norm_text(p_text text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select lower(regexp_replace(coalesce(p_text,''), '\s+', ' ', 'g'));
$function$
;

CREATE OR REPLACE FUNCTION public.be_normalize_app_notification()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.notification_type := coalesce(nullif(new.notification_type, ''), 'general');
  new.category := coalesce(nullif(new.category, ''), new.notification_type, 'general');
  new.target_role := coalesce(nullif(new.target_role, ''), 'general');
  new.source_table := coalesce(nullif(new.source_table, ''), 'be_app_notifications');
  new.source_key := coalesce(nullif(new.source_key, ''), nullif(new.event_key, ''), coalesce(new.pickup_id, 'general') || ':' || new.target_role || ':' || gen_random_uuid()::text);
  new.event_key := coalesce(nullif(new.event_key, ''), new.notification_type || ':' || new.target_role || ':' || new.source_table || ':' || new.source_key);
  new.title := coalesce(nullif(new.title, ''), 'Notification');
  new.body := coalesce(nullif(new.body, ''), nullif(new.message, ''), new.title, 'Notification');
  new.message := coalesce(nullif(new.message, ''), new.body, new.title, 'Notification');
  new.status := coalesce(nullif(new.status, ''), 'unread');
  new.is_read := coalesce(new.is_read, false);
  new.payload := coalesce(new.payload, '{}'::jsonb);
  new.metadata := coalesce(new.metadata, '{}'::jsonb);
  new.created_at := coalesce(new.created_at, now());
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_normalize_assignment_notifications_for_pickup(p_pickup_id text, p_rider_code text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_updated integer := 0;
begin
  update public.be_app_notifications n
  set
    target_role = 'rider',
    target_user_code = coalesce(
      n.target_user_code,
      n.metadata#>>'{assignment,payload,rider_code}',
      p_rider_code
    ),
    target_workforce_code = coalesce(
      n.target_workforce_code,
      n.metadata#>>'{assignment,payload,rider_code}',
      p_rider_code
    ),
    notification_type = 'PICKUP_ASSIGNMENT',
    status = coalesce(nullif(n.status, ''), 'unread'),
    is_read = coalesce(n.is_read, false),
    metadata = coalesce(n.metadata, '{}'::jsonb) || jsonb_build_object(
      'next_action', 'PICKUP_VERIFY',
      'workflow_stage', 'RIDER_APP_QUEUE',
      'source', 'normalize_assignment_notifications_for_pickup'
    ),
    payload = coalesce(n.payload, '{}'::jsonb) || jsonb_build_object(
      'pickup_id', p_pickup_id,
      'pickup_way_id', p_pickup_id,
      'rider_code', coalesce(n.metadata#>>'{assignment,payload,rider_code}', p_rider_code),
      'next_action', 'PICKUP_VERIFY'
    )
  where (
       n.pickup_id = p_pickup_id
    or n.pickup_way_id = p_pickup_id
    or n.source_key = p_pickup_id
    or n.event_key ilike '%' || p_pickup_id || '%'
  )
  and n.target_role = 'rider'
  and coalesce(
    n.metadata#>>'{assignment,payload,rider_code}',
    n.target_user_code,
    p_rider_code
  ) is not null;

  get diagnostics v_updated = row_count;
  return v_updated;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_normalize_assignment_response_status(p_status text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case upper(trim(coalesce(p_status, '')))
    when 'ACCEPT' then 'ACCEPTED'
    when 'ACCEPTED_PICKUP' then 'ACCEPTED'
    when 'ACCEPTED_BY_RIDER' then 'ACCEPTED'
    when 'PICKUP_VERIFIED' then 'ACCEPTED'
    when 'REJECT' then 'REJECTED'
    when 'DECLINED' then 'REJECTED'
    when 'FAILED' then 'REJECTED'
    when '' then 'WAITING_ACCEPTANCE'
    else upper(trim(p_status))
  end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_normalize_deliveryway_id(p_value text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v text := upper(trim(coalesce(p_value, '')));
begin
  if v ~ '^D[0-9]{4}-[A-Z0-9]+-[0-9]{3}$' then
    return v;
  end if;
  return null;
end;
$function$
;

