CREATE OR REPLACE FUNCTION public.be_normalize_registry_role_value(p_value text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  v text;
BEGIN
  v := lower(trim(coalesce(p_value, '')));
  v := replace(v, '-', '_');
  v := regexp_replace(v, '\s+', '_', 'g');

  IF v = '' THEN
    RETURN null;
  END IF;

  RETURN CASE
    WHEN v IN ('superadmin', 'super_admin', 'administrator', 'system_admin', 'owner') THEN 'admin'
    WHEN v IN ('admin') THEN 'admin'
    WHEN v IN ('customer_service', 'customerservice', 'cs', 'customer_support', 'support') THEN 'customer_service'
    WHEN v IN ('ops', 'operations', 'ops_manager', 'operation_manager', 'operations_manager') THEN 'ops_manager'
    WHEN v IN ('finance_manager', 'finance_mgr') THEN 'finance_manager'
    WHEN v IN ('accountant', 'cashier', 'auditor', 'finance') THEN v
    WHEN v IN ('warehouse', 'warehouse_user', 'warehouse_staff', 'wh') THEN 'warehouse'
    WHEN v IN ('dispatch', 'dispatcher', 'dispatch_user') THEN 'dispatch'
    WHEN v IN ('supervisor', 'pickup_supervisor') THEN 'supervisor'
    WHEN v IN ('merchant', 'merchant_user') THEN 'merchant'
    WHEN v IN ('rider', 'field_rider') THEN 'rider'
    WHEN v IN ('driver', 'field_driver') THEN 'driver'
    WHEN v IN ('helper', 'field_helper') THEN 'helper'
    WHEN v IN ('user', 'staff', 'workforce', 'mobile_workforce') THEN 'user'
    ELSE v
  END;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_normalize_waybill_no(p_value text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v text := upper(trim(coalesce(p_value, '')));
begin
  if v ~ '^WB[0-9]{4}-[A-Z0-9]+-[0-9]{3}$' then
    return v;
  end if;
  return null;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_notify_branch_office_for_portal_pickup()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_branch text;
  v_pickup_id text;
  v_event_key text;
  v_message text;
begin
  v_branch := coalesce(nullif(new.assigned_branch, ''), 'YGN');
  v_pickup_id := new.pickup_id;

  if v_pickup_id is null then
    return new;
  end if;

  v_event_key := 'branch_pickup_request_created:branch_office:be_portal_pickup_requests:' || new.id::text;
  v_message := 'Pickup ' || v_pickup_id || ' is assigned to branch ' || v_branch || '.';

  insert into public.be_app_notifications (
    notification_type, category, target_role, target_branch_code, title, body, message, pickup_id,
    source_table, source_key, event_key, metadata, payload, status, is_read, created_at
  )
  values (
    'branch_pickup_request_created', 'branch_pickup_request_created', 'branch_office', v_branch,
    'New Branch Pickup Request', v_message, v_message, v_pickup_id,
    'be_portal_pickup_requests', new.id::text, v_event_key,
    jsonb_build_object('assigned_branch', v_branch, 'merchant_name', new.merchant_name, 'sender_name', new.sender_name, 'township', new.township, 'city', new.city),
    jsonb_build_object('pickup_id', v_pickup_id, 'event', 'branch_pickup_request_created', 'assigned_branch', v_branch),
    'unread', false, now()
  )
  on conflict (event_key)
  do update set
    target_branch_code = excluded.target_branch_code,
    pickup_id = excluded.pickup_id,
    body = excluded.body,
    message = excluded.message,
    metadata = excluded.metadata,
    payload = excluded.payload,
    status = 'unread',
    is_read = false,
    created_at = now(),
    read_at = null;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_operational_master_snapshot()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_payload jsonb;
begin
  select payload
    into v_payload
  from public.be_master_data_snapshots
  where snapshot_key = 'default'
  order by updated_at desc
  limit 1;

  return coalesce(
    v_payload,
    jsonb_build_object(
      'riders', '[]'::jsonb,
      'drivers', '[]'::jsonb,
      'helpers', '[]'::jsonb,
      'fleets', '[]'::jsonb,
      'vehicles', '[]'::jsonb,
      'employees', '[]'::jsonb,
      'townships', '[]'::jsonb,
      'service_types', '[]'::jsonb,
      'zones', '[]'::jsonb,
      'cod_fee_rules', '[]'::jsonb,
      'weight_brackets', '[]'::jsonb,
      'surcharge_rules', '[]'::jsonb,
      'updated_at', null
    )
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_operations_action(p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_action text := coalesce(p_payload->>'action','');
  v_ref text := coalesce(p_payload->>'ref_id','');
  v_actor text := coalesce(p_payload->>'actor','system');
begin
  insert into public.be_operational_events(module, action, ref_id, actor, payload)
  values (coalesce(p_payload->>'module','operations'), v_action, v_ref, v_actor, p_payload);

  if v_action = 'WAYPLAN_UPDATE' then
    update public.be_wayplan_command_rows
    set stop_status = coalesce(p_payload->>'status', stop_status),
        rider_name = coalesce(p_payload->>'rider_name', rider_name),
        vehicle_no = coalesce(p_payload->>'vehicle_no', vehicle_no),
        updated_at = now()
    where wayplan_id = v_ref or delivery_way_id = v_ref or pickup_id = v_ref;
  end if;

  if v_action = 'COD_STATUS_UPDATE' then
    update public.be_cod_handover_records
    set cod_status = coalesce(p_payload->>'status', cod_status),
        submitted_at = case when coalesce(p_payload->>'status','') in ('SUBMITTED','HANDED_OVER','LOCKED') then now() else submitted_at end
    where delivery_way_id = v_ref or handover_ref = v_ref;
  end if;

  return jsonb_build_object('ok', true, 'action', v_action, 'ref_id', v_ref);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_parcel_photo_reupload(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id uuid;
  v_row public.be_parcel_photo_reviews%rowtype;
begin
  if nullif(p_payload->>'review_id', '') is null then
    return jsonb_build_object('ok', false, 'error', 'review_id is required');
  end if;

  if nullif(p_payload->>'photo_url', '') is null then
    return jsonb_build_object('ok', false, 'error', 'photo_url is required');
  end if;

  v_id := (p_payload->>'review_id')::uuid;

  update public.be_parcel_photo_reviews
  set previous_photo_url = current_photo_url,
      current_photo_url = p_payload->>'photo_url',
      review_status = 'PENDING_REVIEW',
      rejection_reason = null,
      rejection_note = null,
      uploaded_by = p_payload->>'uploaded_by',
      uploaded_role = coalesce(p_payload->>'uploaded_role', 'WAREHOUSE'),
      reviewed_by = null,
      reviewed_at = null,
      reupload_count = coalesce(reupload_count, 0) + 1,
      payload = coalesce(payload, '{}'::jsonb) || p_payload,
      updated_at = now()
  where id = v_id
  returning * into v_row;

  if not found then
    return jsonb_build_object('ok', false, 'error', 'photo review row not found');
  end if;

  return jsonb_build_object(
    'ok', true,
    'source', 'be_parcel_photo_reupload',
    'review_id', v_row.id,
    'pickup_id', v_row.pickup_id,
    'parcel_sequence', v_row.parcel_sequence,
    'review_status', 'PENDING_REVIEW',
    'reupload_count', v_row.reupload_count
  );
end $function$
;

CREATE OR REPLACE FUNCTION public.be_parse_pickup_way_id(p_pickup_way_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  parts text[];
  v_mmdd text;
  v_merchant text;
  v_count integer;
begin
  if p_pickup_way_id is null or p_pickup_way_id !~ '^P[0-9]{4}-[A-Z0-9]{3}-[0-9]{3}$' then
    raise exception 'Invalid pickup way ID format: %. Expected P0713-BBG-005', p_pickup_way_id;
  end if;

  parts := string_to_array(p_pickup_way_id, '-');
  v_mmdd := substring(parts[1] from 2);
  v_merchant := parts[2];
  v_count := parts[3]::integer;

  return jsonb_build_object(
    'pickup_way_id', p_pickup_way_id,
    'mmdd', v_mmdd,
    'merchant_code', v_merchant,
    'parcel_count', v_count
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_parse_portal_date(p_value text)
 RETURNS date
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  v text := trim(coalesce(p_value, ''));
  a text[];
BEGIN
  IF v = '' THEN
    RETURN NULL;
  END IF;

  -- 2026-07-05 or 2026-07-05T...
  IF v ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}' THEN
    RETURN left(v, 10)::date;
  END IF;

  -- 07/05/2026 = MM/DD/YYYY, matching the portal date input shown in UAT.
  IF v ~ '^[0-9]{1,2}/[0-9]{1,2}/[0-9]{4}$' THEN
    a := regexp_split_to_array(v, '/');
    RETURN make_date(a[3]::int, a[1]::int, a[2]::int);
  END IF;

  BEGIN
    RETURN v::date;
  EXCEPTION WHEN others THEN
    RETURN NULL;
  END;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_patch_pickup_date_prefix()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  -- If the function forgot to include date_prefix, generate it automatically (e.g., '0705')
  IF NEW.date_prefix IS NULL AND NEW.pickup_date IS NOT NULL THEN
    NEW.date_prefix := to_char(NEW.pickup_date, 'MMDD');
  END IF;

  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_pending_pickup_assignment_list(p_search text DEFAULT ''::text, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
AS $function$
  select coalesce(jsonb_agg(jsonb_build_object(
    'raw_uuid', pickup_id, 'pickup_id', pickup_id, 'pickup_request_id', pickup_id, 'pickup_way_id', pickup_id, 'way_id', pickup_id,
    'sender_name', sender_name, 'sender_phone', sender_phone, 'merchant_name', merchant_name, 'merchant_code', merchant_code,
    'township', township, 'pickup_address', pickup_address, 'pickup_time', pickup_time, 'cod_amount', cod_amount,
    'parcel_count', parcel_count, 'status', status, 'assignment_status', coalesce(assignment_status, 'pending_assignment'),
    'assigned_branch', assigned_branch, 'created_at', created_at
  ) order by created_at desc), '[]'::jsonb)
  from public.be_portal_pickup_requests
  where pickup_id ~ '^P[0-9]{4}-[A-Z][A-Z0-9]{1,4}-[0-9]{3}$'
    and coalesce(status, '') not in ('cancelled', 'archived_test_data')
    and coalesce(assignment_status, 'pending_assignment') <> 'assigned'
    and (
      coalesce(p_search, '') = ''
      or pickup_id ilike '%' || p_search || '%'
      or sender_name ilike '%' || p_search || '%'
      or sender_phone ilike '%' || p_search || '%'
      or merchant_name ilike '%' || p_search || '%'
      or township ilike '%' || p_search || '%'
    )
  limit coalesce(p_limit, 100);
$function$
;

