CREATE OR REPLACE FUNCTION public.be_pickup_assignment_rider_notification_bridge()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_new jsonb;
  v_old jsonb;
  v_pickup_id text;
  v_rider_email text;
  v_rider_code text;
  v_payload jsonb;
begin
  v_new := to_jsonb(new);
  v_old := coalesce(to_jsonb(old), '{}'::jsonb);

  v_pickup_id := coalesce(
    v_new->>'pickup_way_id',
    v_new->>'pickup_id',
    v_new->>'request_code',
    v_new->>'tracking_no'
  );

  v_rider_email := coalesce(
    nullif(v_new->>'assigned_rider_email',''),
    nullif(v_new->>'rider_email',''),
    nullif(v_new->>'assigned_workforce_email','')
  );

  v_rider_code := coalesce(
    nullif(v_new->>'assigned_rider_code',''),
    nullif(v_new->>'rider_code',''),
    nullif(v_new->>'assigned_workforce_code','')
  );

  if v_pickup_id is null then
    return new;
  end if;

  if v_rider_email is null and v_rider_code is null then
    return new;
  end if;

  if coalesce(v_old->>'assigned_rider_email','') = coalesce(v_new->>'assigned_rider_email','')
     and coalesce(v_old->>'assigned_rider_code','') = coalesce(v_new->>'assigned_rider_code','')
     and coalesce(v_old->>'assigned_rider_id','') = coalesce(v_new->>'assigned_rider_id','')
     and coalesce(v_old->>'rider_code','') = coalesce(v_new->>'rider_code','')
  then
    return new;
  end if;

  v_payload := jsonb_strip_nulls(
    jsonb_build_object(
      'type', 'PICKUP_ASSIGNMENT',
      'notification_type', 'PICKUP_ASSIGNMENT',
      'category', 'pickup',
      'channel', 'rider_app',
      'status', 'UNREAD',
      'read', false,
      'is_read', false,

      'title', 'New pickup assignment',
      'message', 'Pickup ' || v_pickup_id || ' has been assigned to you.',
      'body', 'Pickup ' || v_pickup_id || ' has been assigned to you.',

      'recipient_email', v_rider_email,
      'target_email', v_rider_email,
      'user_email', v_rider_email,
      'rider_email', v_rider_email,

      'recipient_code', v_rider_code,
      'target_code', v_rider_code,
      'rider_code', v_rider_code,

      'recipient_role', 'rider',
      'target_role', 'rider',
      'role', 'rider',

      'pickup_id', v_pickup_id,
      'pickup_way_id', v_pickup_id,
      'request_code', v_pickup_id,
      'ref_id', v_pickup_id,
      'reference_id', v_pickup_id,

      'metadata', jsonb_build_object(
        'source', 'supervisor_assignment_bridge',
        'pickup_id', v_pickup_id,
        'rider_email', v_rider_email,
        'rider_code', v_rider_code,
        'workflow_stage', 'RIDER_APP_QUEUE',
        'action_required', 'PICKUP_VERIFY'
      ),
      'payload', jsonb_build_object(
        'source', 'supervisor_assignment_bridge',
        'pickup_id', v_pickup_id,
        'rider_email', v_rider_email,
        'rider_code', v_rider_code,
        'next_action', 'PICKUP_VERIFY'
      ),

      'created_at', now(),
      'updated_at', now()
    )
  );

  begin
    insert into public.be_app_notifications
    select *
    from jsonb_populate_record(null::public.be_app_notifications, v_payload);
  exception when others then
    raise notice 'Rider notification insert skipped: %', sqlerrm;
  end;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_pickup_assignment_status_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_new jsonb;
  v_status text;
  v_stage text;
  v_rider_status text;
  v_has_rider boolean;
begin
  v_new := to_jsonb(new);

  v_status := upper(coalesce(
    v_new->>'pickup_status',
    v_new->>'workflow_stage',
    v_new->>'status',
    ''
  ));

  v_stage := upper(coalesce(v_new->>'workflow_stage', ''));

  v_rider_status := upper(coalesce(v_new->>'rider_status', ''));

  /*
    Never downgrade records that already moved beyond assignment.
  */
  if v_status in (
      'ACCEPTED_BY_RIDER',
      'ACCEPTED',
      'PICKUP_VERIFIED',
      'PICKUP_COLLECTED',
      'DATA_ENTRY_REGISTERED',
      'WAREHOUSE_RECEIVED',
      'RECEIVED_AT_ORIGIN',
      'SORTING',
      'READY_FOR_DISPATCH',
      'IN_TRANSIT_TO_HUB',
      'RECEIVED_AT_DESTINATION',
      'READY_FOR_DELIVERY',
      'OUT_FOR_DELIVERY',
      'DELIVERED',
      'EXCEPTION'
    )
    or v_stage in (
      'ACCEPTED_PICKUP',
      'PICKUP_VERIFIED',
      'PICKUP_COLLECTED',
      'DATA_ENTRY_REGISTERED',
      'WAITING_WAREHOUSE_RECEIVE',
      'WAREHOUSE_RECEIVED',
      'SORTING',
      'READY_FOR_DISPATCH'
    )
    or v_rider_status in (
      'ACCEPTED',
      'PICKUP_VERIFIED',
      'PICKUP_COLLECTED',
      'EXCEPTION'
    )
  then
    return new;
  end if;

  v_has_rider :=
       nullif(v_new->>'assigned_rider_email','') is not null
    or nullif(v_new->>'assigned_rider_code','') is not null
    or nullif(v_new->>'assigned_rider_id','') is not null
    or nullif(v_new->>'assigned_workforce_code','') is not null
    or nullif(v_new->>'rider_code','') is not null
    or nullif(v_new->>'rider_id','') is not null;

  if v_has_rider then
    new := jsonb_populate_record(
      new,
      jsonb_strip_nulls(
        jsonb_build_object(
          'pickup_status', 'RIDER_ASSIGNED',
          'status', 'ASSIGNED',
          'workflow_stage', 'RIDER_APP_QUEUE',
          'rider_app_stage', 'ASSIGNED_PICKUP',
          'supervisor_status', 'ASSIGNED',
          'rider_status', 'WAITING_ACCEPTANCE',
          'assignment_status', 'ASSIGNED',
          'wayplan_status', coalesce(nullif(v_new->>'wayplan_status',''), 'PENDING_WAYPLAN'),
          'assigned_at', coalesce(nullif(v_new->>'assigned_at','')::timestamptz, now()),
          'updated_at', now()
        )
      )
    );
  end if;

  return new;
exception when others then
  raise notice 'be_pickup_assignment_status_guard skipped: %', sqlerrm;
  return new;
end;
$function$
;

