CREATE OR REPLACE FUNCTION public.be_pickup_id_parcel_count_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row jsonb;
  v_old jsonb;
  v_count integer;
  v_old_count integer;
  v_merchant text;
  v_created_at timestamptz;
  v_pickup_way_id text;
  v_existing_id text;
  v_should_recalculate boolean := false;
begin
  v_row := to_jsonb(new);
  v_old := coalesce(to_jsonb(old), '{}'::jsonb);

  v_count := public.be_pickup_total_parcels_from_payload(v_row);
  v_old_count := public.be_pickup_total_parcels_from_payload(v_old);

  v_existing_id := coalesce(
    nullif(v_row->>'pickup_way_id', ''),
    nullif(v_row->>'pickup_id', ''),
    nullif(v_row->>'request_code', '')
  );

  /*
    Recalculate pickup ID only when:
    1. New insert
    2. ID is missing
    3. ID is still wrong -001 but actual parcel count > 1
    4. Parcel count changed and old/new ID is still the old wrong generated form

    Do NOT recalculate during normal assignment/status updates.
  */
  v_should_recalculate :=
       TG_OP = 'INSERT'
    or v_existing_id is null
    or (
      v_count > 1
      and coalesce(v_existing_id, '') ~ '-001$'
    )
    or (
      TG_OP = 'UPDATE'
      and v_count is distinct from v_old_count
      and coalesce(v_existing_id, '') ~ '-001$'
    );

  if not v_should_recalculate then
    return new;
  end if;

  v_merchant := public.be_clean_merchant_code3(
    coalesce(
      v_row->>'merchant_code',
      v_row#>>'{metadata,merchant_code}',
      v_row#>>'{payload,merchant_code}',
      v_row->>'merchantCode',
      v_row->>'merchant',
      v_row->>'merchant_id',
      v_row->>'merchant_name',
      v_row#>>'{metadata,merchant_name}',
      'GEN'
    )
  );

  v_created_at := coalesce(
    nullif(v_row->>'created_at','')::timestamptz,
    nullif(v_row->>'pickup_date','')::timestamptz,
    nullif(v_row#>>'{metadata,submitted_at}','')::timestamptz,
    now()
  );

  v_pickup_way_id := public.be_make_pickup_way_id(
    v_merchant,
    v_count,
    v_created_at
  );

  -- Avoid duplicate pickup_id collision.
  if TG_OP = 'UPDATE'
     and v_pickup_way_id <> coalesce(v_existing_id, '')
     and exists (
       select 1
       from public.be_portal_pickup_requests x
       where x.id <> new.id
         and (
              x.pickup_way_id = v_pickup_way_id
           or x.pickup_id = v_pickup_way_id
           or x.request_code = v_pickup_way_id
         )
     )
  then
    -- Preserve current ID, but still correct counts.
    new := jsonb_populate_record(
      new,
      jsonb_strip_nulls(
        jsonb_build_object(
          'parcel_count', v_count,
          'expected_parcels', v_count,
          'expected_parcel_count', v_count
        )
      )
    );

    return new;
  end if;

  new := jsonb_populate_record(
    new,
    jsonb_strip_nulls(
      jsonb_build_object(
        'pickup_way_id', v_pickup_way_id,
        'pickup_id', v_pickup_way_id,
        'request_code', v_pickup_way_id,
        'parcel_count', v_count,
        'expected_parcels', v_count,
        'expected_parcel_count', v_count
      )
    )
  );

  return new;
exception when others then
  return new;
end;
$function$
;

