CREATE OR REPLACE FUNCTION public.be_pickup_merchant_code(p_merchant_code text DEFAULT NULL::text, p_merchant_name text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  v_code text := regexp_replace(upper(coalesce(p_merchant_code, '')), '[^A-Z0-9]', '', 'g');
  v_name text := upper(coalesce(p_merchant_name, ''));
  v_alpha text;
BEGIN
  IF length(v_code) >= 3 THEN
    RETURN left(v_code, 3);
  END IF;

  IF v_name LIKE '%BABY GENIUS%' THEN
    RETURN 'BBG';
  END IF;

  IF v_name LIKE '%BEAUTY COS%' OR v_name LIKE '%BCA%' THEN
    RETURN 'BCA';
  END IF;

  v_alpha := upper(regexp_replace(v_name, '[^A-Z0-9]', '', 'g'));

  IF length(v_alpha) >= 3 THEN
    RETURN left(v_alpha, 3);
  END IF;

  RETURN rpad(coalesce(nullif(v_alpha, ''), 'GEN'), 3, 'X');
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_pickup_next_id(p_pickup_date date, p_merchant_code text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_mmdd text := to_char(coalesce(p_pickup_date, current_date), 'MMDD');
  v_code text := left(public.be_pickup_clean_code(p_merchant_code, 'GEN'), 3);
  v_next integer := 1;
begin
  select coalesce(max(nullif(split_part(pickup_id, '-', 3), '')::integer), 0) + 1
  into v_next
  from public.be_portal_pickup_requests
  where pickup_id ~ ('^P' || v_mmdd || '-' || v_code || '-[0-9]{3}$');

  return 'P' || v_mmdd || '-' || v_code || '-' || lpad(v_next::text, 3, '0');
exception when others then
  return 'P' || v_mmdd || '-' || v_code || '-' || lpad(floor(random() * 900 + 100)::int::text, 3, '0');
end;
$function$
;

