CREATE OR REPLACE FUNCTION public.be_pickup_request_options(p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
AS $function$
  select coalesce(jsonb_agg(jsonb_build_object(
    'value', pickup_id,
    'label', pickup_id || ' — [' || coalesce(merchant_name, merchant_code, sender_name, '-') || '] — Count: ' || coalesce(parcel_count, 1)::text,
    'pickup_id', pickup_id, 'pickup_request_id', pickup_id, 'pickup_way_id', pickup_id, 'way_id', pickup_id,
    'merchant_code', merchant_code, 'merchant_name', merchant_name, 'sender_name', sender_name, 'sender_phone', sender_phone,
    'township', township, 'city', city, 'pickup_address', pickup_address, 'payment_terms', payment_terms, 'tariff_code', tariff_code,
    'assigned_branch', assigned_branch, 'pickup_time', pickup_time, 'parcel_count', parcel_count, 'cod_amount', cod_amount,
    'status', status, 'assignment_status', assignment_status, 'payload', payload
  ) order by created_at desc), '[]'::jsonb)
  from (
    select * from public.be_portal_pickup_requests
    where pickup_id ~ '^P[0-9]{4}-[A-Z][A-Z0-9]{1,4}-[0-9]{3}$'
      and coalesce(status, '') not in ('cancelled', 'archived_test_data')
    order by created_at desc
    limit coalesce(p_limit, 100)
  ) r;
$function$
;

CREATE OR REPLACE FUNCTION public.be_pickup_requests_before_insert_id_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  base_code TEXT;
  date_str TEXT;
  seq_num INT;
BEGIN
  -- If the frontend already provided a valid pickup_id, skip generation.
  IF NEW.pickup_id IS NOT NULL AND NEW.pickup_id != '' THEN
    RETURN NEW;
  END IF;

  -- 1. Get the current date string (e.g., '0706' for July 6th)
  date_str := to_char(now(), 'MMDD');

  -- 2. Determine the merchant code (Fallback to 'GEN' if missing)
  base_code := COALESCE(NEW.merchant_code, 'GEN');

  -- 3. Safely get the next sequence number without looping
  -- This checks how many pickups this merchant already has today
  SELECT COUNT(*) + 1 INTO seq_num
  FROM public.be_portal_pickup_requests
  WHERE merchant_code = base_code
    AND DATE(created_at) = CURRENT_DATE;

  -- 4. Construct the new ID (e.g., 'P0706-KKK-001')
  NEW.pickup_id := 'P' || date_str || '-' || base_code || '-' || lpad(seq_num::text, 3, '0');

  -- 5. Fallback guard: If by some tiny chance this exact ID was just inserted
  -- in the last millisecond by another user, append a random string to guarantee uniqueness
  -- without causing a database loop.
  IF EXISTS (SELECT 1 FROM public.be_portal_pickup_requests WHERE pickup_id = NEW.pickup_id) THEN
     NEW.pickup_id := NEW.pickup_id || '-' || substr(md5(random()::text), 1, 4);
  END IF;

  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_pickup_total_parcels_from_payload(p_payload jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v_count integer := 1;
  v_candidate text;
  v_key text;
  v_keys text[] := array[
    'pickup_parcel_count',
    'parcel_count',
    'expected_parcels',
    'expected_parcel_count',
    'total_parcels',
    'number_of_parcels',
    'numberOfParcels',
    'totalPackages',
    'package_count',
    'packageCount',
    'qty',
    'quantity',
    'expected_count',
    'delivery_count',
    'waybill_count'
  ];
begin
  -- top-level, metadata, and payload scalar counts.
  foreach v_key in array v_keys loop
    v_candidate := p_payload->>v_key;
    if v_candidate is not null and trim(v_candidate) ~ '^[0-9]+$' then
      v_count := greatest(v_count, trim(v_candidate)::integer);
    end if;

    v_candidate := p_payload#>>array['metadata', v_key];
    if v_candidate is not null and trim(v_candidate) ~ '^[0-9]+$' then
      v_count := greatest(v_count, trim(v_candidate)::integer);
    end if;

    v_candidate := p_payload#>>array['payload', v_key];
    if v_candidate is not null and trim(v_candidate) ~ '^[0-9]+$' then
      v_count := greatest(v_count, trim(v_candidate)::integer);
    end if;
  end loop;

  -- array-based counts.
  if jsonb_typeof(p_payload->'parcels') = 'array' then
    v_count := greatest(v_count, jsonb_array_length(p_payload->'parcels'));
  end if;

  if jsonb_typeof(p_payload->'items') = 'array' then
    v_count := greatest(v_count, jsonb_array_length(p_payload->'items'));
  end if;

  if jsonb_typeof(p_payload->'packages') = 'array' then
    v_count := greatest(v_count, jsonb_array_length(p_payload->'packages'));
  end if;

  if jsonb_typeof(p_payload->'waybills') = 'array' then
    v_count := greatest(v_count, jsonb_array_length(p_payload->'waybills'));
  end if;

  if jsonb_typeof(p_payload->'deliveries') = 'array' then
    v_count := greatest(v_count, jsonb_array_length(p_payload->'deliveries'));
  end if;

  return greatest(least(coalesce(v_count, 1), 999), 1);
exception when others then
  return 1;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_pickupway_normalized_rows()
 RETURNS TABLE(source_table text, raw_id text, pickup_id text, pickup_way_id text, request_code text, merchant_code text, merchant_name text, township text, city text, pickup_address text, pickup_phone text, assigned_rider_email text, assigned_rider_code text, assigned_rider text, pickup_status text, workflow_stage text, supervisor_status text, rider_status text, status text, assigned_at text, created_at text, updated_at text, vehicle_type text, expected_parcels integer, parcel_count integer, payment_terms text, payment_type text, cod_amount numeric, item_price numeric, delivery_fee numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_table text;
  v_reg regclass;
begin
  foreach v_table in array array[
    'be_portal_pickup_requests',
    'be_pickup_requests',
    'be_supervisor_pickup_assignments'
  ] loop
    v_reg := to_regclass('public.' || quote_ident(v_table));
    if v_reg is null then
      continue;
    end if;

    return query execute format($q$
      select
        %L::text as source_table,
        public.be_json_first_text(j, array['id','pickup_way_id','pickup_id','pickup_request_id','request_code','pickup_waybill_id','waybill_no','tracking_no']) as raw_id,
        upper(public.be_json_first_text(j, array['pickup_way_id','pickup_id','pickup_request_id','request_code','pickup_waybill_id','waybill_no','tracking_no','id'])) as pickup_id,
        upper(public.be_json_first_text(j, array['pickup_way_id','pickup_id','pickup_request_id','request_code','pickup_waybill_id','waybill_no','tracking_no','id'])) as pickup_way_id,
        upper(public.be_json_first_text(j, array['request_code','pickup_way_id','pickup_id','pickup_request_id','pickup_waybill_id','waybill_no','tracking_no','id'])) as request_code,
        public.be_json_first_text(j, array['merchant_code','merchant_id','customer_code']) as merchant_code,
        public.be_json_first_text(j, array['merchant_name','merchant','customer_name','customer']) as merchant_name,
        public.be_json_first_text(j, array['township','pickup_township','merchant_township','delivery_township','destination_township']) as township,
        public.be_json_first_text(j, array['city','pickup_city','merchant_city','delivery_city']) as city,
        public.be_json_first_text(j, array['pickup_address','address','merchant_address','origin_address']) as pickup_address,
        public.be_json_first_text(j, array['pickup_phone','phone','merchant_phone','customer_phone','phone_primary']) as pickup_phone,
        lower(public.be_json_first_text(j, array['assigned_rider_email','rider_email','assigned_workforce_email'])) as assigned_rider_email,
        upper(public.be_json_first_text(j, array['assigned_rider_code','assigned_rider','assigned_workforce_code','rider_code','rider_id'])) as assigned_rider_code,
        upper(public.be_json_first_text(j, array['assigned_rider','assigned_rider_code','assigned_workforce_code','rider_code','rider_id'])) as assigned_rider,
        upper(public.be_json_first_text(j, array['pickup_status','status','request_status'])) as pickup_status,
        upper(public.be_json_first_text(j, array['workflow_stage','stage'])) as workflow_stage,
        upper(public.be_json_first_text(j, array['supervisor_status'])) as supervisor_status,
        upper(public.be_json_first_text(j, array['rider_status'])) as rider_status,
        upper(public.be_json_first_text(j, array['status','pickup_status','request_status'])) as status,
        public.be_json_first_text(j, array['assigned_at','assigned_on','assignment_at']) as assigned_at,
        public.be_json_first_text(j, array['created_at','created_on','request_created_at']) as created_at,
        public.be_json_first_text(j, array['updated_at','modified_at']) as updated_at,
        public.be_json_first_text(j, array['vehicle_type','fleet_type','vehicle_code','vehicle_no','vehicle_plate']) as vehicle_type,
        public.be_json_try_int(public.be_json_first_text(j, array['expected_parcels','parcel_count','total_parcels','parcels'])) as expected_parcels,
        public.be_json_try_int(public.be_json_first_text(j, array['parcel_count','expected_parcels','total_parcels','parcels'])) as parcel_count,
        public.be_json_first_text(j, array['payment_terms','payment_term']) as payment_terms,
        public.be_json_first_text(j, array['payment_type','payment_mode']) as payment_type,
        public.be_json_try_numeric(public.be_json_first_text(j, array['cod_amount','rider_cod_amount','cod_collected_amount'])) as cod_amount,
        public.be_json_try_numeric(public.be_json_first_text(j, array['item_price','declared_value'])) as item_price,
        public.be_json_try_numeric(public.be_json_first_text(j, array['delivery_fee','shipping_fee'])) as delivery_fee
      from (
        select to_jsonb(p) as j
        from %s p
      ) s
      where public.be_json_first_text(j, array['pickup_way_id','pickup_id','pickup_request_id','request_code','pickup_waybill_id','waybill_no','tracking_no','id']) is not null
    $q$, v_table, v_reg);
  end loop;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_pickupway_total_parcel_count(p_pickup_way_id text, p_fallback_count numeric DEFAULT NULL::numeric)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v_id text := public.be_normalize_pickupway_id(p_pickup_way_id);
  v_suffix text;
  v_count integer;
  v_fallback integer;
begin
  if v_id is not null then
    v_suffix := substring(v_id from '-([0-9]{3})$');
    v_count := nullif(v_suffix::integer, 0);
  end if;

  v_fallback := greatest(1, least(999, coalesce(floor(p_fallback_count)::integer, 1)));

  -- Business rule from Britium: the final 3 digits of PickupWayID represent
  -- the delivery parcel count under the same sender pickup.
  return greatest(1, least(999, coalesce(v_count, v_fallback)));
exception when others then
  return 1;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_portal_wiring_health()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_checks jsonb := '[]'::jsonb;
  v_item jsonb;
  v_system_ok boolean;
begin
  begin
    v_item := public.be_go_live_system_readiness();

    v_system_ok := coalesce(
      (v_item->>'ok')::boolean,
      (v_item->>'passed')::boolean,
      false
    );

    v_checks := v_checks || jsonb_build_array(jsonb_build_object(
      'module', 'System Readiness',
      'ok', v_system_ok,
      'source', 'be_go_live_system_readiness',
      'status', case when v_system_ok then 'ready' else 'not_ready' end,
      'summary', v_item
    ));
