      'error', sqlerrm
    ));
  end;

  begin
    v_item := public.be_exception_screen_snapshot(null, null);
    v_checks := v_checks || jsonb_build_array(jsonb_build_object(
      'module', 'Exceptions',
      'ok', coalesce((v_item->>'ok')::boolean, false),
      'source', 'be_exception_screen_snapshot',
      'summary', v_item->'summary'
    ));
