      'error', sqlerrm
    ));
  end;

  return jsonb_build_object(
    'ok', not exists (
      select 1
      from jsonb_to_recordset(v_checks) as x(ok boolean)
      where ok is false
    ),
    'source', 'be_portal_wiring_health',
    'checked_at', now(),
    'total_modules', jsonb_array_length(v_checks),
    'checks', v_checks
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_process_router(p_route text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_route text := lower(coalesce(p_route, ''));
  v_payload jsonb := coalesce(p_payload, '{}'::jsonb);

  v_ids jsonb := '{}'::jsonb;

  v_weight numeric := 0;
  v_chargeable_weight integer := 0;
  v_service_tier text := '';
  v_allowance integer := 3;
  v_extra_weight integer := 0;
  v_weight_surcharge numeric := 0;
  v_highway_fee numeric := 0;
  v_extra_weight_fee numeric := 0;
  v_base_fee numeric := 2500;
  v_total_tariff numeric := 0;

  v_branch text := 'YGN';
  v_city_text text := '';
begin
  if v_route = 'pickup.create' then
    v_ids := public.be_make_operational_ids_v2(v_payload);

    v_service_tier := upper(coalesce(v_payload->>'service_tier', 'STANDARD'));
    v_weight := coalesce(nullif(v_payload->>'pickup_weight_kg','')::numeric, 0);
    v_chargeable_weight := greatest(ceil(v_weight)::integer, 1);

    v_allowance := case
      when v_service_tier = 'ROYAL' then 5
      else 3
    end;

    v_extra_weight := greatest(v_chargeable_weight - v_allowance, 0);
    v_weight_surcharge := v_extra_weight * 500;

    v_highway_fee := case
      when coalesce((v_payload->>'highway_station_dropoff')::boolean, false) then 3000
      else 0
    end;

    v_extra_weight_fee := v_weight_surcharge + v_highway_fee;
    v_total_tariff := v_base_fee + v_extra_weight_fee;

    v_city_text := lower(
      coalesce(v_payload->>'pickup_city','') || ' ' ||
      coalesce(v_payload->>'township','') || ' ' ||
      coalesce(v_payload->>'pickup_address','')
    );

    v_branch := case
      when v_city_text like '%naypyitaw%'
        or v_city_text like '%nay pyi taw%'
        or v_city_text like '%npt%' then 'NPT'
      when v_city_text like '%mandalay%'
        or v_city_text like '%mdy%' then 'MDY'
      else 'YGN'
    end;

    return jsonb_build_object(
      'ok', true,
      'source', 'be_process_router',
      'route', p_route,
      'dry_run', coalesce((v_payload->>'dry_run')::boolean, false),
      'process_function', 'be_process_create_pickup',
      'canonical_ids', jsonb_build_object(
        'pickup_id', v_ids->>'pickup_way_id',
        'pickup_way_id', v_ids->>'pickup_way_id',
        'pickup_parcel_count', v_ids->>'pickup_parcel_count',
        'deliveries', v_ids->'deliveries'
      ),
      'tariff', jsonb_build_object(
        'service_tier', v_service_tier,
        'actual_weight_kg', v_weight,
        'chargeable_weight_kg', v_chargeable_weight,
        'allowance_kg', v_allowance,
        'extra_weight_kg', v_extra_weight,
        'weight_surcharge', v_weight_surcharge,
        'highway_fee', v_highway_fee,
        'extra_weight_fee', v_extra_weight_fee,
        'base_fee', v_base_fee,
        'total_tariff', v_total_tariff
      ),
      'assigned_branch', v_branch,
      'notification', jsonb_build_object(
        'type', 'task',
        'role',
          case
            when v_branch = 'NPT' then 'Naypyitaw Branch Admin'
            when v_branch = 'MDY' then 'Mandalay Branch Admin'
            else 'Yangon Branch Admin'
          end,
        'branch_code', v_branch
      ),
      'status', 'pickup_created'
    );
  end if;

  if v_route in ('production.readiness', 'production_readiness') then
    return public.be_production_readiness_dashboard_plus(
      v_payload->>'actor_email',
      v_payload->>'actor_role'
    );
  end if;

  if v_route in ('document.print.governance', 'document_print_governance') then
    return public.be_document_print_governance_dashboard(
      coalesce(nullif(v_payload->>'limit','')::integer, 200)
    );
  end if;

  if v_route in ('dispatch.rider.finance.e2e', 'dispatch_rider_finance_e2e') then
    return public.be_dispatch_rider_finance_e2e_health();
  end if;

  return jsonb_build_object(
    'ok', false,
    'source', 'be_process_router',
    'route', p_route,
    'message', 'Unknown process route'
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_production_readiness_dashboard()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_wiring jsonb := '[]'::jsonb;
  v_admin jsonb := '{}'::jsonb;
  v_master jsonb := '{}'::jsonb;
  v_branch jsonb := '{}'::jsonb;
  v_governance jsonb := '{}'::jsonb;
  v_print jsonb := '{}'::jsonb;
  v_summary jsonb := '{}'::jsonb;
  v_modules jsonb := '[]'::jsonb;
begin
  begin
    select coalesce(jsonb_agg(to_jsonb(x)), '[]'::jsonb)
    into v_wiring
    from public.be_portal_wiring_health() x;
  exception when others then
    v_wiring := jsonb_build_array(jsonb_build_object(
      'module', 'Portal Wiring Health',
      'status', 'ERROR',
      'message', sqlerrm
    ));
  end;

  begin
    v_admin := public.be_hr_dashboard();
  exception when others then
    v_admin := jsonb_build_object('ok', false, 'error', sqlerrm);
  end;

  begin
    v_master := public.be_master_data_page_snapshot();
  exception when others then
    v_master := jsonb_build_object('ok', false, 'error', sqlerrm);
  end;

  begin
    v_branch := public.be_branch_office_snapshot(null, 50);
  exception when others then
    v_branch := jsonb_build_object('ok', false, 'error', sqlerrm);
  end;

  begin
    v_governance := public.be_governance_approval_center(50);
  exception when others then
    v_governance := jsonb_build_object('ok', false, 'error', sqlerrm);
  end;

  begin
    v_print := public.be_document_print_approval_center(50);
  exception when others then
    v_print := jsonb_build_object('ok', false, 'error', sqlerrm);
  end;

  v_modules := jsonb_build_array(
    jsonb_build_object(
      'module', 'Portal Wiring Health',
      'status', case when jsonb_array_length(v_wiring) > 0 then 'READY' else 'WARNING' end,
      'detail', v_wiring
    ),
    jsonb_build_object(
      'module', 'Admin / HR',
      'status', case when coalesce((v_admin->>'ok')::boolean, false) then 'READY' else 'ERROR' end,
      'summary', v_admin->'summary',
      'error', v_admin->>'error'
    ),
    jsonb_build_object(
      'module', 'Master Data',
      'status', case when coalesce((v_master->>'ok')::boolean, false) then 'READY' else 'ERROR' end,
      'summary', v_master->'summary',
      'error', v_master->>'error'
    ),
    jsonb_build_object(
      'module', 'Branch Office',
      'status', case when coalesce((v_branch->>'ok')::boolean, false) then 'READY' else 'ERROR' end,
      'summary', v_branch->'summary',
      'error', v_branch->>'error'
    ),
    jsonb_build_object(
      'module', 'Governance Approval',
      'status', case when coalesce((v_governance->>'ok')::boolean, false) then 'READY' else 'ERROR' end,
      'summary', v_governance->'summary',
      'error', v_governance->>'error'
    ),
    jsonb_build_object(
      'module', 'Print Approval',
      'status', case when coalesce((v_print->>'ok')::boolean, false) then 'READY' else 'ERROR' end,
      'summary', v_print->'summary',
      'error', v_print->>'error'
    )
  );

  select jsonb_build_object(
    'total_modules', count(*),
    'ready_modules', count(*) filter (where m->>'status' = 'READY'),
    'warning_modules', count(*) filter (where m->>'status' = 'WARNING'),
    'error_modules', count(*) filter (where m->>'status' = 'ERROR')
  )
  into v_summary
  from jsonb_array_elements(v_modules) m;

  return jsonb_build_object(
    'ok', true,
    'source', 'be_production_readiness_dashboard',
    'generated_at', now(),
    'summary', v_summary,
    'modules', v_modules
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_production_readiness_dashboard(p_actor_email text DEFAULT NULL::text, p_actor_role text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_ctx jsonb;
  v_wiring jsonb := '[]'::jsonb;
  v_admin jsonb := '{}'::jsonb;
  v_master jsonb := '{}'::jsonb;
  v_branch jsonb := '{}'::jsonb;
  v_governance jsonb := '{}'::jsonb;
  v_print jsonb := '{}'::jsonb;
  v_summary jsonb := '{}'::jsonb;
  v_modules jsonb := '[]'::jsonb;
begin
  v_ctx := public.be_require_admin(p_actor_email, p_actor_role);

  begin
    select coalesce(jsonb_agg(to_jsonb(x)), '[]'::jsonb)
    into v_wiring
    from public.be_portal_wiring_health() x;
  exception when others then
    v_wiring := jsonb_build_array(jsonb_build_object(
      'module', 'Portal Wiring Health',
      'status', 'ERROR',
      'message', sqlerrm
    ));
  end;

  begin
    v_admin := public.be_hr_dashboard();
  exception when others then
    v_admin := jsonb_build_object('ok', false, 'error', sqlerrm);
  end;

  begin
    v_master := public.be_master_data_page_snapshot();
  exception when others then
    v_master := jsonb_build_object('ok', false, 'error', sqlerrm);
  end;

  begin
    v_branch := public.be_branch_office_snapshot(null, 50);
  exception when others then
    v_branch := jsonb_build_object('ok', false, 'error', sqlerrm);
  end;

  begin
    v_governance := public.be_governance_approval_center(50, p_actor_email, p_actor_role);
  exception when others then
    v_governance := jsonb_build_object('ok', false, 'error', sqlerrm);
  end;

  begin
    v_print := public.be_document_print_approval_center(50);
  exception when others then
    v_print := jsonb_build_object('ok', false, 'error', sqlerrm);
  end;

  v_modules := jsonb_build_array(
    jsonb_build_object('module', 'Portal Wiring Health', 'status', case when jsonb_array_length(v_wiring) > 0 then 'READY' else 'WARNING' end, 'detail', v_wiring),
    jsonb_build_object('module', 'Admin / HR', 'status', case when coalesce((v_admin->>'ok')::boolean, false) then 'READY' else 'ERROR' end, 'summary', v_admin->'summary', 'error', v_admin->>'error'),
    jsonb_build_object('module', 'Master Data', 'status', case when coalesce((v_master->>'ok')::boolean, false) then 'READY' else 'ERROR' end, 'summary', v_master->'summary', 'error', v_master->>'error'),
    jsonb_build_object('module', 'Branch Office', 'status', case when coalesce((v_branch->>'ok')::boolean, false) then 'READY' else 'ERROR' end, 'summary', v_branch->'summary', 'error', v_branch->>'error'),
    jsonb_build_object('module', 'Governance Approval', 'status', case when coalesce((v_governance->>'ok')::boolean, false) then 'READY' else 'ERROR' end, 'summary', v_governance->'summary', 'error', v_governance->>'error'),
    jsonb_build_object('module', 'Print Approval', 'status', case when coalesce((v_print->>'ok')::boolean, false) then 'READY' else 'ERROR' end, 'summary', v_print->'summary', 'error', v_print->>'error')
  );

  select jsonb_build_object(
    'total_modules', count(*),
    'ready_modules', count(*) filter (where m->>'status' = 'READY'),
    'warning_modules', count(*) filter (where m->>'status' = 'WARNING'),
    'error_modules', count(*) filter (where m->>'status' = 'ERROR')
  )
  into v_summary
  from jsonb_array_elements(v_modules) m;

  return jsonb_build_object(
    'ok', true,
    'source', 'be_production_readiness_dashboard',
    'actor', v_ctx,
    'generated_at', now(),
    'summary', v_summary,
    'modules', v_modules
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_production_readiness_dashboard_plus(p_actor_email text DEFAULT NULL::text, p_actor_role text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_base jsonb := '{}'::jsonb;
  v_e2e_module jsonb := '{}'::jsonb;
  v_print_module jsonb := '{}'::jsonb;
  v_base_modules jsonb := '[]'::jsonb;
  v_combined_modules jsonb := '[]'::jsonb;
  v_ready_count integer := 0;
  v_warning_count integer := 0;
  v_error_count integer := 0;
  v_total_count integer := 0;
begin
  begin
    select public.be_production_readiness_dashboard(p_actor_email, p_actor_role)
    into v_base;
  exception when others then
    v_base := jsonb_build_object(
      'ok', false,
      'source', 'be_production_readiness_dashboard_plus',
      'base_error', sqlerrm,
      'modules', '[]'::jsonb
    );
  end;

  select public.be_production_readiness_dispatch_rider_finance_module()
  into v_e2e_module;

  select public.be_production_readiness_print_governance_module()
  into v_print_module;

  v_base_modules := case
    when jsonb_typeof(v_base->'modules') = 'array' then v_base->'modules'
    when jsonb_typeof(v_base->'checks') = 'array' then v_base->'checks'
    when jsonb_typeof(v_base->'readiness_modules') = 'array' then v_base->'readiness_modules'
    else '[]'::jsonb
  end;

  v_combined_modules :=
    v_base_modules
    || jsonb_build_array(v_e2e_module)
    || jsonb_build_array(v_print_module);

  select
    count(*) filter (where upper(coalesce(m->>'status', '')) = 'READY'),
    count(*) filter (where upper(coalesce(m->>'status', '')) in ('WARNING','CHECK_REQUIRED')),
    count(*) filter (where upper(coalesce(m->>'status', '')) in ('ERROR','FAILED','NOT_READY')),
    count(*)
  into
    v_ready_count,
    v_warning_count,
    v_error_count,
    v_total_count
  from jsonb_array_elements(v_combined_modules) m;

  return jsonb_build_object(
    'ok', true,
    'source', 'be_production_readiness_dashboard_plus',
    'generated_at', now(),
    'status',
      case
        when v_error_count > 0 then 'ERROR'
        when v_warning_count > 0 then 'WARNING'
        else 'READY'
      end,
    'summary', jsonb_build_object(
      'total_modules', v_total_count,
      'ready_modules', v_ready_count,
      'warning_modules', v_warning_count,
      'error_modules', v_error_count,
      'dispatch_rider_finance_e2e', coalesce(v_e2e_module->>'status', 'CHECK_REQUIRED'),
      'document_print_governance', coalesce(v_print_module->>'status', 'CHECK_REQUIRED')
    ),
    'modules', v_combined_modules,
    'base_dashboard', v_base,
    'dispatch_rider_finance_e2e', v_e2e_module,
    'document_print_governance', v_print_module
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_production_readiness_dispatch_rider_finance_module()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_health jsonb := '{}'::jsonb;
begin
  select public.be_dispatch_rider_finance_e2e_health()
  into v_health;

  return jsonb_build_object(
    'module', 'Dispatch Rider Finance E2E',
    'status', coalesce(v_health->>'status', 'CHECK_REQUIRED'),
    'ready', coalesce(v_health->>'status', '') = 'READY',
    'summary', v_health->'summary',
    'capacity', v_health->'capacity',
    'rider_jobs', v_health->'rider_jobs',
    'finance_queue', v_health->'finance_queue',
    'checked_at', now()
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_production_readiness_print_governance_module()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_dashboard jsonb := '{}'::jsonb;
  v_summary jsonb := '{}'::jsonb;
begin
  select public.be_document_print_governance_dashboard(100)
  into v_dashboard;

  v_summary := coalesce(v_dashboard->'summary', '{}'::jsonb);

  return jsonb_build_object(
    'module', 'Document Print Governance',
    'status', coalesce(v_dashboard->>'status', 'CHECK_REQUIRED'),
    'ready', coalesce(v_dashboard->>'status', '') = 'READY',
    'summary', v_summary,
    'checked_at', now()
  );
end;
$function$
;

create or replace view "public"."be_proof_gallery_daily_merchant" as  SELECT business_date,
    merchant_code,
    merchant_name,
    proof_scope,
    count(*) AS proof_count,
    count(*) FILTER (WHERE (proof_type = 'PHOTO'::text)) AS photo_count,
    count(*) FILTER (WHERE (proof_type = 'SIGNATURE'::text)) AS signature_count,
    count(DISTINCT pickup_id) AS pickup_count,
    count(DISTINCT delivery_way_id) AS delivery_count,
    max(created_at) AS latest_uploaded_at
   FROM public.be_parcel_proof_media
  GROUP BY business_date, merchant_code, merchant_name, proof_scope;


CREATE OR REPLACE FUNCTION public.be_qr_scan_validate(p_tracking_code text, p_actor_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_parcel record;
begin

select *
into v_parcel
from public.parcels
where tracking_code = p_tracking_code
limit 1;


if v_parcel.id is null then

return jsonb_build_object(
'ok',false,
'error','Tracking code not found'
);

end if;


return jsonb_build_object(
'ok',true,
'tracking_code',v_parcel.tracking_code,
'parcel_id',v_parcel.id,
'current_status',v_parcel.status,
'next_actions',
case
 when v_parcel.status='registered'
 then jsonb_build_array('PICKUP')
 when v_parcel.status='in_transit'
 then jsonb_build_array('DELIVER')
 when v_parcel.status='out_for_delivery'
 then jsonb_build_array('DELIVER','FAILED')
 else jsonb_build_array()
end,
'actor',p_actor_code,
'validated_at',now()
);

end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_rebuild_auto_commission_events(p_work_date date DEFAULT CURRENT_DATE, p_actor_email text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  rec record;
  d jsonb;
  v_work_date date := coalesce(p_work_date, current_date);
  v_inserted integer := 0;
  v_delivery_rows integer := 0;
  v_pickup_rows integer := 0;
  v_role text;
  v_code text;
  v_name text;
  v_rate numeric;
  v_pickup_count integer;
  v_status text;
  v_done_date date;
begin
  delete from public.be_commission_events
  where work_date = v_work_date
    and source_type = 'AUTO';

  for rec in
    select
      s.*,
      d.rider_code,
      d.rider_name,
      d.driver_code,
      d.driver_name,
      d.helper_code,
      d.helper_name,
      d.vehicle_code,
      d.vehicle_name
    from public.be_wayplan_dispatch_stops s
    left join public.be_wayplan_dispatches d
      on d.wayplan_id = s.wayplan_id
  loop
    d := to_jsonb(rec);

    v_status := upper(coalesce(
      public.be_text_first_nonempty(d, 'stop_status', 'delivery_status', 'dispatch_status', 'status'),
      ''
    ));

    v_done_date := public.be_date_from_json(d, 'delivered_at', 'completed_at', 'updated_at', 'created_at');

    if v_status = 'DELIVERED' and v_done_date = v_work_date then
      foreach v_role in array array['RIDER','DRIVER','HELPER'] loop
        v_code := case v_role
          when 'RIDER' then public.be_text_first_nonempty(d, 'rider_code', 'rider_email', 'assigned_rider_code', 'assigned_rider_email')
          when 'DRIVER' then public.be_text_first_nonempty(d, 'driver_code', 'driver_email', 'assigned_driver_code', 'assigned_driver_email')
          when 'HELPER' then public.be_text_first_nonempty(d, 'helper_code', 'helper_email', 'assigned_helper_code', 'assigned_helper_email')
        end;

        v_name := case v_role
          when 'RIDER' then public.be_text_first_nonempty(d, 'rider_name', 'assigned_rider_name')
          when 'DRIVER' then public.be_text_first_nonempty(d, 'driver_name', 'assigned_driver_name')
          when 'HELPER' then public.be_text_first_nonempty(d, 'helper_name', 'assigned_helper_name')
        end;

        if v_code is not null then
          v_rate := public.be_commission_get_rate('DELIVERY', v_role, 'PARCEL', v_work_date);

          insert into public.be_commission_events (
            source_type,
            work_date,
            operation_type,
            unit_type,
            unit_count,
            role_code,
            assignee_email,
            assignee_name,
            asset_code,
            tracking_no,
            pickup_id,
            waybill_no,
            wayplan_code,
            rate_mmk,
            commission_mmk,
            event_status,
            actor_email,
            metadata
          )
          values (
            'AUTO',
            v_work_date,
            'DELIVERY',
            'PARCEL',
            1,
            v_role,
            v_code,
            coalesce(v_name, v_code),
            public.be_text_first_nonempty(d, 'vehicle_code', 'vehicle_name', 'asset_code'),
            public.be_text_first_nonempty(d, 'delivery_way_id', 'tracking_no', 'waybill_no'),
            public.be_text_first_nonempty(d, 'pickup_id'),
            public.be_text_first_nonempty(d, 'waybill_no', 'delivery_way_id', 'tracking_no'),
            public.be_text_first_nonempty(d, 'wayplan_id', 'wayplan_code'),
            v_rate,
            v_rate,
            'READY',
            p_actor_email,
            d
          );

          v_inserted := v_inserted + 1;
        end if;
      end loop;

      v_delivery_rows := v_delivery_rows + 1;
    end if;
  end loop;

  for rec in
    select *
    from public.be_portal_pickup_requests p
  loop
    d := to_jsonb(rec);

    v_status := upper(coalesce(
      public.be_text_first_nonempty(d, 'pickup_status', 'workflow_stage', 'status'),
      ''
    ));

    v_done_date := public.be_date_from_json(d, 'pickup_completed_at', 'completed_at', 'updated_at', 'created_at');

    if v_status in ('PICKUP_COMPLETED','PICKUP_COLLECTED','COMPLETED','COLLECTED') and v_done_date = v_work_date then
      v_pickup_count := greatest(
        coalesce(
          nullif(public.be_text_first_nonempty(d, 'expected_parcel_count'), '')::integer,
          nullif(public.be_text_first_nonempty(d, 'expected_parcels'), '')::integer,
          nullif(public.be_text_first_nonempty(d, 'parcel_count'), '')::integer,
          nullif(d->'metadata'->>'parcel_count', '')::integer,
          1
        ),
        1
      );

      foreach v_role in array array['RIDER','DRIVER','HELPER'] loop
        v_code := case v_role
          when 'RIDER' then public.be_text_first_nonempty(d, 'rider_code', 'assigned_rider_code', 'assigned_rider_email', 'rider_email')
          when 'DRIVER' then public.be_text_first_nonempty(d, 'driver_code', 'assigned_driver_code', 'assigned_driver_email', 'driver_email')
          when 'HELPER' then public.be_text_first_nonempty(d, 'helper_code', 'assigned_helper_code', 'assigned_helper_email', 'helper_email')
        end;

        v_name := case v_role
          when 'RIDER' then public.be_text_first_nonempty(d, 'rider_name', 'assigned_rider_name')
          when 'DRIVER' then public.be_text_first_nonempty(d, 'driver_name', 'assigned_driver_name')
          when 'HELPER' then public.be_text_first_nonempty(d, 'helper_name', 'assigned_helper_name')
        end;

        if v_code is not null then
          v_rate := public.be_commission_get_rate('PICKUP', v_role, 'PARCEL', v_work_date);

          insert into public.be_commission_events (
            source_type,
            work_date,
            operation_type,
            unit_type,
            unit_count,
            role_code,
            assignee_email,
            assignee_name,
            asset_code,
            tracking_no,
            pickup_id,
            waybill_no,
            wayplan_code,
            rate_mmk,
            commission_mmk,
            event_status,
            actor_email,
            metadata
          )
          values (
            'AUTO',
            v_work_date,
            'PICKUP',
            'PARCEL',
            v_pickup_count,
            v_role,
            v_code,
            coalesce(v_name, v_code),
            public.be_text_first_nonempty(d, 'vehicle_code', 'vehicle_name', 'asset_code'),
            public.be_text_first_nonempty(d, 'pickup_id', 'pickup_way_id'),
            public.be_text_first_nonempty(d, 'pickup_id', 'pickup_way_id'),
            public.be_text_first_nonempty(d, 'waybill_no'),
            null,
            v_rate,
            v_rate * v_pickup_count,
            'READY',
            p_actor_email,
            d
          );

          v_inserted := v_inserted + 1;
        end if;
      end loop;

      v_pickup_rows := v_pickup_rows + 1;
    end if;
  end loop;

  return jsonb_build_object(
    'ok', true,
    'work_date', v_work_date,
    'delivery_completed_rows', v_delivery_rows,
    'pickup_completed_rows', v_pickup_rows,
    'commission_event_rows_inserted', v_inserted
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_record_highway_dropoff_bags(p_wayplan_code text, p_bag_count integer, p_asset_code text DEFAULT NULL::text, p_rider_email text DEFAULT NULL::text, p_driver_email text DEFAULT NULL::text, p_helper_email text DEFAULT NULL::text, p_actor_email text DEFAULT NULL::text, p_work_date date DEFAULT CURRENT_DATE)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_bags integer := greatest(coalesce(p_bag_count,0),0);
  v_work_date date := coalesce(p_work_date, current_date);
  v_role text;
  v_email text;
  v_rate numeric;
  v_inserted integer := 0;
begin
  if nullif(trim(coalesce(p_wayplan_code,'')), '') is null then
    raise exception 'p_wayplan_code is required';
  end if;

  if v_bags <= 0 then
    raise exception 'p_bag_count must be greater than zero';
  end if;

  delete from public.be_commission_events
  where source_type = 'MANUAL_HIGHWAY_DROPOFF'
    and work_date = v_work_date
    and wayplan_code = p_wayplan_code
    and coalesce(asset_code,'') = coalesce(p_asset_code,'');

  foreach v_role in array array['RIDER','DRIVER','HELPER'] loop
    v_email := case v_role
      when 'RIDER' then nullif(trim(coalesce(p_rider_email,'')), '')
      when 'DRIVER' then nullif(trim(coalesce(p_driver_email,'')), '')
      when 'HELPER' then nullif(trim(coalesce(p_helper_email,'')), '')
    end;

    if v_email is not null then
      v_rate := public.be_commission_get_rate('HIGHWAY_DROPOFF', v_role, 'BAG', v_work_date);

      insert into public.be_commission_events (
        source_type, work_date, operation_type, unit_type, unit_count,
        role_code, assignee_email, asset_code, wayplan_code, bag_count,
        rate_mmk, commission_mmk, event_status, actor_email,
        metadata
      )
      values (
        'MANUAL_HIGHWAY_DROPOFF', v_work_date, 'HIGHWAY_DROPOFF', 'BAG', v_bags,
        v_role, v_email, p_asset_code, p_wayplan_code, v_bags,
        v_rate, v_rate * v_bags, 'READY', p_actor_email,
        jsonb_build_object('wayplan_code', p_wayplan_code, 'asset_code', p_asset_code, 'bag_count', v_bags)
      );

      v_inserted := v_inserted + 1;
    end if;
  end loop;

  return jsonb_build_object(
    'ok', true,
    'wayplan_code', p_wayplan_code,
    'bag_count', v_bags,
    'rows_inserted', v_inserted,
    'rate_per_bag_mmk', public.be_commission_get_rate('HIGHWAY_DROPOFF','DRIVER','BAG',v_work_date)
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_register_pickup_id_alias(p_legacy_pickup_id text, p_canonical_pickup_id text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
begin
  if coalesce(p_legacy_pickup_id, '') = '' or coalesce(p_canonical_pickup_id, '') = '' then
    raise exception 'legacy and canonical pickup IDs are required';
  end if;

  insert into public.be_pickup_id_aliases(legacy_pickup_id, canonical_pickup_id, reason)
  values (p_legacy_pickup_id, p_canonical_pickup_id, p_reason)
  on conflict (legacy_pickup_id) do update set
    canonical_pickup_id = excluded.canonical_pickup_id,
    reason = coalesce(excluded.reason, public.be_pickup_id_aliases.reason);

  return jsonb_build_object('ok', true, 'legacy_pickup_id', p_legacy_pickup_id, 'canonical_pickup_id', p_canonical_pickup_id);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_registry_safe_email_from_row(p_payload jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  v_seed text;
  v_role text;
  v_email text;
BEGIN
  v_role := lower(coalesce(
    nullif(p_payload->>'role', ''),
    nullif(p_payload->>'role_type', ''),
    nullif(p_payload->>'workforce_type', ''),
    nullif(p_payload->>'user_type', ''),
    'user'
  ));

  v_seed := coalesce(
    nullif(p_payload->>'account_code', ''),
    nullif(p_payload->>'employee_code', ''),
    nullif(p_payload->>'workforce_code', ''),
    nullif(p_payload->>'worker_id', ''),
    nullif(p_payload->>'rider_code', ''),
    nullif(p_payload->>'driver_code', ''),
    nullif(p_payload->>'user_id', ''),
    nullif(p_payload->>'auth_user_id', ''),
    nullif(p_payload->>'phone_number', ''),
    nullif(p_payload->>'phone', ''),
    substring(md5(coalesce(p_payload::text, '') || 'britium') from 1 for 12)
  );

  v_email := lower(v_role || '-' || v_seed || '@testing.britium.local');
  v_email := regexp_replace(v_email, '[^a-z0-9@._+-]+', '-', 'g');
  v_email := regexp_replace(v_email, '-+', '-', 'g');
  v_email := regexp_replace(v_email, '^-|-$', '', 'g');

  IF position('@' IN v_email) = 0 THEN
    v_email := 'user-' || substring(md5(coalesce(p_payload::text, '') || clock_timestamp()::text) from 1 for 12) || '@testing.britium.local';
  END IF;

  RETURN v_email;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_repair_pickup_operational_ids(p_pickup_way_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_count integer := 0;
  v_updated integer := 0;
begin
  if p_pickup_way_id is null then
    raise exception 'p_pickup_way_id is required';
  end if;

  perform public.be_parse_pickup_way_id(p_pickup_way_id);

  -- Repair be_waybill_ledger.
  if to_regclass('public.be_waybill_ledger') is not null then
    update public.be_waybill_ledger
    set pickup_way_id = p_pickup_way_id
    where pickup_way_id is null
      and pickup_id = p_pickup_way_id;

    with target as (
      select
        ctid,
        row_number() over (
          order by
            created_at nulls last,
            ctid
        )::integer as rn
      from public.be_waybill_ledger
      where coalesce(pickup_way_id, pickup_id) = p_pickup_way_id
    ),
    ids as (
      select
        t.ctid,
        public.be_make_operational_ids(p_pickup_way_id, t.rn) as j
      from target t
    )
    update public.be_waybill_ledger w
    set
      pickup_way_id = p_pickup_way_id,
      delivery_way_id = ids.j->>'delivery_way_id',
      waybill_no = ids.j->>'waybill_no',
      invoice_no = ids.j->>'invoice_no',
      tracking_no = ids.j->>'tracking_no',
      updated_at = now()
    from ids
    where w.ctid = ids.ctid;

    get diagnostics v_count = row_count;
    v_updated := v_updated + v_count;
  end if;

  -- Repair be_wayplan_dispatch_stops.
  if to_regclass('public.be_wayplan_dispatch_stops') is not null then
    with target as (
      select
        ctid,
        row_number() over (
          order by
            stop_sequence nulls last,
            created_at nulls last,
            ctid
        )::integer as rn
      from public.be_wayplan_dispatch_stops
      where pickup_id = p_pickup_way_id
    ),
    ids as (
      select
        t.ctid,
        public.be_make_operational_ids(p_pickup_way_id, t.rn) as j
      from target t
    )
    update public.be_wayplan_dispatch_stops s
    set
      delivery_way_id = ids.j->>'delivery_way_id',
      waybill_no = ids.j->>'waybill_no',
      invoice_no = ids.j->>'invoice_no',
      tracking_no = ids.j->>'tracking_no',
      warehouse_metadata = coalesce(s.warehouse_metadata, '{}'::jsonb) || jsonb_build_object(
        'id_repaired_at', now(),
        'pickup_way_id', p_pickup_way_id,
        'delivery_way_id', ids.j->>'delivery_way_id',
        'waybill_no', ids.j->>'waybill_no',
        'invoice_no', ids.j->>'invoice_no',
        'tracking_no', ids.j->>'tracking_no'
      ),
      updated_at = now()
    from ids
    where s.ctid = ids.ctid;

    get diagnostics v_count = row_count;
    v_updated := v_updated + v_count;
  end if;

  return jsonb_build_object(
    'ok', true,
    'pickup_way_id', p_pickup_way_id,
    'updated_rows', v_updated,
    'rule', 'P -> D / WB / INV / TRK using same MMDD, merchant code, and parcel sequence'
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_report_finance(p_from date, p_to date)
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
DECLARE v_role TEXT := public.be_current_user_role();
BEGIN
  IF v_role NOT IN ('admin','finance','accountant','auditor','operation_manager') THEN RAISE EXCEPTION 'Access denied'; END IF;
  RETURN (SELECT json_build_object(
    'period', json_build_object('from',p_from,'to',p_to),
    'by_payment', (SELECT COALESCE(json_agg(row_to_json(p)),'[]'::json) FROM (
      SELECT payment_method, COUNT(*) AS count, COALESCE(SUM(delivery_fee),0) AS total_fee, COALESCE(SUM(cod_amount),0) AS total_cod
      FROM public.be_portal_pickup_requests WHERE created_at::DATE BETWEEN p_from AND p_to GROUP BY payment_method
    ) p),
    'by_merchant', (SELECT COALESCE(json_agg(row_to_json(m)),'[]'::json) FROM (
      SELECT merchant_code, merchant_name, COUNT(*) AS shipments, COALESCE(SUM(delivery_fee),0) AS total_fee, COALESCE(SUM(cod_amount) FILTER (WHERE payment_method='COD'),0) AS cod_amount
      FROM public.be_portal_pickup_requests WHERE created_at::DATE BETWEEN p_from AND p_to GROUP BY merchant_code, merchant_name ORDER BY total_fee DESC LIMIT 20
    ) m)
  ));
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_report_operational(p_from date, p_to date, p_branch text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
DECLARE v_role TEXT := public.be_current_user_role();
BEGIN
  IF v_role NOT IN ('admin','operation_manager','supervisor','auditor','finance') THEN RAISE EXCEPTION 'Access denied'; END IF;
  RETURN (SELECT json_build_object(
    'period', json_build_object('from',p_from,'to',p_to),
    'branch', COALESCE(p_branch,'ALL'),
    'totals', (SELECT row_to_json(t) FROM (
      SELECT COUNT(*) AS total_shipments, COUNT(*) FILTER (WHERE status='DELIVERED') AS delivered, COUNT(*) FILTER (WHERE status IN ('FAILED_DELIVERY','RETURN_INITIATED','RETURNED')) AS failed, COUNT(*) FILTER (WHERE status='HOLD') AS on_hold, ROUND(COUNT(*) FILTER (WHERE status='DELIVERED')::NUMERIC / NULLIF(COUNT(*),0)*100,1) AS delivery_rate_pct, COALESCE(SUM(delivery_fee),0) AS total_delivery_fee, COALESCE(SUM(cod_amount) FILTER (WHERE payment_method='COD'),0) AS total_cod_collected, COALESCE(AVG(weight_kg),0) AS avg_weight_kg
      FROM public.be_portal_pickup_requests WHERE created_at::DATE BETWEEN p_from AND p_to AND (p_branch IS NULL OR branch_code=p_branch)
    ) t),
    'by_status', (SELECT COALESCE(json_agg(row_to_json(s)),'[]'::json) FROM (
      SELECT status, COUNT(*) AS count, ROUND(COUNT(*)::NUMERIC/NULLIF((SELECT COUNT(*) FROM public.be_portal_pickup_requests WHERE created_at::DATE BETWEEN p_from AND p_to),0)*100,1) AS pct
      FROM public.be_portal_pickup_requests WHERE created_at::DATE BETWEEN p_from AND p_to AND (p_branch IS NULL OR branch_code=p_branch) GROUP BY status ORDER BY count DESC
    ) s),
    'by_day', (SELECT COALESCE(json_agg(row_to_json(d)),'[]'::json) FROM (
      SELECT created_at::DATE AS date, COUNT(*) AS total, COUNT(*) FILTER (WHERE status='DELIVERED') AS delivered, COALESCE(SUM(delivery_fee),0) AS revenue
      FROM public.be_portal_pickup_requests WHERE created_at::DATE BETWEEN p_from AND p_to AND (p_branch IS NULL OR branch_code=p_branch) GROUP BY created_at::DATE ORDER BY date
    ) d),
    'by_tier', (SELECT COALESCE(json_agg(row_to_json(ti)),'[]'::json) FROM (
      SELECT service_tier, COUNT(*) AS count, COALESCE(SUM(delivery_fee),0) AS revenue
      FROM public.be_portal_pickup_requests WHERE created_at::DATE BETWEEN p_from AND p_to AND (p_branch IS NULL OR branch_code=p_branch) GROUP BY service_tier ORDER BY count DESC
    ) ti)
  ));
END;
$function$
;

