CREATE OR REPLACE FUNCTION public.be_require_admin(p_actor_email text DEFAULT NULL::text, p_actor_role text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_ctx jsonb;
begin
  v_ctx := public.be_current_actor_context(p_actor_email, p_actor_role);

  if coalesce((v_ctx->>'is_admin')::boolean, false) is not true then
    raise exception 'Access denied. Admin or Superadmin permission is required.';
  end if;

  return v_ctx;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_reserve_canonical_pickup_id(p_pickup_date date DEFAULT CURRENT_DATE, p_merchant_code text DEFAULT NULL::text, p_merchant_name text DEFAULT NULL::text, p_reserved_by text DEFAULT NULL::text, p_source text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_date date := coalesce(p_pickup_date, current_date);
  v_code text := public.be_pickup_merchant_code(p_merchant_code, p_merchant_name);
  v_prefix text;
  v_seq integer;
  v_id text;
BEGIN
  v_prefix := public.be_pickup_id_prefix(v_date, v_code);

  -- Prevent two browsers/users from reserving the same next sequence at once.
  PERFORM pg_advisory_xact_lock(hashtext('be_pickup_id:' || to_char(v_date, 'YYYY-MM-DD') || ':' || v_code));

  SELECT greatest(
    coalesce((
      SELECT max(r.sequence_no)
      FROM public.be_pickup_id_reservations r
      WHERE r.pickup_date = v_date
        AND upper(r.merchant_code) = v_code
    ), 0),
    coalesce((
      SELECT max(substring(p.pickup_id from '[0-9]+$')::integer)
      FROM public.be_portal_pickup_requests p
      WHERE p.pickup_id LIKE v_prefix || '%'
    ), 0)
  ) + 1
  INTO v_seq;

  LOOP
    v_id := v_prefix || lpad(v_seq::text, 3, '0');

    IF NOT EXISTS (
      SELECT 1 FROM public.be_portal_pickup_requests p WHERE p.pickup_id = v_id
    ) THEN
      BEGIN
        INSERT INTO public.be_pickup_id_reservations (
          pickup_date,
          merchant_code,
          sequence_no,
          pickup_id,
          reserved_by,
          source,
          metadata,
          created_at
        ) VALUES (
          v_date,
          v_code,
          v_seq,
          v_id,
          p_reserved_by,
          p_source,
          coalesce(p_metadata, '{}'::jsonb),
          now()
        );

        RETURN v_id;
      EXCEPTION WHEN unique_violation THEN
        v_seq := v_seq + 1;
      END;
    ELSE
      v_seq := v_seq + 1;
    END IF;
  END LOOP;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_resolve_branch(p_city text, p_township text, p_address text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE v_text TEXT := LOWER(COALESCE(p_city,'') || ' ' || COALESCE(p_township,'') || ' ' || COALESCE(p_address,''));
BEGIN
  IF v_text LIKE '%mandalay%' OR v_text LIKE '%mdy%' THEN RETURN 'MDY'; END IF;
  IF v_text LIKE '%naypyidaw%' OR v_text LIKE '%naypyitaw%' OR v_text LIKE '%nay pyi taw%' OR v_text LIKE '%npt%' THEN RETURN 'NPT'; END IF;
  RETURN 'YGN';
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_resolve_branch_code(p_city text, p_township text, p_address text)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  select case
    when lower(coalesce(p_city,'') || ' ' || coalesce(p_township,'') || ' ' || coalesce(p_address,'')) ~ 'mandalay|mdy' then 'MDY'
    when lower(coalesce(p_city,'') || ' ' || coalesce(p_township,'') || ' ' || coalesce(p_address,'')) ~ 'naypyitaw|naypyidaw|npt' then 'NPT'
    else 'YGN'
  end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_resolve_branch_from_location(city text, township text, addr text, fallback text DEFAULT 'YGN'::text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare h text := lower(coalesce(city,'')||' '||coalesce(township,'')||' '||coalesce(addr,''));
begin
  if h like '%mandalay%' or h like '%မန္တလေး%' then return 'MDY'; end if;
  if h like '%naypyitaw%' or h like '%nay pyi taw%' or h like '%naypyidaw%' or h like '%နေပြည်တော်%' then return 'NPT'; end if;
  return coalesce(public.be30_clean(fallback), 'YGN');
end; $function$
;

CREATE OR REPLACE FUNCTION public.be_resolve_merchant_meta(p_merchant_code text, p_merchant_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_code text;
  v_result jsonb := '{}'::jsonb;
begin
  v_code := public.be_known_merchant_code(p_merchant_code, p_merchant_name);

  if to_regclass('public.merchant_master') is not null then
    execute $q$
      with rows as (select to_jsonb(m) j from public.merchant_master m)
      select j || jsonb_build_object(
        'merchant_code', $1,
        'merchant_id', $1,
        'default_pickup_address',
          coalesce(
            nullif(j->>'default_pickup_address', ''),
            array_to_string(array_remove(array[j->>'address_line_1', j->>'address_line_2'], null), ', ')
          )
      )
      from rows
      where upper(coalesce(j->>'merchant_code', j->>'merchant_id', j->>'record_key', '')) = upper($1)
         or lower(coalesce(j->>'merchant_name', j->>'display_name', j->>'name', '')) = lower(coalesce($2, ''))
      limit 1
    $q$ into v_result using v_code, p_merchant_name;
  end if;

  if v_result is null or v_result = '{}'::jsonb then
    v_result := jsonb_build_object('merchant_code', v_code, 'merchant_id', v_code, 'merchant_name', coalesce(p_merchant_name, v_code), 'payment_terms', 'COD');
  end if;

  return v_result;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_resolve_mobile_worker(p_login text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_login text := lower(trim(coalesce(p_login, '')));
  v_digits text := regexp_replace(coalesce(p_login, ''), '[^0-9]', '', 'g');
  v_row record;
BEGIN
  IF v_login = '' THEN
    RETURN NULL;
  END IF;

  SELECT * INTO v_row
  FROM public.be_mobile_workforce_accounts w
  WHERE w.is_active IS DISTINCT FROM false
    AND (
      lower(coalesce(w.worker_code, '')) = v_login
      OR lower(coalesce(w.account_code, '')) = v_login
      OR lower(coalesce(w.email, '')) = v_login
      OR regexp_replace(coalesce(w.phone, ''), '[^0-9]', '', 'g') = v_digits
      OR EXISTS (
        SELECT 1
        FROM jsonb_array_elements_text(coalesce(w.aliases, '[]'::jsonb)) a(value)
        WHERE lower(a.value) = v_login
      )
    )
  ORDER BY CASE WHEN lower(coalesce(w.worker_code, '')) = v_login THEN 1 WHEN lower(coalesce(w.email, '')) = v_login THEN 2 ELSE 9 END
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  RETURN jsonb_build_object(
    'worker_code', v_row.worker_code,
    'account_code', v_row.account_code,
    'role', lower(v_row.role),
    'display_name', v_row.display_name,
    'phone', v_row.phone,
    'email', v_row.email,
    'branch_code', v_row.branch_code,
    'assigned_zone', v_row.assigned_zone,
    'aliases', coalesce(v_row.aliases, '[]'::jsonb)
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_resolve_pickup_id(p_pickup_id text)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  select coalesce(
    (select a.canonical_pickup_id
     from public.be_pickup_id_aliases a
     where a.legacy_pickup_id = p_pickup_id
     limit 1),
    p_pickup_id
  );
$function$
;

CREATE OR REPLACE FUNCTION public.be_resolve_user_access_by_email(p_email text)
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
DECLARE v_user RECORD;
BEGIN
    SELECT user_id, full_name, role, branch_code, status
    INTO v_user FROM public.be_user_account_registry WHERE email = p_email AND status = 'active' LIMIT 1;

    IF v_user IS NULL THEN RETURN json_build_object('authorized', false); END IF;
    RETURN json_build_object('authorized', true, 'role', v_user.role, 'branch', v_user.branch_code, 'name', v_user.full_name);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_resolve_workforce_identifier(p_identifier text, p_role text)
 RETURNS TABLE(resolved_email text, resolved_code text, resolved_name text, resolved_role text)
 LANGUAGE sql
 STABLE
AS $function$
  select
    nullif(email, '') as resolved_email,
    nullif(workforce_code, '') as resolved_code,
    coalesce(nullif(full_name, ''), nullif(name, ''), nullif(email, ''), nullif(workforce_code, '')) as resolved_name,
    upper(coalesce(role, p_role)) as resolved_role
  from public.be_mobile_workforce_accounts
  where p_identifier is not null
    and coalesce(is_active, true) = true
    and upper(coalesce(role, p_role)) = upper(p_role)
    and (
      lower(coalesce(email, '')) = lower(p_identifier)
      or lower(coalesce(workforce_code, '')) = lower(p_identifier)
      or lower(coalesce(full_name, '')) = lower(p_identifier)
      or lower(coalesce(name, '')) = lower(p_identifier)
    )
  order by
    case when lower(coalesce(email, '')) = lower(p_identifier) then 0 else 1 end,
    case when lower(coalesce(workforce_code, '')) = lower(p_identifier) then 0 else 1 end
  limit 1;
$function$
;

CREATE OR REPLACE FUNCTION public.be_review_parcel_photo(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id uuid;
  v_action text := upper(coalesce(p_payload->>'action', ''));
  v_status text;
  v_row public.be_parcel_photo_reviews%rowtype;
begin
  if nullif(p_payload->>'review_id', '') is null then
    return jsonb_build_object('ok', false, 'error', 'review_id is required');
  end if;

  v_id := (p_payload->>'review_id')::uuid;

  if v_action not in ('APPROVE', 'REJECT') then
    return jsonb_build_object('ok', false, 'error', 'action must be APPROVE or REJECT');
  end if;

  v_status := case when v_action = 'APPROVE' then 'APPROVED' else 'REUPLOAD_REQUIRED' end;

  update public.be_parcel_photo_reviews
  set review_status = v_status,
      rejection_reason = case when v_action = 'REJECT' then coalesce(p_payload->>'rejection_reason', 'OTHER') else null end,
      rejection_note = case when v_action = 'REJECT' then p_payload->>'rejection_note' else null end,
      reviewed_by = p_payload->>'reviewed_by',
      reviewed_at = now(),
      updated_at = now()
  where id = v_id
  returning * into v_row;

  if not found then
    return jsonb_build_object('ok', false, 'error', 'photo review row not found');
  end if;

  -- Synchronize with the Rider verification table using its actual sequence column.
  if to_regclass('public.be_rider_pickup_parcel_verifications') is not null then
    begin
      if exists (
        select 1 from information_schema.columns
        where table_schema = 'public'
          and table_name = 'be_rider_pickup_parcel_verifications'
          and column_name = 'parcel_sequence'
      ) then
        execute 'update public.be_rider_pickup_parcel_verifications
                 set status = $1, verified = $2, remarks = coalesce($3, remarks)
                 where pickup_id = $4 and parcel_sequence = $5'
        using v_status, (v_action = 'APPROVE'), v_row.rejection_note, v_row.pickup_id, v_row.parcel_sequence;
      elsif exists (
        select 1 from information_schema.columns
        where table_schema = 'public'
          and table_name = 'be_rider_pickup_parcel_verifications'
          and column_name = 'item_no'
      ) then
        execute 'update public.be_rider_pickup_parcel_verifications
                 set status = $1, verified = $2, remarks = coalesce($3, remarks)
                 where pickup_id = $4 and item_no = $5'
        using v_status, (v_action = 'APPROVE'), v_row.rejection_note, v_row.pickup_id, v_row.parcel_sequence;
      elsif exists (
        select 1 from information_schema.columns
        where table_schema = 'public'
          and table_name = 'be_rider_pickup_parcel_verifications'
          and column_name = 'tracking_no'
      ) and nullif(v_row.tracking_no, '') is not null then
        execute 'update public.be_rider_pickup_parcel_verifications
                 set status = $1, verified = $2, remarks = coalesce($3, remarks)
                 where pickup_id = $4 and tracking_no = $5'
        using v_status, (v_action = 'APPROVE'), v_row.rejection_note, v_row.pickup_id, v_row.tracking_no;
      else
        raise notice 'Rider verification sync skipped: no parcel_sequence, item_no, or usable tracking_no column.';
      end if;
    exception when undefined_column then
      raise notice 'Rider verification sync skipped because a legacy column is missing: %', sqlerrm;
    end;
  end if;

  update public.be_portal_pickup_requests p
  set rejected_photo_count = (
        select count(*) from public.be_parcel_photo_reviews r
        where r.pickup_id = v_row.pickup_id
          and r.review_status in ('PHOTO_REJECTED', 'REUPLOAD_REQUIRED')
      ),
      pending_photo_count = (
        select count(*) from public.be_parcel_photo_reviews r
        where r.pickup_id = v_row.pickup_id
          and r.review_status = 'PENDING_REVIEW'
      ),
      photo_review_status = case
        when exists (
          select 1 from public.be_parcel_photo_reviews r
          where r.pickup_id = v_row.pickup_id
            and r.review_status in ('PHOTO_REJECTED', 'REUPLOAD_REQUIRED')
        ) then 'REUPLOAD_REQUIRED'
        else 'PARTIAL_REVIEW'
      end,
      updated_at = now()
  where p.pickup_way_id = v_row.pickup_id;

  if v_action = 'REJECT' and to_regclass('public.be_app_notifications') is not null then
    begin
      insert into public.be_app_notifications (
        notification_type, title, message, target_role,
        target_user_code, pickup_id, is_read, created_at
      )
      select
        'PARCEL_PHOTO_REUPLOAD',
        'Photo re-upload required',
        'Parcel ' || v_row.parcel_sequence || ' photo was rejected: ' ||
          coalesce(v_row.rejection_reason, 'unclear photo'),
        'rider',
        p.assigned_rider_code,
        v_row.pickup_id,
        false,
        now()
      from public.be_portal_pickup_requests p
      where p.pickup_way_id = v_row.pickup_id;
    exception when others then
      raise notice 'Notification insert skipped: %', sqlerrm;
    end;
  end if;

  return jsonb_build_object(
    'ok', true,
    'source', 'be_review_parcel_photo',
    'review_id', v_row.id,
    'pickup_id', v_row.pickup_id,
    'parcel_sequence', v_row.parcel_sequence,
    'review_status', v_status
  );
end $function$
;

