CREATE OR REPLACE FUNCTION public.be_rider_assignment_notification_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_pickup_id text;
  v_rider_code text;
  v_rider_email text;
  v_rider_name text;
  v_event_key text;
begin
  v_pickup_id := coalesce(new.pickup_way_id, new.pickup_id, new.request_code);

  v_rider_code := coalesce(
    new.assigned_rider_code,
    new.metadata#>>'{assignment_payload,rider_code}',
    new.payload#>>'{assignment_payload,rider_code}'
  );

  v_rider_email := new.assigned_rider_email;

  v_rider_name := coalesce(
    new.assigned_rider_name,
    new.metadata#>>'{assignment_payload,rider_name}',
    new.payload#>>'{assignment_payload,rider_name}'
  );

  if v_pickup_id is null then
    return new;
  end if;

  if v_rider_code is null and v_rider_email is null then
    return new;
  end if;

  v_event_key := 'workflow:rider:be_portal_pickup_requests:' || v_pickup_id;

  insert into public.be_app_notifications (
    title,
    body,
    message,
    status,
    is_read,
    category,
    notification_type,
    event_type,
    event_key,
    source_key,
    source_table,
    pickup_id,
    pickup_way_id,
    target_role,
    target_user_code,
    target_workforce_code,
    target_email,
    recipient_role,
    recipient_email,
    metadata,
    payload,
    created_at
  )
  values (
    'New pickup assigned',
    v_pickup_id || ' is assigned to you',
    v_pickup_id || ' is assigned to you. Please accept and verify pickup.',
    'unread',
    false,
    'pickup',
    'PICKUP_ASSIGNMENT',
    'pickup_assignment',
    v_event_key,
    v_pickup_id,
    'be_portal_pickup_requests',
    v_pickup_id,
    v_pickup_id,
    'rider',
    v_rider_code,
    v_rider_code,
    v_rider_email,
    'rider',
    v_rider_email,
    jsonb_build_object(
      'source', 'rider_assignment_trigger',
      'pickup_id', v_pickup_id,
      'rider_code', v_rider_code,
      'rider_name', v_rider_name,
      'next_action', 'PICKUP_VERIFY',
      'workflow_stage', 'RIDER_APP_QUEUE'
    ),
    jsonb_build_object(
      'pickup_id', v_pickup_id,
      'pickup_way_id', v_pickup_id,
      'rider_code', v_rider_code,
      'rider_email', v_rider_email,
      'next_action', 'PICKUP_VERIFY'
    ),
    now()
  )
  on conflict (event_key) do update
  set
    title = excluded.title,
    body = excluded.body,
    message = excluded.message,
    status = 'unread',
    is_read = false,
    category = 'pickup',
    notification_type = 'PICKUP_ASSIGNMENT',
    event_type = 'pickup_assignment',
    source_key = excluded.source_key,
    source_table = excluded.source_table,
    pickup_id = excluded.pickup_id,
    pickup_way_id = excluded.pickup_way_id,
    target_role = 'rider',
    target_user_code = excluded.target_user_code,
    target_workforce_code = excluded.target_workforce_code,
    target_email = excluded.target_email,
    recipient_role = 'rider',
    recipient_email = excluded.recipient_email,
    metadata = coalesce(public.be_app_notifications.metadata, '{}'::jsonb) || excluded.metadata,
    payload = coalesce(public.be_app_notifications.payload, '{}'::jsonb) || excluded.payload;

  return new;
exception when others then
  raise notice 'rider assignment notification trigger skipped: %', sqlerrm;
  return new;
end;
$function$
;

