CREATE OR REPLACE FUNCTION public.be_rider_delivery_jobs(p_rider_email text DEFAULT NULL::text, p_pickup_way_id text DEFAULT NULL::text, p_delivery_way_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'ok', true,
    'count', count(*),
    'jobs', coalesce(jsonb_agg(to_jsonb(j) order by j.assigned_at desc nulls last, j.delivery_sequence asc), '[]'::jsonb)
  )
  from public.be_v_rider_delivery_jobs j
  where (p_rider_email is null or p_rider_email = '' or lower(coalesce(j.assigned_rider_email, '')) = lower(p_rider_email))
    and (p_pickup_way_id is null or p_pickup_way_id = '' or j.pickup_way_id = public.be_normalize_pickupway_id(p_pickup_way_id))
    and (p_delivery_way_id is null or p_delivery_way_id = '' or j.delivery_way_id = public.be_normalize_deliveryway_id(p_delivery_way_id));
$function$
;

CREATE OR REPLACE FUNCTION public.be_rider_delivery_page_healthcheck()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_total integer := 0;
  v_d_valid integer := 0;
  v_p_valid integer := 0;
  v_sample_pickup text;
  v_sample_delivery text;
  v_sample_waybill text;
  v_sample_invoice text;
  v_valid_waybill integer := 0;
  v_valid_invoice integer := 0;
  v_max_count integer;
begin
  select
    count(*)::integer,
    count(*) filter (where delivery_way_id ~ '^D[0-9]{4}-[A-Z0-9]+-[0-9]{3}$')::integer,
    count(distinct pickup_way_id) filter (where pickup_way_id ~ '^P[0-9]{4}-[A-Z0-9]+-[0-9]{3}$')::integer,
    count(*) filter (where waybill_no ~ '^WB[0-9]{4}-[A-Z0-9]+-[0-9]{3}$')::integer,
    count(*) filter (where invoice_no ~ '^INV[0-9]{4}-[A-Z0-9]+-[0-9]{3}$')::integer,
    min(pickup_way_id),
    min(delivery_way_id),
    min(waybill_no),
    min(invoice_no),
    max(delivery_count)::integer
  into v_total, v_d_valid, v_p_valid, v_valid_waybill, v_valid_invoice, v_sample_pickup, v_sample_delivery, v_sample_waybill, v_sample_invoice, v_max_count
  from public.be_v_rider_delivery_jobs;

  return jsonb_build_object(
    'ok', true,
    'view', 'public.be_v_rider_delivery_jobs',
    'pickupway_format', 'P0611-BRV-001',
    'deliveryway_format', 'D0611-BRV-001',
    'waybill_format', 'WB0611-BRV-001',
    'invoice_format', 'INV0611-BRV-001',
    'model', 'one pickup_way_id P... parent to many delivery_way_id D... lines; each D... line has WB... waybill and INV... invoice',
    'total_delivery_rows', v_total,
    'valid_deliveryway_rows', v_d_valid,
    'valid_waybill_rows', v_valid_waybill,
    'valid_invoice_rows', v_valid_invoice,
    'valid_parent_pickupway_count', v_p_valid,
    'sample_pickup_way_id', v_sample_pickup,
    'sample_delivery_way_id', v_sample_delivery,
    'sample_waybill_no', v_sample_waybill,
    'sample_invoice_no', v_sample_invoice,
    'max_delivery_count_seen', coalesce(v_max_count, 0),
    'message', case
      when v_total = 0 then 'Objects are installed, but no delivery rows are visible yet.'
      when v_total <> v_d_valid then 'Some rows still have invalid DeliveryWayID values.'
      when v_total <> v_valid_waybill then 'Some rows still have invalid WB-prefixed WaybillNo values.'
      when v_total <> v_valid_invoice then 'Some rows still have invalid INV-prefixed InvoiceNo values.'
      else 'DeliveryWayID, WaybillNo, and InvoiceNo bridge is ready. Delivery rows use D, WB, and INV prefixes.'
    end
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_rider_delivery_wayplan_jobs(p_rider_code text DEFAULT NULL::text, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_rows jsonb;
begin
  select coalesce(jsonb_agg(to_jsonb(x) order by x.stop_sequence asc), '[]'::jsonb)
  into v_rows
  from (
    select *
    from public.be_v_rider_delivery_wayplan_jobs
    where p_rider_code is null
       or rider_code = p_rider_code
    order by wayplan_created_at desc, stop_sequence asc
    limit greatest(coalesce(p_limit, 100), 1)
  ) x;

  return jsonb_build_object(
    'ok', true,
    'source', 'be_rider_delivery_wayplan_jobs',
    'rider_code', p_rider_code,
    'count', jsonb_array_length(v_rows),
    'jobs', v_rows
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_rider_email_from_code(p_code text, p_branch text DEFAULT 'YGN'::text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  v_code text := upper(trim(coalesce(p_code, '')));
  v_digits text := regexp_replace(v_code, '[^0-9]', '', 'g');
BEGIN
  IF v_code !~ '^RID[0-9]{3}$' THEN
    RETURN lower(v_code) || '@britiumexpress.com';
  END IF;
  RETURN 'rider_' || lower(coalesce(nullif(p_branch, ''), 'YGN')) || '_' || lpad(v_digits, 4, '0') || '@britiumventures.com';
END;
$function$
;

