CREATE OR REPLACE FUNCTION public.be_rider_live_map_healthcheck(p_actor_email text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'ok', true,
    'objects', jsonb_build_object(
      'be_rider_live_locations', to_regclass('public.be_rider_live_locations') is not null,
      'be_rider_location_events', to_regclass('public.be_rider_location_events') is not null,
      'be_v_rider_live_locations', to_regclass('public.be_v_rider_live_locations') is not null,
      'be_rider_update_live_location', to_regprocedure('public.be_rider_update_live_location(text,text,numeric,numeric,numeric,numeric,numeric,numeric,text)') is not null,
      'be_rider_live_map_snapshot', to_regprocedure('public.be_rider_live_map_snapshot(text,text,text)') is not null
    ),
    'counts', jsonb_build_object(
      'live_locations', (select count(*) from public.be_rider_live_locations),
      'events_today', (select count(*) from public.be_rider_location_events where captured_at::date = current_date)
    ),
    'sample', public.be_rider_live_map_snapshot(p_actor_email, null, null)
