;

CREATE OR REPLACE FUNCTION public.be_rider_live_map_snapshot(p_actor_email text DEFAULT NULL::text, p_wayplan_code text DEFAULT NULL::text, p_tracking_no text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor text := lower(nullif(trim(coalesce(p_actor_email,'')), ''));
  v_jobs jsonb := '[]'::jsonb;
  v_location jsonb := null;
  v_stats jsonb := '{}'::jsonb;
  v_has_delivery_view boolean := to_regclass('public.be_v_rider_delivery_jobs') is not null;
  v_has_dispatch_view boolean := to_regclass('public.be_v_rider_dispatch_jobs') is not null;
begin
  select to_jsonb(l)
    into v_location
  from public.be_v_rider_live_locations l
  where v_actor is null or lower(l.actor_email) = v_actor
  order by l.last_seen_at desc
  limit 1;

  if v_has_delivery_view then
    execute $q$
      select coalesce(jsonb_agg(to_jsonb(t) order by t.parcel_sequence nulls last, t.tracking_no), '[]'::jsonb)
      from (
        select *
        from public.be_v_rider_delivery_jobs j
        where ($1 is null or lower(coalesce(j.rider_email, j.driver_email, j.helper_email, '')) = $1
              or lower(coalesce(j.rider_email,'')) = $1
              or lower(coalesce(j.driver_email,'')) = $1
              or lower(coalesce(j.helper_email,'')) = $1)
          and ($2 is null or coalesce(j.wayplan_code, j.wayplan_no, j.wayplan_id) = $2)
          and ($3 is null or coalesce(j.tracking_no, j.delivery_way_id) = $3)
        order by j.parcel_sequence nulls last, j.tracking_no
        limit 250
      ) t
    $q$ into v_jobs using v_actor, nullif(p_wayplan_code,''), nullif(p_tracking_no,'');
  elsif v_has_dispatch_view then
    execute $q$
      select coalesce(jsonb_agg(to_jsonb(t) order by t.parcel_sequence nulls last, t.tracking_no), '[]'::jsonb)
      from (
        select *
        from public.be_v_rider_dispatch_jobs j
        where ($1 is null or lower(coalesce(j.rider_email, j.driver_email, j.helper_email, '')) = $1
              or lower(coalesce(j.rider_email,'')) = $1
              or lower(coalesce(j.driver_email,'')) = $1
              or lower(coalesce(j.helper_email,'')) = $1)
          and ($2 is null or coalesce(j.wayplan_code, j.wayplan_no, j.wayplan_id) = $2)
          and ($3 is null or coalesce(j.tracking_no, j.delivery_way_id) = $3)
        order by j.parcel_sequence nulls last, j.tracking_no
        limit 250
      ) t
    $q$ into v_jobs using v_actor, nullif(p_wayplan_code,''), nullif(p_tracking_no,'');
  end if;

  select jsonb_build_object(
    'total', count(*),
    'active', count(*) filter (where upper(coalesce(x.job->>'delivery_status', x.job->>'dispatch_status', '')) not in ('DELIVERED','RTO')),
    'out_for_delivery', count(*) filter (where upper(coalesce(x.job->>'delivery_status', x.job->>'dispatch_status', '')) = 'OUT_FOR_DELIVERY'),
    'delivered', count(*) filter (where upper(coalesce(x.job->>'delivery_status', x.job->>'dispatch_status', '')) = 'DELIVERED'),
    'failed', count(*) filter (where upper(coalesce(x.job->>'delivery_status', x.job->>'dispatch_status', '')) in ('FAILED','ATTEMPTED_FAILED','DELIVERY_FAILED')),
    'with_gps_points', count(*) filter (
      where coalesce(x.job->>'last_gps_lat', x.job->>'delivery_lat', x.job->>'recipient_lat', x.job->>'gps_lat') is not null
        and coalesce(x.job->>'last_gps_lng', x.job->>'delivery_lng', x.job->>'recipient_lng', x.job->>'gps_lng') is not null
    )
  )
  into v_stats
  from jsonb_array_elements(v_jobs) as x(job);

  return jsonb_build_object(
    'ok', true,
    'actor_email', v_actor,
    'rider_location', v_location,
    'jobs', v_jobs,
    'stats', v_stats,
    'objects', jsonb_build_object(
      'be_rider_live_locations', to_regclass('public.be_rider_live_locations') is not null,
      'be_v_rider_live_locations', to_regclass('public.be_v_rider_live_locations') is not null,
      'be_v_rider_delivery_jobs', v_has_delivery_view,
      'be_v_rider_dispatch_jobs', v_has_dispatch_view
    )
  );
end;
$function$
;

