CREATE OR REPLACE FUNCTION public.be_rider_parcel_verification_queue(p_pickup_id text)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
select jsonb_build_object(

  'ok',
  true,

  'pickup_id',
  p_pickup_id,

  'parcel_count',
  count(*),

  'verified_count',
  count(*) filter (
    where coalesce(v.verified,false)=true
       or upper(coalesce(v.status,''))='VERIFIED'
  ),

  'rows',
  coalesce(
    jsonb_agg(
      jsonb_build_object(

        'parcel_sequence',
          w.parcel_sequence,

        'delivery_way_id',
          w.delivery_way_id,

        'waybill_no',
          w.waybill_no,

        'tracking_no',
          w.tracking_no,

        'recipient_name',
          w.recipient_name,

        'recipient_phone',
          w.recipient_phone,

        'weight_kg',
          coalesce(v.actual_weight_kg,0),

        'proof_url',
          v.proof_url,

        'signature_url',
          v.signature_url,

        'verified',
          coalesce(v.verified,false),

        'status',
          coalesce(v.status,'PENDING')

      )
      order by w.parcel_sequence
    ),
    '[]'::jsonb
  )

)

from public.be_waybill_ledger w

left join public.be_rider_pickup_parcel_verifications v
  on v.pickup_id = p_pickup_id
 and v.parcel_sequence = w.parcel_sequence

where
  w.pickup_id = p_pickup_id
  or w.pickup_way_id = p_pickup_id;

$function$
;

CREATE OR REPLACE FUNCTION public.be_rider_pickup_action(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_action text;
  v_pickup_id text;
  v_rider_code text;
  v_rider_email text;
  v_actor_email text;
  v_proof_url text;
  v_actual_weight numeric;
  v_verified_count integer;
  v_updated integer := 0;
  v_next_status text;
  v_next_stage text;
begin
  v_action := upper(coalesce(
    p_payload->>'action',
    p_payload->>'rider_action',
    p_payload->>'next_action',
    ''
  ));

  v_pickup_id := nullif(coalesce(
    p_payload->>'pickup_way_id',
    p_payload->>'pickup_id',
    p_payload->>'request_code'
  ), '');

  v_rider_code := nullif(coalesce(
    p_payload->>'rider_code',
    p_payload->>'target_user_code',
    p_payload->>'workforce_code'
  ), '');

  v_rider_email := nullif(coalesce(
    p_payload->>'rider_email',
    p_payload->>'actor_email',
    p_payload->>'user_email'
  ), '');

  v_actor_email := coalesce(v_rider_email, p_payload->>'actor_email');

  v_proof_url := nullif(coalesce(
    p_payload->>'proof_url',
    p_payload->>'photo_url',
    p_payload->>'proof_photo_path',
    p_payload#>>'{proof,photo_url}'
  ), '');

  v_actual_weight := case
    when coalesce(p_payload->>'actual_weight_kg', p_payload->>'weight_kg', '') ~ '^[0-9]+(\.[0-9]+)?$'
      then coalesce(p_payload->>'actual_weight_kg', p_payload->>'weight_kg')::numeric
    else null
  end;

  v_verified_count := coalesce(
    nullif(p_payload->>'verified_count', '')::integer,
    nullif(p_payload->>'actual_parcel_count', '')::integer,
    nullif(p_payload->>'parcel_count', '')::integer,
    jsonb_array_length(coalesce(p_payload->'parcels', '[]'::jsonb)),
    0
  );

  if v_pickup_id is null then
    return jsonb_build_object('ok', false, 'error', 'pickup_id / pickup_way_id is required', 'payload', p_payload);
  end if;

  if v_action in ('ACCEPT', 'ACCEPT_PICKUP', 'ACCEPT_ASSIGNMENT') then
    v_next_status := 'ACCEPTED_BY_RIDER';
    v_next_stage := 'ACCEPTED_PICKUP';

    update public.be_portal_pickup_requests
    set
      pickup_status = 'ACCEPTED_BY_RIDER',
      workflow_stage = 'ACCEPTED_PICKUP',
      rider_app_stage = 'ACCEPTED_PICKUP',
      rider_status = 'ACCEPTED',
      status = 'ACCEPTED',
      supervisor_status = 'ASSIGNED',
      assignment_status = 'accepted',
      accepted_at = now(),
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
        'last_rider_payload', p_payload,
        'last_rider_action_at', now()
      ),
      updated_at = now()
    where pickup_way_id = v_pickup_id
       or pickup_id = v_pickup_id
       or request_code = v_pickup_id;

    get diagnostics v_updated = row_count;

    update public.be_app_notifications
    set
      is_read = true,
      read_at = now(),
      status = 'read'
    where target_role = 'rider'
      and notification_type = 'PICKUP_ASSIGNMENT'
      and (
           pickup_id = v_pickup_id
        or pickup_way_id = v_pickup_id
        or source_key = v_pickup_id
        or event_key ilike '%' || v_pickup_id || '%'
      );

  elsif v_action in ('VERIFY_PICKUP', 'PICKUP_VERIFY', 'PICKUP_VERIFIED', 'VERIFY') then
    v_next_status := 'PICKUP_VERIFIED';
    v_next_stage := 'PICKUP_VERIFIED';

    update public.be_portal_pickup_requests
    set
      pickup_status = 'PICKUP_VERIFIED',
      workflow_stage = 'PICKUP_VERIFIED',
      rider_app_stage = 'PICKUP_VERIFIED',
      rider_status = 'PICKUP_VERIFIED',
      status = 'PICKUP_VERIFIED',
      supervisor_status = 'ASSIGNED',
      warehouse_status = 'WAITING_DATA_ENTRY',
      data_entry_status = 'WAITING_DATA_ENTRY',
      assignment_status = 'pickup_verified',
      verified_parcels = greatest(coalesce(v_verified_count, 0), coalesce(verified_parcels, 0)),
      pickup_verified_at = now(),
      field_verified_at = now(),
      field_verified_by = coalesce(v_rider_code, v_rider_email),
      proof_url = coalesce(v_proof_url, proof_url),
      pickup_proof_url = coalesce(v_proof_url, pickup_proof_url),
      pickup_verified_total_weight = coalesce(v_actual_weight, pickup_verified_total_weight, total_weight_kg, 0),
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
        'last_rider_payload', p_payload,
        'last_rider_action_at', now()
      ),
      updated_at = now()
    where pickup_way_id = v_pickup_id
       or pickup_id = v_pickup_id
       or request_code = v_pickup_id;

    get diagnostics v_updated = row_count;

    insert into public.be_app_notifications (
      title,
      body,
      message,
      status,
      is_read,
      category,
      notification_type,
      event_type,
      event_key,
      source_key,
      source_table,
      pickup_id,
      pickup_way_id,
      target_role,
      metadata,
      payload,
      created_at
    )
    values (
      'Pickup verified for data entry',
      'Pickup ' || v_pickup_id || ' has been verified by rider and is ready for data entry.',
      'Pickup ' || v_pickup_id || ' has been verified by rider and is ready for data entry.',
      'unread',
      false,
      'data_entry',
      'PICKUP_VERIFIED_DATA_ENTRY',
      'pickup_verified',
      'workflow:data-entry:be_portal_pickup_requests:' || v_pickup_id,
      v_pickup_id,
      'be_portal_pickup_requests',
      v_pickup_id,
      v_pickup_id,
      'data_entry',
      jsonb_build_object(
        'source', 'be_rider_pickup_action',
        'pickup_id', v_pickup_id,
        'rider_code', v_rider_code,
        'next_action', 'DATA_ENTRY_REGISTER',
        'workflow_stage', 'WAITING_DATA_ENTRY',
        'verified_count', v_verified_count,
        'proof_url', v_proof_url,
        'actual_weight_kg', v_actual_weight
      ),
      jsonb_build_object(
        'pickup_id', v_pickup_id,
        'pickup_way_id', v_pickup_id,
        'next_action', 'DATA_ENTRY_REGISTER',
        'verified_count', v_verified_count,
        'proof_url', v_proof_url,
        'actual_weight_kg', v_actual_weight
      ),
      now()
    )
    on conflict (event_key) do update
    set
      status = 'unread',
      is_read = false,
      notification_type = 'PICKUP_VERIFIED_DATA_ENTRY',
      metadata = coalesce(public.be_app_notifications.metadata, '{}'::jsonb) || excluded.metadata,
      payload = coalesce(public.be_app_notifications.payload, '{}'::jsonb) || excluded.payload;

  elsif v_action in ('COLLECT', 'PICKUP_COLLECTED', 'COLLECTED') then
    v_next_status := 'PICKUP_COLLECTED';
    v_next_stage := 'PICKUP_COLLECTED';

    update public.be_portal_pickup_requests
    set
      pickup_status = 'PICKUP_COLLECTED',
      workflow_stage = 'PICKUP_COLLECTED',
      rider_app_stage = 'PICKUP_COLLECTED',
      rider_status = 'PICKUP_COLLECTED',
      status = 'PICKUP_COLLECTED',
      warehouse_status = 'IN_TRANSIT_TO_WAREHOUSE',
      assignment_status = 'collected',
      pickup_collected_at = now(),
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
        'last_rider_payload', p_payload,
        'last_rider_action_at', now()
      ),
      updated_at = now()
    where pickup_way_id = v_pickup_id
       or pickup_id = v_pickup_id
       or request_code = v_pickup_id;

    get diagnostics v_updated = row_count;

  else
    return jsonb_build_object(
      'ok', false,
      'error', 'Unsupported rider action',
      'action', v_action,
      'pickup_id', v_pickup_id,
      'supported_actions', jsonb_build_array('ACCEPT_PICKUP', 'PICKUP_VERIFY', 'PICKUP_COLLECTED')
    );
  end if;

  return jsonb_build_object(
    'ok', v_updated > 0,
    'source', 'be_rider_pickup_action',
    'action', v_action,
    'pickup_id', v_pickup_id,
    'rider_code', v_rider_code,
    'updated_rows', v_updated,
    'next_status', v_next_status,
    'next_stage', v_next_stage
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_rider_pickup_queue(p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'ok', true,
    'source', 'be_v_rider_pickup_queue',
    'rider_code', coalesce(nullif(p_payload ->> 'rider_code', ''), nullif(p_payload ->> 'rider_id', ''), nullif(p_payload ->> 'login', ''), 'RID001'),
    'jobs', coalesce(jsonb_agg(to_jsonb(q) order by q.updated_at desc), '[]'::jsonb),
    'pickups', coalesce(jsonb_agg(to_jsonb(q) order by q.updated_at desc), '[]'::jsonb),
    'data', coalesce(jsonb_agg(to_jsonb(q) order by q.updated_at desc), '[]'::jsonb)
  )
  from public.be_v_rider_pickup_queue q
  where q.rider_code = coalesce(nullif(p_payload ->> 'rider_code', ''), nullif(p_payload ->> 'rider_id', ''), nullif(p_payload ->> 'login', ''), 'RID001');
$function$
;

CREATE OR REPLACE FUNCTION public.be_rider_route_job_update(p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_action text := upper(coalesce(p_payload->>'action', ''));
  v_target_id text := nullif(coalesce(
    p_payload->>'delivery_way_id',
    p_payload->>'waybill_no',
    p_payload->>'tracking_no',
    p_payload->>'id'
  ), '');
  v_actor text := nullif(p_payload->>'actor_email', '');
  v_status text;
  v_cod_amount numeric := 0;
  v_failed_reason text := nullif(p_payload->>'failed_reason', '');
  v_updated integer := 0;
begin
  if v_action = '' then
    raise exception 'action is required';
  end if;

  if v_target_id is null then
    raise exception 'delivery_way_id, waybill_no, tracking_no, or id is required';
  end if;

  if coalesce(p_payload->>'cod_amount', '') ~ '^[0-9]+(\.[0-9]+)?$' then
    v_cod_amount := (p_payload->>'cod_amount')::numeric;
  elsif coalesce(p_payload->>'amount_collected', '') ~ '^[0-9]+(\.[0-9]+)?$' then
    v_cod_amount := (p_payload->>'amount_collected')::numeric;
  end if;

  v_status := case v_action
    when 'START_DELIVERY' then 'OUT_FOR_DELIVERY'
    when 'ARRIVED' then 'ARRIVED_AT_DESTINATION'
    when 'COLLECT_COD' then 'COD_COLLECTED'
    when 'DELIVERED' then 'DELIVERED'
    when 'FAILED' then 'FAILED'
    when 'RETURNED' then 'RETURNED'
    else v_action
  end;

  update public.be_wayplan_dispatch_stops
  set
    dispatch_status = v_status,
    stop_status = v_status,
    rider_status = v_status,
    rider_action_at = now(),

    cod_collected = case
      when v_action in ('COLLECT_COD','DELIVERED') then greatest(v_cod_amount, coalesce(cod_amount, amount_to_collect, cod_collected, 0))
      else coalesce(cod_collected, 0)
    end,
    cod_collected_at = case
      when v_action in ('COLLECT_COD','DELIVERED') then now()
      else cod_collected_at
    end,
    cod_collected_by = case
      when v_action in ('COLLECT_COD','DELIVERED') then v_actor
      else cod_collected_by
    end,
    finance_status = case
      when v_action in ('COLLECT_COD','DELIVERED') and greatest(v_cod_amount, coalesce(cod_amount, amount_to_collect, cod_collected, 0)) > 0
        then 'COD_PENDING_SETTLEMENT'
      when v_action = 'DELIVERED'
        then coalesce(finance_status, 'NO_COD')
      else finance_status
    end,

    delivered_at = case
      when v_action = 'DELIVERED' then now()
      else delivered_at
    end,
    failed_reason = case
      when v_action in ('FAILED','RETURNED') then coalesce(v_failed_reason, failed_reason, 'Rider marked ' || v_action)
      else failed_reason
    end,
    updated_at = now()
  where id::text = v_target_id
     or delivery_way_id = v_target_id
     or waybill_no = v_target_id
     or tracking_no = v_target_id;

  get diagnostics v_updated = row_count;

  perform public.be_write_governance_audit(
    'RIDER_APP',
    v_action,
    'be_wayplan_dispatch_stops',
    v_target_id,
    v_actor,
    '{}'::jsonb,
    jsonb_build_object(
      'target_id', v_target_id,
      'status', v_status,
      'cod_amount', v_cod_amount,
      'updated_rows', v_updated,
      'payload', p_payload
    ),
    jsonb_build_object('source', 'be_rider_route_job_update')
  );

  return jsonb_build_object(
    'ok', true,
    'source', 'be_rider_route_job_update',
    'action', v_action,
    'target_id', v_target_id,
    'status', v_status,
    'cod_amount', v_cod_amount,
    'updated_rows', v_updated
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_rider_route_jobs(p_actor_email text DEFAULT NULL::text, p_limit integer DEFAULT 200)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_email text := nullif(p_actor_email, '');
  v_jobs jsonb := '[]'::jsonb;
  v_summary jsonb := '{}'::jsonb;
begin
  select coalesce(jsonb_agg(to_jsonb(t)), '[]'::jsonb)
  into v_jobs
  from (
    select
      id,
      pickup_id,
      pickup_way_id,
      delivery_way_id,
      waybill_no,
      invoice_no,
      tracking_no,

      coalesce(assigned_to, rider_email, rider_code) as rider_email,
      rider_name,
      rider_code,

      route_code,
      optimized_sequence,

      coalesce(dispatch_status, stop_status, warehouse_status, 'PENDING') as job_status,
      coalesce(warehouse_status, stop_status, dispatch_status, 'PENDING') as warehouse_status,

      township,
      delivery_township,
      recipient_township,

      cod_amount,
      amount_to_collect,

      coalesce(recipient_name, receiver_name, 'Customer') as recipient_name,
      coalesce(recipient_phone, receiver_phone, '') as recipient_phone,
      coalesce(delivery_address, address, '') as delivery_address,

      created_at,
      updated_at
    from public.be_wayplan_dispatch_stops
    where (
      v_email is null
      or coalesce(assigned_to, rider_email, rider_code, '') = v_email
    )
    and upper(coalesce(dispatch_status, stop_status, warehouse_status, '')) not in (
      'CANCELLED',
      'FAILED',
      'RETURNED'
    )
    order by
      route_code desc nulls last,
      optimized_sequence asc nulls last,
      delivery_sequence asc nulls last,
      stop_sequence asc nulls last,
      delivery_way_id asc nulls last
    limit greatest(coalesce(p_limit, 200), 1)
  ) t;

  select jsonb_build_object(
    'total_jobs', coalesce(jsonb_array_length(v_jobs), 0),
    'assigned_jobs', (
      select count(*)
      from jsonb_array_elements(v_jobs) j
      where coalesce(j->>'rider_email', '') <> ''
    ),
    'optimized_jobs', (
      select count(*)
      from jsonb_array_elements(v_jobs) j
      where coalesce(j->>'route_code', '') <> ''
    ),
    'pending_jobs', (
      select count(*)
      from jsonb_array_elements(v_jobs) j
      where upper(coalesce(j->>'job_status', '')) in (
        'PENDING',
        'ASSIGNED',
        'ROUTE_OPTIMIZED',
        'READY_FOR_DISPATCH',
        'OUT_FOR_DELIVERY'
      )
    )
  )
  into v_summary;

  return jsonb_build_object(
    'ok', true,
    'source', 'be_rider_route_jobs',
    'actor_email', v_email,
    'generated_at', now(),
    'summary', v_summary,
    'jobs', v_jobs
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_rider_save_parcel_proof(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ select public.be_rider_pickup_action(coalesce(p_payload, '{}'::jsonb) || jsonb_build_object('action', 'verify_pickup')); $function$
;

CREATE OR REPLACE FUNCTION public.be_rider_save_pickup_parcel_verifications(p_pickup_id text, p_rider_login text, p_parcels jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_pickup_id text := trim(coalesce(p_pickup_id, ''));
  v_rider_login text := trim(coalesce(p_rider_login, ''));
  v_count integer := 0;
BEGIN
  IF v_pickup_id = '' THEN
    RAISE EXCEPTION 'pickup_id is required';
  END IF;

  DELETE FROM public.be_rider_pickup_parcel_verifications
  WHERE pickup_id = v_pickup_id;

  INSERT INTO public.be_rider_pickup_parcel_verifications (
    pickup_id,
    rider_login,
    rider_code,
    parcel_id,
    parcel_sequence,
    actual_weight_kg,
    proof_url,
    proof_file_name,
    remarks,
    verified,
    payload
  )
  SELECT
    v_pickup_id,
    v_rider_login,
    upper(v_rider_login),
    coalesce(x->>'parcel_id', x->>'parcelId', v_pickup_id || '-' || lpad((row_number() over ())::text, 3, '0')),
    coalesce((x->>'parcel_sequence')::integer, (x->>'index')::integer, row_number() over ()),
    nullif(x->>'actual_weight_kg', '')::numeric,
    nullif(x->>'proof_url', ''),
    nullif(x->>'proof_file_name', ''),
    nullif(x->>'remarks', ''),
    coalesce((x->>'verified')::boolean, true),
    x
  FROM jsonb_array_elements(coalesce(p_parcels, '[]'::jsonb)) x;

  GET DIAGNOSTICS v_count = ROW_COUNT;

  UPDATE public.be_portal_pickup_requests
  SET
    pickup_status = 'PICKUP_VERIFIED',
    rider_status = 'PICKUP_VERIFIED',
    workflow_stage = 'PICKUP_VERIFIED',
    rider_last_action = 'PICKUP_VERIFIED',
    rider_last_action_at = now(),
    pickup_verified_at = coalesce(pickup_verified_at, now()),
    proof_url = coalesce(
      proof_url,
      'parcel-batch:' || v_pickup_id
    ),
    updated_at = now()
  WHERE
    pickup_id = v_pickup_id
    OR canonical_pickup_id = v_pickup_id
    OR pickup_way_id = v_pickup_id;

  RETURN jsonb_build_object(
    'ok', true,
    'pickup_id', v_pickup_id,
    'saved_parcels', v_count,
    'pickup_status', 'PICKUP_VERIFIED'
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_rider_save_pickup_parcel_verifications(p_pickup_id text, p_rider_login text, p_parcels jsonb, p_remark text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_item jsonb;
  v_count integer := 0;
begin
  if coalesce(trim(p_pickup_id), '') = '' then
    raise exception 'pickup_id is required';
  end if;

  if jsonb_typeof(coalesce(p_parcels, '[]'::jsonb)) <> 'array' then
    raise exception 'p_parcels must be a jsonb array';
  end if;

  for v_item in select * from jsonb_array_elements(coalesce(p_parcels, '[]'::jsonb)) loop
    insert into public.be_rider_parcel_verifications (
      pickup_id,
      waybill_id,
      rider_login,
      actual_weight_kg,
      photo_proof,
      photo_name,
      remark,
      status,
      metadata,
      updated_at
    ) values (
      p_pickup_id,
      coalesce(v_item ->> 'waybill_id', v_item ->> 'id'),
      p_rider_login,
      nullif(v_item ->> 'actual_weight_kg', '')::numeric,
      v_item ->> 'photo_proof',
      v_item ->> 'photo_name',
      coalesce(v_item ->> 'remark', p_remark),
      coalesce(v_item ->> 'status', 'VERIFIED'),
      v_item,
      now()
    )
    on conflict do nothing;

    v_count := v_count + 1;
  end loop;

  insert into public.be_portal_cargo_events (
    pickup_id,
    source_table,
    source_key,
    event_type,
    event_status,
    event_note,
    actor_type,
    actor_code,
    metadata
  ) values (
    p_pickup_id,
    'be_rider_parcel_verifications',
    p_pickup_id,
    'PICKUP_PARCELS_VERIFIED',
    'PICKUP_VERIFIED',
    coalesce(p_remark, 'Rider saved parcel-level pickup verification.'),
    'rider',
    p_rider_login,
    jsonb_build_object('parcel_count', v_count, 'parcels', p_parcels)
  );

  return jsonb_build_object('ok', true, 'pickup_id', p_pickup_id, 'parcel_count', v_count);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_rider_settlement_snapshot(p_rider_email text DEFAULT NULL::text, p_work_date date DEFAULT CURRENT_DATE)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_work_date date := coalesce(p_work_date, current_date);
  v_base jsonb;
  v_rows jsonb;
  v_stats jsonb;
begin
  v_base := public.be_commission_settlement_snapshot(v_work_date, p_rider_email, true);

  select coalesce(jsonb_agg(to_jsonb(s) order by s.assignee_email, s.operation_type), '[]'::jsonb)
  into v_rows
  from public.be_v_commission_settlement s
  where s.work_date = v_work_date
    and s.role_code = 'RIDER'
    and (p_rider_email is null or s.assignee_email = p_rider_email);

  select jsonb_build_object(
    'work_date', v_work_date,
    'rider_email', p_rider_email,
    'pickup_units', coalesce(sum(total_units) filter (where operation_type = 'PICKUP'),0),
    'delivery_units', coalesce(sum(total_units) filter (where operation_type = 'DELIVERY'),0),
    'highway_bags', coalesce(sum(total_units) filter (where operation_type = 'HIGHWAY_DROPOFF'),0),
    'pickup_commission', coalesce(sum(commission_mmk) filter (where operation_type = 'PICKUP'),0),
    'delivery_commission', coalesce(sum(commission_mmk) filter (where operation_type = 'DELIVERY'),0),
    'highway_dropoff_commission', coalesce(sum(commission_mmk) filter (where operation_type = 'HIGHWAY_DROPOFF'),0),
    'total_commission', coalesce(sum(commission_mmk),0),
    'jobs', coalesce(sum(event_rows),0)
  )
  into v_stats
  from public.be_v_commission_settlement s
  where s.work_date = v_work_date
    and s.role_code = 'RIDER'
    and (p_rider_email is null or s.assignee_email = p_rider_email);

  return jsonb_build_object('ok', true, 'stats', v_stats, 'rows', v_rows, 'rates', v_base -> 'rates');
end;
$function$
;

