CREATE OR REPLACE FUNCTION public.be_rider_submit_cod_settlement(p_pickup_id text DEFAULT NULL::text, p_rider_email text DEFAULT NULL::text, p_cod_amount numeric DEFAULT 0, p_remark text DEFAULT NULL::text, p_pickup_way_id text DEFAULT NULL::text, p_rider_code text DEFAULT NULL::text, p_delivery_way_id text DEFAULT NULL::text, p_waybill_no text DEFAULT NULL::text, p_invoice_no text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_delivery_way_id text := coalesce(
    public.be_normalize_deliveryway_id(p_delivery_way_id),
    public.be_normalize_deliveryway_id(p_pickup_id),
    public.be_deliveryway_id_from_waybill_no(p_waybill_no),
    public.be_deliveryway_id_from_invoice_no(p_invoice_no)
  );
  v_pickup_way_id text := coalesce(public.be_normalize_pickupway_id(p_pickup_way_id), public.be_normalize_pickupway_id(p_pickup_id));
begin
  if v_pickup_way_id is null and v_delivery_way_id is not null then
    select pickup_way_id into v_pickup_way_id
    from public.be_v_rider_delivery_jobs
    where delivery_way_id = v_delivery_way_id
    limit 1;
  end if;

  if v_pickup_way_id is null then
    raise exception 'Valid PickupWayID is required for COD settlement.';
  end if;

  return public.be_rider_update_pickup_status(
    v_pickup_way_id,
    p_rider_email,
    p_rider_code,
    'COD_SUBMITTED',
    null,
    null,
    jsonb_build_object(
      'delivery_way_id', v_delivery_way_id,
      'tracking_no', v_delivery_way_id,
      'waybill_no', public.be_make_waybill_no(v_delivery_way_id),
      'invoice_no', public.be_make_invoice_no(v_delivery_way_id),
      'cod_collected_amount', coalesce(p_cod_amount, 0),
      'cod_settlement_status', 'SUBMITTED_TO_FINANCE',
      'cod_handover_submitted_at', now(),
      'remark', p_remark
    )
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_rider_submit_delivery_exception(p_pickup_id text, p_rider_email text, p_exception_reason text, p_remark text DEFAULT NULL::text, p_proof_url text DEFAULT NULL::text)
