CREATE OR REPLACE FUNCTION public.be_rider_submit_partial_pickup_verification(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_pickup text := coalesce(p_payload->>'pickup_id', p_payload->>'pickup_way_id');
  v_expected integer := greatest(1, coalesce(nullif(p_payload->>'parcel_count', '')::integer, 1));
  v_submitted integer := greatest(0, coalesce(nullif(p_payload->>'submitted_count', '')::integer, 0));
  v_verified integer := greatest(0, coalesce(nullif(p_payload->>'verified_count', '')::integer, 0));
  v_rejected integer := greatest(0, coalesce(nullif(p_payload->>'rejected_count', '')::integer, 0));
  v_stage text;
begin
  if nullif(v_pickup, '') is null then
    return jsonb_build_object('ok', false, 'error', 'pickup_id is required');
  end if;

  v_stage := case
    when v_verified >= v_expected then 'PICKUP_VERIFIED'
    else 'PARTIAL_PICKUP_VERIFICATION'
  end;

  update public.be_portal_pickup_requests
  set expected_parcel_count = v_expected,
      registered_parcel_count = v_verified,
      rejected_photo_count = v_rejected,
      pending_photo_count = greatest(0, v_expected - v_verified - v_rejected),
      photo_review_status = case
        when v_rejected > 0 then 'REUPLOAD_REQUIRED'
        when v_verified >= v_expected then 'APPROVED'
        else 'PARTIAL_REVIEW'
      end,
      pickup_status = case when v_verified >= v_expected then 'PICKUP_VERIFIED' else pickup_status end,
      workflow_stage = v_stage,
      rider_status = case when v_verified >= v_expected then 'PICKUP_VERIFIED' else 'PARTIAL_VERIFICATION_SAVED' end,
      data_entry_status = case when v_verified > 0 then 'PARTIAL_DATA_ENTRY_READY' else data_entry_status end,
      updated_at = now()
  where pickup_way_id = v_pickup;

  return jsonb_build_object(
    'ok', true,
    'source', 'be_rider_submit_partial_pickup_verification',
    'pickup_id', v_pickup,
    'expected_count', v_expected,
    'submitted_count', v_submitted,
    'verified_count', v_verified,
    'rejected_count', v_rejected,
    'workflow_stage', v_stage,
    'partial', v_verified < v_expected
  );
end $function$
;

CREATE OR REPLACE FUNCTION public.be_rider_submit_pickup_verification(p_pickup_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_total integer := 0;
  v_verified integer := 0;
  v_total_weight numeric := 0;
begin
  select
    count(*),
    count(*) filter (
      where coalesce(proof_url, photo_url, '') <> ''
    ),
    coalesce(sum(coalesce(actual_weight_kg, 0)), 0)
  into v_total, v_verified, v_total_weight
  from public.be_portal_pickup_request_items
  where pickup_id = p_pickup_id;

  if v_total = 0 then
    raise exception 'No parcel rows found for pickup %', p_pickup_id;
  end if;

  if v_verified < v_total then
    raise exception 'Only % of % parcels have photo proof. Please attach/capture all photos before submit.', v_verified, v_total;
  end if;

  update public.be_portal_pickup_requests
  set
    pickup_status = 'PICKUP_VERIFIED',
    rider_status = 'PICKUP_VERIFIED',
    workflow_stage = 'PICKUP_VERIFIED',
    verified_parcels = v_verified,
    total_weight_kg = v_total_weight,
    pickup_verified_at = now(),
    updated_at = now()
  where pickup_id = p_pickup_id
     or pickup_way_id = p_pickup_id;

  update public.be_portal_pickup_request_items
  set
    delivery_status = 'PICKUP_VERIFIED',
    proof_status = 'VERIFIED',
    updated_at = now()
  where pickup_id = p_pickup_id;

  return jsonb_build_object(
    'ok', true,
    'pickup_id', p_pickup_id,
    'verified_parcels', v_verified,
    'delivery_count', v_total,
    'total_weight_kg', v_total_weight,
    'message', 'Pickup verification submitted successfully. Data Entry can now check the photos.'
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_rider_update_job_status(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare pid text := coalesce(p_payload->>'pickup_id',p_payload->>'pickup_way_id'); st text := lower(coalesce(p_payload->>'status',p_payload->>'job_status','updated')); worker text := public.be30_clean(coalesce(p_payload->>'rider_code',p_payload->>'worker_code')); mapped text; r record;
begin
  select * into r from public.be_portal_pickup_requests where pickup_id=pid or pickup_way_id=pid limit 1;
  if not found then raise exception 'Pickup % not found',pid; end if;
  mapped := case when st in ('accepted','accept') then 'accepted' when st in ('picked_up','pickup_completed') then 'picked_up' when st in ('delivered','completed','complete') then 'delivered' when st in ('failed','failed_attempt') then 'failed_attempt' else st end;
  update public.be_portal_pickup_requests set status=mapped,rider_status=mapped,cod_status=case when mapped='delivered' and coalesce(cod_amount,0)>0 then 'awaiting_handover' else cod_status end,finance_status=case when mapped='delivered' and coalesce(cod_amount,0)>0 then 'cod_pending_handover' when mapped='delivered' then 'finance_pending' else finance_status end,updated_at=now() where id=r.id;
  update public.be_mobile_workflow_tasks set status=mapped,payload=coalesce(payload,'{}'::jsonb)||p_payload,updated_at=now() where pickup_id=r.pickup_id and (worker is null or assignee_code=worker);
  if mapped='delivered' and coalesce(r.cod_amount,0)>0 then update public.be_cod_ledger set rider_code=coalesce(worker,rider_code),cod_collected=coalesce(r.cod_amount,0),status='awaiting_handover',updated_at=now() where pickup_id=r.pickup_id; end if;
  perform public.be30_event(r.pickup_id,'rider_status_update',mapped,'rider',worker,p_payload);
  perform public.be30_notify('customer_service',r.assigned_branch,r.pickup_id,'Delivery status update',r.pickup_id||' status: '||mapped,p_payload);
  return jsonb_build_object('ok',true,'pickup_id',r.pickup_id,'status',mapped);
end; $function$
;

CREATE OR REPLACE FUNCTION public.be_rider_update_job_status(p_pickup_id text, p_rider_code text DEFAULT NULL::text, p_rider_email text DEFAULT NULL::text, p_action text DEFAULT 'UPDATED'::text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_pickup_key text := trim(coalesce(p_pickup_id, ''));
  v_action text := upper(trim(coalesce(p_action, 'UPDATED')));
  v_rider_code text := coalesce(public.be_rider_code_from_login(p_rider_code), public.be_rider_code_from_login(p_rider_email), upper(nullif(p_rider_code, '')));
  v_rider_email text := nullif(p_rider_email, '');
  v_row record;
  v_pickup_status text;
  v_rider_status text;
  v_workflow_stage text;
  v_note text;
  v_reason text;
  v_proof text;
  v_cod_required numeric := 0;
  v_cod_collected numeric := 0;
BEGIN
  IF v_pickup_key = '' THEN RAISE EXCEPTION 'Pickup ID is required'; END IF;

  SELECT * INTO v_row
  FROM public.be_portal_pickup_requests p
  WHERE upper(coalesce(p.pickup_id, '')) = upper(v_pickup_key)
     OR upper(coalesce(p.canonical_pickup_id, '')) = upper(v_pickup_key)
     OR upper(coalesce(p.pickup_way_id, '')) = upper(v_pickup_key)
     OR upper(coalesce(p.pickup_request_id, '')) = upper(v_pickup_key)
     OR upper(coalesce(p.pickup_waybill_id, '')) = upper(v_pickup_key)
     OR upper(coalesce(p.waybill_no, '')) = upper(v_pickup_key)
     OR upper(coalesce(p.tracking_no, '')) = upper(v_pickup_key)
     OR p.id::text = v_pickup_key
  LIMIT 1
  FOR UPDATE;

  IF NOT FOUND THEN RAISE EXCEPTION 'Pickup % not found in be_portal_pickup_requests', v_pickup_key; END IF;

  v_rider_code := coalesce(v_rider_code, v_row.assigned_rider_code, v_row.assigned_workforce_code, v_row.rider_code, v_row.rider_id);
  v_rider_email := coalesce(v_rider_email, v_row.assigned_rider_email, public.be_rider_email_from_code(v_rider_code, coalesce(v_row.branch_code, 'YGN')));
  v_reason := nullif(coalesce(p_payload->>'exception_reason', p_payload->>'exceptionReason', p_payload->>'reason', p_payload->>'remark'), '');
  v_proof := nullif(coalesce(p_payload->>'proof_url', p_payload->>'proofUrl', p_payload->>'photoProof', p_payload->>'photo', p_payload->>'proof_photo'), '');
  v_cod_required := coalesce(v_row.rider_cod_amount, v_row.cod_amount, v_row.item_price, 0);

  BEGIN
    v_cod_collected := coalesce(
      nullif(p_payload->>'cod_collected_amount', '')::numeric,
      nullif(p_payload->>'codCollectedAmount', '')::numeric,
      nullif(p_payload->>'cod_amount', '')::numeric,
      0
    );
  EXCEPTION WHEN others THEN
    v_cod_collected := 0;
  END;

  IF v_action IN ('ACCEPT', 'ACCEPTED') THEN
    v_action := 'ACCEPTED';
    v_pickup_status := coalesce(v_row.pickup_status, 'PICKUP_ASSIGNED');
    v_rider_status := 'ACCEPTED';
    v_workflow_stage := 'RIDER_ACCEPTED';
    v_note := 'Rider accepted assignment';
  ELSIF v_action IN ('ARRIVED', 'ARRIVED_MERCHANT', 'ARRIVED_AT_PICKUP') THEN
    v_action := 'ARRIVED_MERCHANT';
    v_pickup_status := 'ARRIVED_MERCHANT';
    v_rider_status := 'ARRIVED_MERCHANT';
    v_workflow_stage := 'ARRIVED_MERCHANT';
    v_note := 'Rider arrived at pickup location';
  ELSIF v_action IN ('VERIFY_PICKUP', 'PICKUP_VERIFIED') THEN
    v_action := 'PICKUP_VERIFIED';
    v_pickup_status := 'PICKUP_VERIFIED';
    v_rider_status := 'PICKUP_VERIFIED';
    v_workflow_stage := 'PICKUP_VERIFIED';
    v_note := 'Pickup verified by rider';
  ELSIF v_action IN ('PICKUP_COLLECTED', 'COLLECTED', 'PICKUP_COMPLETED') THEN
    v_action := 'PICKUP_COLLECTED';
    v_pickup_status := 'PICKUP_COLLECTED';
    v_rider_status := 'PICKUP_COLLECTED';
    v_workflow_stage := 'DELIVERY_READY';
    v_note := 'Pickup collected by rider';
  ELSIF v_action IN ('START_DELIVERY', 'OUT_FOR_DELIVERY') THEN
    v_action := 'OUT_FOR_DELIVERY';
    v_pickup_status := 'OUT_FOR_DELIVERY';
    v_rider_status := 'OUT_FOR_DELIVERY';
    v_workflow_stage := 'OUT_FOR_DELIVERY';
    v_note := 'Rider started delivery';
  ELSIF v_action IN ('VERIFY_DELIVERY', 'DELIVERY_VERIFIED', 'DELIVERED') THEN
    IF v_cod_required > 0 AND v_cod_collected < v_cod_required THEN
      RAISE EXCEPTION 'COD collection is required before delivery. Required %, collected %', v_cod_required, v_cod_collected;
    END IF;
    v_action := 'DELIVERED';
    v_pickup_status := 'DELIVERED';
    v_rider_status := 'DELIVERED';
    v_workflow_stage := 'DELIVERED';
    v_note := 'Delivery verified by rider';
  ELSIF v_action IN ('EXCEPTION', 'DELIVERY_EXCEPTION', 'DELIVERY_FAILED', 'PICKUP_EXCEPTION', 'PICKUP_FAILED') THEN
    IF v_reason IS NULL THEN RAISE EXCEPTION 'Exception reason is required'; END IF;
    IF v_proof IS NULL THEN RAISE EXCEPTION 'Proof photo or proof URL is required for exception'; END IF;
    IF v_action IN ('PICKUP_EXCEPTION', 'PICKUP_FAILED') THEN
      v_action := 'PICKUP_FAILED';
      v_pickup_status := 'PICKUP_FAILED';
      v_rider_status := 'PICKUP_EXCEPTION';
      v_workflow_stage := 'PICKUP_EXCEPTION';
      v_note := 'Pickup exception logged by rider';
    ELSE
      v_action := 'DELIVERY_FAILED';
      v_pickup_status := 'DELIVERY_FAILED';
      v_rider_status := 'DELIVERY_EXCEPTION';
      v_workflow_stage := 'DELIVERY_EXCEPTION';
      v_note := 'Delivery exception logged by rider';
    END IF;
  ELSE
    RAISE EXCEPTION 'Unsupported rider action: %', v_action;
  END IF;

  UPDATE public.be_portal_pickup_requests p
     SET pickup_status = v_pickup_status,
         status = v_pickup_status,
         rider_status = v_rider_status,
         workflow_stage = v_workflow_stage,
         rider_app_stage = v_workflow_stage,
         rider_last_action = v_action,
         rider_last_action_at = v_now,
         pickup_verified_at = CASE WHEN v_action = 'PICKUP_VERIFIED' THEN v_now ELSE p.pickup_verified_at END,
         pickup_collected_at = CASE WHEN v_action = 'PICKUP_COLLECTED' THEN v_now ELSE p.pickup_collected_at END,
         out_for_delivery_at = CASE WHEN v_action = 'OUT_FOR_DELIVERY' THEN v_now ELSE p.out_for_delivery_at END,
         delivery_verified_at = CASE WHEN v_action = 'DELIVERED' THEN v_now ELSE p.delivery_verified_at END,
         delivered_at = CASE WHEN v_action = 'DELIVERED' THEN v_now ELSE p.delivered_at END,
         exception_at = CASE WHEN v_action IN ('PICKUP_FAILED', 'DELIVERY_FAILED') THEN v_now ELSE p.exception_at END,
         exception_reason = CASE WHEN v_action IN ('PICKUP_FAILED', 'DELIVERY_FAILED') THEN v_reason ELSE p.exception_reason END,
         proof_url = coalesce(v_proof, p.proof_url),
         recipient_name = coalesce(nullif(p_payload->>'recipient_name', ''), nullif(p_payload->>'recipientName', ''), p.recipient_name),
         recipient_phone = coalesce(nullif(p_payload->>'recipient_phone', ''), nullif(p_payload->>'recipientPhone', ''), p.recipient_phone),
         cod_collected_amount = CASE WHEN v_action = 'DELIVERED' THEN v_cod_collected ELSE p.cod_collected_amount END,
         cod_collected_at = CASE WHEN v_action = 'DELIVERED' AND v_cod_collected > 0 THEN v_now ELSE p.cod_collected_at END,
         rider_cod_settlement_status = CASE WHEN v_action = 'DELIVERED' AND v_cod_required > 0 THEN 'PENDING_FINANCE_SETTLEMENT' ELSE p.rider_cod_settlement_status END,
         updated_at = v_now,
         metadata = coalesce(p.metadata, '{}'::jsonb) || jsonb_build_object('last_rider_payload', coalesce(p_payload, '{}'::jsonb), 'last_rider_action_at', v_now)
   WHERE p.id = v_row.id;

  INSERT INTO public.be_portal_cargo_events (
    pickup_id, source_table, source_key, event_name, event_type, event_status, status,
    event_note, notes, actor_type, actor_role, actor_code, actor_email, branch_code, proof_url, metadata, created_at
  ) VALUES (
    coalesce(v_row.pickup_id, v_pickup_key), 'be_portal_pickup_requests', coalesce(v_row.pickup_id, v_pickup_key),
    v_action, v_action, v_pickup_status, v_pickup_status,
    v_note, v_note,
    'rider', 'rider', v_rider_code, v_rider_email, coalesce(v_row.branch_code, 'YGN'), v_proof,
    jsonb_build_object('pickup_id', coalesce(v_row.pickup_id, v_pickup_key), 'rider_code', v_rider_code, 'rider_email', v_rider_email, 'action', v_action, 'payload', coalesce(p_payload, '{}'::jsonb)),
    v_now
  );

  INSERT INTO public.be_app_notifications (
    notification_type, title, body, message, target_role, target_branch,
    source_table, source_key, pickup_id, is_read, metadata, created_at
  )
  SELECT
    v_action,
    'Rider update: ' || v_action,
    'Pickup ' || coalesce(v_row.pickup_id, v_pickup_key) || ' updated by ' || coalesce(v_rider_code, 'rider') || '.',
    'Pickup ' || coalesce(v_row.pickup_id, v_pickup_key) || ' updated by ' || coalesce(v_rider_code, 'rider') || '.',
    role_name,
    CASE WHEN role_name = 'branch_office' THEN coalesce(v_row.branch_code, 'YGN') ELSE NULL END,
    'be_portal_pickup_requests', coalesce(v_row.pickup_id, v_pickup_key), coalesce(v_row.pickup_id, v_pickup_key), false,
    jsonb_build_object('pickup_id', coalesce(v_row.pickup_id, v_pickup_key), 'rider_code', v_rider_code, 'rider_email', v_rider_email, 'action', v_action, 'pickup_status', v_pickup_status),
    v_now
  FROM unnest(
    CASE
      WHEN v_action IN ('PICKUP_FAILED', 'DELIVERY_FAILED') THEN ARRAY['customer_service','operations_supervisor','dispatch']
      WHEN v_action = 'DELIVERED' AND v_cod_required > 0 THEN ARRAY['customer_service','finance']
      ELSE ARRAY['customer_service','operations_supervisor']
    END
  ) AS role_name;

  RETURN jsonb_build_object('ok', true, 'pickup_id', coalesce(v_row.pickup_id, v_pickup_key), 'action', v_action, 'pickup_status', v_pickup_status, 'rider_status', v_rider_status, 'workflow_stage', v_workflow_stage, 'rider_code', v_rider_code, 'rider_email', v_rider_email);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_rider_update_job_status(p_pickup_id text, p_rider_login text, p_action text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT public.be_rider_update_job_status(
    p_pickup_id,
    public.be_rider_code_from_login(p_rider_login),
    p_rider_login,
    p_action,
    coalesce(p_payload, '{}'::jsonb)
  );
$function$
;

CREATE OR REPLACE FUNCTION public.be_rider_update_job_status(p_pickup_id text, p_rider_login text, p_action text, p_remark text DEFAULT NULL::text, p_proof_url text DEFAULT NULL::text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_pickup_id text := trim(coalesce(p_pickup_id, ''));
  v_action text := upper(trim(coalesce(p_action, '')));
  v_now timestamptz := now();
  v_worker jsonb;
  v_code text;
  v_email text;
  v_pickup_status text;
  v_rider_status text;
  v_stage text;
  v_col text;
  v_exception_reason text;
BEGIN
  IF v_pickup_id = '' THEN RAISE EXCEPTION 'pickup_id is required'; END IF;
  IF v_action = '' THEN RAISE EXCEPTION 'action is required'; END IF;

  v_worker := public.be_resolve_mobile_worker(p_rider_login);
  v_code := upper(coalesce(v_worker ->> 'worker_code', p_rider_login));
  v_email := lower(coalesce(v_worker ->> 'email', p_rider_login));

  IF v_action IN ('ACCEPT','ACCEPTED') THEN
    v_action := 'ACCEPTED'; v_pickup_status := 'PICKUP_ASSIGNED'; v_rider_status := 'ACCEPTED'; v_stage := 'RIDER_ACCEPTED'; v_col := 'accepted_at';
  ELSIF v_action IN ('ARRIVED','ARRIVED_AT_PICKUP','ARRIVED_MERCHANT') THEN
    v_action := 'ARRIVED_AT_PICKUP'; v_pickup_status := 'ARRIVED_AT_PICKUP'; v_rider_status := 'ARRIVED_AT_PICKUP'; v_stage := 'ARRIVED_AT_PICKUP'; v_col := 'arrived_pickup_at';
  ELSIF v_action IN ('VERIFY_PICKUP','PICKUP_VERIFIED') THEN
    v_action := 'PICKUP_VERIFIED'; v_pickup_status := 'PICKUP_VERIFIED'; v_rider_status := 'PICKUP_VERIFIED'; v_stage := 'PICKUP_VERIFIED'; v_col := 'pickup_verified_at';
  ELSIF v_action IN ('COLLECTED','PICKUP_COLLECTED','PICKUP_COMPLETED') THEN
    v_action := 'PICKUP_COLLECTED'; v_pickup_status := 'PICKUP_COLLECTED'; v_rider_status := 'PICKUP_COLLECTED'; v_stage := 'READY_FOR_DELIVERY'; v_col := 'pickup_collected_at';
  ELSIF v_action IN ('START_DELIVERY','OUT_FOR_DELIVERY') THEN
    v_action := 'OUT_FOR_DELIVERY'; v_pickup_status := 'OUT_FOR_DELIVERY'; v_rider_status := 'OUT_FOR_DELIVERY'; v_stage := 'OUT_FOR_DELIVERY'; v_col := 'out_for_delivery_at';
  ELSIF v_action IN ('DELIVERED','VERIFY_DELIVERY','DELIVERY_VERIFIED') THEN
    v_action := 'DELIVERED'; v_pickup_status := 'DELIVERED'; v_rider_status := 'DELIVERED'; v_stage := 'DELIVERED'; v_col := 'delivered_at';
  ELSIF v_action IN ('EXCEPTION','DELIVERY_EXCEPTION','DELIVERY_FAILED','PICKUP_EXCEPTION','PICKUP_FAILED') THEN
    v_exception_reason := coalesce(nullif(p_payload ->> 'exception_reason',''), nullif(p_payload ->> 'reason',''), nullif(p_remark,''));
    IF v_exception_reason IS NULL THEN RAISE EXCEPTION 'Exception reason is required'; END IF;
    v_action := CASE WHEN v_action LIKE 'PICKUP%' THEN 'PICKUP_FAILED' ELSE 'DELIVERY_FAILED' END;
    v_pickup_status := v_action; v_rider_status := 'EXCEPTION'; v_stage := 'EXCEPTION'; v_col := 'exception_at';
  ELSE
    RAISE EXCEPTION 'Unsupported rider action: %', v_action;
  END IF;

  UPDATE public.be_portal_pickup_requests p
  SET
    status = v_pickup_status,
    pickup_status = v_pickup_status,
    rider_status = v_rider_status,
    workflow_stage = v_stage,
    rider_app_stage = v_stage,
    rider_last_action = v_action,
    rider_last_action_at = v_now,
    accepted_at = CASE WHEN v_col = 'accepted_at' THEN v_now ELSE p.accepted_at END,
    arrived_pickup_at = CASE WHEN v_col = 'arrived_pickup_at' THEN v_now ELSE p.arrived_pickup_at END,
    pickup_verified_at = CASE WHEN v_col = 'pickup_verified_at' THEN v_now ELSE p.pickup_verified_at END,
    pickup_collected_at = CASE WHEN v_col = 'pickup_collected_at' THEN v_now ELSE p.pickup_collected_at END,
    out_for_delivery_at = CASE WHEN v_col = 'out_for_delivery_at' THEN v_now ELSE p.out_for_delivery_at END,
    delivered_at = CASE WHEN v_col = 'delivered_at' THEN v_now ELSE p.delivered_at END,
    exception_at = CASE WHEN v_col = 'exception_at' THEN v_now ELSE p.exception_at END,
    exception_reason = coalesce(v_exception_reason, p.exception_reason),
    proof_url = coalesce(nullif(p_proof_url,''), p.proof_url),
    cod_collected_amount = coalesce(nullif(p_payload ->> 'cod_collected_amount','')::numeric, p.cod_collected_amount),
    updated_at = v_now,
    metadata = coalesce(p.metadata, '{}'::jsonb) || jsonb_build_object('last_rider_payload', coalesce(p_payload, '{}'::jsonb), 'last_rider_action_at', v_now)
  WHERE upper(coalesce(p.pickup_id, p.canonical_pickup_id, p.pickup_way_id, p.id::text)) = upper(v_pickup_id)
    AND (
      coalesce(p.assigned_rider_code, p.assigned_workforce_code, p.rider_id, '') = ''
      OR upper(coalesce(p.assigned_rider_code,'')) = v_code
      OR upper(coalesce(p.assigned_workforce_code,'')) = v_code
      OR upper(coalesce(p.rider_id,'')) = v_code
      OR lower(coalesce(p.assigned_rider_email,'')) = v_email
    );

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Pickup % not found or not assigned to rider %', v_pickup_id, p_rider_login;
  END IF;

  INSERT INTO public.be_portal_cargo_events (
    pickup_id, source_table, source_key, event_type, event_status, status,
    event_note, actor_type, actor_role, actor_code, actor_email, proof_url, metadata
  ) VALUES (
    v_pickup_id, 'be_portal_pickup_requests', v_pickup_id, v_action, v_pickup_status, v_pickup_status,
    coalesce(p_remark, v_action), 'mobile', 'rider', v_code, v_email, p_proof_url,
    jsonb_build_object('pickup_id', v_pickup_id, 'rider_code', v_code, 'rider_email', v_email, 'payload', coalesce(p_payload, '{}'::jsonb))
  );

  RETURN jsonb_build_object('ok', true, 'pickup_id', v_pickup_id, 'action', v_action, 'pickup_status', v_pickup_status, 'rider_status', v_rider_status, 'workflow_stage', v_stage);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_rider_update_live_location(p_actor_email text, p_role_code text, p_lat numeric, p_lng numeric, p_heading numeric DEFAULT NULL::numeric, p_speed_mps numeric DEFAULT NULL::numeric, p_accuracy_m numeric DEFAULT NULL::numeric, p_battery_pct numeric DEFAULT NULL::numeric, p_source text DEFAULT 'rider_app_geolocation'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor text := lower(nullif(trim(coalesce(p_actor_email,'')), ''));
  v_role text := lower(nullif(trim(coalesce(p_role_code,'')), ''));
  v_row public.be_rider_live_locations%rowtype;
begin
  if v_actor is null then
    raise exception 'actor email is required';
  end if;

  if p_lat is null or p_lng is null then
    raise exception 'lat/lng are required';
  end if;

  insert into public.be_rider_location_events(
    actor_email, role_code, lat, lng, heading, speed_mps, accuracy_m, battery_pct, source, captured_at
  ) values (
    v_actor, coalesce(v_role,'rider'), p_lat, p_lng, p_heading, p_speed_mps, p_accuracy_m, p_battery_pct,
    coalesce(nullif(p_source,''),'rider_app_geolocation'), now()
  );

  insert into public.be_rider_live_locations(
    actor_email, role_code, rider_email, driver_email, helper_email,
    lat, lng, heading, speed_mps, accuracy_m, battery_pct, source, last_seen_at, updated_at
  ) values (
    v_actor,
    coalesce(v_role,'rider'),
    case when coalesce(v_role,'rider') = 'rider' then v_actor else null end,
    case when coalesce(v_role,'rider') = 'driver' then v_actor else null end,
    case when coalesce(v_role,'rider') = 'helper' then v_actor else null end,
    p_lat, p_lng, p_heading, p_speed_mps, p_accuracy_m, p_battery_pct,
    coalesce(nullif(p_source,''),'rider_app_geolocation'),
    now(), now()
  )
  on conflict (actor_email) do update set
    role_code = excluded.role_code,
    rider_email = coalesce(excluded.rider_email, public.be_rider_live_locations.rider_email),
    driver_email = coalesce(excluded.driver_email, public.be_rider_live_locations.driver_email),
    helper_email = coalesce(excluded.helper_email, public.be_rider_live_locations.helper_email),
    lat = excluded.lat,
    lng = excluded.lng,
    heading = excluded.heading,
    speed_mps = excluded.speed_mps,
    accuracy_m = excluded.accuracy_m,
    battery_pct = excluded.battery_pct,
    source = excluded.source,
    last_seen_at = now(),
    updated_at = now()
  returning * into v_row;

  return jsonb_build_object(
    'ok', true,
    'location', to_jsonb(v_row),
    'live_status', 'LIVE'
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_rider_update_pickup_status(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ select public.be_rider_pickup_action(p_payload); $function$
;

CREATE OR REPLACE FUNCTION public.be_rider_update_pickup_status(p_pickup_way_id text, p_rider_email text DEFAULT NULL::text, p_rider_code text DEFAULT NULL::text, p_rider_status text DEFAULT NULL::text, p_pickup_status text DEFAULT NULL::text, p_workflow_stage text DEFAULT NULL::text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id text := public.be_validate_pickupway_id(p_pickup_way_id);
  v_payload jsonb;
  v_rows integer := 0;
begin
  if v_id is null then
    raise exception 'Invalid PickupWayID %. Expected format like P0611-BRV-001.', p_pickup_way_id;
  end if;

  v_payload := jsonb_strip_nulls(
    coalesce(p_payload, '{}'::jsonb)
    || jsonb_build_object(
      'pickup_way_id', v_id,
      'pickup_id', v_id,
      'request_code', v_id,
      'assigned_rider_email', lower(trim(coalesce(p_rider_email, ''))),
      'assigned_rider_code', upper(trim(coalesce(p_rider_code, ''))),
      'assigned_rider', upper(trim(coalesce(p_rider_code, ''))),
      'rider_status', p_rider_status,
      'pickup_status', coalesce(p_pickup_status, p_rider_status),
      'workflow_stage', coalesce(p_workflow_stage, p_pickup_status, p_rider_status),
      'status', coalesce(p_pickup_status, p_rider_status),
      'rider_last_action', p_rider_status,
      'rider_last_action_at', now()
    )
  );

  v_rows := v_rows + public.be_try_update_pickupway_table('be_portal_pickup_requests', v_id, v_payload);
  v_rows := v_rows + public.be_try_update_pickupway_table('be_pickup_requests', v_id, v_payload);
  v_rows := v_rows + public.be_try_update_pickupway_table('be_supervisor_pickup_assignments', v_id, v_payload);

  return jsonb_build_object(
    'ok', true,
    'pickup_way_id', v_id,
    'pickup_id', v_id,
    'updated_rows', v_rows,
    'payload', v_payload
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_rider_verify_delivery(p_pickup_id text, p_rider_email text, p_recipient_name text DEFAULT NULL::text, p_recipient_phone text DEFAULT NULL::text, p_cod_collected_amount numeric DEFAULT 0, p_remark text DEFAULT NULL::text, p_proof_url text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT public.be_rider_update_job_status(p_pickup_id, p_rider_email, 'DELIVERED', p_remark, p_proof_url, jsonb_build_object('recipient_name', p_recipient_name, 'recipient_phone', p_recipient_phone, 'cod_collected_amount', p_cod_collected_amount, 'proof_url', p_proof_url));
$function$
;

CREATE OR REPLACE FUNCTION public.be_rider_verify_delivery(p_pickup_id text DEFAULT NULL::text, p_rider_email text DEFAULT NULL::text, p_recipient_name text DEFAULT NULL::text, p_recipient_phone text DEFAULT NULL::text, p_cod_collected_amount numeric DEFAULT 0, p_remark text DEFAULT NULL::text, p_proof_url text DEFAULT NULL::text, p_pickup_way_id text DEFAULT NULL::text, p_rider_code text DEFAULT NULL::text, p_delivery_way_id text DEFAULT NULL::text, p_waybill_no text DEFAULT NULL::text, p_invoice_no text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_delivery_way_id text := coalesce(
    public.be_normalize_deliveryway_id(p_delivery_way_id),
    public.be_normalize_deliveryway_id(p_pickup_id),
    public.be_deliveryway_id_from_waybill_no(p_waybill_no),
    public.be_deliveryway_id_from_invoice_no(p_invoice_no)
  );
  v_pickup_way_id text := coalesce(public.be_normalize_pickupway_id(p_pickup_way_id), public.be_normalize_pickupway_id(p_pickup_id));
begin
  if v_pickup_way_id is null and v_delivery_way_id is not null then
    select pickup_way_id into v_pickup_way_id
    from public.be_v_rider_delivery_jobs
    where delivery_way_id = v_delivery_way_id
    limit 1;
  end if;

  if v_pickup_way_id is null then
    raise exception 'Valid PickupWayID is required. Pass p_pickup_id/p_pickup_way_id as P.... and p_delivery_way_id as D....';
  end if;

  return public.be_rider_update_pickup_status(
    v_pickup_way_id,
    p_rider_email,
    p_rider_code,
    'DELIVERED',
    'DELIVERED',
    'DELIVERED',
    jsonb_build_object(
      'delivery_way_id', v_delivery_way_id,
      'tracking_no', v_delivery_way_id,
      'waybill_no', public.be_make_waybill_no(v_delivery_way_id),
      'invoice_no', public.be_make_invoice_no(v_delivery_way_id),
      'recipient_name', p_recipient_name,
      'recipient_phone', p_recipient_phone,
      'cod_collected_amount', coalesce(p_cod_collected_amount, 0),
      'cod_collected_at', case when coalesce(p_cod_collected_amount, 0) > 0 then now() else null end,
      'cod_settlement_status', case when coalesce(p_cod_collected_amount, 0) > 0 then 'PENDING_REMITTANCE' else null end,
      'delivery_verified_at', now(),
      'delivery_verified_by', p_rider_email,
      'remark', p_remark,
      'proof_url', p_proof_url
    )
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_rider_verify_pickup(p_pickup_id text, p_rider_email text, p_parcel_count integer DEFAULT 1, p_remark text DEFAULT NULL::text, p_proof_url text DEFAULT NULL::text)
 RETURNS jsonb
