$function$
;

CREATE OR REPLACE FUNCTION public.be_rider_verify_pickup(p_pickup_id text, p_rider_email text DEFAULT NULL::text, p_parcel_count integer DEFAULT NULL::integer, p_remark text DEFAULT NULL::text, p_proof_url text DEFAULT NULL::text, p_pickup_way_id text DEFAULT NULL::text, p_rider_code text DEFAULT NULL::text, p_weight_kg numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
