;

CREATE OR REPLACE FUNCTION public.be_rider_wayplan_action(p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_wayplan_id text := nullif(p_payload->>'wayplan_id', '');
  v_delivery_way_id text := nullif(p_payload->>'delivery_way_id', '');
  v_action text := lower(coalesce(nullif(p_payload->>'action', ''), ''));
  v_status text;
  v_cod numeric := coalesce(nullif(p_payload->>'cod_collected', '')::numeric, 0);
  v_proof text := nullif(p_payload->>'proof_url', '');
  v_receiver_name text := nullif(p_payload->>'receiver_name', '');
  v_receiver_phone text := nullif(p_payload->>'receiver_phone', '');
  v_failed_reason text := nullif(p_payload->>'failed_reason', '');
  v_count integer;
begin
  if v_wayplan_id is null or v_delivery_way_id is null then
    return jsonb_build_object('ok', false, 'error', 'wayplan_id and delivery_way_id are required');
  end if;

  v_status := case v_action
    when 'accept' then 'RIDER_ACCEPTED'
    when 'start_delivery' then 'OUT_FOR_DELIVERY'
    when 'arrived' then 'ARRIVED_AT_CUSTOMER'
    when 'deliver' then 'DELIVERED'
    when 'failed' then 'FAILED_DELIVERY'
    when 'return' then 'RETURN_TO_WAREHOUSE'
    else null
  end;

  if v_status is null then
    return jsonb_build_object(
      'ok', false,
      'error', 'Invalid rider action',
      'allowed_actions', jsonb_build_array('accept', 'start_delivery', 'arrived', 'deliver', 'failed', 'return')
    );
  end if;

  update public.be_wayplan_dispatch_stops
  set
    rider_status = v_status,
    stop_status = v_status,
    rider_action_at = now(),
    delivered_at = case when v_status = 'DELIVERED' then now() else delivered_at end,
    cod_collected = case when v_status = 'DELIVERED' then coalesce(v_cod, cod_amount, 0) else cod_collected end,
    rider_proof_url = coalesce(v_proof, rider_proof_url),
    receiver_name = coalesce(v_receiver_name, receiver_name),
    receiver_phone = coalesce(v_receiver_phone, receiver_phone),
    failed_reason = case when v_status = 'FAILED_DELIVERY' then v_failed_reason else failed_reason end,
    metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
      'last_rider_action', v_action,
      'last_rider_status', v_status,
      'last_rider_action_at', now()
    ),
    updated_at = now()
  where wayplan_id = v_wayplan_id
    and delivery_way_id = v_delivery_way_id;

  get diagnostics v_count = row_count;

  if v_count = 0 then
    return jsonb_build_object('ok', false, 'error', 'Wayplan stop not found');
  end if;

  update public.be_waybill_ledger
  set
    rider_status = v_status,
    dispatch_status = v_status,
    wayplan_status = v_status,
    delivered_at = case when v_status = 'DELIVERED' then now() else delivered_at end,
    cod_collected = case when v_status = 'DELIVERED' then coalesce(v_cod, cod_amount, 0) else cod_collected end,
    rider_proof_url = coalesce(v_proof, rider_proof_url),
    failed_reason = case when v_status = 'FAILED_DELIVERY' then v_failed_reason else failed_reason end,
    updated_at = now()
  where delivery_way_id = v_delivery_way_id;

  update public.be_portal_pickup_requests
  set
    dispatch_status = v_status,
    wayplan_status = v_status,
    updated_at = now()
  where delivery_way_id = v_delivery_way_id
     or pickup_id in (
       select pickup_id
       from public.be_wayplan_dispatch_stops
       where wayplan_id = v_wayplan_id
         and delivery_way_id = v_delivery_way_id
     );

  update public.be_wayplan_dispatches w
  set
    wayplan_status = case
      when not exists (
        select 1
        from public.be_wayplan_dispatch_stops s
        where s.wayplan_id = w.wayplan_id
          and coalesce(s.stop_status, '') not in ('DELIVERED', 'FAILED_DELIVERY', 'RETURN_TO_WAREHOUSE')
      ) then 'COMPLETED'
      when v_status = 'OUT_FOR_DELIVERY' then 'OUT_FOR_DELIVERY'
      else w.wayplan_status
    end,
    total_delivered = (
      select count(*)
      from public.be_wayplan_dispatch_stops s
      where s.wayplan_id = w.wayplan_id
        and s.stop_status = 'DELIVERED'
    ),
    total_failed = (
      select count(*)
      from public.be_wayplan_dispatch_stops s
      where s.wayplan_id = w.wayplan_id
        and s.stop_status in ('FAILED_DELIVERY', 'RETURN_TO_WAREHOUSE')
    ),
    total_cod_collected = (
      select coalesce(sum(cod_collected), 0)
      from public.be_wayplan_dispatch_stops s
      where s.wayplan_id = w.wayplan_id
        and s.stop_status = 'DELIVERED'
    ),
    completed_at = case
      when not exists (
        select 1
        from public.be_wayplan_dispatch_stops s
        where s.wayplan_id = w.wayplan_id
          and coalesce(s.stop_status, '') not in ('DELIVERED', 'FAILED_DELIVERY', 'RETURN_TO_WAREHOUSE')
      ) then now()
      else completed_at
    end,
    updated_at = now()
  where w.wayplan_id = v_wayplan_id;

  return jsonb_build_object(
    'ok', true,
    'wayplan_id', v_wayplan_id,
    'delivery_way_id', v_delivery_way_id,
    'action', v_action,
    'status', v_status
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_rider_workflow_jobs(p_rider_email text DEFAULT NULL::text, p_rider_code text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'ok', true,
    'rider_email', p_rider_email,
    'rider_code', p_rider_code,
    'jobs', coalesce(jsonb_agg(to_jsonb(x) order by x.assigned_at desc nulls last), '[]'::jsonb)
  )
  from (
    select *
    from public.be_v_rider_workflow_jobs
    where (
      nullif(trim(coalesce(p_rider_email, '')), '') is null
      or assigned_rider_email = lower(trim(p_rider_email))
    )
    and (
      nullif(trim(coalesce(p_rider_code, '')), '') is null
      or assigned_rider_code = upper(trim(p_rider_code))
      or assigned_rider = upper(trim(p_rider_code))
    )
    limit 300
  ) x;
$function$
;

create or replace view "public"."be_riders" as  SELECT record_key AS id,
    record_key AS rider_id,
    record_key AS rider_code,
    record_key AS code,
    COALESCE((payload ->> 'rider_name'::text), (payload ->> 'name'::text), record_key) AS rider_name,
    COALESCE((payload ->> 'rider_name'::text), (payload ->> 'name'::text), record_key) AS name,
    COALESCE((payload ->> 'rider_name'::text), (payload ->> 'name'::text), record_key) AS label,
    COALESCE((payload ->> 'rider_name'::text), (payload ->> 'name'::text), record_key) AS display_name,
    COALESCE((payload ->> 'phone_primary'::text), (payload ->> 'phone'::text)) AS phone,
    'ACTIVE'::text AS status,
    true AS active,
    true AS is_active,
    true AS available,
    true AS is_available,
    payload,
    updated_at
   FROM public.be_master_data_rows
  WHERE ((dataset_key = 'rider_master'::text) AND (deleted_at IS NULL) AND (lower(COALESCE((payload ->> 'status'::text), status, 'active'::text)) <> 'inactive'::text));


CREATE OR REPLACE FUNCTION public.be_role_portal_snapshot(p_role text, p_branch text DEFAULT NULL::text, p_workforce_code text DEFAULT NULL::text, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_role text := lower(coalesce(p_role, 'superadmin'));
  v_branch text := nullif(upper(coalesce(p_branch, '')), '');
  v_limit integer := least(greatest(coalesce(p_limit, 100), 1), 500);
  v_pickups jsonb;
  v_assignments jsonb;
  v_notifications jsonb;
  v_events jsonb;
begin
  select coalesce(jsonb_agg(row_to_json(x)::jsonb order by x.updated_at desc), '[]'::jsonb) into v_pickups
  from (select * from public.be_portal_pickup_requests p where v_branch is null or p.branch_code = v_branch order by p.updated_at desc nulls last limit v_limit) x;

  select coalesce(jsonb_agg(row_to_json(x)::jsonb order by x.updated_at desc), '[]'::jsonb) into v_assignments
  from (select * from public.be_supervisor_job_assignments a where (v_branch is null or a.branch_code = v_branch) and (p_workforce_code is null or a.rider_id = p_workforce_code or a.driver_id = p_workforce_code or a.helper_id = p_workforce_code) order by a.updated_at desc nulls last limit v_limit) x;

  select coalesce(jsonb_agg(row_to_json(n)::jsonb order by n.created_at desc), '[]'::jsonb) into v_notifications
  from (select * from public.be_app_notifications n where n.target_role in (v_role, 'all', 'superadmin') or (v_role = 'operation_manager' and n.target_role in ('operations','operation_manager','dispatch','warehouse','supervisor')) order by n.created_at desc limit v_limit) n;

  select coalesce(jsonb_agg(row_to_json(e)::jsonb order by e.created_at desc), '[]'::jsonb) into v_events
  from (select * from public.be_portal_cargo_events e where v_branch is null or e.branch_code = v_branch order by e.created_at desc limit v_limit) e;

  return jsonb_build_object(
    'ok', true,
    'role', v_role,
    'branch', v_branch,
    'pickups', coalesce(v_pickups, '[]'::jsonb),
    'assignments', coalesce(v_assignments, '[]'::jsonb),
    'notifications', coalesce(v_notifications, '[]'::jsonb),
    'cargo_events', coalesce(v_events, '[]'::jsonb),
    'finance', jsonb_build_object('cod_rows','[]'::jsonb,'settlements','[]'::jsonb),
    'kpis', jsonb_build_object('pickups', jsonb_array_length(coalesce(v_pickups,'[]'::jsonb)), 'assignments', jsonb_array_length(coalesce(v_assignments,'[]'::jsonb)), 'notifications', jsonb_array_length(coalesce(v_notifications,'[]'::jsonb)), 'events', jsonb_array_length(coalesce(v_events,'[]'::jsonb))),
    'synced_at', now()
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_save_data_entry_parcel_detail(p_actor_email text, p_actual_collect numeric, p_cod_amount numeric, p_contact_no_1 text, p_contact_no_2 text, p_customer_tier text, p_delivery_fee numeric, p_delivery_way_id text, p_destination text, p_item_price numeric, p_parcel_sequence integer, p_pickup_by text, p_pickup_id text, p_recipient_address text, p_recipient_name text, p_remark text, p_surcharge numeric, p_township text, p_weight_kg numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_tariff jsonb;
  v_surcharge numeric := 0;
  v_delivery_fee numeric := 0;
  v_actual_collect numeric := 0;
begin
  v_tariff := public.be_calculate_tariff(
    p_township,
    coalesce(p_customer_tier, 'Standard'),
    coalesce(p_weight_kg, 0),
    coalesce(p_item_price, 0)
  );

  v_surcharge := coalesce((v_tariff->>'surcharge')::numeric, 0);
  v_delivery_fee := coalesce((v_tariff->>'delivery_fee')::numeric, 0);
  v_actual_collect := coalesce((v_tariff->>'actual_collect')::numeric, 0);

  insert into public.be_data_entry_parcel_details (
    pickup_id,
    parcel_sequence,
    delivery_way_id,
    recipient_name,
    contact_no_1,
    contact_no_2,
    township,
    recipient_address,
    customer_tier,
    item_price,
    weight_kg,
    surcharge,
    delivery_fee,
    cod_amount,
    actual_collect,
    destination,
    pickup_by,
    remark,
    saved_by_email,
    saved_at,
    updated_at
  )
  values (
    p_pickup_id,
    p_parcel_sequence,
    p_delivery_way_id,
    p_recipient_name,
    p_contact_no_1,
    p_contact_no_2,
    p_township,
    p_recipient_address,
    coalesce(p_customer_tier, 'Standard'),
    coalesce(p_item_price, 0),
    coalesce(p_weight_kg, 0),
    v_surcharge,
    v_delivery_fee,
    v_actual_collect,
    v_actual_collect,
    coalesce(p_destination, 'Yangon'),
    coalesce(p_pickup_by, 'DATA_ENTRY'),
    p_remark,
    p_actor_email,
    now(),
    now()
  )
  on conflict (pickup_id, parcel_sequence)
  do update set
    delivery_way_id = excluded.delivery_way_id,
    recipient_name = excluded.recipient_name,
    contact_no_1 = excluded.contact_no_1,
    contact_no_2 = excluded.contact_no_2,
    township = excluded.township,
    recipient_address = excluded.recipient_address,
    customer_tier = excluded.customer_tier,
    item_price = excluded.item_price,
    weight_kg = excluded.weight_kg,
    surcharge = excluded.surcharge,
    delivery_fee = excluded.delivery_fee,
    cod_amount = excluded.cod_amount,
    actual_collect = excluded.actual_collect,
    destination = excluded.destination,
    pickup_by = excluded.pickup_by,
    remark = excluded.remark,
    saved_by_email = excluded.saved_by_email,
    updated_at = now();

  return jsonb_build_object(
    'ok', true,
    'pickup_id', p_pickup_id,
    'parcel_sequence', p_parcel_sequence,
    'delivery_way_id', p_delivery_way_id,
    'item_price', coalesce(p_item_price, 0),
    'weight_kg', coalesce(p_weight_kg, 0),
    'surcharge', v_surcharge,
    'delivery_fee', v_delivery_fee,
    'cod_amount', v_actual_collect,
    'actual_collect', v_actual_collect,
    'remark', p_remark
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_save_delivery_signature(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
 v_tracking text;
begin

v_tracking := p_payload->>'tracking_code';


insert into public.be_delivery_pod_signatures
(
tracking_code,
delivery_way_id,
receiver_name,
receiver_phone,
signature_url,
gps_lat,
gps_lng,
signed_by,
metadata
)
values
(
v_tracking,
p_payload->>'delivery_way_id',
p_payload->>'receiver_name',
p_payload->>'receiver_phone',
p_payload->>'signature_url',
(p_payload->>'latitude')::numeric,
(p_payload->>'longitude')::numeric,
p_payload->>'actor',
p_payload
);


update public.parcels
set
delivery_signature_url = p_payload->>'signature_url',
delivery_photo_url = coalesce(
 delivery_photo_url,
 p_payload->>'photo_url'
),
status='delivered',
delivered_at=now(),
updated_at=now()
where tracking_code=v_tracking;


return jsonb_build_object(
'ok',true,
'tracking_code',v_tracking,
'status','delivered',
'signed_at',now()
);

end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_save_operational_master_snapshot(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_payload jsonb := coalesce(p_payload, '{}'::jsonb);
  v_saved jsonb;
begin
  v_payload := v_payload || jsonb_build_object(
    'updated_at', now(),
    'source', coalesce(v_payload->>'source', 'master_data_upload_screen')
  );

  insert into public.be_master_data_snapshots (snapshot_key, payload, updated_at, created_by)
  values ('default', v_payload, now(), auth.uid())
  on conflict (snapshot_key)
  do update set
    payload = excluded.payload,
    updated_at = now(),
    created_by = coalesce(auth.uid(), public.be_master_data_snapshots.created_by)
  returning payload into v_saved;

  return v_saved;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_settings_get_config()
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
DECLARE v_role TEXT := public.be_current_user_role();
BEGIN
  IF v_role != 'admin' THEN RAISE EXCEPTION 'Admin only'; END IF;
  RETURN (SELECT COALESCE(json_agg(row_to_json(c)),'[]'::json) FROM ( SELECT config_key, config_value, description, updated_at FROM public.be_system_config ORDER BY config_key ) c);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_settings_get_tariff()
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
DECLARE v_role TEXT := public.be_current_user_role();
BEGIN
  IF v_role NOT IN ('admin','operation_manager') THEN RAISE EXCEPTION 'Access denied'; END IF;
  RETURN (SELECT COALESCE(json_agg(row_to_json(t)),'[]'::json) FROM ( SELECT tier_name, free_allowance_kg, base_fee_mmk, extra_per_kg_mmk, highway_fee_mmk, is_active, updated_at FROM public.be_tariff_master ORDER BY tier_name ) t);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_settings_go_live_verification()
 RETURNS json
 LANGUAGE sql
 STABLE SECURITY DEFINER
AS $function$
  SELECT json_build_object('ok',true,'rpc_count',(SELECT count(*) FROM pg_proc WHERE proname LIKE 'be_settings_%'),'ts',NOW());
$function$
;

CREATE OR REPLACE FUNCTION public.be_settings_set_config(p_key text, p_value text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE v_role TEXT := public.be_current_user_role();
BEGIN
  IF v_role != 'admin' THEN RAISE EXCEPTION 'Admin only'; END IF;
  INSERT INTO public.be_system_config(config_key,config_value,updated_at) VALUES(p_key,p_value,NOW()) ON CONFLICT(config_key) DO UPDATE SET config_value=EXCLUDED.config_value, updated_at=NOW();
  RETURN json_build_object('success',true,'key',p_key,'value',p_value);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_settings_toggle_user(p_user_id uuid, p_status text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE v_role TEXT := public.be_current_user_role();
BEGIN
  IF v_role NOT IN ('admin','operation_manager') THEN RAISE EXCEPTION 'Access denied'; END IF;
  IF p_status NOT IN ('active','inactive','suspended') THEN RAISE EXCEPTION 'Invalid status'; END IF;
  UPDATE public.be_user_account_registry SET status=p_status, updated_at=NOW() WHERE user_id=p_user_id;
  RETURN json_build_object('success',true,'user_id',p_user_id,'status',p_status);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_settings_update_tariff(p_tier text, p_base_fee integer, p_extra_per_kg integer, p_free_kg integer, p_highway_fee integer)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE v_role TEXT := public.be_current_user_role();
BEGIN
  IF v_role != 'admin' THEN RAISE EXCEPTION 'Admin only'; END IF;
  UPDATE public.be_tariff_master SET base_fee_mmk=p_base_fee, extra_per_kg_mmk=p_extra_per_kg, free_allowance_kg=p_free_kg, highway_fee_mmk=p_highway_fee, updated_at=NOW() WHERE tier_name=p_tier;
  INSERT INTO public.be_audit_log(action,table_name,record_id,old_values,new_values,performed_by,performed_at) VALUES('UPDATE','be_tariff_master',p_tier,NULL,json_build_object('tier',p_tier,'base_fee',p_base_fee,'extra',p_extra_per_kg,'free_kg',p_free_kg,'highway',p_highway_fee),auth.uid(),NOW());
  RETURN json_build_object('success',true,'tier',p_tier,'updated_at',NOW());
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_settings_users(p_role text DEFAULT NULL::text, p_branch text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
DECLARE v_role TEXT := public.be_current_user_role();
BEGIN
  IF v_role NOT IN ('admin','operation_manager') THEN RAISE EXCEPTION 'Access denied'; END IF;
  RETURN (SELECT COALESCE(json_agg(row_to_json(u)),'[]'::json) FROM ( SELECT user_id, full_name, role, email, phone_number, branch_code, status, created_at FROM public.be_user_account_registry WHERE (p_role IS NULL OR role=p_role) AND (p_branch IS NULL OR branch_code=p_branch) ORDER BY role, full_name ) u);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_submit_parcel_photo_for_review(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_pickup text := coalesce(p_payload->>'pickup_id', p_payload->>'pickup_way_id');
  v_seq_text text := coalesce(p_payload->>'parcel_sequence', p_payload->>'item_no', '1');
  v_seq integer := case when v_seq_text ~ '^[0-9]+$' then greatest(1, v_seq_text::integer) else 1 end;
  v_id uuid;
begin
  if nullif(v_pickup, '') is null then
    return jsonb_build_object('ok', false, 'error', 'pickup_id is required');
  end if;

  if nullif(p_payload->>'photo_url', '') is null then
    return jsonb_build_object('ok', false, 'error', 'photo_url is required');
  end if;

  update public.be_parcel_photo_reviews
  set previous_photo_url = current_photo_url,
      current_photo_url = p_payload->>'photo_url',
      delivery_way_id = coalesce(p_payload->>'delivery_way_id', delivery_way_id),
      tracking_no = coalesce(p_payload->>'tracking_no', tracking_no),
      actual_weight_kg = coalesce(
        case when coalesce(p_payload->>'actual_weight_kg', '') ~ '^[0-9]+([.][0-9]+)?$'
          then (p_payload->>'actual_weight_kg')::numeric end,
        actual_weight_kg
      ),
      review_status = 'PENDING_REVIEW',
      rejection_reason = null,
      rejection_note = null,
      uploaded_by = p_payload->>'uploaded_by',
      uploaded_role = coalesce(p_payload->>'uploaded_role', 'RIDER'),
      remarks = p_payload->>'remarks',
      payload = coalesce(payload, '{}'::jsonb) || p_payload,
      updated_at = now()
  where id = (
    select r.id
    from public.be_parcel_photo_reviews r
    where r.pickup_id = v_pickup
      and r.parcel_sequence = v_seq
    order by r.updated_at desc nulls last, r.created_at desc nulls last
    limit 1
  )
  returning id into v_id;

  if not found then
    insert into public.be_parcel_photo_reviews (
      pickup_id, parcel_sequence, delivery_way_id, tracking_no,
      current_photo_url, actual_weight_kg, review_status,
      uploaded_by, uploaded_role, remarks, payload, updated_at
    ) values (
      v_pickup,
      v_seq,
      p_payload->>'delivery_way_id',
      p_payload->>'tracking_no',
      p_payload->>'photo_url',
      case when coalesce(p_payload->>'actual_weight_kg', '') ~ '^[0-9]+([.][0-9]+)?$'
        then (p_payload->>'actual_weight_kg')::numeric end,
      'PENDING_REVIEW',
      p_payload->>'uploaded_by',
      coalesce(p_payload->>'uploaded_role', 'RIDER'),
      p_payload->>'remarks',
      p_payload,
      now()
    ) returning id into v_id;
  end if;

  update public.be_portal_pickup_requests
  set photo_review_status = 'PARTIAL_REVIEW',
      updated_at = now()
  where pickup_way_id = v_pickup;

  return jsonb_build_object(
    'ok', true,
    'source', 'be_submit_parcel_photo_for_review',
    'review_id', v_id,
    'pickup_id', v_pickup,
    'parcel_sequence', v_seq,
    'review_status', 'PENDING_REVIEW'
  );
end $function$
;

CREATE OR REPLACE FUNCTION public.be_submit_pickup_request(p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_pickup_id text;
  v_merchant_code text := upper(coalesce(
    nullif(p_payload->>'merchant_code', ''),
    nullif(p_payload->>'merchant', ''),
    'GEN'
  ));
  v_merchant_name text := coalesce(
    nullif(p_payload->>'merchant_name', ''),
    nullif(p_payload->>'merchant_label', ''),
    v_merchant_code
  );
  v_actor_email text := coalesce(
    nullif(p_payload->>'actor_email', ''),
    nullif(p_payload->>'created_by_email', ''),
    nullif(p_payload->>'email', '')
  );
  v_expected_parcels integer := greatest(coalesce(nullif(p_payload->>'expected_parcels', '')::integer, 1), 1);
  v_pickup_date date := coalesce(
    nullif(p_payload->>'pickup_date', '')::date,
    nullif(p_payload->>'date', '')::date,
    current_date
  );
  v_address text := nullif(p_payload->>'address', '');
  v_township text := nullif(p_payload->>'township', '');
  v_row jsonb;
begin
  v_merchant_code := upper(left(regexp_replace(v_merchant_code, '[^A-Za-z0-9]', '', 'g'), 3));

  v_pickup_id := coalesce(
    nullif(p_payload->>'pickup_id', ''),
    'P'
      || to_char(v_pickup_date, 'MMDD')
      || '-'
      || v_merchant_code
      || '-'
      || lpad(v_expected_parcels::text, 3, '0')
  );

  insert into public.be_portal_pickup_requests (
    pickup_id,
    pickup_way_id,
    merchant_code,
    merchant_name,
    contact_person,
    phone,

    address,
    township,
    pickup_address,
    pickup_township,

    expected_parcels,
    parcel_count,
    expected_parcel_count,

    required_vehicle,
    vehicle_type,
    payment_terms,
    payment_method,
    payment_type,

    pickup_date,
    pickup_status,
    status,
    operation_status,
    supervisor_status,
    assignment_status,
    data_entry_status,
    warehouse_status,
    dispatch_status,
    wayplan_status,
    rider_status,
    finance_status,
    settlement_status,

    branch_code,
    source_portal,
    source_channel,
    requester_type,
    workflow_stage,

    created_by,
    metadata,
    created_at,
    updated_at
  )
  values (
    v_pickup_id,
    v_pickup_id,
    v_merchant_code,
    v_merchant_name,
    nullif(p_payload->>'contact_person', ''),
    nullif(p_payload->>'phone', ''),

    v_address,
    v_township,
    v_address,
    v_township,

    v_expected_parcels,
    v_expected_parcels,
    v_expected_parcels,

    nullif(p_payload->>'required_vehicle', ''),
    nullif(p_payload->>'required_vehicle', ''),
    coalesce(nullif(p_payload->>'payment_terms', ''), 'COD'),
    coalesce(nullif(p_payload->>'payment_terms', ''), 'COD'),
    coalesce(nullif(p_payload->>'payment_terms', ''), 'COD'),

    v_pickup_date,
    'WAITING_ASSIGNMENT',
    'WAITING_ASSIGNMENT',
    'submitted',
    'PENDING_ASSIGNMENT',
    'PENDING',
    'WAITING_PICKUP',
    'WAITING_DATA_ENTRY',
    'WAITING_WAYPLAN',
    'PENDING_WAYPLAN',
    'NOT_ASSIGNED',
    'pending_finance',
    'pending',

    'YGN',
    'enterprise',
    'pickup_request_form',
    'merchant',
    'PICKUP_REQUESTED',

    auth.uid(),
    coalesce(p_payload, '{}'::jsonb) || jsonb_build_object(
      'source', 'pickup_request_form',
      'actor_email', v_actor_email,
      'submitted_at', now(),
      'generated_pickup_id_rule', 'P + MMDD + MERCHANT + EXPECTED_PARCELS'
    ),
    now(),
    now()
  )
  on conflict (pickup_id) do update
  set
    pickup_way_id = excluded.pickup_way_id,
    merchant_code = excluded.merchant_code,
    merchant_name = excluded.merchant_name,
    contact_person = excluded.contact_person,
    phone = excluded.phone,

    address = excluded.address,
    township = excluded.township,
    pickup_address = excluded.pickup_address,
    pickup_township = excluded.pickup_township,

    expected_parcels = excluded.expected_parcels,
    parcel_count = excluded.parcel_count,
    expected_parcel_count = excluded.expected_parcel_count,

    required_vehicle = excluded.required_vehicle,
    vehicle_type = excluded.vehicle_type,
    payment_terms = excluded.payment_terms,
    payment_method = excluded.payment_method,
    payment_type = excluded.payment_type,

    pickup_date = excluded.pickup_date,
    pickup_status = excluded.pickup_status,
    status = excluded.status,
    operation_status = excluded.operation_status,
    supervisor_status = excluded.supervisor_status,
    assignment_status = excluded.assignment_status,
    data_entry_status = excluded.data_entry_status,
    warehouse_status = excluded.warehouse_status,
    dispatch_status = excluded.dispatch_status,
    wayplan_status = excluded.wayplan_status,
    rider_status = excluded.rider_status,
    finance_status = excluded.finance_status,
    settlement_status = excluded.settlement_status,

    branch_code = excluded.branch_code,
    source_portal = excluded.source_portal,
    source_channel = excluded.source_channel,
    requester_type = excluded.requester_type,
    workflow_stage = excluded.workflow_stage,

    metadata = excluded.metadata,
    updated_at = now()
  returning to_jsonb(be_portal_pickup_requests.*)
  into v_row;

  return jsonb_build_object(
    'ok', true,
    'status', 'PICKUP_SUBMITTED',
    'pickup_id', v_pickup_id,
    'pickup_way_id', v_pickup_id,
    'expected_parcels', v_expected_parcels,
    'row', v_row
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_submit_portal_pickup_request(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_merchant jsonb;
  v_pickup_time timestamptz;
  v_pickup_date date;
  v_merchant_code text;
  v_merchant_name text;
  v_sender_phone text;
  v_township text;
  v_city text;
  v_pickup_address text;
  v_payment_terms text;
  v_count integer;
  v_batch jsonb;
  v_pickup_id text;
  v_row public.be_portal_pickup_requests;
begin
  v_merchant := public.be_resolve_merchant_meta(
    coalesce(p_payload->>'merchant_code', p_payload->>'merchant_id'),
    coalesce(p_payload->>'merchant_name', p_payload->>'sender_name')
  );

  v_merchant_code := public.be_known_merchant_code(
    coalesce(v_merchant->>'merchant_code', p_payload->>'merchant_code', p_payload->>'merchant_id'),
    coalesce(v_merchant->>'merchant_name', p_payload->>'merchant_name', p_payload->>'sender_name')
  );

  v_merchant_name := coalesce(nullif(v_merchant->>'merchant_name', ''), nullif(v_merchant->>'display_name', ''), nullif(p_payload->>'merchant_name', ''), v_merchant_code);
  v_sender_phone := coalesce(nullif(p_payload->>'sender_phone', ''), nullif(v_merchant->>'phone_primary', ''));
  v_township := coalesce(nullif(p_payload->>'township', ''), nullif(v_merchant->>'township', ''));
  v_city := coalesce(nullif(p_payload->>'city', ''), nullif(v_merchant->>'city', ''), 'Yangon');
  v_pickup_address := coalesce(nullif(p_payload->>'pickup_address', ''), nullif(v_merchant->>'default_pickup_address', ''), nullif(v_merchant->>'address_line_1', ''), array_to_string(array_remove(array[v_merchant->>'address_line_1', v_merchant->>'address_line_2'], null), ', '));

  if v_pickup_address is null or trim(v_pickup_address) = '' then
    raise exception 'Merchant % has no pickup address. Update merchant_master address_line_1/default_pickup_address first.', v_merchant_code;
  end if;

  v_payment_terms := coalesce(nullif(p_payload->>'payment_terms', ''), nullif(v_merchant->>'payment_terms', ''), 'COD');
  v_pickup_time := nullif(p_payload->>'pickup_time', '')::timestamptz;
  v_pickup_date := coalesce(v_pickup_time::date, now()::date);
  v_count := greatest(coalesce(nullif(p_payload->>'parcel_count', '')::int, 1), 1);

  v_batch := public.be_next_go_live_pickup_batch(v_pickup_date, v_merchant_code, v_count);
  v_pickup_id := v_batch->>'pickup_id';

  insert into public.be_portal_pickup_requests (
    pickup_id, canonical_pickup_id, pickup_way_id, pickup_date, merchant_abbr,
    delivery_start_no, delivery_end_no, delivery_date_prefix, delivery_prefix,
    source, requester_type, merchant_code, merchant_name, sender_name, sender_phone,
    township, city, pickup_address, payment_terms, tariff_code, assigned_branch,
    pickup_time, parcel_count, cod_amount, priority, special_instructions,
    status, assignment_status, payload, created_at, updated_at
  )
  values (
    v_pickup_id, v_pickup_id, v_pickup_id, v_pickup_date, v_merchant_code,
    (v_batch->>'delivery_start_no')::int, (v_batch->>'delivery_end_no')::int,
    'D' || to_char(v_pickup_date, 'MMDD'), v_batch->>'delivery_prefix',
    coalesce(p_payload->>'source', 'customer_service'), coalesce(p_payload->>'requester_type', 'Merchant'),
    v_merchant_code, v_merchant_name, coalesce(nullif(p_payload->>'sender_name', ''), v_merchant_name), v_sender_phone,
    v_township, v_city, v_pickup_address, v_payment_terms, p_payload->>'tariff_code', coalesce(nullif(p_payload->>'assigned_branch', ''), 'YGN'),
    v_pickup_time, v_count, coalesce(nullif(p_payload->>'cod_amount', '')::numeric, 0), coalesce(p_payload->>'priority', 'normal'), p_payload->>'special_instructions',
    'pending_assignment', 'pending_assignment',
    coalesce(p_payload, '{}'::jsonb) || jsonb_build_object('pickup_id', v_pickup_id, 'pickup_way_id', v_pickup_id, 'canonical_pickup_id', v_pickup_id, 'merchant_code', v_merchant_code, 'merchant_name', v_merchant_name, 'merchant_payload', v_merchant, 'id_generation', v_batch),
    now(), now()
  )
  returning * into v_row;

  return jsonb_build_object('ok', true, 'pickup_id', v_pickup_id, 'pickup_request_id', v_pickup_id, 'pickup_way_id', v_pickup_id, 'merchant_code', v_merchant_code, 'merchant_name', v_merchant_name, 'pickup_address', v_pickup_address, 'delivery_start_no', v_row.delivery_start_no, 'delivery_end_no', v_row.delivery_end_no, 'request', to_jsonb(v_row));
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_supervisor_assign_job(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_pickup_id text;
  v_rider_code text;
  v_driver_code text;
  v_helper_code text;
  v_vehicle_code text;
  v_actor_email text;

  v_rider_name text;
  v_driver_name text;
  v_helper_name text;

  v_updated integer := 0;
  v_assignment_payload jsonb;
begin
  v_pickup_id := nullif(coalesce(
    p_payload->>'pickup_way_id',
    p_payload->>'pickup_id',
    p_payload->>'request_code',
    p_payload->>'assignment_key'
  ), '');

  v_rider_code := nullif(coalesce(
    p_payload->>'rider_code',
    p_payload->>'assigned_rider_code',
    p_payload->>'field_rider_code',
    p_payload#>>'{assignment_payload,rider_code}'
  ), '');

  v_driver_code := nullif(coalesce(
    p_payload->>'driver_code',
    p_payload->>'assigned_driver_code',
    p_payload#>>'{assignment_payload,driver_code}'
  ), '');

  v_helper_code := nullif(coalesce(
    p_payload->>'helper_code',
    p_payload->>'assigned_helper_code',
    p_payload#>>'{assignment_payload,helper_code}'
  ), '');

  v_vehicle_code := nullif(coalesce(
    p_payload->>'vehicle_code',
    p_payload->>'vehicle_name',
    p_payload->>'fleet_code',
    p_payload->>'assigned_vehicle_code',
    p_payload#>>'{assignment_payload,vehicle_code}'
  ), '');

  v_actor_email := nullif(coalesce(
    p_payload->>'actor_email',
    p_payload->>'assigned_by_email',
    p_payload->>'user_email',
    'supervisor@britiumexpress.com'
  ), '');

  if v_pickup_id is null then
    return jsonb_build_object(
      'ok', false,
      'error', 'pickup_id / pickup_way_id is required',
      'payload', p_payload
    );
  end if;

  if v_rider_code is null and v_driver_code is null then
    return jsonb_build_object(
      'ok', false,
      'error', 'rider_code or driver_code is required',
      'pickup_id', v_pickup_id,
      'payload', p_payload
    );
  end if;

  select display_name
  into v_rider_name
  from public.be_mobile_workforce_accounts
  where lower(coalesce(workforce_type, role_type, role, '')) = 'rider'
    and lower(coalesce(workforce_code, rider_code, worker_id, display_name, '')) = lower(v_rider_code)
  limit 1;

  select display_name
  into v_driver_name
  from public.be_mobile_workforce_accounts
  where lower(coalesce(workforce_type, role_type, role, '')) = 'driver'
    and lower(coalesce(workforce_code, rider_code, worker_id, display_name, '')) = lower(v_driver_code)
  limit 1;

  select display_name
  into v_helper_name
  from public.be_mobile_workforce_accounts
  where lower(coalesce(workforce_type, role_type, role, '')) = 'helper'
    and lower(coalesce(workforce_code, rider_code, worker_id, display_name, '')) = lower(v_helper_code)
  limit 1;

  v_assignment_payload := jsonb_build_object(
    'pickup_id', v_pickup_id,
    'pickup_way_id', v_pickup_id,
    'rider_code', v_rider_code,
    'rider_name', coalesce(v_rider_name, p_payload->>'rider_name', ''),
    'driver_code', v_driver_code,
    'driver_name', coalesce(v_driver_name, p_payload->>'driver_name', ''),
    'helper_code', v_helper_code,
    'helper_name', coalesce(v_helper_name, p_payload->>'helper_name', ''),
    'vehicle_code', v_vehicle_code,
    'vehicle_name', coalesce(p_payload->>'vehicle_name', v_vehicle_code, ''),
    'actor_email', v_actor_email
  );

  update public.be_portal_pickup_requests
  set
    assigned_rider_code = v_rider_code,
    assigned_rider_name = coalesce(v_rider_name, p_payload->>'rider_name', assigned_rider_name),
    assigned_driver_code = v_driver_code,
    assigned_driver_name = coalesce(v_driver_name, p_payload->>'driver_name', assigned_driver_name),
    assigned_helper_code = v_helper_code,
    assigned_helper_name = coalesce(v_helper_name, p_payload->>'helper_name', assigned_helper_name),
    assigned_vehicle_code = v_vehicle_code,
    assigned_vehicle_name = coalesce(p_payload->>'vehicle_name', v_vehicle_code, assigned_vehicle_name),
    assigned_workforce_code = coalesce(v_rider_code, v_driver_code, v_helper_code),
    assigned_workforce_name = coalesce(v_rider_name, v_driver_name, v_helper_name, assigned_workforce_name),
    assigned_workforce_type = case
      when v_rider_code is not null then 'rider'
      when v_driver_code is not null then 'driver'
      when v_helper_code is not null then 'helper'
      else assigned_workforce_type
    end,
    assigned_by_email = v_actor_email,
    assigned_at = now(),

    pickup_status = 'RIDER_ASSIGNED',
    workflow_stage = 'RIDER_APP_QUEUE',
    rider_app_stage = 'ASSIGNED_PICKUP',
    supervisor_status = 'ASSIGNED',
    rider_status = 'WAITING_ACCEPTANCE',
    status = 'ASSIGNED',
    wayplan_status = coalesce(nullif(wayplan_status, ''), 'PENDING_WAYPLAN'),

    metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
      'assigned_at', now(),
      'assigned_by_email', v_actor_email,
      'assignment_payload', v_assignment_payload
    ),
    payload = coalesce(payload, '{}'::jsonb) || jsonb_build_object(
      'assignment_payload', v_assignment_payload
    ),
    updated_at = now()
  where pickup_way_id = v_pickup_id
     or pickup_id = v_pickup_id
     or request_code = v_pickup_id;

  get diagnostics v_updated = row_count;

  if v_updated = 0 then
    return jsonb_build_object(
      'ok', false,
      'error', 'Pickup not found or not updated',
      'pickup_id', v_pickup_id,
      'payload', p_payload
    );
  end if;

  /*
    Normalize old assignment notification from the supervisor-job path.
    These rows already exist, but target_user_code was null.
  */
  update public.be_app_notifications n
  set
    target_role = case when target_role is null then 'rider' else target_role end,
    target_user_code = coalesce(
      target_user_code,
      metadata#>>'{assignment,payload,rider_code}',
      v_rider_code
    ),
    target_workforce_code = coalesce(
      target_workforce_code,
      metadata#>>'{assignment,payload,rider_code}',
      v_rider_code
    ),
    notification_type = case
      when target_role = 'rider' or metadata#>>'{assignment,payload,rider_code}' is not null
      then 'PICKUP_ASSIGNMENT'
      else notification_type
    end,
    status = coalesce(nullif(status, ''), 'unread'),
    is_read = coalesce(is_read, false),
    metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
      'next_action', 'PICKUP_VERIFY',
      'workflow_stage', 'RIDER_APP_QUEUE',
      'source', 'be_supervisor_assign_job_patch'
    ),
    payload = coalesce(payload, '{}'::jsonb) || jsonb_build_object(
      'pickup_id', v_pickup_id,
      'pickup_way_id', v_pickup_id,
      'rider_code', v_rider_code,
      'next_action', 'PICKUP_VERIFY'
    )
  where pickup_id = v_pickup_id
     or pickup_way_id = v_pickup_id
     or source_key = v_pickup_id
     or event_key ilike '%' || v_pickup_id || '%';

  return jsonb_build_object(
    'ok', true,
    'source', 'be_supervisor_assign_job',
    'pickup_id', v_pickup_id,
    'pickup_way_id', v_pickup_id,
    'assigned_rider_code', v_rider_code,
    'assigned_rider_name', v_rider_name,
    'assigned_driver_code', v_driver_code,
    'assigned_helper_code', v_helper_code,
    'assigned_vehicle_code', v_vehicle_code,
    'updated_rows', v_updated,
    'status', 'RIDER_ASSIGNED',
    'workflow_stage', 'RIDER_APP_QUEUE',
    'rider_app_stage', 'ASSIGNED_PICKUP',
    'rider_status', 'WAITING_ACCEPTANCE'
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_supervisor_assign_job(p_pickup_id text, p_job_type text, p_rider_id text DEFAULT NULL::text, p_driver_id text DEFAULT NULL::text, p_helper_id text DEFAULT NULL::text, p_vehicle_code text DEFAULT NULL::text, p_assigned_by text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_pickup public.be_portal_pickup_requests;
  v_types text[];
  v_type text;
  v_job public.be_supervisor_job_assignments;
begin
  select * into v_pickup
  from public.be_portal_pickup_requests
  where pickup_id = p_pickup_id;

  if v_pickup.pickup_id is null then
    raise exception 'Pickup ID % not found', p_pickup_id;
  end if;

  if p_job_type = 'both' then
    v_types := array['order_picking', 'delivery'];
  else
    v_types := array[p_job_type];
  end if;

  foreach v_type in array v_types loop
    insert into public.be_supervisor_job_assignments (
      pickup_id,
      job_type,
      status,
      rider_id,
      driver_id,
      helper_id,
      vehicle_code,
      notes,
      assigned_by
    )
    values (
      p_pickup_id,
      v_type,
      'assigned',
      p_rider_id,
      p_driver_id,
      p_helper_id,
      p_vehicle_code,
      p_notes,
      p_assigned_by
    )
    on conflict (pickup_id, job_type) do update set
      status = 'assigned',
      rider_id = excluded.rider_id,
      driver_id = excluded.driver_id,
      helper_id = excluded.helper_id,
      vehicle_code = excluded.vehicle_code,
      notes = excluded.notes,
      assigned_by = excluded.assigned_by,
      assigned_at = now(),
      updated_at = now()
    returning * into v_job;

    if v_type = 'order_picking' then
      insert into public.be_order_picking_jobs (
        pickup_id,
        status,
        rider_id,
        driver_id,
        helper_id,
        vehicle_code,
        notes,
        assigned_by
      )
      values (
        p_pickup_id,
        'assigned',
        p_rider_id,
        p_driver_id,
        p_helper_id,
        p_vehicle_code,
        p_notes,
        p_assigned_by
      )
      on conflict (pickup_id) do update set
        status = 'assigned',
        rider_id = excluded.rider_id,
        driver_id = excluded.driver_id,
        helper_id = excluded.helper_id,
        vehicle_code = excluded.vehicle_code,
        notes = excluded.notes,
        assigned_by = excluded.assigned_by,
        assigned_at = now(),
        updated_at = now();
    end if;

    insert into public.be_portal_cargo_events (
      pickup_id,
      job_id,
      event_type,
      status,
      actor_role,
      actor_id,
      notes,
      metadata
    )
    values (
      p_pickup_id,
      v_job.job_id,
      'supervisor_job_assigned',
      'assigned',
      'supervisor',
      p_assigned_by,
      p_notes,
      jsonb_build_object(
        'job_type', v_type,
        'rider_id', p_rider_id,
        'driver_id', p_driver_id,
        'helper_id', p_helper_id,
        'vehicle_code', p_vehicle_code
      )
    );

    insert into public.be_app_notifications (
      pickup_id,
      source_table,
      source_key,
      target_role,
      target_user_id,
      target_branch,
      title,
      body,
      metadata
    )
    values
      (p_pickup_id, 'be_supervisor_job_assignments', v_job.job_id, 'rider', p_rider_id, v_pickup.branch_code, 'New supervisor assignment', 'You have a new ' || v_type || ' job for pickup ' || p_pickup_id, jsonb_build_object('job_id', v_job.job_id, 'job_type', v_type)),
      (p_pickup_id, 'be_supervisor_job_assignments', v_job.job_id, 'driver', p_driver_id, v_pickup.branch_code, 'New supervisor assignment', 'You have a new ' || v_type || ' job for pickup ' || p_pickup_id, jsonb_build_object('job_id', v_job.job_id, 'job_type', v_type)),
      (p_pickup_id, 'be_supervisor_job_assignments', v_job.job_id, 'helper', p_helper_id, v_pickup.branch_code, 'New supervisor assignment', 'You have a new ' || v_type || ' job for pickup ' || p_pickup_id, jsonb_build_object('job_id', v_job.job_id, 'job_type', v_type));
  end loop;

  update public.be_portal_pickup_requests
  set
    status = 'assigned',
    assignment_status = 'assigned',
    rider_id = p_rider_id,
    driver_id = p_driver_id,
    helper_id = p_helper_id,
    vehicle_code = p_vehicle_code,
    assigned_by = p_assigned_by,
    assigned_at = now(),
    supervisor_note = p_notes
  where pickup_id = p_pickup_id;

  return jsonb_build_object(
    'ok', true,
    'pickup_id', p_pickup_id,
    'job_type', p_job_type
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_supervisor_assign_pickup(p_pickup_id text, p_rider_email text, p_driver_email text DEFAULT NULL::text, p_helper_email text DEFAULT NULL::text, p_vehicle_id text DEFAULT NULL::text, p_actor_email text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_old_status text;
  v_rider_email text;
  v_driver_email text;
  v_helper_email text;
  v_rider_code text;
  v_driver_code text;
  v_helper_code text;
  v_rider_name text;
  v_driver_name text;
  v_helper_name text;
begin
  select pickup_status
  into v_old_status
  from public.be_portal_pickup_requests
  where pickup_id = p_pickup_id
  limit 1;

  if v_old_status is null then
    raise exception 'Pickup ID not found: %', p_pickup_id;
  end if;

  select resolved_email, resolved_code, resolved_name
  into v_rider_email, v_rider_code, v_rider_name
  from public.be_resolve_workforce_identifier(p_rider_email, 'RIDER');

  if v_rider_email is null and v_rider_code is null then
    raise exception 'Active Rider not found by email/code: %', p_rider_email;
  end if;

  if p_driver_email is not null and btrim(p_driver_email) <> '' then
    select resolved_email, resolved_code, resolved_name
    into v_driver_email, v_driver_code, v_driver_name
    from public.be_resolve_workforce_identifier(p_driver_email, 'DRIVER');
  end if;

  if p_helper_email is not null and btrim(p_helper_email) <> '' then
    select resolved_email, resolved_code, resolved_name
    into v_helper_email, v_helper_code, v_helper_name
    from public.be_resolve_workforce_identifier(p_helper_email, 'HELPER');
  end if;

  update public.be_portal_pickup_requests
  set
    workflow_stage = 'RIDER_ASSIGNED',
    pickup_status = 'RIDER_ASSIGNED',
    supervisor_status = 'ASSIGNED',
    rider_status = 'ASSIGNED',
    data_entry_status = 'WAITING_PICKUP',
    warehouse_status = 'WAITING_DATA_ENTRY',
    wayplan_status = 'WAITING_WAREHOUSE',
    dispatch_status = 'WAITING_WAYPLAN',
    assigned_rider_email = v_rider_email,
    assigned_driver_email = v_driver_email,
    assigned_helper_email = v_helper_email,
    assigned_rider_code = coalesce(v_rider_code, p_rider_email),
    assigned_driver_code = v_driver_code,
    assigned_helper_code = v_helper_code,
    assigned_vehicle_id = p_vehicle_id,
    assigned_fleet_id = p_vehicle_id,
    assigned_by_email = p_actor_email,
    assigned_at = now(),
    supervisor_note = nullif(coalesce(supervisor_note, ''), ''),
    last_event_at = now(),
    last_event_by = p_actor_email,
    last_event_note = 'Supervisor assigned pickup workforce',
    updated_at = now()
  where pickup_id = p_pickup_id;

  update public.be_app_notifications
  set is_read = true, read_at = now()
  where pickup_id = p_pickup_id
    and recipient_role = 'supervisor'
    and notification_type = 'PICKUP_REQUESTED';

  insert into public.be_app_notifications (
    recipient_role,
    recipient_email,
    notification_type,
    title,
    message,
    entity_type,
    entity_id,
    pickup_id,
    priority,
    is_read,
    payload,
    created_at
  )
  values
    (
      'rider',
      v_rider_email,
      'PICKUP_ASSIGNED',
      'Pickup assigned',
      'Pickup assigned to rider: ' || p_pickup_id,
      'pickup',
      p_pickup_id,
      p_pickup_id,
      'HIGH',
      false,
      jsonb_build_object('pickup_id', p_pickup_id, 'role', 'RIDER', 'workforce_code', v_rider_code, 'workforce_name', v_rider_name),
      now()
    ),
    (
      'driver',
      v_driver_email,
      'PICKUP_ASSIGNED',
      'Pickup assigned',
      'Pickup assigned to driver: ' || p_pickup_id,
      'pickup',
      p_pickup_id,
      p_pickup_id,
      'HIGH',
      false,
      jsonb_build_object('pickup_id', p_pickup_id, 'role', 'DRIVER', 'workforce_code', v_driver_code, 'workforce_name', v_driver_name),
      now()
    ),
    (
      'helper',
      v_helper_email,
      'PICKUP_ASSIGNED',
      'Pickup assigned',
      'Pickup assigned to helper: ' || p_pickup_id,
      'pickup',
      p_pickup_id,
      p_pickup_id,
      'NORMAL',
      false,
      jsonb_build_object('pickup_id', p_pickup_id, 'role', 'HELPER', 'workforce_code', v_helper_code, 'workforce_name', v_helper_name),
      now()
    )
  on conflict do nothing;

  delete from public.be_app_notifications
  where pickup_id = p_pickup_id
    and notification_type = 'PICKUP_ASSIGNED'
    and (
      (recipient_role = 'driver' and recipient_email is null)
      or (recipient_role = 'helper' and recipient_email is null)
    );

  perform public.be_log_operational_event(
    'pickup',
    p_pickup_id,
    p_pickup_id,
    null,
    null,
    v_old_status,
    'RIDER_ASSIGNED',
    p_actor_email,
    'supervisor',
    'Supervisor assigned rider/driver/helper',
    jsonb_build_object(
      'rider_email', v_rider_email,
      'rider_code', v_rider_code,
      'driver_email', v_driver_email,
      'driver_code', v_driver_code,
      'helper_email', v_helper_email,
      'helper_code', v_helper_code,
      'vehicle_id', p_vehicle_id
    )
  );

  return jsonb_build_object(
    'ok', true,
    'pickup_id', p_pickup_id,
    'status', 'RIDER_ASSIGNED',
    'assigned_rider_email', v_rider_email,
    'assigned_driver_email', v_driver_email,
    'assigned_helper_email', v_helper_email,
    'assigned_rider_code', v_rider_code,
    'assigned_driver_code', v_driver_code,
    'assigned_helper_code', v_helper_code,
    'assigned_vehicle_id', p_vehicle_id
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_supervisor_assign_rider(p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_type text := coalesce(p_payload->>'type','pickup');
  v_id text := coalesce(p_payload->>'id','');
  v_rider_id text := coalesce(p_payload->>'rider_id','');
  v_rider_name text := coalesce(p_payload->>'rider_name','');
  v_count integer := 0;
begin
  if v_id = '' then
    raise exception 'id is required';
  end if;

  if v_type = 'pickup' then
    update public.be_portal_pickup_requests
    set assigned_rider_id = v_rider_id,
        assigned_rider_name = v_rider_name,
        supervisor_status = 'PICKUP_ASSIGNED',
        wayplan_status = 'PICKUP_ASSIGNED',
        assigned_at = now()
    where pickup_id = v_id or pickup_way_id = v_id;
  else
    update public.be_data_entry_parcel_details
    set assigned_rider_id = v_rider_id,
        assigned_rider_name = v_rider_name,
        supervisor_status = 'DELIVERY_ASSIGNED',
        way_management_status = 'DELIVERY_ASSIGNED',
        updated_at = now()
    where delivery_way_id = v_id or way_id = v_id or pickup_id = v_id;
  end if;

  get diagnostics v_count = row_count;

  insert into public.be_waybill_status_events(
    waybill_no, pickup_id, event_code, event_name, actor, source_module, note, payload
  )
  values (
    case when v_type = 'dropoff' then v_id else null end,
    case when v_type = 'pickup' then v_id else null end,
    case when v_type = 'pickup' then 'PICKUP_ASSIGNED' else 'DELIVERY_ASSIGNED' end,
    case when v_type = 'pickup' then 'Pickup Assigned' else 'Delivery Assigned' end,
    v_rider_name,
    'SUPERVISOR_PORTAL',
    'Assigned rider from supervisor portal',
    p_payload
  );

  return jsonb_build_object('ok', true, 'updated_count', v_count);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_supervisor_assignment_queue(p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select public.be_supervisor_pickup_queue(p_limit);
$function$
;

CREATE OR REPLACE FUNCTION public.be_supervisor_assignment_snapshot()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'ok', true,
    'pickups', coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc nulls last), '[]'::jsonb)
  )
  from (
    select *
    from public.be_v_supervisor_pickup_queue
    where upper(coalesce(pickup_status, status, 'PENDING')) not in ('DELIVERED','CANCELLED','REJECTED','RTO')
    limit 300
  ) x;
$function$
;

CREATE OR REPLACE FUNCTION public.be_supervisor_confirm_dispatch(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ select public.be_supervisor_assign_job(p_payload); $function$
;

CREATE OR REPLACE FUNCTION public.be_supervisor_dispatch_wayplan(p_wayplan_id text, p_rider_id text DEFAULT NULL::text, p_driver_id text DEFAULT NULL::text, p_helper_id text DEFAULT NULL::text, p_vehicle_code text DEFAULT NULL::text, p_actor_id text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_stop record;
begin
  if not exists (select 1 from public.be_wayplans where wayplan_id = p_wayplan_id) then
    raise exception 'Wayplan ID % not found', p_wayplan_id;
  end if;

  update public.be_wayplans
  set
    status = 'dispatched',
    rider_id = p_rider_id,
    driver_id = p_driver_id,
    helper_id = p_helper_id,
    vehicle_code = p_vehicle_code,
    dispatched_at = now(),
    updated_at = now()
  where wayplan_id = p_wayplan_id;

  for v_stop in
    select *
    from public.be_wayplan_stops
    where wayplan_id = p_wayplan_id
    order by stop_no
  loop
    insert into public.be_delivery_jobs (
      pickup_id,
      wayplan_id,
      stop_id,
      status,
      rider_id,
      driver_id,
      helper_id,
      vehicle_code,
      notes,
      assigned_by
    )
    values (
      v_stop.pickup_id,
      p_wayplan_id,
      v_stop.id,
      'assigned',
      p_rider_id,
      p_driver_id,
      p_helper_id,
      p_vehicle_code,
      p_notes,
      p_actor_id
    );

    update public.be_wayplan_stops
    set status = 'dispatched'
    where id = v_stop.id;

    update public.be_portal_pickup_requests
    set
      status = 'dispatch_assigned',
      rider_id = p_rider_id,
      driver_id = p_driver_id,
      helper_id = p_helper_id,
      vehicle_code = p_vehicle_code
    where pickup_id = v_stop.pickup_id;

    insert into public.be_portal_cargo_events (
      pickup_id,
      wayplan_id,
      event_type,
      status,
      actor_role,
      actor_id,
      notes,
      metadata
    )
    values (
      v_stop.pickup_id,
      p_wayplan_id,
      'fleet_dispatched',
      'assigned',
      'supervisor',
      p_actor_id,
      p_notes,
      jsonb_build_object(
        'rider_id', p_rider_id,
        'driver_id', p_driver_id,
        'helper_id', p_helper_id,
        'vehicle_code', p_vehicle_code
      )
    );
  end loop;

  insert into public.be_app_notifications (
    wayplan_id,
    source_table,
    source_key,
    target_role,
    target_user_id,
    title,
    body,
    metadata
  )
  values
    (p_wayplan_id, 'be_wayplans', p_wayplan_id, 'rider', p_rider_id, 'Wayplan dispatched', 'Wayplan ' || p_wayplan_id || ' has been dispatched to you.', jsonb_build_object('wayplan_id', p_wayplan_id)),
    (p_wayplan_id, 'be_wayplans', p_wayplan_id, 'driver', p_driver_id, 'Wayplan dispatched', 'Wayplan ' || p_wayplan_id || ' has been dispatched to you.', jsonb_build_object('wayplan_id', p_wayplan_id)),
    (p_wayplan_id, 'be_wayplans', p_wayplan_id, 'helper', p_helper_id, 'Wayplan dispatched', 'Wayplan ' || p_wayplan_id || ' has been dispatched to you.', jsonb_build_object('wayplan_id', p_wayplan_id));

  return jsonb_build_object(
    'ok', true,
    'wayplan_id', p_wayplan_id
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_supervisor_generate_wayplan(p_pickup_ids text[], p_created_by text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_wayplan_id text;
  v_pickup_id text;
  v_stop_no integer := 0;
  v_pickup public.be_portal_pickup_requests;
begin
  if array_length(p_pickup_ids, 1) is null then
    raise exception 'At least one pickup ID is required';
  end if;

  v_wayplan_id := 'WP-' || to_char(now(), 'YYYYMMDD') || '-' || upper(substr(gen_random_uuid()::text, 1, 6));

  insert into public.be_wayplans (
    wayplan_id,
    status,
    pickup_count,
    stop_count,
    notes,
    created_by
  )
  values (
    v_wayplan_id,
    'planned',
    array_length(p_pickup_ids, 1),
    array_length(p_pickup_ids, 1),
    p_notes,
    p_created_by
  );

  foreach v_pickup_id in array p_pickup_ids loop
    select * into v_pickup
    from public.be_portal_pickup_requests
    where pickup_id = v_pickup_id;

    if v_pickup.pickup_id is not null then
      v_stop_no := v_stop_no + 1;

      insert into public.be_wayplan_stops (
        wayplan_id,
        pickup_id,
        stop_no,
        merchant_name,
        pickup_address,
        township,
        cod_amount,
        status
      )
      values (
        v_wayplan_id,
        v_pickup_id,
        v_stop_no,
        v_pickup.merchant_name,
        v_pickup.pickup_address,
        v_pickup.township,
        v_pickup.cod_amount,
        'planned'
      )
      on conflict (wayplan_id, pickup_id) do nothing;

      update public.be_portal_pickup_requests
      set status = 'wayplan_generated'
      where pickup_id = v_pickup_id;

      insert into public.be_portal_cargo_events (
        pickup_id,
        wayplan_id,
        event_type,
        status,
        actor_role,
        actor_id,
        notes
      )
      values (
        v_pickup_id,
        v_wayplan_id,
        'wayplan_generated',
        'planned',
        'supervisor',
        p_created_by,
        p_notes
      );
    end if;
  end loop;

  return jsonb_build_object(
    'ok', true,
    'wayplan_id', v_wayplan_id,
    'pickup_count', array_length(p_pickup_ids, 1)
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_supervisor_live_gps_snapshot()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
with riders as (
  select distinct
    d.rider_code,
    d.rider_name,
    d.vehicle_code,
    d.vehicle_name,
    d.driver_code,
    d.driver_name,
    d.helper_code,
    d.helper_name,
    d.wayplan_id,
    d.wayplan_status,
    d.handed_over_to_rider_at,
    d.dispatched_at,
    count(s.*) as total_stops,
    count(*) filter (where s.stop_status = 'DELIVERED') as delivered_stops,
    count(*) filter (where s.stop_status = 'HANDOVER_TO_RIDER') as active_stops
  from public.be_wayplan_dispatches d
  left join public.be_wayplan_dispatch_stops s
    on s.wayplan_id = d.wayplan_id
  where nullif(d.rider_code, '') is not null
  group by
    d.rider_code,
    d.rider_name,
    d.vehicle_code,
    d.vehicle_name,
    d.driver_code,
    d.driver_name,
    d.helper_code,
    d.helper_name,
    d.wayplan_id,
    d.wayplan_status,
    d.handed_over_to_rider_at,
    d.dispatched_at
)
select jsonb_build_object(
  'ok', true,
  'source', 'be_supervisor_live_gps_snapshot',
  'count', count(*),
  'riders', coalesce(jsonb_agg(to_jsonb(riders) order by rider_code), '[]'::jsonb),
  'mapbox_required', true,
  'note', 'Use Mapbox token in frontend env; backend provides active rider and wayplan state.'
)
from riders;
$function$
;

