CREATE OR REPLACE FUNCTION public.be_supervisor_pickup_assignment_queue(p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
AS $function$ select public.be_pending_pickup_assignment_list('', p_limit); $function$
;

CREATE OR REPLACE FUNCTION public.be_supervisor_pickup_queue(p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'ok', true,
    'count', count(*),
    'items', coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc), '[]'::jsonb),
    'data', coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc), '[]'::jsonb),
    'queue', coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc), '[]'::jsonb)
  )
  from (
    select
      id,
      pickup_id,
      pickup_way_id,
      merchant_code,
      merchant_name,
      sender_name,
      sender_phone,
      contact_person,
      pickup_address,
      address,
      township,
      pickup_township,
      pickup_city,
      pickup_date,
      parcel_count,
      expected_parcel_count,
      required_vehicle,
      branch,
      assigned_branch,
      route_zone,
      assigned_rider_code,
      assigned_rider_name,
      assigned_driver_code,
      assigned_driver_name,
      assigned_helper_code,
      assigned_helper_name,
      assigned_vehicle_code,
      assigned_vehicle_name,
      pickup_status,
      status,
      data_entry_status,
      assignment_status,
      warehouse_status,
      finance_status,
      remarks,
      payload,
      metadata,
      created_at,
      updated_at
    from public.be_portal_pickup_requests
    where lower(coalesce(status, '')) not in ('closed', 'cancelled', 'pickup_cancelled')
      and lower(coalesce(assignment_status, 'pending_assignment')) in ('pending_assignment', 'pending', 'requested', 'pickup_requested', 'assigned')
    order by
      case when lower(coalesce(assignment_status, 'pending_assignment')) in ('pending_assignment', 'pending', 'requested', 'pickup_requested') then 0 else 1 end,
      created_at desc nulls last
    limit greatest(1, least(coalesce(p_limit, 50), 200))
  ) x;
$function$
;

CREATE OR REPLACE FUNCTION public.be_supervisor_portal_snapshot()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_pickups jsonb;
  v_workforce jsonb;
  v_assignments jsonb;
  v_wayplans jsonb;
  v_events jsonb;
begin
  select coalesce(jsonb_agg(to_jsonb(p) order by p.created_at desc), '[]'::jsonb)
  into v_pickups
  from public.be_portal_pickup_requests p;

  select coalesce(jsonb_agg(to_jsonb(w) order by w.role, w.full_name), '[]'::jsonb)
  into v_workforce
  from public.be_mobile_workforce_accounts w
  where coalesce(w.active, true) = true;

  select coalesce(jsonb_agg(to_jsonb(a) order by a.assigned_at desc), '[]'::jsonb)
  into v_assignments
  from public.be_supervisor_job_assignments a;

  select coalesce(jsonb_agg(to_jsonb(wp) order by wp.created_at desc), '[]'::jsonb)
  into v_wayplans
  from public.be_wayplans wp;

  select coalesce(jsonb_agg(to_jsonb(e) order by e.created_at desc), '[]'::jsonb)
  into v_events
  from (
    select *
    from public.be_portal_cargo_events
    order by created_at desc
    limit 150
  ) e;

  return jsonb_build_object(
    'pickups', v_pickups,
    'workforce', v_workforce,
    'assignments', v_assignments,
    'wayplans', v_wayplans,
    'cargo_events', v_events
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_supervisor_snapshot()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare q jsonb; pending int; assigned int;
begin
  q := public.be_supervisor_pickup_queue(200);
  select count(*) into pending from public.be_portal_pickup_requests where coalesce(assignment_status,'pending_assignment')='pending_assignment';
  select count(*) into assigned from public.be_portal_pickup_requests where coalesce(assignment_status,'')='assigned';
  return jsonb_build_object('ok',true,'status','ready','pending_assignment',pending,'assigned',assigned,'queue',q->'pickups','pickups',q->'pickups');
end; $function$
;

CREATE OR REPLACE FUNCTION public.be_supervisor_workforce_options()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'ok', true,

    'riders', coalesce((
      select jsonb_agg(jsonb_build_object(
        'value', record_key,
        'label', coalesce(payload ->> 'rider_name', payload ->> 'name', record_key),
        'code', record_key,
        'name', coalesce(payload ->> 'rider_name', payload ->> 'name', record_key),
        'phone', payload ->> 'phone_primary'
      ) order by record_key)
      from public.be_master_data_rows
      where dataset_key = 'rider_master'
        and deleted_at is null
        and lower(coalesce(payload ->> 'status', status, 'active')) <> 'inactive'
    ), '[]'::jsonb),

    'drivers', coalesce((
      select jsonb_agg(jsonb_build_object(
        'value', record_key,
        'label', coalesce(payload ->> 'driver_name', payload ->> 'name', record_key),
        'code', record_key,
        'name', coalesce(payload ->> 'driver_name', payload ->> 'name', record_key),
        'phone', payload ->> 'phone_primary'
      ) order by record_key)
      from public.be_master_data_rows
      where dataset_key = 'driver_master'
        and deleted_at is null
        and lower(coalesce(payload ->> 'status', status, 'active')) <> 'inactive'
    ), '[]'::jsonb),

    'helpers', coalesce((
      select jsonb_agg(jsonb_build_object(
        'value', record_key,
        'label', coalesce(payload ->> 'helper_name', payload ->> 'employee_name', payload ->> 'name', record_key),
        'code', record_key,
        'name', coalesce(payload ->> 'helper_name', payload ->> 'employee_name', payload ->> 'name', record_key),
        'phone', payload ->> 'phone_primary'
      ) order by record_key)
      from public.be_master_data_rows
      where dataset_key in ('helper_master', 'employee_master')
        and deleted_at is null
        and lower(coalesce(payload ->> 'status', status, 'active')) <> 'inactive'
        and (
          dataset_key = 'helper_master'
          or lower(coalesce(payload ->> 'role_id', '')) like '%warehouse helper%'
        )
    ), '[]'::jsonb),

    'vehicles', coalesce((
      select jsonb_agg(jsonb_build_object(
        'value', record_key,
        'label', concat_ws(
          ' · ',
          nullif(payload ->> 'vehicle_no', ''),
          nullif(payload ->> 'vehicle_type', ''),
          nullif(payload ->> 'capacity_kg', '') || ' kg'
        ),
        'code', record_key,
        'name', coalesce(payload ->> 'vehicle_no', payload ->> 'vehicle_name', payload ->> 'fleet_id', record_key),
        'vehicle_type', payload ->> 'vehicle_type',
        'capacity_kg', payload ->> 'capacity_kg'
      ) order by record_key)
      from public.be_master_data_rows
      where dataset_key = 'fleet_master'
        and deleted_at is null
        and record_key like 'FLT%'
        and coalesce(payload ->> 'vehicle_no', '') <> ''
    ), '[]'::jsonb)
  );
$function$
;

CREATE OR REPLACE FUNCTION public.be_sync_field_team_status_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_rider text;
  v_driver text;
  v_helper text;
begin
  if tg_op = 'INSERT' then
    new.rider_status := case
      when coalesce(nullif(trim(new.assigned_rider_code), ''), nullif(trim(new.assigned_rider_email), '')) is null then 'NOT_ASSIGNED'
      else coalesce(nullif(public.be_normalize_assignment_response_status(new.rider_status), ''), 'WAITING_ACCEPTANCE')
    end;
    new.driver_status := case
      when coalesce(nullif(trim(new.assigned_driver_code), ''), nullif(trim(new.assigned_driver_email), '')) is null then 'NOT_ASSIGNED'
      else coalesce(nullif(public.be_normalize_assignment_response_status(new.driver_status), ''), 'WAITING_ACCEPTANCE')
    end;
    new.helper_status := case
      when coalesce(nullif(trim(new.assigned_helper_code), ''), nullif(trim(new.assigned_helper_email), '')) is null then 'NOT_ASSIGNED'
      else coalesce(nullif(public.be_normalize_assignment_response_status(new.helper_status), ''), 'WAITING_ACCEPTANCE')
    end;
  else
    -- Only reset a role when the assigned person actually changes.
    if new.assigned_rider_code is distinct from old.assigned_rider_code
       or new.assigned_rider_email is distinct from old.assigned_rider_email then
      new.rider_status := case
        when coalesce(nullif(trim(new.assigned_rider_code), ''), nullif(trim(new.assigned_rider_email), '')) is null then 'NOT_ASSIGNED'
        else 'WAITING_ACCEPTANCE'
      end;
      new.rider_accepted_at := null;
      new.rider_rejected_at := null;
      new.rider_response_note := null;
    end if;

    if new.assigned_driver_code is distinct from old.assigned_driver_code
       or new.assigned_driver_email is distinct from old.assigned_driver_email then
      new.driver_status := case
        when coalesce(nullif(trim(new.assigned_driver_code), ''), nullif(trim(new.assigned_driver_email), '')) is null then 'NOT_ASSIGNED'
        else 'WAITING_ACCEPTANCE'
      end;
      new.driver_accepted_at := null;
      new.driver_rejected_at := null;
      new.driver_response_note := null;
    end if;

    if new.assigned_helper_code is distinct from old.assigned_helper_code
       or new.assigned_helper_email is distinct from old.assigned_helper_email then
      new.helper_status := case
        when coalesce(nullif(trim(new.assigned_helper_code), ''), nullif(trim(new.assigned_helper_email), '')) is null then 'NOT_ASSIGNED'
        else 'WAITING_ACCEPTANCE'
      end;
      new.helper_accepted_at := null;
      new.helper_rejected_at := null;
      new.helper_response_note := null;
    end if;
  end if;

  v_rider := case
    when coalesce(nullif(trim(new.assigned_rider_code), ''), nullif(trim(new.assigned_rider_email), '')) is null then 'NOT_ASSIGNED'
    else public.be_normalize_assignment_response_status(new.rider_status)
  end;
  v_driver := case
    when coalesce(nullif(trim(new.assigned_driver_code), ''), nullif(trim(new.assigned_driver_email), '')) is null then 'NOT_ASSIGNED'
    else public.be_normalize_assignment_response_status(new.driver_status)
  end;
  v_helper := case
    when coalesce(nullif(trim(new.assigned_helper_code), ''), nullif(trim(new.assigned_helper_email), '')) is null then 'NOT_ASSIGNED'
    else public.be_normalize_assignment_response_status(new.helper_status)
  end;

  new.rider_status := v_rider;
  new.driver_status := v_driver;
  new.helper_status := v_helper;

  if v_rider = 'REJECTED' or v_driver = 'REJECTED' or v_helper = 'REJECTED' then
    new.team_acceptance_status := 'NEEDS_REASSIGNMENT';
  elsif (
    (v_rider in ('ACCEPTED', 'NOT_ASSIGNED')) and
    (v_driver in ('ACCEPTED', 'NOT_ASSIGNED')) and
    (v_helper in ('ACCEPTED', 'NOT_ASSIGNED')) and
    (v_rider = 'ACCEPTED' or v_driver = 'ACCEPTED' or v_helper = 'ACCEPTED')
  ) then
    new.team_acceptance_status := 'TEAM_READY';
  elsif v_rider = 'NOT_ASSIGNED' and v_driver = 'NOT_ASSIGNED' and v_helper = 'NOT_ASSIGNED' then
    new.team_acceptance_status := 'NOT_ASSIGNED';
  else
    new.team_acceptance_status := 'WAITING_TEAM_ACCEPTANCE';
  end if;

  new.updated_at := now();
  return new;
end;
$function$
;

