CREATE OR REPLACE FUNCTION public.be_sync_waybill_to_finance_aiu()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_cod_id uuid;
  v_settlement_id text;
  v_invoice_id text;
begin
  if new.delivery_way_id is null or trim(new.delivery_way_id) = '' then
    return new;
  end if;

  insert into public.be_cod_ledger (
    pickup_id,
    pickup_way_id,
    delivery_way_id,
    merchant_code,
    merchant_name,
    recipient_name,
    cod_amount,
    cod_status,
    payload,
    updated_at
  )
  values (
    new.pickup_id,
    new.pickup_way_id,
    new.delivery_way_id,
    new.merchant_code,
    new.merchant_name,
    new.recipient_name,
    coalesce(new.finance_cod, new.final_cod, 0),
    case
      when coalesce(new.finance_cod, new.final_cod, 0) > 0 then 'pending_collection'
      else 'not_required'
    end,
    to_jsonb(new),
    now()
  )
  on conflict (delivery_way_id) do update set
    pickup_id = excluded.pickup_id,
    pickup_way_id = excluded.pickup_way_id,
    merchant_code = excluded.merchant_code,
    merchant_name = excluded.merchant_name,
    recipient_name = excluded.recipient_name,
    cod_amount = excluded.cod_amount,
    cod_status = case
      when public.be_cod_ledger.cod_status in ('handed_over_to_finance', 'finance_settled') then public.be_cod_ledger.cod_status
      else excluded.cod_status
    end,
    payload = coalesce(public.be_cod_ledger.payload, '{}'::jsonb) || excluded.payload,
    updated_at = now()
  returning cod_id into v_cod_id;

  insert into public.be_financial_settlements (
    pickup_id,
    pickup_way_id,
    delivery_way_id,
    cod_id,
    merchant_code,
    merchant_name,
    recipient_name,
    delivery_fee,
    gross_cod,
    finance_deli,
    finance_cod,
    settlement_status,
    payload,
    updated_at
  )
  values (
    new.pickup_id,
    new.pickup_way_id,
    new.delivery_way_id,
    v_cod_id,
    new.merchant_code,
    new.merchant_name,
    new.recipient_name,
    coalesce(new.finance_deli, new.deli_fee_os, 0),
    coalesce(new.finance_cod, new.final_cod, 0),
    coalesce(new.finance_deli, new.deli_fee_os, 0),
    coalesce(new.finance_cod, new.final_cod, 0),
    coalesce(new.finance_status, 'pending_finance'),
    to_jsonb(new),
    now()
  )
  on conflict (delivery_way_id) do update set
    cod_id = excluded.cod_id,
    pickup_id = excluded.pickup_id,
    pickup_way_id = excluded.pickup_way_id,
    merchant_code = excluded.merchant_code,
    merchant_name = excluded.merchant_name,
    recipient_name = excluded.recipient_name,
    delivery_fee = excluded.delivery_fee,
    gross_cod = excluded.gross_cod,
    finance_deli = excluded.finance_deli,
    finance_cod = excluded.finance_cod,
    settlement_status = case
      when public.be_financial_settlements.settlement_status = 'finance_settled' then public.be_financial_settlements.settlement_status
      else excluded.settlement_status
    end,
    payload = coalesce(public.be_financial_settlements.payload, '{}'::jsonb) || excluded.payload,
    updated_at = now()
  returning settlement_id into v_settlement_id;

  update public.be_cod_ledger
  set settlement_id = v_settlement_id,
      updated_at = now()
  where cod_id = v_cod_id;

  insert into public.be_customer_invoices (
    settlement_id,
    delivery_way_id,
    merchant_code,
    merchant_name,
    invoice_amount,
    invoice_status,
    payload,
    updated_at
  )
  values (
    v_settlement_id,
    new.delivery_way_id,
    new.merchant_code,
    new.merchant_name,
    coalesce(new.finance_deli, new.deli_fee_os, 0),
    'draft',
    to_jsonb(new),
    now()
  )
  on conflict (delivery_way_id) do update set
    settlement_id = excluded.settlement_id,
    merchant_code = excluded.merchant_code,
    merchant_name = excluded.merchant_name,
    invoice_amount = excluded.invoice_amount,
    payload = coalesce(public.be_customer_invoices.payload, '{}'::jsonb) || excluded.payload,
    updated_at = now()
  returning invoice_id into v_invoice_id;

  insert into public.be_enterprise_workflow_events (
    pickup_id,
    pickup_way_id,
    delivery_way_id,
    event_type,
    event_status,
    source_module,
    target_module,
    amount,
    payload
  )
  values (
    new.pickup_id,
    new.pickup_way_id,
    new.delivery_way_id,
    'DATA_ENTRY_TO_FINANCE_SYNC',
    coalesce(new.finance_status, 'pending_finance'),
    'data_entry',
    'finance',
    coalesce(new.finance_cod, new.final_cod, 0),
    jsonb_build_object(
      'cod_id', v_cod_id,
      'settlement_id', v_settlement_id,
      'invoice_id', v_invoice_id
    )
  );

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_sync_wayplan_cod_settlement()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_rider_code text;
  v_rider_name text;
begin
  if new.stop_status = 'DELIVERED'
     and coalesce(new.cod_collected, 0) >= 0 then

    select w.rider_code, w.rider_name
    into v_rider_code, v_rider_name
    from public.be_wayplan_dispatches w
    where w.wayplan_id = new.wayplan_id
    limit 1;

    insert into public.be_wayplan_cod_settlements (
      wayplan_id,
      delivery_way_id,
      waybill_no,
      pickup_id,
      rider_code,
      rider_name,
      recipient_name,
      recipient_phone,
      cod_expected,
      cod_collected,
      delivery_fee,
      settlement_status,
      delivered_at,
      metadata,
      created_at,
      updated_at
    )
    values (
      new.wayplan_id,
      new.delivery_way_id,
      new.waybill_no,
      new.pickup_id,
      v_rider_code,
      v_rider_name,
      coalesce(new.receiver_name, new.recipient_name),
      coalesce(new.receiver_phone, new.recipient_phone),
      coalesce(new.cod_amount, 0),
      coalesce(new.cod_collected, 0),
      coalesce(new.delivery_fee, 0),
      'PENDING_SETTLEMENT',
      new.delivered_at,
      jsonb_build_object(
        'source', 'be_wayplan_dispatch_stops',
        'stop_status', new.stop_status,
        'rider_status', new.rider_status,
        'rider_proof_url', new.rider_proof_url
      ),
      now(),
      now()
    )
    on conflict (wayplan_id, delivery_way_id) do update
    set
      rider_code = excluded.rider_code,
      rider_name = excluded.rider_name,
      recipient_name = excluded.recipient_name,
      recipient_phone = excluded.recipient_phone,
      cod_expected = excluded.cod_expected,
      cod_collected = excluded.cod_collected,
      delivery_fee = excluded.delivery_fee,
      delivered_at = excluded.delivered_at,
      metadata = excluded.metadata,
      updated_at = now();
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_sync_workforce_wallets()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_rider_count integer := 0;
  v_driver_count integer := 0;
  v_helper_count integer := 0;
begin
  insert into public.be_workforce_wallets (
    code,
    name,
    role,
    status,

    worker_code,
    worker_name,
    worker_role,
    wayplan_id,
    delivery_way_id,
    source,
    earning_type,
    amount,
    wallet_status,
    reference_no,
    metadata,
    earned_at,
    updated_at
  )
  select
    'WALLET-RIDER-' || s.delivery_way_id,
    d.rider_name,
    'RIDER',
    'active',

    d.rider_code,
    d.rider_name,
    'RIDER',
    s.wayplan_id,
    s.delivery_way_id,
    'WAYPLAN_DELIVERY',
    'COMMISSION',
    coalesce(r.base_rate, 500),
    'PENDING',
    'RIDER-' || s.delivery_way_id,
    jsonb_build_object(
      'source', 'be_sync_workforce_wallets',
      'rule_id', r.rule_id,
      'stop_status', s.stop_status,
      'cod_collected', coalesce(s.cod_collected, 0)
    ),
    coalesce(s.delivered_at, now()),
    now()
  from public.be_wayplan_dispatch_stops s
  join public.be_wayplan_dispatches d
    on d.wayplan_id = s.wayplan_id
  left join public.be_commission_rules r
    on r.role = 'RIDER'
   and r.is_active = true
  where s.stop_status = 'DELIVERED'
    and nullif(d.rider_code, '') is not null
  on conflict (worker_code, worker_role, delivery_way_id, earning_type) do update
  set
    code = excluded.code,
    name = excluded.name,
    role = excluded.role,
    status = excluded.status,
    worker_name = excluded.worker_name,
    amount = excluded.amount,
    metadata = excluded.metadata,
    updated_at = now();

  get diagnostics v_rider_count = row_count;

  insert into public.be_workforce_wallets (
    code,
    name,
    role,
    status,

    worker_code,
    worker_name,
    worker_role,
    wayplan_id,
    delivery_way_id,
    source,
    earning_type,
    amount,
    wallet_status,
    reference_no,
    metadata,
    earned_at,
    updated_at
  )
  select distinct
    'WALLET-DRIVER-' || d.wayplan_id,
    d.driver_name,
    'DRIVER',
    'active',

    d.driver_code,
    d.driver_name,
    'DRIVER',
    d.wayplan_id,
    d.wayplan_id,
    'WAYPLAN',
    'ALLOWANCE',
    coalesce(r.base_rate, 1000),
    'PENDING',
    'DRIVER-' || d.wayplan_id,
    jsonb_build_object(
      'source', 'be_sync_workforce_wallets',
      'rule_id', r.rule_id,
      'wayplan_status', d.wayplan_status
    ),
    coalesce(d.dispatched_at, d.created_at, now()),
    now()
  from public.be_wayplan_dispatches d
  left join public.be_commission_rules r
    on r.role = 'DRIVER'
   and r.is_active = true
  where nullif(d.driver_code, '') is not null
    and exists (
      select 1
      from public.be_wayplan_dispatch_stops s
      where s.wayplan_id = d.wayplan_id
    )
  on conflict (worker_code, worker_role, delivery_way_id, earning_type) do update
  set
    code = excluded.code,
    name = excluded.name,
    role = excluded.role,
    status = excluded.status,
    worker_name = excluded.worker_name,
    amount = excluded.amount,
    metadata = excluded.metadata,
    updated_at = now();

  get diagnostics v_driver_count = row_count;

  insert into public.be_workforce_wallets (
    code,
    name,
    role,
    status,

    worker_code,
    worker_name,
    worker_role,
    wayplan_id,
    delivery_way_id,
    source,
    earning_type,
    amount,
    wallet_status,
    reference_no,
    metadata,
    earned_at,
    updated_at
  )
  select distinct
    'WALLET-HELPER-' || d.wayplan_id,
    d.helper_name,
    'HELPER',
    'active',

    d.helper_code,
    d.helper_name,
    'HELPER',
    d.wayplan_id,
    d.wayplan_id,
    'WAYPLAN',
    'ALLOWANCE',
    coalesce(r.base_rate, 700),
    'PENDING',
    'HELPER-' || d.wayplan_id,
    jsonb_build_object(
      'source', 'be_sync_workforce_wallets',
      'rule_id', r.rule_id,
      'wayplan_status', d.wayplan_status
    ),
    coalesce(d.dispatched_at, d.created_at, now()),
    now()
  from public.be_wayplan_dispatches d
  left join public.be_commission_rules r
    on r.role = 'HELPER'
   and r.is_active = true
  where nullif(d.helper_code, '') is not null
    and exists (
      select 1
      from public.be_wayplan_dispatch_stops s
      where s.wayplan_id = d.wayplan_id
    )
  on conflict (worker_code, worker_role, delivery_way_id, earning_type) do update
  set
    code = excluded.code,
    name = excluded.name,
    role = excluded.role,
    status = excluded.status,
    worker_name = excluded.worker_name,
    amount = excluded.amount,
    metadata = excluded.metadata,
    updated_at = now();

  get diagnostics v_helper_count = row_count;

  return jsonb_build_object(
    'ok', true,
    'source', 'be_sync_workforce_wallets',
    'status', 'SYNCED',
    'rider_rows', v_rider_count,
    'driver_rows', v_driver_count,
    'helper_rows', v_helper_count
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_table_exists(p_table text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1
    from information_schema.tables
    where table_schema = 'public'
      and table_name = p_table
  );
$function$
;

CREATE OR REPLACE FUNCTION public.be_table_rows_json(p_table text, p_limit integer DEFAULT 300)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_sql text;
  v_order_col text;
  v_rows jsonb := '[]'::jsonb;
begin
  if not public.be_table_exists(p_table) then
    return '[]'::jsonb;
  end if;

  select column_name
  into v_order_col
  from information_schema.columns
  where table_schema = 'public'
    and table_name = p_table
    and column_name in ('updated_at', 'created_at', 'id')
  order by case column_name
    when 'updated_at' then 1
    when 'created_at' then 2
    when 'id' then 3
    else 9
  end
  limit 1;

  if v_order_col is null then
    v_sql := format(
      'select coalesce(jsonb_agg(to_jsonb(t)), ''[]''::jsonb)
       from (select * from public.%I limit $1) t',
      p_table
    );
  else
    v_sql := format(
      'select coalesce(jsonb_agg(to_jsonb(t) order by t.%I desc nulls last), ''[]''::jsonb)
       from (select * from public.%I order by %I desc nulls last limit $1) t',
      v_order_col,
      p_table,
      v_order_col
    );
  end if;

  execute v_sql into v_rows using greatest(coalesce(p_limit, 300), 1);

  return coalesce(v_rows, '[]'::jsonb);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_template_sync_row(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_module text := coalesce(p_payload->>'module', p_payload->>'module_name', 'data_entry');
  v_template text := coalesce(p_payload->>'template_code', 'parcel_import');
  v_merchant_code text := p_payload->>'merchant_code';
  v_autofill_data jsonb;
  v_result jsonb := p_payload;
BEGIN
  -- If a merchant code is passed, automatically fetch and merge the autofill data
  IF v_merchant_code IS NOT NULL THEN
    v_autofill_data := public.be_master_data_autofill(v_merchant_code);
    IF (v_autofill_data->>'ok')::boolean THEN
      v_result := v_result || v_autofill_data;
    END IF;
  END IF;

  -- Log the synchronization event
  INSERT INTO public.be_template_sync_events (
    module_name, template_code, merchant_code, row_payload, result_payload
  ) VALUES (
    v_module, v_template, v_merchant_code, p_payload, v_result
  );

  RETURN v_result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_template_sync_row(p_row json)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
   RETURN json_build_object('success', true, 'status', 'Synced');
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_text_first_nonempty(p_data jsonb, VARIADIC p_keys text[])
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  k text;
  v text;
begin
  foreach k in array p_keys loop
    v := nullif(trim(coalesce(p_data ->> k, '')), '');
    if v is not null and lower(v) not in ('null','undefined','nan') then
      return v;
    end if;
  end loop;
  return null;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_text_from_jsonb(p_row jsonb, p_keys text[])
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  k text;
  v jsonb;
  out_text text;
begin
  foreach k in array p_keys loop
    if p_row ? k then
      v := p_row -> k;
      if jsonb_typeof(v) = 'string' then
        out_text := p_row ->> k;
      elsif jsonb_typeof(v) = 'object' then
        out_text := concat_ws(', ',
          nullif(v ->> 'line1', ''),
          nullif(v ->> 'line_1', ''),
          nullif(v ->> 'address1', ''),
          nullif(v ->> 'address_1', ''),
          nullif(v ->> 'street', ''),
          nullif(v ->> 'street_address', ''),
          nullif(v ->> 'ward', ''),
          nullif(v ->> 'landmark', ''),
          nullif(v ->> 'township', ''),
          nullif(v ->> 'city', ''),
          nullif(v ->> 'region', '')
        );
      else
        out_text := p_row ->> k;
      end if;

      if nullif(trim(coalesce(out_text, '')), '') is not null then
        return trim(out_text);
      end if;
    end if;
  end loop;

  return '';
end;
$function$
;

