CREATE OR REPLACE FUNCTION public.be_try_update_pickupway_table(p_table_name text, p_pickup_way_id text, p_payload jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_reg regclass;
  v_schema text := 'public';
  v_set_parts text[] := array[]::text[];
  v_where_parts text[] := array[]::text[];
  v_key text;
  v_rows integer := 0;
  v_sql text;
  v_id_columns text[] := array[
    'pickup_way_id',
    'pickup_id',
    'pickup_request_id',
    'pickup_waybill_id',
    'request_code',
    'waybill_no',
    'tracking_no',
    'id'
  ];
begin
  v_reg := to_regclass(v_schema || '.' || quote_ident(p_table_name));
  if v_reg is null then
    return 0;
  end if;

  if public.be_validate_pickupway_id(p_pickup_way_id) is null then
    raise exception 'Invalid PickupWayID %. Expected format like P0611-BRV-001.', p_pickup_way_id;
  end if;

  for v_key in select jsonb_object_keys(coalesce(p_payload, '{}'::jsonb)) loop
    if exists (
      select 1
      from information_schema.columns
      where table_schema = v_schema
        and table_name = p_table_name
        and column_name = v_key
    ) then
      v_set_parts := array_append(v_set_parts, format('%I = %L', v_key, p_payload ->> v_key));
    end if;
  end loop;

  if exists (
    select 1
    from information_schema.columns
    where table_schema = v_schema
      and table_name = p_table_name
      and column_name = 'updated_at'
  ) and not (coalesce(p_payload, '{}'::jsonb) ? 'updated_at') then
    v_set_parts := array_append(v_set_parts, 'updated_at = now()');
  end if;

  foreach v_key in array v_id_columns loop
    if exists (
      select 1
      from information_schema.columns
      where table_schema = v_schema
        and table_name = p_table_name
        and column_name = v_key
    ) then
      v_where_parts := array_append(v_where_parts, format('%I::text = %L', v_key, upper(trim(p_pickup_way_id))));
    end if;
  end loop;

  if coalesce(array_length(v_set_parts, 1), 0) = 0 or coalesce(array_length(v_where_parts, 1), 0) = 0 then
    return 0;
  end if;

  v_sql := format(
    'update %s set %s where %s',
    v_reg,
    array_to_string(v_set_parts, ', '),
    array_to_string(v_where_parts, ' or ')
  );

  execute v_sql;
  get diagnostics v_rows = row_count;
  return coalesce(v_rows, 0);
end;
$function$
;

