CREATE OR REPLACE FUNCTION public.be_upsert_field_assignment_notification(p_pickup_id text, p_role text, p_target_user_id uuid, p_workforce_code text, p_workforce_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_event_key text;
  v_message text;
  v_row public.be_app_notifications;
begin
  if p_workforce_code is null or trim(p_workforce_code) = '' then
    return jsonb_build_object('ok', true, 'skipped', true);
  end if;

  v_event_key := p_pickup_id || ':assigned:' || p_role || ':' || p_workforce_code;
  v_message := 'Pickup ' || p_pickup_id || ' assigned to ' || coalesce(p_workforce_name, p_workforce_code) || '.';

  insert into public.be_app_notifications (
    notification_type, category, target_role, target_user_id, pickup_id, source_table, source_key,
    event_key, title, body, message, status, is_read, payload, metadata, created_at
  )
  values (
    'field_assignment', 'field_assignment', p_role, p_target_user_id, p_pickup_id, 'be_portal_pickup_requests', v_event_key,
    v_event_key, 'Pickup Assigned', v_message, v_message, 'unread', false,
    jsonb_build_object('pickup_id', p_pickup_id, 'pickup_request_id', p_pickup_id, 'event', 'assigned', 'workforce_code', p_workforce_code, 'workforce_name', p_workforce_name, 'workforce_type', p_role),
    '{}'::jsonb, now()
  )
  on conflict (event_key)
  do update set
    target_user_id = excluded.target_user_id,
    body = excluded.body,
    message = excluded.message,
    status = 'unread',
    is_read = false,
    payload = excluded.payload,
    created_at = now()
  returning * into v_row;

  return to_jsonb(v_row);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_user_account_registry_compat_before_write()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_uuid_regex CONSTANT text := '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
BEGIN
  IF new.id IS NULL THEN
    new.id := gen_random_uuid();
  END IF;

  IF new.user_id IS NULL AND new.auth_user_id IS NOT NULL THEN
    new.user_id := new.auth_user_id;
  END IF;

  IF new.auth_user_id IS NULL AND new.user_id IS NOT NULL THEN
    new.auth_user_id := new.user_id;
  END IF;

  -- For testing seed rows without a real Supabase auth user, generate a stable DB UUID.
  -- Production real users should still be linked by their actual auth.users.id.
  IF new.auth_user_id IS NULL THEN
    new.auth_user_id := gen_random_uuid();
  END IF;

  IF new.user_id IS NULL THEN
    new.user_id := new.auth_user_id;
  END IF;

  new.full_name := coalesce(nullif(btrim(new.full_name), ''), new.email, new.phone_number, 'User');
  new.role := coalesce(nullif(btrim(new.role), ''), 'staff');
  new.branch_code := coalesce(nullif(btrim(new.branch_code), ''), 'YGN');
  new.status := coalesce(nullif(btrim(new.status), ''), 'active');
  new.metadata := coalesce(new.metadata, '{}'::jsonb);
  new.created_at := coalesce(new.created_at, now());
  new.updated_at := now();

  RETURN new;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_user_registry_app_role_compat_verification()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_total int := 0;
  v_null_app_role int := 0;
  v_null_email int := 0;
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM information_schema.tables
    WHERE table_schema = 'public'
      AND table_name = 'be_user_account_registry'
  ) THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'be_user_account_registry table not found'
    );
  END IF;

  EXECUTE 'SELECT count(*) FROM public.be_user_account_registry'
    INTO v_total;

  EXECUTE 'SELECT count(*) FROM public.be_user_account_registry WHERE app_role IS NULL OR trim(app_role) = '''''
    INTO v_null_app_role;

  IF EXISTS (
    SELECT 1
    FROM information_schema.columns
    WHERE table_schema = 'public'
      AND table_name = 'be_user_account_registry'
      AND column_name = 'email'
  ) THEN
    EXECUTE 'SELECT count(*) FROM public.be_user_account_registry WHERE email IS NULL OR trim(email) = '''''
      INTO v_null_email;
  END IF;

  RETURN jsonb_build_object(
    'ok', v_null_app_role = 0,
    'total_registry_rows', v_total,
    'null_app_role_rows', v_null_app_role,
    'null_email_rows', v_null_email,
    'trigger_installed', EXISTS (
      SELECT 1 FROM pg_trigger WHERE tgname = 'trg_be_user_registry_fill_required_fields'
    )
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_user_registry_compat_verification()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'ok', true,
    'be_user_account_registry_exists', to_regclass('public.be_user_account_registry') IS NOT NULL,
    'has_user_id', EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema='public' AND table_name='be_user_account_registry' AND column_name='user_id'
    ),
    'has_auth_user_id', EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema='public' AND table_name='be_user_account_registry' AND column_name='auth_user_id'
    ),
    'user_count', coalesce((SELECT count(*) FROM public.be_user_account_registry), 0),
    'null_user_id_count', coalesce((SELECT count(*) FROM public.be_user_account_registry WHERE user_id IS NULL), 0),
    'null_auth_user_id_count', coalesce((SELECT count(*) FROM public.be_user_account_registry WHERE auth_user_id IS NULL), 0)
  )
  INTO v_result;

  RETURN v_result;
END;
$function$
;

