CREATE OR REPLACE FUNCTION public.be_user_registry_fill_required_fields()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  payload jsonb;
  inferred_role text;
  inferred_email text;
  inferred_user_id text;
BEGIN
  payload := to_jsonb(new);

  inferred_role := coalesce(
    public.be_normalize_registry_role_value(payload ->> 'app_role'),
    public.be_normalize_registry_role_value(payload ->> 'user_type'),
    public.be_normalize_registry_role_value(payload ->> 'role_type'),
    public.be_normalize_registry_role_value(payload ->> 'workforce_type'),
    public.be_normalize_registry_role_value(payload ->> 'account_type'),
    public.be_normalize_registry_role_value(payload ->> 'role'),
    'user'
  );

  new.app_role := coalesce(nullif(trim(new.app_role), ''), inferred_role, 'user');

  IF payload ? 'role' THEN
    new.role := coalesce(
      nullif(trim(new.role), ''),
      initcap(replace(new.app_role, '_', ' '))
    );
  END IF;

  IF payload ? 'email' THEN
    inferred_user_id := coalesce(
      nullif(payload ->> 'user_id', ''),
      nullif(payload ->> 'auth_user_id', ''),
      nullif(payload ->> 'account_code', ''),
      nullif(payload ->> 'employee_code', ''),
      nullif(payload ->> 'rider_code', ''),
      nullif(payload ->> 'driver_code', ''),
      nullif(payload ->> 'worker_id', ''),
      replace(coalesce(payload ->> 'full_name', 'user'), ' ', '-')
    );

    inferred_email := lower(
      regexp_replace(
        coalesce(new.app_role, 'user') || '-' || coalesce(inferred_user_id, gen_random_uuid()::text) || '@testing.britium.local',
        '[^a-zA-Z0-9@._-]+',
        '-',
        'g'
      )
    );

    new.email := coalesce(nullif(trim(new.email), ''), inferred_email);
  END IF;

  -- SAFELY handle user_id (UUID type) without trim()
  IF payload ? 'user_id' THEN
    IF new.user_id IS NULL THEN
      IF payload ->> 'auth_user_id' IS NOT NULL THEN
        BEGIN
          new.user_id := (payload ->> 'auth_user_id')::uuid;
        EXCEPTION WHEN OTHERS THEN
          new.user_id := gen_random_uuid();
        END;
      ELSE
        new.user_id := gen_random_uuid();
      END IF;
    END IF;
  END IF;

  IF payload ? 'auth_user_id' THEN
    new.auth_user_id := new.auth_user_id;
  END IF;

  RETURN new;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_user_registry_required_defaults_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_payload jsonb;
  v_base_email text;
  v_email text;
  v_counter integer := 0;
  v_current_id text;
BEGIN
  v_payload := to_jsonb(new);
  v_current_id := coalesce(v_payload->>'id', v_payload->>'user_id', v_payload->>'auth_user_id', '');

  -- Fill email before NOT NULL constraint is checked.
  IF new.email IS NULL OR btrim(new.email) = '' THEN
    v_base_email := public.be_registry_safe_email_from_row(v_payload);
    v_email := v_base_email;

    -- Avoid unique email collisions if the table has a unique index/constraint.
    WHILE EXISTS (
      SELECT 1
      FROM public.be_user_account_registry existing
      WHERE lower(existing.email) = lower(v_email)
        AND coalesce(existing.id::text, existing.user_id::text, existing.auth_user_id::text, '') <> v_current_id
    ) LOOP
      v_counter := v_counter + 1;
      v_email := regexp_replace(v_base_email, '@', '-' || v_counter::text || '@', 'g');
      EXIT WHEN v_counter > 50;
    END LOOP;

    new.email := v_email;
  END IF;

  -- Keep other common required fields safe for mixed old/new seed files.
  IF new.role IS NULL OR btrim(new.role) = '' THEN
    new.role := coalesce(nullif(v_payload->>'role_type', ''), nullif(v_payload->>'workforce_type', ''), 'user');
  END IF;

  IF new.full_name IS NULL OR btrim(new.full_name) = '' THEN
    new.full_name := coalesce(nullif(v_payload->>'display_name', ''), nullif(v_payload->>'name', ''), 'Britium User');
  END IF;

  IF new.status IS NULL OR btrim(new.status) = '' THEN
    new.status := 'active';
  END IF;

  IF new.branch_code IS NULL OR btrim(new.branch_code) = '' THEN
    new.branch_code := 'YGN';
  END IF;

  RETURN new;
END;
$function$
;

create or replace view "public"."be_v32_data_entry_proof_rows" as  SELECT (proof_id)::text AS id,
    pickup_id,
    wayplan_id,
    waybill_no,
    waybill_no AS delivery_way_id,
    waybill_no AS parcel_no,
    parcel_index,
    proof_status AS status,
    proof_status AS verification_status,
    proof_photo_url,
    proof_photo_path,
    proof_photo_data,
    proof_photo_url AS photo_url,
    proof_photo_url AS image_url,
    COALESCE(display_photo, proof_photo_url, proof_photo_data, proof_photo_path) AS display_photo,
    created_at
   FROM public.be_v32_proofs;


create or replace view "public"."be_v32_ops_snapshot" as  SELECT ( SELECT count(*) AS count
           FROM public.be_v32_parcels) AS total_parcels,
    ( SELECT count(*) AS count
           FROM public.be_v32_parcels
          WHERE (be_v32_parcels.status = ANY (ARRAY['REGISTERED'::text, 'READY'::text, 'PICKUP_SUCCESS'::text, 'WAREHOUSE_RECEIVED'::text, 'READY_FOR_DELIVERY'::text]))) AS ready_for_wayplan,
    ( SELECT count(*) AS count
           FROM public.be_v32_wayplans
          WHERE (be_v32_wayplans.status <> ALL (ARRAY['COMPLETED'::text, 'CANCELLED'::text]))) AS active_wayplans,
    ( SELECT count(*) AS count
           FROM public.be_v32_parcels
          WHERE ((be_v32_parcels.delivery_status = 'DELIVERED'::text) OR (be_v32_parcels.status = 'DELIVERED'::text))) AS delivered,
    ( SELECT count(*) AS count
           FROM public.be_v32_parcels
          WHERE (COALESCE(be_v32_parcels.delivery_status, be_v32_parcels.status) ~~ '%FAILED%'::text)) AS failed,
    ( SELECT count(*) AS count
           FROM public.be_v32_proofs
          WHERE (be_v32_proofs.proof_status = ANY (ARRAY['NEEDS_REVIEW'::text, 'PENDING'::text]))) AS proof_exceptions,
    ( SELECT count(*) AS count
           FROM public.be_v32_role_tasks
          WHERE (be_v32_role_tasks.status = ANY (ARRAY['OPEN'::text, 'IN_PROGRESS'::text, 'WAITING_APPROVAL'::text]))) AS open_tasks,
    ( SELECT count(*) AS count
           FROM public.be_v32_reprint_requests
          WHERE (be_v32_reprint_requests.status = 'PENDING'::text)) AS pending_reprints,
    ( SELECT COALESCE(sum(be_v32_cod_collections.amount_collected), (0)::numeric) AS "coalesce"
           FROM public.be_v32_cod_collections
          WHERE (be_v32_cod_collections.status = ANY (ARRAY['COLLECTED'::text, 'SUBMITTED'::text]))) AS unsettled_cod;


create or replace view "public"."be_v32_role_inbox" as  SELECT id,
    source_role,
    target_role,
    process_area,
    ref_type,
    ref_id,
    waybill_no,
    pickup_id,
    wayplan_id,
    title,
    description,
    priority,
    status,
    assigned_to,
    created_by,
    resolved_by,
    payload,
    due_at,
    resolved_at,
    created_at,
    updated_at
   FROM public.be_v32_role_tasks
  WHERE (status <> ALL (ARRAY['CLOSED'::text, 'CANCELLED'::text]))
  ORDER BY
        CASE priority
            WHEN 'URGENT'::text THEN 1
            WHEN 'HIGH'::text THEN 2
            WHEN 'NORMAL'::text THEN 3
            ELSE 4
        END, created_at DESC;


create or replace view "public"."be_v_active_drivers" as  SELECT driver_code AS code,
    COALESCE(driver_name, name, driver_code) AS name,
    phone_primary AS phone,
