    status
   FROM public.be_master_drivers
  WHERE (lower(COALESCE(status, 'active'::text)) = 'active'::text);


create or replace view "public"."be_v_active_fleet" as  SELECT COALESCE(vehicle_code, vehicle_no, fleet_id) AS code,
