create or replace view "public"."be_v_branch_office_dashboard" as  SELECT branch_code,
    branch_name,
    city,
    region_state,
    address,
    phone,
    manager_name,
    manager_phone,
    manager_email,
    status,
    ( SELECT count(*) AS count
           FROM public.be_branch_merchant_registry m
          WHERE ((m.branch_code = b.branch_code) AND (COALESCE(m.status, 'ACTIVE'::text) = 'ACTIVE'::text))) AS approved_merchants,
    ( SELECT count(*) AS count
           FROM public.be_branch_merchant_onboarding_requests r
          WHERE ((r.branch_code = b.branch_code) AND (r.status = 'PENDING'::text))) AS pending_merchant_requests,
    ( SELECT count(*) AS count
           FROM public.be_branch_staff s
          WHERE ((s.branch_code = b.branch_code) AND (COALESCE(s.status, 'ACTIVE'::text) = 'ACTIVE'::text))) AS active_staff,
    ( SELECT count(*) AS count
           FROM public.be_branch_service_areas a
          WHERE ((a.branch_code = b.branch_code) AND a.active)) AS service_areas
   FROM public.be_branch_offices b;


create or replace view "public"."be_v_commission_settlement" as  SELECT work_date,
    role_code,
    assignee_email,
    COALESCE((array_agg(NULLIF(assignee_name, ''::text) ORDER BY
        CASE
            WHEN (NULLIF(assignee_name, ''::text) IS NULL) THEN 2
            WHEN (assignee_name = assignee_email) THEN 1
            ELSE 0
        END, updated_at DESC))[1], assignee_email) AS assignee_name,
    operation_type,
    unit_type,
    sum(unit_count) AS total_units,
    max(rate_mmk) AS rate_mmk,
    sum(commission_mmk) AS commission_mmk,
    count(*) AS event_rows
   FROM public.be_commission_events e
  WHERE (event_status = ANY (ARRAY['READY'::text, 'PENDING'::text, 'APPROVED'::text, 'PAID'::text]))
  GROUP BY work_date, role_code, assignee_email, operation_type, unit_type;


create or replace view "public"."be_v_data_entry_parcel_proofs" as  SELECT COALESCE((id)::text, ((pickup_id || '-'::text) || (item_no)::text)) AS id,
    pickup_request_id,
    pickup_id,
    COALESCE(pickup_way_id, pickup_id) AS pickup_way_id,
    COALESCE(delivery_way_id, tracking_no) AS delivery_way_id,
    COALESCE(tracking_no, delivery_way_id) AS tracking_no,
    item_no,
    COALESCE(delivery_sequence, item_no) AS parcel_sequence,
    COALESCE(delivery_sequence, item_no) AS parcel_sequence_safe,
    delivery_count,
    merchant_code,
    merchant_name,
    COALESCE(weight_kg, actual_weight_kg, (0)::numeric) AS weight_kg,
    COALESCE(actual_weight_kg, weight_kg, (0)::numeric) AS actual_weight_kg,
    COALESCE(NULLIF(proof_photo_path, ''::text), NULLIF(proof_url, ''::text), NULLIF(photo_url, ''::text)) AS proof_photo_path,
    COALESCE(NULLIF(proof_url, ''::text), NULLIF(photo_url, ''::text), NULLIF(proof_photo_path, ''::text)) AS proof_url,
    COALESCE(NULLIF(photo_url, ''::text), NULLIF(proof_url, ''::text), NULLIF(proof_photo_path, ''::text)) AS photo_url,
    COALESCE(proof_urls,
        CASE
            WHEN (COALESCE(proof_photo_path, proof_url, photo_url, ''::text) <> ''::text) THEN jsonb_build_array(COALESCE(proof_photo_path, proof_url, photo_url))
            ELSE '[]'::jsonb
        END) AS proof_urls,
        CASE
            WHEN (COALESCE(proof_photo_path, proof_url, photo_url, ''::text) <> ''::text) THEN 1
            WHEN (jsonb_typeof(COALESCE(proof_urls, '[]'::jsonb)) = 'array'::text) THEN jsonb_array_length(COALESCE(proof_urls, '[]'::jsonb))
            ELSE 0
        END AS photo_count,
    COALESCE(proof_status, delivery_status, 'PENDING_PROOF'::text) AS proof_status,
    rider_uploaded_at,
    rider_verified_at,
    created_at,
    updated_at
   FROM public.be_portal_pickup_request_items i;


create or replace view "public"."be_v_data_entry_pickup_verification_queue" as  SELECT id,
    pickup_way_id,
    merchant_name,
    COALESCE(parcel_count, expected_parcels, 0) AS verified_parcels,
    status,
    pickup_status,
    verification_status,
    pickup_verified_at,
    pickup_verified_by,
    created_at,
    updated_at
   FROM public.be_pickup_requests p
  WHERE ((status = 'PICKUP_VERIFIED'::text) OR (pickup_status = 'PICKUP_VERIFIED'::text) OR (verification_status = 'PICKUP_VERIFIED'::text));


create or replace view "public"."be_v_data_entry_pickup_verification_summary" as  SELECT count(*) AS total_pending
   FROM public.be_portal_pickup_requests
  WHERE (status = 'PICKED_UP'::text);


create or replace view "public"."be_v_data_entry_rider_proofs" as  SELECT id,
    pickup_id,
    delivery_way_id,
    parcel_sequence,
    parcel_weight_kg,
    proof_photo_path,
    proof_photo_url,
    proof_photo_data,
    COALESCE(NULLIF(proof_photo_url, ''::text), NULLIF(proof_photo_data, ''::text), NULLIF(proof_photo_path, ''::text), NULLIF((raw_payload ->> 'proof_photo_url'::text), ''::text), NULLIF((raw_payload ->> 'proof_photo_data'::text), ''::text), NULLIF((raw_payload ->> 'photo_url'::text), ''::text), NULLIF((raw_payload ->> 'image_url'::text), ''::text), NULLIF((raw_payload ->> 'photo'::text), ''::text)) AS display_photo,
    qr_payload,
    status,
    verified_at,
    actor_email,
    created_at,
    updated_at,
        CASE
            WHEN (COALESCE(NULLIF(proof_photo_url, ''::text), NULLIF(proof_photo_data, ''::text), NULLIF((raw_payload ->> 'photo_url'::text), ''::text), NULLIF((raw_payload ->> 'image_url'::text), ''::text), NULLIF((raw_payload ->> 'photo'::text), ''::text)) IS NOT NULL) THEN 'HAS_URL_OR_DATA'::text
            WHEN (COALESCE(NULLIF(proof_photo_path, ''::text), NULLIF((raw_payload ->> 'proof_photo_path'::text), ''::text)) IS NOT NULL) THEN 'HAS_STORAGE_PATH'::text
            WHEN (upper(COALESCE(status, ''::text)) = ANY (ARRAY['VERIFIED'::text, 'PICKUP_VERIFIED'::text])) THEN 'VERIFIED_BUT_PHOTO_MISSING'::text
            ELSE 'PENDING'::text
        END AS photo_state,
    'be_pickup_parcel_verifications'::text AS source_table
   FROM public.be_pickup_parcel_verifications pv
  ORDER BY pickup_id, parcel_sequence;


create or replace view "public"."be_v_data_entry_rider_verified_pickups" as  SELECT p.pickup_id,
    COALESCE(p.canonical_pickup_id, p.pickup_id) AS canonical_pickup_id,
    COALESCE(p.pickup_way_id, p.pickup_id) AS pickup_way_id,
    p.merchant_name,
    p.merchant_code,
    COALESCE(p.branch_code, 'YGN'::text) AS branch_code,
    p.city,
    p.township,
    p.pickup_address,
    p.assigned_rider_code,
    p.assigned_rider_email,
    p.pickup_status,
    p.rider_status,
    p.workflow_stage,
    p.proof_url,
    p.pickup_verified_at,
    p.rider_last_action_at,
    COALESCE(p.expected_parcels, 1) AS expected_parcels,
    COALESCE(v.verified_parcels, (0)::bigint) AS verified_parcels,
    COALESCE(v.total_weight_kg, (0)::numeric) AS total_weight_kg,
    COALESCE(v.proofs, '[]'::jsonb) AS rider_proofs,
    p.created_at,
    p.updated_at
   FROM (public.be_portal_pickup_requests p
     LEFT JOIN ( SELECT be_rider_pickup_parcel_verifications.pickup_id,
            count(*) AS verified_parcels,
            sum(COALESCE(be_rider_pickup_parcel_verifications.actual_weight_kg, (0)::numeric)) AS total_weight_kg,
            jsonb_agg(jsonb_build_object('parcel_id', be_rider_pickup_parcel_verifications.parcel_id, 'parcel_sequence', be_rider_pickup_parcel_verifications.parcel_sequence, 'actual_weight_kg', be_rider_pickup_parcel_verifications.actual_weight_kg, 'proof_url', be_rider_pickup_parcel_verifications.proof_url, 'proof_file_name', be_rider_pickup_parcel_verifications.proof_file_name, 'remarks', be_rider_pickup_parcel_verifications.remarks, 'verified', be_rider_pickup_parcel_verifications.verified, 'created_at', be_rider_pickup_parcel_verifications.created_at) ORDER BY be_rider_pickup_parcel_verifications.parcel_sequence, be_rider_pickup_parcel_verifications.created_at) AS proofs
           FROM public.be_rider_pickup_parcel_verifications
          GROUP BY be_rider_pickup_parcel_verifications.pickup_id) v ON ((v.pickup_id = p.pickup_id)))
  WHERE ((upper(COALESCE(p.pickup_status, ''::text)) = 'PICKUP_VERIFIED'::text) OR (upper(COALESCE(p.rider_status, ''::text)) = 'PICKUP_VERIFIED'::text) OR (upper(COALESCE(p.workflow_stage, ''::text)) = 'PICKUP_VERIFIED'::text) OR (p.pickup_verified_at IS NOT NULL) OR (COALESCE(p.proof_url, ''::text) ~~ 'parcel-batch:%'::text));


create or replace view "public"."be_v_delivery_proof_integrity_v27" as  SELECT i.waybill_no,
    i.status AS delivery_status,
    i.wayplan_id,
    i.assigned_rider_email,
    i.proof_photo_url AS item_proof_photo_url,
    i.signature_data AS item_signature_data,
    p.proof_id,
    p.proof_type,
    p.proof_status,
    p.proof_photo_url,
    p.signature_data,
    p.cod_collected,
    v.verification_id,
    v.verification_status,
    v.photo_url AS verification_photo_url,
        CASE
            WHEN (p.proof_id IS NULL) THEN 'MISSING_PROOF'::text
            WHEN (COALESCE(p.proof_photo_url, i.proof_photo_url, v.photo_url, ''::text) = ''::text) THEN 'MISSING_PHOTO'::text
            WHEN ((i.status = 'DELIVERED'::text) AND (COALESCE(p.cod_collected, (0)::numeric) < (0)::numeric)) THEN 'COD_INVALID'::text
            ELSE 'OK'::text
        END AS integrity_status,
    GREATEST(COALESCE(p.created_at, '1970-01-01 00:00:00+00'::timestamp with time zone), COALESCE(v.created_at, '1970-01-01 00:00:00+00'::timestamp with time zone), i.updated_at) AS last_activity_at
   FROM ((public.be_delivery_items_v25 i
     LEFT JOIN LATERAL ( SELECT p_1.proof_id,
            p_1.waybill_no,
            p_1.wayplan_id,
            p_1.rider_email,
            p_1.proof_type,
            p_1.proof_status,
            p_1.recipient_name,
            p_1.recipient_phone,
            p_1.proof_photo_url,
            p_1.signature_data,
            p_1.cod_collected,
            p_1.payment_type,
            p_1.failure_reason,
            p_1.lat,
            p_1.lng,
            p_1.reviewed_by,
            p_1.review_note,
            p_1.payload,
            p_1.created_by,
            p_1.created_at,
            p_1.reviewed_at
           FROM public.be_delivery_proofs_v27 p_1
          WHERE (p_1.waybill_no = i.waybill_no)
          ORDER BY p_1.created_at DESC
         LIMIT 1) p ON (true))
     LEFT JOIN LATERAL ( SELECT v_1.verification_id,
            v_1.waybill_no,
            v_1.pickup_id,
            v_1.verification_type,
            v_1.verification_status,
            v_1.verified_by,
            v_1.photo_url,
            v_1.photo_data,
            v_1.signature_data,
            v_1.failure_reason,
            v_1.lat,
            v_1.lng,
            v_1.payload,
            v_1.created_at,
            v_1.updated_at
           FROM public.be_delivery_verifications_v27 v_1
          WHERE (v_1.waybill_no = i.waybill_no)
          ORDER BY v_1.created_at DESC
         LIMIT 1) v ON (true));


create or replace view "public"."be_v_delivery_tariff_master" as  SELECT tier_name,
    free_allowance_kg,
