    assigned_driver_name,
    assigned_helper_id,
    assigned_helper_name,
    assigned_fleet_id,
    vehicle_plate,
    status,
    total_parcels,
    total_cod,
    total_delivery_fee_os,
    total_actual_collect,
    generated_by,
    generated_at,
    assigned_at,
    completed_at,
    notes,
    created_at,
    updated_at,
    route_name,
    total_weight_kg,
    assigned_vehicle_no,
    supervisor_note,
    dispatched_at,
    pickup_count,
    stop_count,
    rider_id,
    driver_id,
    helper_id,
    vehicle_code,
    created_by,
