    merchant_code
   FROM public.be_wayplans wp
  ORDER BY dispatch_date DESC NULLS LAST, created_at DESC;


create or replace view "public"."be_v_dispatch_ready_queue" as  SELECT COALESCE(NULLIF(w.delivery_way_id, ''::text), NULLIF(p.delivery_way_id, ''::text), NULLIF(w.waybill_no, ''::text), (NULLIF(p.pickup_id, ''::text) || '-001'::text), (NULLIF(w.pickup_id, ''::text) || '-001'::text)) AS delivery_way_id,
    COALESCE(NULLIF(w.waybill_no, ''::text), NULLIF(w.delivery_way_id, ''::text), NULLIF(p.delivery_way_id, ''::text), (NULLIF(p.pickup_id, ''::text) || '-001'::text), (NULLIF(w.pickup_id, ''::text) || '-001'::text)) AS waybill_no,
    COALESCE(w.pickup_id, p.pickup_id) AS pickup_id,
    COALESCE(p.pickup_way_id, w.pickup_id, p.pickup_id) AS pickup_way_id,
    COALESCE(w.merchant_name, p.merchant_name, ''::text) AS merchant_name,
    COALESCE(w.recipient_name, w.customer_name, p.customer_name, ''::text) AS recipient_name,
    COALESCE(w.recipient_phone, w.contact_no_1, p.customer_phone, ''::text) AS recipient_phone,
    COALESCE(w.township, p.township, p.pickup_township, ''::text) AS township,
    COALESCE(w.recipient_address, w.delivery_address, p.pickup_address, ''::text) AS address,
    COALESCE(w.cod_amount, w.item_price, (0)::numeric) AS cod_amount,
    COALESCE(w.delivery_fee, (0)::numeric) AS delivery_fee,
    COALESCE(w.weight_kg, w.parcel_weight_kg, w.total_weight_kg, p.total_weight_kg, (0)::numeric) AS parcel_weight_kg,
    COALESCE(w.dispatch_status, p.dispatch_status, 'READY_FOR_DISPATCH'::text) AS dispatch_status,
    COALESCE(w.warehouse_status, p.warehouse_status, 'READY_FOR_DISPATCH'::text) AS warehouse_status,
    COALESCE(w.wayplan_status, p.wayplan_status, 'NOT_PLANNED'::text) AS wayplan_status,
    COALESCE(w.created_at, p.created_at, now()) AS created_at,
    COALESCE(w.updated_at, p.updated_at, now()) AS updated_at,
    jsonb_build_object('source', 'be_v_dispatch_ready_queue', 'pickup_status', p.pickup_status, 'data_entry_status', p.data_entry_status, 'warehouse_status', COALESCE(w.warehouse_status, p.warehouse_status), 'dispatch_status', COALESCE(w.dispatch_status, p.dispatch_status), 'wayplan_status', COALESCE(w.wayplan_status, p.wayplan_status)) AS metadata
   FROM (public.be_waybill_ledger w
     LEFT JOIN public.be_portal_pickup_requests p ON ((p.pickup_id = w.pickup_id)))
  WHERE ((COALESCE(w.wayplan_status, p.wayplan_status, 'NOT_PLANNED'::text) = ANY (ARRAY['NOT_PLANNED'::text, 'READY_FOR_WAYPLAN'::text])) AND (COALESCE(w.dispatch_status, p.dispatch_status, 'READY_FOR_DISPATCH'::text) = ANY (ARRAY['READY_FOR_DISPATCH'::text, 'WAITING_DISPATCH'::text, 'READY'::text, 'WAYBILL_CREATED'::text])));


create or replace view "public"."be_v_exception_board" as  SELECT e.id,
    e.created_at,
    e.tracking_no,
    e.delivery_way_id,
    e.waybill_no,
    e.pickup_id,
    e.wayplan_code,
    e.merchant_code,
    e.merchant_name,
    e.merchant_email,
    e.recipient_name,
    e.recipient_phone,
    e.township,
    e.process_type,
    e.exception_code,
    e.exception_name_en,
    e.exception_name_mm,
    e.mapped_status,
    e.attempt_no,
    e.remarks,
    e.reported_by_email,
    e.branch_code,
    e.previous_status,
    e.new_status,
    e.next_action,
    e.is_rto,
    e.resolved_at,
    e.resolved_by_email,
    COALESCE(r.exception_name_en, e.exception_name_en) AS reason_name_en,
    COALESCE(r.exception_name_mm, e.exception_name_mm) AS reason_name_mm,
    r.severity,
    r.require_photo,
    r.require_remark,
    COALESCE(r.next_action, e.next_action) AS rule_next_action,
    r.customer_message_en,
    r.customer_message_mm
   FROM (public.be_parcel_exception_events e
     LEFT JOIN public.be_exception_rules r ON (((r.process_type = e.process_type) AND (r.exception_code = e.exception_code))));


create or replace view "public"."be_v_finance_cod_queue" as  SELECT settlement_id,
    pickup_id,
    waybill_no,
    wayplan_id,
    merchant_code,
    rider_email,
    driver_email,
    cod_amount,
    collected_amount,
    settled_amount,
    settlement_status,
    settlement_method,
    reference_no,
    collected_at,
    settled_by_email,
    settled_at,
    created_at,
    updated_at,
    invoice_no,
    delivery_way_id
   FROM public.be_cod_settlements c
  WHERE (settlement_status = ANY (ARRAY['PENDING_SETTLEMENT'::text, 'PARTIALLY_SETTLED'::text]))
  ORDER BY collected_at DESC NULLS LAST, created_at DESC;


create or replace view "public"."be_v_integrated_department_snapshot_v27" as  SELECT ( SELECT count(*) AS count
           FROM public.be_cross_role_work_items_v27
          WHERE (be_cross_role_work_items_v27.status = ANY (ARRAY['OPEN'::text, 'IN_PROGRESS'::text, 'WAITING_APPROVAL'::text]))) AS open_cross_role_tasks,
    ( SELECT count(*) AS count
           FROM public.be_cross_role_work_items_v27
          WHERE ((be_cross_role_work_items_v27.target_role = 'operations_manager'::text) AND (be_cross_role_work_items_v27.status = ANY (ARRAY['OPEN'::text, 'IN_PROGRESS'::text, 'WAITING_APPROVAL'::text])))) AS ops_manager_tasks,
    ( SELECT count(*) AS count
           FROM public.be_cross_role_work_items_v27
          WHERE ((be_cross_role_work_items_v27.target_role = 'business_development_manager'::text) AND (be_cross_role_work_items_v27.status = ANY (ARRAY['OPEN'::text, 'IN_PROGRESS'::text, 'WAITING_APPROVAL'::text])))) AS bdm_tasks,
    ( SELECT count(*) AS count
           FROM public.be_cross_role_work_items_v27
          WHERE ((be_cross_role_work_items_v27.target_role = 'customer_service'::text) AND (be_cross_role_work_items_v27.status = ANY (ARRAY['OPEN'::text, 'IN_PROGRESS'::text, 'WAITING_APPROVAL'::text])))) AS cs_tasks,
    ( SELECT count(*) AS count
           FROM public.be_cross_role_work_items_v27
          WHERE ((be_cross_role_work_items_v27.target_role = 'marketing'::text) AND (be_cross_role_work_items_v27.status = ANY (ARRAY['OPEN'::text, 'IN_PROGRESS'::text, 'WAITING_APPROVAL'::text])))) AS marketing_tasks,
    ( SELECT count(*) AS count
           FROM public.be_customer_service_cases_v27
          WHERE (be_customer_service_cases_v27.status <> ALL (ARRAY['RESOLVED'::text, 'CLOSED'::text]))) AS open_cs_cases,
    ( SELECT count(*) AS count
           FROM public.be_business_development_activities_v27
          WHERE (be_business_development_activities_v27.stage <> ALL (ARRAY['WON'::text, 'LOST'::text]))) AS active_bd_leads,
    ( SELECT count(*) AS count
           FROM public.be_marketing_activities_v27
          WHERE (be_marketing_activities_v27.status = 'ACTIVE'::text)) AS active_marketing_campaigns,
    ( SELECT count(*) AS count
           FROM public.be_v_delivery_proof_integrity_v27
          WHERE (be_v_delivery_proof_integrity_v27.integrity_status <> 'OK'::text)) AS proof_exceptions,
    ( SELECT count(*) AS count
           FROM public.be_delivery_items_v25
          WHERE (be_delivery_items_v25.status = 'DELIVERED'::text)) AS delivered_count,
    ( SELECT count(*) AS count
           FROM public.be_delivery_items_v25
          WHERE (be_delivery_items_v25.status ~~ '%FAILED%'::text)) AS failed_delivery_count,
    ( SELECT COALESCE(sum(be_cod_collections_v25.amount_collected), (0)::numeric) AS "coalesce"
           FROM public.be_cod_collections_v25
          WHERE (be_cod_collections_v25.collection_status = ANY (ARRAY['COLLECTED'::text, 'SUBMITTED'::text]))) AS unsettled_cod;


create or replace view "public"."be_v_master_data_active_rows" as  SELECT r.id,
    r.dataset_key,
    t.display_name_en,
    t.display_name_mm,
    t.category,
    t.primary_key,
    r.record_key,
    r.payload,
    r.status,
    r.updated_at,
    r.updated_by_email
   FROM (public.be_master_data_rows r
     JOIN public.be_master_data_tabs t ON ((t.dataset_key = r.dataset_key)))
  WHERE ((r.deleted_at IS NULL) AND (t.active = true));


create or replace view "public"."be_v_master_data_live_rows" as  SELECT r.id,
    r.dataset_key,
    t.display_name_en,
    t.category,
    t.primary_key,
    r.record_key,
    r.payload,
    r.status,
    r.updated_at,
    r.updated_by_email
   FROM (public.be_master_data_rows r
     JOIN public.be_master_data_tabs t ON ((t.dataset_key = r.dataset_key)))
  WHERE ((r.deleted_at IS NULL) AND (t.active = true));


create or replace view "public"."be_v_master_fleets" as  SELECT record_key AS fleet_id,
    COALESCE((payload ->> 'vehicle_no'::text), (payload ->> 'plate_no'::text)) AS vehicle_no,
    (payload ->> 'vehicle_type'::text) AS vehicle_type,
    (NULLIF((payload ->> 'capacity_kg'::text), ''::text))::numeric AS capacity_kg,
    (NULLIF((payload ->> 'capacity_cbm'::text), ''::text))::numeric AS capacity_cbm,
    (payload ->> 'assigned_driver_id'::text) AS assigned_driver_id,
    (payload ->> 'ownership_type'::text) AS ownership_type,
    (payload ->> 'zone_note'::text) AS zone_note,
    status,
    payload,
    updated_at
   FROM public.be_v_master_data_active_rows
  WHERE (dataset_key = 'fleet_master'::text);


create or replace view "public"."be_v_master_merchants" as  SELECT record_key AS merchant_code,
    COALESCE((payload ->> 'merchant_name'::text), (payload ->> 'name'::text)) AS merchant_name,
    COALESCE((payload ->> 'business_type'::text), (payload ->> 'customer_type'::text)) AS business_type,
    COALESCE((payload ->> 'contact_person'::text), (payload ->> 'owner_name'::text)) AS contact_person,
    COALESCE((payload ->> 'phone_primary'::text), (payload ->> 'phone'::text)) AS phone_primary,
    (payload ->> 'phone_secondary'::text) AS phone_secondary,
    (payload ->> 'email'::text) AS email,
    COALESCE((payload ->> 'address_line_1'::text), (payload ->> 'address'::text)) AS address_line_1,
    (payload ->> 'township'::text) AS township,
    (payload ->> 'city'::text) AS city,
    (payload ->> 'region_state'::text) AS region_state,
    COALESCE((payload ->> 'payment_terms'::text), (payload ->> 'payment_type'::text)) AS payment_terms,
    status,
    payload,
    updated_at
   FROM public.be_v_master_data_active_rows
  WHERE (dataset_key = 'merchant_master'::text);


create or replace view "public"."be_v_master_tariff_inputs" as  SELECT id,
    dataset_key,
    display_name_en,
    display_name_mm,
    category,
    primary_key,
    record_key,
    payload,
    status,
    updated_at,
    updated_by_email
   FROM public.be_v_master_data_active_rows
  WHERE (dataset_key = ANY (ARRAY['service_types'::text, 'weight_brackets'::text, 'vehicle_capacity'::text, 'zone_master'::text, 'cod_fee_rules'::text, 'surcharge_rules'::text, 'cargo_dropoff_rate'::text]));


create or replace view "public"."be_v_master_townships" as  SELECT record_key AS township_code,
    COALESCE((payload ->> 'township_name_en'::text), (payload ->> 'township'::text)) AS township_name_en,
    (payload ->> 'township_name_mm'::text) AS township_name_mm,
    (payload ->> 'state_region_code'::text) AS state_region_code,
    (payload ->> 'state_region_name_en'::text) AS state_region_name_en,
    (payload ->> 'state_region_name_mm'::text) AS state_region_name_mm,
    COALESCE((payload ->> 'township_name_for_current_app'::text), (payload ->> 'township_name_en'::text)) AS township_name_for_current_app,
    status,
    payload,
    updated_at
   FROM public.be_v_master_data_active_rows
  WHERE (dataset_key = 'township_master'::text);


create or replace view "public"."be_v_master_workforce" as  SELECT dataset_key,
    record_key AS worker_id,
    COALESCE((payload ->> 'rider_name'::text), (payload ->> 'driver_name'::text), (payload ->> 'helper_name'::text), (payload ->> 'employee_name'::text), (payload ->> 'name'::text)) AS worker_name,
        CASE dataset_key
            WHEN 'rider_master'::text THEN 'RIDER'::text
            WHEN 'driver_master'::text THEN 'DRIVER'::text
            WHEN 'helper_master'::text THEN 'HELPER'::text
            ELSE COALESCE((payload ->> 'role_id'::text), 'EMPLOYEE'::text)
        END AS role_code,
    COALESCE((payload ->> 'phone_primary'::text), (payload ->> 'phone'::text)) AS phone_primary,
    COALESCE((payload ->> 'assigned_zone'::text), (payload ->> 'zone'::text)) AS assigned_zone,
    (payload ->> 'assigned_fleet_id'::text) AS assigned_fleet_id,
    status,
    payload,
    updated_at
   FROM public.be_v_master_data_active_rows
  WHERE (dataset_key = ANY (ARRAY['rider_master'::text, 'driver_master'::text, 'helper_master'::text, 'employee_master'::text]));


