create or replace view "public"."be_v_operational_wayplan_items" as  SELECT COALESCE(NULLIF(wayplan_code, ''::text), NULLIF(wayplan_no, ''::text), NULLIF(wayplan_id, ''::text), NULLIF(upload_code, ''::text)) AS wayplan_code,
    COALESCE(NULLIF(wayplan_no, ''::text), NULLIF(wayplan_code, ''::text), NULLIF(wayplan_id, ''::text), NULLIF(upload_code, ''::text)) AS wayplan_no,
    COALESCE(NULLIF(wayplan_id, ''::text), NULLIF(wayplan_code, ''::text), NULLIF(wayplan_no, ''::text), NULLIF(upload_code, ''::text)) AS wayplan_id,
    COALESCE(NULLIF(upload_code, ''::text), NULLIF(wayplan_code, ''::text), NULLIF(wayplan_no, ''::text), NULLIF(wayplan_id, ''::text)) AS upload_code,
    tracking_no,
    waybill_no,
    pickup_id,
    delivery_way_id,
    COALESCE(parcel_sequence, item_no, 0) AS parcel_sequence,
    COALESCE(item_no, parcel_sequence, 0) AS item_no,
    recipient_name,
    COALESCE(NULLIF(recipient_phone, ''::text), NULLIF(recipient_phone_2, ''::text)) AS phone_number,
    recipient_address,
    delivery_township,
    destination_city,
    COALESCE(NULLIF(remarks, ''::text), NULLIF(remark, ''::text), NULLIF(special_instruction, ''::text)) AS remarks,
    COALESCE(weight_kg, (0)::numeric) AS weight_kg,
    COALESCE(cod_amount, (0)::numeric) AS cod_amount,
    COALESCE(delivery_charges, (0)::numeric) AS delivery_charges,
    COALESCE(total_collected_amount, (0)::numeric) AS total_collected_amount,
    COALESCE(NULLIF(warehouse_status, ''::text), 'RECEIVED'::text) AS warehouse_status,
    COALESCE(NULLIF(wayplan_status, ''::text), 'ASSIGNED'::text) AS wayplan_status,
    COALESCE(NULLIF(dispatch_status, ''::text), 'READY_FOR_DISPATCH'::text) AS dispatch_status,
    COALESCE(NULLIF(delivery_status, ''::text), NULLIF(status, ''::text), 'assigned'::text) AS delivery_status,
    COALESCE(updated_at, now()) AS updated_at
   FROM public.be_wayplan_items i;


create or replace view "public"."be_v_operational_wayplans" as  WITH item_counts AS (
         SELECT COALESCE(NULLIF(be_wayplan_items.wayplan_code, ''::text), NULLIF(be_wayplan_items.wayplan_no, ''::text), NULLIF(be_wayplan_items.wayplan_id, ''::text), be_wayplan_items.upload_code) AS wayplan_key,
            max(be_wayplan_items.waybill_no) AS item_waybill_no,
            max(be_wayplan_items.pickup_id) AS item_pickup_id,
            (count(*))::integer AS item_count,
            COALESCE(sum(be_wayplan_items.weight_kg), (0)::numeric) AS item_weight_kg,
            COALESCE(sum(be_wayplan_items.cod_amount), (0)::numeric) AS item_cod_amount,
            COALESCE(sum(be_wayplan_items.total_collected_amount), (0)::numeric) AS item_collect_amount
           FROM public.be_wayplan_items
          GROUP BY COALESCE(NULLIF(be_wayplan_items.wayplan_code, ''::text), NULLIF(be_wayplan_items.wayplan_no, ''::text), NULLIF(be_wayplan_items.wayplan_id, ''::text), be_wayplan_items.upload_code)
        )
 SELECT COALESCE(NULLIF(w.wayplan_code, ''::text), NULLIF(w.wayplan_no, ''::text), NULLIF(w.wayplan_id, ''::text), NULLIF(w.upload_code, ''::text)) AS wayplan_code,
    COALESCE(NULLIF(w.wayplan_no, ''::text), NULLIF(w.wayplan_code, ''::text), NULLIF(w.wayplan_id, ''::text), NULLIF(w.upload_code, ''::text)) AS wayplan_no,
    COALESCE(NULLIF(w.wayplan_id, ''::text), NULLIF(w.wayplan_code, ''::text), NULLIF(w.wayplan_no, ''::text), NULLIF(w.upload_code, ''::text)) AS wayplan_id,
    COALESCE(NULLIF(w.upload_code, ''::text), NULLIF(w.wayplan_code, ''::text), NULLIF(w.wayplan_no, ''::text), NULLIF(w.wayplan_id, ''::text)) AS upload_code,
    COALESCE(NULLIF(w.waybill_no, ''::text), i.item_waybill_no) AS waybill_no,
    COALESCE(NULLIF(w.pickup_id, ''::text), i.item_pickup_id) AS pickup_id,
    w.merchant_code,
    w.merchant_name,
    w.route_code,
    w.route_name,
    w.branch_code,
    w.driver_email,
    w.helper_email,
    w.rider_email,
    w.vehicle_id,
    GREATEST(COALESCE(w.parcel_count, 0), COALESCE(w.total_parcels, 0), COALESCE(i.item_count, 0)) AS parcel_count,
    GREATEST(COALESCE(w.total_parcels, 0), COALESCE(w.parcel_count, 0), COALESCE(i.item_count, 0)) AS total_parcels,
    COALESCE(w.pickup_count, 1) AS pickup_count,
    COALESCE(w.total_waybills, 1) AS total_waybills,
    GREATEST(COALESCE(w.total_weight_kg, (0)::numeric), COALESCE(i.item_weight_kg, (0)::numeric)) AS total_weight_kg,
    GREATEST(COALESCE(w.total_cod_amount, (0)::numeric), COALESCE(i.item_cod_amount, (0)::numeric)) AS total_cod_amount,
    GREATEST(COALESCE(w.total_actual_collect, (0)::numeric), COALESCE(i.item_collect_amount, (0)::numeric)) AS total_actual_collect,
    COALESCE(NULLIF(w.status, ''::text), lower(COALESCE(w.wayplan_status, 'assigned'::text))) AS status,
    COALESCE(NULLIF(w.wayplan_status, ''::text), 'ASSIGNED'::text) AS wayplan_status,
    COALESCE(NULLIF(w.dispatch_status, ''::text), 'READY_FOR_DISPATCH'::text) AS dispatch_status,
    w.assigned_at,
    w.dispatched_at,
    w.completed_at,
    COALESCE(w.updated_at, w.assigned_at, w.dispatched_at, w.completed_at, now()) AS updated_at
   FROM (public.be_wayplans w
     LEFT JOIN item_counts i ON ((i.wayplan_key = COALESCE(NULLIF(w.wayplan_code, ''::text), NULLIF(w.wayplan_no, ''::text), NULLIF(w.wayplan_id, ''::text), NULLIF(w.upload_code, ''::text)))));


create or replace view "public"."be_v_ops_workflow_snapshot_v25" as  SELECT ( SELECT count(*) AS count
           FROM public.be_delivery_items_v25) AS total_delivery_items,
    ( SELECT count(*) AS count
           FROM public.be_delivery_items_v25
          WHERE (be_delivery_items_v25.status = ANY (ARRAY['REGISTERED'::text, 'READY'::text, 'READY_FOR_DELIVERY'::text]))) AS ready_for_wayplan,
    ( SELECT count(*) AS count
           FROM public.be_wayplans_v25
          WHERE (be_wayplans_v25.status = ANY (ARRAY['GENERATED'::text, 'READY_FOR_DISPATCH'::text, 'OUT_FOR_DELIVERY'::text]))) AS active_wayplans,
    ( SELECT count(*) AS count
           FROM public.be_delivery_items_v25
          WHERE (be_delivery_items_v25.status = 'DELIVERED'::text)) AS delivered_count,
    ( SELECT count(*) AS count
           FROM public.be_delivery_items_v25
          WHERE (be_delivery_items_v25.status ~~ '%FAILED%'::text)) AS failed_count,
    ( SELECT COALESCE(sum(be_cod_collections_v25.amount_collected), (0)::numeric) AS "coalesce"
           FROM public.be_cod_collections_v25
          WHERE (be_cod_collections_v25.collection_status = ANY (ARRAY['COLLECTED'::text, 'SUBMITTED'::text]))) AS unsettled_cod,
    ( SELECT count(*) AS count
           FROM public.be_waybill_reprint_requests_v25
          WHERE (be_waybill_reprint_requests_v25.status = 'PENDING'::text)) AS pending_reprint_approvals;


create or replace view "public"."be_v_rider_delivery_wayplan_jobs" as  SELECT s.id,
    s.wayplan_id,
    s.stop_sequence,
    s.pickup_id,
    s.pickup_way_id,
    s.delivery_way_id,
    s.waybill_no,
    COALESCE(s.recipient_name, 'Customer'::text) AS recipient_name,
    COALESCE(s.recipient_phone, ''::text) AS recipient_phone,
    COALESCE(s.township, ''::text) AS township,
    COALESCE(s.address, ''::text) AS address,
    COALESCE(s.cod_amount, (0)::numeric) AS cod_amount,
    COALESCE(s.delivery_fee, (0)::numeric) AS delivery_fee,
    COALESCE(s.parcel_weight_kg, (0)::numeric) AS parcel_weight_kg,
    s.stop_status,
    COALESCE(s.rider_status, 'PENDING'::text) AS rider_status,
    s.loaded_to_vehicle_at,
    s.handed_over_to_rider_at,
    s.delivered_at,
    s.cod_collected,
    s.failed_reason,
    s.rider_proof_url,
    s.receiver_name,
    s.receiver_phone,
    w.wayplan_status,
    w.vehicle_code,
    w.vehicle_name,
    w.driver_code,
    w.driver_name,
    w.rider_code,
    w.rider_name,
    w.helper_code,
    w.helper_name,
    w.dispatched_at,
    w.created_at AS wayplan_created_at,
    jsonb_build_object('source', 'be_v_rider_delivery_wayplan_jobs', 'wayplan_status', w.wayplan_status, 'stop_status', s.stop_status, 'rider_status', COALESCE(s.rider_status, 'PENDING'::text), 'rider_code', w.rider_code, 'vehicle_code', w.vehicle_code) AS metadata
   FROM (public.be_wayplan_dispatch_stops s
     JOIN public.be_wayplan_dispatches w ON ((w.wayplan_id = s.wayplan_id)))
  WHERE ((COALESCE(w.wayplan_status, ''::text) = ANY (ARRAY['DISPATCHED'::text, 'LOADED_TO_VEHICLE'::text, 'HANDOVER_TO_RIDER'::text, 'OUT_FOR_DELIVERY'::text, 'COMPLETED'::text])) AND (COALESCE(s.stop_status, ''::text) = ANY (ARRAY['DISPATCHED'::text, 'LOADED_TO_VEHICLE'::text, 'HANDOVER_TO_RIDER'::text, 'OUT_FOR_DELIVERY'::text, 'ARRIVED_AT_CUSTOMER'::text, 'DELIVERED'::text, 'FAILED_DELIVERY'::text, 'RETURN_TO_WAREHOUSE'::text])));


