create or replace view "public"."be_v_rider_live_locations" as  SELECT id,
    actor_email,
    role_code,
    rider_email,
    driver_email,
    helper_email,
    lat,
    lng,
    heading,
    speed_mps,
    accuracy_m,
    battery_pct,
    source,
    last_seen_at,
        CASE
            WHEN (last_seen_at >= (now() - '00:02:00'::interval)) THEN 'LIVE'::text
            WHEN (last_seen_at >= (now() - '00:15:00'::interval)) THEN 'RECENT'::text
            ELSE 'OFFLINE'::text
        END AS live_status,
    (EXTRACT(epoch FROM (now() - last_seen_at)))::integer AS seconds_since_seen
   FROM public.be_rider_live_locations;


create or replace view "public"."be_v_rider_pickup_queue" as  SELECT id,
    pickup_id,
    COALESCE(pickup_way_id, pickup_id) AS pickup_way_id,
    merchant_code,
    merchant_name,
    COALESCE(pickup_address, address) AS pickup_address,
    COALESCE(pickup_township, township) AS pickup_township,
    COALESCE(pickup_city, 'Yangon'::text) AS pickup_city,
    pickup_date,
    COALESCE(parcel_count, expected_parcel_count, expected_parcels, 1) AS parcel_count,
    COALESCE(expected_parcel_count, parcel_count, expected_parcels, 1) AS expected_parcel_count,
    COALESCE(total_weight_kg, (0)::numeric) AS total_weight_kg,
    COALESCE(cod_amount, total_cod, (0)::numeric) AS cod_amount,
    COALESCE(assigned_rider_code, assigned_rider_id, rider_code, rider_id) AS rider_code,
    assigned_rider_name AS rider_name,
    COALESCE(assigned_driver_code, assigned_driver_id, driver_id) AS driver_code,
    assigned_driver_name AS driver_name,
    COALESCE(assigned_helper_code, assigned_helper_id, helper_id) AS helper_code,
    assigned_helper_name AS helper_name,
    COALESCE(assigned_vehicle_code, assigned_vehicle_id, assigned_fleet_id, vehicle_code) AS vehicle_code,
    assigned_vehicle_name AS vehicle_name,
    pickup_status,
    status,
    assignment_status,
    rider_status,
    rider_app_stage,
    warehouse_status,
    data_entry_status,
    finance_status,
    verified_parcels,
    pickup_proof_url,
    proof_url,
    metadata,
    payload,
    created_at,
    updated_at
   FROM public.be_portal_pickup_requests p
  WHERE ((COALESCE(assigned_rider_code, assigned_rider_id, rider_code, rider_id) IS NOT NULL) AND (lower(COALESCE(status, ''::text)) <> ALL (ARRAY['cancelled'::text, 'closed'::text])) AND (upper(COALESCE(pickup_status, ''::text)) <> ALL (ARRAY['CANCELLED'::text, 'CLOSED'::text])));


create or replace view "public"."be_v_rider_workflow_jobs" as  SELECT id,
    pickup_id,
    COALESCE(pickup_way_id, pickup_id) AS pickup_way_id,
    COALESCE(tracking_no, pickup_way_id, pickup_id) AS tracking_no,
    merchant_code,
    merchant_name,
    pickup_address,
    pickup_township,
    branch_code,
    COALESCE(expected_parcels, delivery_count, 1) AS expected_parcels,
    COALESCE(delivery_count, expected_parcels, 1) AS delivery_count,
    COALESCE(total_weight_kg, (0)::numeric) AS total_weight_kg,
    assigned_rider_code,
    assigned_rider_code AS assigned_workforce_code,
    assigned_rider_code AS rider_id,
    assigned_rider_email,
    assigned_driver_code,
    assigned_helper_code,
    assigned_vehicle_code,
    assigned_at,
    pickup_status,
    rider_status,
    workflow_stage,
    updated_at,
        CASE
            WHEN (COALESCE(rider_status, ''::text) = 'WAITING_ACCEPTANCE'::text) THEN 'ACCEPT_PICKUP'::text
            WHEN (COALESCE(rider_status, ''::text) = 'PICKUP_ACCEPTED'::text) THEN 'ARRIVE_PICKUP'::text
            WHEN (COALESCE(rider_status, ''::text) = 'ARRIVED_AT_PICKUP'::text) THEN 'VERIFY_PICKUP'::text
            WHEN (COALESCE(rider_status, ''::text) = 'PICKUP_VERIFIED'::text) THEN 'COMPLETED'::text
            ELSE 'ACCEPT_PICKUP'::text
        END AS next_action
   FROM public.be_portal_pickup_requests p
  WHERE ((COALESCE(assigned_rider_code, ''::text) <> ''::text) AND (COALESCE(pickup_status, ''::text) = ANY (ARRAY['PICKUP_ASSIGNED'::text, 'PICKUP_ACCEPTED'::text, 'ARRIVED_AT_PICKUP'::text, 'PICKUP_VERIFIED'::text])));


create or replace view "public"."be_v_role_inbox_v27" as  SELECT id,
    process_area,
    source_role,
    target_role,
    ref_type,
    ref_id,
    waybill_no,
    customer_key,
    title,
    description,
    priority,
    status,
    assigned_to,
    created_by,
    due_at,
    created_at,
    updated_at,
    payload
   FROM public.be_cross_role_work_items_v27
  WHERE (status <> ALL (ARRAY['CLOSED'::text, 'CANCELLED'::text]))
  ORDER BY
        CASE priority
            WHEN 'URGENT'::text THEN 1
            WHEN 'HIGH'::text THEN 2
            WHEN 'NORMAL'::text THEN 3
            ELSE 4
        END, created_at DESC;


create or replace view "public"."be_v_supervisor_assignment_status" as  SELECT pickup_way_id,
    merchant_name,
    parcel_count,
    pickup_status,
    workflow_stage,
    rider_app_stage,
    assigned_rider_code,
    assigned_rider_name,
    COALESCE(rider_status, 'WAITING_ACCEPTANCE'::text) AS rider_status,
    assigned_driver_code,
    assigned_driver_name,
    COALESCE(driver_status, 'WAITING_ACCEPTANCE'::text) AS driver_status,
    driver_accepted_at,
    driver_rejected_at,
    assigned_helper_code,
    assigned_helper_name,
    COALESCE(helper_status, 'WAITING_ACCEPTANCE'::text) AS helper_status,
    helper_accepted_at,
    helper_rejected_at,
        CASE
            WHEN ((COALESCE(rider_status, 'WAITING_ACCEPTANCE'::text) = 'ACCEPTED'::text) AND (COALESCE(driver_status, 'WAITING_ACCEPTANCE'::text) = 'ACCEPTED'::text) AND (COALESCE(helper_status, 'WAITING_ACCEPTANCE'::text) = 'ACCEPTED'::text)) THEN 'TEAM_READY'::text
            WHEN ((COALESCE(rider_status, 'WAITING_ACCEPTANCE'::text) = 'REJECTED'::text) OR (COALESCE(driver_status, 'WAITING_ACCEPTANCE'::text) = 'REJECTED'::text) OR (COALESCE(helper_status, 'WAITING_ACCEPTANCE'::text) = 'REJECTED'::text)) THEN 'NEEDS_REASSIGNMENT'::text
            ELSE 'WAITING_TEAM_ACCEPTANCE'::text
        END AS team_acceptance_status,
    updated_at
   FROM public.be_portal_pickup_requests
  WHERE ((pickup_status = ANY (ARRAY['RIDER_ASSIGNED'::text, 'ACCEPTED_BY_RIDER'::text, 'PICKUP_VERIFIED'::text, 'DATA_ENTRY_REGISTERED'::text, 'DELIVERED'::text])) OR (workflow_stage = ANY (ARRAY['RIDER_APP_QUEUE'::text, 'ACCEPTED_PICKUP'::text, 'PICKUP_VERIFIED'::text])));


create or replace view "public"."be_v_supervisor_notifications" as  SELECT id,
    target_role,
    target_branch,
    pickup_id,
    title,
    message,
    is_read,
    created_at,
    pickup_way_id,
    source_table,
    source_key,
    notification_type,
    metadata,
    body,
    target_user_code,
    target_email,
    read_at,
    target_user_id,
    target_workforce_code,
    target_user_email,
    category,
    target_branch_code,
    status,
    payload,
    event_type,
    event_key,
    recipient_role,
    recipient_email,
    entity_type,
    entity_id,
