create or replace view "public"."be_v_wayplan_fleet_zoning_geojson" as  WITH zone_features AS (
         SELECT jsonb_build_object('type', 'Feature', 'id', be_wayplan_fleet_zones.zone_code, 'properties', jsonb_build_object('zone_code', be_wayplan_fleet_zones.zone_code, 'zone_name', be_wayplan_fleet_zones.zone_name, 'layer_type', be_wayplan_fleet_zones.layer_type, 'operation_type', be_wayplan_fleet_zones.operation_type, 'vehicle_assignment', be_wayplan_fleet_zones.vehicle_assignment, 'color_hex', be_wayplan_fleet_zones.color_hex, 'townships_included', be_wayplan_fleet_zones.townships_included), 'geometry', be_wayplan_fleet_zones.geometry) AS feature
           FROM public.be_wayplan_fleet_zones
          WHERE be_wayplan_fleet_zones.active
        ), location_features AS (
         SELECT jsonb_build_object('type', 'Feature', 'id', be_wayplan_service_locations.location_code, 'properties', jsonb_build_object('name', be_wayplan_service_locations.location_name, 'layer_type',
                CASE
                    WHEN (be_wayplan_service_locations.location_type = 'hub'::text) THEN 'hub'::text
                    ELSE 'service_location'::text
                END, 'marker-color',
                CASE
                    WHEN (be_wayplan_service_locations.location_type = 'hub'::text) THEN '#0000FF'::text
                    ELSE '#F6B84B'::text
                END, 'address', be_wayplan_service_locations.address, 'township', be_wayplan_service_locations.township, 'location_type', be_wayplan_service_locations.location_type, 'zone_code', be_wayplan_service_locations.zone_code, 'operation_type', be_wayplan_service_locations.operation_type), 'geometry', jsonb_build_object('type', 'Point', 'coordinates', jsonb_build_array(be_wayplan_service_locations.longitude, be_wayplan_service_locations.latitude))) AS feature
           FROM public.be_wayplan_service_locations
          WHERE (be_wayplan_service_locations.active AND (be_wayplan_service_locations.longitude IS NOT NULL) AND (be_wayplan_service_locations.latitude IS NOT NULL))
        )
 SELECT jsonb_build_object('type', 'FeatureCollection', 'features', COALESCE(jsonb_agg(feature), '[]'::jsonb)) AS geojson
   FROM ( SELECT location_features.feature
           FROM location_features
        UNION ALL
         SELECT zone_features.feature
           FROM zone_features) f;


CREATE OR REPLACE FUNCTION public.be_validate_bulk_row(p_row json)
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
DECLARE v_errors TEXT[] := '{}'; v_merchant_ok BOOLEAN;
BEGIN
  IF p_row->>'recipient_phone' IS NULL OR NOT ((p_row->>'recipient_phone') ~ '^(09|\+959)[0-9]{7,9}$') THEN v_errors := array_append(v_errors,'Invalid phone: '||(p_row->>'recipient_phone')); END IF;
  IF p_row->>'recipient_name' IS NULL OR length(trim(p_row->>'recipient_name'))<2 THEN v_errors := array_append(v_errors,'Recipient name too short'); END IF;
  IF p_row->>'delivery_address' IS NULL OR length(trim(p_row->>'delivery_address'))<5 THEN v_errors := array_append(v_errors,'Delivery address too short'); END IF;
  IF p_row->>'merchant_code' IS NULL THEN v_errors := array_append(v_errors,'merchant_code is required'); END IF;
  IF p_row->>'weight_kg' IS NOT NULL THEN IF (p_row->>'weight_kg')::NUMERIC <= 0 THEN v_errors := array_append(v_errors,'weight_kg must be positive'); END IF; END IF;
  SELECT EXISTS(SELECT 1 FROM public.be_masterdata_merchants WHERE merchant_code=p_row->>'merchant_code' AND status='active') INTO v_merchant_ok;
  IF NOT v_merchant_ok THEN v_errors := array_append(v_errors,'Unknown or inactive merchant: '||(p_row->>'merchant_code')); END IF;
  RETURN json_build_object('valid', array_length(v_errors,1) IS NULL, 'errors', to_json(v_errors));
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_validate_pickupway_id(p_id text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case
    when upper(trim(coalesce(p_id, ''))) ~ '^P[0-9]{4}-BRV-[0-9]{3}$'
      then upper(trim(p_id))
    else null
  end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_warehouse_action_v2(p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_action text := upper(coalesce(public.be_wh_text(p_payload, 'action', 'action_code'), 'SCAN'));
  v_exception_code text := upper(coalesce(public.be_wh_text(p_payload, 'exception_code', 'reason_code'), ''));
  v_wayplan text := public.be_wh_text(p_payload, 'wayplan_id', 'wayplan_code');
  v_way_id text := public.be_wh_text(p_payload, 'delivery_way_id', 'way_id', 'tracking_no');
  v_pickup text := public.be_wh_text(p_payload, 'pickup_id', 'pickup_way_id');
  v_actor text := public.be_wh_text(p_payload, 'actor_email', 'user_email');
  v_reason text := public.be_wh_text(p_payload, 'reason', 'note', 'remarks');
  v_status text;
  v_count integer := 0;
  v_batch text := coalesce(public.be_wh_text(p_payload, 'batch_id', 'warehouse_batch_id'), 'WH-' || to_char(now(), 'YYYYMMDD-HH24MISS'));
  v_rule record;
begin
  if v_action in ('MISSING','DAMAGED','EXCEPTION','HOLD') and v_exception_code = '' then
    v_exception_code := case
      when v_action = 'DAMAGED' then 'DAMAGED_PARCEL'
      when v_action = 'MISSING' then 'UNIDENTIFIED_PARCEL'
      when v_action = 'HOLD' then 'WAYBILL_MISMATCH'
      else 'UNIDENTIFIED_PARCEL'
    end;
  end if;

  if v_exception_code <> '' then
    select *
    into v_rule
    from public.be_logistics_exception_rules
    where process_type = 'WAREHOUSE'
      and exception_code = v_exception_code
      and active = true
    limit 1;
  end if;

  v_status := case
    when v_action = 'SCAN' then 'RECEIVED_AT_ORIGIN'
    when v_action = 'RECEIVE' then 'RECEIVED_AT_ORIGIN'
    when v_action = 'SORT' then 'SORTING'
    when v_action = 'DATA_ENTRY_COMPLETE' then 'DATA_ENTRY_COMPLETED'
    when v_action = 'READY_DISPATCH' then 'READY_FOR_DISPATCH'
    when v_action = 'LOAD_VEHICLE' then 'LOADED_TO_VEHICLE'
    when v_action = 'HANDOVER_RIDER' then 'OUT_FOR_DELIVERY'
    when v_action = 'RELEASE_HOLD' then 'READY_FOR_DISPATCH'
    when v_exception_code <> '' and v_rule.mapped_status is not null then v_rule.mapped_status
    when v_action in ('HOLD','MISSING','DAMAGED','EXCEPTION') then 'WAREHOUSE_HOLD'
    when v_action = 'RETURN_TO_CS' then 'CS_HOLD'
    else 'RECEIVED_AT_ORIGIN'
  end;

  update public.be_wayplan_dispatch_stops s
  set
    warehouse_status = v_status,
    warehouse_action = v_action,
    warehouse_actor_email = v_actor,
    warehouse_batch_id = v_batch,
    warehouse_hold_reason = case when coalesce(v_rule.hold_required, 'No') = 'YES' or v_action in ('HOLD','MISSING','DAMAGED','EXCEPTION') then coalesce(v_reason, v_rule.notes) else null end,
    warehouse_exception_status = case when v_exception_code <> '' or v_action in ('HOLD','MISSING','DAMAGED','EXCEPTION') then 'OPEN' else warehouse_exception_status end,
    warehouse_exception_reason = case when v_exception_code <> '' or v_action in ('HOLD','MISSING','DAMAGED','EXCEPTION') then coalesce(v_reason, v_rule.exception_name_en, v_exception_code) else warehouse_exception_reason end,
    warehouse_received_at = case when v_action in ('SCAN','RECEIVE') then now() else warehouse_received_at end,
    data_entry_completed_at = case when v_action = 'DATA_ENTRY_COMPLETE' then now() else data_entry_completed_at end,
    ready_for_dispatch_at = case when v_action in ('READY_DISPATCH','RELEASE_HOLD') then now() else ready_for_dispatch_at end,
    loaded_to_vehicle_at = case when v_action = 'LOAD_VEHICLE' then now() else loaded_to_vehicle_at end,
    handed_over_to_rider_at = case when v_action = 'HANDOVER_RIDER' then now() else handed_over_to_rider_at end,
    scan_count = coalesce(scan_count, 0) + case when v_action = 'SCAN' then 1 else 0 end,
    stop_status = case
      when v_action = 'LOAD_VEHICLE' then 'LOADED_TO_VEHICLE'
      when v_action = 'HANDOVER_RIDER' then 'OUT_FOR_DELIVERY'
      when v_status in ('READY_FOR_DISPATCH','SORTING','RECEIVED_AT_ORIGIN') then v_status
      else coalesce(stop_status, v_status)
    end,
    warehouse_metadata = coalesce(warehouse_metadata, '{}'::jsonb) || jsonb_build_object(
      'last_action', v_action,
      'exception_code', nullif(v_exception_code, ''),
      'mapped_status', v_status,
      'approval_team', v_rule.approval_team,
      'require_photo', v_rule.require_photo,
      'require_remark', v_rule.require_remark,
      'next_action', v_rule.next_action,
      'last_actor', v_actor,
      'last_reason', v_reason,
      'last_action_at', now(),
      'batch_id', v_batch
    ),
    updated_at = now()
  where
    (v_wayplan is null or s.wayplan_id = v_wayplan)
    and (
      v_way_id is null
      or s.delivery_way_id = v_way_id
      or s.tracking_no = v_way_id
      or s.waybill_no = v_way_id
    )
    and (v_pickup is null or s.pickup_id = v_pickup);

  get diagnostics v_count = row_count;

  if v_exception_code <> '' or v_action in ('HOLD','MISSING','DAMAGED','EXCEPTION') then
    insert into public.be_warehouse_exceptions (
      exception_code,
      exception_status,
      priority,
      wayplan_id,
      delivery_way_id,
      pickup_id,
      tracking_no,
      reason,
      actor_email,
      metadata
    )
    values (
      coalesce(nullif(v_exception_code, ''), v_action),
      'OPEN',
      coalesce(v_rule.severity, 'NORMAL'),
      v_wayplan,
      v_way_id,
      v_pickup,
      v_way_id,
      coalesce(v_reason, v_rule.exception_name_en, v_exception_code),
      v_actor,
      p_payload || jsonb_build_object(
        'mapped_status', v_status,
        'approval_team', v_rule.approval_team,
        'next_action', v_rule.next_action,
        'customer_message_en', v_rule.customer_message_en,
        'customer_message_mm', v_rule.customer_message_mm
      )
    );
  end if;

  if v_wayplan is not null then
    update public.be_wayplan_dispatches d
    set
      warehouse_status = case
        when v_action = 'LOAD_VEHICLE' then 'LOADED_TO_VEHICLE'
        when v_action = 'HANDOVER_RIDER' then 'OUT_FOR_DELIVERY'
        when v_action in ('READY_DISPATCH','RELEASE_HOLD') then 'READY_FOR_DISPATCH'
        when v_action in ('HOLD','MISSING','DAMAGED','EXCEPTION') then v_status
        else coalesce(d.warehouse_status, v_status)
      end,
      warehouse_batch_id = v_batch,
      warehouse_ready_at = case when v_action in ('READY_DISPATCH','RELEASE_HOLD') then now() else warehouse_ready_at end,
      loaded_to_vehicle_at = case when v_action = 'LOAD_VEHICLE' then now() else loaded_to_vehicle_at end,
      handed_over_to_rider_at = case when v_action = 'HANDOVER_RIDER' then now() else handed_over_to_rider_at end,
      warehouse_actor_email = v_actor,
      warehouse_metadata = coalesce(warehouse_metadata, '{}'::jsonb) || jsonb_build_object(
        'last_action', v_action,
        'exception_code', nullif(v_exception_code, ''),
        'mapped_status', v_status,
        'last_actor', v_actor,
        'last_reason', v_reason,
        'last_action_at', now(),
        'batch_id', v_batch
      ),
      updated_at = now()
    where d.wayplan_id = v_wayplan;
  end if;

  perform public.be_warehouse_audit(v_action, v_status, p_payload || jsonb_build_object(
    'warehouse_batch_id', v_batch,
    'affected_rows', v_count,
    'exception_code', nullif(v_exception_code, '')
  ));

  return jsonb_build_object(
    'ok', true,
    'action', v_action,
    'exception_code', nullif(v_exception_code, ''),
    'status', v_status,
    'next_action', v_rule.next_action,
    'approval_team', v_rule.approval_team,
    'warehouse_batch_id', v_batch,
    'affected_rows', v_count,
    'wayplan_id', v_wayplan,
    'delivery_way_id', v_way_id,
    'pickup_id', v_pickup
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_warehouse_bulk_import_excel(p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_rows jsonb := coalesce(p_payload->'rows', '[]'::jsonb);
  v_row jsonb;
  v_batch text := coalesce(public.be_wh_text(p_payload, 'import_batch_id', 'batch_id'), 'WH-IMPORT-' || to_char(now(), 'YYYYMMDD-HH24MISS'));
  v_file text := public.be_wh_text(p_payload, 'source_file_name', 'file_name');
  v_actor text := public.be_wh_text(p_payload, 'actor_email', 'user_email');
  v_idx integer := 0;
  v_errors jsonb;
  v_way text;
  v_inserted integer := 0;
begin
  if jsonb_typeof(v_rows) <> 'array' then
    raise exception 'p_payload.rows must be an array';
  end if;

  for v_row in select * from jsonb_array_elements(v_rows)
  loop
    v_idx := v_idx + 1;
    v_way := public.be_wh_text(v_row, 'way_id', 'Way ID', 'delivery_way_id', 'tracking_no', 'id');

    v_errors := '[]'::jsonb;

    if v_way is null then
      v_errors := v_errors || jsonb_build_array('Missing Way ID / way_id');
    end if;

    if public.be_wh_text(v_row, 'recipient_name', 'Recipient name') is null then
      v_errors := v_errors || jsonb_build_array('Missing recipient name');
    end if;

    insert into public.be_warehouse_bulk_import_rows (
      import_batch_id,
      source_file_name,
      row_no,
      row_status,
      validation_status,
      validation_errors,
      way_id,
      delivery_way_id,
      pickup_id,
      merchant,
      recipient_name,
      recipient_phone,
      township,
      delivery_address,
      item_price,
      delivery_fee,
      weight_kg,
      surcharge,
      cod_amount,
      actual_collect,
      destination,
      pickup_by,
      remarks,
      driver_code,
      driver_name,
      rider_code,
      rider_name,
      helper_code,
      helper_name,
      vehicle_plate,
      manifest_group,
      route_type,
      route_date,
      highway_drop,
      raw_row,
      actor_email
    )
    values (
      v_batch,
      v_file,
      v_idx,
      'STAGED',
      case when jsonb_array_length(v_errors) = 0 then 'VALID' else 'INVALID' end,
      v_errors,
      v_way,
      public.be_wh_text(v_row, 'delivery_way_id', 'way_id', 'Way ID', 'tracking_no'),
      public.be_wh_text(v_row, 'pickup_id', 'pickup_way_id'),
      public.be_wh_text(v_row, 'merchant', 'Merchant', 'merchant_id'),
      public.be_wh_text(v_row, 'recipient_name', 'Recipient name', 'receiver_name'),
      public.be_wh_text(v_row, 'recipient_phone', 'Recipient phone', 'receiver_phone'),
      public.be_wh_text(v_row, 'township', 'Town', 'Township', 'destination'),
      public.be_wh_text(v_row, 'delivery_address', 'Recipient address', 'recipient_address'),
      public.be_wh_num(v_row, 'item_price', 'Item price'),
      public.be_wh_num(v_row, 'delivery_fee', 'Delivery Fee (OS)', 'delivery_charges'),
      public.be_wh_num(v_row, 'weight_kg', 'Weight'),
      public.be_wh_num(v_row, 'surcharge', 'Surcharge'),
      public.be_wh_num(v_row, 'cod_amount', 'COD'),
      public.be_wh_num(v_row, 'actual_collect', 'Actual Collect'),
      public.be_wh_text(v_row, 'destination', 'Destination'),
      public.be_wh_text(v_row, 'pickup_by', 'Pickup By'),
      public.be_wh_text(v_row, 'remarks', 'Remarks'),
      public.be_wh_text(v_row, 'driver_code', 'Driver Code'),
      public.be_wh_text(v_row, 'driver_name', 'Driver Name'),
      public.be_wh_text(v_row, 'rider_code', 'Rider Code'),
      public.be_wh_text(v_row, 'rider_name', 'Rider Name'),
      public.be_wh_text(v_row, 'helper_code', 'Helper Code'),
      public.be_wh_text(v_row, 'helper_name', 'Helper Name'),
      public.be_wh_text(v_row, 'vehicle_plate', 'Vehicle Plate'),
      public.be_wh_text(v_row, 'manifest_group', 'Manifest Group'),
      public.be_wh_text(v_row, 'route_type', 'Route Type'),
      public.be_wh_date(v_row, 'route_date', 'Route Date', 'Pickup Date'),
      coalesce(lower(public.be_wh_text(v_row, 'highway_drop', 'Highway Drop')) in ('true','yes','1','y'), false),
      v_row,
      v_actor
    );

    v_inserted := v_inserted + 1;
  end loop;

  perform public.be_warehouse_audit('BULK_IMPORT_EXCEL', 'STAGED', p_payload || jsonb_build_object(
    'import_batch_id', v_batch,
    'rows_inserted', v_inserted
  ));

  return jsonb_build_object(
    'ok', true,
    'import_batch_id', v_batch,
    'rows_inserted', v_inserted,
    'valid_rows', (
      select count(*) from public.be_warehouse_bulk_import_rows
      where import_batch_id = v_batch and validation_status = 'VALID'
    ),
    'invalid_rows', (
      select count(*) from public.be_warehouse_bulk_import_rows
      where import_batch_id = v_batch and validation_status = 'INVALID'
    )
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_warehouse_bulk_update_rows(p_rows jsonb, p_original_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row jsonb;
  v_way_id text;
  v_result jsonb;
  v_total integer := 0;
  v_updated integer := 0;
  v_failed integer := 0;
  v_failures jsonb := '[]'::jsonb;
  v_upload_id uuid;
begin
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' then
    raise exception 'p_rows must be a JSON array';
  end if;

  for v_row in select * from jsonb_array_elements(p_rows) loop
    v_total := v_total + 1;
    v_way_id := coalesce(
      v_row->>'way_id',
      v_row->>'wayId',
      v_row->>'Way ID',
      v_row->>'WayID',
      v_row->>'wayid',
      v_row->>'deliver_way_id',
      v_row->>'delivery_way_id',
      v_row->>'tracking_no'
    );

    if v_way_id is null or btrim(v_way_id) = '' then
      v_failed := v_failed + 1;
      v_failures := v_failures || jsonb_build_array(jsonb_build_object('row', v_total, 'error', 'Missing Way ID'));
      continue;
    end if;

    begin
      v_result := public.be_warehouse_update_situation(
        p_way_id := v_way_id,
        p_row_id := null,
        p_status := coalesce(v_row->>'status', v_row->>'warehouse_status', v_row->>'Warehouse Status', 'warehouse_received'),
        p_package_condition := coalesce(v_row->>'package_condition', v_row->>'Package Condition'),
        p_exception_code := coalesce(v_row->>'exception_code', v_row->>'Exception Code'),
        p_exception_note := coalesce(v_row->>'exception_note', v_row->>'Exception Note'),
        p_warehouse_location := coalesce(v_row->>'warehouse_location', v_row->>'Warehouse Location'),
        p_shelf_bin := coalesce(v_row->>'shelf_bin', v_row->>'Shelf / Bin', v_row->>'Shelf Bin'),
        p_handover_to := coalesce(v_row->>'handover_to', v_row->>'Handover To'),
        p_warehouse_staff := coalesce(v_row->>'warehouse_staff', v_row->>'Warehouse Staff'),
        p_evidence_url := coalesce(v_row->>'evidence_url', v_row->>'Photo / Evidence URL'),
        p_remarks := coalesce(v_row->>'remarks', v_row->>'Remarks')
      );

      v_updated := v_updated + 1;
    exception when others then
      v_failed := v_failed + 1;
      v_failures := v_failures || jsonb_build_array(jsonb_build_object('row', v_total, 'way_id', v_way_id, 'error', sqlerrm));
    end;
  end loop;

  insert into public.warehouse_bulk_uploads (
    original_name,
    row_count,
    accepted_count,
    failed_count,
    status,
    result
  ) values (
    p_original_name,
    v_total,
    v_updated,
    v_failed,
    case when v_failed = 0 then 'processed' else 'processed_with_errors' end,
    jsonb_build_object('updated', v_updated, 'failed', v_failed, 'failures', v_failures)
  ) returning id into v_upload_id;

  return jsonb_build_object(
    'ok', true,
    'upload_id', v_upload_id,
    'row_count', v_total,
    'updated', v_updated,
    'failed', v_failed,
    'failures', v_failures
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_warehouse_bulk_update_upload(p_bucket text, p_file_path text, p_original_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_upload_id uuid;
begin
  insert into public.warehouse_bulk_uploads (
    original_name,
    bucket,
    file_path,
    status,
    result
  ) values (
    p_original_name,
    p_bucket,
    p_file_path,
    'uploaded_pending_parser',
    jsonb_build_object(
      'message', 'File was registered. Use be_warehouse_bulk_update_rows for immediate parsed-row processing, or attach an Edge Function parser for storage files.',
      'bucket', p_bucket,
      'file_path', p_file_path
    )
  ) returning id into v_upload_id;

  return jsonb_build_object(
    'ok', true,
    'upload_id', v_upload_id,
    'status', 'uploaded_pending_parser',
    'message', 'File registered. For immediate bulk update, send parsed rows to be_warehouse_bulk_update_rows.'
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_warehouse_dispatch(p_pickup_ids text[], p_rider_id text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE v_role TEXT := public.be_current_user_role(); v_count INT:=0;
BEGIN
  IF v_role NOT IN ('admin','operation_manager','warehouse','supervisor','dispatch') THEN RAISE EXCEPTION 'Access denied'; END IF;
  UPDATE public.be_portal_pickup_requests SET status='IN_TRANSIT', assigned_rider_id=p_rider_id, updated_at=NOW()
  WHERE pickup_id=ANY(p_pickup_ids) AND status IN ('IN_WAREHOUSE','SUBMITTED','PICKED_UP');
  GET DIAGNOSTICS v_count = ROW_COUNT;
  INSERT INTO public.be_portal_cargo_events(pickup_id,event_type,description,actor_role,created_at)
  SELECT pid,'DISPATCHED','Dispatched from warehouse to rider: '||p_rider_id, v_role, NOW()
  FROM UNNEST(p_pickup_ids) AS pid;
  RETURN json_build_object('success',true,'dispatched',v_count,'rider_id',p_rider_id);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_warehouse_go_live_verification()
 RETURNS json
 LANGUAGE sql
 STABLE SECURITY DEFINER
AS $function$
  SELECT json_build_object('ok',true,'rpc_count',(SELECT count(*) FROM pg_proc WHERE proname LIKE 'be_warehouse_%'),'ts',NOW());
$function$
;

CREATE OR REPLACE FUNCTION public.be_warehouse_inbound_queue(p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object('ok', true, 'items', coalesce(jsonb_agg(to_jsonb(p) order by p.updated_at desc), '[]'::jsonb), 'data', coalesce(jsonb_agg(to_jsonb(p) order by p.updated_at desc), '[]'::jsonb))
  from public.be_portal_pickup_requests p
  where upper(coalesce(p.warehouse_status, '')) in ('WAITING_DATA_ENTRY', 'IN_TRANSIT_TO_WAREHOUSE', 'WAITING_INBOUND', 'INBOUND_READY')
     or upper(coalesce(p.pickup_status, '')) in ('PICKUP_VERIFIED', 'PICKUP_COLLECTED');
$function$
;

CREATE OR REPLACE FUNCTION public.be_warehouse_intake_scan(p_pickup_id text, p_location text DEFAULT 'INTAKE'::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE v_role TEXT := public.be_current_user_role(); v_status TEXT;
BEGIN
  IF v_role NOT IN ('admin','operation_manager','warehouse','supervisor') THEN RAISE EXCEPTION 'Access denied'; END IF;
  SELECT status INTO v_status FROM public.be_portal_pickup_requests WHERE pickup_id=p_pickup_id;
  IF v_status IS NULL THEN RAISE EXCEPTION 'Shipment not found: %', p_pickup_id; END IF;
  IF v_status NOT IN ('SUBMITTED','PICKED_UP') THEN RAISE EXCEPTION 'Cannot intake shipment in status: %', v_status; END IF;
  UPDATE public.be_portal_pickup_requests SET status='IN_WAREHOUSE', warehouse_location=p_location, updated_at=NOW() WHERE pickup_id=p_pickup_id;
  INSERT INTO public.be_portal_cargo_events(pickup_id,event_type,description,actor_role,created_at)
  VALUES(p_pickup_id,'INTAKE_SCAN','Received at warehouse — location: '||p_location, v_role, NOW());
  RETURN json_build_object('success',true,'pickup_id',p_pickup_id,'location',p_location,'prev_status',v_status);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_warehouse_lifecycle_action(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_action text;
  v_pickup_id text;
  v_actor_email text;
  v_notes text;
  v_next_status text;
  v_parcel_status text;
  v_updated_parcels integer := 0;
  v_updated_ledger integer := 0;
  v_updated_pickup integer := 0;
begin
  v_action := upper(coalesce(
    p_payload->>'action',
    p_payload->>'warehouse_action',
    ''
  ));

  v_pickup_id := nullif(coalesce(
    p_payload->>'pickup_way_id',
    p_payload->>'pickup_id',
    p_payload->>'request_code'
  ), '');

  v_actor_email := nullif(coalesce(
    p_payload->>'actor_email',
    p_payload->>'warehouse_email',
    'warehouse@britiumexpress.com'
  ), '');

  v_notes := nullif(coalesce(
    p_payload->>'notes',
    p_payload->>'warehouse_notes'
  ), '');

  if v_pickup_id is null then
    return jsonb_build_object(
      'ok', false,
      'error', 'pickup_id / pickup_way_id is required',
      'payload', p_payload
    );
  end if;

  if v_action in ('RECEIVE', 'WAREHOUSE_RECEIVE', 'RECEIVED_AT_ORIGIN') then
    v_next_status := 'RECEIVED_AT_ORIGIN';
    v_parcel_status := 'at_branch';

  elsif v_action in ('SORT', 'SORTING') then
    v_next_status := 'SORTING';
    v_parcel_status := 'at_branch';

  elsif v_action in ('READY_FOR_DISPATCH', 'MARK_READY_FOR_DISPATCH') then
    v_next_status := 'READY_FOR_DISPATCH';
    v_parcel_status := 'at_branch';

  else
    return jsonb_build_object(
      'ok', false,
      'error', 'Unsupported warehouse action',
      'action', v_action,
      'supported_actions', jsonb_build_array(
        'WAREHOUSE_RECEIVE',
        'SORTING',
        'READY_FOR_DISPATCH'
      )
    );
  end if;

  update public.be_waybill_ledger
  set
    warehouse_status = v_next_status,
    pickup_status = case
      when v_next_status = 'RECEIVED_AT_ORIGIN' then 'WAREHOUSE_RECEIVED'
      else pickup_status
    end,
    data_entry_status = coalesce(data_entry_status, 'PARCEL_BULK_LOADED'),
    status = lower(v_next_status),
    updated_at = now(),
    payload = coalesce(payload, '{}'::jsonb) || jsonb_build_object(
      'last_warehouse_action', v_action,
      'last_warehouse_status', v_next_status,
      'warehouse_actor', v_actor_email,
      'warehouse_notes', v_notes,
      'warehouse_action_at', now()
    )
  where pickup_id = v_pickup_id
     or pickup_way_id = v_pickup_id;

  get diagnostics v_updated_ledger = row_count;

  update public.parcels p
  set
    status = v_parcel_status,
    updated_at = now(),
    notes = coalesce(p.notes, '') || ' | Warehouse action ' || v_next_status || ' for pickup ' || v_pickup_id
  where p.tracking_code in (
    select coalesce(w.tracking_no, w.waybill_no, w.delivery_way_id)
    from public.be_waybill_ledger w
    where w.pickup_id = v_pickup_id
       or w.pickup_way_id = v_pickup_id
  )
  and p.status not in ('delivered', 'returned', 'cancelled');

  get diagnostics v_updated_parcels = row_count;

  update public.be_portal_pickup_requests
  set
    warehouse_status = v_next_status,
    workflow_stage = v_next_status,
    pickup_status = case
      when v_next_status = 'RECEIVED_AT_ORIGIN' then 'WAREHOUSE_RECEIVED'
      else v_next_status
    end,
    status = case
      when v_next_status = 'RECEIVED_AT_ORIGIN' then 'WAREHOUSE_RECEIVED'
      else v_next_status
    end,
    metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
      'last_warehouse_action', v_action,
      'last_warehouse_status', v_next_status,
      'warehouse_actor', v_actor_email,
      'warehouse_notes', v_notes,
      'warehouse_action_at', now()
    ),
    updated_at = now()
  where pickup_way_id = v_pickup_id
     or pickup_id = v_pickup_id
     or request_code = v_pickup_id;

  get diagnostics v_updated_pickup = row_count;

  if v_next_status = 'READY_FOR_DISPATCH' then
    insert into public.be_app_notifications (
      title,
      body,
      message,
      status,
      is_read,
      category,
      notification_type,
      event_type,
      event_key,
      source_key,
      source_table,
      pickup_id,
      pickup_way_id,
      target_role,
      metadata,
      payload,
      created_at
    )
    values (
      'Pickup ready for dispatch',
      'Pickup ' || v_pickup_id || ' is ready for dispatch planning.',
      'Pickup ' || v_pickup_id || ' is ready for dispatch planning.',
      'unread',
      false,
      'dispatch',
      'WAREHOUSE_READY_FOR_DISPATCH',
      'warehouse_ready_for_dispatch',
      'workflow:dispatch:be_portal_pickup_requests:' || v_pickup_id,
      v_pickup_id,
      'be_portal_pickup_requests',
      v_pickup_id,
      v_pickup_id,
      'dispatch',
      jsonb_build_object(
        'source', 'be_warehouse_lifecycle_action',
        'pickup_id', v_pickup_id,
        'next_action', 'DISPATCH_PLAN',
        'workflow_stage', 'READY_FOR_DISPATCH'
      ),
      jsonb_build_object(
        'pickup_id', v_pickup_id,
        'pickup_way_id', v_pickup_id,
        'next_action', 'DISPATCH_PLAN'
      ),
      now()
    )
    on conflict (event_key) do update
    set
      status = 'unread',
      is_read = false,
      notification_type = 'WAREHOUSE_READY_FOR_DISPATCH',
      metadata = coalesce(public.be_app_notifications.metadata, '{}'::jsonb) || excluded.metadata,
      payload = coalesce(public.be_app_notifications.payload, '{}'::jsonb) || excluded.payload;
  end if;

  return jsonb_build_object(
    'ok', true,
    'source', 'be_warehouse_lifecycle_action',
    'pickup_id', v_pickup_id,
    'action', v_action,
    'warehouse_status', v_next_status,
    'parcel_status', v_parcel_status,
    'updated_pickup_rows', v_updated_pickup,
    'updated_ledger_rows', v_updated_ledger,
    'updated_parcel_rows', v_updated_parcels,
    'next_action', case
      when v_next_status = 'READY_FOR_DISPATCH' then 'DISPATCH_PLAN'
      when v_next_status = 'SORTING' then 'READY_FOR_DISPATCH'
      else 'SORTING'
    end
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_warehouse_list(p_zone text DEFAULT NULL::text, p_limit integer DEFAULT 50)
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
DECLARE v_role TEXT := public.be_current_user_role();
BEGIN
  IF v_role NOT IN ('admin','operation_manager','warehouse','supervisor','dispatch') THEN RAISE EXCEPTION 'Access denied'; END IF;
  RETURN (SELECT COALESCE(json_agg(row_to_json(t)),'[]'::json) FROM (
    SELECT pickup_id, merchant_name, recipient_name, recipient_phone,
           delivery_township, delivery_address, warehouse_location,
           weight_kg, service_tier, status, updated_at
    FROM public.be_portal_pickup_requests
    WHERE status='IN_WAREHOUSE'
      AND (p_zone IS NULL OR warehouse_location=p_zone)
    ORDER BY updated_at ASC LIMIT p_limit
  ) t);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_warehouse_scan(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare pid text := coalesce(p_payload->>'pickup_id',p_payload->>'pickup_way_id'); scan text := lower(coalesce(p_payload->>'scan_type','inbound')); st text; r record;
begin
  select * into r from public.be_portal_pickup_requests where pickup_id=pid or pickup_way_id=pid limit 1;
  if not found then raise exception 'Pickup % not found',pid; end if;
  st := case when scan in ('inbound','received','receive') then 'received' when scan in ('warehouse','in_warehouse') then 'in_warehouse' when scan in ('sort','sorting') then 'sorting' when scan in ('bag','bagged') then 'bagged' when scan in ('dispatch','dispatched') then 'dispatched' else scan end;
  insert into public.be_warehouse_scans(pickup_id,waybill_no,scan_type,warehouse_branch,operator_code,bag_code,route_zone,expected_parcel_count,scanned_parcel_count,status,metadata,created_at)
  values(r.pickup_id,r.waybill_no,scan,coalesce(p_payload->>'warehouse_branch',r.assigned_branch),p_payload->>'operator_code',p_payload->>'bag_code',coalesce(p_payload->>'route_zone',r.route_zone),r.parcel_count,coalesce(nullif(p_payload->>'scanned_parcel_count','')::int,r.parcel_count),st,p_payload,now());
  update public.be_portal_pickup_requests set status=st,warehouse_status=st,updated_at=now() where id=r.id;
  update public.be_waybill_ledger set status=st,updated_at=now() where waybill_no=r.waybill_no;
  perform public.be30_event(r.pickup_id,'warehouse_scan',st,'warehouse',p_payload->>'operator_code',p_payload);
  return jsonb_build_object('ok',true,'pickup_id',r.pickup_id,'warehouse_status',st);
end; $function$
;

CREATE OR REPLACE FUNCTION public.be_warehouse_scan_action(p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_waybill text := coalesce(p_payload->>'waybill_no', p_payload->>'tracking_no', '');
  v_action text := upper(coalesce(p_payload->>'action', 'INBOUND'));
  v_reason text := coalesce(p_payload->>'reason', '');
  v_note text := coalesce(p_payload->>'note', '');
  v_actor text := coalesce(p_payload->>'actor', 'warehouse@britiumexpress.com');
  v_status text;
  v_count integer := 0;
begin
  if v_waybill = '' then
    raise exception 'waybill_no is required';
  end if;

  v_status := case
    when v_action = 'INBOUND' then 'RECEIVED_AT_ORIGIN'
    when v_action = 'DISPATCH' then 'READY_FOR_DISPATCH'
    when v_action = 'RETURN' then 'RTO_INITIATED'
    when v_action = 'SORTING' then 'SORTING'
    else v_action
  end;

  update public.be_data_entry_parcel_details
  set warehouse_status = v_status,
      inbound_scanned_at = case when v_action = 'INBOUND' then now() else inbound_scanned_at end,
      dispatch_scanned_at = case when v_action = 'DISPATCH' then now() else dispatch_scanned_at end,
      return_scanned_at = case when v_action = 'RETURN' then now() else return_scanned_at end,
      updated_at = now()
  where way_id = v_waybill or delivery_way_id = v_waybill;

  get diagnostics v_count = row_count;

  insert into public.be_warehouse_scan_events(
    waybill_no, pickup_id, scan_type, scan_note, reason, actor, payload
  )
  select
    coalesce(way_id, delivery_way_id),
    pickup_id,
    v_action,
    v_note,
    v_reason,
    v_actor,
    p_payload
  from public.be_data_entry_parcel_details
  where way_id = v_waybill or delivery_way_id = v_waybill
  limit 1;

  insert into public.be_waybill_status_events(
    waybill_no, pickup_id, event_code, event_name, actor, source_module, note, payload
  )
  select
    coalesce(way_id, delivery_way_id),
    pickup_id,
    v_status,
    v_status,
    v_actor,
    'WAREHOUSE',
    v_note,
    p_payload
  from public.be_data_entry_parcel_details
  where way_id = v_waybill or delivery_way_id = v_waybill
  limit 1;

  return jsonb_build_object('ok', true, 'updated_count', v_count, 'status', v_status);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_warehouse_snapshot(p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
AS $function$
  select jsonb_build_object('ok',true,'warehouse_rows',coalesce((select jsonb_agg(row_to_json(x)::jsonb order by updated_at desc) from public.be_warehouse_parcel_status x),'[]'::jsonb));
$function$
;

CREATE OR REPLACE FUNCTION public.be_warehouse_sort_scan(p_pickup_id text, p_sort_zone text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE v_role TEXT := public.be_current_user_role();
BEGIN
  IF v_role NOT IN ('admin','operation_manager','warehouse','supervisor') THEN RAISE EXCEPTION 'Access denied'; END IF;
  UPDATE public.be_portal_pickup_requests SET warehouse_location=p_sort_zone, updated_at=NOW() WHERE pickup_id=p_pickup_id;
  INSERT INTO public.be_portal_cargo_events(pickup_id,event_type,description,actor_role,created_at)
  VALUES(p_pickup_id,'SORT_SCAN','Sorted to zone: '||p_sort_zone, v_role, NOW());
  RETURN json_build_object('success',true,'pickup_id',p_pickup_id,'sort_zone',p_sort_zone);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_warehouse_summary()
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
DECLARE v_role TEXT := public.be_current_user_role();
BEGIN
  IF v_role NOT IN ('admin','operation_manager','warehouse','supervisor') THEN RAISE EXCEPTION 'Access denied'; END IF;
  RETURN (SELECT json_build_object(
    'in_warehouse', (SELECT COUNT(*) FROM public.be_portal_pickup_requests WHERE status='IN_WAREHOUSE'),
    'pending_sort', (SELECT COUNT(*) FROM public.be_portal_pickup_requests WHERE status='IN_WAREHOUSE' AND (warehouse_location IS NULL OR warehouse_location='INTAKE')),
    'pending_dispatch', (SELECT COUNT(*) FROM public.be_portal_pickup_requests WHERE status='IN_WAREHOUSE' AND warehouse_location IS NOT NULL AND warehouse_location!='INTAKE'),
    'zones', (SELECT COALESCE(json_agg(row_to_json(z)),'[]'::json) FROM (
      SELECT warehouse_location AS zone, COUNT(*) AS count
      FROM public.be_portal_pickup_requests WHERE status='IN_WAREHOUSE' AND warehouse_location IS NOT NULL
      GROUP BY warehouse_location ORDER BY count DESC
    ) z)
  ));
END;
$function$
;

CREATE OR REPLACE FUNCTION public.be_warehouse_update_situation(p_way_id text, p_row_id uuid DEFAULT NULL::uuid, p_status text DEFAULT 'warehouse_received'::text, p_package_condition text DEFAULT NULL::text, p_exception_code text DEFAULT NULL::text, p_exception_note text DEFAULT NULL::text, p_warehouse_location text DEFAULT NULL::text, p_shelf_bin text DEFAULT NULL::text, p_handover_to text DEFAULT NULL::text, p_warehouse_staff text DEFAULT NULL::text, p_evidence_url text DEFAULT NULL::text, p_remarks text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_log_id uuid;
  v_tables text[] := array[
    'cargo_events',
    'delivery_waybills',
    'deliveries',
    'shipments',
    'waybills',
    'pickup_delivery_rows',
    'data_entry_delivery_rows',
    'parcel_events',
    'parcels'
  ];
  v_match_cols text[] := array[
    'id',
    'deliver_way_id',
    'delivery_way_id',
    'tracking_no',
    'tracking_number',
    'awb',
    'waybill_number'
  ];
  v_table text;
  v_match_col text;
  v_match_value text;
  v_updates integer := 0;
  v_payload jsonb;
begin
  if p_way_id is null or btrim(p_way_id) = '' then
    raise exception 'p_way_id is required';
  end if;

  v_payload := jsonb_build_object(
    'way_id', p_way_id,
    'row_id', p_row_id,
    'status', p_status,
    'package_condition', p_package_condition,
    'exception_code', p_exception_code,
    'exception_note', p_exception_note,
    'warehouse_location', p_warehouse_location,
    'shelf_bin', p_shelf_bin,
    'handover_to', p_handover_to,
    'warehouse_staff', p_warehouse_staff,
    'evidence_url', p_evidence_url,
    'remarks', p_remarks,
    'updated_at', now()
  );

  insert into public.warehouse_situation_updates (
    way_id,
    row_id,
    status,
    package_condition,
    exception_code,
    exception_note,
    warehouse_location,
    shelf_bin,
    handover_to,
    warehouse_staff,
    evidence_url,
    remarks,
    payload
  ) values (
    p_way_id,
    p_row_id,
    coalesce(nullif(p_status, ''), 'warehouse_received'),
    nullif(p_package_condition, ''),
    nullif(p_exception_code, ''),
    nullif(p_exception_note, ''),
    nullif(p_warehouse_location, ''),
    nullif(p_shelf_bin, ''),
    nullif(p_handover_to, ''),
    nullif(p_warehouse_staff, ''),
    nullif(p_evidence_url, ''),
    nullif(p_remarks, ''),
    v_payload
  ) returning id into v_log_id;

  foreach v_table in array v_tables loop
    foreach v_match_col in array v_match_cols loop
      if v_match_col = 'id' then
        v_match_value := p_row_id::text;
      else
        v_match_value := p_way_id;
      end if;

      if v_match_value is null or btrim(v_match_value) = '' then
        continue;
      end if;

      -- Status/status-like columns.
      v_updates := v_updates + public.be__warehouse_update_one(v_table, v_match_col, v_match_value, 'warehouse_status', p_status);
      v_updates := v_updates + public.be__warehouse_update_one(v_table, v_match_col, v_match_value, 'status', p_status);
      v_updates := v_updates + public.be__warehouse_update_one(v_table, v_match_col, v_match_value, 'current_status', p_status);

      -- Situation columns.
      v_updates := v_updates + public.be__warehouse_update_one(v_table, v_match_col, v_match_value, 'package_condition', p_package_condition);
      v_updates := v_updates + public.be__warehouse_update_one(v_table, v_match_col, v_match_value, 'warehouse_condition', p_package_condition);
      v_updates := v_updates + public.be__warehouse_update_one(v_table, v_match_col, v_match_value, 'exception_code', p_exception_code);
      v_updates := v_updates + public.be__warehouse_update_one(v_table, v_match_col, v_match_value, 'warehouse_exception_code', p_exception_code);
      v_updates := v_updates + public.be__warehouse_update_one(v_table, v_match_col, v_match_value, 'exception_note', p_exception_note);
      v_updates := v_updates + public.be__warehouse_update_one(v_table, v_match_col, v_match_value, 'warehouse_exception_note', p_exception_note);
      v_updates := v_updates + public.be__warehouse_update_one(v_table, v_match_col, v_match_value, 'warehouse_location', p_warehouse_location);
      v_updates := v_updates + public.be__warehouse_update_one(v_table, v_match_col, v_match_value, 'shelf_bin', p_shelf_bin);
      v_updates := v_updates + public.be__warehouse_update_one(v_table, v_match_col, v_match_value, 'bin_location', p_shelf_bin);
      v_updates := v_updates + public.be__warehouse_update_one(v_table, v_match_col, v_match_value, 'shelf', p_shelf_bin);
      v_updates := v_updates + public.be__warehouse_update_one(v_table, v_match_col, v_match_value, 'handover_to', p_handover_to);
      v_updates := v_updates + public.be__warehouse_update_one(v_table, v_match_col, v_match_value, 'warehouse_staff', p_warehouse_staff);
      v_updates := v_updates + public.be__warehouse_update_one(v_table, v_match_col, v_match_value, 'received_by', p_warehouse_staff);
      v_updates := v_updates + public.be__warehouse_update_one(v_table, v_match_col, v_match_value, 'evidence_url', p_evidence_url);
      v_updates := v_updates + public.be__warehouse_update_one(v_table, v_match_col, v_match_value, 'photo_url', p_evidence_url);
      v_updates := v_updates + public.be__warehouse_update_one(v_table, v_match_col, v_match_value, 'warehouse_photo_url', p_evidence_url);
      v_updates := v_updates + public.be__warehouse_update_one(v_table, v_match_col, v_match_value, 'remarks', p_remarks);
      v_updates := v_updates + public.be__warehouse_update_one(v_table, v_match_col, v_match_value, 'warehouse_remarks', p_remarks);
      v_updates := v_updates + public.be__warehouse_touch_table(v_table, v_match_col, v_match_value);
    end loop;
  end loop;

  return jsonb_build_object(
    'ok', true,
    'log_id', v_log_id,
    'way_id', p_way_id,
    'status', coalesce(nullif(p_status, ''), 'warehouse_received'),
    'target_updates', v_updates,
    'warning', case when v_updates = 0 then 'Situation was logged, but no matching operational row/table was updated. Check Way ID or schema column names.' else null end
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_warehouse_wayplan_action(p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select public.be_warehouse_action_v2(p_payload);
$function$
;

CREATE OR REPLACE FUNCTION public.be_warehouse_wayplan_center(p_limit integer DEFAULT 300)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_rows jsonb;
  v_summary jsonb;
  v_exceptions jsonb;
  v_imports jsonb;
  v_count integer := 0;
begin
  select coalesce(jsonb_agg(to_jsonb(x) order by x.wayplan_id desc nulls last, x.delivery_way_id), '[]'::jsonb)
  into v_rows
  from (
    select
      s.*,
      d.rider_code,
      d.rider_name,
      d.driver_code,
      d.driver_name,
      d.helper_code,
      d.helper_name,
      d.vehicle_code,
      d.vehicle_name,
      d.wayplan_status,
      coalesce(s.warehouse_status, s.stop_status) as live_warehouse_status,
      case when coalesce(s.warehouse_exception_status, '') = 'OPEN' then true else false end as has_open_exception,
      case
        when coalesce(s.warehouse_status, s.stop_status, '') in ('READY_FOR_DISPATCH','LOADED_TO_VEHICLE')
        then true
        else false
      end as can_load_or_handover
    from public.be_wayplan_dispatch_stops s
    left join public.be_wayplan_dispatches d
      on d.wayplan_id = s.wayplan_id
    order by s.updated_at desc nulls last
    limit greatest(coalesce(p_limit, 300), 1)
  ) x;

  v_count := jsonb_array_length(v_rows);

  select jsonb_build_object(
    'total_stops', count(*),
    'warehouse_received', count(*) filter (where coalesce(warehouse_status, stop_status) in ('RECEIVED_AT_ORIGIN','WAREHOUSE_RECEIVED','WAREHOUSE_SCANNED')),
    'sorting', count(*) filter (where coalesce(warehouse_status, stop_status) = 'SORTING'),
    'data_entry_completed', count(*) filter (where coalesce(warehouse_status, stop_status) = 'DATA_ENTRY_COMPLETED'),
    'ready_for_dispatch', count(*) filter (where coalesce(warehouse_status, stop_status) = 'READY_FOR_DISPATCH'),
    'loaded_to_vehicle', count(*) filter (where coalesce(warehouse_status, stop_status) = 'LOADED_TO_VEHICLE'),
    'handed_over_to_rider', count(*) filter (where coalesce(warehouse_status, stop_status) in ('HANDOVER_TO_RIDER','OUT_FOR_DELIVERY')),
    'delivered', count(*) filter (where stop_status = 'DELIVERED'),
    'open_exceptions', count(*) filter (where warehouse_exception_status = 'OPEN'),
    'on_hold', count(*) filter (where coalesce(warehouse_status, stop_status) in ('WAREHOUSE_HOLD','FINANCE_HOLD','CS_HOLD'))
  )
  into v_summary
  from public.be_wayplan_dispatch_stops;

  select coalesce(jsonb_agg(to_jsonb(e) order by e.created_at desc), '[]'::jsonb)
  into v_exceptions
  from (
    select *
    from public.be_warehouse_exceptions
    where exception_status = 'OPEN'
    order by created_at desc
    limit 50
  ) e;

  select coalesce(jsonb_agg(to_jsonb(i) order by i.imported_at desc), '[]'::jsonb)
  into v_imports
  from (
    select
      import_batch_id,
      source_file_name,
      count(*) as total_rows,
      count(*) filter (where validation_status = 'VALID') as valid_rows,
      count(*) filter (where validation_status = 'INVALID') as invalid_rows,
      max(created_at) as imported_at
    from public.be_warehouse_bulk_import_rows
    group by import_batch_id, source_file_name
    order by max(created_at) desc
    limit 20
  ) i;

  return jsonb_build_object(
    'ok', true,
    'source', 'be_warehouse_wayplan_center',
    'count', v_count,
    'summary', v_summary,
    'rows', v_rows,
    'exceptions', v_exceptions,
    'recent_imports', v_imports
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_way_initiate_return(p_pickup_id text, p_reason text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE v_role TEXT := public.be_current_user_role();
BEGIN
  IF v_role NOT IN ('admin','operation_manager','supervisor','cs') THEN RAISE EXCEPTION 'Access denied'; END IF;
  UPDATE public.be_portal_pickup_requests SET status='RETURN_INITIATED', updated_at=NOW() WHERE pickup_id=p_pickup_id;
  INSERT INTO public.be_portal_cargo_events(pickup_id,event_type,description,actor_role,created_at)
  VALUES(p_pickup_id,'RETURN_INITIATED','Return to origin initiated. Reason: '||p_reason, v_role, NOW());
  RETURN json_build_object('success',true,'pickup_id',p_pickup_id);
END; $function$
;

CREATE OR REPLACE FUNCTION public.be_way_management_detail(p_pickup_id text)
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
DECLARE v_role TEXT := public.be_current_user_role();
BEGIN
  IF v_role NOT IN ('admin','operation_manager','supervisor','cs','dispatch') THEN RAISE EXCEPTION 'Access denied'; END IF;
  RETURN (SELECT json_build_object(
    'shipment', row_to_json(p),
    'events', (SELECT COALESCE(json_agg(row_to_json(e) ORDER BY e.created_at),'[]'::json) FROM public.be_portal_cargo_events e WHERE e.pickup_id = p_pickup_id)
  ) FROM public.be_portal_pickup_requests p WHERE p.pickup_id = p_pickup_id LIMIT 1);
END; $function$
;

