CREATE OR REPLACE FUNCTION public.be_way_update_status(p_pickup_id text, p_status text, p_reason text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE v_role TEXT := public.be_current_user_role(); v_old TEXT;
BEGIN
  IF v_role NOT IN ('admin','operation_manager','supervisor','cs') THEN RAISE EXCEPTION 'Access denied'; END IF;
  SELECT status INTO v_old FROM public.be_portal_pickup_requests WHERE pickup_id = p_pickup_id;
  UPDATE public.be_portal_pickup_requests SET status=p_status, updated_at=NOW() WHERE pickup_id=p_pickup_id;
  INSERT INTO public.be_portal_cargo_events(pickup_id,event_type,description,actor_role,created_at)
  VALUES(p_pickup_id,'STATUS_UPDATE','Status changed from '||v_old||' to '||p_status||'. Reason: '||p_reason, v_role, NOW());
  RETURN json_build_object('success',true,'pickup_id',p_pickup_id,'old_status',v_old,'new_status',p_status);
END; $function$
;

CREATE OR REPLACE FUNCTION public.be_waybill_close_check(p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_waybill text := coalesce(p_payload->>'waybill_no', '');
  v_row record;
begin
  select *
  into v_row
  from public.be_data_entry_parcel_details
  where way_id = v_waybill or delivery_way_id = v_waybill
  limit 1;

  if not found then
    return jsonb_build_object('ok', false, 'error', 'Waybill not found');
  end if;

  return jsonb_build_object(
    'ok', true,
    'waybill_no', v_waybill,
    'conditions', jsonb_build_array(
      jsonb_build_object('no', 1, 'label', 'Shipment delivered, returned, or cancelled', 'passed', coalesce(v_row.warehouse_status,'') in ('DELIVERED','RETURNED_TO_SENDER','PICKUP_CANCELLED','LOST')),
      jsonb_build_object('no', 2, 'label', 'POD or failure proof captured and validated', 'passed', coalesce(v_row.remark,'') ilike '%photo%' or coalesce(v_row.remark,'') ilike '%pod%'),
      jsonb_build_object('no', 3, 'label', 'COD status = Settled or Not Applicable', 'passed', coalesce(v_row.finance_status,'') in ('COD_SETTLED','READY_FOR_INVOICE','PAID')),
      jsonb_build_object('no', 4, 'label', 'Rider handover verified', 'passed', coalesce(v_row.supervisor_status,'') not in ('FAILED','PENDING')),
      jsonb_build_object('no', 5, 'label', 'Merchant settlement generated or Not Required', 'passed', coalesce(v_row.finance_status,'') in ('READY_FOR_INVOICE','PAID','NOT_REQUIRED')),
      jsonb_build_object('no', 6, 'label', 'Invoice status = Issued, Paid, or On Hold', 'passed', coalesce(v_row.finance_status,'') in ('READY_FOR_INVOICE','PAID','ON_HOLD')),
      jsonb_build_object('no', 7, 'label', 'No unresolved warehouse exceptions', 'passed', coalesce(v_row.warehouse_status,'') not in ('WAREHOUSE_HOLD','DAMAGED','LOST')),
      jsonb_build_object('no', 8, 'label', 'Finance locked the waybill record', 'passed', v_row.closed_at is not null)
    )
  );
end;
$function$
;

