CREATE OR REPLACE FUNCTION public.be_wayplan_assign_route(p_pickup_id text, p_rider_code text DEFAULT NULL::text, p_driver_code text DEFAULT NULL::text, p_helper_code text DEFAULT NULL::text, p_vehicle_plate text DEFAULT NULL::text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_pickup_id text := upper(trim(p_pickup_id));
  v_route_no text := public.be_wayplan_no_from_pickup_id(v_pickup_id);
  v_assignment jsonb;
begin
  if to_regprocedure('public.be_assign_pickup_field_team(text,text,text,text,text,text)') is not null then
    select public.be_assign_pickup_field_team(
      v_pickup_id,
      p_rider_code,
      p_driver_code,
      p_helper_code,
      p_vehicle_plate,
      p_note
    ) into v_assignment;
  else
    update public.be_portal_pickup_requests
    set
      assigned_rider_code = coalesce(p_rider_code, assigned_rider_code),
      assigned_driver_code = coalesce(p_driver_code, assigned_driver_code),
      assigned_helper_code = coalesce(p_helper_code, assigned_helper_code),
      assigned_vehicle_plate = coalesce(p_vehicle_plate, assigned_vehicle_plate),
      assignment_status = 'assigned',
      assigned_at = now(),
      updated_at = now()
    where pickup_id = v_pickup_id;

    v_assignment := jsonb_build_object('ok', true, 'pickup_id', v_pickup_id);
  end if;

  perform public.be_generate_wayplan_for_pickup(v_pickup_id, 'assign_route');

  update public.be_wayplan_routes r
  set
    route_status = 'assigned',
    assigned_rider_code = p.assigned_rider_code,
    assigned_rider_name = p.assigned_rider_name,
    assigned_driver_code = p.assigned_driver_code,
    assigned_driver_name = p.assigned_driver_name,
    assigned_helper_code = p.assigned_helper_code,
    assigned_helper_name = p.assigned_helper_name,
    assigned_vehicle_plate = p.assigned_vehicle_plate,
    updated_at = now()
  from public.be_portal_pickup_requests p
  where p.pickup_id = v_pickup_id
    and r.route_no = v_route_no;

  return jsonb_build_object(
    'ok', true,
    'pickup_id', v_pickup_id,
    'route_no', v_route_no,
    'assignment', v_assignment
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_wayplan_command_center(p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_rows jsonb;
begin
  select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc), '[]'::jsonb)
  into v_rows
  from (
    select *
    from public.be_v_wayplan_command_center
    order by created_at desc
    limit greatest(coalesce(p_limit, 100), 1)
  ) x;

  return jsonb_build_object(
    'ok', true,
    'wayplans', v_rows,
    'count', jsonb_array_length(v_rows),
    'source', 'be_wayplan_command_center'
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_wayplan_dashboard_snapshot(p_search text DEFAULT ''::text, p_limit integer DEFAULT 200)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_routes jsonb;
  v_stops jsonb;
  v_kpis jsonb;
  v_search text := lower(trim(coalesce(p_search, '')));
begin
  select jsonb_build_object(
    'pending_pickups', coalesce((
      select count(*)
      from public.be_portal_pickup_requests p
      where coalesce(p.status, '') not in ('archived_test_data', 'cancelled')
        and coalesce(p.assignment_status, 'pending_assignment') <> 'assigned'
    ), 0),
    'hub_processing', coalesce((
      select count(*)
      from public.be_portal_cargo_events e
      where e.event_type = 'data_entry_waybill'
        and coalesce(e.status, '') in ('draft', 'assigned', 'pickup_verified', 'hub_received', 'sorting')
    ), 0),
    'active_dispatch', coalesce((
      select count(*)
      from public.be_wayplan_routes r
      where r.route_status in ('planned', 'assigned', 'out_for_delivery')
    ), 0),
    'success_rate', coalesce((
      select round(
        100.0 * count(*) filter (where stop_status = 'delivered')
        / nullif(count(*) filter (where stop_status in ('delivered', 'failed', 'return')), 0),
        1
      )
      from public.be_wayplan_stops
    ), 0),
    'cod_to_collect', coalesce((
      select sum(cod_amount)
      from public.be_wayplan_stops
      where stop_status not in ('delivered', 'return')
    ), 0)
  )
  into v_kpis;

  select coalesce(
    jsonb_agg(to_jsonb(r) order by r.updated_at desc),
    '[]'::jsonb
  )
  into v_routes
  from (
    select
      r.route_no,
      r.pickup_id,
      r.route_date,
      r.route_zone,
      r.route_status,
      r.assigned_rider_name,
      r.assigned_driver_name,
      r.assigned_helper_name,
      r.assigned_vehicle_plate,
      r.total_stops,
      r.completed_stops,
      r.failed_stops,
      r.total_cod,
      r.updated_at
    from public.be_wayplan_routes r
    where v_search = ''
       or lower(r.route_no) like '%' || v_search || '%'
       or lower(r.pickup_id) like '%' || v_search || '%'
       or lower(coalesce(r.route_zone, '')) like '%' || v_search || '%'
       or lower(coalesce(r.assigned_rider_name, '')) like '%' || v_search || '%'
    order by r.updated_at desc
    limit coalesce(p_limit, 200)
  ) r;

  select coalesce(
    jsonb_agg(to_jsonb(s) order by s.route_no desc, s.stop_sequence),
    '[]'::jsonb
  )
  into v_stops
  from (
    select
      s.id,
      s.route_no,
      s.pickup_id,
      s.deliver_way_id,
      s.stop_sequence,
      s.township,
      s.recipient_name,
      s.recipient_phone,
      s.delivery_address,
      s.cod_amount,
      s.weight_kg,
      s.stop_status,
      s.scan_status,
      s.updated_at
    from public.be_wayplan_stops s
    where v_search = ''
       or lower(s.route_no) like '%' || v_search || '%'
       or lower(s.pickup_id) like '%' || v_search || '%'
       or lower(s.deliver_way_id) like '%' || v_search || '%'
       or lower(coalesce(s.recipient_name, '')) like '%' || v_search || '%'
       or lower(coalesce(s.recipient_phone, '')) like '%' || v_search || '%'
       or lower(coalesce(s.township, '')) like '%' || v_search || '%'
    order by s.updated_at desc
    limit coalesce(p_limit, 200)
  ) s;

  return jsonb_build_object(
    'ok', true,
    'kpis', v_kpis,
    'routes', v_routes,
    'stops', v_stops,
    'server_time', now()
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_wayplan_determine_route(p_township text, p_address text DEFAULT ''::text, p_is_highway boolean DEFAULT NULL::boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  t text := public.be_wayplan_norm(p_township);
  a text := public.be_wayplan_norm(p_address);
  r public.be_wayplan_zone_resources%rowtype;
  code text;
  hw boolean := coalesce(p_is_highway, false);
begin
  if not hw then
    hw := t like '%ဒဂုံဧရာ%' or a like '%ဒဂုံဧရာ%' or t like '%လှိုင်သာယာအဝေးပြေး%' or a like '%လှိုင်သာယာအဝေးပြေး%'
       or t like '%အောင်မင်္ဂလာ%' or a like '%အောင်မင်္ဂလာ%' or t like '%aungmingalar%' or a like '%aungmingalar%'
       or t like '%dagonayar%' or a like '%dagonayar%' or t like '%highway%' or a like '%highway%';
  end if;

  if hw then
    code := case when t like '%ဒဂုံဧရာ%' or a like '%ဒဂုံဧရာ%' or t like '%လှိုင်သာယာအဝေးပြေး%' or a like '%လှိုင်သာယာအဝေးပြေး%' or t like '%dagonayar%' or a like '%dagonayar%' then 'VAN5' else 'VAN4' end;
  else
    select route_code into code from public.be_wayplan_zone_rules where alias_normalized=t and is_active=true order by priority limit 1;
    code := coalesce(code, 'OUT_OF_SERVICE');
  end if;

  select * into r from public.be_wayplan_zone_resources where route_code=code;
  return jsonb_build_object('route_code', r.route_code, 'route_label', r.route_label, 'resource_type', r.resource_type, 'zone_name', r.zone_name, 'is_highway', hw);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_wayplan_dispatch(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
begin
  update public.be_wayplan_routes set status='dispatched', payload=payload||p_payload, updated_at=now()
  where wayplan_id=p_payload->>'wayplan_id';
  return jsonb_build_object('ok',true,'wayplan_id',p_payload->>'wayplan_id','status','dispatched');
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_wayplan_export_rows(p_pickup_or_route text DEFAULT NULL::text, p_limit integer DEFAULT 1000)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
AS $function$
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'route_no', s.route_no,
        'pickup_id', s.pickup_id,
        'deliver_way_id', s.deliver_way_id,
        'stop_sequence', s.stop_sequence,
        'township', s.township,
        'recipient_name', s.recipient_name,
        'recipient_phone', s.recipient_phone,
        'delivery_address', s.delivery_address,
        'cod_amount', s.cod_amount,
        'weight_kg', s.weight_kg,
        'stop_status', s.stop_status,
        'assigned_rider_name', r.assigned_rider_name,
        'assigned_driver_name', r.assigned_driver_name,
        'vehicle_plate', r.assigned_vehicle_plate,
        'updated_at', s.updated_at
      )
      order by s.route_no, s.stop_sequence
    ),
    '[]'::jsonb
  )
  from public.be_wayplan_stops s
  join public.be_wayplan_routes r on r.route_no = s.route_no
  where coalesce(p_pickup_or_route, '') = ''
     or s.pickup_id = upper(trim(p_pickup_or_route))
     or s.route_no = upper(trim(p_pickup_or_route))
  limit coalesce(p_limit, 1000);
$function$
;

CREATE OR REPLACE FUNCTION public.be_wayplan_generate(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare v_route public.be_wayplan_routes;
begin
  insert into public.be_wayplan_routes(wayplan_id,branch_code,zone_code,rider_id,driver_id,helper_id,fleet_id,stops,payload)
  values('WP-'||coalesce(p_payload->>'branch_code','YGN')||'-'||to_char(now(),'YYYYMMDD')||'-'||upper(substr(encode(gen_random_bytes(3),'hex'),1,6)),
         coalesce(p_payload->>'branch_code','YGN'),p_payload->>'zone_code',p_payload->>'rider_id',p_payload->>'driver_id',p_payload->>'helper_id',p_payload->>'fleet_id',coalesce(p_payload->'stops','[]'::jsonb),p_payload)
  returning * into v_route;
  return jsonb_build_object('ok',true,'route',row_to_json(v_route)::jsonb);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_wayplan_is_dropoff_route(p_route_label text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select coalesce(p_route_label,'') not ilike '%pickup%'
     and coalesce(p_route_label,'') not ilike '%Aung Mingalar Highway%'
     and coalesce(p_route_label,'') not ilike '%Hlaing Thar Yar Highway%';
$function$
;

CREATE OR REPLACE FUNCTION public.be_wayplan_list(p_pickup_or_route text DEFAULT NULL::text, p_limit integer DEFAULT 200)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
AS $function$
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'route_no', r.route_no,
        'pickup_id', r.pickup_id,
        'route_date', r.route_date,
        'route_zone', r.route_zone,
        'route_status', r.route_status,
        'assigned_rider_code', r.assigned_rider_code,
        'assigned_rider_name', r.assigned_rider_name,
        'assigned_driver_code', r.assigned_driver_code,
        'assigned_driver_name', r.assigned_driver_name,
        'assigned_helper_code', r.assigned_helper_code,
        'assigned_helper_name', r.assigned_helper_name,
        'assigned_vehicle_plate', r.assigned_vehicle_plate,
        'total_stops', r.total_stops,
        'completed_stops', r.completed_stops,
        'failed_stops', r.failed_stops,
        'total_cod', r.total_cod,
        'updated_at', r.updated_at,
        'stops', coalesce((
          select jsonb_agg(
            jsonb_build_object(
              'id', s.id,
              'route_no', s.route_no,
              'pickup_id', s.pickup_id,
              'deliver_way_id', s.deliver_way_id,
              'stop_sequence', s.stop_sequence,
              'township', s.township,
              'recipient_name', s.recipient_name,
              'recipient_phone', s.recipient_phone,
              'delivery_address', s.delivery_address,
              'cod_amount', s.cod_amount,
              'weight_kg', s.weight_kg,
              'stop_status', s.stop_status,
              'scan_status', s.scan_status,
              'updated_at', s.updated_at
            )
            order by s.stop_sequence
          )
          from public.be_wayplan_stops s
          where s.route_no = r.route_no
        ), '[]'::jsonb)
      )
      order by r.updated_at desc
    ),
    '[]'::jsonb
  )
  from (
    select *
    from public.be_wayplan_routes r
    where (
      coalesce(p_pickup_or_route, '') = ''
      or r.pickup_id = upper(trim(p_pickup_or_route))
      or r.route_no = upper(trim(p_pickup_or_route))
    )
    order by r.updated_at desc
    limit coalesce(p_limit, 200)
  ) r;
$function$
;

CREATE OR REPLACE FUNCTION public.be_wayplan_no_from_pickup_id(p_pickup_id text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v text := upper(trim(coalesce(p_pickup_id, '')));
begin
  if v ~ '^P[0-9]{4}-[A-Z][A-Z0-9]{1,4}-[0-9]{3}$' then
    return 'W' || substring(v from 2);
  end if;
  return 'W-' || regexp_replace(v, '[^A-Z0-9]+', '-', 'g');
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_wayplan_norm(p_text text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select lower(regexp_replace(coalesce(p_text, ''), '\s+', '', 'g'));
$function$
;

CREATE OR REPLACE FUNCTION public.be_wayplan_normalize_text(p_value text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select lower(regexp_replace(coalesce(p_value, ''), '\s+', '', 'g'));
$function$
;

CREATE OR REPLACE FUNCTION public.be_wayplan_resolve_route(p_township text, p_address text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_town text := public.be_wayplan_normalize_text(p_township);
  v_alias record;
begin
  select zone_code, route_name into v_alias
  from public.be_wayplan_township_aliases
  where normalized_alias = v_town limit 1;

  if v_alias.zone_code is not null then
    return jsonb_build_object('zone_code', v_alias.zone_code, 'route_name', v_alias.route_name, 'is_highway_dropoff', false);
  end if;

  return jsonb_build_object('zone_code', 'OUT_OF_SERVICE', 'route_name', 'OUT_OF_SERVICE', 'is_highway_dropoff', false);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_wayplan_save(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
AS $function$ select public.be_wayplan_generate(p_payload); $function$
;

CREATE OR REPLACE FUNCTION public.be_wayplan_seed_rule(p_alias text, p_route_code text, p_priority integer DEFAULT 100)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
begin
  insert into public.be_wayplan_zone_rules(alias, alias_normalized, route_code, priority, is_active, updated_at)
  values(p_alias, public.be_wayplan_norm(p_alias), p_route_code, p_priority, true, now())
  on conflict(alias_normalized) do update set
    alias=excluded.alias, route_code=excluded.route_code, priority=excluded.priority, is_active=true, updated_at=now();
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_wayplan_snapshot(p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
AS $function$
  select jsonb_build_object('ok',true,'routes',coalesce((select jsonb_agg(row_to_json(x)::jsonb order by updated_at desc) from public.be_wayplan_routes x),'[]'::jsonb));
$function$
;

CREATE OR REPLACE FUNCTION public.be_wayplan_status_normalize(p_status text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case lower(coalesce(p_status, 'planned'))
    when 'planned' then 'planned'
    when 'assigned' then 'assigned'
    when 'out_for_delivery' then 'out_for_delivery'
    when 'in_transit' then 'out_for_delivery'
    when 'delivered' then 'delivered'
    when 'success' then 'delivered'
    when 'failed' then 'failed'
    when 'return' then 'return'
    when 'returned' then 'return'
    when 'hold' then 'hold'
    else lower(coalesce(p_status, 'planned'))
  end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_wayplan_update_status(p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_wayplan_id text := nullif(p_payload->>'wayplan_id', '');
  v_status text := upper(coalesce(nullif(p_payload->>'status', ''), ''));
  v_actor text := coalesce(nullif(p_payload->>'actor', ''), 'wayplan_command_center');
begin
  if v_wayplan_id is null then
    return jsonb_build_object('ok', false, 'error', 'wayplan_id is required');
  end if;

  if v_status not in ('CREATED', 'DISPATCHED', 'COMPLETED', 'ON_HOLD', 'CANCELLED') then
    return jsonb_build_object(
      'ok', false,
      'error', 'Invalid status',
      'allowed_statuses', jsonb_build_array('CREATED', 'DISPATCHED', 'COMPLETED', 'ON_HOLD', 'CANCELLED')
    );
  end if;

  update public.be_wayplan_dispatches
  set
    wayplan_status = v_status,
    dispatched_at = case
      when v_status = 'DISPATCHED' and dispatched_at is null then now()
      else dispatched_at
    end,
    completed_at = case
      when v_status = 'COMPLETED' and completed_at is null then now()
      else completed_at
    end,
    metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
      'last_action_actor', v_actor,
      'last_action_status', v_status,
      'last_action_at', now()
    ),
    updated_at = now()
  where wayplan_id = v_wayplan_id;

  update public.be_wayplan_dispatch_stops
  set
    stop_status = v_status,
    updated_at = now()
  where wayplan_id = v_wayplan_id;

  update public.be_waybill_ledger
  set
    dispatch_status = v_status,
    wayplan_status = v_status,
    updated_at = now()
  where wayplan_id = v_wayplan_id;

  update public.be_portal_pickup_requests
  set
    dispatch_status = v_status,
    wayplan_status = v_status,
    updated_at = now()
  where wayplan_id = v_wayplan_id;

  return jsonb_build_object(
    'ok', true,
    'wayplan_id', v_wayplan_id,
    'status', v_status
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_wayplan_update_stop_status(p_deliver_way_id text, p_status text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_deliver_way_id text := upper(trim(p_deliver_way_id));
  v_status text := public.be_wayplan_status_normalize(p_status);
  v_stop public.be_wayplan_stops;
begin
  update public.be_wayplan_stops
  set
    stop_status = v_status,
    scan_status = v_status,
    scanned_at = case when v_status in ('out_for_delivery', 'delivered', 'failed', 'return') then now() else scanned_at end,
    delivered_at = case when v_status = 'delivered' then now() else delivered_at end,
    failed_at = case when v_status in ('failed', 'return') then now() else failed_at end,
    failure_reason = case when v_status in ('failed', 'return') then p_note else failure_reason end,
    payload = coalesce(payload, '{}'::jsonb) || jsonb_build_object(
      'last_status_note', p_note,
      'last_status_at', now()
    ),
    updated_at = now()
  where deliver_way_id = v_deliver_way_id
  returning * into v_stop;

  if v_stop.id is null then
    raise exception 'Wayplan stop % not found', p_deliver_way_id;
  end if;

  update public.be_portal_cargo_events e
  set
    status = v_status,
    wayplan_status = v_status,
    updated_at = now(),
    payload = coalesce(e.payload, '{}'::jsonb) || jsonb_build_object(
      'wayplan_status', v_status,
      'wayplan_status_note', p_note,
      'wayplan_status_at', now()
    )
  where e.id = v_stop.cargo_event_id
     or coalesce(e.deliver_way_id, e.tracking_no) = v_deliver_way_id;

  update public.be_wayplan_routes r
  set
    completed_stops = (
      select count(*) from public.be_wayplan_stops s
      where s.route_no = r.route_no and s.stop_status = 'delivered'
    ),
    failed_stops = (
      select count(*) from public.be_wayplan_stops s
      where s.route_no = r.route_no and s.stop_status in ('failed', 'return')
    ),
    route_status = case
      when (select count(*) from public.be_wayplan_stops s where s.route_no = r.route_no and s.stop_status not in ('delivered', 'failed', 'return')) = 0
        then 'closed'
      when (select count(*) from public.be_wayplan_stops s where s.route_no = r.route_no and s.stop_status = 'out_for_delivery') > 0
        then 'out_for_delivery'
      else r.route_status
    end,
    updated_at = now()
  where r.route_no = v_stop.route_no;

  return jsonb_build_object(
    'ok', true,
    'deliver_way_id', v_deliver_way_id,
    'status', v_status,
    'route_no', v_stop.route_no
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_wayplan_zone_for_township(p_township text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v text := lower(trim(coalesce(p_township, '')));
begin
  if v = '' then
    return 'UNASSIGNED';
  end if;

  if v similar to '%(north dagon|east dagon|south dagon|dagon|မြောက်ဒဂုံ|အရှေ့ဒဂုံ|တောင်ဒဂုံ)%' then
    return 'YGN-DAGON';
  end if;

  if v similar to '%(shwe pyi thar|hlaing thar yar|လှိုင်သာယာ|ရွှေပြည်သာ)%' then
    return 'YGN-WEST';
  end if;

  if v similar to '%(tamwe|bahan|yankin|thingangyun|တာမွေ|ဗဟန်း|ရန်ကင်း|သင်္ဃန်းကျွန်း)%' then
    return 'YGN-CENTRAL';
  end if;

  if v similar to '%(thaketa|north okkalapa|south okkalapa|သာကေတ|မြောက်ဥက္ကလာ|တောင်ဥက္ကလာ)%' then
    return 'YGN-EAST';
  end if;

  if v similar to '%(kamayut|hlaing|sanchaung|ကြည့်မြင်တိုင်|ကမာရွတ်|လှိုင်|စမ်းချောင်း)%' then
    return 'YGN-INNER-WEST';
  end if;

  return 'YGN-GENERAL';
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_wh_date(p_data jsonb, p_key1 text, p_key2 text DEFAULT NULL::text, p_key3 text DEFAULT NULL::text, p_key4 text DEFAULT NULL::text, p_key5 text DEFAULT NULL::text, p_key6 text DEFAULT NULL::text)
 RETURNS date
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  keys text[] := array[p_key1,p_key2,p_key3,p_key4,p_key5,p_key6];
  k text;
  v text;
begin
  foreach k in array keys loop
    if k is not null then
      v := nullif(trim(coalesce(p_data ->> k, '')), '');

      if v is not null and lower(v) not in ('null','undefined','nan','-') then
        begin
          return v::date;
        exception when others then
          begin
            return v::timestamptz::date;
          exception when others then
            null;
          end;
        end;
      end if;
    end if;
  end loop;

  return current_date;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.be_wh_num(p_data jsonb, p_key1 text, p_key2 text DEFAULT NULL::text, p_key3 text DEFAULT NULL::text, p_key4 text DEFAULT NULL::text, p_key5 text DEFAULT NULL::text, p_key6 text DEFAULT NULL::text, p_key7 text DEFAULT NULL::text, p_key8 text DEFAULT NULL::text)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  keys text[] := array[p_key1,p_key2,p_key3,p_key4,p_key5,p_key6,p_key7,p_key8];
  k text;
  v text;
begin
  foreach k in array keys loop
    if k is not null then
      v := nullif(regexp_replace(coalesce(p_data ->> k, ''), '[^0-9.\-]', '', 'g'), '');
      if v is not null then
        begin
          return v::numeric;
        exception when others then
          null;
        end;
      end if;
    end if;
  end loop;

  return 0;
end;
$function$
;

