CREATE OR REPLACE FUNCTION public.bulk_create_shipments_portal(p_rows jsonb)
 RETURNS TABLE(ok boolean, way_id text, shipment_id uuid, error text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r jsonb;
  sid uuid;
  wid text;
begin
  if jsonb_typeof(p_rows) <> 'array' then
    raise exception 'p_rows must be jsonb array';
  end if;

  for r in select * from jsonb_array_elements(p_rows)
  loop
    begin
      select shipment_id, way_id
      into sid, wid
      from public.create_shipment_portal(
        r->>'sender_name',
        r->>'sender_phone',
        r->>'sender_address',
        r->>'sender_city',
        r->>'sender_state',
        r->>'receiver_name',
        r->>'receiver_phone',
        r->>'receiver_address',
        r->>'receiver_city',
        coalesce(r->>'receiver_state','MM'),
        (r->>'item_price')::numeric,
        (r->>'delivery_fee')::numeric,
        coalesce((r->>'cod_amount')::numeric, 0),
        nullif(r->>'package_weight','')::numeric,
        coalesce(nullif(r->>'cbm','')::numeric, 1),
        coalesce(r->>'delivery_type','Normal'),
        r->>'remarks',
        nullif(r->>'pickup_branch_id','')::uuid,
        nullif(r->>'delivery_branch_id','')::uuid
      );

      ok := true; way_id := wid; shipment_id := sid; error := null;
      return next;
    exception when others then
      ok := false; way_id := null; shipment_id := null; error := sqlerrm;
      return next;
    end;
  end loop;

end;
$function$
;

CREATE OR REPLACE FUNCTION public.calculate_distance_km_2026_02_18_17_00(lat1 numeric, lon1 numeric, lat2 numeric, lon2 numeric)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
    R DECIMAL := 6371; -- Earth's radius in kilometers
    dLat DECIMAL;
    dLon DECIMAL;
    a DECIMAL;
    c DECIMAL;
BEGIN
    dLat := RADIANS(lat2 - lat1);
    dLon := RADIANS(lon2 - lon1);

    a := SIN(dLat/2) * SIN(dLat/2) +
         COS(RADIANS(lat1)) * COS(RADIANS(lat2)) *
         SIN(dLon/2) * SIN(dLon/2);
    c := 2 * ATAN2(SQRT(a), SQRT(1-a));

    RETURN R * c;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.calculate_domestic_rate(p_from_state character varying, p_to_state character varying, p_weight numeric, p_service_type character varying DEFAULT 'STANDARD'::character varying)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    from_zone VARCHAR(50);
    to_zone VARCHAR(50);
    base_rate DECIMAL(10,2);
    per_kg_rate DECIMAL(10,2);
    remote_surcharge DECIMAL(10,2);
    fuel_surcharge_percent DECIMAL(5,2);
    total_cost DECIMAL(10,2);
    result JSONB;
BEGIN
    -- Get zones for states
    SELECT zone INTO from_zone
    FROM public.myanmar_locations_2026_02_19_13_00
    WHERE state_division = p_from_state
    LIMIT 1;

    SELECT zone INTO to_zone
    FROM public.myanmar_locations_2026_02_19_13_00
    WHERE state_division = p_to_state
    LIMIT 1;

    -- Get rate information
    SELECT dr.base_rate, dr.per_kg_rate, dr.remote_area_surcharge, dr.fuel_surcharge_percent
    INTO base_rate, per_kg_rate, remote_surcharge, fuel_surcharge_percent
    FROM public.domestic_rates_2026_02_19_13_00 dr
    WHERE dr.from_zone = from_zone
    AND dr.to_zone = to_zone
    AND dr.service_type = p_service_type
    AND p_weight >= dr.weight_from
    AND p_weight <= dr.weight_to
    AND dr.effective_from <= CURRENT_DATE
    AND (dr.effective_to IS NULL OR dr.effective_to >= CURRENT_DATE)
    ORDER BY dr.weight_from DESC
    LIMIT 1;

    -- Calculate total cost
    IF base_rate IS NOT NULL THEN
        total_cost := base_rate + (p_weight * per_kg_rate) + remote_surcharge;
        total_cost := total_cost + (total_cost * fuel_surcharge_percent / 100);

        result := jsonb_build_object(
            'success', true,
            'base_rate', base_rate,
            'per_kg_rate', per_kg_rate,
            'weight', p_weight,
            'remote_surcharge', remote_surcharge,
            'fuel_surcharge_percent', fuel_surcharge_percent,
            'total_cost', ROUND(total_cost, 2),
            'currency', 'MMK',
            'service_type', p_service_type
        );
    ELSE
        result := jsonb_build_object(
            'success', false,
            'error', 'No rate found for the specified route and weight'
        );
    END IF;

    RETURN result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.calculate_domestic_rate_2026_02_18_18_00(p_weight_kg numeric, p_township_id uuid, p_service_type character varying, p_cod_amount numeric DEFAULT 0, p_declared_value numeric DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
    v_township RECORD;
    v_state RECORD;
    v_rate RECORD;
    v_base_rate DECIMAL;
    v_zone_multiplier DECIMAL;
    v_cod_fee DECIMAL := 0;
    v_insurance_fee DECIMAL := 0;
    v_fuel_surcharge DECIMAL;
    v_total DECIMAL;
    v_delivery_days INTEGER;
BEGIN
    -- Get township information
    SELECT * INTO v_township
    FROM public.townships_2026_02_18_18_00
    WHERE id = p_township_id AND is_active = true;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('error', 'Township not found');
    END IF;

    -- Get state information
    SELECT * INTO v_state
    FROM public.myanmar_states_divisions_2026_02_18_18_00
    WHERE id = v_township.state_division_id;

    -- Get applicable rate
    SELECT * INTO v_rate
    FROM public.domestic_shipping_rates_2026_02_18_18_00
    WHERE service_type = p_service_type
    AND p_weight_kg >= weight_from_kg
    AND p_weight_kg <= weight_to_kg
    AND is_active = true
    ORDER BY weight_from_kg DESC
    LIMIT 1;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('error', 'No rate found for this weight');
    END IF;

    -- Calculate base rate
    v_base_rate := v_rate.base_rate_mmk;

    -- Apply zone multiplier
    v_zone_multiplier := CASE v_state.zone_classification
        WHEN 'METRO' THEN v_rate.metro_multiplier
        WHEN 'STANDARD' THEN v_rate.standard_multiplier
        WHEN 'REMOTE' THEN v_rate.remote_multiplier
        ELSE 1.00
    END;

    v_base_rate := v_base_rate * v_zone_multiplier * v_township.rate_multiplier;

    -- Calculate COD fee
    IF p_cod_amount > 0 THEN
        v_cod_fee := GREATEST(v_rate.cod_fee_mmk, p_cod_amount * v_rate.cod_percentage / 100);
    END IF;

    -- Calculate insurance fee
    IF p_declared_value > 0 THEN
        v_insurance_fee := p_declared_value * v_rate.insurance_percentage / 100;
    END IF;

    -- Calculate fuel surcharge
    v_fuel_surcharge := v_base_rate * v_rate.fuel_surcharge_percentage / 100;

    -- Calculate total
    v_total := v_base_rate + v_cod_fee + v_insurance_fee + v_fuel_surcharge;

    -- Calculate delivery time
    v_delivery_days := v_rate.delivery_time_days + COALESCE(v_township.delivery_time_days, 0);

    RETURN jsonb_build_object(
        'base_rate', v_base_rate,
        'zone_multiplier', v_zone_multiplier,
        'cod_fee', v_cod_fee,
        'insurance_fee', v_insurance_fee,
        'fuel_surcharge', v_fuel_surcharge,
        'total_amount', v_total,
        'currency', 'MMK',
        'delivery_days', v_delivery_days,
        'service_type', p_service_type,
        'destination', jsonb_build_object(
            'township', v_township.name_en,
            'township_mm', v_township.name_mm,
            'zone', v_state.zone_classification
        )
    );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.calculate_highway_bus_station_dropoff_charge(p_actual_weight_kg numeric DEFAULT 3)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actual_weight NUMERIC := COALESCE(p_actual_weight_kg, 0);
  v_base_fee NUMERIC := 3000;
  v_allowance_kg NUMERIC := 3;
  v_extra_fee_per_kg NUMERIC := 500;
  v_extra_kg NUMERIC := 0;
BEGIN
  v_extra_kg := GREATEST(CEIL(v_actual_weight - v_allowance_kg), 0);
  RETURN v_base_fee + (v_extra_kg * v_extra_fee_per_kg);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.calculate_merchant_payout(way_id_input text)
 RETURNS TABLE(net_payout numeric, service_fees numeric)
 LANGUAGE plpgsql
AS $function$
BEGIN
  RETURN QUERY
  SELECT
    (cod_amount - (delivery_fee + extra_weight_charges)) as net_payout,
    (delivery_fee + extra_weight_charges) as service_fees
  FROM way_records
  WHERE way_id = way_id_input AND status = 'SUCCESSFUL';
END;
$function$
;

CREATE OR REPLACE FUNCTION public.calculate_pickup_tariff(p_tier text, p_actual_weight numeric, p_is_highway_dropoff boolean)
 RETURNS json
 LANGUAGE plpgsql
 IMMUTABLE SECURITY DEFINER
AS $function$
DECLARE
    v_allowance DECIMAL;
    v_base_fee DECIMAL;
    v_chargeable_weight INT;
    v_extra_weight INT;
    v_surcharge DECIMAL;
    v_highway_fee DECIMAL := 0;
    v_total_tariff DECIMAL;
BEGIN
    -- (၁) Base Fee နှင့် Weight Allowance သတ်မှတ်ခြင်း
    IF p_tier = 'Royal' THEN
        v_allowance := 5.0;
        v_base_fee := 3500; -- Royal Base Fee ဥပမာ
    ELSE
        v_allowance := 3.0;
        v_base_fee := 2500; -- Standard Base Fee ဥပမာ
    END IF;

    -- (၂) အလေးချိန် တွက်ချက်ခြင်း (ceil(weight) rule အတိုင်း)
    v_chargeable_weight := CEIL(p_actual_weight);
    v_extra_weight := GREATEST(0, v_chargeable_weight - v_allowance);

    -- (၃) ပိုမိုသော အလေးချိန်အတွက် Surcharge (500 MMK per extra kg)
    v_surcharge := v_extra_weight * 500;

    -- (၄) Highway Station Drop-off စရိတ်
    IF p_is_highway_dropoff THEN
        v_highway_fee := 3000;
    END IF;

    -- (၅) စုစုပေါင်း ကျသင့်ငွေ
    v_total_tariff := v_base_fee + v_surcharge + v_highway_fee;

    RETURN json_build_object(
        'tier', p_tier,
        'actual_weight', p_actual_weight,
        'base_fee', v_base_fee,
        'chargeable_weight', v_chargeable_weight,
        'extra_weight', v_extra_weight,
        'surcharge', v_surcharge,
        'highway_fee', v_highway_fee,
        'total_tariff', v_total_tariff
    );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.calculate_recovered_delivery_charge(p_route_pricing_group text DEFAULT 'YGN_TO_YGN'::text, p_actual_weight_kg numeric DEFAULT 3, p_merchant_code text DEFAULT NULL::text, p_is_bus_station_dropoff boolean DEFAULT false)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_route TEXT := UPPER(COALESCE(p_route_pricing_group, 'YGN_TO_YGN'));
  v_actual_weight NUMERIC := COALESCE(p_actual_weight_kg, 0);
  v_is_bus_drop BOOLEAN := COALESCE(p_is_bus_station_dropoff, FALSE);
  v_base_fee NUMERIC := 4000;
  v_allowance_kg NUMERIC := 3;
  v_extra_fee_per_kg NUMERIC := 500;
  v_extra_kg NUMERIC := 0;
  v_is_special_merchant BOOLEAN := FALSE;
BEGIN
  IF v_is_bus_drop
     OR v_route IN (
       'BUS_STATION_DROP',
       'HIGHWAY_BUS_STATION',
       'HIGHWAY_BUS_STATION_DROPOFF',
       'CARGO_DROPOFF',
       'HIGHWAY_CARGO_DROPOFF'
     )
     OR v_route LIKE '%BUS%STATION%'
     OR v_route LIKE '%HIGHWAY%'
  THEN
    RETURN public.calculate_highway_bus_station_dropoff_charge(v_actual_weight);
  END IF;

  IF p_merchant_code IS NOT NULL
     AND to_regclass('public.britium_merchant_master') IS NOT NULL
  THEN
    SELECT COALESCE(MAX(is_special_5kg_allowance::INT), 0) = 1
    INTO v_is_special_merchant
    FROM public.britium_merchant_master
    WHERE UPPER(merchant_code) = UPPER(p_merchant_code)
      AND COALESCE(is_active, TRUE) = TRUE;
  END IF;

  v_allowance_kg := CASE WHEN v_is_special_merchant THEN 5 ELSE 3 END;

  IF v_route IN ('YGN_TO_MDY', 'YANGON_TO_MANDALAY')
     OR v_route LIKE '%MDY%'
     OR v_route LIKE '%MANDALAY%'
  THEN
    v_base_fee := 6000;
  ELSIF v_route IN ('YGN_TO_NPT', 'YANGON_TO_NAYPYITAW', 'YANGON_TO_NAY_PYI_TAW')
        OR v_route LIKE '%NPT%'
        OR v_route LIKE '%NAY%PYI%TAW%'
  THEN
    v_base_fee := 6000;
  ELSIF v_route IN ('YGN_TO_YGN', 'YANGON_TO_YANGON')
        OR v_route LIKE '%YGN%'
        OR v_route LIKE '%YANGON%'
  THEN
    v_base_fee := 4000;
  ELSE
    v_base_fee := 4000;
  END IF;

  v_extra_kg := GREATEST(CEIL(v_actual_weight - v_allowance_kg), 0);
  RETURN v_base_fee + (v_extra_kg * v_extra_fee_per_kg);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.can_access_branch(p_branch uuid)
 RETURNS boolean
 LANGUAGE sql
 SECURITY DEFINER
AS $function$
  select exists (
    select 1
    from public.user_branch_assignments uba
    where uba.user_id = auth.uid()
      and uba.branch_id = p_branch
  );
$function$
;

CREATE OR REPLACE FUNCTION public.can_access_hierarchy(target_branch uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  user_scope int;
  user_branch uuid;
  user_region uuid;
  target_region uuid;
begin

  -- Company-wide access
  if public.has_role('SUPER_ADMIN') or public.has_role('APP_OWNER') then
    return true;
  end if;

  -- Get user scope level
  select r.scope_level into user_scope
  from public.roles r
  join public.profiles p on lower(r.code::text) = lower(p.role::text)
  where p.id = auth.uid();

  if user_scope is null then
    return false;
  end if;

  -- S3 branch scope
  if user_scope = 3 then
    return exists (
      select 1
      from public.user_branch_assignments uba
      where uba.user_id = auth.uid()
        and uba.branch_id = target_branch
    );
  end if;

  -- S4 regional scope
  if user_scope = 4 then
    select region_id into user_region
    from public.branches b
    join public.user_branch_assignments uba
      on uba.branch_id = b.id
    where uba.user_id = auth.uid()
    limit 1;

    select region_id into target_region
    from public.branches
    where id = target_branch;

    return user_region = target_region;
  end if;

  return false;

end;
$function$
;

CREATE OR REPLACE FUNCTION public.can_access_record(p_created_by uuid, p_branch_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_role text;
begin

  select role into v_role
  from public.profiles
  where id = auth.uid();

  if v_role in ('APP_OWNER','SUPER_ADMIN') then
    return true;
  end if;

  if p_created_by = auth.uid() then
    return true;
  end if;

  if can_access_branch(p_branch_id) then
    return true;
  end if;

  return false;
end;
$function$
;

