CREATE OR REPLACE FUNCTION public.change_user_password_2026_02_17_18_40(user_id uuid, new_password text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
    UPDATE public.auth_users_2026_02_17_18_40
    SET password_hash = new_password,
        must_change_password = false,
        updated_at = now()
    WHERE id = user_id AND is_active = true;

    IF FOUND THEN
        RETURN json_build_object('success', true, 'message', 'Password changed successfully');
    ELSE
        RETURN json_build_object('success', false, 'error', 'User not found');
    END IF;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.check_geofence_2026_02_18_18_00(p_lat numeric, p_lng numeric, p_geofence_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
    v_geofence RECORD;
    v_distance DECIMAL;
BEGIN
    SELECT center_lat, center_lng, radius_meters, is_active
    INTO v_geofence
    FROM public.geofences_2026_02_18_18_00
    WHERE id = p_geofence_id;

    IF NOT FOUND OR NOT v_geofence.is_active THEN
        RETURN false;
    END IF;

    -- Calculate distance using Haversine formula
    v_distance := public.calculate_distance_km_2026_02_18_17_00(
        p_lat, p_lng, v_geofence.center_lat, v_geofence.center_lng
    ) * 1000; -- convert to meters

    RETURN v_distance <= v_geofence.radius_meters;
END;
$function$
;

