CREATE OR REPLACE FUNCTION public.execute_delivery_resolution(p_awb character varying, p_rider_id uuid, p_resolution character varying, p_lat numeric, p_lng numeric, p_evidence_url text, p_receiver_name character varying, p_ndr_reason character varying)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_shipment_status VARCHAR;
BEGIN
  -- Verify Shipment exists
  SELECT status INTO v_shipment_status FROM shipments WHERE awb = p_awb;
  IF v_shipment_status IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid AWB. Parcel not found.');
  END IF;

  IF p_resolution = 'DELIVERED' THEN
    -- ⚡ ATOMIC PoD TRANSACTION
    UPDATE shipments
    SET status = 'DELIVERED'
    WHERE awb = p_awb;

    INSERT INTO chain_of_custody_logs (awb, actor_id, action_type, lat, lng, evidence_url, created_at)
    VALUES (p_awb, p_rider_id, 'DELIVERED_TO_CUSTOMER', p_lat, p_lng, p_evidence_url, NOW());

    RETURN jsonb_build_object('success', true, 'message', 'PoD successfully recorded.');

  ELSIF p_resolution = 'FAILED' THEN
    -- ⚡ ATOMIC NDR TRANSACTION
    UPDATE shipments
    SET status = 'DELIVERY_FAILED'
    WHERE awb = p_awb;

    INSERT INTO chain_of_custody_logs (awb, actor_id, action_type, lat, lng, evidence_url, created_at)
    -- Store the NDR reason in the evidence_url/notes field for now, or a dedicated column
    VALUES (p_awb, p_rider_id, 'DELIVERY_FAILED: ' || p_ndr_reason, p_lat, p_lng, NULL, NOW());

    RETURN jsonb_build_object('success', true, 'message', 'NDR successfully recorded.');
  ELSE
    RETURN jsonb_build_object('success', false, 'error', 'Invalid resolution type.');
  END IF;

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.execute_golive_runtime_cleanup(p_admin_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_count INT;
BEGIN
    -- (A) Archive & Clean: Exception Audits
    WITH moved AS (DELETE FROM be_exception_audit RETURNING *)
    INSERT INTO be_go_live_archived_operational_test_data (original_table_name, record_data, archived_by)
    SELECT 'be_exception_audit', row_to_json(moved)::jsonb, p_admin_id FROM moved;

    GET DIAGNOSTICS v_count = ROW_COUNT;
    INSERT INTO be_go_live_runtime_reset_log (action_name, records_affected, executed_by)
    VALUES ('CLEANUP_EXCEPTION_AUDIT', v_count, p_admin_id);

    -- (B) Archive & Clean: Cargo Events (Tracking)
    WITH moved AS (DELETE FROM be_portal_cargo_events RETURNING *)
    INSERT INTO be_go_live_archived_operational_test_data (original_table_name, record_data, archived_by)
    SELECT 'be_portal_cargo_events', row_to_json(moved)::jsonb, p_admin_id FROM moved;

    GET DIAGNOSTICS v_count = ROW_COUNT;
    INSERT INTO be_go_live_runtime_reset_log (action_name, records_affected, executed_by)
    VALUES ('CLEANUP_CARGO_EVENTS', v_count, p_admin_id);

    -- (C) Archive & Clean: Dispatch Routes & Assignments
    WITH moved AS (DELETE FROM be_dispatch_routes RETURNING *)
    INSERT INTO be_go_live_archived_operational_test_data (original_table_name, record_data, archived_by)
    SELECT 'be_dispatch_routes', row_to_json(moved)::jsonb, p_admin_id FROM moved;

    GET DIAGNOSTICS v_count = ROW_COUNT;
    INSERT INTO be_go_live_runtime_reset_log (action_name, records_affected, executed_by)
    VALUES ('CLEANUP_DISPATCH_ROUTES', v_count, p_admin_id);

    -- (D) Archive & Clean: Pickup Requests
    WITH moved AS (DELETE FROM be_portal_pickup_requests RETURNING *)
    INSERT INTO be_go_live_archived_operational_test_data (original_table_name, record_data, archived_by)
    SELECT 'be_portal_pickup_requests', row_to_json(moved)::jsonb, p_admin_id FROM moved;

    GET DIAGNOSTICS v_count = ROW_COUNT;
    INSERT INTO be_go_live_runtime_reset_log (action_name, records_affected, executed_by)
    VALUES ('CLEANUP_PICKUP_REQUESTS', v_count, p_admin_id);

    -- (E) Archive & Clean: System Notifications
    WITH moved AS (DELETE FROM be_app_notifications RETURNING *)
    INSERT INTO be_go_live_archived_operational_test_data (original_table_name, record_data, archived_by)
    SELECT 'be_app_notifications', row_to_json(moved)::jsonb, p_admin_id FROM moved;

    GET DIAGNOSTICS v_count = ROW_COUNT;
    INSERT INTO be_go_live_runtime_reset_log (action_name, records_affected, executed_by)
    VALUES ('CLEANUP_NOTIFICATIONS', v_count, p_admin_id);

    RETURN 'SYSTEM_READY_FOR_GOLIVE';
END;
$function$
;

CREATE OR REPLACE FUNCTION public.execute_secure_pickup(p_awb character varying, p_tag_id character varying, p_rider_id uuid, p_lat numeric, p_lng numeric, p_photo_url character varying)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_shipment_status VARCHAR;
  v_tag_status VARCHAR;
BEGIN
  -- 1. Verify the Shipment exists and is ready for pickup
  SELECT status INTO v_shipment_status FROM shipments WHERE awb = p_awb;
  IF v_shipment_status IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid AWB.');
  END IF;
  IF v_shipment_status != 'PENDING_PICKUP' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Shipment is not pending pickup.');
  END IF;

  -- 2. Verify the Tamper Tag is valid and available
  SELECT status INTO v_tag_status FROM tamper_tags WHERE tag_id = p_tag_id;
  IF v_tag_status IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid Tamper Tag.');
  END IF;
  IF v_tag_status != 'AVAILABLE' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Tag is already used or voided.');
  END IF;

  -- 3. ACTIVATE TRANSACTION: Update Tamper Tag
  UPDATE tamper_tags
  SET status = 'USED', used_at = NOW()
  WHERE tag_id = p_tag_id;

  -- 4. ACTIVATE TRANSACTION: Update Shipment
  UPDATE shipments
  SET status = 'IN_TRANSIT_TO_HUB', tamper_tag_id = p_tag_id
  WHERE awb = p_awb;

  -- 5. ACTIVATE TRANSACTION: Insert GPS Audit Log
  INSERT INTO chain_of_custody_logs (awb, actor_id, action_type, lat, lng, evidence_url, created_at)
  VALUES (p_awb, p_rider_id, 'SECURED_AT_MERCHANT', p_lat, p_lng, p_photo_url, NOW());

  -- 6. Return Success
  RETURN jsonb_build_object('success', true, 'message', 'Chain of custody secured.');

EXCEPTION WHEN OTHERS THEN
  -- If ANYTHING fails above, Postgres automatically rolls back all changes
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.execute_secure_pickup(p_awb character varying, p_tag_id character varying, p_rider_id uuid, p_lat numeric, p_lng numeric, p_photo_url text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_shipment_status VARCHAR;
  v_tag_status VARCHAR;
BEGIN
  -- Verify Shipment
  SELECT status INTO v_shipment_status FROM shipments WHERE awb = p_awb;
  IF v_shipment_status IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid AWB. Parcel not found.');
  END IF;

  -- Verify Tag
  SELECT status INTO v_tag_status FROM tamper_tags WHERE tag_id = p_tag_id;
  IF v_tag_status IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid Tamper Tag ID.');
  END IF;
  IF v_tag_status != 'AVAILABLE' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Security tag is already used or voided.');
  END IF;

  -- ⚡ ATOMIC TRANSACTION BEGINS
  UPDATE tamper_tags
  SET status = 'USED', used_at = NOW()
  WHERE tag_id = p_tag_id;

  UPDATE shipments
  SET status = 'IN_TRANSIT_TO_HUB', tamper_tag_id = p_tag_id
  WHERE awb = p_awb;

  INSERT INTO chain_of_custody_logs (awb, actor_id, action_type, lat, lng, evidence_url, created_at)
  VALUES (p_awb, p_rider_id, 'SECURED_AT_MERCHANT', p_lat, p_lng, p_photo_url, NOW());

  RETURN jsonb_build_object('success', true, 'message', 'Chain of custody secured.');

EXCEPTION WHEN OTHERS THEN
  -- 🛡️ Auto-Rollback on failure
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.fetch_supervisor_pending_assignments()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_result jsonb;
BEGIN
  SELECT coalesce(jsonb_agg(to_jsonb(t)), '[]'::jsonb)
  INTO v_result
  FROM (
    SELECT
      pr.id::text as id,
      coalesce(pr.pickup_request_id, pr.id::text) as pickup_id,
      coalesce(pr.sender_name, 'Merchant') as sender_name,
      pr.sender_phone,
      coalesce(pr.parcel_count, 1) as parcel_count,
      coalesce(pr.status, 'pending_assignment') as status,
      pr.created_at,
      0 as cod_amount,
      null as pickup_time
    FROM public.be_pickup_requests pr
    WHERE pr.status IN ('pending_assignment', 'assigned', 'data_entry_in_progress', 'data_entry_ready')
       OR pr.id::text = 'd0b612d1-662b-43f3-b89a-1e7d704f3779'
    ORDER BY pr.created_at DESC
  ) t;

  RETURN v_result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_audit_checksum()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.checksum :=
    encode(
      digest(
        coalesce(new.user_id::text,'') ||
        coalesce(new.action,'') ||
        coalesce(new.table_name,'') ||
        coalesce(new.record_id::text,''),
        'sha256'
      ),
      'hex'
    );
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_awb_number()
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
    new_awb TEXT;
    counter INTEGER;
BEGIN
    -- Get current date in YYYYMMDD format
    SELECT TO_CHAR(NOW(), 'YYYYMMDD') INTO new_awb;

    -- Get count of shipments created today
    SELECT COUNT(*) + 1 INTO counter
    FROM public.shipments_2026_02_19_13_00
    WHERE DATE(created_at) = CURRENT_DATE;

    -- Format: YYYYMMDD + 6-digit counter (e.g., 20260219000001)
    new_awb := new_awb || LPAD(counter::TEXT, 6, '0');

    RETURN new_awb;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_britium_pickup_id(p_merchant_code text, p_parcel_count integer)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_date text;
    v_merchant text;
    v_count text;
BEGIN
    v_date := to_char(now(), 'MMDD');

    -- Extract first 3 alphanumeric characters of merchant code
    v_merchant := upper(substring(regexp_replace(COALESCE(p_merchant_code, 'XXX'), '[^a-zA-Z0-9]', '', 'g') from 1 for 3));
    IF length(v_merchant) < 3 THEN
        v_merchant := rpad(v_merchant, 3, 'X');
    END IF;

    -- Pad parcel count to 3 digits
    v_count := lpad(COALESCE(p_parcel_count, 1)::text, 3, '0');

    RETURN 'P' || v_date || '-' || v_merchant || '-' || v_count;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_customer_code()
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
    new_code TEXT;
    counter INTEGER;
BEGIN
    -- Get count of customers
    SELECT COUNT(*) + 1 INTO counter
    FROM public.customers_2026_02_19_13_00;

    -- Format: CUST + 6-digit counter (e.g., CUST000001)
    new_code := 'CUST' || LPAD(counter::TEXT, 6, '0');

    RETURN new_code;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_dispatch_route(p_branch_code text, p_rider_id uuid, p_pickup_ids text[], p_dispatcher_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_route_id TEXT;
    v_pickup_id TEXT;
BEGIN
    -- (၁) Route ID အသစ်ဖန်တီးခြင်း
    v_route_id := 'RTE-' || p_branch_code || '-' || TO_CHAR(NOW(), 'YYYYMMDD-HH24MISS');

    -- (၂) Route Header Record တည်ဆောက်ခြင်း
    INSERT INTO be_dispatch_routes (route_id, branch_code, assigned_rider_id, created_by, status)
    VALUES (v_route_id, p_branch_code, p_rider_id, p_dispatcher_id, 'ACTIVE');

    -- (၃) ရွေးချယ်ထားသော Pickup ID များကို Route သို့ ထည့်သွင်းခြင်း & Status ပြောင်းလဲခြင်း
    FOREACH v_pickup_id IN ARRAY p_pickup_ids
    LOOP
        -- Update Pickup Request Status to 'PICKUP_ASSIGNED'
        UPDATE be_portal_pickup_requests
        SET
            route_id = v_route_id,
            assigned_rider_id = p_rider_id,
            status = 'PICKUP_ASSIGNED'
        WHERE pickup_id = v_pickup_id;

        -- Cargo Event အသစ်ထည့်သွင်းခြင်း (Merchant/Customer Tracking အတွက်)
        INSERT INTO be_portal_cargo_events (pickup_id, status_code, updated_by)
        VALUES (v_pickup_id, 'PICKUP_ASSIGNED', p_dispatcher_id);

        -- အကယ်၍ Rider အဟောင်းမှ REASSIGN_RIDER Exception တင်ထားခဲ့ပါက Resolved အဖြစ်ပြောင်းပေးရန်
        UPDATE be_exception_audit
        SET resolved_at = NOW(), resolved_by = p_dispatcher_id
        WHERE shipment_id = v_pickup_id AND next_action = 'REASSIGN_RIDER' AND resolved_at IS NULL;

    END LOOP;

    -- (၄) Rider App သို့ Notification ပေးပို့ခြင်း
    INSERT INTO be_app_notifications (target_user_id, message, source_record_id)
    VALUES (p_rider_id, 'လမ်းကြောင်းအသစ် (Route) တာဝန်ချထားခံရပါသည်။', v_route_id);

    RETURN v_route_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_invoice_id(merchant_code text, seq_number integer)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
BEGIN
    -- Updated to 'INV' prefix as requested
    RETURN 'INV' || to_char(now(), 'MMDD') || '-' || merchant_code || '-' || lpad(seq_number::text, 3, '0');
END;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_merchant_code()
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
    new_code TEXT;
    counter INTEGER;
BEGIN
    -- Get count of merchants
    SELECT COUNT(*) + 1 INTO counter
    FROM public.merchants_2026_02_19_13_00;

    -- Format: MERCH + 6-digit counter (e.g., MERCH000001)
    new_code := 'MERCH' || LPAD(counter::TEXT, 6, '0');

    RETURN new_code;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_parcel_id_2026_02_18_17_00(p_pickup_zone character varying DEFAULT 'YGN'::character varying)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_sequence_num INTEGER;
    v_parcel_id TEXT;
BEGIN
    -- Get next sequence number for the zone and date
    SELECT COALESCE(MAX(CAST(SUBSTRING(parcel_id FROM '[0-9]+') AS INTEGER)), 0) + 1
    INTO v_sequence_num
    FROM public.parcels_2026_02_18_17_00
    WHERE parcel_id LIKE p_pickup_zone || '%' || p_pickup_zone
    AND DATE(created_at) = CURRENT_DATE;

    -- Format: YGN119874YGN (zone + 6-digit number + zone)
    v_parcel_id := p_pickup_zone || LPAD(v_sequence_num::TEXT, 6, '0') || p_pickup_zone;

    RETURN v_parcel_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_qr_code_2026_02_18_17_00(p_qr_data text, p_qr_type character varying DEFAULT 'SHIPMENT'::character varying, p_shipment_id text DEFAULT NULL::text, p_generated_by text DEFAULT 'system'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_qr_id UUID;
BEGIN
    -- Check if QR code already exists
    SELECT id INTO v_qr_id
    FROM public.qr_codes_2026_02_18_17_00
    WHERE qr_data = p_qr_data AND is_active = true;

    -- If not exists, create new QR code record
    IF v_qr_id IS NULL THEN
        INSERT INTO public.qr_codes_2026_02_18_17_00 (
            qr_data,
            qr_type,
            shipment_id,
            generated_by
        ) VALUES (
            p_qr_data,
            p_qr_type,
            p_shipment_id,
            p_generated_by
        ) RETURNING id INTO v_qr_id;
    ELSE
        -- Update existing record
        UPDATE public.qr_codes_2026_02_18_17_00
        SET updated_at = NOW()
        WHERE id = v_qr_id;
    END IF;

    RETURN v_qr_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_qr_code_advanced_2026_02_19_15_00(p_qr_type text, p_reference_id uuid, p_reference_type text, p_data jsonb DEFAULT '{}'::jsonb, p_generated_by uuid DEFAULT NULL::uuid)
 RETURNS TABLE(success boolean, qr_code text, qr_id uuid, message text)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_qr_code TEXT;
  v_qr_id UUID;
BEGIN
  -- Generate unique QR code
  v_qr_code := 'BRT-' || p_qr_type || '-' || EXTRACT(YEAR FROM NOW()) || '-' ||
               LPAD(EXTRACT(DOY FROM NOW())::TEXT, 3, '0') || '-' ||
               LPAD(EXTRACT(HOUR FROM NOW())::TEXT, 2, '0') ||
               LPAD(EXTRACT(MINUTE FROM NOW())::TEXT, 2, '0') ||
               LPAD(EXTRACT(SECOND FROM NOW())::TEXT, 2, '0') || '-' ||
               SUBSTRING(p_reference_id::TEXT, 1, 8);

  -- Insert QR code record
  INSERT INTO qr_codes_advanced_2026_02_19_15_00 (
    qr_code, qr_type, reference_id, reference_type, data, generated_by
  ) VALUES (
    v_qr_code, p_qr_type, p_reference_id, p_reference_type, p_data, p_generated_by
  ) RETURNING id INTO v_qr_id;

  RETURN QUERY SELECT true, v_qr_code, v_qr_id, 'QR code generated successfully'::TEXT;
EXCEPTION
  WHEN OTHERS THEN
    RETURN QUERY SELECT false, NULL::TEXT, NULL::UUID, SQLERRM::TEXT;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_smart_user_id()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    -- Determine Office Prefix
    NEW.display_id := CASE
        WHEN NEW.branch_code = 'YGN-HQ' THEN 'H'
        WHEN NEW.branch_code LIKE 'YGN%' THEN 'Y'
        WHEN NEW.branch_code LIKE 'MDY%' THEN 'M'
        WHEN NEW.branch_code LIKE 'NPT%' THEN 'N'
        ELSE 'X'
    END;

    -- Map Roles to Abbreviations
    NEW.display_id := NEW.display_id || '-' || CASE
        WHEN NEW.role = 'admin' THEN 'SADM'
        WHEN NEW.role = 'rider_bike' THEN 'RDB'
        WHEN NEW.role = 'rider_van' THEN 'RDD'
        WHEN NEW.role = 'rider_moto' THEN 'RDM'
        WHEN NEW.role = 'helper' THEN 'RDH'
        ELSE 'STFF'
    END;

    -- Append Serial (Simplified for demo)
    NEW.display_id := NEW.display_id || '-' || LPAD((SELECT COUNT(*) + 1 FROM public.operators WHERE role = NEW.role)::text, 4, '0');

    -- Auto-populate email from auth if not provided
    IF NEW.email IS NULL THEN
        SELECT email INTO NEW.email FROM auth.users WHERE id = NEW.id;
    END IF;

    RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_transaction_hash()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.auth_hash := encode(digest(
    NEW.id::text ||
    NEW.amount::text ||
    COALESCE(NEW.sender_id::text, 'none') ||
    COALESCE(NEW.recipient_id::text, 'none') ||
    'BRITIUM_SECURE_SALT_2026',
    'sha256'
  ), 'hex');
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_transaction_number()
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
    new_number TEXT;
    counter INTEGER;
BEGIN
    -- Get current date in YYYYMMDD format
    SELECT TO_CHAR(NOW(), 'YYYYMMDD') INTO new_number;

    -- Get count of transactions created today
    SELECT COUNT(*) + 1 INTO counter
    FROM public.transactions_2026_02_19_13_00
    WHERE DATE(created_at) = CURRENT_DATE;

    -- Format: TXN + YYYYMMDD + 4-digit counter (e.g., TXN202602190001)
    new_number := 'TXN' || new_number || LPAD(counter::TEXT, 4, '0');

    RETURN new_number;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_waybill_id(merchant_code text, seq_number integer)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
BEGIN
    -- This uses 'MMDD' from the current date (now())
    RETURN 'WB' || to_char(now(), 'MMDD') || '-' || merchant_code || '-' || lpad(seq_number::text, 3, '0');
END;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_waybill_id(p_org text, p_dst text, p_tag text DEFAULT 'HQ'::text)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE seq_val text;
BEGIN
  seq_val := lpad(floor(random() * 900000 + 100000)::text, 6, '0');
  RETURN upper(p_org) || seq_val || upper(p_tag) || to_char(now(), 'DDMMYYYY') || upper(p_dst);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_waybill_id(p_origin_city text, p_dest_city text, p_office_tag text DEFAULT NULL::text, p_branch_code text DEFAULT NULL::text, p_issue_date date DEFAULT CURRENT_DATE)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  org text := public.city_code(p_origin_city);
  dst text := public.city_code(p_dest_city);
  tag text := upper(coalesce(p_office_tag, public.current_office_tag(), 'HQ'));
  bcode text := upper(coalesce(p_branch_code, public.current_branch_code(), ''));
  seq bigint;
  seq6 text;
  dstr text := to_char(p_issue_date, 'DDMMYYYY');
begin
  if tag not in ('HQ','BO') then tag := 'HQ'; end if;
  if tag = 'HQ' then bcode := ''; end if;

  seq := public.next_waybill_seq(p_issue_date, org, tag, bcode);
  seq6 := lpad(seq::text, 6, '0');

  return org || seq6 || tag || bcode || dstr || dst;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_assignment_queue_2026_02_19_17_00(p_user_id uuid DEFAULT NULL::uuid, p_branch_id uuid DEFAULT NULL::uuid, p_queue_type character varying DEFAULT NULL::character varying, p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_result JSONB;
BEGIN
    SELECT jsonb_agg(
        jsonb_build_object(
            'id', aq.id,
            'shipment_id', aq.shipment_id,
            'queue_type', aq.queue_type,
            'priority', aq.priority,
            'status', aq.status,
            'queue_position', aq.queue_position,
            'estimated_processing_time', aq.estimated_processing_time,
            'created_at', aq.created_at,
            'shipment_info', (
                SELECT jsonb_build_object(
                    'awb_number', s.awb_number,
                    'sender_name', s.sender_name,
                    'receiver_name', s.receiver_name,
                    'pickup_address', s.pickup_address,
                    'delivery_address', s.delivery_address,
                    'cod_amount', s.cod_amount,
                    'service_type', s.service_type
                )
                FROM shipments_2026_02_19_13_00 s
                WHERE s.id = aq.shipment_id
            )
        )
        ORDER BY aq.priority ASC, aq.created_at ASC
    ) INTO v_result
    FROM assignment_queue_2026_02_19_17_00 aq
    WHERE
        (p_user_id IS NULL OR aq.assigned_user_id = p_user_id)
        AND (p_branch_id IS NULL OR aq.branch_id = p_branch_id)
        AND (p_queue_type IS NULL OR aq.queue_type = p_queue_type)
        AND aq.status = 'PENDING'
    LIMIT p_limit;

    RETURN COALESCE(v_result, '[]'::jsonb);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_britium_merchant_pricing_policy(p_merchant_code text DEFAULT NULL::text)
 RETURNS TABLE(merchant_code text, merchant_name text, allowance_kg numeric, extra_per_kg_mmk numeric, is_special_5kg_allowance boolean)
 LANGUAGE sql
 STABLE
AS $function$
  SELECT m.merchant_code, m.merchant_name,
         CASE WHEN m.is_special_5kg_allowance THEN m.special_allowance_kg ELSE m.standard_allowance_kg END AS allowance_kg,
         m.extra_per_kg_mmk,
         m.is_special_5kg_allowance
  FROM public.britium_merchant_master m
  WHERE p_merchant_code IS NULL OR UPPER(m.merchant_code) = UPPER(p_merchant_code)
  ORDER BY m.merchant_name;
$function$
;

CREATE OR REPLACE FUNCTION public.get_britium_merchant_pricing_policy(p_merchant_code text DEFAULT NULL::text, p_merchant_name text DEFAULT NULL::text)
 RETURNS TABLE(merchant_code text, merchant_name text, is_special_5kg_allowance boolean, allowance_kg numeric, extra_per_kg_mmk numeric)
 LANGUAGE sql
 STABLE
AS $function$
  SELECT
    m.merchant_code,
    m.merchant_name,
    m.is_special_5kg_allowance,
    CASE WHEN m.is_special_5kg_allowance THEN m.special_allowance_kg ELSE m.standard_allowance_kg END AS allowance_kg,
    m.extra_per_kg_mmk
  FROM public.britium_merchant_master m
  WHERE (p_merchant_code IS NOT NULL AND m.merchant_code = p_merchant_code)
     OR (p_merchant_code IS NULL AND p_merchant_name IS NOT NULL AND lower(m.merchant_name) = lower(p_merchant_name))
  ORDER BY m.is_active DESC, m.updated_at DESC
  LIMIT 1;
$function$
;

CREATE OR REPLACE FUNCTION public.get_cs_dashboard_snapshot()
 RETURNS json
 LANGUAGE plpgsql
AS $function$
DECLARE
  open_reqs INT;
  pickup_reqs INT;
  merchant_opts INT;
BEGIN
  -- Count metrics from your tables
  SELECT count(*) INTO open_reqs FROM pickup_queue WHERE status = 'Open';
  SELECT count(*) INTO pickup_reqs FROM pickup_queue;
  SELECT count(*) INTO merchant_opts FROM merchant_master;

  -- Return the exact JSON structure your frontend expects
  RETURN json_build_object(
    'total_tickets', 0,
    'open_requests', open_reqs,
    'pickup_requests', pickup_reqs,
    'merchant_options', merchant_opts
  );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_dashboard_metrics(p_user_id uuid DEFAULT NULL::uuid, p_branch_id uuid DEFAULT NULL::uuid, p_date_from date DEFAULT (CURRENT_DATE - '30 days'::interval), p_date_to date DEFAULT CURRENT_DATE)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    result JSONB;
    total_shipments INTEGER;
    pending_shipments INTEGER;
    delivered_shipments INTEGER;
    total_revenue DECIMAL(12,2);
    cod_collected DECIMAL(12,2);
    active_vehicles INTEGER;
BEGIN
    -- Get shipment metrics
    SELECT COUNT(*) INTO total_shipments
    FROM public.shipments_2026_02_19_13_00
    WHERE created_at::DATE BETWEEN p_date_from AND p_date_to
    AND (p_branch_id IS NULL OR origin_branch_id = p_branch_id);

    SELECT COUNT(*) INTO pending_shipments
    FROM public.shipments_2026_02_19_13_00
    WHERE status IN ('CREATED', 'PICKED_UP', 'IN_TRANSIT')
    AND (p_branch_id IS NULL OR origin_branch_id = p_branch_id);

    SELECT COUNT(*) INTO delivered_shipments
    FROM public.shipments_2026_02_19_13_00
    WHERE status = 'DELIVERED'
    AND created_at::DATE BETWEEN p_date_from AND p_date_to
    AND (p_branch_id IS NULL OR origin_branch_id = p_branch_id);

    -- Get financial metrics
    SELECT COALESCE(SUM(total_cost), 0) INTO total_revenue
    FROM public.shipments_2026_02_19_13_00
    WHERE created_at::DATE BETWEEN p_date_from AND p_date_to
    AND (p_branch_id IS NULL OR origin_branch_id = p_branch_id);

    SELECT COALESCE(SUM(amount), 0) INTO cod_collected
    FROM public.transactions_2026_02_19_13_00
    WHERE transaction_type = 'COD_COLLECTION'
    AND status = 'COMPLETED'
    AND created_at::DATE BETWEEN p_date_from AND p_date_to
    AND (p_branch_id IS NULL OR branch_id = p_branch_id);

    -- Get vehicle metrics
    SELECT COUNT(*) INTO active_vehicles
    FROM public.vehicles_2026_02_19_13_00
    WHERE status = 'AVAILABLE'
    AND (p_branch_id IS NULL OR home_branch_id = p_branch_id);

    -- Build result JSON
    result := jsonb_build_object(
        'total_shipments', total_shipments,
        'pending_shipments', pending_shipments,
        'delivered_shipments', delivered_shipments,
        'delivery_rate', CASE WHEN total_shipments > 0 THEN ROUND((delivered_shipments::DECIMAL / total_shipments) * 100, 2) ELSE 0 END,
        'total_revenue', total_revenue,
        'cod_collected', cod_collected,
        'active_vehicles', active_vehicles,
        'date_range', jsonb_build_object('from', p_date_from, 'to', p_date_to)
    );

    RETURN result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_finance_summary()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  select jsonb_build_object(
    'wallet_accounts', coalesce((select count(*) from public.wallet_accounts), 0),
    'wallet_transactions', coalesce((select count(*) from public.wallet_transactions), 0),
    'total_balance', coalesce((select sum(coalesce(balance, 0)) from public.wallet_accounts), 0),
    'updated_at', now()
  );
$function$
;

CREATE OR REPLACE FUNCTION public.get_qr_stats_2026_02_18_17_00(p_user_id text DEFAULT NULL::text, p_days integer DEFAULT 30)
 RETURNS TABLE(total_generated bigint, total_scanned bigint, unique_scanners bigint, most_scanned_data text, recent_activity jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
    RETURN QUERY
    WITH stats AS (
        SELECT
            COUNT(*) as generated_count,
            SUM(scan_count) as total_scan_count,
            COUNT(DISTINCT last_scanned_by) FILTER (WHERE last_scanned_by IS NOT NULL) as unique_scanner_count
        FROM public.qr_codes_2026_02_18_17_00
        WHERE (p_user_id IS NULL OR generated_by = p_user_id)
        AND generated_at >= NOW() - INTERVAL '1 day' * p_days
    ),
    most_scanned AS (
        SELECT qr_data
        FROM public.qr_codes_2026_02_18_17_00
        WHERE (p_user_id IS NULL OR generated_by = p_user_id)
        AND generated_at >= NOW() - INTERVAL '1 day' * p_days
        ORDER BY scan_count DESC
        LIMIT 1
    ),
    recent AS (
        SELECT jsonb_agg(
            jsonb_build_object(
                'qr_data', qr_data,
                'type', qr_type,
                'generated_at', generated_at,
                'scan_count', scan_count
            ) ORDER BY generated_at DESC
        ) as activity
        FROM public.qr_codes_2026_02_18_17_00
        WHERE (p_user_id IS NULL OR generated_by = p_user_id)
        AND generated_at >= NOW() - INTERVAL '1 day' * p_days
        LIMIT 10
    )
    SELECT
        s.generated_count,
        s.total_scan_count,
        s.unique_scanner_count,
        ms.qr_data,
        r.activity
    FROM stats s
    CROSS JOIN most_scanned ms
    CROSS JOIN recent r;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_shipment_workflow_2026_02_19_17_00(p_shipment_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_result JSONB;
BEGIN
    SELECT jsonb_build_object(
        'shipment_id', sws.shipment_id,
        'current_state', sws.current_state,
        'previous_state', sws.previous_state,
        'assigned_to_user', u.full_name,
        'assigned_to_branch', b.name,
        'auto_assigned', sws.auto_assigned,
        'assignment_reason', sws.assignment_reason,
        'created_at', sws.created_at,
        'updated_at', sws.updated_at,
        'queue_info', (
            SELECT jsonb_build_object(
                'queue_type', aq.queue_type,
                'priority', aq.priority,
                'status', aq.status,
                'queue_position', aq.queue_position
            )
            FROM assignment_queue_2026_02_19_17_00 aq
            WHERE aq.shipment_id = p_shipment_id
            ORDER BY aq.created_at DESC
            LIMIT 1
        )
    ) INTO v_result
    FROM shipment_workflow_states_2026_02_19_17_00 sws
    LEFT JOIN users_2026_02_19_13_00 u ON sws.assigned_to_user_id = u.id
    LEFT JOIN branches_2026_02_19_13_00 b ON sws.assigned_to_branch_id = b.id
    WHERE sws.shipment_id = p_shipment_id
    ORDER BY sws.created_at DESC
    LIMIT 1;

    RETURN COALESCE(v_result, '{"error": "Shipment workflow not found"}'::jsonb);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_user_permissions(user_role text)
 RETURNS TABLE(permission_code text, domain text, resource text, action text, scope text)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
    RETURN QUERY
    SELECT p.code, p.domain, p.resource, p.action, p.scope
    FROM permissions p
    JOIN role_permissions rp ON p.code = rp.permission_code
    WHERE rp.role_code = user_role AND p.is_active = true;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_waybill_invoice_data(p_pickup_id text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_result JSON;
BEGIN
    SELECT json_build_object(
        'pickup_id', p.pickup_id,
        'created_at', p.created_at,
        'branch_code', p.branch_code,
        'status', p.status,

        -- Sender Info
        'sender_name', p.sender_name,
        'sender_phone', p.sender_phone,
        'sender_address', p.sender_address,

        -- Receiver Info
        'receiver_name', p.receiver_name,
        'receiver_phone', p.receiver_phone,
        'receiver_address', p.receiver_address,
        'receiver_city', p.receiver_city,

        -- Parcel & Tariff Info
        'weight', p.weight,
        'tier', p.tier,
        'payment_terms', p.payment_terms,
        'cod_amount', COALESCE(p.cod_amount, 0),
        'base_fee', p.base_fee,
        'weight_surcharge', COALESCE(p.weight_surcharge, 0),
        'highway_fee', COALESCE(p.highway_fee, 0),
        'total_tariff', COALESCE(p.base_fee, 0) + COALESCE(p.weight_surcharge, 0) + COALESCE(p.highway_fee, 0),

        -- Routing Info
        'destination_hub', CASE
            WHEN p.receiver_city ILIKE '%Mandalay%' THEN 'MDY-HUB'
            WHEN p.receiver_city ILIKE '%Naypyitaw%' THEN 'NPT-HUB'
            ELSE 'YGN-HUB'
        END
    ) INTO v_result
    FROM be_portal_pickup_requests p
    WHERE p.pickup_id = p_pickup_id;

    RETURN v_result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_waybill_print_data(p_way_id text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  SELECT jsonb_build_object(
    'way_id', s.way_id,
    'qr_code', s.way_id, -- Used to generate the barcode/QR
    'date', to_char(s.created_at, 'DD-Mon-YYYY'),
    'sender', jsonb_build_object(
        'name', s.sender_name,
        'phone', s.sender_phone,
        'city', s.sender_city
    ),
    'receiver', jsonb_build_object(
        'name', s.receiver_name,
        'phone', s.receiver_phone,
        'address', s.receiver_address,
        'city', s.receiver_city
    ),
    'financials', jsonb_build_object(
        'cod', s.cod_amount,
        'fee', s.delivery_fee,
        'total', s.total_amount
    ),
    'service', s.service_type
  )
  FROM public.shipments s
  WHERE s.way_id = p_way_id;
$function$
;

