CREATE OR REPLACE FUNCTION public.log_approval_history(p_entity_type text, p_entity_id uuid, p_action text, p_reason text DEFAULT NULL::text, p_meta jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor text := coalesce(auth.jwt() ->> 'email', auth.uid()::text, 'system');
  v_role text := public.current_app_role();
begin
  insert into public.approval_history (
    entity_type,
    entity_id,
    action,
    actor,
    actor_role,
    reason,
    meta
  )
  values (
    p_entity_type,
    p_entity_id,
    upper(coalesce(p_action, 'UNKNOWN')),
    v_actor,
    v_role,
    nullif(trim(coalesce(p_reason, '')), ''),
    coalesce(p_meta, '{}'::jsonb)
  );
end;
$function$
;

