CREATE OR REPLACE FUNCTION public.log_qr_scan_2026_02_18_17_00(p_qr_data text, p_scanned_by text, p_scan_location jsonb DEFAULT NULL::jsonb, p_device_info jsonb DEFAULT NULL::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_qr_id UUID;
    v_scan_id UUID;
BEGIN
    -- Find the QR code
    SELECT id INTO v_qr_id
    FROM public.qr_codes_2026_02_18_17_00
    WHERE qr_data = p_qr_data AND is_active = true;

    -- If QR code doesn't exist, create it
    IF v_qr_id IS NULL THEN
        v_qr_id := public.generate_qr_code_2026_02_18_17_00(p_qr_data, 'UNKNOWN', NULL, 'scanner');
    END IF;

    -- Log the scan
    INSERT INTO public.qr_scan_logs_2026_02_18_17_00 (
        qr_code_id,
        qr_data,
        scanned_by,
        scan_location,
        device_info
    ) VALUES (
        v_qr_id,
        p_qr_data,
        p_scanned_by,
        p_scan_location,
        p_device_info
    ) RETURNING id INTO v_scan_id;

    -- Update scan count and last scan info
    UPDATE public.qr_codes_2026_02_18_17_00
    SET
        scan_count = scan_count + 1,
        last_scanned_at = NOW(),
        last_scanned_by = p_scanned_by,
        updated_at = NOW()
    WHERE id = v_qr_id;

    RETURN v_scan_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.log_qr_scan_event(p_actor_staff_id uuid, p_next_staff_id uuid, p_process_step text, p_shipment_id uuid DEFAULT NULL::uuid, p_manifest_id uuid DEFAULT NULL::uuid, p_delivery_id uuid DEFAULT NULL::uuid, p_territory_code text DEFAULT NULL::text, p_scan_channel text DEFAULT 'qr_scanner'::text, p_notes text DEFAULT NULL::text, p_event_payload jsonb DEFAULT '{}'::jsonb, p_location_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_event_id uuid;
begin
  insert into public.qr_scan_events (
    shipment_id,
    manifest_id,
    delivery_id,
    actor_staff_id,
    next_staff_id,
    process_step,
    territory_code,
    scan_channel,
    notes,
    event_payload,
    location_payload,
    requires_ack
  )
  values (
    p_shipment_id,
    p_manifest_id,
    p_delivery_id,
    p_actor_staff_id,
    p_next_staff_id,
    p_process_step,
    p_territory_code,
    p_scan_channel,
    p_notes,
    coalesce(p_event_payload, '{}'::jsonb),
    coalesce(p_location_payload, '{}'::jsonb),
    true
  )
  returning id into v_event_id;

  if p_next_staff_id is not null then
    insert into public.workflow_acknowledgements (
      qr_scan_event_id,
      responsible_staff_id,
      status,
      due_at,
      reminder_count
    )
    values (
      v_event_id,
      p_next_staff_id,
      'pending',
      now() + interval '15 minutes',
      0
    );
  end if;

  return v_event_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.log_shipment_status_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
    IF OLD.status IS DISTINCT FROM NEW.status THEN
        INSERT INTO public.audit_logs (record_id, action, actor_id, old_data, new_data)
        VALUES (
            NEW.tracking_number,
            'STATUS_CHANGED_TO_' || UPPER(NEW.status::text),
            auth.uid(),
            jsonb_build_object('status', OLD.status),
            jsonb_build_object('status', NEW.status)
        );
    END IF;

    -- Auto-update the 'updated_at' timestamp
    NEW.updated_at = now();
    RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.lookup_townships(p_language text DEFAULT 'en'::text, p_state_region_code text DEFAULT NULL::text)
 RETURNS TABLE(township_code text, label text, state_region_code text, state_region_label text, district_label text)
 LANGUAGE sql
 STABLE
AS $function$
  SELECT
    township_code,
    CASE WHEN lower(coalesce(p_language, 'en')) = 'mm' THEN township_name_mm ELSE township_name_en END AS label,
    state_region_code,
    CASE WHEN lower(coalesce(p_language, 'en')) = 'mm' THEN state_region_name_mm ELSE state_region_name_en END AS state_region_label,
    CASE WHEN lower(coalesce(p_language, 'en')) = 'mm' THEN district_saz_name_mm ELSE district_saz_name_en END AS district_label
  FROM public.township_master
  WHERE is_selectable_for_address = TRUE
    AND (p_state_region_code IS NULL OR state_region_code = p_state_region_code)
  ORDER BY state_region_label, district_label, label;
$function$
;

