CREATE OR REPLACE FUNCTION public.process_gps_update_2026_02_18_18_00(p_device_id text, p_latitude numeric, p_longitude numeric, p_speed numeric DEFAULT NULL::numeric, p_heading numeric DEFAULT NULL::numeric, p_accuracy numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_tracking_id UUID;
    v_user_id TEXT;
    v_route_id UUID;
    v_geofence RECORD;
    v_events JSONB := '[]';
    v_is_moving BOOLEAN;
BEGIN
    -- Determine if moving (speed > 5 km/h)
    v_is_moving := COALESCE(p_speed, 0) > 5;

    -- Insert GPS tracking record
    INSERT INTO public.gps_tracking_2026_02_18_18_00 (
        device_id, latitude, longitude, speed, heading, accuracy,
        is_moving, recorded_at
    ) VALUES (
        p_device_id, p_latitude, p_longitude, p_speed, p_heading, p_accuracy,
        v_is_moving, NOW()
    ) RETURNING id, user_id, route_id INTO v_tracking_id, v_user_id, v_route_id;

    -- Check for geofence events
    FOR v_geofence IN
        SELECT id, name, type, entry_alert, exit_alert
        FROM public.geofences_2026_02_18_18_00
        WHERE is_active = true
    LOOP
        IF public.check_geofence_2026_02_18_18_00(p_latitude, p_longitude, v_geofence.id) THEN
            -- Create geofence entry event
            INSERT INTO public.realtime_events_2026_02_18_18_00 (
                event_type, entity_type, entity_id, event_data, location, geofence_id
            ) VALUES (
                'GEOFENCE_ENTRY', 'DEVICE', p_device_id,
                jsonb_build_object(
                    'geofence_name', v_geofence.name,
                    'geofence_type', v_geofence.type,
                    'user_id', v_user_id,
                    'route_id', v_route_id
                ),
                jsonb_build_object('lat', p_latitude, 'lng', p_longitude),
                v_geofence.id
            );

            v_events := v_events || jsonb_build_object(
                'type', 'geofence_entry',
                'geofence', v_geofence.name
            );
        END IF;
    END LOOP;

    -- Check for speed violations (> 80 km/h)
    IF COALESCE(p_speed, 0) > 80 THEN
        INSERT INTO public.realtime_events_2026_02_18_18_00 (
            event_type, entity_type, entity_id, event_data, location, priority
        ) VALUES (
            'SPEED_VIOLATION', 'DEVICE', p_device_id,
            jsonb_build_object(
                'speed', p_speed,
                'limit', 80,
                'user_id', v_user_id,
                'route_id', v_route_id
            ),
            jsonb_build_object('lat', p_latitude, 'lng', p_longitude),
            'HIGH'
        );

        v_events := v_events || jsonb_build_object(
            'type', 'speed_violation',
            'speed', p_speed
        );
    END IF;

    RETURN jsonb_build_object(
        'tracking_id', v_tracking_id,
        'events_triggered', v_events,
        'is_moving', v_is_moving
    );
END;
$function$
;

CREATE OR REPLACE FUNCTION public.process_warehouse_scan(p_pickup_id text, p_branch_code text, p_scan_type text, p_scanned_by uuid, p_actual_weight numeric DEFAULT NULL::numeric)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_current_status TEXT;
    v_new_status TEXT;
    v_declared_weight DECIMAL;
BEGIN
    -- (၁) လက်ရှိ Shipment အချက်အလက်ကို ဆွဲယူခြင်း
    SELECT status, weight INTO v_current_status, v_declared_weight
    FROM be_portal_pickup_requests
    WHERE pickup_id = p_pickup_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Shipment / Waybill ရှာမတွေ့ပါ။';
    END IF;

    -- (၂) Exception Rule: Weight Mismatch စစ်ဆေးခြင်း
    IF p_actual_weight IS NOT NULL AND ABS(p_actual_weight - v_declared_weight) > 0.5 THEN
        INSERT INTO be_exception_audit (shipment_id, branch_id, exception_code, new_status, remarks, reported_by_user_id, next_action)
        VALUES (p_pickup_id, p_branch_code, 'WEIGHT_MISMATCH', 'QC_FAILED', 'Actual weight differs significantly.', p_scanned_by, 'RECALCULATE_TARIFF');

        UPDATE be_portal_pickup_requests SET status = 'QC_FAILED' WHERE pickup_id = p_pickup_id;
        RETURN 'EXCEPTION_WEIGHT_MISMATCH';
    END IF;

    -- (၃) Scan Type အလိုက် Status အသစ်သတ်မှတ်ခြင်း
    IF p_scan_type = 'INBOUND' THEN
        v_new_status := 'RECEIVED_AT_ORIGIN';
    ELSIF p_scan_type = 'SORTING' THEN
        v_new_status := 'SORTING';
    ELSIF p_scan_type = 'OUTBOUND' THEN
        v_new_status := 'READY_FOR_DISPATCH';
    END IF;

    -- (၄) Status Update လုပ်ခြင်း & Cargo Event ထည့်သွင်းခြင်း
    UPDATE be_portal_pickup_requests
    SET status = v_new_status, current_branch = p_branch_code
    WHERE pickup_id = p_pickup_id;

    INSERT INTO be_portal_cargo_events (pickup_id, status_code, branch_code, updated_by)
    VALUES (p_pickup_id, v_new_status, p_branch_code, p_scanned_by);

    RETURN v_new_status;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.public_track_shipment(p_way_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  s record;
begin
  select
    sh.id, sh.way_id, sh.status, sh.estimated_delivery, sh.receiver_city, sh.receiver_state, sh.created_at
  into s
  from public.shipments sh
  where sh.way_id = p_way_id
  limit 1;

  if s.id is null then
    return jsonb_build_object('found', false);
  end if;

  return jsonb_build_object(
    'found', true,
    'shipment', jsonb_build_object(
      'id', s.id,
      'way_id', s.way_id,
      'status', s.status,
      'estimated_delivery', s.estimated_delivery,
      'receiver_city', s.receiver_city,
      'receiver_state', s.receiver_state,
      'created_at', s.created_at
    ),
    'tracking', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'timestamp', t.timestamp,
          'status', t.status,
          'location', t.location,
          'notes', t.notes
        )
        order by t.timestamp asc
      )
      from public.shipment_tracking t
      where t.shipment_id = s.id
        and t.is_customer_visible = true
    ), '[]'::jsonb)
  );
end
$function$
;

CREATE OR REPLACE FUNCTION public.publish_current_app_tariffs()
 RETURNS TABLE(published_count integer, skipped_missing_price_count integer)
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_published INTEGER := 0;
  v_skipped INTEGER := 0;
BEGIN
  SELECT COUNT(*) INTO v_skipped
  FROM public.current_app_tariff_staging
  WHERE is_active = TRUE AND base_price_mmk IS NULL;

  DELETE FROM public.tariffs t
  USING public.current_app_tariff_staging s
  WHERE s.is_active = TRUE
    AND s.base_price_mmk IS NOT NULL
    AND (
      (t.township_code IS NOT NULL AND t.township_code = s.township_code) OR
      (t.township_code IS NULL AND lower(t.township_name) = lower(s.township_name_for_current_app))
    );

  INSERT INTO public.tariffs (
    zone,
    service_type,
    weight_band,
    delivery_type,
    city,
    base_fee,
    extra_fee,
    status,
    version,
    township_name,
    township_code,
    base_price,
    weight_surcharge_per_kg,
    currency,
    route_pricing_group,
    standard_allowance_kg,
    special_merchant_allowance_kg,
    bus_station_dropoff_fee_mmk,
    created_at,
    updated_at
  )
  SELECT
    COALESCE(route_pricing_group, 'OTHER_REVIEW') AS zone,
    'STANDARD' AS service_type,
    '0-' || TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM COALESCE(standard_allowance_kg, 3)::TEXT)) || 'KG' AS weight_band,
    'Normal' AS delivery_type,
    COALESCE(state_region_name_en, 'Myanmar') AS city,
    COALESCE(base_price_mmk, 0) AS base_fee,
    COALESCE(weight_surcharge_per_kg_mmk, 500) AS extra_fee,
    'active' AS status,
    'v1' AS version,
    township_name_for_current_app AS township_name,
    township_code,
    COALESCE(base_price_mmk, 0) AS base_price,
    COALESCE(weight_surcharge_per_kg_mmk, 500) AS weight_surcharge_per_kg,
    COALESCE(currency, 'MMK') AS currency,
    COALESCE(route_pricing_group, 'OTHER_REVIEW') AS route_pricing_group,
    COALESCE(standard_allowance_kg, 3) AS standard_allowance_kg,
    COALESCE(special_merchant_allowance_kg, 5) AS special_merchant_allowance_kg,
    COALESCE(bus_station_dropoff_fee_mmk, 3000) AS bus_station_dropoff_fee_mmk,
    NOW() AS created_at,
    NOW() AS updated_at
  FROM public.current_app_tariff_staging
  WHERE is_active = TRUE
    AND base_price_mmk IS NOT NULL;

  GET DIAGNOSTICS v_published = ROW_COUNT;
  RETURN QUERY SELECT v_published, v_skipped;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.publish_excel_current_app_tariffs_to_legacy_tariffs()
 RETURNS TABLE(inserted_or_updated integer)
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_count INTEGER := 0;
BEGIN
  IF to_regclass('public.tariffs') IS NULL THEN
    RAISE NOTICE 'public.tariffs does not exist; skipped legacy publish.';
    RETURN QUERY SELECT 0;
    RETURN;
  END IF;

  ALTER TABLE public.tariffs ADD COLUMN IF NOT EXISTS township_name TEXT;
  ALTER TABLE public.tariffs ADD COLUMN IF NOT EXISTS township_code TEXT;
  ALTER TABLE public.tariffs ADD COLUMN IF NOT EXISTS base_price NUMERIC(12,2);
  ALTER TABLE public.tariffs ADD COLUMN IF NOT EXISTS weight_surcharge_per_kg NUMERIC(12,2);
  ALTER TABLE public.tariffs ADD COLUMN IF NOT EXISTS currency TEXT DEFAULT 'MMK';
  ALTER TABLE public.tariffs ADD COLUMN IF NOT EXISTS route_pricing_group TEXT;
  ALTER TABLE public.tariffs ADD COLUMN IF NOT EXISTS standard_allowance_kg NUMERIC(8,2) DEFAULT 3;
  ALTER TABLE public.tariffs ADD COLUMN IF NOT EXISTS special_merchant_allowance_kg NUMERIC(8,2) DEFAULT 5;
  ALTER TABLE public.tariffs ADD COLUMN IF NOT EXISTS bus_station_dropoff_fee_mmk NUMERIC(12,2) DEFAULT 3000;
  ALTER TABLE public.tariffs ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ DEFAULT NOW();

  -- If legacy columns exist and are NOT NULL, make sure they have safe defaults.
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='tariffs' AND column_name='zone') THEN
    UPDATE public.tariffs SET zone = COALESCE(zone, 'OTHER_REVIEW');
  END IF;
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='tariffs' AND column_name='service_type') THEN
    UPDATE public.tariffs SET service_type = COALESCE(service_type, 'STANDARD');
  END IF;
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='tariffs' AND column_name='weight_band') THEN
    UPDATE public.tariffs SET weight_band = COALESCE(weight_band, '0-3KG');
  END IF;

  DELETE FROM public.tariffs
  WHERE township_code IN (
    SELECT township_code FROM public.britium_tariff_current_master WHERE is_active = TRUE AND base_price_mmk IS NOT NULL
  );

  INSERT INTO public.tariffs (
    zone,
    service_type,
    weight_band,
    delivery_type,
    city,
    base_fee,
    extra_fee,
    status,
    version,
    township_name,
    township_code,
    base_price,
    weight_surcharge_per_kg,
    currency,
    route_pricing_group,
    standard_allowance_kg,
    special_merchant_allowance_kg,
    bus_station_dropoff_fee_mmk,
    updated_at
  )
  SELECT
    COALESCE(route_pricing_group, 'OTHER_REVIEW') AS zone,
    'STANDARD' AS service_type,
    '0-3KG' AS weight_band,
    'Normal' AS delivery_type,
    COALESCE(state_region_name_en, 'Myanmar') AS city,
    COALESCE(base_price_mmk, 0) AS base_fee,
    COALESCE(weight_surcharge_per_kg_mmk, 500) AS extra_fee,
    'active' AS status,
    'v8_excel' AS version,
    township_name_for_current_app AS township_name,
    township_code,
    base_price_mmk AS base_price,
    COALESCE(weight_surcharge_per_kg_mmk, 500) AS weight_surcharge_per_kg,
    COALESCE(currency, 'MMK') AS currency,
    route_pricing_group,
    COALESCE(standard_allowance_kg, 3) AS standard_allowance_kg,
    COALESCE(special_merchant_allowance_kg, 5) AS special_merchant_allowance_kg,
    COALESCE(bus_station_dropoff_fee_mmk, 3000) AS bus_station_dropoff_fee_mmk,
    NOW() AS updated_at
  FROM public.britium_tariff_current_master
  WHERE is_active = TRUE
    AND base_price_mmk IS NOT NULL;

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN QUERY SELECT v_count;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.record_cod_collection(p_shipment_id uuid, p_collected_by uuid, p_amount numeric, p_payment_method character varying)
 RETURNS uuid
 LANGUAGE plpgsql
AS $function$
DECLARE
    transaction_id UUID;
    transaction_number TEXT;
BEGIN
    -- Generate transaction number
    SELECT generate_transaction_number() INTO transaction_number;

    -- Insert transaction
    INSERT INTO public.transactions_2026_02_19_13_00 (
        transaction_number, transaction_type, reference_type, reference_id,
        amount, payment_method, collected_by, status
    ) VALUES (
