CREATE OR REPLACE FUNCTION public.record_gps_location_2026_02_19_15_00(p_device_id text, p_latitude numeric, p_longitude numeric, p_vehicle_id uuid DEFAULT NULL::uuid, p_rider_id uuid DEFAULT NULL::uuid, p_shipment_id uuid DEFAULT NULL::uuid, p_altitude numeric DEFAULT NULL::numeric, p_accuracy numeric DEFAULT NULL::numeric, p_speed numeric DEFAULT NULL::numeric, p_heading numeric DEFAULT NULL::numeric, p_battery_level integer DEFAULT NULL::integer, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS TABLE(success boolean, location_id uuid, message text)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_location_id UUID;
BEGIN
  -- Insert GPS tracking record
  INSERT INTO gps_tracking_advanced_2026_02_19_15_00 (
    device_id, latitude, longitude, vehicle_id, rider_id, shipment_id,
    altitude, accuracy, speed, heading, battery_level, metadata
  ) VALUES (
    p_device_id, p_latitude, p_longitude, p_vehicle_id, p_rider_id, p_shipment_id,
