CREATE OR REPLACE FUNCTION public.record_rider_pickup_verification(p_tracking_no text DEFAULT NULL::text, p_awb text DEFAULT NULL::text, p_pickup_id text DEFAULT NULL::text, p_rider_id text DEFAULT NULL::text, p_rider_name text DEFAULT NULL::text, p_merchant_code text DEFAULT NULL::text, p_merchant_name text DEFAULT NULL::text, p_expected_parcel_count integer DEFAULT NULL::integer, p_verified_parcel_count integer DEFAULT NULL::integer, p_condition_note text DEFAULT NULL::text, p_proof_photo_url text DEFAULT NULL::text, p_signature_url text DEFAULT NULL::text, p_lat numeric DEFAULT NULL::numeric, p_lng numeric DEFAULT NULL::numeric, p_tamper_tag_id text DEFAULT NULL::text)
 RETURNS public.rider_pickup_verification_log
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_row public.rider_pickup_verification_log;
BEGIN
  INSERT INTO public.rider_pickup_verification_log (
    tracking_no, awb, pickup_id, rider_id, rider_name,
    merchant_code, merchant_name, expected_parcel_count, verified_parcel_count,
    condition_note, proof_photo_url, signature_url, lat, lng, tamper_tag_id,
    verification_status
  )
  VALUES (
    p_tracking_no, p_awb, p_pickup_id, p_rider_id, p_rider_name,
    p_merchant_code, p_merchant_name, p_expected_parcel_count, p_verified_parcel_count,
    p_condition_note, p_proof_photo_url, p_signature_url, p_lat, p_lng, p_tamper_tag_id,
    CASE WHEN p_expected_parcel_count IS NOT NULL AND p_verified_parcel_count IS NOT NULL
           AND p_expected_parcel_count <> p_verified_parcel_count
         THEN 'mismatch'
         ELSE 'verified'
    END
  )
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$function$
;

