CREATE OR REPLACE FUNCTION public.reserve_document_id(p_seq_date date, p_org_abbr text, p_seq_kind text, p_existing_id text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
declare
  v_seq integer;
  v_prefix text;
begin
  if p_existing_id is not null and btrim(p_existing_id) <> '' then
    return p_existing_id;
  end if;

  insert into public.document_daily_sequences (seq_date, org_abbr, seq_kind, last_seq)
  values (p_seq_date, upper(p_org_abbr), upper(p_seq_kind), 1)
  on conflict (seq_date, org_abbr, seq_kind)
  do update set last_seq = public.document_daily_sequences.last_seq + 1
  returning last_seq into v_seq;

  v_prefix := case upper(p_seq_kind) when 'P' then 'P' else 'D' end;

  return v_prefix || to_char(p_seq_date, 'MMDD') || '-' || upper(p_org_abbr) || '-' || lpad(v_seq::text, 3, '0');
end;
$function$
;

CREATE OR REPLACE FUNCTION public.resolve_township(p_query text)
 RETURNS TABLE(township_code text, township_name_en text, township_name_mm text, state_region_code text, state_region_name_en text, state_region_name_mm text, match_strength integer)
 LANGUAGE sql
 STABLE
AS $function$
  WITH q AS (SELECT trim(coalesce(p_query, '')) AS raw, lower(trim(coalesce(p_query, ''))) AS lq)
  SELECT
    tm.township_code,
    tm.township_name_en,
    tm.township_name_mm,
    tm.state_region_code,
    tm.state_region_name_en,
    tm.state_region_name_mm,
    CASE
      WHEN tm.township_code = q.raw THEN 100
      WHEN lower(tm.township_name_en) = q.lq THEN 95
      WHEN tm.township_name_mm = q.raw THEN 95
      WHEN lower(tm.township_name_en) LIKE '%' || q.lq || '%' THEN 70
      WHEN tm.township_name_mm LIKE '%' || q.raw || '%' THEN 70
      ELSE 10
    END AS match_strength
  FROM public.township_master tm, q
  WHERE q.raw <> ''
    AND tm.is_selectable_for_address = TRUE
    AND (
      tm.township_code = q.raw OR
      lower(tm.township_name_en) LIKE '%' || q.lq || '%' OR
      tm.township_name_mm LIKE '%' || q.raw || '%'
    )
  ORDER BY match_strength DESC, tm.state_region_name_en, tm.township_name_en
  LIMIT 20;
$function$
;

