CREATE OR REPLACE FUNCTION public.rpc_filter_options_branches()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'value', x.value,
        'labelEn', x.label_en,
        'labelMy', x.label_my
      )
      order by x.label_en
    ),
    '[]'::jsonb
  )
  from (
    select distinct
      coalesce(b.code, b.id::text) as value,
      coalesce(b.name, b.code, b.id::text) as label_en,
      coalesce(b.name, b.code, b.id::text) as label_my
    from public.branches b
    where coalesce(b.is_active, true) = true
  ) x;
$function$
;

