CREATE OR REPLACE FUNCTION public.rpc_restore_broadcast_message(p_id uuid)
 RETURNS public.broadcast_messages
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row public.broadcast_messages;
begin
  update public.broadcast_messages
  set
    status = 'DRAFT',
    rejected_by = null,
    rejected_at = null,
    rejection_reason = null
  where id = p_id
    and upper(coalesce(status, '')) in ('ARCHIVED', 'REJECTED', 'VOID')
  returning * into v_row;

  if v_row.id is null then
    raise exception 'Broadcast message not found or not restorable';
  end if;

  perform public.log_approval_history(
    'broadcast_message',
    v_row.id,
    'RESTORE',
    null,
    jsonb_build_object(
      'message_title', v_row.message_title,
      'status', v_row.status
    )
  );

  return v_row;
end;
$function$
;

