CREATE OR REPLACE FUNCTION public.rpc_restore_deliveryman(p_id uuid)
 RETURNS public.deliverymen
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row public.deliverymen;
begin
  update public.deliverymen
  set status = 'ACTIVE'
  where id = p_id
    and upper(coalesce(status, '')) = 'INACTIVE'
  returning * into v_row;

  if v_row.id is null then
    raise exception 'Deliveryman not found or not inactive';
  end if;

  perform public.log_approval_history(
    'deliveryman',
    v_row.id,
    'RESTORE',
    null,
    jsonb_build_object(
      'staff_code', v_row.staff_code,
      'name', v_row.name,
      'status', v_row.status
    )
  );

  return v_row;
end;
$function$
;

