CREATE OR REPLACE FUNCTION public.rpc_rider_finalize_pickup_handover(p_pickup_id text, p_batch_id text, p_sender_name text, p_signature_data_url text, p_parcels jsonb DEFAULT '[]'::jsonb, p_summary jsonb DEFAULT '{}'::jsonb, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
begin
  if trim(coalesce(p_signature_data_url,'')) = '' then
    raise exception 'Sender signature is required';
  end if;

  insert into public.rider_pickup_handover_events(
    pickup_id, batch_id, sender_name, signature_data_url, parcels, summary, note, created_by
  )
  values (
    p_pickup_id, p_batch_id, p_sender_name, p_signature_data_url, coalesce(p_parcels,'[]'::jsonb), coalesce(p_summary,'{}'::jsonb), p_note, auth.uid()
  );

  update public.pickup_delivery_parcels
  set status = case when status in ('missing','rejected','exception') then status else 'pickup_handover_completed' end,
      updated_at = now()
  where pickup_id = p_pickup_id;

  return jsonb_build_object('ok', true, 'pickup_id', p_pickup_id, 'status', 'completed');
end;
$function$
;

CREATE OR REPLACE FUNCTION public.rpc_rider_pickup_batches(p_search text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_rows jsonb;
begin
  select coalesce(jsonb_agg(row_to_json(x)::jsonb order by x.created_at desc), '[]'::jsonb)
  into v_rows
  from (
    select
      s.id::text as id,
      coalesce(nullif(s.pickup_id,''), nullif(s.way_id,''), s.id::text) as pickup_id,
      coalesce(nullif(s.way_id,''), nullif(s.pickup_id,''), s.id::text) as batch_id,
      s.way_id,
      coalesce(nullif(s.merchant_name,''), nullif(s.sender_name,''), 'Unknown Sender') as merchant_name,
      s.merchant_code,
      s.sender_name,
      s.sender_phone,
      s.pickup_address as pickup_location,
      s.pickup_time as scheduled_time,
      coalesce(s.quantity, 1) as parcel_count,
      coalesce(s.status, 'assigned') as status,
      s.payload,
      s.created_at
    from public.pickup_delivery_form_submissions s
    where (p_search is null or p_search = ''
       or coalesce(s.pickup_id,'') ilike '%' || p_search || '%'
       or coalesce(s.way_id,'') ilike '%' || p_search || '%'
       or coalesce(s.merchant_name,'') ilike '%' || p_search || '%'
       or coalesce(s.sender_name,'') ilike '%' || p_search || '%'
       or coalesce(s.sender_phone,'') ilike '%' || p_search || '%')
    order by s.created_at desc
    limit 100
  ) x;

  return v_rows;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.rpc_rider_pickup_parcel_queue(p_pickup_id text, p_way_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_rows jsonb;
begin
  select coalesce(jsonb_agg(row_to_json(x)::jsonb order by x.way_id), '[]'::jsonb)
  into v_rows
  from (
    select
      p.id::text as id,
      p.pickup_id,
      p.way_id,
      p.delivery_id,
      p.temp_parcel_id,
      p.sender_name,
      p.weight_kg,
      p.cargo_photo_url,
      p.qr_text,
      p.qr_scan_status,
      p.print_status,
      p.status,
      p.reason,
      p.payload,
      p.created_at
    from public.pickup_delivery_parcels p
    where (p.pickup_id = p_pickup_id)
       or (p.way_id = p_way_id)
       or (p.way_id like coalesce(p_way_id, p_pickup_id, '') || '%')
    order by p.created_at asc
    limit 1000
  ) x;

  return v_rows;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.rpc_rider_record_label_print_status(p_pickup_id text, p_way_id text, p_delivery_id text DEFAULT NULL::text, p_temp_parcel_id text DEFAULT NULL::text, p_print_status text DEFAULT 'complete'::text, p_printer_name text DEFAULT NULL::text, p_command_language text DEFAULT 'PDF'::text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
begin
  insert into public.rider_pickup_print_events(
    pickup_id, way_id, delivery_id, temp_parcel_id, print_status,
    printer_name, command_language, note, created_by
  )
  values (
    p_pickup_id, p_way_id, p_delivery_id, p_temp_parcel_id, p_print_status,
    p_printer_name, p_command_language, p_note, auth.uid()
  );

  update public.pickup_delivery_parcels
  set print_status = p_print_status,
      printed_at = case when p_print_status = 'complete' then now() else printed_at end,
      printer_name = p_printer_name,
      command_language = p_command_language,
      updated_at = now()
  where (delivery_id = p_delivery_id and p_delivery_id is not null)
     or (way_id = p_way_id and p_way_id is not null);

  return jsonb_build_object('ok', true, 'print_status', p_print_status);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.rpc_submit_broadcast_message(p_id uuid)
 RETURNS public.broadcast_messages
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row public.broadcast_messages;
  v_actor text := coalesce(auth.jwt() ->> 'email', auth.uid()::text, 'system');
begin
  if not public.can_submit_approval() then
    raise exception 'Not allowed to submit broadcast message';
  end if;

  update public.broadcast_messages
  set
    status = 'PENDING_APPROVAL',
    submitted_by = v_actor,
    submitted_at = now(),
    approved_by = null,
    approved_at = null,
    rejected_by = null,
    rejected_at = null,
    rejection_reason = null
  where id = p_id
    and upper(coalesce(status, '')) in ('DRAFT', 'REJECTED')
  returning * into v_row;

  if v_row.id is null then
    raise exception 'Broadcast message not found or invalid status for submit';
  end if;

  perform public.log_approval_history(
    'broadcast_message',
    v_row.id,
    'SUBMIT',
    null,
    jsonb_build_object(
      'message_title', v_row.message_title,
      'status', v_row.status
    )
  );

  return v_row;
end;
$function$
;

