CREATE OR REPLACE FUNCTION public.submit_unified_pickup_request(p_weight numeric, p_city text, p_address text, p_tier text, p_requester_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_pickup_id TEXT;
    v_branch_code TEXT;
    v_tariff DECIMAL;
BEGIN
    -- (၁) Canonical P-format Pickup ID ဖန်တီးခြင်း
    v_pickup_id := 'P-' || TO_CHAR(NOW(), 'YYYYMMDD') || '-' || LPAD((FLOOR(RANDOM() * 10000))::TEXT, 4, '0');

    -- (၂) Mandalay နှင့် Naypyitaw အတွက် Branch သတ်မှတ်ခြင်း
    IF p_city ILIKE '%Mandalay%' THEN
        v_branch_code := 'MDY';
    ELSIF p_city ILIKE '%Naypyitaw%' OR p_city ILIKE '%Naypyidaw%' THEN
        v_branch_code := 'NPT';
    ELSE
        v_branch_code := 'YGN';
    END IF;

    -- (၃) Tariff တွက်ချက်ခြင်း (Standard/Royal rules အတိုင်း)
    -- (ဤနေရာတွင် be_tariff_master မှ rules များကို ခေါ်ယူတွက်ချက်ရန်)

    -- (၄) Pickup Request အသစ်ထည့်သွင်းခြင်း
    INSERT INTO be_portal_pickup_requests (pickup_id, branch_code, status, weight)
    VALUES (v_pickup_id, v_branch_code, 'PICKUP_REQUESTED', p_weight);

    -- (၅) Notification များ ပေးပို့ခြင်း
    INSERT INTO be_app_notifications (pickup_id, target_role, message)
    VALUES
        (v_pickup_id, 'Supervisor', 'New Pickup Request: ' || v_pickup_id),
        (v_pickup_id, 'Customer Service', 'Pickup initiated: ' || v_pickup_id);

    -- (၆) Cargo Event မှတ်တမ်းတင်ခြင်း
    INSERT INTO be_portal_cargo_events (pickup_id, status_code)
    VALUES (v_pickup_id, 'PICKUP_REQUESTED');

    RETURN v_pickup_id;
END;
$function$
;

