CREATE OR REPLACE FUNCTION public.sync_excel_master_data_to_portal()
 RETURNS TABLE(template_code text, synced_rows integer, upload_enabled boolean)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  UPDATE public.master_data_template_registry
  SET synced_rows = CASE template_code
    WHEN 'merchant_master' THEN (SELECT COUNT(*) FROM public.britium_merchant_master)
    WHEN 'customer_master' THEN (SELECT COUNT(*) FROM public.britium_customer_master)
    WHEN 'rider_master' THEN (SELECT COUNT(*) FROM public.britium_rider_master)
    WHEN 'driver_master' THEN (SELECT COUNT(*) FROM public.britium_driver_master)
    WHEN 'helper_master' THEN (SELECT COUNT(*) FROM public.britium_helper_master)
    WHEN 'employee_master' THEN (SELECT COUNT(*) FROM public.britium_employee_master)
    WHEN 'fleet_master' THEN (SELECT COUNT(*) FROM public.britium_fleet_master)
    WHEN 'current_app_tariffs' THEN (SELECT COUNT(*) FROM public.britium_tariff_current_master)
    WHEN 'vehicle_capacity' THEN (SELECT COUNT(*) FROM public.vehicle_capacity_master)
    WHEN 'service_types' THEN (SELECT COUNT(*) FROM public.britium_service_type_master)
    WHEN 'weight_brackets' THEN (SELECT COUNT(*) FROM public.britium_weight_bracket_master)
    WHEN 'zone_master' THEN (SELECT COUNT(*) FROM public.britium_zone_master)
    ELSE synced_rows END,
      is_upload_enabled = TRUE,
      template_available_count = 1,
      updated_at = NOW();

  UPDATE public.master_data_templates m
  SET synced_rows = r.synced_rows,
      available_count = r.template_available_count,
      upload_enabled = TRUE,
      updated_at = NOW()
  FROM public.master_data_template_registry r
  WHERE r.template_code = m.template_code;

  SELECT template_code, synced_rows, TRUE AS upload_enabled
  FROM public.master_data_template_registry
  ORDER BY display_order;
$function$
;

CREATE OR REPLACE FUNCTION public.sync_parcel_to_warehouse()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_doc record;
  v_status text;
  v_warehouse_status text;
begin
  select *
  into v_doc
  from public.be_waybill_ledger w
  where w.tracking_no = new.tracking_code
     or w.waybill_no = new.tracking_code
     or w.delivery_way_id = new.tracking_code
  order by w.created_at desc
  limit 1;

  v_status := coalesce(new.status, 'registered');

  v_warehouse_status := case lower(v_status)
    when 'registered' then 'pending_receiving'
    when 'picked_up' then 'pending_receiving'
    when 'at_branch' then 'RECEIVED_AT_ORIGIN'
    when 'in_transit' then 'IN_TRANSIT'
    when 'out_for_delivery' then 'OUT_FOR_DELIVERY'
    when 'delivered' then 'DELIVERED'
    when 'failed' then 'EXCEPTION'
    when 'returned' then 'RETURNED'
    when 'cancelled' then 'CANCELLED'
    else coalesce(to_jsonb(v_doc)->>'warehouse_status', 'pending_receiving')
  end;

  insert into public.be_warehouse_inventory (
    upload_code,
    tracking_no,
    pickup_id,
    pickup_date,
    way_id,
    delivery_way_id,
    waybill_no,
    invoice_no,

    merchant_name,
    customer_name,
    customer_phone,
    receiver_name,
    receiver_phone,
    township,
    delivery_address,

    item_price,
    delivery_fee_os,
    weight_kg,
    surcharge,
    cod_amount,
    actual_collect,
    destination,
    pickup_by,
    remarks,

    warehouse_status,
    status,
    notes,
    received_at,
    updated_at
  )
  values (
    'DATA-ENTRY-BULK-LOAD',
    new.tracking_code,
    coalesce(to_jsonb(v_doc)->>'pickup_way_id', to_jsonb(v_doc)->>'pickup_id'),
    coalesce(to_jsonb(v_doc)->>'created_at', new.created_at::text)::timestamptz,
    coalesce(to_jsonb(v_doc)->>'pickup_way_id', to_jsonb(v_doc)->>'pickup_id'),
    to_jsonb(v_doc)->>'delivery_way_id',
    to_jsonb(v_doc)->>'waybill_no',
    to_jsonb(v_doc)->>'invoice_no',

    coalesce(to_jsonb(v_doc)->>'merchant_name', new.sender_name),
    new.recipient_name,
    new.recipient_phone,
    new.recipient_name,
    new.recipient_phone,
    new.recipient_township,
    new.recipient_address,

    coalesce(new.declared_value, 0),
    coalesce(new.base_price, 0),
    coalesce(new.actual_weight_kg, new.weight_kg, 0),
    coalesce(new.overweight_fee, 0),
    coalesce(new.cod_amount, 0),
    coalesce(new.cod_amount, 0) + coalesce(new.base_price, 0) + coalesce(new.overweight_fee, 0),
    new.recipient_township,
    coalesce(to_jsonb(v_doc)->'payload'->>'parcel_bulk_loaded_by', 'data.entry@britiumexpress.com'),
    new.notes,

    v_warehouse_status,
    v_status,
    new.notes,
    case when lower(v_status) = 'at_branch' then now() else null end,
    now()
  )
  on conflict (tracking_no) do update
  set
    pickup_id = excluded.pickup_id,
    pickup_date = excluded.pickup_date,
    way_id = excluded.way_id,
    delivery_way_id = excluded.delivery_way_id,
    waybill_no = excluded.waybill_no,
    invoice_no = excluded.invoice_no,

    merchant_name = excluded.merchant_name,
    customer_name = excluded.customer_name,
    customer_phone = excluded.customer_phone,
    receiver_name = excluded.receiver_name,
    receiver_phone = excluded.receiver_phone,
    township = excluded.township,
    delivery_address = excluded.delivery_address,

    item_price = excluded.item_price,
    delivery_fee_os = excluded.delivery_fee_os,
    weight_kg = excluded.weight_kg,
    surcharge = excluded.surcharge,
    cod_amount = excluded.cod_amount,
    actual_collect = excluded.actual_collect,
    destination = excluded.destination,
    pickup_by = excluded.pickup_by,
    remarks = excluded.remarks,

    warehouse_status = excluded.warehouse_status,
    status = excluded.status,
    notes = excluded.notes,
    received_at = coalesce(public.be_warehouse_inventory.received_at, excluded.received_at),
    updated_at = now();

  return new;
end;
$function$
;

