CREATE OR REPLACE FUNCTION public.update_rider_job_status(p_pickup_id text, p_rider_id uuid, p_new_status text, p_pod_signature_url text DEFAULT NULL::text, p_pod_photo_url text DEFAULT NULL::text, p_collected_cod numeric DEFAULT 0)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_branch_code TEXT;
BEGIN
    -- (၁) လက်ရှိ Branch ကို ရယူခြင်း
    SELECT current_branch INTO v_branch_code
    FROM be_portal_pickup_requests WHERE pickup_id = p_pickup_id;

    -- (၂) Pickup Request ကို Update လုပ်ခြင်း
    UPDATE be_portal_pickup_requests
    SET
        status = p_new_status,
        pod_signature_url = COALESCE(p_pod_signature_url, pod_signature_url),
        pod_photo_url = COALESCE(p_pod_photo_url, pod_photo_url),
        collected_cod_amount = p_collected_cod,
        updated_at = NOW()
    WHERE pickup_id = p_pickup_id AND assigned_rider_id = p_rider_id;

    -- (၃) Merchant/Customer ခြေရာခံနိုင်ရန် Cargo Tracking Event ထည့်သွင်းခြင်း
    INSERT INTO be_portal_cargo_events (pickup_id, status_code, branch_code, updated_by)
    VALUES (p_pickup_id, p_new_status, v_branch_code, p_rider_id);

    -- (၄) အကယ်၍ DELIVERED ဖြစ်ပြီး COD ကောက်ခံရရှိပါက Finance Alert ပေးပို့ခြင်း
    IF p_new_status = 'DELIVERED' AND p_collected_cod > 0 THEN
        INSERT INTO be_app_notifications (pickup_id, target_role, target_branch, message)
        VALUES (p_pickup_id, 'Finance', v_branch_code, 'COD Collected: ' || p_collected_cod || ' MMK by Rider');
    END IF;

    RETURN 'SUCCESS';
END;
$function$
;

CREATE OR REPLACE FUNCTION public.update_shipment_status(p_shipment_id uuid, p_status character varying, p_location character varying, p_updated_by uuid, p_notes text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
BEGIN
    -- Update shipment status
    UPDATE public.shipments_2026_02_19_13_00
    SET status = p_status, current_location = p_location
    WHERE id = p_shipment_id;

    -- Add tracking entry
    INSERT INTO public.shipment_tracking_2026_02_19_13_00 (
        shipment_id, status, location, updated_by, notes
    ) VALUES (
        p_shipment_id, p_status, p_location, p_updated_by, p_notes
    );

    RETURN TRUE;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.update_shipment_status(p_way_id text, p_new_status text, p_location text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_sid uuid;
BEGIN
  -- Get the shipment ID
  SELECT id INTO v_sid FROM public.shipments WHERE way_id = p_way_id;
  IF v_sid IS NULL THEN RAISE EXCEPTION 'Shipment not found'; END IF;

  -- 1. Update the main table
  UPDATE public.shipments
  SET
    status = p_new_status::public.shipment_status,
    actual_pickup_time = CASE WHEN p_new_status = 'picked_up' THEN now() ELSE actual_pickup_time END,
    actual_delivery_time = CASE WHEN p_new_status = 'delivered' THEN now() ELSE actual_delivery_time END
  WHERE id = v_sid;

  -- 2. Add to the tracking history (the audit trail)
  INSERT INTO public.shipment_tracking (
    shipment_id,
    status,
    location,
    notes,
    handled_by
  ) VALUES (
    v_sid,
    p_new_status,
    p_location,
    p_notes,
    auth.uid()
  );

  RETURN true;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.update_shipment_workflow_2026_02_19_17_00(p_shipment_id uuid, p_new_state character varying, p_user_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_current_state VARCHAR(50);
    v_result JSONB;
BEGIN
    -- Get current state
    SELECT current_state INTO v_current_state
    FROM shipment_workflow_states_2026_02_19_17_00
    WHERE shipment_id = p_shipment_id
    ORDER BY created_at DESC
    LIMIT 1;

    -- Update workflow state
    UPDATE shipment_workflow_states_2026_02_19_17_00
    SET
        previous_state = v_current_state,
        current_state = p_new_state,
        updated_at = NOW()
    WHERE shipment_id = p_shipment_id;

    -- Update assignment queue if needed
    UPDATE assignment_queue_2026_02_19_17_00
    SET
        status = CASE
            WHEN p_new_state IN ('DELIVERED', 'CANCELLED') THEN 'COMPLETED'
            WHEN p_new_state IN ('OUT_FOR_DELIVERY', 'IN_TRANSIT') THEN 'PROCESSING'
            ELSE status
        END,
        processed_at = CASE
            WHEN p_new_state IN ('DELIVERED', 'CANCELLED') THEN NOW()
            ELSE processed_at
        END
    WHERE shipment_id = p_shipment_id;

    -- Create notifications for state changes
    IF p_new_state = 'READY_FOR_PICKUP' THEN
        INSERT INTO realtime_notifications_2026_02_19_17_00 (
            user_id, notification_type, title, message, data
        )
        SELECT
            u.id, 'SHIPMENT_READY', 'Shipment Ready for Pickup',
            'Shipment is ready for pickup from warehouse',
            jsonb_build_object('shipment_id', p_shipment_id)
        FROM users_2026_02_19_13_00 u
        WHERE u.role = 'RIDER' AND u.status = 'ACTIVE';
    END IF;

    v_result := jsonb_build_object(
        'success', true,
        'previous_state', v_current_state,
        'new_state', p_new_state,
        'updated_at', NOW()
    );

    RETURN v_result;
END;
$function$
;

