create or replace view "public"."v_master_data_template_status" as  SELECT r.template_code,
    r.template_name,
    r.source_sheet,
    r.source_file,
    r.target_table,
    r.expected_source_rows,
        CASE r.template_code
            WHEN 'merchant_master'::text THEN ( SELECT count(*) AS count
               FROM public.britium_merchant_master)
            WHEN 'customer_master'::text THEN ( SELECT count(*) AS count
               FROM public.britium_customer_master)
            WHEN 'rider_master'::text THEN ( SELECT count(*) AS count
               FROM public.britium_rider_master)
            WHEN 'driver_master'::text THEN ( SELECT count(*) AS count
               FROM public.britium_driver_master)
            WHEN 'helper_master'::text THEN ( SELECT count(*) AS count
               FROM public.britium_helper_master)
            WHEN 'employee_master'::text THEN ( SELECT count(*) AS count
               FROM public.britium_employee_master)
            WHEN 'fleet_master'::text THEN ( SELECT count(*) AS count
               FROM public.britium_fleet_master)
            WHEN 'current_app_tariffs'::text THEN ( SELECT count(*) AS count
               FROM public.britium_tariff_current_master)
            WHEN 'vehicle_capacity'::text THEN ( SELECT count(*) AS count
               FROM public.vehicle_capacity_master)
            WHEN 'service_types'::text THEN ( SELECT count(*) AS count
               FROM public.britium_service_type_master)
            WHEN 'weight_brackets'::text THEN ( SELECT count(*) AS count
               FROM public.britium_weight_bracket_master)
            WHEN 'zone_master'::text THEN ( SELECT count(*) AS count
               FROM public.britium_zone_master)
            ELSE (r.synced_rows)::bigint
        END AS synced_rows,
    r.template_available_count,
    true AS upload_enabled,
    r.is_active,
    r.display_order,
    f.public_path AS template_download_path,
    f.accepted_extensions,
        CASE
            WHEN ((r.template_available_count > 0) AND r.is_upload_enabled) THEN 'ready'::text
            WHEN (r.template_available_count > 0) THEN 'template_available'::text
            ELSE 'missing_template'::text
        END AS ui_status,
    r.notes,
    r.updated_at
   FROM (public.master_data_template_registry r
     LEFT JOIN public.master_data_upload_template_files f ON ((f.template_code = r.template_code)))
  ORDER BY r.display_order;


