    COALESCE(NULLIF(default_pickup_address, ''::text), address_line_1) AS pickup_address,
    default_pickup_time_window,
    payment_terms,
    is_active,
    standard_allowance_kg,
        CASE
            WHEN is_special_5kg_allowance THEN special_allowance_kg
            ELSE standard_allowance_kg
        END AS active_allowance_kg,
    extra_per_kg_mmk
   FROM public.britium_merchant_master
  WHERE (is_active = true)
  ORDER BY merchant_name;


