CREATE OR REPLACE FUNCTION public.zzzz_be30_force_canonical_ids()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN

    /*
      IMPORTANT:
      Existing operational IDs are immutable.
      Only generate canonical IDs for INSERT.
    */

    IF TG_OP = 'UPDATE'
       AND OLD.pickup_id IS NOT NULL
       AND NEW.pickup_id = OLD.pickup_id
    THEN
        RETURN NEW;
    END IF;


    /*
      Keep your existing INSERT canonical ID logic here.
      Do not regenerate IDs on UPDATE.
    */


    RETURN NEW;

END;
$function$
;

CREATE OR REPLACE FUNCTION public.zzzzzz_force_britium_pickup_id_format()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_merchant_code text;
  v_parcel_count integer;
  v_pickup_id text;
  v_payload jsonb;
  v_patch jsonb := '{}'::jsonb;
begin
  v_payload := coalesce(new.request_payload, '{}'::jsonb);

  v_merchant_code := coalesce(
    nullif(new.merchant_code, ''),
    nullif(v_payload ->> 'merchant_code', ''),
    nullif(v_payload ->> 'merchantCode', ''),
    nullif(v_payload ->> 'merchant_id', ''),
    nullif(v_payload ->> 'merchantId', ''),
    nullif(new.merchant_name, ''),
    'MER'
  );

  v_parcel_count := coalesce(
    new.expected_parcels,
    case
      when v_payload ->> 'expected_parcels' ~ '^[0-9]+$'
        then (v_payload ->> 'expected_parcels')::integer
      else null
    end,
    case
      when v_payload ->> 'expectedParcels' ~ '^[0-9]+$'
        then (v_payload ->> 'expectedParcels')::integer
      else null
    end,
    case
      when v_payload ->> 'parcel_count' ~ '^[0-9]+$'
        then (v_payload ->> 'parcel_count')::integer
      else null
    end,
    case
      when v_payload ->> 'parcelCount' ~ '^[0-9]+$'
        then (v_payload ->> 'parcelCount')::integer
      else null
    end,
    1
  );

  v_pickup_id := public.be_format_britium_pickup_id(
    coalesce(new.pickup_date, current_date),
    v_merchant_code,
    v_parcel_count
  );

  -- Set pickup_id
  if exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'be_portal_pickup_requests'
      and column_name = 'pickup_id'
  ) then
    v_patch := v_patch || jsonb_build_object('pickup_id', v_pickup_id);
  end if;

  -- Also sync pickup_uid if the column exists
  if exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'be_portal_pickup_requests'
      and column_name = 'pickup_uid'
  ) then
    v_patch := v_patch || jsonb_build_object('pickup_uid', v_pickup_id);
  end if;

  new := jsonb_populate_record(new, v_patch);

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.zzzzzzzz_britium_pickup_sequence_after_update()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_old_code text;
  v_new_code text;
  v_old_date date;
  v_new_date date;
begin
  if pg_trigger_depth() > 1 then
    return new;
  end if;

  v_old_date := coalesce(old.pickup_date, current_date);
  v_new_date := coalesce(new.pickup_date, current_date);

  v_old_code := public.be_pickup_normalize_merchant_code(
    old.merchant_code,
    old.merchant_name,
    coalesce(old.request_payload, '{}'::jsonb)
  );

  v_new_code := public.be_pickup_normalize_merchant_code(
    new.merchant_code,
    new.merchant_name,
    coalesce(new.request_payload, '{}'::jsonb)
  );

  if v_old_date is distinct from v_new_date
     or v_old_code is distinct from v_new_code
  then
    perform public.be_rebuild_pickup_sequence_for_day(v_old_date, v_old_code);
  end if;

  perform public.be_rebuild_pickup_sequence_for_day(v_new_date, v_new_code);

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.zzzzzzzz_britium_pickup_sequence_before_insert()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_date date;
  v_code text;
  v_count integer;
  v_last_end integer;
  v_start integer;
  v_end integer;
  v_pickup_id text;
begin
  v_date := coalesce(new.pickup_date, current_date);
  v_code := public.be_pickup_normalize_merchant_code(
    new.merchant_code,
    new.merchant_name,
    coalesce(new.request_payload, '{}'::jsonb)
  );

  v_count := public.be_pickup_parcel_count(
    new.expected_parcels,
    coalesce(new.request_payload, '{}'::jsonb)
  );

  perform pg_advisory_xact_lock(hashtext('pickup-seq:' || v_date::text || ':' || v_code));

  select greatest(
    coalesce(max(pickup_sequence_end), 0),
    coalesce(max(
      case
        when pickup_id ~ ('^P[0-9]{4}-' || v_code || '-[0-9]+$')
        then regexp_replace(pickup_id, '^.*-', '')::integer
        else null
      end
    ), 0)
  )
  into v_last_end
  from public.be_portal_pickup_requests
  where coalesce(pickup_date, current_date) = v_date
    and public.be_pickup_normalize_merchant_code(
      merchant_code,
      merchant_name,
      coalesce(request_payload, '{}'::jsonb)
    ) = v_code;

  v_start := coalesce(v_last_end, 0) + 1;
  v_end := v_start + v_count - 1;

  v_pickup_id := public.be_format_britium_pickup_marker(v_date, v_code, v_end);

  new.pickup_date := v_date;
  new.merchant_code := v_code;
  new.expected_parcels := v_count;
  new.pickup_parcel_count := v_count;
  new.pickup_sequence_start := v_start;
  new.pickup_sequence_end := v_end;
  new.pickup_id := v_pickup_id;
  new.pickup_uid := v_pickup_id;
  new.pickup_range_label :=
    public.be_format_britium_pickup_marker(v_date, v_code, v_start)
    || ' - '
    || public.be_format_britium_pickup_marker(v_date, v_code, v_end);

  return new;
end;
$function$
;

