    COALESCE(sum(expected_source_rows), (0)::bigint) AS expected_source_rows,
    COALESCE(sum(synced_rows), (0)::numeric) AS synced_rows,
    count(*) FILTER (WHERE (synced_rows > 0)) AS templates_with_data,
